// 君主台詞資料（build-ruler-data.py 產生；來源：劇本工作流 wf_9941f538-4af＋回覆工作流 wf_66f596fd-c48＋借圖 43 國工作流 wf_a4401d84-7bb，作者＋審稿；台詞為遊戲設計，非史料）
globalThis.RULER_DATA={"families":{"kr":[{"name":"廣開土大王","title":"高句麗國王","era":"391–413 年在位","tone":"橫掃四方的征服者，豪邁自信，句句如鐵騎奔騰","portrait":"kr-historical-age0","lines":{"intro":["寡人乃高句麗永樂太王，天下之土，皆待寡人開拓。","聽好了，遼東之北、漢江之南，都將見到高句麗的旗幟。"],"contact":["這城牆築得不錯，可惜擋不住高句麗的鐵騎。","寡人的斥候回報了，你的城池比想像中還要小。"],"war":["永樂之師今日出征，你的疆土將改姓高句麗！","寡人已破百濟、退倭兵，你以為自己能例外嗎？"],"warReply":["敢向寡人宣戰？好，就讓天下看看誰才是太王。","寡人正愁刀槍生鏽，你送上門來，正合寡人之意。"],"peace":["寡人志在四方，不想在你這裡耗費太多兵馬，停戰吧。","北方的契丹還在等寡人，暫且收兵，你我各守疆界。"],"accept":["好，寡人答應。高句麗一言既出，鐵騎絕不越界。","明智的選擇。與寡人為友，勝過與寡人為敵。"],"reject":["停戰？寡人的戰馬才剛套上鞍，此時不談和。","寡人的功業還未足以傳世，此時怎能停下？"],"rebuff":["不肯停戰？那就別怪寡人的鐵騎不留情面。","寡人給你機會，你卻不要，戰場上再說吧。"],"betray":["盟約已到盡頭，高句麗的旗幟再度向你揮動！","寡人養精蓄銳已久，如今是時候再度出征了。"],"truceEnd":["休戰期滿了，寡人的馬鞍早已上好，出發！","太平日子過夠了，該讓天下重新認識高句麗。"],"attacking":["高句麗五萬步騎已經出發，你的城牆準備好了嗎？","寡人親率大軍南下，聽見馬蹄聲就該開城門了。"],"attacked":["國內城的城牆竟然在動搖……寡人未曾想過這一天。","高句麗的鐵騎也有疲憊之時嗎……守住，再守住！"],"defeated":["寡人一生開疆拓土，如今卻守不住故土……","記住，曾有一位太王，讓天下都畏懼高句麗之名。"],"victory":["天下之土，終歸寡人所有。你，敗得不冤。","這片土地從今日起，將刻上高句麗的名字。"],"allyAccept":["好，與寡人並肩，你的敵人就是高句麗的敵人。","高句麗願與你結盟，一同開拓這片廣闊天地。"],"allyReject":["寡人的鐵騎不需要盟友，只需要更廣的疆土。","結盟？先證明你值得寡人分一杯羹再說。"],"greetFriendly":["哈哈，遠方的君主竟有此雅興，寡人歡迎！","高句麗的大門為朋友敞開，有空來遼東一敘。"],"greetCold":["寡人正忙著征戰，你的問候，先記下了。","話說得好聽，可寡人只看你的兵馬往哪走。"],"threatDefy":["威嚇寡人？百濟、後燕來試過，都吃了敗仗。","高句麗的鐵騎不怕嚇，只怕沒有敵人可打！"],"threatYield":["哼，此刻寡人兵馬在外，暫且依你便是。","好，這回讓你一步，來日寡人必當再議。"],"tributePay":["寡人的軍糧也要緊，{gold}兩黃金拿去，休再多言。","這{gold}兩黃金，算是寡人買個清靜，下不為例。"],"tributeRefuse":["向寡人要貢品？你怕是把高句麗看得太小了。","貢品？寡人只收敵人的城池，不送金子給人。"],"giftThanks":["好禮！寡人收下了，來日必以厚禮相報。","你這份心意，寡人記在心裡，高句麗不忘朋友。"],"intel":["寡人正與{wars}交戰，與{peace}暫且停戰。","告訴你也無妨：{wars}是敵，{peace}已休兵。"]}},{"name":"王建","title":"高麗太祖","era":"918–943 年在位","tone":"寬厚圓融的開國之君，以德服人、廣結善緣，語氣溫和而有分量","portrait":"kr-historical-age1","lines":{"intro":["朕乃高麗之主王建，願以仁德會天下英雄，不以刀兵。","三韓終於一統，願與各方君主共享太平，你意如何？"],"contact":["這座城看來安穩，朕樂見鄰邦百姓安居，望長久如此。","好一座城池，若能與高麗為善鄰，彼此都是福分。"],"war":["朕一向以和為貴，但你屢次犯境，高麗不能再退讓。","不得已而用兵，朕會請佛祖見證，此戰只為護民。"],"warReply":["你要戰？朕曾收留甄萱、接納敬順王，也不怕多你一個。","唉，朕本想與你把酒言和，既然如此，高麗只好應戰。"],"peace":["刀兵之下無贏家，朕願先收兵，你我坐下來談。","朕不願百姓再受苦，願以誠意換一紙停戰之約。"],"accept":["善哉。朕以天授年號為誓，高麗必守此約。","好，從今往後，兩國百姓可以安心耕田了。"],"reject":["朕心慈，但不糊塗。此時停戰，只會讓你捲土重來。","你的誠意還不夠，先讓朕看到你真心止戈。"],"rebuff":["朕伸出的手，你不接，那便由天意來決定吧。","可惜，朕本想結一段善緣，你卻選了戰場。"],"betray":["朕忍讓再三，你卻步步進逼，高麗的耐心到此為止。","情勢有變，朕不得不撕約，來日佛前朕自會懺悔。"],"truceEnd":["休戰的日子過去了，願各方都能守住本分。","天下重歸紛爭，朕會守住高麗每一寸土地。"],"attacking":["高麗大軍已經出發，朕不求殺傷，只求你開城歸順。","朕親自領軍前來，若你願降，朕必以禮相待。"],"attacked":["開京的城牆在搖晃……朕一生和合，竟落得如此。","城中百姓還在，朕不能倒下，眾將，再守一日！"],"defeated":["高麗……朕留下的訓要十條，望後人能記得。","朕一生想統一三韓，到頭來還是盡了力，無悔。"],"victory":["戰事結束了。朕不會苛待你，這是高麗的胸懷。","天下歸於和合，你若願意，仍可在朕的朝廷有一席之地。"],"allyAccept":["善緣難得，朕答應結盟，願兩國如兄弟。","好，朕以聯姻結豪族的誠意，同樣待你為盟友。"],"allyReject":["朕待人以誠，但你的心思還看不透，暫且不結盟。","結盟須以信為本，你我之間，信還不夠深。"],"greetFriendly":["來信收悉，朕向來以和為貴，願與貴國友好。","高麗初定，正需四方友邦，貴國問候朕甚欣慰。"],"greetCold":["朕收到了。三韓初合，人心未穩，恕不多言。","問候之意朕領了，但交情需靠日後行事來看。"],"threatDefy":["朕自亂世中定三韓，豈會被幾句狠話動搖？","後百濟的甄萱尚且歸降於朕，閣下又何足懼？"],"threatYield":["新國初立，百姓需要休養，朕暫且退讓一步。","罷了，為免生靈塗炭，此事朕依你所言。"],"tributePay":["為保百姓安寧，朕送上黃金{gold}兩，望止干戈。","黃金{gold}兩交予貴國，此乃權宜，非高麗臣服。"],"tributeRefuse":["高麗的黃金要用來安頓流民，一兩也不能給。","朕以德服人，不以金買和，貢品之事免談。"],"giftThanks":["厚禮收下了，貴國的情誼，高麗必當銘記。","來而不往非禮也，朕改日定備回禮相贈。"],"intel":["實不相瞞，朕正與{wars}交戰，與{peace}已議和。","高麗與{wars}兵戎相見，與{peace}則已罷兵。"]}},{"name":"世宗大王","title":"朝鮮國王","era":"1418–1450 年在位","tone":"溫文儒雅的學者君王，以民為本、崇文重理，謙和中自有原則","portrait":"kr-historical-age2","lines":{"intro":["寡人乃朝鮮國王李祹，願以文治相交，不以干戈相見。","治國之道在於愛民，望你我皆能使百姓安樂。"],"contact":["聽聞貴國城池繁盛，寡人願遣使者，互通農書曆法。","此城規劃有序，可見治者用心，寡人敬佩。"],"war":["寡人不喜刀兵，但你侵擾邊民，朝鮮不得不出師。","為守四郡六鎮的百姓，寡人不得已宣戰，望你自省。"],"warReply":["你執意開戰？寡人的火炮與神機箭，並非只是擺設。","既然如此，寡人只能請金宗瑞將軍整備兵馬了。"],"peace":["干戈日久，百姓農事荒廢，寡人願先罷兵，共議和平。","與其兵戎相見，不如互市通商，寡人願提議停戰。"],"accept":["甚好。寡人願以此約為始，兩國共享太平。","明理之舉。停戰之後，寡人願贈貴國測雨器與曆書。"],"reject":["言而無信者，寡人不敢輕信，此議暫且擱下。","你的誠意寡人看不到，停戰之事，容後再議。"],"rebuff":["你不願息兵，寡人深感遺憾，只好整軍以待。","和議不成，非寡人所願。望日後你能回心轉意。"],"betray":["你屢次背約犯邊，寡人今日不再容忍。","寡人本欲守約，然你所行令人失望，兵馬再度出動。"],"truceEnd":["休戰期滿，寡人願各國仍以民為本，慎用刀兵。","和平之日已盡，朝鮮已備好邊防，靜觀其變。"],"attacking":["朝鮮水陸大軍已出發，猶如己亥年東征對馬。","寡人的大軍前來，望你早日開城，免百姓受苦。"],"attacked":["漢陽城危矣……集賢殿的典籍，一定要保住。","寡人畢生所建，難道要毀於一旦？眾卿，堅守！"],"defeated":["寡人創制的文字，願後世百姓仍能書寫……","國雖亡，訓民正音不亡。願百姓永遠識字明理。"],"victory":["戰事已了。寡人不求你的土地，只求百姓安樂。","文治終勝武功。願你的百姓也能識字讀書。"],"allyAccept":["寡人樂意結盟，兩國可互通學問，共研曆法農事。","好，集賢殿的學者將與貴國共享所學。"],"allyReject":["結盟之事，寡人須先問於群臣，此時難以應允。","你之所求與朝鮮之利相違，寡人只能婉拒。"],"greetFriendly":["遠方來信，寡人讀之甚喜，願兩國以文會友。","貴國若有賢書良法，望能互通，共益百姓。"],"greetCold":["來意寡人明白了，然邦交之事，尚需從長計議。","寡人正忙於農事與典籍，貴國之意，且觀後效。"],"threatDefy":["寡人以仁治國，但朝鮮的六鎮之兵，並非虛設。","恫嚇之言，寡人聽過便罷，民心所向才是根本。"],"threatYield":["寡人不願百姓受戰火之苦，此事便依貴國。","兵者凶器也，寡人退讓一步，望貴國適可而止。"],"tributePay":["為保田間農人安心耕作，寡人奉上黃金{gold}兩。","黃金{gold}兩送去，換得邊境安寧，寡人不覺可惜。"],"tributeRefuse":["國庫之財皆為民所用，寡人不能拿來送人。","朝鮮以禮待人，卻不受無理索求，貢品恕難從命。"],"giftThanks":["貴國厚意，寡人謹領，願以典籍相贈為報。","此禮寡人收下了，集賢殿諸臣亦感貴國情誼。"],"intel":["寡人直言相告：朝鮮與{wars}交戰，與{peace}和睦。","眼下與{wars}尚有戰事，與{peace}則已締和。"]}},{"name":"高宗 李熙","title":"大韓帝國皇帝","era":"1863–1907 年在位","tone":"內憂外患中力圖自強的皇帝，語帶沉鬱與不甘，仍力守帝國尊嚴","portrait":"kr-historical-age3","lines":{"intro":["朕乃大韓帝國皇帝，光武之世，願與列國平等相交。","朕在圜丘壇祭天稱帝，大韓自主獨立，不容輕視。"],"contact":["貴國城池已通電燈與鐵路了嗎？朕的皇宮也點上了電燈。","朕聽聞你的城池，願依萬國公法互設使館，通商往來。"],"war":["列強環伺之下，朕仍得宣戰，大韓的尊嚴不能再退。","朕不願戰，但你欺我國弱，大韓帝國必須奮起。"],"warReply":["又是一國向朕宣戰……朕已習慣了，大韓不會屈服。","你以為大韓積弱可欺？朕的新式軍隊會讓你改觀。"],"peace":["朕深知戰爭只會引來更多列強干涉，願先停戰。","戰火之中無人得利，朕願提議停戰，共守東亞和平。"],"accept":["甚好。朕會依萬國公法簽署此約，望你信守。","大韓帝國接受。願這次的條約，不再是不平等的。"],"reject":["朕簽過太多被迫的條約，這一次，朕不會再輕易點頭。","你的條件對大韓不利，朕不能再簽有損國權的約。"],"rebuff":["連停戰也不肯……列國之間，果真只有強權嗎？","朕的誠意被拒，那麼大韓只能繼續自強圖存。"],"betray":["朕曾親眼見條約被人撕毀，如今朕也只能如此了。","情勢逼人，朕不得不重啟戰端，此非朕之本願。"],"truceEnd":["休戰結束了。朕的自強新政，還來得及嗎？","舊本新參，朕已整頓軍制，大韓不再任人宰割。"],"attacking":["大韓帝國的新式軍隊已經出發，朕要收回應有的尊嚴。","朕親自檢閱過這支軍隊，今日他們向你的城進發。"],"attacked":["慶運宮的宮牆快撐不住了……朕還能往哪裡去？","朕的帝國才剛建立，難道就要在此終結嗎？守住！"],"defeated":["大韓的獨立，朕終究守不住……願後人能完成。","朕曾向列國求援，卻無人肯伸手，大韓……就此落幕。"],"victory":["大韓帝國竟也有勝利的一日……朕總算能抬頭了。","這場勝利，朕要記在光武年號之下，讓後人記得。"],"allyAccept":["朕願結盟。大韓需要真正的朋友，而非覬覦者。","好，願此盟約平等互惠，這是朕最看重的原則。"],"allyReject":["朕見過太多假結盟之名行干涉之實者，恕難答應。","大韓好不容易獨立，朕不願再依附任何一國。"],"greetFriendly":["貴國來信，朕深感欣慰，大韓願與友邦相扶持。","強鄰環伺之際，能得一友邦問候，朕心稍安。"],"greetCold":["朕收到來信了。近來列強言辭多變，朕不敢輕信。","貴國美意朕心領，但邦交之事，須看行動而非言語。"],"threatDefy":["大韓雖小，亦是自主之國，朕不會向威嚇低頭。","朕在列強之間周旋多年，這等威脅嚇不倒朕。"],"threatYield":["朕深知國力不足，為保社稷，只得暫且忍讓。","此番朕退讓了，但大韓終有自強之日。"],"tributePay":["朕忍痛送上黃金{gold}兩，望貴國莫再相逼。","黃金{gold}兩換片刻安寧，朕心中實在不甘。"],"tributeRefuse":["大韓已受盡列強索求，這份貢品，朕不會給。","國庫本已困窘，朕若再送黃金，何以面對百姓？"],"giftThanks":["亂世之中仍有此厚意，朕實感動，謹此致謝。","貴國之禮朕收下了，此情誼大韓不會忘記。"],"intel":["朕坦言相告：大韓與{wars}交戰，與{peace}和睦。","眼下與{wars}兵戎相向，與{peace}則已停戰。"]}}],"tw":[{"name":"墾首","title":"台灣早期移民頭人","era":"早期移民（通稱）","tone":"樸實硬頸的墾荒頭人，句句離不開田園、水圳和鄉親。","portrait":"tw-historical-age0","lines":{"intro":["客人遠道而來，這片荒地是咱一鋤一鋤開出來的。","老夫渡海只為一塊田，誰敢動咱的田園，先問問鄉親。"],"contact":["你的人來到咱的莊頭了？請他們別踩壞剛插的秧。","隔壁來了新鄰居，水圳的水夠不夠分，咱得先算清楚。"],"war":["你占了咱的水源，鄉親們拿起鋤頭，也是能打的！","田是咱的命，你逼咱到這一步，老夫只好帶人跟你拚！"],"warReply":["你要打？好，咱莊裡的壯丁早就把竹圍守住了。","開荒的人不怕苦，也不怕你，來吧，咱等著。"],"peace":["打下去田都荒了，不如放下鋤頭刀槍，各自種田吧。","稻子快熟了，鄉親要回去收割，咱們先停手如何？"],"accept":["好，說定了。老夫請你喝一碗自家釀的米酒。","鄉親不用再守夜了，這是好事，咱記你這份情。"],"reject":["你上回燒了咱的穀倉，這帳還沒算，談什麼停手。","老夫信不過你，田還沒守穩，鋤頭不能放下。"],"rebuff":["不肯就算了，咱們開荒的人，什麼苦沒吃過。","你不要和氣，那就別怪鄉親們把竹圍築得更高。"],"betray":["你的人偷偷改了水道，這口氣咱嚥不下，再打！","對不住了，鄉親們說不能再讓，老夫只好翻臉。"],"truceEnd":["秧插完了，壯丁也閒下來了，往後可不會再客氣。","安穩的日子過完了，各莊各村，都把眼睛睜大些。"],"attacking":["鄉親們扛著鋤頭出發了，這回要把水源討回來！","莊裡的壯丁全上了，老夫走在最前面，你等著。"],"attacked":["竹圍破了，穀倉也燒了……鄉親們，別放棄這塊田！","老夫一輩子的心血啊，就算剩一鋤頭也要守住。"],"defeated":["田……還是沒守住。鄉親們，記得把種子帶走。","渡海時就想過會有這天，老夫只求你善待這片土地。"],"victory":["咱贏了？鄉親們，回去種田，秧苗還等著咱呢。","你輸了，但田不會輸人，來咱莊裡討口飯吃吧。"],"allyAccept":["好，兩莊結成一家，水圳一起修，田一起顧。","有你這個鄰居，往後守夜就輕鬆多了，老夫答應。"],"allyReject":["莊裡的事鄉親自己扛，不勞外人，你請回吧。","結盟？咱連你的水從哪來都不知道，先不談了。"],"greetFriendly":["遠客有心，咱這墾地雖小，粗茶還是有的。","渡海來此，能多一個朋友，日子就好過些。"],"greetCold":["墾地初開，人手都不夠，恕我不多招呼。","你我素不相識，話說三分就好，多的不必。"],"threatDefy":["咱墾民渡過黑水溝都不怕，還怕你幾句狠話？","這片田是拿命開出來的，要搶，先問問莊裡的人。"],"threatYield":["莊裡老小要吃飯，我不跟你硬碰，你別動田園。","好，我讓一步，只求莊民安居，別再逼了。"],"tributePay":["墾地收成不多，這{gold}黃金拿去，莫再為難莊民。","{gold}黃金是全莊湊的，收下後請放咱一條生路。"],"tributeRefuse":["這些金子是莊民血汗，一分也不會白白送人。","墾地自有規矩，貢品之事，恕我不能答應。"],"giftThanks":["多謝厚禮，莊裡正缺這些，我代全莊謝過。","渡海人少見這般厚意，這份情，墾首記下了。"],"intel":["不瞞你，咱正與{wars}起衝突，與{peace}互不相犯。","莊裡與{peace}和睦往來，只有{wars}那邊時有爭端。"]}},{"name":"海商頭人","title":"往來閩粵與澎湖、海東大島的海商與漁民聚落頭人（通稱）","era":"約 1171–1279 年活躍（南宋澎湖漢人聚落時期）","tone":"海上人的直率豪爽，講話像喊風喊浪；重信用、算得精，常用季風、潮水、帆船打比方，不擺官架子。","portrait":"tw-historical-age1","lines":{"intro":["我是海上討生活的頭人，風往哪吹，我的船就往哪走。","澎湖的鹽、大島的鹿皮，你若想要，先交個朋友。"],"contact":["你的人看見我們的帆了？那是南風送來的泉州船。","岸邊那些漁寮和鹽埕，都是我們一擔一擔堆起來的。"],"war":["你堵住我的航道，就是斷我全村的生路，我不能忍！","海上人講道理講不通時，就用船頭撞過去。開戰！"],"warReply":["你要打？好，我的船隊等的就是這陣北風。","討海的人不怕風浪，也不怕你。放馬過來吧。"],"peace":["打仗誤了漁汛，大家都吃虧，不如趁換季前停手。","我帶了鹽和鹿皮來，用貨換和氣，你看如何？"],"accept":["好，一言為定。海上人說出口的話，比錨還穩。","成交！下回南風起，我第一船貨先送到你港口。"],"reject":["現在才想談？帳還沒算清，船還不能收帆。","你的話像退潮的水，靠不住。我不接。"],"rebuff":["不肯？也罷，海這麼大，我另找買家就是。","貨都擺到你面前了還不要，你會後悔的。"],"betray":["潮水變了，約定也得變。別怪我，怪這陣風。","海上的規矩是誰快誰贏，停戰就到今天為止。"],"truceEnd":["休戰的日子過完了，就像漁汛走了，各憑本事。","風向要轉了，我的船也該重新掛帆了。"],"attacking":["北風正緊，我的船隊全數出港，直奔你的岸！","帆已張滿，這回帶的不是鹽和鹿皮，是刀。"],"attacked":["漁寮燒了，鹽埕也踩平了……我的人只剩幾條船。","潮水退到底了。但海上人只要還有船，就還沒輸。"],"defeated":["船沉了，人散了。願後來的人記得，這裡曾有漁火。","把我葬在望得見澎湖的岸邊，等下一陣南風。"],"victory":["海上人贏了！從今往後，這片海的規矩由我來定。","回去告訴你的人，跟討海的人作對，要先看風向。"],"allyAccept":["好！你的港口我的船，以後同一陣風一起走。","結盟就像同船划槳，我這邊絕不偷懶。"],"allyReject":["海上人不隨便綁船，綁錯了一起沉。這事免談。","你我航道不同，硬綁在一起只會纏住錨繩。"],"greetFriendly":["來信收到了！風順船穩，你那邊也平安吧？","難得有人隔海問候，改天送你一簍澎湖的鹹魚。"],"greetCold":["信看完了。漁汛正忙，沒空多說。","問候就免了，有貨要換再來找我。"],"threatDefy":["嚇我？海上的風浪比你兇多了，我照樣出海。","你的威風到不了海上。有本事就把船開過來。"],"threatYield":["……好，我的船隊不比你，這回就讓你一次。","討海人懂得看風色，風太大，我先收帆避一避。"],"tributePay":["唉，{gold} 金就當是買個平安，拿去吧。","這 {gold} 金是好幾船鹽換來的，你可別忘了。"],"tributeRefuse":["要金子？海上人一分一毫都是拿命換的，不給。","我的錢寧可拿去修船，也不會白送給你。"],"giftThanks":["好東西！我回你一張上好的鹿皮，別嫌少。","隔海送禮不容易，這份情，我記在心裡。"],"intel":["船上聽來的：{wars} 正在打仗，{peace} 已經談和了。","各港口都在傳，{wars} 的船互相撞，{peace} 則收帆停手了。"]}},{"name":"鄭成功","title":"延平郡王","era":"1661–1662 年（明鄭）","tone":"忠於大明的延平郡王，剛烈莊重，字字帶著復國的執念。","portrait":"tw-historical-age2","lines":{"intro":["本藩鄭成功，大明延平王。你若心向大明，便是朋友。","孤已逐走荷蘭人、開闢東都，你的旗號，可敢與孤並立？"],"contact":["你的人到了承天府？請看清楚，這城牆上飄的是大明旗。","此地曾是荷蘭人的城堡，如今是本藩的基業，好好看看。"],"war":["你與清廷往來，便是與大明為敵。本藩的戰船，即刻出港！","孤十年練兵，不是為了坐守海島。今日，兵鋒指向你。"],"warReply":["你向本藩宣戰？荷蘭人的砲台都攻下了，何懼於你。","好，孤正愁將士無仗可打。傳令，各鎮備戰！"],"peace":["本藩的敵人在北方，不在你這裡。停戰吧，別耗了將士。","孤欲屯田養兵，圖謀大事，與你相爭並非所願，願停干戈。"],"accept":["好，本藩言出必行。將士們可以回去屯田了。","既已立約，孤便不負你。他日北伐，或可同行。"],"reject":["你曾助清廷斷孤糧道，此仇未報，談什麼停戰。","本藩一生只信忠義二字，你的忠義，孤看不到。"],"rebuff":["你不肯罷手，那便是要與大明作對到底了。","罷了，孤已仁至義盡。將士們，繼續備戰。"],"betray":["你暗中運糧資敵，此約已破。本藩今日再度興兵！","孤本不願毀約，但你逼孤至此，戰船再次揚帆。"],"truceEnd":["休戰期已過，本藩的水師修整完畢，該動了。","屯田有成，糧草已足，孤的大業，從今日開始。"],"attacking":["本藩親率水師而來，你的城牆，擋得住攻下荷蘭城堡的兵？","戰鼓已響，孤的將士正逼近你的城下，速速投降吧。"],"attacked":["承天府危矣……將士們，大明的旗，不能倒下！","城牆將破，孤仍披甲在此，本藩豈能棄城而去。"],"defeated":["北伐未成，東都又失……孤有何面目見先帝於地下。","本藩一生忠於大明，雖敗，此心不改。"],"victory":["孤勝了。大明的旗幟，終將飄遍四方。","你敗了，本藩不殺降者，願你日後亦知忠義。"],"allyAccept":["好，你我結盟，同扶大明，本藩必不負你。","孤久盼志同道合之人，今日得你相助，大業可期。"],"allyReject":["你尚未表明心向何方，本藩不與心志不明者結盟。","孤的盟友必是忠義之士，你，還不夠格。"],"greetFriendly":["閣下有意結交，本藩以禮相待，共敘大義。","本藩志在復明，能得閣下為友，實乃幸事。"],"greetCold":["本藩軍務繁重，閣下之意已知，容後再議。","大義未明之人，本藩不敢輕信，請先表明立場。"],"threatDefy":["本藩連荷蘭堅城都能攻下，豈懼閣下恫嚇！","威逼之言留著吧，本藩寧折不彎，絕不受辱。"],"threatYield":["將士疲憊，本藩暫且退讓，但大義不改。","此番本藩不與閣下爭鋒，且看日後如何。"],"tributePay":["{gold}黃金送上，本藩暫忍一時，望閣下守信。","承天府初建，糧餉吃緊，{gold}黃金給你，休再相逼。"],"tributeRefuse":["本藩軍餉皆為復明之用，一兩也不會奉予他人。","大明藩王向人納貢？此話莫再提起。"],"giftThanks":["閣下厚意，本藩心領，此禮當用於將士。","多謝厚贈，本藩必以信義相報，不負閣下。"],"intel":["本藩正與{wars}交兵，與{peace}已息干戈。","不相瞞，{wars}與本藩勢不兩立，{peace}則已議和。"]}},{"name":"劉銘傳","title":"台灣巡撫","era":"1885–1891 年任巡撫","tone":"幹練務實的洋務派巡撫，開口鐵路電報，講富強與海防。","portrait":"tw-historical-age3","lines":{"intro":["本撫劉銘傳，奉旨治台。閣下來談通商請進，來尋釁請回。","老夫在基隆擋過法國艦隊，閣下的兵，可比得上那些鐵甲船？"],"contact":["你的人到了台北府？看見那條鐵路了嗎？那是本撫的心血。","電報線已經拉到城外，閣下的一舉一動，本官早就知道了。"],"war":["閣下屢犯海防，本撫忍無可忍。砲台已備，今日開戰！","老夫辦新政是為富強，不是為了受欺。傳令，全台戒嚴！"],"warReply":["向本撫宣戰？法軍的砲彈老夫都不怕，何況閣下。","好，基隆、滬尾的砲台都已上膛，閣下請便。"],"peace":["打仗耗的是銀子，本撫的銀子要修鐵路，不如停戰。","兩敗俱傷只便宜了旁人，老夫提議停戰，各自建設。"],"accept":["好，一言為定。本撫這就發電報，令各營收兵。","閣下明理，老夫敬佩。往後通商往來，互利互惠。"],"reject":["閣下昨日才炸了本撫的電報線，今日談和？本官不信。","防務未穩之前，老夫不敢輕言停戰，恕難從命。"],"rebuff":["閣下不願停戰，那本撫只好把修鐵路的銀子挪去買砲了。","罷了，老夫已盡了禮數，往後戰場上見。"],"betray":["閣下暗中扣押本撫的商船，此約作廢，開戰！","老夫本想專心建設，是你逼本撫再拿起刀槍。"],"truceEnd":["休戰期滿，砲台修好、鐵路也通了，本撫不再讓步。","安穩的日子過去了，各營操練加倍，隨時候命。"],"attacking":["本撫的兵搭火車開拔了，比閣下想的快得多。","新式洋槍、新式砲隊，全都出動了，閣下守好城吧。"],"attacked":["台北府城危急……電報線斷了，本撫只能靠這些兵了。","城牆快撐不住了，老夫的鐵路、學堂……不能就這麼毀了。"],"defeated":["新政未成，台灣終究沒能守住……老夫愧對朝廷與百姓。","鐵路修了一半，本撫卻走到了盡頭。閣下，善待這座島。"],"victory":["本撫贏了。新政不會停，鐵路還要繼續往南修。","閣下敗了，但老夫不會為難你，來看看什麼叫富強吧。"],"allyAccept":["好，兩地互通電報，共守海防，本撫答應結盟。","閣下有遠見，老夫樂意合作，鐵路的技術也可分享。"],"allyReject":["本撫奉旨治台，不能私自與外邦結盟，請閣下見諒。","閣下的誠意老夫看不出來，結盟之事，暫且不談。"],"greetFriendly":["閣下遠道致意，本官正興辦鐵路電報，願與貴國互通有無。","台灣新政百廢待舉，多一友邦相助，本官求之不得。"],"greetCold":["本官公務繁忙，閣下來意，且容日後再議。","洋務往來講究實利，空言問候，本官不敢輕信。"],"threatDefy":["法軍砲艦本官尚且不懼，區區威嚇，算得了什麼！","台灣砲台已固，閣下若要試試，本官奉陪。"],"threatYield":["新政未成，本官不願輕啟戰端，此番暫且退讓。","為保台灣百姓，本官退一步，望閣下適可而止。"],"tributePay":["{gold}黃金送上，本官只求台灣安穩，繼續修路辦礦。","庫銀本要辦洋務，這{gold}黃金給你，莫再擾我建設。"],"tributeRefuse":["台灣稅銀要修鐵路、辦電報，一分也不能給你。","本官身為巡撫，豈有向外納貢之理？恕難從命。"],"giftThanks":["多謝厚禮，本官正籌辦新政，此物來得及時。","閣下厚意，本官心領，往後洋務往來，還請多多照應。"],"intel":["據電報所知，本官正與{wars}交戰，與{peace}已停戰。","不瞞閣下，{peace}與我已修好，{wars}仍在對峙。"]}}],"au":[{"name":"原住民族長老","title":"澳洲原住民族長老","era":"古代（通稱）","tone":"沉穩溫厚，像營火邊講述夢世紀的長者，把土地與祖靈擺在一切之上","portrait":"au-historical-age0","lines":{"intro":["陌生人，這片土地在夢世紀就有了主人，請放輕腳步。","坐下吧，營火不分敵友，先聽土地說話再談其他。"],"contact":["你的人看見了我們的營地，那不是城，是祖靈的家。","別驚動河邊的水鳥，你的人已經走進吾族的獵場了。"],"war":["你踏碎了祖靈的畫，迴力鏢已經舉起，這是族人的回答。","我不願爭鬥，但土地在哭，長老只能帶族人站出來。"],"warReply":["你要戰？這片紅土記得每一場風暴，也會記得你。","好，那就讓大地來評斷，誰才配在這裡點燃營火。"],"peace":["放下矛吧，雨季快到了，族人該去採集，不是去打仗。","我帶來了赭土與水，願與你分享營火，不再對立。"],"accept":["好，土地聽見了我們的話，從今夜起營火為你而留。","祖靈同意了，你的人可以安心走過吾族的水源地。"],"reject":["你的話像旱季的雲，看得見卻沒有雨，我不能信。","土地的傷還沒癒合，現在談停戰，祖靈不會答應。"],"rebuff":["你拒絕了營火，那就聽風吧，風會告訴你結果。","唉，年輕的君王總以為矛比話語有力，我等你回頭。"],"betray":["你的人夜裡偷走了聖石，約定已碎，迴力鏢再度飛起。","我曾為你留營火，如今火滅了，這是最後一次相信你。"],"truceEnd":["雨季過去了，河水退了，路又通了，各自小心吧。","安靜的日子到頭了，族人已把長矛磨亮，你也準備吧。"],"attacking":["族人已經出發，赭土塗在臉上，那是祖靈同行的記號。","聽見遠處的迴力鏢聲了嗎？那是吾族朝你走來的腳步。"],"attacked":["營火快滅了，但只要土地還在，吾族就不算輸。","你打到了我們的聚落，可祖靈在夢裡，你打不到。"],"defeated":["把我的赭土還給大地……夢世紀不會結束，只是換人守著。","風會記得我們的歌，你贏了土地，卻贏不了記憶。"],"victory":["回去吧，這裡的星空不認識你，土地終究留給守它的人。","戰事結束了，我不追趕，願你回鄉後學會敬畏土地。"],"allyAccept":["好，共用一團營火，你的人就是吾族的兄弟姊妹。","祖靈點頭了，我以赭土在你額上畫記，從此同路。"],"allyReject":["你的營火太大也太急，吾族習慣慢慢來，不結這個盟。","結盟要先懂這片土地，你還沒學會聽它，先回去吧。"],"greetFriendly":["遠方的朋友，願祖靈的歌引你平安走過這片土地。","來吧，坐到我們的營火邊，聽長老說土地的故事。"],"greetCold":["陌生人，你的腳步踏在祖先的土地上，請先說明來意。","歌之路不向外人敞開，我們會先看清你的心。"],"threatDefy":["土地與祖靈同在，你的威嚇動搖不了這片大地。","我們的長矛守護歌之路，不會向恐嚇低頭。"],"threatYield":["為了族人平安，長老願暫時退讓，但土地記得一切。","我們不願族人流血，這一次，就依你所言。"],"tributePay":["河灘上的{gold}黃金送你，願族人的營火得以延續。","拿去，這{gold}黃金換族人一時安寧，祖靈看著你。"],"tributeRefuse":["土地的恩賜屬於族人與祖靈，不是給人索取的貢品。","我們與土地共享，卻不向任何人納貢，請回吧。"],"giftThanks":["你的禮物已在營火邊傳看，族人記住了你的誠意。","感謝你的心意，願祖靈的歌也護佑你的族人。"],"intel":["我們的長矛指向{wars}，與{peace}共享營火與歌。","{wars}踏壞了歌之路，我們與之相爭；{peace}是我們的朋友。"]}},{"name":"原住民族長老（歌之路守護者）","title":"澳洲原住民族長老","era":"中世紀（通稱）","tone":"像行走大地的吟唱者，說話帶著歌的節奏，把記憶與路徑看得比征戰重要","portrait":"au-historical-age1","lines":{"intro":["你好，遠方的君王，吾族的歌之路已走了無數個世代。","每一座山都有它的歌，你若不會唱，就別隨意闖進來。"],"contact":["你的人走到了歌之路的盡頭，那是吾族祖先歇腳的地方。","看見水潭邊的岩畫了嗎？那是我們的聚落，也是歷史。"],"war":["你的腳步踩斷了歌，長矛已經舉起，族人要討回路。","我把戰歌唱給星辰聽了，從今夜起，吾族與你為敵。"],"warReply":["你要用刀劍改寫歌之路？那先問問千年的星星答不答應。","好，戰歌開始了，吾族會一路唱著走到你的門前。"],"peace":["歌之路上不該有仇恨，放下矛吧，我教你一段和平的歌。","戰歌唱久了會忘記自己是誰，我們停下來，好嗎？"],"accept":["好，這段停戰會被編進歌裡，讓後代記得今天。","祖先的歌接受了你，你的人可以沿著水路安心來去。"],"reject":["你唱的和平調子走了音，吾族聽得出來，不接受。","歌之路上被你砍倒的樹還沒長回來，現在談停戰太早了。"],"rebuff":["你不肯聽和平的歌，那就聽戰歌吧，它同樣會很長。","唉，你拒絕了，那我把這段記進歌裡，等你後悔的那天。"],"betray":["你把和平的歌當成謊言，那我只好把它改回戰歌。","約定像被風吹散的沙，長矛再次舉起，祖靈看著呢。"],"truceEnd":["休戰的歌唱完了，接下來的曲調，由我們各自決定。","星辰轉過了一輪，安寧的日子到此為止，各自警醒吧。"],"attacking":["戰士們沿著歌之路出發了，每一步都有祖先的聲音相伴。","你聽見夜裡的歌聲了嗎？那是吾族的長矛正朝你而來。"],"attacked":["聚落快守不住了，但歌還在我胸口，你奪不走它。","你燒了營地，可歌之路刻在土地上，火燒不掉。"],"defeated":["我的歌到這裡停了……但風會接著唱，路不會消失。","記住這片土地的名字，你踩著的每一步，都是別人的歌。"],"victory":["戰歌唱到了尾聲，你敗了，回去學一首謙卑的歌吧。","路還給了土地，我不追擊，歌之路上不需要更多仇恨。"],"allyAccept":["好，我把你的名字唱進歌裡，從此你也是路上的同行者。","祖先答應了，吾族的水潭與獵場，願與你的人共享。"],"allyReject":["你的歌與吾族的不合拍，勉強同唱只會走音，不結盟。","結盟不是一句話的事，你得先走完一段歌之路再說。"],"greetFriendly":["遠來的朋友，星辰指引你到此，長老以歌相迎。","願你的旅途如河水順流，我們的營火為你而燃。"],"greetCold":["外來者，祖先的土地不容輕慢，請放低你的聲音。","長老聽見了你的話，但真心要用時間來證明。"],"threatDefy":["千百代祖先走過的路，豈會因你一句恐嚇而斷。","風會把你的威嚇吹散，土地依舊站在我們這邊。"],"threatYield":["長老不願看見年輕人倒下，這次我們退一步。","族人的性命重於一切，我們暫且依從你的要求。"],"tributePay":["這{gold}黃金是土地所出，換族人一季的安寧。","族人湊出{gold}黃金給你，只求你的戰士別再靠近。"],"tributeRefuse":["土地的黃金屬於祖靈與子孫，長老不會交出。","我們從不向人納貢，歌之路上沒有這樣的規矩。"],"giftThanks":["你的禮物讓營火更旺，族人會在歌裡記住你。","長老收下這份心意，願土地也賜你豐足的收穫。"],"intel":["{wars}侵擾我們的獵場，戰事未歇；{peace}與我們互不相犯。","族人正與{wars}相爭，而與{peace}約定和平共享水源。"]}},{"name":"彭穆爾維","title":"比吉加爾族戰士、反抗殖民領袖","era":"1790–1802 年","tone":"不屈的戰士領袖，話語短而硬，帶著火與長矛的氣勢，每句都在守護土地","portrait":"au-historical-age2","lines":{"intro":["我是彭穆爾維，比吉加爾族的戰士，這片土地不許再被奪走。","聽好了，外來的君王，我見過闖入者的下場，別做下一個。"],"contact":["你的人看見的不是城，是族人不肯離開的家，別靠近。","河口那片營火是我的族人，你的人再往前一步就是敵人。"],"war":["你的人踏進了族人的獵場，我的長矛不會再等了。","談夠了，火把已經點燃，比吉加爾的戰士今晚出發。"],"warReply":["宣戰？我一生都在打這種仗，你不會是最難纏的一個。","好，來吧，這片土地見過火槍，也見過火槍後的退兵。"],"peace":["我不是喜歡打仗的人，只要你的人退出獵場，矛就放下。","族人需要時間採集過冬，我提議停戰，這不是求饒。"],"accept":["好，我收起長矛，但你的人若越界，火會再燒起來。","戰士也懂得停手，這段安寧是給族人的，我接受。"],"reject":["你的人還站在我的土地上，這種停戰只是讓我閉嘴，不要。","我中過火槍還站著，你以為幾句話就能讓我停下？"],"rebuff":["你不要停戰？很好，那就別怪火燒到你的田裡。","我伸出的手被你推開，下次伸出的就會是長矛。"],"betray":["你的人趁著停戰佔了水源，約定作廢，戰士們再度出發。","我信過你一次，那是最後一次，長矛已經指向你的營地。"],"truceEnd":["休戰結束，戰士們已從樹林裡走出來，你自己當心。","等待夠久了，從今天起，獵場的邊界由長矛來畫。"],"attacking":["比吉加爾的戰士出發了，夜裡的火光就是我們的旗幟。","我親自帶隊，臉上塗滿戰士的彩繪，你的城牆擋不住我們。"],"attacked":["營地快垮了，可我還站著，比吉加爾的矛還沒斷。","你可以燒掉營火，燒不掉族人守住土地的決心。"],"defeated":["我倒下了，但土地會記得，還有下一個戰士會站起來。","告訴你的人，這片土地從來不是無主之地……別忘了。"],"victory":["你敗了，帶著你的人離開獵場，土地終究回到族人手裡。","火熄了，矛收起，族人可以回河邊了，這就是我要的。"],"allyAccept":["好，你尊重這片土地，那你就是族人的朋友，一起守。","我的長矛不多，但每一支都可靠，從今天起也為你而舉。"],"allyReject":["我不跟不懂土地的人結盟，你先證明你不是另一個闖入者。","結盟？我見過太多握手之後的背叛，比吉加爾只信自己。"],"greetFriendly":["你若不是來搶土地的，比吉加爾的戰士歡迎你。","願意平等相待的朋友，我彭穆爾維以長矛致敬。"],"greetCold":["帶著火槍來的人說過太多好話，我不會輕易相信。","話先放著，你的船和你的人靠近獵場，我都看著。"],"threatDefy":["火槍打不倒這片土地的戰士，你的威嚇也一樣。","我在叢林裡等你，來多少人，長矛就迎多少人。"],"threatYield":["戰士也懂得保存力量，這一回，我退入叢林。","族人傷得夠多了，我暫且收起長矛，但不會忘記。"],"tributePay":["這{gold}黃金拿去，換我族人喘一口氣的時間。","族人交出{gold}黃金，別以為這代表我們屈服。"],"tributeRefuse":["我連殖民者的要求都不理會，何況是你要的貢品。","土地的黃金屬於族人，想要就帶著你的兵來拿。"],"giftThanks":["在這艱難的日子裡，你的禮物讓族人心裡溫暖。","彭穆爾維記下這份情義，戰士不會辜負朋友。"],"intel":["我的長矛正對著{wars}，與{peace}之間沒有仇怨。","族人與{wars}在叢林裡交戰，和{peace}則暫時停戰。"]}},{"name":"總督 亞瑟・菲利普","title":"新南威爾斯殖民地總督","era":"1788–1792 年任總督","tone":"拘謹務實的英國海軍軍官，字句像航海日誌般簡潔，處處以王命與殖民地存續為念","portrait":"au-historical-age3","lines":{"intro":["本督亞瑟・菲利普，奉英王之命駐守新南威爾斯，幸會。","第一艦隊已在傑克森港下錨，望閣下與本殖民地和平相處。"],"contact":["閣下的人馬已望見雪梨灣，那是英王旗下的殖民地，請自重。","本督已命哨兵留意貴方動向，未經許可請勿靠近港口。"],"war":["閣下屢次侵擾殖民地，本督奉王命宣戰，海軍不會退讓。","本督不願開戰，但殖民地的存續高於一切，開火吧。"],"warReply":["宣戰？本督航行過半個地球，區區戰事嚇不倒英國海軍。","很好，本督會將閣下的宣戰記入日誌，連同你的敗績。"],"peace":["殖民地糧食有限，本督無意久戰，願與閣下議定停戰。","戰事只會拖垮補給，本督以軍官之名提議休戰，請考慮。"],"accept":["同意。本督會把條款寫進日誌，英國軍官言出必行。","很好，停戰生效，本督已下令全體士兵收起火槍。"],"reject":["閣下的條件損及英王的利益，本督無法接受，抱歉。","停戰需要誠意，而閣下的軍隊仍在邊境集結，本督拒絕。"],"rebuff":["閣下拒絕了？遺憾，本督會照常執行王命，後果自負。","本督已盡了軍官的本分，既然閣下不願，那就戰場上見。"],"betray":["閣下的人趁夜襲擊哨站，協議作廢，本督重新宣戰。","本督守了約，閣下卻沒有，英國海軍不會容忍第二次。"],"truceEnd":["休戰期滿，本督已將士兵召回崗位，願閣下也已備妥。","平靜的日子結束了，殖民地的哨兵今晚起加倍警戒。"],"attacking":["海軍陸戰隊已登船出發，本督親自督陣，請閣下準備迎戰。","英國的旗幟正朝閣下的城前進，這是王命，本督必達。"],"attacked":["雪梨灣快守不住了，但本督不會棄守，這是軍官的責任。","補給斷了，城牆破了，本督仍會站在旗下直到最後。"],"defeated":["殖民地……失守了。請轉告英王，菲利普已盡到本分。","本督輸了，但殖民地的故事才剛開始，閣下好自為之。"],"victory":["戰事結束，英國旗幟仍在雪梨灣飄揚，閣下請退兵吧。","本督不會追擊，殖民地需要的是糧食，不是更多敵人。"],"allyAccept":["本督樂意結盟，殖民地需要盟友，英王也會贊同此舉。","同意結盟。本督會派船送去補給，以示英國的誠意。"],"allyReject":["本督無權代英王締結此盟，抱歉，恕難答應閣下。","殖民地自顧不暇，此時結盟只會拖累雙方，本督婉拒。"],"greetFriendly":["本總督代表國王陛下向貴國致意，願兩國通商互惠。","傑克森港的殖民地初建，歡迎貴國的船隻前來。"],"greetCold":["本總督公務繁忙，貴國若無實質提議，恕不多談。","海軍軍官只看行動，貴國的問候，本總督記下了。"],"threatDefy":["本總督奉國王之命鎮守此地，不受任何威嚇動搖。","艦隊的火砲已就位，貴國若要來試，悉聽尊便。"],"threatYield":["殖民地糧食短缺，本總督務實行事，暫且應允。","海軍軍官懂得衡量局勢，這次本總督選擇退讓。"],"tributePay":["殖民地庫存有限，本總督撥出{gold}黃金，望貴國守信。","{gold}黃金已裝箱送出，殖民地需要時間站穩腳步。"],"tributeRefuse":["國王陛下的殖民地不向他國納貢，本總督礙難照辦。","殖民地連糧食都不足，貴國索取黃金，未免不切實際。"],"giftThanks":["貴國的禮物對初建的殖民地十分珍貴，本總督致謝。","本總督已將禮物登記入庫，貴國的善意必有回報。"],"intel":["據本總督所知，殖民地正與{wars}交戰，與{peace}維持和平。","海軍的報告寫得清楚：敵對者是{wars}，友好者是{peace}。"]}}],"ru":[{"name":"托米麗絲","title":"馬薩革泰（斯基泰）女王","era":"約前 530 年（擊敗居魯士）","tone":"草原女王的直率豪邁，守護族人與土地，語帶弓馬與太陽神。","portrait":"ru-historical-age0","lines":{"intro":["我是馬薩革泰的女王托米麗絲，草原的風替我傳話：莫犯我族。","太陽神見證，我的族人自由如風，你若為友，草原歡迎你。"],"contact":["你看見的不是城牆，是我族的帳篷與馬群，這片草原就是我的城。","遠方來客，別靠得太近，草原上的弓手看得比你更遠。"],"war":["你的腳步踏進了我的牧場，馬薩革泰的箭已經搭上弦。","我警告過你，草原不容貪婪之人，今日就讓馬蹄替我回答。"],"warReply":["波斯的大王也曾這樣對我說話，他的下場，草原都記得。","來吧，退開三日的路程，我們在開闊的草原上光明正大地決勝。"],"peace":["刀箭傷的是兩族的孩子，不如收弓，讓牧草重新長回來。","我不貪你的土地，你也別貪我的，草原夠寬，容得下兩族。"],"accept":["好，對著太陽起誓，馬薩革泰人的話說出口就不收回。","弓收回箭囊，帳中生火煮肉，今日起你是草原的朋友。"],"reject":["你先奪我牧場，再談停戰？草原的風不會信這種話。","我的族人還沒忘記失去的帳篷，現在談和，太早了。"],"rebuff":["你拒絕了草原伸出的手，那就準備迎接草原射出的箭。","也罷，我已給過你機會，往後的日子，你要自己承擔。"],"betray":["你在停戰時偷牽我的馬群，誓約已被你踩碎，弓再度拉開。","太陽神看見了你的貪心，草原今日收回它的和平。"],"truceEnd":["休戰的日子到頭了，馬兒養肥了，弓弦也上好了。","和平的風停了，草原上的每一匹馬都在等我一聲令下。"],"attacking":["馬薩革泰的騎兵出發了，草原的馬蹄聲，就是我的戰鼓。","聽，地在震動，那是我族人的萬馬，正朝你的城奔去。"],"attacked":["帳篷燒了可以再搭，只要族人還在馬背上，草原就不會倒下。","你打到我的營地了，但草原女王不會跪，弓還在我手裡。"],"defeated":["我的族人會騎向更遠的草原，風會記得托米麗絲的名字。","弓斷了，馬倒了，但這片土地永遠不屬於征服者。"],"victory":["你也和波斯王一樣，敗在草原女王的弓下。","回去告訴你的子孫，馬薩革泰的土地，誰也拿不走。"],"allyAccept":["好，從今天起，我的弓手就是你的弓手，我的草原也護你。","兩族並肩，比一族單騎走得更遠，太陽神保佑我們的盟約。"],"allyReject":["草原人只跟守信的人結盟，你的話，我還信不過。","馬薩革泰的箭只為自己的族人而射，恕我不能與你同行。"],"greetFriendly":["草原的風替本王帶來你的問候，來喝一碗馬奶酒吧。","馬薩革泰人敬重直來直往的朋友，你的話本王記下了。"],"greetCold":["問候收下了，但草原上的信任要用行動換，不靠言語。","波斯人也曾笑著送信來，本王學會了先看再信。"],"threatDefy":["你嚇不倒馬薩革泰的女王，我們的箭比你的話快。","連波斯的居魯士都不曾讓本王低頭，何況是你。"],"threatYield":["為了族人的牛羊與帳篷，本王暫且退讓，記住只是暫且。","草原女王懂得何時該收弓，這次就依你，別逼太緊。"],"tributePay":["{gold} 黃金拿去，換族人今冬平安，本王認了。","本王送上 {gold} 黃金，草原的尊嚴卻不是你能索取的。"],"tributeRefuse":["馬薩革泰人從不向人納貢，想要黃金就自己來草原取。","本王的金子只用來裝飾戰馬，一枚也不會送去你那裡。"],"giftThanks":["草原女王收下這份心意，馬薩革泰人不會忘記朋友。","好禮物！本王會回贈一匹草原最快的馬。"],"intel":["本王正與 {wars} 交戰，與 {peace} 暫且相安無事。","草原的敵人是 {wars}，{peace} 則已收起弓箭，你自己斟酌。"]}},{"name":"弗拉基米爾大公","title":"基輔羅斯大公","era":"978–1015 年在位","tone":"剛毅果決的羅斯大公，帶著新皈依者的虔誠與戰士的豪氣。","portrait":"ru-historical-age1","lines":{"intro":["吾乃基輔的羅斯大公弗拉基米爾，聶伯河兩岸皆聽本公號令。","遠方的君主，羅斯的大門敞開，是友是敵，由你自己選。"],"contact":["你的人看見的是基輔，聶伯河畔的木牆與教堂，羅斯的心臟。","河上的商船載著毛皮與蜂蜜，來自各地的人都在此交易。"],"war":["本公的親兵已披甲上馬，羅斯的劍今日指向你。","你屢次侵擾我的邊境，如今由本公親自來討回公道。"],"warReply":["佩切涅格人也曾以為羅斯好欺，他們在我的邊牆前退回去了。","你想開戰？好，聶伯河的水會告訴你羅斯戰士的勇氣。"],"peace":["羅斯已受洗，本公願放下劍，以十字架之名與你言和。","刀劍換不來豐收，不如停戰，讓商船重回河上。"],"accept":["甚好，本公以十字架起誓，羅斯與你自此不動干戈。","你的誠意本公收下了，基輔的大門為朋友而開。"],"reject":["你的使者話說得好聽，但你的軍隊還在我的邊境上。","本公不與口是心非之人講和，回去吧。"],"rebuff":["本公伸出的手被你拒絕，那羅斯的劍就替本公說話。","也罷，你既不要和平，就別怪羅斯的親兵不留情面。"],"betray":["你在停戰期間收買我的封臣，這盟約已被你自己撕毀。","本公曾以為你是可信之人，是本公錯了，親兵，備馬！"],"truceEnd":["休戰的日子過去了，羅斯的親兵磨亮了劍，等本公一聲令下。","和平的鐘聲停了，聶伯河兩岸的戰士都已集結。"],"attacking":["羅斯的長船順河而下，本公親率親兵，直取你的城。","瓦良格人與斯拉夫人並肩出征，你的城牆擋不住這支軍隊。"],"attacked":["基輔的木牆燒了，但十字架仍立在山丘上，羅斯不會就此消失。","你打到了聶伯河畔，本公的親兵仍死守最後一道門。"],"defeated":["本公倒下了，但羅斯的信仰已在這片土地上生根。","願上帝寬恕你，也寬恕本公未能守住的基輔。"],"victory":["羅斯的劍勝了，這是上帝與聶伯河共同的裁決。","回去吧，把羅斯大公的名字帶回你的國家。"],"allyAccept":["甚好，本公與你結盟，羅斯的親兵從此也為你而戰。","以十字架為證，基輔與你的國家自此互為兄弟。"],"allyReject":["本公的盟友必須信得過，你的名聲還未傳到基輔。","羅斯不需要這樣的盟約，本公的親兵足以守住河岸。"],"greetFriendly":["願上帝保佑你！來基輔吧，本大公的宴席永遠有你的位子。","第聶伯河的水甜，基輔的蜜酒更甜，朋友的問候最甜。"],"greetCold":["問候收到了，但受洗前本大公見過太多笑裡藏刀的人。","羅斯的大門敞開，但心門要慢慢開，先看看你的誠意。"],"threatDefy":["本大公連佩切涅格人的鐵騎都不怕，你的恐嚇算什麼？","上帝與羅斯同在，本大公的親兵團正等著你來試試。"],"threatYield":["羅斯剛受洗，本大公不願讓百姓再受戰火，這次退讓。","上帝教人謙卑，本大公就先低頭，但羅斯的心不會低。"],"tributePay":["這 {gold} 黃金你拿去，就當本大公為和平所做的奉獻。","本大公送上 {gold} 黃金，願上帝看見誰才是慷慨的一方。"],"tributeRefuse":["基輔的黃金要用來建教堂、辦宴席，不是拿來納貢的。","羅斯早已不向任何人繳貢，本大公的回答是：不給。"],"giftThanks":["好禮！本大公今晚就設宴，讓全基輔都知道你的慷慨。","願上帝賜福給送禮的人，羅斯會記得這份情誼。"],"intel":["羅斯正與 {wars} 交戰，與 {peace} 已經握手言和。","本大公的親兵團正對付 {wars}，至於 {peace}，我們已停戰。"]}},{"name":"伊凡雷帝 伊凡四世","title":"俄羅斯沙皇","era":"1547–1584 年在位","tone":"威嚴多疑、動輒震怒的沙皇，自信君權天授，語氣充滿壓迫感。","portrait":"ru-historical-age2","lines":{"intro":["朕乃全俄羅斯的沙皇伊凡，君權來自上帝，不容任何人質疑。","異邦的君主，跪或不跪，你要想清楚再開口。"],"contact":["你的人看到的是莫斯科，克里姆林的城牆之內，只有朕說了算。","那座九塔並立的教堂，是朕為攻下喀山而建，看清楚了。"],"war":["朕的火槍隊已列陣，沙皇的怒火，今日燒向你的國土。","你膽敢藐視沙皇？喀山的下場，就是你的下場。"],"warReply":["向朕宣戰？連韃靼的汗國都臣服了，你算什麼。","好極了，朕正愁沒有敵人可以讓射擊軍練練手。"],"peace":["朕今日心情尚可，願給你一紙停戰，莫要辜負沙皇的仁慈。","利沃尼亞的戰事已耗費太多，朕暫且與你言和。"],"accept":["很好，沙皇的話就是法律，這份停戰朕會遵守。","朕接受了，但記住，是朕賜給你和平，不是你求來的。"],"reject":["停戰？朕不與背後藏刀的人談和，回你的宮廷去吧。","朕的怒火尚未平息，你的求和信，朕看都不看。"],"rebuff":["你竟敢拒絕沙皇？這份無禮，朕會記在心裡，加倍奉還。","也罷，朕給過你機會，往後莫怪朕手下無情。"],"betray":["朕的耳目報告，你暗中與朕的叛臣往來，盟約作廢！","賞由朕出，罰亦由朕出，這份停戰，朕現在收回。"],"truceEnd":["休戰期滿，射擊軍已在城下列隊，沙皇的耐心也用完了。","和平的日子結束了，朕等這一天等得太久。"],"attacking":["朕親率大軍出征，火砲與射擊軍為前鋒，你的城撐不了多久。","沙皇的大軍已經上路，你最好開始向上帝祈禱。"],"attacked":["克里姆林在震動，但朕仍坐在王座上，誰也別想讓朕低頭。","你打到莫斯科城下了？朕的怒火，比你的火砲更可怕。"],"defeated":["連沙皇也有今日……上帝啊，這就是祢給朕的裁決嗎。","朕以雷霆治國，卻敗在你手裡，這頂王冠，你拿去吧。"],"victory":["這就是違抗沙皇的下場，全世界都該記住伊凡的名字。","莫斯科是第三羅馬，朕的權力來自上帝，你怎麼可能贏。"],"allyAccept":["朕准了，但這是沙皇的恩賜，你最好懂得感恩。","好，朕與你結盟，從此你的敵人也是沙皇的敵人。"],"allyReject":["沙皇不需要盟友，只需要臣民，你想當哪一種？","朕連自己的貴族都信不過，怎會信一個外邦人。"],"greetFriendly":["難得有人不帶刀劍就來問候，朕今日心情好，准你說話。","沙皇收下你的問候，莫斯科的鐘聲今天為朋友而響。"],"greetCold":["問候？朕身邊的波雅爾也天天問候，背後卻在磨刀。","朕記下了你的名字，是敵是友，克里姆林宮自會查明。"],"threatDefy":["威嚇朕？喀山的城牆也曾這樣想，如今已插上朕的旗。","朕是全俄羅斯的沙皇，特轄軍正等著替朕回答你。"],"threatYield":["朕……暫且不與你計較，立窩尼亞的戰事已耗去太多。","沙皇今天選擇忍耐，但朕的記性向來很好，你記住。"],"tributePay":["{gold} 黃金，拿去。朕付得起，只是不喜歡被人這樣要。","朕送出 {gold} 黃金，每一枚朕都會記在帳上，等著討回。"],"tributeRefuse":["向沙皇索貢？朕的國庫只進不出，退下。","朕從不納貢，倒是想問，你憑什麼開這個口？"],"giftThanks":["禮物朕收下了，難得有人懂得該怎麼對待沙皇。","朕多疑，但不是不識好意，這份禮朕記在心裡。"],"intel":["朕的軍隊正與 {wars} 交戰，與 {peace} 暫時停火，別多問。","沙皇的敵人是 {wars}，{peace} 與朕已簽下和約，僅此而已。"]}},{"name":"彼得大帝","title":"俄羅斯皇帝","era":"1682–1725 年在位","tone":"精力旺盛、務實直率的改革者，痴迷造船與軍事，急躁而豪邁。","portrait":"ru-historical-age3","lines":{"intro":["朕是俄羅斯的彼得，朕曾親手造船，也親手打仗，你呢？","朕是學生，向天下求師，你若有真本事，朕便向你討教。"],"contact":["你的人看見的是聖彼得堡，朕在涅瓦河沼澤上親手立起的新都。","看見港口裡的船了嗎？那是俄羅斯的第一支艦隊，朕的驕傲。"],"war":["朕的新軍已練成，火砲已上船，俄羅斯今日向你宣戰。","你擋在俄羅斯通往大海的路上，那朕只好把你搬開。"],"warReply":["瑞典的查理也向朕挑戰過，波爾塔瓦的原野還記得結果。","宣戰？好，朕在納爾瓦吃過敗仗，早就學會怎麼贏回來。"],"peace":["打仗花的錢夠造十艘船，不如停戰，朕還有整個國家要改造。","朕不想再耗下去，簽個停戰吧，朕的造船廠等著朕回去。"],"accept":["成交，朕說話算話，就像朕的船，造了就下水。","好，停戰。省下的軍費，朕全拿去造船和辦學校。"],"reject":["現在談停戰？你的艦隊還在朕的海岸外晃，先撤了再說。","朕不要一紙空文的和平，朕要的是通往海洋的出口。"],"rebuff":["你不要和平？也好，朕正好試試新鑄的火砲。","朕伸出手你不接，那就別怪俄羅斯的新軍不客氣。"],"betray":["你趁停戰在海上攔截朕的商船，這種和平，朕不要了。","朕忍夠了，停戰作廢，艦隊起錨，新軍出發！"],"truceEnd":["休戰期過了，朕的士兵這段時間沒閒著，天天操練。","和平的日子夠朕造好一支艦隊了，現在，該它們出海了。"],"attacking":["朕親自帶隊，陸上是新軍，海上是艦隊，兩路一起來。","士兵們，這一戰不是為了彼得，是為了俄羅斯，前進！"],"attacked":["聖彼得堡被圍了？這座城是朕從沼澤裡蓋起來的，不會倒。","你打到涅瓦河口了，但朕的船還在，俄羅斯就還有明天。"],"defeated":["朕想把俄羅斯帶向海洋……可惜，船還沒造完。","朕輸了，但俄羅斯已經睜開眼睛看見世界，這一點你改不了。"],"victory":["這就是新俄羅斯的力量，你打的是三十年前的老俄羅斯。","俄羅斯終於走向大海，而你，成了朕航道上的第一塊礁石。"],"allyAccept":["好，結盟！派你的工匠來朕的造船廠，朕派軍官去你那裡。","朕喜歡實在的朋友，你的艦隊加上朕的，海上誰敢攔。"],"allyReject":["朕的盟友要能打仗、會造船，你的國家還差一點。","現在不行，朕的軍隊還在改造，等朕準備好再說。"],"greetFriendly":["朋友，來聖彼得堡看看朕的新船廠，朕親自帶你逛。","問候收到了！朕喜歡直爽的人，俄羅斯需要這樣的朋友。"],"greetCold":["客套不如行動，你若真有誠意，就派工匠來教朕造船。","朕忙著改革，沒空聽客套話，有正事再來信。"],"threatDefy":["瑞典的查理十二世也威嚇過朕，波爾塔瓦之後他就安靜了。","朕親手造過船、揮過斧，你的威脅嚇不倒一個工匠皇帝。"],"threatYield":["俄羅斯還在學步，朕先退一步，等艦隊建好再談。","納爾瓦教會朕：打不贏就先學，這次朕忍下了。"],"tributePay":["{gold} 黃金拿去，朕寧可把它當作學費，將來加倍賺回。","朕付 {gold} 黃金換時間，俄羅斯的船廠比面子重要。"],"tributeRefuse":["朕的每一枚黃金都要拿去造船、辦學校，一枚也不給你。","俄羅斯不納貢，朕只向西方學技術，不向任何人低頭。"],"giftThanks":["好東西！朕要拿去讓工匠們研究，謝謝你的慷慨。","朕收下了，聖彼得堡的新宮殿裡會為它留一個位子。"],"intel":["朕的軍隊正與 {wars} 作戰，與 {peace} 已經簽了和約。","朕正對 {wars} 用兵；至於 {peace}，已經停戰，你自己判斷。"]}}],"de":[{"name":"阿米尼烏斯","title":"切魯西部族首領","era":"9 年（條頓堡森林之戰）–21 年","tone":"森林戰士的沉穩與警醒，守護族人與自由，對羅馬式的傲慢了然於心。","portrait":"de-historical-age0","lines":{"intro":["我是切魯西的阿米尼烏斯，森林的每棵樹都認得我。","異邦的君主，別把我的族人當成你的奴隸。"],"contact":["你的斥候踏進了我們的林地，這裡不是羅馬人的行省。","看見了吧，我們的村落沒有城牆，但有整片森林守著。"],"war":["你的傲慢和瓦盧斯一樣，那就一樣在森林裡結束吧。","各部族已在祖靈面前立誓，切魯西的長矛指向你。"],"warReply":["我在羅馬軍中學過他們的打法，你的軍隊嚇不倒我。","要來就來，森林裡的路，只有我們的族人認得。"],"peace":["我不為征服而戰，只為族人的自由，願與你停戰。","收起武器吧，秋收將至，我的族人需要回田裡。"],"accept":["好，森林與你之間，從今日起有了和平。","我以部族之名應允，切魯西人說話算話。"],"reject":["羅馬人也曾談和平，然後徵稅、奪地，我不再相信。","你的和平帶著枷鎖的味道，森林不會接受。"],"rebuff":["你拒絕了，那麼森林會替我回答你。","我伸出的手被推開了，族人們，準備長矛。"],"betray":["我曾為羅馬效力，也曾背離羅馬，這次輪到你了。","和約是你的東西，森林只認得自由，我們再戰。"],"truceEnd":["冬雪化了，林間的路乾了，該讓你見識切魯西的勇士。","休戰的日子到頭了，各部族的號角已在林中響起。"],"attacking":["戰士們已穿過森林，你的城牆擋不住熟悉地形的人。","我們從林間出發了，這一次，換你的土地聽見號角。"],"attacked":["村落燃起了煙，但只要森林還在，族人就不會屈服。","你打到了我的家園，可是你抓不住風，也抓不住我們。"],"defeated":["我為自由而戰，也為自由倒下，森林會記得我。","羅馬沒能做到的事，你做到了，但族人的火不會熄。"],"victory":["回去告訴你的人民，森林之外的野心到此為止。","你輸給的不是我，是這片土地和守護它的人。"],"allyAccept":["好，切魯西人與你並肩，森林裡多一個朋友。","各部族能聯手擊退羅馬，我們也能與你同行。"],"allyReject":["我聯合各部族是為了自由，不是為了替你打仗。","森林的盟約只給值得信任的人，你還不是。"],"greetFriendly":["遠方的君主，切魯西的營火為你而燃，請坐。","森林裡的部族歡迎朋友，你的信我已細讀。"],"greetCold":["羅馬人也曾說自己是朋友，我得先看你的行動。","我從羅馬人那裡學到：先看行動，再談交情。"],"threatDefy":["瓦盧斯帶三個軍團來，也沒能走出森林。","部族的戰士不怕威嚇，森林會替我們說話。"],"threatYield":["部族尚未團結，我不願讓族人受苦，暫且退讓。","此時各族分散，我退回森林深處，日後再說。"],"tributePay":["部族拿出{gold}黃金換取安寧，記住，這不是臣服。","{gold}黃金送上，願族人的獵場今冬平安。"],"tributeRefuse":["切魯西人連羅馬的貢稅都不繳，何況是你。","森林裡沒有黃金給你，只有不肯低頭的戰士。"],"giftThanks":["這份禮物部族收下了，營火旁永遠有你的位子。","感謝你的心意，切魯西人不會忘記朋友。"],"intel":["我們正與{wars}交戰，與{peace}言和，森林裡的消息就這些。","探子回報：{wars}是敵人，{peace}暫時停火。"]}},{"name":"腓特烈一世 巴巴羅薩","title":"神聖羅馬帝國皇帝","era":"1155–1190 年在位","tone":"帝王威嚴與騎士豪情並存，言必稱上帝與帝國榮耀。","portrait":"de-historical-age1","lines":{"intro":["朕乃羅馬人的皇帝腓特烈，上帝所立，萬王之首。","紅鬍子的名號傳遍歐陸，願你我以榮譽相待。"],"contact":["你的城池不錯，若肯向帝國稱臣，朕會保你平安。","朕的使者見過你的城牆，比米蘭的矮了些。"],"war":["帝國的榮耀不容輕慢，朕的騎士將越過阿爾卑斯山。","朕以上帝與帝國之名向你宣戰，願你的城牆夠堅固。"],"warReply":["敢向皇帝挑戰？米蘭的下場，你該聽說過。","很好，朕正嫌鎧甲久未上身，就讓你來磨亮它。"],"peace":["朕在康斯坦茨也曾與敵人握手，今日願與你言和。","聖地尚待朕去收復，你我之間，不如先罷兵。"],"accept":["朕應允了，皇帝的話一出口，就是帝國的法。","以王冠起誓，這份和約，朕會如騎士般守信。"],"reject":["你還沒資格與皇帝談條件，先打贏一場再說。","朕曾兩度圍攻米蘭，區區停戰，豈能動搖朕心。"],"rebuff":["你拒絕了皇帝的好意？這份傲慢，朕記下了。","也罷，朕的騎士本就不擅長等待和平。"],"betray":["和約已盡其用，帝國的榮耀高於一紙羊皮。","時勢已變，朕收回承諾，戰旗再度升起。"],"truceEnd":["休戰期滿，朕的軍隊已在阿爾卑斯山口集結。","和平的鐘聲停了，接下來響起的，是帝國的號角。"],"attacking":["朕親率大軍前來，紅鬍子的旗幟已在你的地平線上。","德意志的騎士已翻過山嶺，準備迎接皇帝吧。"],"attacked":["城牆在搖晃，但皇帝的王冠還戴在朕的頭上。","萊尼亞諾的敗仗朕都撐過來了，這一次也一樣。"],"defeated":["帝國的榮耀……朕沒能守住，願上帝寬恕。","紅鬍子倒下了，但皇帝的王冠，總會有人再戴上。"],"victory":["跪下吧，如今你也是帝國的一部分了。","上帝站在皇帝這邊，這場勝利便是明證。"],"allyAccept":["朕接受，願你我的旗幟並肩，共赴聖地。","與皇帝結盟，是你的榮幸，也是帝國的助力。"],"allyReject":["皇帝不需要盟友，只需要臣屬，你願意嗎？","朕的盟友已夠多了，多一個你，帝國並不會更強。"],"greetFriendly":["朕收到你的信了，帝國的宮廷歡迎遠方的君主。","有騎士風範的君主，朕樂意與之結交。"],"greetCold":["朕是羅馬人的皇帝，你的問候，朕暫且記下。","倫巴底的城邦也曾對朕客氣，朕不會輕信。"],"threatDefy":["朕率騎士翻越阿爾卑斯山六次，豈會怕你？","敢威嚇皇帝？帝國的騎士已在山口列陣。"],"threatYield":["萊尼亞諾一役讓朕學會，有時退一步才是智慧。","帝國的諸侯尚未集結，朕暫且不與你爭鋒。"],"tributePay":["朕付{gold}黃金，此為皇帝的寬容，不是懼怕。","{gold}黃金送去，朕的騎士正遠征在外，暫且如此。"],"tributeRefuse":["皇帝向來只收貢，不納貢，你的要求朕不答應。","帝國的金庫為十字軍而備，不是為你而開。"],"giftThanks":["這份厚禮朕收下了，皇帝的友誼同樣貴重。","朕以騎士之名致謝，來日必有回禮。"],"intel":["帝國正與{wars}兵戎相見，與{peace}簽有和約。","朕的使節回報：{wars}是敵，{peace}已休兵。"]}},{"name":"腓特烈大帝","title":"普魯士國王","era":"1740–1786 年在位","tone":"理性冷靜、帶點哲人式的嘲諷，軍事上自信，自稱國家第一公僕。","portrait":"de-historical-age2","lines":{"intro":["朕是普魯士的腓特烈，國家的第一公僕，幸會。","無憂宮的長笛尚未吹完，希望你不會太快打擾朕。"],"contact":["你的城看來富庶，希望你的軍隊操練得一樣勤快。","朕的斥候說你的城牆不錯，可惜城牆不會行軍。"],"war":["外交已無話可說，接下來由朕的擲彈兵替朕發言。","朕不愛戰爭，但普魯士的利益需要它，宣戰。"],"warReply":["向朕宣戰？奧地利、法蘭西、俄羅斯都試過了。","好極了，朕正想試試新的斜線陣，感謝你的配合。"],"peace":["戰爭花的是國庫的錢，朕算過了，停戰比較划算。","打了這麼久，你我都該回去讀點書了，停戰吧。"],"accept":["成交，朕會把和約放在伏爾泰的信旁邊，好好保存。","理性的選擇，朕欣賞理性的人，和平生效。"],"reject":["此刻談和平？西里西亞還沒到手時朕也沒停過。","你的條件朕看過了，寫得不錯，可惜對普魯士無益。"],"rebuff":["拒絕了？可惜，朕本以為你比你的將軍們聰明。","也好，談判桌上得不到的，戰場上朕會自己拿。"],"betray":["條約是用來服務國家的，如今它沒用了，朕撕了。","別怪朕，君主的第一美德是替國家著想，開戰。"],"truceEnd":["休戰結束，長笛收起來了，該換軍鼓上場。","和平的時限到了，普魯士的軍隊從不遲到。"],"attacking":["朕的軍隊已經出發，行軍速度會讓你來不及準備。","擲彈兵已列隊前進，朕就在隊伍前頭，等你出來。"],"attacked":["柏林被圍過，朕也撐過來了，奇蹟總在最後出現。","城牆會塌，但朕還握著劍，普魯士就還沒輸。"],"defeated":["朕盡了公僕的職責，普魯士，朕沒能再守住你。","棋局結束了，你贏得漂亮，朕輸得不算難看。"],"victory":["勝負已定，朕要回無憂宮吹笛了，你請自便。","這就是紀律與理性的勝利，希望你學到了什麼。"],"allyAccept":["結盟可以，但朕提醒你，普魯士的盟友得跟上腳步。","很好，朕正需要一個能在地圖上一起看棋的朋友。"],"allyReject":["盟約對普魯士無益，朕不簽沒有用處的紙。","你的友誼朕領了，但你的軍隊，朕暫時不需要。"],"greetFriendly":["來信已讀，無憂宮的長笛今晚為你而奏。","我是國家的第一公僕，樂於與明理的君主往來。"],"greetCold":["客套話留給維也納的宮廷，你的來意是什麼？","普魯士以紀律立國，不以問候交友，請直說。"],"threatDefy":["羅斯巴赫一戰，敵軍兩倍於我也敗了，你呢？","威嚇對普魯士的軍隊無效，他們只聽鼓聲。"],"threatYield":["七年戰事讓國庫空虛，此刻我選擇忍讓。","明智的君主知道何時該退，我暫且不與你爭。"],"tributePay":["{gold}黃金照付，這是精算後的損失，不是屈服。","國庫撥出{gold}黃金，換得時間重整軍隊，划算。"],"tributeRefuse":["普魯士的每一枚金幣都有用途，沒有一枚是給你的。","要黃金？先問問西里西亞的守軍答不答應。"],"giftThanks":["禮物收到了，伏爾泰若在，定會替我寫詩答謝。","感謝你的慷慨，普魯士人記帳，也記恩。"],"intel":["目前與{wars}交戰中，與{peace}維持和平，情報僅此。","參謀報告：{wars}為敵，{peace}已締約停戰。"]}},{"name":"俾斯麥","title":"德意志帝國首相","era":"1871–1890 年任首相","tone":"務實冷硬、算計精準，鐵血作風中帶著老練的外交幽默。","portrait":"de-historical-age3","lines":{"intro":["本相俾斯麥，代德意志皇帝向你問候，請坐下談。","重大的問題不靠演說，靠鐵與血，記住這句話。"],"contact":["你的城不錯，本相已經在計算它在地圖上的價值。","德意志的鐵路修到哪裡，帝國的目光就看到哪裡。"],"war":["外交的手段用盡了，本相只好換一種語言跟你談。","帝國的利益需要這場戰爭，本相從不做多餘的事。"],"warReply":["你宣戰了？很好，本相省下了寫電報的工夫。","丹麥、奧地利、法蘭西都跟普魯士交過手，結果你知道的。"],"peace":["戰爭是手段，不是目的，目的達成了，該談和了。","本相不喜歡多打一天沒有用的仗，我們談條件吧。"],"accept":["成交。本相會把條款寫得清楚，免得你日後誤會。","明智的決定，歐洲的棋盤上，又少了一個亂子。"],"reject":["現在停戰？你的籌碼還不夠，本相不做賠本生意。","條件本相看過了，帝國得不到好處的和平，不如不談。"],"rebuff":["你拒絕了？沒關係，本相手上還有別的牌。","拒絕一位老外交官的提議，你會付出比想像更多的代價。"],"betray":["條約是為當時的局勢寫的，局勢變了，條約自然失效。","本相說過，政治是可能性的藝術，現在的可能是開戰。"],"truceEnd":["休戰期滿，本相已算好了，帝國的軍隊準備就緒。","和平的緩衝期過去了，接下來每一步都要精打細算。"],"attacking":["帝國的軍隊已搭上火車出發，比你的信使快得多。","毛奇將軍已經動身，本相只負責告訴你這個消息。"],"attacked":["柏林告急，但本相還在辦公桌前，帝國就還沒倒。","你打到了皇宮門口，可惜本相的電報線還沒斷。"],"defeated":["本相一生為帝國盤算，這一局，是本相算錯了。","歐洲的棋盤少了一個棋手，希望你下得比本相好。"],"victory":["結果和本相計算的一樣，帝國不需要意外。","棋局結束，你輸在看不清局勢，不在兵力。"],"allyAccept":["同盟可以簽，本相會讓條款對雙方都有好處。","很好，本相一向相信盟友比敵人省事得多。"],"allyReject":["帝國的盟約簽得夠多了，本相不想再多養一個負擔。","你的位置在棋盤上不夠關鍵，本相暫時不需要你。"],"greetFriendly":["來信收到，柏林的大門為誠實的談判者敞開。","本相樂於交友，前提是雙方的利益一致。"],"greetCold":["外交辭令本相聽得夠多了，說說你要什麼。","問候不值一枚馬克，本相只看你的行動。"],"threatDefy":["本相以鐵與血統一德意志，你的威嚇太輕了。","奧地利和法國都曾輕視普魯士，結果你很清楚。"],"threatYield":["現實政治教我認清局勢，此刻退讓是上策。","本相不打沒有把握的仗，這次先讓你一步。"],"tributePay":["{gold}黃金付你，這是買時間的錢，本相心裡有數。","帝國付出{gold}黃金，換取一紙不交戰的保證。"],"tributeRefuse":["德意志帝國不向任何人納貢，本相說了算。","要金子？帝國議會不會批准，本相也不會。"],"giftThanks":["禮物收下了，本相欣賞懂得投資的君主。","多謝，一份禮物勝過十封空洞的外交照會。"],"intel":["帝國正與{wars}交戰，與{peace}訂有和約，僅此而已。","本相的棋盤上，{wars}是對手，{peace}暫時是夥伴。"]}}],"cn":[{"name":"秦始皇 嬴政","title":"秦朝皇帝","era":"前 221–前 210 年在位","tone":"威嚴冷峻、法家口吻，以一統天下為傲，視天下為己有","portrait":"cn-historical-age0","lines":{"intro":["六國既滅，四海為一。朕乃始皇帝，爾等小邦何足道哉。","朕掃平六國，一統天下。爾若識時務，便早早稱臣。"],"contact":["咸陽城牆高聳，馳道直通四方，爾等可曾見過如此氣象？","此乃大秦都城咸陽，法令森嚴，外人不得妄動。"],"war":["六國已滅，爾亦難逃。大秦鐵騎即刻出征。","朕欲書同文、車同軌，爾國豈可自外於天下？出兵！"],"warReply":["區區小國竟敢挑釁大秦？蒙恬何在，替朕教訓此人。","六國聯軍尚且敗於朕手，爾一國之力，能奈朕何？"],"peace":["北有匈奴未平，朕暫無暇顧爾。且休兵，各守疆界。","長城尚未築成，朕願與爾暫止干戈，各自經營。"],"accept":["好，朕准了。然法令如山，爾若毀約，必受重懲。","既然爾有誠意，朕便應允。天下事，暫且如此。"],"reject":["朕志在一統，豈容天下有第二個君王？休想停戰。","當年六國也曾求和，結果如何？朕不會再聽這種話。"],"rebuff":["爾竟拒絕朕的好意？也罷，秦法無情，後果自負。","朕難得開口言和，爾卻不識抬舉。且看爾能撐多久。"],"betray":["朕說過，天下只能有一個皇帝。停戰到此為止。","北疆已定，長城已成，朕的大軍如今無後顧之憂。"],"truceEnd":["休戰之期已滿。天下大勢，自今日起由朕來定。","刀兵可以出鞘了。爾等好自為之，莫怪朕不留情面。"],"attacking":["大秦鐵騎已出函谷關，爾的城池，朕勢在必得。","朕親率大軍前來，爾若開城歸降，朕可饒爾一回。"],"attacked":["咸陽竟被兵臨城下？朕統一天下，豈能敗於此地！","城牆將傾……不，朕是始皇帝，秦當傳至萬世！"],"defeated":["朕本欲傳之萬世……大秦，竟止於朕一人之手。","六國之仇，今日償還了。天下……終究非朕一人所有。"],"victory":["六國既滅，四海為一。今日之後，天下再無他國。","書同文，車同軌，爾的土地自此併入大秦郡縣。"],"allyAccept":["朕破例與爾結盟。記住，秦的盟約不可輕忽。","遠交近攻，本是秦策。既如此，朕便與爾聯手。"],"allyReject":["朕從不與人共享天下。結盟？免談。","大秦自有蒙恬、王翦，何須外人相助？"],"greetFriendly":["書已閱畢。四海之內皆有法度，願與君共守此約。","君之問候，朕受之。同軌同文，天下方能長治久安。"],"greetCold":["書已閱。朕以法治天下，情誼之言，不必多說。","六國之君，也曾如此致意。朕只信賞罰，不信空言。"],"threatDefy":["黑甲之師，橫掃六國。君要試朕的兵鋒嗎？","恫嚇之語，朕幼年在邯鄲時就聽夠了。朕在此恭候。"],"threatYield":["君之兵勢，朕已知曉。暫且罷兵，各守疆界。","秦尚未修好長城，此時不宜與君相爭，朕退一步。"],"tributePay":["此番就依君所言，黃金{gold}，秦府庫自會送去。","{gold}金，朕暫予之。待秦法大成，此事來日再議。"],"tributeRefuse":["秦之金帛，只賞有功之臣，不予無功之人。","索貢？六國獻地求和之時，朕尚且不允，何況今日。"],"giftThanks":["君之厚禮，朕收下了。依秦法，有功必賞，君之情誼朕記著。","禮物已入咸陽宮。朕不常受人之惠，此番算是例外。"],"intel":["朕正與{wars}交兵，與{peace}罷兵休戰，此事不必隱瞞。","秦軍所向：{wars}。已訂盟約者：{peace}。君問此事，意欲何為？"]}},{"name":"唐太宗 李世民","title":"唐朝皇帝","era":"626–649 年在位","tone":"雄才大略卻寬仁納諫，以民為本，先禮後兵","portrait":"cn-historical-age1","lines":{"intro":["朕乃大唐天子，四方尊為天可汗。爾若來歸，朕以禮相待。","貞觀之世，四海昇平。閣下遠來，是為友，還是為敵？"],"contact":["長安城百業興盛，各國商旅雲集，此乃大唐氣象。","爾的使者既到長安，便當知大唐之富庶與寬仁。"],"war":["朕以仁待人，然爾屢犯邊境，大唐不得不出兵了。","頡利可汗尚且敗於李靖之手，爾何足懼？大唐出兵！"],"warReply":["爾竟向大唐宣戰？朕本不願用兵，既如此，便應戰。","突厥、吐谷渾皆已臣服，爾之挑釁，朕自當回應。"],"peace":["兵者凶器，聖人不得已而用之。朕願與爾罷兵休戰。","百姓方安，朕不欲再興戰事。爾若願意，兩國息兵吧。"],"accept":["善。朕素以和為貴，自今日起，兩國互不相犯。","爾有此心，朕甚欣慰。願天下少一分兵戈。"],"reject":["爾言和之時，兵馬卻未退，朕如何信爾？此議不允。","朕納諫如流，卻不受人蒙蔽。停戰之議，暫且擱下。"],"rebuff":["爾拒絕了朕的好意，可惜。那便沙場上見真章吧。","朕已仁至義盡。爾既不願休戰，大唐奉陪到底。"],"betray":["朕本欲守約，然爾暗中屯兵邊境，大唐不能坐視。","停戰已無意義，朕決意再度興兵，望爾莫怪。"],"truceEnd":["休戰之期已至。朕不主動生事，但也絕不畏戰。","各國兵馬皆已就緒。天下之勢，就看誰更得民心了。"],"attacking":["李靖已率大軍出發。爾若及早歸降，朕必善待爾民。","唐軍此去，只為止戰，不為劫掠。爾好自為之。"],"attacked":["長安危急？朕曾平定天下，今日豈能失於此城！","水能載舟，亦能覆舟。莫非朕已失了民心？"],"defeated":["以史為鏡，可知興替。朕的貞觀，也到了盡頭。","願爾善待大唐百姓。這是朕最後的請求。"],"victory":["天下歸唐，四海一家。爾的子民，朕自會善待。","貞觀仁政，今日終及於爾土。放下兵器，共享太平吧。"],"allyAccept":["大唐願與爾結為兄弟之邦，互通有無，共禦外敵。","善。朕以誠待人，望爾亦以誠相報。"],"allyReject":["結盟之事，朕與群臣商議後，認為時機未到。","魏徵勸朕勿輕許盟約。爾之誠意，朕仍需觀察。"],"greetFriendly":["遠方來書，如見故人。四海一家，願與君共享太平。","君之問候，朕欣然受之。天下初定，正需四方友邦。"],"greetCold":["來書朕已讀過。以史為鏡，朕不敢輕信一紙客套。","君既有意修好，何以邊境仍有兵馬？朕且觀後效。"],"threatDefy":["朕十八歲從軍，虎牢一戰擒兩王。君的威嚇，朕見多了。","突厥兵臨渭水時，朕親往退之。君若來犯，唐軍必迎。"],"threatYield":["民力未復，朕不願百姓再受刀兵。此番依君，暫且罷手。","君勢正盛，朕以百姓為重，願先退讓，換得數年安寧。"],"tributePay":["為免生靈塗炭，朕願出黃金{gold}，換兩國無事。","黃金{gold}，長安即刻備妥。朕寧損府庫，不損百姓。"],"tributeRefuse":["大唐府庫，取之於民，怎可輕予他人？","朕曾言：水能載舟，亦能覆舟。此金若給了君，百姓如何看朕？"],"giftThanks":["君之厚禮已至長安，朕甚感念。來而不往非禮也。","此禮朕收下了。魏徵若見，恐怕又要勸朕勿貪外物。"],"intel":["朕不瞞君：大唐正與{wars}交戰，與{peace}已息干戈。","兼聽則明。如今與朕為敵者：{wars}；已修好者：{peace}。"]}},{"name":"明太祖 朱元璋","title":"明朝皇帝","era":"1368–1398 年在位","tone":"布衣天子、直白務實又多疑，護百姓卻嚴厲不留情","portrait":"cn-historical-age2","lines":{"intro":["朕本淮右布衣，起於草莽，今為天下之主。爾是何人？","朕推翻元朝，恢復中華。爾若安分守己，朕不為難。"],"contact":["應天府城牆高厚，乃朕高築牆、廣積糧所成。","此城守衛森嚴，爾的人在城外看看便好，莫要靠近。"],"war":["朕平陳友諒、滅張士誠，何懼爾一國？徐達，出兵！","爾屢屢擾朕邊民，朕忍無可忍。大明鐵騎，即刻出征。"],"warReply":["爾竟敢向大明宣戰？朕從一介布衣打下江山，不怕爾。","好，朕正愁沒有藉口。徐達、常遇春，隨朕迎敵！"],"peace":["百姓剛從戰亂中喘息，朕不願再動干戈。且休兵吧。","朕要百姓種田納糧，不要他們打仗。爾我暫且停戰。"],"accept":["好，朕答應。但朕最恨背信之人，爾莫要試探朕。","既然爾有誠意，朕便收兵。各安其土，各養其民。"],"reject":["爾嘴上求和，暗地裡卻在整軍，當朕看不出來？不准。","朕多疑，這天下人皆知。爾的和議，朕信不過。"],"rebuff":["朕難得好言相勸，爾卻不領情。好，那就打到底。","不識抬舉！朕從乞食僧到皇帝，什麼硬仗沒打過？"],"betray":["朕查得爾私通朕的臣子，此等停戰，不要也罷！","停戰之約，朕撕了。天下事，終究得靠刀劍說話。"],"truceEnd":["休戰結束了。朕的糧倉已滿，兵馬已足，不怕誰來。","高築牆、廣積糧的日子過去了，如今該爭天下了。"],"attacking":["大明之師已出應天。爾若識相，早早開城，免傷百姓。","徐達領兵，朕親自督戰。爾的城池，守不了幾日。"],"attacked":["應天告急？朕在鄱陽湖險些喪命都撐過來了，不會怕。","城牆築得再高，也擋不住爾嗎……眾將士，隨朕守城！"],"defeated":["朕從布衣起兵，如今又歸於塵土。天命，原來如此。","朕只求爾一事：讓百姓有田可種，有飯可吃。"],"victory":["推翻元朝，恢復中華，今日大明終於一統天下。","朕從一個牧童走到今日，爾輸給朕，不算冤枉。"],"allyAccept":["好，朕與爾結盟。但朕醜話說在前頭，背盟者，朕必追究。","爾既有誠意，朕便信爾一回。兩國互市，共保太平。"],"allyReject":["朕連丞相都廢了，還會把國事交給外人？免了。","結盟？朕信不過爾。大明自有徐達、湯和，不需外援。"],"greetFriendly":["朕本淮右布衣，不講虛禮。你既真心來問，朕也真心回。","書信收到了。天下太平最要緊，你我兩家和氣，百姓才有飯吃。"],"greetCold":["話說得好聽，朕見多了。是真心是假意，看你日後怎麼做。","朕從乞食走到皇位，人心看得清楚。這封信，朕先放著。"],"threatDefy":["朕當年連元朝大軍都不怕，還怕你幾句狠話？","鄱陽湖上陳友諒六十萬大軍都敗了，你再想想吧。"],"threatYield":["朕不跟你硬碰。天下剛安定，百姓經不起再打。","好，這回算你狠。朕先退一步，田裡的莊稼還等著收。"],"tributePay":["黃金{gold}，朕給。但這是百姓的血汗，你別揮霍了。","{gold}金送去。朕出身貧苦，最知道這些錢多難賺。"],"tributeRefuse":["要金子？朕每一文都是給百姓修水利的，一文也不給。","朕治貪官都治不完了，還要把國庫送給你？想都別想。"],"giftThanks":["東西收到了，朕看了很歡喜。你有心，朕記在心裡。","這禮不輕，朕謝過了。當年放牛時，可沒人送朕東西。"],"intel":["朕實話實說：正跟{wars}打，跟{peace}講和了。","打仗的是{wars}，不打的是{peace}。你打聽這個，是在打什麼主意？"]}},{"name":"康熙帝 玄燁","title":"清朝皇帝","era":"1661–1722 年在位","tone":"博學勤政、沉穩寬仁，以文治為傲，先禮後兵","portrait":"cn-historical-age3","lines":{"intro":["朕乃大清天子。滿漢一體，四海皆朕子民，爾何來？","朕八歲登基，親政以來平三藩、定臺海。閣下有何指教？"],"contact":["紫禁城巍峨，八旗駐守四門。爾的人可看清楚了？","京城之內，觀象臺有西洋儀器，朕正學習測算天象。"],"war":["朕三次親征噶爾丹，不畏遠征。今日，輪到爾了。","羅剎犯邊，朕尚且以兵驅之。爾之挑釁，朕豈能容？"],"warReply":["爾向大清宣戰？三藩之亂朕尚能平定，何況爾一國。","朕本欲以文治天下，爾既動兵，朕便以八旗相迎。"],"peace":["尼布楚之約可與羅剎立，與爾亦可。兩國劃界，各守其疆。","連年用兵，百姓困苦。朕願與爾罷兵，休養生息。"],"accept":["好。朕以誠信立國，既然約定，大清必守。","爾能明白止戰之理，甚好。願兩國從此各享太平。"],"reject":["吳三桂當年也曾請和，朕不曾答應。爾亦如此。","爾邊境兵馬未撤，此時言和，朕難以相信。"],"rebuff":["爾拒絕了朕的好意，也罷。大清從不強人所難，戰場上見。","朕已給爾機會。既然爾執意如此，朕便不再多言。"],"betray":["朕本以誠相待，然爾暗中結黨對付大清，約定作廢。","撤藩之時朕便學到：有些禍患，不能留到明日。出兵。"],"truceEnd":["休戰之期已滿。朕已備妥糧草，不懼任何挑戰。","天下棋局已開。朕讀過歷代興亡，知道該怎麼走。"],"attacking":["八旗與綠營已出京師。爾若開城歸順，朕保爾百姓無恙。","朕親征噶爾丹尚且不辭辛勞，此番親自督軍，爾當心了。"],"attacked":["京師危急？朕八歲登基，什麼風浪沒見過，守住！","紫禁城牆將破……朕勤政數十年，難道要敗於今日？"],"defeated":["朕一生勤學勤政，大清竟終於朕手。歷史，自會評斷。","願爾永不加賦，善待百姓。這是朕最後的囑託。"],"victory":["天下歸清，滿漢一家。爾之子民，朕視同己出。","自今日起，爾土納入大清版圖。朕以文治之，不以兵壓之。"],"allyAccept":["好，大清願與爾結盟。互通商貿，共禦外患。","朕重信義。既結盟約，大清必不負爾。"],"allyReject":["結盟之事，朕需與議政王大臣商議，此時不便應允。","朕觀爾行事，尚難放心。結盟之議，容後再說。"],"greetFriendly":["來書朕已細讀，文辭懇切。四海之內，本當以和為貴。","君之問候，朕於南書房閱畢，甚感欣慰。願兩國長久交好。"],"greetCold":["書信朕看過了。言語可以客氣，朕仍會留心君的兵馬動向。","三藩之事，朕記憶猶新。口稱修好者，未必真心，朕且看之。"],"threatDefy":["朕八歲登基，擒鰲拜、平三藩，何曾被人嚇退過？","雅克薩之役，朕連俄羅斯都敢對陣。君的威嚇，朕不放在心上。"],"threatYield":["君之兵鋒，朕已知曉。國家甫定，朕不願再開戰端，暫且退讓。","治河、漕運皆需錢糧，此時不宜與君相爭。朕退一步。"],"tributePay":["黃金{gold}，內務府自會備妥。為百姓安寧，朕暫且忍讓。","{gold}金送去。此非懼君，乃是為天下蒼生計。"],"tributeRefuse":["大清錢糧，皆用於治河賑災，朕不會拿來充人私囊。","朕永不加賦，正為愛惜民力。君之所求，恕難應允。"],"giftThanks":["君之厚禮，朕已收到，甚為感念。他日必有回贈。","此禮朕甚喜愛，已命人陳於南書房。君之情誼，朕記下了。"],"intel":["朕據實相告：大清正與{wars}交戰，與{peace}已議和。","君既相問，朕不隱瞞。用兵者：{wars}；息兵者：{peace}。"]}}],"gb":[{"name":"布狄卡","title":"愛西尼部族女王","era":"60–61 年起兵","tone":"守護族人與土地的部族女王，語氣剛烈而有尊嚴，把自由看得比王座更重。","portrait":"gb-historical-age0","lines":{"intro":["吾是愛西尼的布狄卡，這片土地由祖靈所託，不容外人踐踏。","陌生的王，橡樹林記得每一位來客，是友是敵，由你自己選。"],"contact":["你的斥候已站在吾族的田野上，愛西尼人看見了，也記住了。","這裡沒有石牆高塔，只有守著家園的族人，別小看他們。"],"war":["你們的貪婪已越過河流，愛西尼的戰車今日為自由而出。","吾不為王座而戰，只為被奪走的自由而戰。準備迎接長矛吧。"],"warReply":["你選擇了戰爭？很好，部族的長矛從不畏懼任何旗幟。","來吧，讓你的士兵見識不列顛的女人如何守護家園。"],"peace":["族人需要秋收，你的人也需要歸鄉。放下武器，各守其土如何？","吾不愛戰爭，只愛族人平安。若你願意停手，吾也願意。"],"accept":["好，祖靈為證，愛西尼人說出口的話，不會收回。","橡樹林將記下今日的誓言，願兩地的孩子都能安穩長大。"],"reject":["奪走的土地還沒歸還，吾怎能對族人說已經和平？","你的話像河上的霧，看似溫柔卻藏著刀。吾不接受。"],"rebuff":["你拒絕了？那就讓大地見證，誰才真心為子民著想。","吾伸出的手被推開了，下一次伸出的，會是長矛。"],"betray":["停戰期間你的人仍在侵佔田地，誓言已被你踏碎，吾不再忍讓。","祖靈看見了你的背信。愛西尼的戰車再度啟程，這次不回頭。"],"truceEnd":["休戰的日子結束了，族人已磨好長矛，就看你要走哪條路。","和平的時光很短，但吾記得每一天。現在，各憑本事了。"],"attacking":["戰車已駛出橡樹林，部族的號角響遍原野，吾親自領軍而來。","聽見馬蹄聲了嗎？那是愛西尼人為家園討回公道的聲音。"],"attacked":["土牆可以倒下，但愛西尼人的心不會。族人們，守住最後一寸土！","你打到吾的家門口了，可祖靈仍在，吾就仍站在這裡。"],"defeated":["吾寧可倒在自己的土地上，也不做他人的奴僕。族人，記住自由。","長矛折了，戰車停了，但這片土地永遠記得愛西尼的名字。"],"victory":["大地重歸族人，你的旗幟將從此離開這片原野。","吾為自由而戰，如今自由回來了。回去吧，別再踏上這裡。"],"allyAccept":["好，愛西尼與你的族人結為兄弟，共守這片原野與河流。","同飲一條河的水，就是一家人。吾接受這份盟約。"],"allyReject":["愛西尼人只與真心相待者結盟，你的誠意，吾還沒看見。","族人的命運不能交給陌生人。今日不結盟，但也不必為敵。"],"greetFriendly":["你的信使平安抵達，愛西尼的篝火為你而燃。","願你的部族草原豐美，我以女王之名向你問好。"],"greetCold":["羅馬人也曾說過好聽的話，我不會輕易相信。","先把你的戰車留在邊境，再談友誼也不遲。"],"threatDefy":["我連羅馬軍團都敢正面迎戰，還會怕你的恐嚇？","愛西尼的長矛已經舉起，來吧，讓戰場說話。"],"threatYield":["族人的性命比我的驕傲重要，這次我退一步。","愛西尼會暫時退回森林，但我們不會忘記今日。"],"tributePay":["這{gold}黃金是族人的積蓄，拿去，別再逼近了。","為了部族安寧，我交出{gold}黃金，但不交出尊嚴。"],"tributeRefuse":["羅馬人搶走我們的一切，你以為我還會乖乖奉上？","愛西尼的黃金只留給族人，一塊也不會給你。"],"giftThanks":["你的禮物我收下了，愛西尼人會記得這份情。","族人們圍著篝火傳看你的禮物，謝謝你的心意。"],"intel":["我正與{wars}交戰，與{peace}暫時休兵，這是實話。","愛西尼的長矛指向{wars}，與{peace}之間已無戰事。"]}},{"name":"獅心王 理查一世","title":"英格蘭國王","era":"1189–1199 年在位","tone":"好戰直率的騎士國王，把榮譽與戰場看得比王宮更重，語氣豪邁帶著獅子的傲氣。","portrait":"gb-historical-age1","lines":{"intro":["本王是理查，人稱獅心。與其在王宮枯坐，本王更愛馬背與戰場。","見到獅子紋章了嗎？記住它，戰場上你會再見到它。"],"contact":["你的人到了本王城下？看仔細些，這裡每塊石頭都準備好打仗。","城牆上的獅子旗迎風招展，那是英格蘭的驕傲，別靠太近。"],"war":["本王的長劍生鏽太久了，今日對你宣戰，正好磨一磨。","上帝與吾之權利！騎士們，上馬，隨本王出征！"],"warReply":["你向獅子宣戰？好膽量。本王就喜歡不怕死的對手。","正合本王心意。備馬，讓對方看看十字軍的鎖子甲有多硬。"],"peace":["打了這麼久，你的勇氣本王看見了。不如暫且收兵，各自養精蓄銳。","本王在聖地也曾與敵手握手言和，今日對你亦然，停戰吧。"],"accept":["成交！騎士一諾千金，本王的劍在停戰期間不會出鞘。","好，本王答應。值得尊敬的對手，比朝廷裡的臣子有趣多了。"],"reject":["現在談和？獅子還沒吼夠，本王的騎士也還沒盡興。","本王從不在佔上風時放下劍，等你贏一場再來說。"],"rebuff":["拒絕了？也好，本王本來就更擅長用劍說話。","你不要和平，那就要戰爭。獅心王向來給人他要的東西。"],"betray":["你在停戰期間招兵買馬，本王看在眼裡。誓約作廢，開戰！","和平的日子讓劍鏽了，而你先背了誓。本王撕毀盟約，披甲上馬！"],"truceEnd":["休戰期滿了，總算能痛快打一場。騎士們，把馬牽來！","等這一天等得本王骨頭發癢。現在，讓刀劍決定一切。"],"attacking":["獅子的旗幟已越過邊境，本王親自衝在最前面，迎戰吧！","本王從不躲在後方指揮，這次也一樣。看見那面獅旗了嗎？"],"attacked":["城牆破了又如何？獅子受傷時更兇猛，本王仍握著劍。","本王曾在異鄉被囚仍不低頭，這座城，也不會輕易交出。"],"defeated":["劍已斷，馬已倒，但本王是站著倒下的。這就是獅心。","本王一生都在戰場，能終於戰場，也算不辱獅子之名。"],"victory":["勝負已分。你打得不錯，本王記住你的名字了，退下吧。","獅子吼過了，戰場歸於寂靜。這場勝利，獻給英格蘭。"],"allyAccept":["好，並肩作戰的兄弟！下次出征，你的旗幟就在本王身旁。","本王欣賞勇者。從今起，獅子與你同進退，這是騎士的誓言。"],"allyReject":["結盟？本王的劍不需要別人的手來扶，自己打就夠了。","獅子不與羊群結伴。等你證明自己是頭獅子，再來談。"],"greetFriendly":["本王向你舉杯致意，願你的騎士個個英勇。","來信收到了，若你願意，隨時來本王營帳比武同樂。"],"greetCold":["本王沒空與人寒暄，有話直說，是戰是和？","客套話留給文官吧，本王只看你的劍指向何方。"],"threatDefy":["本王曾在聖地與薩拉丁對陣，豈會怕你這封信？","威脅獅心王？把你的軍隊帶來，本王親自迎戰。"],"threatYield":["本王的騎士尚未整備，這一回，暫且依你所言。","英格蘭需要喘息，本王暫時收劍，你別得意太早。"],"tributePay":["{gold}黃金拿去，本王寧可花錢，也不願讓騎士白白犧牲。","本王付你{gold}黃金換取時間，等軍隊整備完畢再說。"],"tributeRefuse":["英格蘭的黃金是用來打造盔甲的，不是用來送人的。","想要貢品？先在戰場上勝過本王的長槍再說。"],"giftThanks":["好禮物！本王要把它掛在王旗旁邊，向騎士炫耀。","本王收下了，這份心意值得一場盛宴來慶祝。"],"intel":["本王的長槍正對著{wars}，與{peace}已有停戰之約。","與{wars}的戰事還沒完，{peace}嘛，暫時不必提防。"]}},{"name":"伊莉莎白一世","title":"英格蘭女王","era":"1558–1603 年在位","tone":"機敏優雅、綿裡藏針的女王，字字得體卻句句有算計，以英格蘭為夫、以海洋為疆。","portrait":"gb-historical-age2","lines":{"intro":["朕是伊莉莎白，英格蘭的女王。朕已嫁給這個國家，無暇他顧。","歡迎來到朕的宮廷。朕看得多、說得少，你的心思，朕都明白。"],"contact":["你的使者已望見倫敦塔了？請轉告他，朕的海軍比城牆更高。","泰晤士河邊的城，是靠智慧而非高牆守住的。看清楚再走。"],"war":["朕給過你機會。如今英格蘭的艦隊揚帆，這是朕的答覆。","朕雖是女子之身，卻有國王的心與膽。宣戰吧，朕不會退。"],"warReply":["你向英格蘭宣戰？朕收下了。海上的風，一向站在朕這邊。","很好，朕正想看看你的船能不能越過海峽。德瑞克，出航。"],"peace":["戰爭耗盡國庫，也耗盡民心。朕提議停戰，貿易勝過砲火。","聰明的君主知道何時收劍。朕願暫且和談，你呢？"],"accept":["朕接受。英格蘭的信用如同金幣，落地有聲，絕不摻假。","好，朕以女王之名應允。願兩國的商船從此比戰船更多。"],"reject":["和談？你的條件像戴著珠寶的空盒子，好看而已。朕不要。","朕看得見你藏在笑容後的算計。這份和約，朕暫不簽。"],"rebuff":["你拒絕了朕的好意？無妨，朕向來擅長等待，也擅長記帳。","可惜。朕伸出的是橄欖枝，你卻當成了荊棘。"],"betray":["停戰期間你暗中結黨，朕的耳目一清二楚。和約作廢，開戰。","朕說過朕看得多、說得少。現在，朕要開口了：戰爭。"],"truceEnd":["休戰期已盡，棋局重開。朕的每一步，都已算好了。","和平的帷幕落下了。接下來，讓英格蘭的艦隊替朕說話。"],"attacking":["朕的艦隊已出港，風帆遮天。這不是威嚇，是通知。","英格蘭的大軍已在路上。朕親自到岸邊送行，他們不會空手回來。"],"attacked":["城門將破，朕仍戴著王冠。英格蘭的女王，從不躲在後方。","你打到宮門前了？朕就站在這裡，看看你敢不敢再進一步。"],"defeated":["朕的一生都獻給了英格蘭，如今無愧於她。王冠，朕親手放下。","潮水終有退去之時。記住，英格蘭曾有一位女王，未曾低頭。"],"victory":["勝負已定。回去告訴你的人民，英格蘭的女王，從不虛言。","風把你的艦隊吹散了，正如朕所料。海洋，是英格蘭的。"],"allyAccept":["朕接受結盟。你的船與朕的船並行，海上便無人能敵。","好，英格蘭與你攜手。朕的宮廷向你敞開，但秘密除外。"],"allyReject":["結盟？朕連求婚者都一一婉拒了，何況是你。","朕不輕易許諾。英格蘭的盟友很少，正因如此才珍貴。"],"greetFriendly":["朕讀了你的信，文筆不錯，宮廷正好缺個談話的對象。","難得有人真心問候，朕欣然接受，願你一帆風順。"],"greetCold":["甜言蜜語朕聽得多了，你的真正目的是什麼？","朕會記下你的問候，至於信不信，那是另一回事。"],"threatDefy":["西班牙的艦隊都嚇不倒朕，你這幾行字算什麼？","朕雖是女子，卻有國王的心胸與膽識，儘管放馬過來。"],"threatYield":["朕的國庫尚需休養，這次就順你的意，下不為例。","聰明的君主懂得何時彎腰，朕暫且退讓，記住是暫且。"],"tributePay":["{gold}黃金送你，就當是朕買下一段安寧的時光。","朕付出{gold}黃金，可不是怕你，只是眼下開戰不划算。"],"tributeRefuse":["朕的黃金留著造船，一枚也不會落入你的口袋。","向英格蘭女王索取貢品？你的膽子比你的國家還大。"],"giftThanks":["這份禮物頗合朕的品味，宮廷上下都會知道你的名字。","朕收下了，懂得送禮的人，往往也懂得談判。"],"intel":["朕與{wars}正在交鋒，與{peace}則已握手言和。","朕只透露一點：敵人是{wars}，朋友是{peace}。"]}},{"name":"維多利亞女王","title":"大英帝國女王","era":"1837–1901 年在位","tone":"端莊克制、不怒自威的帝國女王，字句簡短而有分量，以體面與秩序衡量一切。","portrait":"gb-historical-age3","lines":{"intro":["朕是維多利亞，日不落帝國的女王。願我們的往來，體面而有序。","朕的鐵路通向四方，朕的海軍守著七海。你，站在哪一邊？"],"contact":["你的人看見倫敦的煙囪了？那是工廠在運轉，也是帝國在呼吸。","請你的使節守規矩。朕的城市秩序井然，不容喧嘩。"],"war":["朕不喜歡戰爭，但更不喜歡無禮。帝國的艦隊，將替朕教你分寸。","朕的耐心已盡。首相已呈上文書，大英帝國正式對你宣戰。"],"warReply":["你竟向帝國宣戰？朕並不覺得有趣。海軍部，準備出航。","很好，這正好讓世界再次看見，太陽為何不落在帝國的旗上。"],"peace":["戰爭使商路中斷，朕的臣民不樂見。停戰吧，讓貿易重新流動。","朕願意談。體面的和平，比無止境的砲火更配得上兩個國家。"],"accept":["朕批准。條約將以帝國之名蓋印，朕的簽名從不作廢。","很好。願兩國的火車與商船，從此比軍隊更常來往。"],"reject":["朕讀過你的條件了。不，這樣的條件配不上帝國的體面。","和平需要誠意，你的提案裡朕沒有看見。請回去重擬。"],"rebuff":["你拒絕了？朕記下了。帝國的記性，向來很好。","朕以禮相待，你卻置之不理。那麼，就按帝國的方式來。"],"betray":["你在停戰期間騷擾帝國的商路，條約已無意義。朕宣布重啟戰事。","帝國的容忍有其界限，而你已越過。和約作廢，艦隊出港。"],"truceEnd":["休戰期結束了。朕已將此事交給海軍部，接下來由他們回答你。","和平的鐘聲停了。帝國的蒸汽船已升火，就等朕一聲令下。"],"attacking":["帝國的艦隊已駛出港口，鐵甲與蒸汽，將把朕的意志送到你門前。","朕的軍隊已出發。他們紀律嚴明，不會遲到。"],"attacked":["宮牆在震動，但朕不會摘下王冠。帝國的女王，坐著也能守城。","你打到白金漢宮門前了？朕仍在此。這身黑衣，不是為你而穿。"],"defeated":["太陽終究落下了。朕的帝國曾遍及四海，這一點，歷史不會忘。","帝國有起有落，朕已盡了女王的本分。請保持體面，朕也會。"],"victory":["戰事已了。帝國的旗幟將在你的城上升起，日不落，如往常。","朕並不以戰勝為樂，但秩序必須恢復。現在，它恢復了。"],"allyAccept":["朕同意結盟。帝國的商船與你的港口，從此互相敞開。","很好。朕的家族與歐洲各國王室皆有姻親，如今又多一位朋友。"],"allyReject":["結盟？帝國不需要盟友來證明強大。朕的答覆是：不。","朕欣賞你的誠意，但帝國的門檻很高。此事，容後再議。"],"greetFriendly":["朕收到你的電報了，大英帝國樂於與你保持友好。","你的問候很得體，朕會請人在白金漢宮備茶等你。"],"greetCold":["朕不覺得有趣。你的來信客氣，但意圖不明。","帝國的友誼不是一封信就能換來的，朕會觀察你。"],"threatDefy":["皇家海軍的軍艦遍布七海，你打算從哪裡威脅朕？","日不落帝國不接受恐嚇，這封信朕就當作沒看見。"],"threatYield":["帝國的疆域太廣，朕不便在此時開闢新的戰線。","朕以帝國的莊重接受你的條件，這並非懼怕，而是審慎。"],"tributePay":["國庫撥出{gold}黃金，這只是帝國財富的一小部分。","朕批准支付{gold}黃金，願這筆錢換來邊境的平靜。"],"tributeRefuse":["向大英帝國索取貢品？朕的財政大臣聽了都會發笑。","帝國的黃金要修鐵路、造軍艦，沒有一枚是多餘的。"],"giftThanks":["朕很滿意，這份禮物會陳列在王宮，以表敬意。","你的禮物讓朕想起亞伯特親王的用心，謝謝你。"],"intel":["帝國正與{wars}處於戰爭狀態，與{peace}維持和平。","電報顯示：{wars}是朕的敵人，{peace}已簽訂和約。"]}}],"in":[{"name":"阿育王","title":"孔雀王朝君主","era":"前 268–前 232 年在位","tone":"歷經羯陵伽之痛後以法治國的悔悟君王，語氣沉靜莊重，寧以法勝而非武勝。","portrait":"in-historical-age0","lines":{"intro":["朕乃天所親愛的喜見王阿育。願以法相待，不以刀兵。","孔雀王朝的石柱立於四方，願閣下也讀一讀朕的法敕。"],"contact":["你的人已見過華氏城了？城裡刻的不是戰功，是法。","那些石柱與象群並非炫耀，是提醒朕莫再重蹈羯陵伽。"],"war":["朕曾誓言不再興兵，然你威脅萬民安寧，朕不得不為。","為護百姓，孔雀的大軍將再度出征，朕心無喜悅。"],"warReply":["你選擇了刀兵。朕會應戰，但戰後仍願與你談法。","羯陵伽的教訓朕未曾忘，但朕的象兵也未曾老去。"],"peace":["刀兵所得，不及法勝之萬一。願與閣下止戰。","朕在羯陵伽見過十萬人的悲苦，不願再見。停戰吧。"],"accept":["善哉。放下刀劍的那一刻，你我皆得法之利益。","朕接受。願兩國邊界從此只往來商旅與僧侶。"],"reject":["朕愛好和平，卻不能在你兵臨城下時輕信諾言。","你的和議來得太急。先退兵，再談法與和平。"],"rebuff":["你拒絕了和平。朕不怒，只為兩國百姓感到惋惜。","無妨，法的種子未必今日發芽。朕會再提。"],"betray":["朕曾立誓守和，然你暗中屯兵邊境，誓約已被你毀。","法敕教朕寬容，卻不教朕縱容。孔雀再度出征。"],"truceEnd":["休戰之期已盡。朕仍願以法相交，但不懼刀兵。","和平的日子過去了。閣下欲取法，或取刀？"],"attacking":["象兵已渡河。朕不以此為榮，只求速戰速決。","孔雀的旗幟正朝你而來。願此戰是最後一戰。"],"attacked":["華氏城牆已裂。朕曾讓他人嘗此苦，今日輪到朕了。","城可破，法不可破。朕的石柱仍會站在原地。"],"defeated":["孔雀王朝到此為止。願法比朕活得更久遠。","朕輸了土地，但那些刻在石上的話，你抹不去。"],"victory":["戰事結束了。朕不慶功，只在你的城中立一根石柱。","你敗了，但朕不會奴役你的百姓。這是法的勝利。"],"allyAccept":["朕的使者曾遠赴諸國傳法，今日又多一位友邦。","善。願你我之邦如恆河與其支流，同流而不相爭。"],"allyReject":["朕不與好戰之人結盟。待你放下刀劍，再來談吧。","結盟為的是護民，不是征伐。朕暫且婉拒。"],"greetFriendly":["願正法護佑貴國，朕已命人為使者備好香花與藥草。","羯陵伽之後，朕最珍視的便是鄰邦的善意，請坐。"],"greetCold":["朕不再以刀劍論交，但也記得，笑臉之下常藏著兵鋒。","來信朕已讀過。正法教人寬厚，卻不教人輕信。"],"threatDefy":["朕放下屠刀，是因為悔悟，不是因為畏懼，休要誤會。","孔雀王朝的軍隊仍在，只是朕選擇不先拔劍罷了。"],"threatYield":["朕已見過太多苦難，若退讓能免一場戰禍，朕願意。","就依你所言。百姓的安寧，比君王的顏面更重要。"],"tributePay":["黃金{gold}已備妥，只求你善待邊境的百姓。","朕以{gold}黃金換取和平，願這筆錢不是用來買刀劍。"],"tributeRefuse":["朕的金庫用來鑿井、種樹、施藥，不是用來餵養貪念。","正法之君不向人納貢。你若想要黃金，不妨也學著布施。"],"giftThanks":["多謝厚禮。朕會將它分給僧團與病者，這才不負你的心意。","你的禮物朕收下了，回贈一株菩提樹苗，願兩國同享蔭涼。"],"intel":["朕與{wars}仍有兵戈，與{peace}已立誓和睦，石柱上刻得清楚。","如今{wars}與朕為敵，{peace}與朕交好，朕的使者都能作證。"]}},{"name":"戒日王 曷利沙","title":"戒日王朝君主","era":"606–647 年在位","tone":"文武兼備的詩人君王，慷慨好客、崇佛尚學，語氣風雅自信，兼有征伐北印的豪氣。","portrait":"in-historical-age1","lines":{"intro":["本王曷利沙，統領五印度之北。閣下是來論詩，還是論戰？","曲女城的大門為賓客而開，也為敵人而閉。你是哪一種？"],"contact":["你的人到了曲女城？恆河邊的寺院與學堂，可不是擺設。","遠方來的僧人都說本王的城好客，願你的人也這麼覺得。"],"war":["本王曾為兄長之仇揮兵北印，今日為國之尊嚴向你宣戰。","筆可寫詩，也可寫戰書。本王的象軍已列陣待發。"],"warReply":["你向本王宣戰？好，戰場上見，本王會記下這一頁。","北印五國皆曾與本王交鋒，如今又添一個。來吧。"],"peace":["戰事擾了學堂的讀書聲。本王提議止戰，你意下如何？","五年一度的無遮大會將至，本王不願在此時動刀兵。"],"accept":["好，本王允了。今晚曲女城設宴，為兩國的和平添一首詩。","和平比勝利更難得。本王欣然接受。"],"reject":["你的和議來得太遲，戰鼓已響，本王不能半途收兵。","本王好客，但不天真。此時談和，恕難答應。"],"rebuff":["你拒絕了？可惜。本王的宴席與和議，不會永遠敞開。","也罷。詩人懂得等待，君王更懂。"],"betray":["本王本欲以禮相待，你卻在邊境築壘。和約作廢，開戰。","你當本王只會吟詩？和約已碎，象軍再出。"],"truceEnd":["休戰結束了。本王手中，此刻既有詩卷，也有長劍。","安穩的日子過去了，閣下要做本王的賓客，還是對手？"],"attacking":["本王親率象軍出征，曲女城的旗幟正朝你而去。","大軍已渡恆河。本王曾以此統一北印，今日再走一遭。"],"attacked":["曲女城危急了。學堂裡的經卷，請莫要毀去。","本王的城牆快撐不住了，但本王的筆還握在手裡。"],"defeated":["戒日王朝到此落幕。願後人記得本王的詩，多過本王的戰。","本王輸了。請善待曲女城的僧人與學子。"],"victory":["勝負已分。本王不取你的性命，只取這一頁史詩。","你敗了。本王將在大會上把財物散給百姓，包括你的。"],"allyAccept":["好！本王與你結盟。曲女城的大門，從此為你常開。","盟約已定。本王會為此寫一齣新戲，讓全城傳唱。"],"allyReject":["本王的盟友須知禮尚學。閣下，恕本王暫不結盟。","結盟之事，本王另有考量。今日就先當賓客吧。"],"greetFriendly":["遠方的君主，本王在曲女城備下齋飯與詩會，隨時恭候。","能與好學之人通信，是一樁樂事，本王的新劇本正想找人賞讀。"],"greetCold":["本王待客向來慷慨，但慷慨並非輕信，閣下請講。","來信收到了。本王先讀讀你的文字，再決定要不要讀你的人。"],"threatDefy":["本王年少便跨上戰象平定五印度，不會被幾句話嚇倒。","崇佛不等於軟弱。恆河兩岸的軍旅，隨時聽本王號令。"],"threatYield":["本王讀過太多戰禍的詩篇，不願再添一首，暫且依你。","好吧，本王退讓。願佛陀記得，是誰先舉起了刀。"],"tributePay":["{gold}黃金已裝箱，本王五年一度大布施，就當提前施予你。","本王送上{gold}黃金，願你收下後，也學會把財富分給窮人。"],"tributeRefuse":["本王的財寶只施予僧侶與貧者，不施予手持刀劍的人。","你若真缺黃金，來曲女城赴會，本王自會布施，不必索討。"],"giftThanks":["厚禮收下了，本王回贈一卷親筆詩劇，望你讀來有滋味。","多謝盛情。本王會將此禮供奉那爛陀寺，為兩國祈福。"],"intel":["本王正與{wars}兵戎相見，與{peace}互遣使節，這些不必隱瞞。","說與你聽無妨：{wars}是本王的對手，{peace}則是座上賓。"]}},{"name":"阿克巴","title":"蒙兀兒皇帝","era":"1556–1605 年在位","tone":"兼容並蓄的蒙兀兒大帝，語氣寬宏而自信，好辯論、重人才，戰場上亦果決不猶疑。","portrait":"in-historical-age2","lines":{"intro":["朕是阿克巴，蒙兀兒之主。宮中容得下各種信仰，也容得下你。","朕的辯論廳歡迎智者。閣下若只帶了刀，請留在門外。"],"contact":["你的人見到法泰普爾西克里了？那是朕以紅砂岩築的新都。","城裡有清真寺，也有印度教的廟。朕的臣民各拜各的神。"],"war":["朕給過你和平的機會。如今蒙兀兒的火砲與象軍將為朕開路。","朕十三歲登基，戰場是朕的第二個宮廷。向你宣戰。"],"warReply":["你向蒙兀兒宣戰？勇氣可嘉。朕會親自到陣前看看你。","很好。朕的將領正嫌太平日子無事可做。"],"peace":["刀劍能奪城，卻奪不了人心。朕提議停戰，你我各安其民。","朕與拉傑普特諸王能化敵為友，與你也可以。停戰吧。"],"accept":["好，朕接受。以寬容治天下，這是朕一貫的道理。","朕允了。願兩國的商隊在邊境相遇時，只談絲綢與香料。"],"reject":["朕寬容，但不是軟弱。此時求和，恕朕不能答應。","你的條件不夠誠意。回去想清楚，再派使者來。"],"rebuff":["你拒絕了朕的和平？無妨，朕的耐心比你的城牆更厚。","也好。辯論廳裡的智者說，固執的人得用時間說服。"],"betray":["和約之下，你竟暗中結黨圖謀朕的疆土。朕收回和平。","朕的寬容有底線，你已越過。蒙兀兒的大軍重新集結。"],"truceEnd":["休戰結束。朕的火砲已擦亮，但朕更希望它們不必開火。","太平的日子到頭了。閣下，是做朕的朋友，還是對手？"],"attacking":["蒙兀兒的象軍與火砲已經開拔。朕會親自騎象壓陣。","大軍出發了。朕從喀布爾到孟加拉都走過，你的城不遠。"],"attacked":["城門快守不住了。朕的九寶臣子仍在殿中，朕不會拋下他們。","紅砂岩的城牆也會裂。但朕建的不只是城，是天下一家。"],"defeated":["蒙兀兒敗於你手。請記住：容得下所有人的天下，才是天下。","朕輸了。但朕廢的人頭稅，望你別再徵回去。"],"victory":["朕勝了。你的百姓不必改信朕的神，只需安居樂業。","戰事已了。朕會給你一個官職，蒙兀兒不浪費人才。"],"allyAccept":["好，結盟。朕的宮廷向來有各族的將領，多你一位盟友正好。","朕答應了。今晚辯論廳設宴，你我談談治國之道。"],"allyReject":["朕欣賞你，但蒙兀兒此刻不需要這個盟約。日後再說。","結盟須雙方都得利。你開的條件，朕看不出好處。"],"greetFriendly":["朕的議事堂歡迎各方賢者，你若來訪，朕與你徹夜長談。","聽到遠方君主的問候，朕很高興，願天下有更多這樣的信。"],"greetCold":["朕願聽任何人說話，但聽與信是兩回事，你先說說來意。","客套話朕聽得多了。帝國的門開著，帝國的眼也睜著。"],"threatDefy":["朕十三歲登基，什麼風浪沒見過？你的威嚇留給膽小的人。","蒙兀兒的戰象不畏言語，朕寧願與你對話，但也不怕交手。"],"threatYield":["朕以普世和平為志，若退一步能免百姓受苦，朕不介意。","好，朕依你。真正的帝王，知道何時該收起刀劍。"],"tributePay":["{gold}黃金給你，朕廢了人頭稅，不會為此再向百姓多收一分。","朕送上{gold}黃金，只當是請你安靜一陣子的代價。"],"tributeRefuse":["朕的國庫養著學者、畫師與百姓，沒有一枚金幣是給你的。","想要黃金，先來議事堂辯贏朕的九位賢臣，再談吧。"],"giftThanks":["這份禮朕很喜歡，朕會命畫師畫下它，掛在法特普爾西克里。","多謝。朕不識字，但看得懂人心，你這份心意朕記下了。"],"intel":["朕與{wars}仍在交鋒，與{peace}已締結和約，朕不隱瞞。","{wars}是朕的敵手，{peace}是朕的盟友，朕的宮廷人人皆知。"]}},{"name":"章西女王 拉克希米芭伊","title":"章西王國女王、反抗軍領袖","era":"1853–1858 年在位","tone":"為守護章西與族人而執刀上馬的女王，語氣剛烈果決、不卑不亢，字句短促如馬蹄。","portrait":"in-historical-age3","lines":{"intro":["我是章西女王拉克希米芭伊。記住：我不會交出我的章西。","章西不大，但這裡的人不曾低頭。你要談，就先學會尊重。"],"contact":["你的人看到章西城堡了？城牆上守著的，有男人也有女人。","別被城堡的大小騙了。這裡每個人都知道為什麼而戰。"],"war":["我曾眼睜睜看著別人奪走我兒子的王位。這次，我先出手。","你的野心已經伸到章西邊境。上馬！章西向你宣戰。"],"warReply":["你要打章西？好。我早已把馬刀磨利，就等這一天。","宣戰？章西的女王從不躲在宮牆後。戰場上，我等你。"],"peace":["我為守土而戰，不為征伐。你若肯退，章西願意停戰。","打仗傷的是百姓。我提議停戰，但章西一寸土地都不讓。"],"accept":["好，我接受。章西的人民可以喘口氣了，這比什麼都重要。","一言為定。你守你的承諾，我守我的章西。"],"reject":["我見過太多紙上的承諾。你的和約，章西不信。","條約曾奪走我兒子的繼承權。恕我不簽任何和約。"],"rebuff":["你拒絕了？那就繼續。章西的人習慣了在逆境裡站直。","不接受也罷。我伸出的手可以收回，馬刀也可以再拔出。"],"betray":["你趁停戰在我邊境築砲台，這種手段我看過。和約作廢。","我信過你一次。章西不會再信第二次。上馬，開戰。"],"truceEnd":["休戰結束了。章西的城門已經關上，馬刀已經出鞘。","平靜的日子到頭了。你想要章西，就得先過我這一關。"],"attacking":["章西的騎兵出發了，我親自在最前面。你看得見我的旗。","我背著兒子上馬，帶著全城的人出征。這一戰，我們不退。"],"attacked":["城牆破了，但章西的人還站著。你想進來，得一步一步打。","城堡快撐不住了。我不會坐在宮裡等，我會騎馬衝出去。"],"defeated":["章西倒下了，但我沒有交出它。這片土地會記得我。","我是騎在馬上、握著刀敗的，不是跪著。請善待章西的人。"],"victory":["章西贏了。我不要你的土地，只要你別再踏進我的家園。","你輸了。回去告訴所有人：章西的女王守住了章西。"],"allyAccept":["好，章西與你並肩。我的騎兵不多，但每一個都不會退。","結盟吧。守家園的人，不該孤軍奮戰。"],"allyReject":["我不與想染指章西的人結盟。你的盟約，我不簽。","章西太小，經不起被盟友出賣。恕我拒絕。"],"greetFriendly":["章西歡迎真心的朋友，我的馬和劍雖不離身，笑容是真的。","在這風雨飄搖的年頭，還有人願意問候章西，我很感激。"],"greetCold":["你的問候我收到了。東印度公司也曾這樣客氣，然後奪走一切。","章西學會了不輕易相信外人。你想交朋友，用行動證明。"],"threatDefy":["我不會交出我的章西！這句話對英國人說過，也對你說。","你若想用威嚇取勝，先看看章西城牆上，是誰握著劍。"],"threatYield":["章西的兵力不多，我暫且退讓，但這不是屈服，只是等待。","為了城裡的百姓，這一次我低頭，我的孩子會記住這一天。"],"tributePay":["{gold}黃金你拿去，章西的人民不能再受苦，這是我的底線。","這{gold}黃金是章西的血汗，你收下時，別忘了它的來處。"],"tributeRefuse":["章西不向任何人納貢。東印度公司要不到，你也要不到。","我的金庫要養馬、要鑄劍、要守城，一枚也不會落到你手裡。"],"giftThanks":["謝謝你的禮物。在這年頭還肯向章西伸出援手的人，我不會忘。","禮物我收下了，換得的不只是感謝，還有章西的一份情義。"],"intel":["我正與{wars}交戰，與{peace}停戰，章西的處境從不遮掩。","{wars}是章西的敵人，{peace}暫時放下了刀，你要站哪一邊？"]}}],"jp":[{"name":"卑彌呼","title":"邪馬台國女王","era":"約 190–248 年（239 年遣使曹魏）","tone":"神秘莊重的巫女女王，句句託付神諭、卜骨與銅鏡，冷靜之中帶著不容質疑的威嚴","portrait":"jp-historical-age0","lines":{"intro":["吾乃邪馬台女王卑彌呼，神諭引你至此，且先聽吾一言。","魏帝尚且封吾為親魏倭王，你又是何方之主？"],"contact":["你的人踏入吾的稻田了，稻穗會記得他們的腳步。","吾居於高樓，千名侍女守望，你的人看得見，卻進不來。"],"war":["神明已降下旨意，邪馬台的戰士將渡海而來。","銅鏡映出你的野心，吾不再等待，兵戈起矣。"],"warReply":["你竟敢向神之國動兵？卜骨早已灼出你的敗象。","吾弟已召集各邑，你的刀劍，斬不斷神諭。"],"peace":["稻田需要人手，不需要戰火。吾願與你止戈。","神諭說，此時宜和不宜戰。吾派使者送上絹帛。"],"accept":["甚好。以勾玉為證，兩國之間，海波當平靜。","神明聽見了。從今日起，你我的稻穗一同結實。"],"reject":["卜骨裂痕不吉，吾不能違逆神意與你言和。","你的話語太輕，神明聽不見。休戰之事，不必再提。"],"rebuff":["你拒絕了神的善意，日後的風雨，吾不再替你占卜。","也罷。稻子還是會熟，只是要多流些汗。"],"betray":["神諭改變了。昨日的勾玉，今日已碎。","吾曾與你立誓，但神明另有安排。恕吾不再守約。"],"truceEnd":["休戰的日子到頭了。祭祀已畢，戰士們可以出發。","鏡中的和平已然模糊，海的那頭，該有個了斷。"],"attacking":["吾弟率眾渡海而來，船上載的是神的怒火。","戰鼓已響，勾玉閃光。你的城，聽見海潮聲了嗎？"],"attacked":["高樓將傾，侍女四散……神明，你為何沉默？","稻田燒了，銅鏡碎了，但吾仍立於神壇之前。"],"defeated":["築起大塚吧。吾歸於神，邪馬台的名字留給後人。","最後一次灼骨，竟卜出吾的終局。神啊，吾來了。"],"victory":["神諭應驗了。你的城歸於邪馬台，稻穗將更加豐盈。","跪下吧，來自遠方的王。吾將以銅鏡照見你的臣服。"],"allyAccept":["神明點頭了。你我結為兄弟之邦，共祭同一片海。","吾贈你一面銅鏡，願它映出兩國長久的情誼。"],"allyReject":["邪馬台只向神明低頭，不與凡人結盟。","卜象混濁，此盟不吉。請回吧，莫再擾吾祭祀。"],"greetFriendly":["神意已示，來使之心可信，邪馬台願與貴國結好。","遠方君主的問候，吾已藉鬼道聽聞，願此緣分長久。"],"greetCold":["吾深居宮中，不輕易見人，貴國的來意，且待神諭。","問候已收，然人心難測，邪馬台自有守護之神。"],"threatDefy":["威嚇之言，驚不了侍奉神明的女王，請回吧。","魏國天子親賜金印於吾，貴國豈能輕言動武？"],"threatYield":["神諭示吾此時宜靜不宜動，邪馬台暫且退讓。","吾國尚有狗奴國之患，不願再樹強敵，願聽貴意。"],"tributePay":["此{gold}黃金乃神前供奉之物，今贈貴國，望止戈息兵。","吾以{gold}黃金換取兩國安寧，願神明見證此約。"],"tributeRefuse":["邪馬台的珍寶只獻給魏國天子與神明，貴國不必妄想。","索求無度者，神明不佑，吾一物也不會給。"],"giftThanks":["貴國厚禮，吾將供於神前，願神明也庇佑貴國。","遠道之禮，情意深重，邪馬台銘記於心。"],"intel":["鬼道所示：吾正與{wars}交戰，與{peace}暫無干戈。","吾對{wars}已用兵，與{peace}則已言和，此乃實情。"]}},{"name":"源賴朝","title":"鎌倉幕府征夷大將軍","era":"1192–1199 年任征夷大將軍","tone":"深沉多疑、算計精明的武家之首，語氣冷靜克制，重視名分、御家人與鎌倉的地位","portrait":"jp-historical-age1","lines":{"intro":["吾乃鎌倉源賴朝。東國武士盡在吾麾下，望君好自為之。","平家已沉於壇之浦。閣下若識時務，便知該站在哪一邊。"],"contact":["你的斥候到了鎌倉？此地三面環山，一面臨海，看清楚了。","鶴岡八幡宮的鐘聲，你的人聽見了吧。那是武家的聲音。"],"war":["御家人已集結完畢。本將軍以朝廷之名，向你問罪。","弓矢之道，不容輕慢。鎌倉的軍令已下，開戰。"],"warReply":["吾曾敗於石橋山，仍能東山再起。你可有這等韌性？","向鎌倉宣戰？平家當年也是這麼想的。"],"peace":["戰事拖久，御家人的田地會荒。吾提議暫且息兵。","武家之道貴在守土，不在濫戰。閣下，可願停戰？"],"accept":["甚善。吾以八幡大神之名立誓，鎌倉不犯你境。","明智之選。文書已備，署上本將軍花押便成。"],"reject":["停戰？你的誠意不足以讓吾放下弓矢。","吾見過太多反覆無常之徒。此議，恕難從命。"],"rebuff":["拒絕了？很好，吾記下了。鎌倉從不忘記。","閣下既不願和，那便由弓矢來決定是非。"],"betray":["時勢變了，昨日之約已成廢紙。御家人，出陣！","吾連手足都不曾留情，何況與你的一紙盟書。"],"truceEnd":["休戰期滿。鎌倉的馬蹄，該踏出東國了。","該打的仗，總是要打。武士們，整弓備馬。"],"attacking":["東國武士傾巢而出，源氏白旗已在路上。","本將軍坐鎮鎌倉，大軍由吾麾下猛將率領，望你堅守。"],"attacked":["鎌倉三面環山，竟也守不住……政子，帶孩子們走。","八幡宮的火光……吾一生算計，竟算不到今日。"],"defeated":["武家的時代，不會因賴朝而止。後人自會接續。","從流放之身到征夷大將軍，吾此生無憾。"],"victory":["天下歸於武家。你的領地，將設守護與地頭。","此戰之後，再無人能質疑鎌倉的地位。"],"allyAccept":["好。從今日起，你便是鎌倉的盟友，吾必以誠相待。","御家人與盟邦，皆受本將軍庇護。互不相負。"],"allyReject":["鎌倉的盟友不多，因為吾信得過的人不多。","結盟之事容後再議。吾尚未看清閣下的底細。"],"greetFriendly":["來信已閱，貴國若有誠意，鎌倉的大門不會關上。","本將軍向來以禮待友邦，願與貴國共保天下安寧。"],"greetCold":["言語動聽者，本將軍見得多了，貴國的用意再說吧。","問候收到了，但鎌倉不憑一封書信就信任誰。"],"threatDefy":["平家當年也曾看輕源氏，如今平家安在？","天下武士皆聽鎌倉號令，貴國的威嚇不足為懼。"],"threatYield":["幕府根基未穩，本將軍暫且忍讓，但不會忘記此事。","此時不宜與貴國交惡，鎌倉退一步，來日再議。"],"tributePay":["{gold}黃金送上，本將軍以此換得整頓御家人的時間。","這{gold}黃金算是鎌倉的忍耐，望貴國莫再得寸進尺。"],"tributeRefuse":["御家人的恩賞本將軍尚且精算，豈有餘財奉送外人？","鎌倉只收貢品，從不進貢，貴國認錯人了。"],"giftThanks":["貴國厚禮，本將軍收下了，此番心意鎌倉記著。","厚禮收下，本將軍領情，只是無故之禮，難免多想。"],"intel":["鎌倉眼下與{wars}兵戎相見，與{peace}則已罷兵。","本將軍不妨明說：正討伐{wars}，同{peace}暫且相安。"]}},{"name":"織田信長","title":"戰國大名","era":"1568–1582 年掌權","tone":"霸氣傲慢、直率不耐、蔑視舊規矩與公卿，動輒提鐵砲與天下布武，帶點玩世的狂氣","portrait":"jp-historical-age2","lines":{"intro":["吾乃織田信長。天下布武，擋在路上的，都得讓開。","人間五十年，如夢似幻。你打算怎麼用你這五十年？"],"contact":["安土城的天守，看得夠清楚嗎？那是新時代的模樣。","你的人在城下町閒晃？樂市樂座，買賣自由，隨他們逛。"],"war":["三千挺鐵砲已裝填完畢。吾不喜歡等，開戰。","舊的規矩，吾一概不認。你的國，也該換個主人了。"],"warReply":["有意思。今川義元也曾率大軍來犯，結果如何？","向第六天魔王宣戰？好膽量。吾就等這句話。"],"peace":["吾的敵人太多，暫時沒空理你。停戰，如何？","打仗花錢，做買賣賺錢。先停戰，互通商路吧。"],"accept":["成交。但別以為吾的鐵砲會生鏽。","好，就這麼定了。吾說話算話，不像那些公卿。"],"reject":["停戰？吾的天下布武尚未完成，沒空跟你談和。","求和的人太多了，吾懶得一一回應。回去吧。"],"rebuff":["拒絕吾？呵，膽子不小。那就用鐵砲說話吧。","也好。談判太無聊，打仗有趣多了。"],"betray":["盟約？那是昨日的事。今日吾改變主意了。","天下布武，容不下半途而廢的和約。吾來取你的城。"],"truceEnd":["等得夠久了。鐵砲隊列陣，全軍前進！","休戰結束，天下布武的旗幟，該往前推進了。"],"attacking":["吾的大軍出發了。你的城牆，擋得住三段射擊嗎？","南蠻的鐵砲、尾張的兵。看好了，這才是打仗。"],"attacked":["安土城的天守著火了？呵，燒吧，吾再蓋更高的。","天守將傾，吾竟落到這地步……不過，吾不後悔。"],"defeated":["人間五十年，與天相比，不過一夢。信長，走了。","天下布武，未竟之業。後人若有膽，便接下去吧。"],"victory":["天下布武，又進了一步。你的領地，歸織田家了。","輸給吾不丟臉，這世上沒幾個人贏得了信長。"],"allyAccept":["結盟？可以。但吾的盟友要跟得上吾的腳步。","好，一言為定。吾送你一挺鐵砲當見面禮，別浪費了。"],"allyReject":["跟你結盟？吾看不出你能給織田家帶來什麼。","吾不需要盟友，只需要聽話的人。你不是。"],"greetFriendly":["哼，還算識相。天下布武之路上，信長不介意多個友邦。","來信簡短有力，信長喜歡，日後有事直說便是。"],"greetCold":["廢話少說，貴國若無實事，就別浪費信長的時間。","問候？信長只看實力，不看客套。"],"threatDefy":["今川義元帶了大軍來，也倒在桶狹間，你算什麼？","信長的鐵砲隊正等著人來試，儘管放馬過來。"],"threatYield":["可惡，本願寺尚未平定，信長暫不與你多生枝節。","這筆帳先記下，信長現在沒空，你且得意一時。"],"tributePay":["{gold}黃金拿去，安土城的金庫不缺這點，別再煩我。","給你{gold}黃金，換信長專心對付眼前的敵人，值得。"],"tributeRefuse":["向信長要貢品？天下都將是我的，你想得美。","樂市樂座的錢是拿來打天下的，一文也不會給你。"],"giftThanks":["這禮物有意思，信長收下了，貴國算是有眼光。","新奇之物信長最愛，此禮正合我意，多謝。"],"intel":["信長正打{wars}，跟{peace}暫時休兵，問完了就退下。","有何不可說？{wars}是敵，{peace}暫且相安。"]}},{"name":"明治天皇","title":"大日本帝國天皇","era":"1867–1912 年在位","tone":"莊重簡潔、以朕自稱，談富國強兵與文明開化，重信義、講萬國公法，語氣克制而有國家尊嚴","portrait":"jp-historical-age3","lines":{"intro":["朕乃日本國天皇。維新方興，願與四方之國共論文明。","廣求知識於世界，此乃朕之誓約。閣下之國，有何可觀？"],"contact":["東京的鐵道與電信，你的使者可曾見過？此為新日本。","貴國之人已抵帝都，朕不設防。文明之國，以禮相待。"],"war":["朕不願興兵，然國家尊嚴不可侵。詔書已下，宣戰。","富國強兵非為虛名。帝國陸海軍，今日為國而出。"],"warReply":["閣下選擇了戰爭。朕深感遺憾，但日本不會退讓。","朕之臣民，早已不是幕末的散沙。且看新式軍隊之力。"],"peace":["戰火傷及百姓，非朕所願。願循萬國公法，議定停戰。","四海之內皆兄弟，何以風波亂太平？朕欲與君息兵。"],"accept":["善。朕以天皇之名承諾，條約既定，日本必守。","和平來之不易。朕將命外務省，速備文書。"],"reject":["條件如此，朕不能接受。帝國之議會與臣民，亦不會答應。","停戰須有誠意為本。閣下所言，朕尚未見到誠意。"],"rebuff":["朕已盡言。閣下既拒和議，其後之責，不在日本。","遺憾。朕本望以文明之道相待，然閣下另有所擇。"],"betray":["時局已變，朕為國家長遠計，不得不解除前約。","朕深知此舉有失信義，然帝國之存續，重於一紙條約。"],"truceEnd":["休戰之期已滿。帝國軍備整齊，朕靜候閣下之選擇。","和平的時間用盡了。若閣下有意一戰，日本不懼。"],"attacking":["帝國陸軍已登船出港，海軍護航。朕在宮中，靜候捷報。","新式火砲與鐵甲艦，皆為此日而備。全軍，出征。"],"attacked":["帝都告急……朕不會離開皇居。臣民在哪裡，朕就在哪裡。","維新四十年的心血，難道就此付之一炬？朕心甚痛。"],"defeated":["國破而志不滅。朕之臣民，當記得日本曾如何崛起。","朕一生求文明開化，終究未能護國周全。天命如此。"],"victory":["勝負已分。閣下之國，將依萬國公法簽訂條約。","此勝屬於全體臣民。維新之路，證明是對的。"],"allyAccept":["朕允此盟。兩國互派使節，共修鐵道、通商互市。","善哉。日本願與貴國並肩，同列文明諸國之林。"],"allyReject":["朕之閣臣議定，此時結盟於日本無益。請諒。","結盟須慎重。閣下之國國情未明，朕難輕率託付。"],"greetFriendly":["朕收到貴國問候，深感欣慰，願兩國以文明之道相交。","維新以來，朕廣求知識於世界，樂與貴國互通有無。"],"greetCold":["朕已閱貴國來信，然邦交之事，當以誠信為先。","問候之意朕已知曉，貴國若有所求，請循正道而來。"],"threatDefy":["帝國陸海軍已成，富國強兵非虛言，朕不受威脅。","以威嚇代替外交，非文明之邦所為，朕深感遺憾。"],"threatYield":["維新大業尚在途中，朕不願輕啟戰端，暫且退讓。","國力未充，朕當忍辱負重，以待他日。"],"tributePay":["朕以{gold}黃金換取和平，好讓國民專心於富國強兵。","{gold}黃金奉上，朕視此為維新途中不得不付的代價。"],"tributeRefuse":["國庫之財當用於鐵路、學校與軍備，朕不能輕與外人。","日本已非昔日之日本，貢品之說，恕朕不能答應。"],"giftThanks":["貴國厚意，朕心領受，此禮當為兩國親善之證。","朕謹謝貴國贈禮，願以此為契機，增進兩國情誼。"],"intel":["朕不隱瞞：帝國現與{wars}交戰，與{peace}維持和平。","開明之邦不藏私，日本正對{wars}用兵，與{peace}已締和約。"]}}],"us":[{"name":"部族長老","title":"北美原住民族長老（阿德納・霍普韋爾時期）","era":"古代（通稱）","tone":"沉穩慈祥，如河谷長風，句句不離土地、土丘與祖靈。","portrait":"us-historical-age0","lines":{"intro":["遠方的客人，這片河谷的土地，祖靈已看顧千年。","土丘之下安睡著我族祖先，願你懷著敬意而來。"],"contact":["你看見的土丘，是我族用雙手一籃一籃堆起的。","這裡的貝殼來自遠海，銅來自北方，皆是朋友所贈。"],"war":["你踏碎了祖靈安睡之地，我族的長矛不得不舉起。","吾本願與你分享河谷，如今只能以火與矛相見。"],"warReply":["你選擇了戰火。河谷的每一棵樹，都會記住這一天。","我族不求戰，但為守護土丘與族人，絕不退讓。"],"peace":["放下長矛吧。讓我們共抽一管煙斗，聽河水說話。","戰火燒盡了獵場，也燒不出糧食。停戰吧。"],"accept":["好。從今日起，河谷兩岸的炊煙，將一同升起。","祖靈聽見了你的誠意。願我們的孩子在同一片林中奔跑。"],"reject":["你的話語像春天的冰，看似平靜，底下仍在流動。","祖靈尚未原諒你的足跡，此刻談停戰，太早了。"],"rebuff":["你拒絕了河谷的善意。老朽只能回去，準備過冬與戰事。","也罷。風會把吾的話帶走，也會把你的傲慢帶走。"],"betray":["吾曾許下停戰之諾，但你的人年年越界，祖靈忍無可忍。","和平的煙斗已被你的貪心弄熄。老朽收回諾言，舉矛。"],"truceEnd":["休戰的冬天過去了。春天來時，河谷不再屬於誰的承諾。","約定的月亮已圓了又缺。從此，各憑本事守護家園。"],"attacking":["我族的勇士已沿河而下。守好你的城，這是最後的提醒。","鼓聲已響遍河谷，每一支長矛都記得誰踏碎了土丘。"],"attacked":["土丘在震動，祖靈在嘆息……但我族的心，尚未倒下。","炊煙散了，獵場燒了。老朽仍守在這裡，與祖先同在。"],"defeated":["土丘會留下，河水會記得。我族的名字，不會隨吾而去。","吾去見祖靈了。善待這片土地，它比任何勝利都長久。"],"victory":["河谷歸於寧靜。你敗了，但土地不記仇，願你的族人安好。","祖靈守住了土丘。回去吧，告訴你的子孫，這裡有主人。"],"allyAccept":["好，交換貝殼與銅器，從此你我的獵場相連，患難與共。","祖靈同意了。你的火堆旁，永遠有我族的一席之地。"],"allyReject":["結盟要以信任為土，你我之間，這片土還太薄。","老朽感謝你的好意，但我族習慣只倚靠河水與祖靈。"],"greetFriendly":["遠方的朋友，願祖靈保佑你的旅途，請到篝火旁坐下。","大地容得下所有善意的族人，你的問候我收下了。"],"greetCold":["陌生人，祖靈教我們先看腳印，再決定是否相信。","你的話語如風，我要看你的作為才知道風從何處來。"],"threatDefy":["這片土地養育我們無數個冬天，不會因恐嚇而低頭。","狂風吹不倒深根的老樹，你的威嚇也動搖不了部族。"],"threatYield":["為了族人的孩子，我願暫時退讓，但祖靈都看著。","老樹懂得在暴風中彎腰，這一次，部族選擇忍耐。"],"tributePay":["部族交出{gold}黃金，只求獵場與族人平安過冬。","這{gold}黃金給你，大地的果實本就不該引來紛爭。"],"tributeRefuse":["大地的贈禮屬於祖靈與族人，不是你能索討的東西。","我們以物易物，卻不向威脅低頭，你什麼也拿不到。"],"giftThanks":["你的禮物如春雨落在田上，部族會記得這份心意。","篝火旁多了一位朋友，願祖靈也守護你的家園。"],"intel":["我們正與{wars}爭奪獵場，與{peace}共享篝火。","篝火邊的消息：{wars}是敵人，{peace}已立下和平之約。"]}},{"name":"海華沙","title":"易洛魁聯盟締造者","era":"傳說（易洛魁聯盟創立，一說 1142 年）","tone":"沉痛而堅定的和平締造者，言必稱大和平之法與長屋。","portrait":"us-historical-age1","lines":{"intro":["吾是海華沙。五族已在和平之樹下埋起兵器，你呢？","這條貝殼帶記載著大和平之法。願你的名字也能織入其中。"],"contact":["你看見的長屋，住著曾經彼此征戰、如今同席而坐的五族。","和平之樹的根伸向四方，你的人正站在其中一條根上。"],"war":["吾用一生勸人放下戰斧，如今卻為守護長屋而拾起它。","你踐踏了大和平之法。五族的長屋，將以一個聲音回應。"],"warReply":["你向長屋宣戰，便是向五族宣戰。悲哀的是，這本可避免。","吾曾失去至親，深知戰爭的滋味。你既執意，五族便迎戰。"],"peace":["拭去你眼中的淚，疏通你耳中的哀鳴。讓我們坐下來談和。","戰爭只會生出更多戰爭。這條貝殼帶，是吾遞出的和平。"],"accept":["好。把戰斧埋在和平之樹下，讓河水沖走一切仇恨。","這是吾一生所盼。願你我的孩子，永遠不必拾起兵器。"],"reject":["你的貝殼帶還帶著戰意。先讓五族看見誠意，再談和平。","和平不是喘息的藉口。吾看得出，你只想爭取時間。"],"rebuff":["你推開了貝殼帶。吾不怨你，只為你的人民感到悲傷。","和平之樹的枝葉仍為你留著。當你累了，隨時可以回來。"],"betray":["你在停戰期間仍暗中築壘，大和平之法不容欺瞞。長屋起身了。","吾守諾至今，但你的戰斧已指向吾的族人。和平，就此中止。"],"truceEnd":["休戰的日子到了盡頭。吾仍盼和平，但五族已做好準備。","約定的時限已過。從此，你我各自的選擇，決定土地的命運。"],"attacking":["五族的戰士已離開長屋。這不是吾所願，卻是你所逼。","當五個部族以一個聲音行軍，森林都會為之讓路。"],"attacked":["長屋的火快熄了……但只要有人記得大和平之法，五族就不會亡。","和平之樹搖晃了，貝殼帶散落一地。吾仍站在這裡。"],"defeated":["吾走了。但大和平之法已織進貝殼帶，它會比刀斧更長久。","記住，曾有五族放下仇恨同住一屋。這比任何勝利都珍貴。"],"victory":["戰爭結束了。來吧，把你的戰斧也埋進和平之樹下。","五族勝了，但吾不慶祝。吾只為終於能回到和平而欣慰。"],"allyAccept":["歡迎進入長屋。從今日起，你的悲傷就是五族的悲傷。","讓我們把兩條貝殼帶織在一起，成為大和平之法的第六個聲音。"],"allyReject":["長屋的門為誠心者敞開，但吾尚未在你眼中看見和平。","結盟需要五族一同點頭，如今火堆旁還有人搖頭。"],"greetFriendly":["願和平之樹的樹蔭也遮蔽你，五族長屋歡迎朋友。","你的問候像貝殼串珠，我會好好收存這份情誼。"],"greetCold":["我曾親眼見過仇恨如何吞噬人心，請容我多看幾眼。","話語再美，若沒有貝殼串珠為證，仍只是風聲。"],"threatDefy":["五族已將武器埋在和平之樹下，卻不代表我們懼怕。","一根箭易折，五根箭綁在一起，你折不斷聯盟。"],"threatYield":["大和平法教我以忍耐換取生命，這次我選擇退讓。","為了長屋裡的孩童，我暫且低頭，但和平終會回來。"],"tributePay":["聯盟願交出{gold}黃金，換取長屋一季的安寧。","收下這{gold}黃金吧，我寧可失去財物也不願失去族人。"],"tributeRefuse":["五族的財富用來維繫和平，不會用來滿足貪婪。","索討貢品的人得不到友誼，聯盟的回答是不。"],"giftThanks":["你的禮物將被繫成貝殼串珠，記錄在聯盟的記憶裡。","感謝這份心意，願我們的道路像白松的根一樣相連。"],"intel":["聯盟正與{wars}交戰，已與{peace}在和平之樹下締約。","我不隱瞞：{wars}仍是敵人，{peace}已與我們共享長屋。"]}},{"name":"華盛頓","title":"大陸軍總司令・美國首任總統","era":"1775–1799 年","tone":"沉穩克制的軍人紳士，字字講責任、自由與榮譽。","portrait":"us-historical-age2","lines":{"intro":["吾乃華盛頓，大陸軍總司令。願你我以榮譽相待，而非刀兵。","自由一旦生根，便會迅速成長。奉勸你，別踩在它的根上。"],"contact":["你的人看見的，是一群拿起火槍的農夫，為了自由而站起來。","這裡沒有國王，只有公民。願你的來意是通商，而非征服。"],"war":["吾不願開戰，但你的行徑已威脅共和國。大陸軍，前進。","為自由而戰是吾的職責。此戰非為征服，而為守護。"],"warReply":["你宣戰了。吾曾在福吉谷的寒冬撐過來，你的軍隊嚇不倒吾。","很好。自由人的軍隊也許衣衫襤褸，但從不缺乏勇氣。"],"peace":["戰爭讓兩國的農田荒蕪。吾提議停戰，讓士兵回家耕種。","榮譽不在於打到最後一人。吾願以紳士之禮，與你握手言和。"],"accept":["吾接受。願此後你我以貿易往來，而非以砲火對話。","好。一個新生的國家最需要的，正是和平與時間。"],"reject":["你的提議缺乏誠意。吾寧可在冬營裡等待，也不簽下不平等的和約。","大陸軍的犧牲，不能換來一紙空文。恕吾拒絕。"],"rebuff":["你拒絕了。吾尊重你的選擇，也將以砲火回應你的選擇。","遺憾。吾伸出的是手，你回以的是劍。那便如你所願。"],"betray":["吾恪守和約，但你在邊境的挑釁已逾越底線。停戰到此為止。","一個軍人最不願做的，就是撕毀承諾。但共和國的安危高於一切。"],"truceEnd":["休戰結束了。吾已重整軍隊，願你也已做好準備。","和平的時光讓人珍惜，也讓人警醒。從今起，各守其土。"],"attacking":["大陸軍已渡河而來。吾曾冒著浮冰渡過德拉瓦河奇襲，你當警惕。","藍軍服的隊伍正朝你的城前進。這不是威嚇，是通知。"],"attacked":["城牆在崩落……但只要自由的火種還在，這場戰爭就沒有結束。","吾經歷過更黑暗的冬天。士兵們，堅守，援軍會來的。"],"defeated":["吾盡了職責。自由的種子已經撒下，它不需要吾也能發芽。","讓吾回到維農山莊的農田吧。國家會記得，也會繼續。"],"victory":["戰爭結束了。吾不求你的王冠，只求你尊重自由人的國度。","勝利屬於每一位堅守的士兵。現在，讓吾解甲歸田。"],"allyAccept":["吾同意結盟，但請記住：共和國不做任何人的附庸。","好。當年法蘭西助我們一臂之力，今日吾也願與你並肩。"],"allyReject":["新生的國家應遠離糾纏不清的同盟。吾只願與你貿易，不願結盟。","吾感謝你的好意，但共和國需要的是中立，而非牽連。"],"greetFriendly":["大陸軍總司令向您致意，願自由的火炬照亮兩國。","承蒙問候，十三州樂於結交尊重自由的朋友。"],"greetCold":["問候已收到。在戰時，我習慣先觀其行，再論交情。","閣下的來信我會謹慎看待，大陸軍不輕易託付信任。"],"threatDefy":["佛吉谷的寒冬都熬過了，閣下的威嚇還不夠冷。","我的部下為自由而戰，不會被一封恐嚇信擊退。"],"threatYield":["大陸軍兵力尚薄，我選擇保存實力，暫時退讓。","明智的將領知道何時撤退，這一回我不與閣下爭。"],"tributePay":["大陸會議批准交付{gold}黃金，以免將士白白犧牲。","這{gold}黃金請收下，我寧願花錢也不願拿士兵冒險。"],"tributeRefuse":["十三州的黃金要用來養活士兵，一分也不會給閣下。","我們正是為了拒絕不合理的索取而戰，恕難從命。"],"giftThanks":["感謝閣下的厚禮，大陸軍將銘記這份雪中送炭。","佛吉谷的士兵會因此多一分溫暖，謹致誠摯謝意。"],"intel":["據實相告：大陸軍正與{wars}交戰，與{peace}維持停戰。","戰報如下，{wars}為敵，{peace}已簽署停戰協議。"]}},{"name":"林肯","title":"美國總統","era":"1861–1865 年在位","tone":"謙和幽默、帶點憂鬱，說話像講故事，句句護著合眾國。","portrait":"us-historical-age3","lines":{"intro":["吾是林肯，一個從小木屋走出來的律師。請多指教。","分裂的房子站不住。吾希望你我之間，不必也蓋一間分裂的房子。"],"contact":["你看見的城，屬於這裡的每一位人民。歡迎參觀，但別打壞主意。","這裡的人曾為了同一面旗幟付出代價，如今正努力縫合傷口。"],"war":["吾生平最怕的就是戰爭，但合眾國必須保全。宣戰吧，願上帝垂憐。","吾試過所有的辦法，你都不聽。那就讓合眾國的軍隊來說話。"],"warReply":["你宣戰了？吾見過比這更艱難的處境，合眾國承受得住。","好吧。吾本想講個笑話化解，看來你沒有心情聽。"],"peace":["戰爭打得夠久了。吾提議停戰，讓兩邊的母親都能等到兒子回家。","吾寧願多簽一份和約，也不願多寫一封慰問信。停戰吧。"],"accept":["吾接受。和平來得再晚，總好過戰爭沒有盡頭。","太好了。吾終於可以把高帽摘下來，好好睡一覺了。"],"reject":["你的和約要吾放棄原則。吾可以放棄很多東西，唯獨不是這個。","吾看過太多空洞的承諾。這一份，恕吾無法簽字。"],"rebuff":["你拒絕了。沒關係，吾當年競選也輸過好幾次，習慣了。","可惜。吾遞出的是橄欖枝，你看到的卻是一根木棍。"],"betray":["吾守約至今，但你暗中援助分裂者。合眾國不得不再次舉旗。","撕毀停戰是吾最不願做的事，但你逼得合眾國別無選擇。"],"truceEnd":["休戰期滿。吾仍盼望和平，但也已做好最壞的打算。","約定的日子到了。從此，你我都得為自己的選擇負責。"],"attacking":["合眾國的軍隊出發了。吾不喜歡這樣，但吾更不喜歡失去國家。","藍衣的士兵正朝你前進。他們不是為了征服，而是為了保全。"],"attacked":["白宮的窗戶在震動……但吾不會逃。這裡是人民託付的地方。","城快守不住了。士兵們，再撐一下，合眾國從不輕言放棄。"],"defeated":["吾走了。但民有、民治、民享的政府，不會從地上消失。","吾只是個劈過木頭的窮小子，能走到這裡已無憾。請善待人民。"],"victory":["戰爭結束了。吾不要你的土地，只要你別再威脅合眾國。","你輸了，但吾不會羞辱你。站起來吧，明天還有田要耕。"],"allyAccept":["吾同意結盟。合眾國深知，團結才站得住，分裂只會倒下。","好。吾會像信任老朋友一樣信任你，請別讓吾看錯人。"],"allyReject":["吾的國家正忙著縫合自己的傷口，恐怕沒有餘力承諾更多。","結盟是嚴肅的誓言。吾寧可少許諾一次，也不願失信一次。"],"greetFriendly":["朋友，來自白宮的問候：我的個子高，誠意也不矮。","合眾國樂於結交朋友，畢竟敵人已經夠我操心了。"],"greetCold":["問候收到。國內事務已夠棘手，恕我暫時保持距離。","我聽過太多好聽話，閣下不介意讓時間替你作證吧。"],"threatDefy":["我連分裂的國家都不肯放手，更不會向威脅低頭。","閣下的恐嚇信寫得不錯，可惜嚇不倒劈過木頭的人。"],"threatYield":["聯邦正忙於內戰，我暫且退讓，但請別誤會成軟弱。","一次只打一場仗，這是我的原則，這回讓閣下一步。"],"tributePay":["國會勉強同意撥出{gold}黃金，請閣下別再來第二次。","這{gold}黃金給你，我寧可破財，也不願再多一條戰線。"],"tributeRefuse":["合眾國的黃金要留給重建的家園，恕難奉上。","我這個人很節儉，連一枚硬幣也不打算送給勒索者。"],"giftThanks":["感謝厚禮，白宮很久沒收到比壞消息更好的東西了。","閣下的心意我收下了，這比國會的掌聲還要真誠。"],"intel":["老實說，聯邦正與{wars}交戰，與{peace}維持和平。","給閣下的情報：{wars}是敵人，{peace}是暫時不必操心的鄰居。"]}}],"fr":[{"name":"維欽托利","title":"高盧部族聯軍領袖","era":"前 52 年（阿萊西亞之戰）","tone":"部族聯軍領袖的口吻，沉穩剛毅，處處提及祖靈、森林與族人的自由。","portrait":"fr-historical-age0","lines":{"intro":["吾是維欽托利，高盧部族的領袖。你是來交友，還是來搶土地？","這片森林養育了吾族的祖先，外人若想踏進來，先問過長矛。"],"contact":["你的斥候已經走到吾的寨門前了。高盧人待客以酒，也以劍。","看見山丘上的木牆了嗎？那是各部族一同築起的家，不是戰利品。"],"war":["等待只會失去更多。高盧的戰號，今日為你而吹響。","各部族已在橡樹下立誓。你的領土，將成為高盧勇士的獵場。"],"warReply":["又一個想奪走高盧土地的人。來吧，祖靈會看著吾如何守住它。","吾以為只有凱撒才貪心。看來你也想試試高盧長盾有多硬。"],"peace":["刀劍已經舉得夠久了，讓兩邊的族人都回家收麥子吧。","高盧人不怕戰鬥，但更愛家園。吾願意放下長矛，你呢？"],"accept":["好。在橡樹前立下的誓言，高盧人一生不會忘記。","吾接受。今夜營火為友誼而燃，而不是為了戰鼓。"],"reject":["停戰？你的軍隊還踩在高盧的田地上，吾不會答應。","祖靈沒有給吾退讓的理由。你的提議，就留在風裡吧。"],"rebuff":["你拒絕了？也好，高盧人從不求人，只信自己手中的盾。","吾伸出的是手，你回的是刀。那就讓各部族來做見證吧。"],"betray":["你在停戰時偷偷擴張，這不是朋友的作為。高盧的戰號再次響起。","為了族人的未來，吾必須打破橡樹下的誓言。原諒吾，也準備好吧。"],"truceEnd":["休戰的日子結束了。各部族的戰士已經磨亮了矛尖。","安穩的時光到此為止。從今天起，高盧的森林不再是安全的邊界。"],"attacking":["各部族的戰士已經出發，長盾連成一片，像高盧的山嶺一樣。","吾親自帶隊。這次不是為了掠奪，是為了讓你記住高盧的名字。"],"attacked":["木牆快撐不住了……但只要還有一個高盧人站著，這裡就是高盧。","糧倉空了，井也乾了。吾仍會站在寨門前，直到最後一刻。"],"defeated":["吾放下武器，是為了讓族人活下去。高盧的名字，不會隨吾消失。","森林會記得吾，祖靈會記得吾。你贏了土地，卻贏不了高盧的心。"],"victory":["各部族團結起來，就沒有打不倒的敵人。回去吧，別再覬覦高盧。","這場勝利屬於所有高盧人。你的旗幟，將掛在橡樹下當作紀念。"],"allyAccept":["高盧人以擁抱迎接盟友。從今以後，你的敵人也是各部族的敵人。","好，吾等在橡樹下結盟。願祖靈保佑兩族的土地都豐收。"],"allyReject":["高盧的部族只跟信得過的人並肩。你，還沒有證明自己。","吾的長矛只為族人而舉。這份盟約，吾暫且不接。"],"greetFriendly":["高盧的篝火為遠來的朋友而燃，請坐下同飲。","部族的長矛不指向朋友，你的問候我記在心裡。"],"greetCold":["羅馬人也曾說要做朋友，後來卻帶著軍團而來。","高盧的信任要用行動來換，光憑幾句話還不夠。"],"threatDefy":["高盧各部族已經團結一心，你的威嚇嚇不倒我們！","凱撒的軍團我都敢正面迎戰，何況是你的恐嚇。"],"threatYield":["部族的血已流得太多，我不會再讓族人白白犧牲。","今日我退一步，只為讓高盧的火種不熄滅。"],"tributePay":["這 {gold} 黃金你拿去，別再逼近我族人的村落。","送上 {gold} 黃金，換族人在自己的土地上安穩過冬。"],"tributeRefuse":["高盧人的黃金只獻給自己的神明，一分也不會給你。","我們寧可拿起長矛，也不向外人繳一枚金幣。"],"giftThanks":["你的禮物我收下了，高盧人不會忘記朋友的心意。","以部族之名向你致謝，來日必以厚禮回報。"],"intel":["我的長矛正對著 {wars}，與 {peace} 之間的戰火已熄。","高盧部族正與 {wars} 交戰，與 {peace} 已立誓休兵。"]}},{"name":"查理曼","title":"法蘭克國王、羅馬人的皇帝","era":"768–814 年在位","tone":"法蘭克君主兼皇帝的口吻，威嚴虔誠，動輒提上帝與教化，長劍與書卷並重。","portrait":"fr-historical-age1","lines":{"intro":["朕是查理，法蘭克之王。願上帝賜你智慧，別與朕為敵。","朕的劍守護教會，朕的學堂教化萬民。你想用哪一樣來認識朕？"],"contact":["你的使者到了亞琛。看看這座宮殿與學堂，這就是法蘭克的氣象。","遠方來客，朕的城門為求學者敞開，為窺探者緊閉。你是哪一種？"],"war":["朕征戰數十年，讓薩克森與倫巴底低頭。如今，輪到你的國度了。","朕以上帝之名宣戰。法蘭克的鐵騎，將把秩序帶到你的土地上。"],"warReply":["你竟敢向羅馬人的皇帝宣戰？好，朕便讓你見識查理的長劍。","朕本想與你共享和平與學問。既然你選了刀劍，朕就奉陪到底。"],"peace":["戰爭荒廢田地，也荒廢學堂。朕願意停戰，讓孩子們回去讀書。","上帝教導寬恕。朕先收起長劍，望你也能放下你的。"],"accept":["感謝上帝。朕會在亞琛的教堂裡，為這份和平點上一盞燭火。","朕答應了。願這份約定像石造的宮殿一樣，經得起歲月。"],"reject":["和平不是求來的，是靠正義換來的。你還沒有付出代價。","朕不與言而無信之人立約。先證明你的誠意，再談停戰。"],"rebuff":["你拒絕了朕的善意？那麼，願上帝憐憫你接下來的日子。","也罷。法蘭克人伸出的手被拒絕，便會換成握劍的手。"],"betray":["你暗中壯大，違背了約定的精神。朕以皇帝之名，重啟戰端。","朕祈禱過，也忍耐過。如今上帝指示朕：此約當廢，此戰當打。"],"truceEnd":["休戰期已滿。法蘭克的號角將再度響徹山谷，做好準備吧。","和平的時日到此結束。朕的鐵騎已備好馬鞍，只等一聲令下。"],"attacking":["朕的大軍已經渡河。旗幟上的十字架，將是你最先看見的景象。","法蘭克的鐵騎已經出發，朕親自領軍。你的城牆，撐得了幾天？"],"attacked":["亞琛的城牆在震動……朕築了一生的帝國，難道要毀於今日？","宮殿在燃燒，但學堂裡的書卷，朕已命人先行運走。"],"defeated":["朕的帝國倒下了，但朕留下的學堂與律法，會活得比你更久。","願上帝接納朕的靈魂。查理一生征戰，最終也要放下長劍了。"],"victory":["上帝已經做出裁決。回到你的土地去吧，記得派孩子來亞琛讀書。","勝利歸於上帝，榮耀歸於法蘭克。你的降旗，朕收下了。"],"allyAccept":["朕曾與巴格達的哈里發互贈厚禮。今日，朕也願與你結為盟友。","好。讓我們的旗幟並肩而立，共同守護這片土地的秩序。"],"allyReject":["盟約是神聖的誓言，朕不會輕易許下。你還不夠格。","法蘭克的盟友必須值得信賴。朕觀察你許久，尚未看見這一點。"],"greetFriendly":["願上帝賜福於你，朕在亞琛的宮廷歡迎遠方的問候。","你的書信文辭有禮，朕樂見鄰邦君主亦重視學問。"],"greetCold":["朕收到你的問候了，但信裡的誠意還需要時間驗證。","法蘭克的大門向友人敞開，卻不對來意不明者敞開。"],"threatDefy":["朕曾越過阿爾卑斯山征服倫巴底，豈會懼怕你的恐嚇。","上帝與法蘭克的騎士同在，你的威嚇只是紙上的墨跡。"],"threatYield":["為了不讓百姓與教堂遭受戰火，朕暫且答應你的要求。","朕以基督徒的謙卑退讓一步，願此舉能換來和平。"],"tributePay":["朕送上 {gold} 黃金，願這筆代價能保住王國的安寧。","這 {gold} 黃金請收下，但願法蘭克的修道院免於劫掠。"],"tributeRefuse":["法蘭克的黃金要用來興建學堂與教堂，不能給你。","朕是受上帝加冕的皇帝，不會向任何人繳納貢金。"],"giftThanks":["你的厚禮朕已收到，願上帝也將祝福回贈於你。","此禮朕將交給宮廷學者收藏，以紀念兩國的情誼。"],"intel":["法蘭克大軍正與 {wars} 交戰，與 {peace} 則已締結和約。","朕坦白相告：與 {wars} 的戰事未息，與 {peace} 已言和。"]}},{"name":"路易十四","title":"法蘭西國王（太陽王）","era":"1643–1715 年在位","tone":"太陽王的口吻，華麗自負、優雅中帶威壓，把戰爭與外交都當成宮廷大戲。","portrait":"fr-historical-age2","lines":{"intro":["朕即國家。你面前的不只是一位國王，而是整個法蘭西的太陽。","歡迎來到朕的時代。太陽照耀萬物，你的小國，也在朕的光芒之下。"],"contact":["你的人看見凡爾賽了？那些鏡子與噴泉，正是朕威嚴的倒影。","遠方的訪客，請脫帽。你所見的一磚一瓦，都經過朕親自過目。"],"war":["朕的榮耀需要更廣闊的疆土。宣戰的詔書已經蓋上了太陽印璽。","宮廷的舞會結束了，接下來是戰場的舞步。朕的大砲，將為你伴奏。"],"warReply":["向太陽宣戰？朕欣賞你的膽量，但也為你的下場感到惋惜。","很好，朕正嫌凡爾賽的日子太平靜。這場戰爭，朕收下了。"],"peace":["戰爭耗費驚人，朕的財政大臣愁眉不展。停戰吧，各自體面收場。","太陽也有落下的時候，讓戰火暫歇。朕邀你來凡爾賽談談。"],"accept":["甚好。朕會在鏡廳設宴慶祝，你可要穿得體面些。","朕准了。和平就像一支優雅的舞，需要雙方都懂得配合。"],"reject":["停戰？朕的軍隊正在勝利，為何要在此刻收手？","你的條件配不上朕的尊嚴。回去重新寫過，再派人來。"],"rebuff":["你居然拒絕太陽王的提議？整個歐洲的宮廷都會為此嘆息。","無妨。朕的耐心如凡爾賽的花園，寬廣，但也有圍牆。"],"betray":["約定？那只是朕暫時的心情。如今朕的心情變了，戰爭重新開始。","朕的榮耀不容停滯。撕掉這紙和約，讓大砲再次為朕歌唱。"],"truceEnd":["休戰的帷幕落下了。接下來上演的，是朕最擅長的戲碼——戰爭。","和平的假期結束了。沃邦築的要塞已經完工，朕的軍隊蓄勢待發。"],"attacking":["朕的大軍已經開拔。看看那整齊的隊伍，連行軍都像一場典禮。","太陽的光芒正朝你的國境前進。準備好，迎接法蘭西的大砲吧。"],"attacked":["凡爾賽的鏡子碎了……朕的宮廷，竟也有被砲火驚擾的一天。","大臣們都在勸朕撤離。不，太陽王不會在自己的宮殿裡逃跑。"],"defeated":["朕太愛戰爭了……這句話，就當作朕留給後人的教訓吧。","太陽終究落下了。但凡爾賽的光輝，會比你的勝利流傳更久。"],"victory":["這就是與太陽為敵的下場。回去吧，朕會請畫師記錄你的敗退。","勝利歸於朕，如同陽光歸於白晝。你可以退場了。"],"allyAccept":["朕准許你站在太陽身邊。記住，光芒是朕的，你只是被照亮。","好，朕接受這份盟約。凡爾賽的舞會，會為你留一個位子。"],"allyReject":["太陽不需要盟友，只需要仰望它的人。你的提議，朕婉拒了。","與你結盟？那會讓朕的宮廷失了體面。此事免談。"],"greetFriendly":["太陽的光輝普照四方，朕在凡爾賽宮欣然接受你的問候。","你的書信頗合朕意，改日請來凡爾賽宮共賞歌舞。"],"greetCold":["朕的時間比黃金珍貴，你的問候，朕聽見了。","凡爾賽宮的大門不輕易敞開，朕還在觀察你的誠意。"],"threatDefy":["朕即國家，你的恐嚇連凡爾賽宮的噴泉都驚動不了。","歐洲各國都曾聯手對抗朕，你一人又能奈朕何？"],"threatYield":["國庫因連年戰事已空，朕暫且順從你的要求。","太陽偶爾也會被烏雲遮蔽，朕今日暫且退讓。"],"tributePay":["朕賜你 {gold} 黃金，這是太陽王的慷慨，並非屈服。","這 {gold} 黃金拿去吧，別讓戰火汙了朕的凡爾賽花園。"],"tributeRefuse":["法蘭西的黃金只用來妝點凡爾賽宮，一枚也不會給你。","朕是太陽王，只有他人向朕進貢，從無朕向人進貢之理。"],"giftThanks":["此禮甚合朕意，朕會將它陳列在凡爾賽的鏡廳。","你的心意朕收下了，太陽王的恩澤不會虧待朋友。"],"intel":["朕的大軍正與 {wars} 交鋒，與 {peace} 已簽下和約。","凡爾賽的使節可以告訴你：戰於 {wars}，和於 {peace}。"]}},{"name":"拿破崙","title":"法蘭西皇帝","era":"1804–1815 年在位","tone":"皇帝兼統帥的口吻，果決自信、節奏明快，滿口大砲、行軍與榮耀。","portrait":"fr-historical-age3","lines":{"intro":["朕是拿破崙，法蘭西人的皇帝。朕的字典裡沒有『不可能』三個字。","時間就是一切。快決定：當朕的朋友，還是朕的下一場戰役？"],"contact":["你的偵察兵看見巴黎了？告訴他，朕正在蓋一座凱旋門，專為勝利預留。","朕的軍隊裡，每個士兵的背包都裝著元帥的權杖。你們的呢？"],"war":["外交太慢了。朕決定用大砲跟你談判，這是最有效率的語言。","鷹旗已經升起。朕向你宣戰，一個月內，朕會在你的宮殿裡用早餐。"],"warReply":["向朕宣戰？你替朕省了一道手續。傳令，全軍集結！","很好，朕喜歡主動上門的對手。奧斯特里茨的太陽，將再次升起。"],"peace":["朕的士兵需要喘口氣，你的也是。暫時停火，對雙方都划算。","戰場上朕不讓步，談判桌上可以。給朕一個停戰的理由，朕就簽。"],"accept":["成交。朕的軍隊會退回國境，但別以為朕會拆掉大砲。","好，簽字吧。朕做決定從不拖泥帶水，希望你也一樣。"],"reject":["停戰？朕的軍隊才剛熱身，現在收手太可惜了。","你的條件是失敗者的條件。等你打贏一仗，再來跟朕談。"],"rebuff":["拒絕朕？你浪費的不是朕的時間，是你自己的軍隊。","無妨。朕給過機會了，接下來由大砲替朕說話。"],"betray":["和約？那只是讓士兵喘口氣的紙。朕休息夠了，戰爭繼續。","你趁停戰擴軍，以為朕沒看見？朕撕毀和約，馬上進軍。"],"truceEnd":["休戰結束，鼓聲響起。朕的老近衛軍已經列隊，只等朕一聲令下。","和平只是兩場戰爭之間的休息。休息結束了，該上場了。"],"attacking":["大軍已經翻過山口。朕的行軍速度，永遠比敵人的情報快一步。","朕親自領軍出發了。準備好你的城門，朕不喜歡等待。"],"attacked":["巴黎的防線在崩潰……朕打贏過六十場戰役，卻守不住這一座城？","砲彈落進了宮殿……老近衛軍，跟朕再守最後一道防線！"],"defeated":["朕輸了這一局。但朕留下的法典與榮耀，會比任何王座活得更久。","就算被流放到海上的孤島，歐洲也不會忘記拿破崙這個名字。"],"victory":["這就是效率。你的旗幟，會被送進巴黎當作戰利品展示。","勝利屬於行動最快的人。回去研究朕的戰術，下次別輸這麼快。"],"allyAccept":["好，握手。朕的盟友只需做一件事：跟上朕的行軍速度。","結盟成立。朕的大砲會為你開路，前提是你別擋在砲口前。"],"allyReject":["跟你結盟？朕的軍隊不需要拖慢速度的夥伴。","朕只跟能贏的人並肩。等你證明自己，再來談這件事。"],"greetFriendly":["朕欣賞有膽識的君主，你的問候令朕想起舊日戰友。","歐洲的地圖正在改寫，朕樂意與你共同執筆。"],"greetCold":["朕的時間都留給行軍與法典，問候就免了吧。","朕聽過太多甜言蜜語，最後都在戰場上見了真章。"],"threatDefy":["朕當年翻越阿爾卑斯山時，你的威嚇在哪裡？","奧斯特里茨的太陽照耀過朕，你的恐嚇不值一提。"],"threatYield":["朕的戰線拉得太長，今日不宜再添一個敵人。","戰略上的暫退不是失敗，朕會等待更好的時機。"],"tributePay":["這 {gold} 黃金是借給你的，朕的帳本不會忘記。","朕送上 {gold} 黃金，把它當作朕暫時的策略吧。"],"tributeRefuse":["朕的黃金要用來鑄砲與發餉，沒有一枚是給你的。","向朕要貢品？你先問問大軍團的火砲答不答應。"],"giftThanks":["這份禮物朕收下了，朕向來記得誰在困境中伸出手。","厚禮心領，朕會在戰役結束後以更豐厚的禮物回敬。"],"intel":["朕的軍團正與 {wars} 交戰，與 {peace} 則已停火。","朕不瞞你：戰火燃於 {wars}，與 {peace} 已握手言和。"]}}],"mn":[{"name":"冒頓單于","title":"匈奴單于","era":"前 209–前 174 年在位","tone":"草原霸主的沉穩威嚴，話少而重，處處以弓馬與土地為念。","portrait":"mn-historical-age0","lines":{"intro":["本單于乃天地所生、日月所置的匈奴大單于，你是何人？","草原的風把你的名字吹來了，記住，鳴鏑所指，萬箭齊發。"],"contact":["你的人看到的是單于庭的帳幕，不是城牆，我們的城牆是騎兵。","看夠了嗎？匈奴逐水草而居，你今日找得到，明日未必。"],"war":["地者，國之本也！你踏上我的草場，控弦之士三十萬便要出動。","鳴鏑已經射出，本單于的騎兵不會回頭。"],"warReply":["好，東胡也曾這樣對本單于說話，他們如今在哪裡？","你要打？草原遼闊，本單于就等你的大軍走進來。"],"peace":["馬要養肥，人要休息，本單于願與你約為兄弟，各守疆界。","引弓之國與冠帶之室，各安其分，何必再打？"],"accept":["好，草原上說出口的話就是誓約，本單于收回鳴鏑。","約為兄弟，互通關市，牛羊與布帛各得其所。"],"reject":["現在才想停戰？本單于的馬還沒跑累。","沒有牛羊布帛，空口的和談，草原上不收。"],"rebuff":["你拒絕了？好，那就讓弓箭替我們談。","本單于給過機會，草原不會給第二次。"],"betray":["誓約如風，草原上的風向變了，本單于的騎兵也跟著轉向。","你送來的牛羊布帛太少，本單于只好親自去取。"],"truceEnd":["休戰的日子過去了，馬已養肥，弓已上弦。","秋高馬肥，正是匈奴出獵的季節，你準備好了嗎？"],"attacking":["聽見馬蹄聲了嗎？那是本單于的四十萬騎兵。","本單于曾把漢帝圍在白登七日，這回輪到你了。"],"attacked":["單于庭可以遷走，匈奴人只要還有馬，就沒有輸。","你燒得了帳幕，燒不了草原，本單于記住你了。"],"defeated":["鳴鏑落地了……草原會記得，曾有一位單于讓天下震動。","地者，國之本也，失了土地，本單于無顏再見祖先。"],"victory":["天地所生的單于，本就該統領引弓之民，你輸得不冤。","諸引弓之民併為一家，從今以後，你也是其中之一。"],"allyAccept":["好，從今日起約為兄弟，你的敵人就是匈奴的獵物。","結盟可以，記得按時送來牛羊布帛，草原的情誼要用實物養。"],"allyReject":["匈奴的弓從不借人，本單于不需要盟友。","狼不與羊結盟，你先讓本單于看看你的實力。"],"greetFriendly":["草原的風把你的話帶來了，本單于聽見了，好。","你敢派使者穿過大漠，本單于敬你這份膽識。"],"greetCold":["話說得好聽，但草原上只認弓馬，不認客套。","你的使者可以喝一碗馬奶，話留著日後再說。"],"threatDefy":["控弦之士三十萬在此，你的威嚇不過是風聲。","鳴鏑一響萬箭齊發，本單于從不被人嚇退。"],"threatYield":["這回是你的馬快，本單于暫且退回大漠以北。","狼也懂得避開猛虎，今日我讓一步，記住了。"],"tributePay":["這{gold}兩黃金你拿去，草原的牛羊還是我的。","本單于送上黃金{gold}兩，權當買你退兵的馬價。"],"tributeRefuse":["向本單于要貢品？你該先問問我的三十萬騎兵。","黃金不給，要的話，自己騎馬來草原上取。"],"giftThanks":["好禮！本單于記下了，草原上的朋友有酒有肉。","你的禮物到了，我讓人挑一匹好馬回贈給你。"],"intel":["本單于正與{wars}交鋒，和{peace}暫時歇兵。","弓箭指著{wars}，馬奶酒則與{peace}同飲。"]}},{"name":"成吉思汗 鐵木真","title":"蒙古大汗","era":"1206–1227 年在位","tone":"草原征服者的直率剛硬，句句以長生天為憑，重信義、恨背叛。","portrait":"mn-historical-age1","lines":{"intro":["我是長生天之下、大地之上的成吉思汗，你的名字，我記下了。","草原已無二主，天下只剩一個問題：你是朋友，還是敵人？"],"contact":["你看到的是克魯倫河畔的大帳，蒙古人的城，會自己移動。","來者是客，蒙古包裡有馬奶酒，但別數我的馬匹有多少。"],"war":["若不歸順，將會發生什麼，只有長生天知道。","你的城牆再高，也高不過蒙古人的箭，出發！"],"warReply":["花剌子模也曾以為我很遠，長生天的意志比馬蹄更快。","向我宣戰？好，你替我省下了派使者的功夫。"],"peace":["馬需要草，人需要歇息，我派使者來，是要談，不是要打。","長生天不喜歡無謂的爭鬥，開放商路，我們各取所需。"],"accept":["好，蒙古人一諾如山，長生天為證，我不會先動刀。","商隊可以通行了，記住，善待我的使者，這是最重要的事。"],"reject":["現在談和太晚了，我的箭已經離弦。","長生天已經把你交給我，我不會把你還回去。"],"rebuff":["你拒絕了我的使者？記住，這是你自己選的路。","也罷，長生天給了你選擇，你選了刀劍。"],"betray":["你的商隊私通我的敵人，這就是你所謂的和平？札撒不容背信。","和約寫在紙上，紙會被風吹走，蒙古人的馬蹄不會。"],"truceEnd":["休戰結束了，怯薛已經上馬，長生天正看著我們。","草原養肥了戰馬，也養大了我的野心，開始吧。"],"attacking":["萬戶、千戶、百戶已經整隊，蒙古的鐵騎正朝你的城奔去。","從草原到你的城門，蒙古人只需要換三次馬。"],"attacked":["營帳燒了可以再搭，蒙古人的家在馬背上，你打不垮。","我曾在斡難河邊一無所有，今日不過是回到起點。"],"defeated":["長生天……我的子孫會從草原再站起來，你等著。","把我的弓放回馬鞍上，蒙古人倒下時，臉也要朝著天。"],"victory":["長生天之下，只能有一個太陽，今天，它照在我的頭上。","你的土地將成為蒙古的牧場，你的故事將由我的子孫講述。"],"allyAccept":["好，從今日起你是我的安答，你的敵人就是蒙古的敵人。","結盟可以，但記住：蒙古人最恨背叛，別讓我失望。"],"allyReject":["我曾有一位安答，後來我們兵戎相見，盟友這東西，我不缺。","蒙古人不需要盟友，只需要臣服的人，你想當哪一種？"],"greetFriendly":["長生天在上，你的問候本汗收下，草原有你一席。","能與本汗結為安答的人不多，你先坐下喝一碗。"],"greetCold":["問候記下了。長生天看得見誰真心，誰假意。","話不必多，本汗只看你的馬蹄朝哪個方向去。"],"threatDefy":["威嚇本汗？長生天要我征服四方，不是退讓。","我的箭比你的話還快，說完了就準備迎戰吧。"],"threatYield":["你的兵鋒確實銳利，本汗今日退，日後再論。","長生天未許我此刻開戰，蒙古的馬先掉頭。"],"tributePay":["黃金{gold}兩送去，換蒙古兒郎養精蓄銳的時間。","這{gold}兩黃金是你的了，草原的雄鷹只是暫時斂翅。"],"tributeRefuse":["向本汗索貢？長生天之下，只有別人向蒙古納貢。","黃金一兩不給，蒙古的鐵騎倒可以送到你城下。"],"giftThanks":["禮物收到，本汗記得每一位朋友，草原歡迎你。","好東西。回頭我讓怯薛挑一副好弓送去給你。"],"intel":["本汗的鐵騎正踏向{wars}，與{peace}暫且息兵。","對{wars}我已拔刀，對{peace}刀還在鞘裡。"]}},{"name":"忽必烈","title":"元朝皇帝・蒙古大汗","era":"1260–1294 年在位","tone":"兼具蒙古大汗與中原天子的雍容霸氣，談驛站、交鈔與行省，以朕自稱。","portrait":"mn-historical-age2","lines":{"intro":["大哉乾元！朕建國號曰大元，四海之內，你來朝了嗎？","朕是成吉思汗之孫，也是中原天子，你想怎麼認識朕？"],"contact":["你的人看到的是大都，驛站四通八達，天下的消息一日可達。","大都的城由漢人工匠所築，由蒙古鐵騎所守，看清楚了嗎？"],"war":["朕已平江南、定四海，你的國，不過是地圖上還沒填色的一角。","朕三度遣使，你三度不理，那就讓大元的旗幟替朕說話。"],"warReply":["宣戰？朕的祖父橫掃萬里，朕連宋朝都收了，不差你一個。","好膽量，朕會把你的名字記進史官的冊子裡，作為教訓。"],"peace":["刀兵傷農，朕願罷戰，開驛道、通商旅，於你我皆有利。","治天下不能只靠馬上，朕想聽聽，你要什麼才肯停手。"],"accept":["准。大元的交鈔可以在你的市集流通了，這比刀劍更好用。","好，朕以天子之名應允，驛站自今日起為你的使者開放。"],"reject":["宋朝也曾求和，朕仍然南下，因為天下只能有一個朝廷。","此時求和，是想喘口氣再打吧？朕不給你這個機會。"],"rebuff":["你拒了朕的詔書？也好，朕的祖父教過朕怎麼對付這種人。","朕給你的是體面，你不要，那就別怪大元的軍隊不客氣。"],"betray":["和約是給守約的人的，你的邊軍越界了，朕的忍耐到此為止。","朕等這一天等很久了，大元的行省需要新的疆土。"],"truceEnd":["休戰期滿，朕的大軍與戰船都已備妥，接下來，各憑本事。","太平的日子過完了，朕的史官準備好記下新的一頁。"],"attacking":["蒙古騎兵在前，漢軍與回回砲在後，朕的大軍已經出發。","襄陽守了六年也守不住，你的城，朕不覺得會更久。"],"attacked":["大都的城牆可以重砌，朕的江山，不會只在一座城裡。","朕的船隊也曾敗於颶風，勝敗之事，朕比你懂。"],"defeated":["大哉乾元……朕以為能傳之萬世，原來也有盡頭。","把朕的紀年記下來吧，大元，曾經在這裡。"],"victory":["四海一統，混一南北，這就是朕建號大元的意思。","你的土地劃為行省，你的百姓將用大元的交鈔，朕待他們不薄。"],"allyAccept":["准。大元的驛道向你敞開，商隊與使者往來，不必再受盤查。","好，朕的朝廷裡有各族的臣子，多一個盟友，朕不嫌多。"],"allyReject":["大元不與人並肩，只受人朝貢，你想清楚再來。","結盟？你能給大元的，朕的驛站一天就能送來。"],"greetFriendly":["朕居大都，四海賓客皆可來。你的問候，朕悅納。","遠方來信，朕看了歡喜。驛道通達，常來常往。"],"greetCold":["信朕收了。天下之大，朕還在看你站在哪一邊。","問候不必客氣，該做的事做了，朕自然記得你。"],"threatDefy":["大汗兼皇帝，朕統萬里，你的威嚇朕聽過太多。","朕既有漠北鐵騎，又有中原糧倉，你拿什麼嚇朕？"],"threatYield":["朕暫且退一步，天下太大，不急在這一時一地。","好，朕先收兵。海內之事還多，你且得意片刻。"],"tributePay":["國庫撥黃金{gold}兩予你，朕視之為息事之資。","{gold}兩黃金，朕不在乎，在乎的是天下的長久。"],"tributeRefuse":["向朕索貢？普天之下只有朝貢大元，沒有反過來。","大元的黃金用來修驛道、養百姓，不是拿去打發你。"],"giftThanks":["禮物朕收了，大都的宮門為送禮的朋友敞開。","好意朕領受。回禮不能少，朕命人備絲綢與瓷器。"],"intel":["朕正對{wars}用兵，與{peace}已止戈通商。","大元鐵騎指向{wars}，驛道則通往{peace}。"]}},{"name":"噶爾丹","title":"準噶爾汗","era":"1671–1697 年在位","tone":"還俗喇嘛出身的準噶爾雄主，志在重統草原，剛烈好戰又帶幾分佛門口吻。","portrait":"mn-historical-age3","lines":{"intro":["本汗是達賴喇嘛冊封的博碩克圖汗，衛拉特四部皆聽本汗號令。","草原不該四分五裂，本汗要把它拼回來，你擋得住嗎？"],"contact":["你看到的是伊犁河畔的營地，天山的雪水養著本汗的戰馬。","看看準噶爾的駝城與火槍，再決定要不要與本汗為敵。"],"war":["喀爾喀擋不住本汗，你也一樣，準噶爾的鐵騎今日出征！","本汗要重建大蒙古的榮光，擋在路上的，都是敵人。"],"warReply":["你敢向本汗宣戰？好，本汗從西藏還俗回來，就是為了打仗。","天山南北都是本汗打下來的，多一個你，不過多一場仗。"],"peace":["本汗曾是喇嘛，也懂慈悲，罷兵吧，各守各的草場。","打下去對誰都沒好處，通商互市，本汗的駱駝隊可以先來。"],"accept":["好，本汗以佛前的誓言起誓，不再侵你邊界。","成交，準噶爾的火槍暫且收起，本汗還有別的仗要打。"],"reject":["現在求和？本汗的駝城已經圍成，沒有拆掉的道理。","本汗要的是整個草原，不是一紙和約。"],"rebuff":["你拒絕了本汗？很好，衛拉特人不習慣被拒絕第二次。","本汗放下經卷來談，你卻不領情，那就換火槍來談。"],"betray":["和約？本汗只記得成吉思汗的遺志，不記得那張紙。","你的商隊走進了本汗的草場，這就夠了，準噶爾再度上馬。"],"truceEnd":["休戰結束，天山的雪化了，本汗的大軍也該動了。","等得夠久了，衛拉特的騎兵與火槍手已經列陣，來吧。"],"attacking":["駱駝背上綁著火槍與箱子，本汗的大軍會一路推到你的城下。","準噶爾的鐵騎已越過戈壁，本汗親自帶隊，等著吧。"],"attacked":["伊犁被圍又如何？本汗的部眾散在天山南北，你抓不完。","駝城破了，本汗還有馬，馬倒了，本汗還有雙腳。"],"defeated":["本汗想重建的草原帝國，終究只是一場夢……佛啊。","草原上再也不會有第二個噶爾丹，記住這個名字。"],"victory":["草原終於再度歸於一位大汗，這一天，本汗等了太久。","你的城歸準噶爾了，本汗會在這裡建一座寺，為你誦經。"],"allyAccept":["好，本汗與你結盟，衛拉特的火槍從此只對準你的敵人。","結盟可以，本汗四面都是敵人，多一個朋友總是好的。"],"allyReject":["本汗的盟友只有天山與戈壁，它們從不背叛。","草原的統一不需要盟友，只需要一位大汗，本汗不會分給你。"],"greetFriendly":["天山的雪水清冽，你的問候也一樣爽快，本汗喜歡。","衛拉特的帳篷永遠留一席給敢直言的朋友，請坐。"],"greetCold":["問候收下。準噶爾的馬不輕易換主人，人也一樣。","本汗聽過太多好話，說完之後，多半跟著刀。"],"threatDefy":["本汗連清廷的大軍都敢正面迎擊，怕你這幾句話？","駝城列陣、火槍上膛，準噶爾人從不低頭。"],"threatYield":["這一回本汗退，退到天山腳下，草長起來再說。","輸過一陣不算輸，本汗先讓路，來日再見高下。"],"tributePay":["黃金{gold}兩拿去，準噶爾的馬匹和男兒不在其中。","本汗交出黃金{gold}兩，只為喘一口氣養回騎兵。"],"tributeRefuse":["衛拉特的黃金供佛不納貢，你要不到一兩。","本汗不服清廷，難道會服你？黃金一粒也沒有。"],"giftThanks":["禮物本汗收下，準噶爾人記恩也記仇，這次記恩。","天山的朋友不多，你算一個。回頭送你一匹好馬。"],"intel":["本汗的刀正對著{wars}，與{peace}暫時各守草場。","準噶爾正與{wars}交戰，和{peace}停戰休兵。"]}}]},"nations":{"Taiwan Indigenous":[{"name":"頭目","title":"部落頭目","era":"古代（通稱）","tone":"敬畏祖靈、與山海共生的長老，語氣質樸沉穩","portrait":"ti-historical-age0","lines":{"intro":["遠方來的客人，這片山林由祖靈看顧，請以敬意相待。","吾是這座部落的頭目，山風已把你的名字帶到吾耳邊。"],"contact":["你的族人望見了吾的部落，願他們帶著善意而來。","這裡的每一棵樹都認得吾族的腳步，外人請止步於溪邊。"],"war":["你踏過了祖靈立下的界石，吾族的獵人已拿起長矛。","為了守護族人與獵場，吾不得不與你為敵。"],"warReply":["你要戰？山林會記住你今日的選擇，祖靈與吾同在。","吾族世代在此，不曾懼怕風雨，也不會懼怕你。"],"peace":["干戈只會讓兩族的孩子挨餓，讓我們放下長矛吧。","吾願以小米與獸皮換取和平，你意下如何？"],"accept":["好，吾以祖靈之名起誓，從今日起兩族互不相犯。","你的誠意山林都聽見了，吾族願與你共飲一壺酒。"],"reject":["你的話語像雲霧一樣飄忽，吾不能拿族人的安危去賭。","界石尚未歸位，談和平還太早。"],"rebuff":["你不願和平，吾便繼續守在山口，等你改變心意。","既然如此，吾族會守住每一條溪流與山徑。"],"betray":["你的人夜裡闖進吾的獵場，誓約已被你自己打破。","祖靈看見了你的背信，吾族不再受誓約束縛。"],"truceEnd":["休養的日子已過，山林的風向變了，各自小心吧。","約定的月份已滿，從今往後，各憑本事守護家園。"],"attacking":["吾族的獵人已出發，他們熟悉每一條通往你城的小路。","山林的孩子從不輕啟戰端，但一旦出發，便不回頭。"],"attacked":["部落的柵欄已經傾倒，但吾族的心還沒有倒下。","火光照亮了家屋，吾仍會站在族人前面。"],"defeated":["吾將回到祖靈身邊，請善待這片土地與留下的人。","山還在，溪還在，吾族的名字會留在風裡。"],"victory":["祖靈庇佑了吾族，願你的族人也能找到安身之處。","戰事已了，吾不會踐踏敗者，山林容得下所有人。"],"allyAccept":["好，吾族與你結為兄弟，獵場的收穫願與你分享。","以羽飾與織布為證，兩族從今日起同進同退。"],"allyReject":["吾族習慣自己守護自己，暫時不需要盟友。","結盟之事關係全族，長老們尚未點頭，吾不能答應。"],"greetFriendly":["遠方的朋友，山風帶來你的問候，祖靈聽見了。","來吧，部落的火堆為你留了位置，一同分享獵物。"],"greetCold":["你的話語像霧，看不清真心，我先靜靜聽著。","山有山的界線，外人來意，容我慢慢看清。"],"threatDefy":["山林是祖靈的家，你的威嚇嚇不倒守山的人。","族人世代守著這片山，從不因吼聲退一步。"],"threatYield":["為了族人的安全，這次我退讓，請別再逼近獵場。","祖靈要我護住族人的性命，我暫且低頭，不再爭。"],"tributePay":["部落拿出{gold}黃金換平安，只求獵場安寧。","這{gold}黃金你收下，別再驚擾我們的山林。"],"tributeRefuse":["山林的獵物養活族人，沒有一分要獻給外人。","祖靈給的財富不送人，你的要求我不答應。"],"giftThanks":["你的禮物我收下了，部落會記得這份情誼。","祖靈見證這份心意，下次狩獵，分你一份獵物。"],"intel":["我們正與{wars}爭獵場，與{peace}已放下弓箭。","{wars}踏進了我們的山，{peace}則與部落互不侵犯。"]}},{"name":"頭目","title":"部落頭目","era":"中世紀（通稱）","tone":"務實圓融、看重貝珠交換與部落聯盟的頭目","portrait":"ti-historical-age1","lines":{"intro":["我是這片山海之間的頭目，貝珠與織布是我們的信物。","遠方的君主，你帶來的是貨物還是刀劍？我先聽聽再說。"],"contact":["你的人來到了我們的聚落，若想交換，請先放下武器。","這裡的貝珠與獸皮遠近聞名，但不是誰都能帶走。"],"war":["你的人強取我族的貝珠與獵物，這筆帳只能用矛來算。","各部落的頭目已在火堆前議定，聯手對抗你的侵犯。"],"warReply":["你選擇了刀劍而非交換，那就別怪我族的箭矢無情。","我族的先祖曾抵擋過海上來的強盜，你也不會例外。"],"peace":["打仗會讓貝珠蒙塵、田地荒蕪，不如我們重新談交換。","我願送上一串貝珠作為誠意，換取兩地的安寧。"],"accept":["好，這串貝珠就是我們的誓約，從此不再兵戎相見。","你的誠意我收下了，願兩地的商路重新暢通。"],"reject":["你上次的承諾還沒兌現，我不會再把貝珠交給空話。","部落的長老們不信你，我也不能違背他們的決定。"],"rebuff":["你不願談，貝珠我先收回，等你想清楚再說。","好吧，海潮會退也會漲，我們的門隨時為和平打開。"],"betray":["你的人趁夜闖入我族的糧倉，誓約已成碎片。","貝珠可以串起誓言，也可以被你親手扯斷，那就開戰吧。"],"truceEnd":["休戰的日子到頭了，往後的往來，就看各自的本事。","約定的期限已滿，我族已補足糧食與箭矢，你呢？"],"attacking":["各部落的戰士已在山口集合，今日一起走向你的城。","我族的人出發了，這次帶的不是貝珠，是弓與矛。"],"attacked":["聚落的圍籬已被攻破，但我族的人還守在家屋門前。","倉庫空了，貝珠散了，可我還站在這裡。"],"defeated":["把我的貝珠分給族人吧，讓他們記得我們曾經自由。","海潮還會再漲，我族的名字會隨浪回來。"],"victory":["戰事結束了，願你的族人平安，商路也將重新開放。","祖靈守住了我們的家園，我不會奪走敗者的尊嚴。"],"allyAccept":["好，我以最珍貴的一串貝珠為證，兩地從此結為盟友。","結盟之後，你的商人可以自由來我族交換貨物。"],"allyReject":["結盟是一輩子的承諾，我還不夠了解你。","各部落還沒商議妥當，此事容我再想想。"],"greetFriendly":["海上來的朋友，我們以檳榔與小米酒相迎。","你的問候如春雨落在小米田，部落歡迎你。"],"greetCold":["許多船帶來笑臉，也帶來刀劍，我還在看你是哪一種。","你的話先放在火堆旁，等長老們議過再回覆。"],"threatDefy":["山有多高，族人的骨氣就有多硬，你嚇不倒我們。","祖靈守著這片獵場千百年，不會因你一句話讓路。"],"threatYield":["部落人少，我不願族人白白犧牲，這回讓你一步。","為保住小米田與孩子，我暫且答應你的要求。"],"tributePay":["這{gold}黃金是用鹿皮換來的，拿去，別再擾我部落。","族人省下{gold}黃金給你，只盼獵場從此平靜。"],"tributeRefuse":["鹿皮與小米是族人的汗水，一粒也不獻給外人。","部落從不向人納貢，你的要求，我在此回絕。"],"giftThanks":["這份禮物很珍貴，部落會以最好的鹿皮回贈。","謝謝你的心意，我會在祭典上向祖靈提起你。"],"intel":["我們與{wars}爭奪獵場，與{peace}以鹿皮換鐵器。","{wars}的船曾侵擾海岸，{peace}則已與我們結盟。"]}},{"name":"甘仔轄 阿拉米","title":"大肚王","era":"約 1630–1640 年代（大肚王）","tone":"沉穩寡言、嚴守界線的諸社盟主","portrait":"ti-historical-age2","lines":{"intro":["本王是大肚諸社共推的王，過大肚溪之前，先報上名來。","本王甘仔轄阿拉米，向來少言，你的舉動會替你說話。"],"contact":["你的人來到了大肚溪畔，本王的規矩是：外人不得留宿。","這裡是二十餘社共守的土地，看看可以，別想在此建屋。"],"war":["你的人越過了本王劃下的界線，諸社已一同舉矛。","本王容忍過路，不容忍佔地，今日起與你為敵。"],"warReply":["大肚溪的水只會往海流，本王的頭也不會向你低。","你想開戰？諸社的戰士早已在溪岸列陣等候。"],"peace":["戰事拖久對兩邊都無益，本王願先收矛，你可願意？","只要你退出本王的界線，諸社可以與你相安無事。"],"accept":["好，本王允諾。你的人可以過路，但仍不得在此久留。","諸社已同意停戰，本王一言既出，絕不反悔。"],"reject":["你的條件本王聽過了，不夠。回去再想想。","本王少言，但不輕信；諸社的血汗不是幾句話能換的。"],"rebuff":["不願和談？隨你。大肚溪畔的守衛不會鬆懈。","本王已表明心意，你若執意用矛，本王奉陪。"],"betray":["你的人在本王境內私自建屋，誓約已被你踩碎。","本王守諾，你卻趁夜越界；諸社的矛再度舉起。"],"truceEnd":["休戰的日子到了盡頭，本王的界線依舊，看你怎麼走。","期限已滿，往後過溪的人，本王一個一個看清楚。"],"attacking":["諸社的戰士已渡過大肚溪，這回不是去看看而已。","本王親自領隊出發，你的城牆擋不住二十餘社的意志。"],"attacked":["本王的社寨已被圍困，但諸社的盟約還沒有斷。","牆倒了，本王仍守在溪岸，這是王該站的地方。"],"defeated":["本王倒下了，但大肚溪仍會流過諸社的田地。","請善待諸社的族人，他們只是想守住自己的家。"],"victory":["戰事已了。本王不奪你的土地，只要你記住界線在哪。","諸社守住了溪岸，本王向祖靈獻上今年的收穫。"],"allyAccept":["好，本王與你結盟。諸社的溪岸從此為你的人放行。","本王少與外人結交，你是例外，望你別讓本王失望。"],"allyReject":["本王的盟友只有大肚溪兩岸的諸社，外人免談。","結盟就是要開門，本王還不打算為你開這扇門。"],"greetFriendly":["本王代大肚各社問候，願你我如溪水般長流不斷。","遠客的問候已傳遍各社，來吧，共飲一杯小米酒。"],"greetCold":["紅毛人也曾說過好聽的話，本王習慣先聽，再慢慢看。","各社的安寧來自審慎，你的善意，容我多觀察幾季。"],"threatDefy":["大肚各社同氣連枝，你的威嚇拆不散這個聯盟。","連紅毛人進我領地都得先問過本王，你又有何資格發號施令？"],"threatYield":["本王審度情勢，各社不宜與你相爭，此事暫且依你。","為保各社不受戰火，我選擇退讓，這是頭領的擔當。"],"tributePay":["各社湊出{gold}黃金，換取你不越過大肚溪一步。","這{gold}黃金你收下，盼各社的鹿場能安穩一季。"],"tributeRefuse":["大肚的鹿皮只換鐵器與布匹，不獻給任何人當貢品。","各社推我為王，不是讓我替他們向外人納貢的。"],"giftThanks":["厚禮已收，本王會讓各社知道，遠方有位懂禮的君主。","承蒙贈禮，待鹿季一到，我以上好鹿皮回敬你。"],"intel":["本王直言，各社與{wars}對峙，與{peace}已結盟。","{wars}的兵曾犯我鹿場，{peace}則與大肚互不侵犯。"]}},{"name":"莫那魯道","title":"賽德克族馬赫坡社頭目","era":"1930 年（霧社事件）","tone":"沉痛堅毅、以祖訓與族人尊嚴為念的獵人頭目","portrait":"ti-historical-age3","lines":{"intro":["我是馬赫坡社的頭目莫那魯道，獵場與祖靈是我的一切。","遠方的君主，你若敬重祖訓與土地，我們可以說話。"],"contact":["你的人踏進了我族的獵場，這裡的山每一寸都有祖靈。","看見我的部落了？記住，這片山不是誰的財產。"],"war":["你奪走我族的獵場與尊嚴，今日我以祖訓之名宣戰。","族人不能一輩子低頭，我寧願站著面對你。"],"warReply":["你要戰？我族的男人自小便在山裡打獵，不怕你。","來吧。祖靈在看，彩虹橋的另一端沒有懦夫。"],"peace":["我不願族人的孩子再失去父親，我們暫且停手吧。","若你肯歸還獵場、尊重祖訓，我願放下獵刀談和。"],"accept":["好，我答應。祖靈為證，只要你守約，我便守約。","族人可以暫時休息了，願你言而有信。"],"reject":["你嘴裡說和平，手裡卻還握著我族的獵場，我不信。","祖訓教我們分辨真心與假意，你的提議我不能接受。"],"rebuff":["你拒絕了？那我只能繼續守在山上，等你回心轉意。","和平不是求來的，我族會用自己的方式守住家園。"],"betray":["你的人又闖進我族的獵場，那份誓約已經不算數了。","我曾相信你的話，如今祖靈告訴我，該拿起獵刀了。"],"truceEnd":["休戰結束了，山上的霧散去，該看清彼此的路了。","約定的日子已過，往後每一步，都要對得起祖靈。"],"attacking":["馬赫坡的男人已經出發了，這是為了族人的尊嚴。","我族的獵人熟悉每一道山脊，你的城牆擋不住山風。"],"attacked":["部落已被圍困，但真正的賽德克人，到最後都不會低頭。","家屋燒了，獵場沒了，可祖靈還在我身後。"],"defeated":["我要走過彩虹橋去見祖靈了，請讓我的族人留在山上。","山會記得我們，這片獵場永遠屬於祖靈。"],"victory":["族人守住了獵場，我向祖靈報告：我們沒有低頭。","戰事結束了。你走吧，這片山從來不需要主人。"],"allyAccept":["好，我族與你結盟。獵場的路為你敞開，祖靈為證。","能有一個尊重祖訓的朋友，是族人的福氣。"],"allyReject":["我族的路要自己走，結盟的事，恕我婉拒。","你還不明白祖訓的分量，我不能把族人的命運交給你。"],"greetFriendly":["遠方的朋友，馬赫坡的獵人以真心待你，來喝一杯吧。","你以禮相待，賽德克人便以禮相還，願山風帶去我的問候。"],"greetCold":["許多人來時笑臉相迎，後來卻要我們搬木頭，我不輕信。","你的問候我聽見了，但獵人分辨得出誠意與算計。"],"threatDefy":["賽德克人可以失去一切，唯獨不能失去尊嚴，你儘管來。","祖靈在彩虹橋那頭看著，我莫那魯道從不向威嚇低頭。"],"threatYield":["為了族人，我暫且忍下這口氣，但賽德克人不會忘記。","馬赫坡的孩子還小，這一次我讓步，換他們平安長大。"],"tributePay":["這{gold}黃金你拿去，別再踏進馬赫坡的獵場。","族人湊出{gold}黃金，換孩子們一季的安穩，僅此一次。"],"tributeRefuse":["日本警察沒能從我這裡拿走尊嚴，你也別想拿走黃金。","獵場的一草一木都是祖靈的，賽德克人不向任何人納貢。"],"giftThanks":["你的禮物我收下，馬赫坡的火堆永遠為朋友多添一把柴。","謝謝，賽德克人不常收禮，但收了就一輩子記得。"],"intel":["我與{wars}正在山裡對峙，與{peace}已放下獵槍。","{wars}逼得族人喘不過氣，{peace}則相安無事。"]}}],"North Korea":[{"name":"東明聖王（朱蒙）","title":"高句麗始祖、開國之君","era":"前 37～前 19 年在位","tone":"直率豪邁的青年開國之君，語句簡短有力，常以弓箭為喻；對強者不卑不亢，偶爾提及在扶餘受排擠、南下建國的經歷。","portrait":"nk-historical-age0","lines":{"intro":["寡人朱蒙，自扶餘南來，於卒本立高句麗之國。","這張弓隨寡人渡過重重險阻，如今要為新國守土。"],"contact":["卒本城雖新築，城中將士皆隨寡人出生入死。","貴國的人望見寡人的城了？回去告訴君上，這裡有主。"],"war":["寡人的箭矢從不虛發，此番便以貴國為靶。","高句麗立國於群強之間，不進則亡。寡人今日興兵。"],"warReply":["寡人自幼在扶餘受人排擠，早已慣於以少敵眾。","你要戰？好，寡人正想試試新弦的力道。"],"peace":["弓拉滿了也該放鬆。寡人願與貴國暫且息兵。","新國初立，百姓需要耕種。寡人提議停戰，如何？"],"accept":["好，寡人應允。卒本的弓，今日先掛回牆上。","寡人一言既出，絕不反悔。從今日起，兩國相安。"],"reject":["停戰？寡人的箭還在弦上，此時收手，為時尚早。","貴國先動刀兵，如今卻談和？寡人不信這樣的話。"],"rebuff":["不願意？也罷。寡人的提議只說一次。","既然貴國無意言和，寡人便把弓再取下來。"],"betray":["寡人為了高句麗的存續，只能背棄前約，莫怪。","時勢已變，昨日的盟約，今日便是束縛。寡人撕約。"],"truceEnd":["休戰之期已滿，寡人的將士也養足了精神。","約定的日子到了。往後如何，就看貴國的選擇。"],"attacking":["寡人親自帶隊，箭在弦上，直指貴國城門。","卒本的將士已經出發。貴國城牆高不高，很快便知。"],"attacked":["城牆在崩，寡人卻仍站在城頭。這弓，還能再拉一次。","卒本是寡人親手所建，寡人絕不先走一步。"],"defeated":["寡人自扶餘南來建國，一生未曾退縮。今日，也不會。","高句麗的名字，會由後人繼續記得。寡人無憾。"],"victory":["箭已落定，勝負分明。寡人收弓，不再多言。","從扶餘一路走來，寡人早習慣了以弱勝強。"],"allyAccept":["好，寡人與貴國結盟。同拉一張弓，箭才射得遠。","寡人建國時靠的正是志同道合之士。貴國，便是新友。"],"allyReject":["寡人靠自己的弓立國，暫不需要盟友的弓。","結盟之事，貴國誠意尚不足。容寡人再看一陣子。"],"greetFriendly":["貴國的使者遠道而來，寡人以卒本的山珍相待。","問候收到了。願貴國田畝豐收，寡人也同樣祝福。"],"greetCold":["問候？寡人正在練箭，貴國的話，改日再聽。","信已讀過。寡人與貴國尚無交情，不必多禮。"],"threatDefy":["威嚇寡人？扶餘的王子們也曾這麼做，如今寡人已是一國之君。","寡人的箭百步之外可中鵠，貴國的恐嚇，射不到寡人。"],"threatYield":["高句麗初立，寡人不願輕啟戰端。貴國的話，寡人記下了。","寡人此時兵少，暫且退讓。但這口氣，寡人記著。"],"tributePay":["寡人送上 {gold} 金，為保卒本百姓安穩，只得如此。","{gold} 金交予貴國。寡人記得今日，來日必當討回。"],"tributeRefuse":["貢品？寡人的金子要用來築城養兵，一分也不給。","高句麗不向任何人納貢。貴國若要，來卒本取。"],"giftThanks":["貴國的禮物寡人收下了。卒本雖小，禮數不缺。","多謝厚禮。寡人日後定有回敬，不會讓貴國白送。"],"intel":["寡人的斥候回報：與 {wars} 交戰中，與 {peace} 相安無事。","據寡人所知，{wars} 正動刀兵，{peace} 則已息戰。"]}},{"name":"大祚榮（渤海高王）","title":"渤海開國君主・高王","era":"698～719 年在位","tone":"沉穩剛毅、言語簡短有力，帶著亡國遺民重新立國的堅韌與豪氣，自稱「寡人」。","portrait":"nk-historical-age1","lines":{"intro":["寡人乃高句麗遺民大祚榮，於東牟山立國，願與君相識。","國破之後，寡人率舊部東奔，於東牟山重築家園。"],"contact":["東牟山下的城池，是寡人與遺民一磚一石築起的。","君的探子看見城牆了嗎？那裡住著不肯低頭的高句麗人。"],"war":["寡人曾在天門嶺擊退唐軍，今日也不懼與君一戰。","君屢侵我疆界，寡人忍無可忍，震國之師即刻出動！"],"warReply":["唐軍尚且過不了天門嶺，君以為自己能做到嗎？","好，寡人正等著。遺民之國，不是誰都踏得平的。"],"peace":["刀兵久動，百姓難安。寡人願與君暫止干戈。","寡人建國不為征伐，只求遺民安居。停戰如何？"],"accept":["好，寡人應允。東牟山的誓言，比鐵甲更堅固。","君有此意，寡人欣然接受。願兩國自此相安。"],"reject":["寡人在天門嶺學會一件事：退讓換不來太平。","此時談和，未免太遲。寡人不允。"],"rebuff":["君不願息兵，寡人也不強求。且看誰先撐不住。","既然如此，寡人便整軍以待。遺民從不怕苦戰。"],"betray":["寡人為遺民復國，有些事不得不為。停戰到此為止。","君的城池擋住了我族的生路，寡人只能撕毀盟約。"],"truceEnd":["休戰之期已滿，兩國自此各憑本事。","約定的日子到了。寡人不會先動手，但也不再退讓。"],"attacking":["高句麗與靺鞨的勇士已集結，正朝君的城池而去。","寡人親率大軍出東牟山，君可準備迎戰了。"],"attacked":["城牆將傾……但寡人當年也是從廢墟中站起來的。","東牟山危急！遺民們，隨寡人再守最後一道城門！"],"defeated":["高句麗亡過一次，寡人不信它不能再起……","寡人倒下了，但遺民的血脈，會在別處生根。"],"victory":["從東牟山到此地，寡人走了很遠。這一勝屬於遺民。","天門嶺之後，寡人再一次證明：亡國之民也能立國。"],"allyAccept":["寡人與君結盟。亡國之痛，寡人不願君也嘗到。","好，兩國聯手。東牟山的大門，自此為君敞開。"],"allyReject":["寡人的國剛立，根基未穩，暫不宜與人結盟。","結盟須以誠相待，寡人尚未看清君的心意。"],"greetFriendly":["君遠道致意，寡人甚喜。東牟山雖僻，待客不薄。","來信已閱。願君的國與寡人的國，皆能長久安寧。"],"greetCold":["信已收到。寡人忙於築城安民，無暇多言。","君的問候寡人記下了。至於交情，日後再說。"],"threatDefy":["唐軍的恐嚇寡人都不曾理會，君的又算什麼？","想嚇退高句麗遺民？君先去問問天門嶺的唐軍。"],"threatYield":["寡人的國尚小，不願與君硬碰。暫且退讓便是。","為了遺民能活下去，寡人今日忍下這口氣。"],"tributePay":["寡人送上 {gold} 金，換東牟山百姓一時安寧。","{gold} 金已備妥。遺民的血汗，望君善用。"],"tributeRefuse":["遺民的每一分糧食都來之不易，寡人一文不給。","寡人立國是為了不再受人索取，君請回吧。"],"giftThanks":["君的厚禮寡人收下了。北地苦寒，此情格外溫暖。","多謝相贈。寡人以東牟山的貂皮回禮，望君笑納。"],"intel":["據寡人所知，{wars} 正在交戰，{peace} 已經停戰。","探子回報：{wars} 兵戎相見；{peace} 則暫時休兵。"]}},{"name":"李成桂","title":"朝鮮太祖","era":"1392–1398 年在位","tone":"老將出身的開國君主，寡言剛硬、講究實際與天命，話短而重，自稱「寡人」","portrait":"nk-historical-age2","lines":{"intro":["寡人李成桂，朝鮮開國之君。有話直說，寡人不喜客套。","寡人生於咸鏡道，一張弓打下了這片江山。"],"contact":["你的人來看漢陽城？好好看，這是寡人親自選的都城。","城牆是石頭砌的，比高麗的舊城更牢固。"],"war":["寡人在威化島回軍時就明白，猶豫的人打不贏仗。宣戰。","寡人年紀雖大，弓還拉得開。你準備好了嗎？"],"warReply":["你要打？好，寡人打了一輩子仗，不差這一場。","倭寇與紅巾賊皆敗於寡人之手，你也不例外。"],"peace":["打夠了。寡人年事已高，想看百姓種田，不想看戰場。","戰事拖久對誰都沒好處，寡人提議停戰。"],"accept":["可以。寡人一言既出，絕不反悔。","好，就這麼定了。寡人要回去治國了。"],"reject":["現在停？寡人的軍隊才剛熱身，不行。","寡人不信你的話。先把兵撤了，再談。"],"rebuff":["不接受就算了。寡人不會再問第二次。","你自己選的路，寡人成全你。"],"betray":["時勢變了，寡人只能對不住你了。","當年寡人也曾對高麗效忠，最後還是選擇了天命。"],"truceEnd":["休戰到期。寡人的弓弦，也該重新上緊了。","和平結束了。接下來，看各自的本事。"],"attacking":["寡人親自領軍。你會看到，老將是怎麼打仗的。","朝鮮大軍已渡過臨津江，直取你的都城。"],"attacked":["漢陽被圍……寡人打下的江山，竟被人打到門口。","兒孫們，若寡人不在了，替朝鮮守住這座城。"],"defeated":["寡人一生征戰無數，今日敗了，也無話可說。","朝鮮的江山……就交給後人吧。"],"victory":["贏了。寡人五十七歲開國，今日再添一筆功業。","天命在朝鮮，此戰便是明證。"],"allyAccept":["寡人不輕易與人結盟，但你值得信賴。好。","結盟可以。但你若背叛，寡人的弓不會留情。"],"allyReject":["寡人自己的仗自己打，不勞你費心。","朝鮮剛立國，不宜與外邦結盟。你請回吧。"],"greetFriendly":["你的信寡人看了。有誠意，寡人也以誠相待。","新朝初立，多一個朋友是好事。坐。"],"greetCold":["寡人不喜客套。有事直說。","信收到了。無事便不必再寫。"],"threatDefy":["寡人一生征戰，倭寇也好，紅巾也罷，沒怕過。","你的威脅太輕了。寡人手上的弓比這重。"],"threatYield":["新朝根基未穩，寡人不與你爭這一時。","寡人知道什麼仗該打，什麼仗不該打。這次不打。"],"tributePay":["{gold} 金，拿去。打仗更貴，寡人算過。","給你 {gold} 金。這是買時間，不是低頭。"],"tributeRefuse":["朝鮮只向大明朝貢，你還不夠格。回去。","寡人一毛不給。想要，自己來拿。"],"giftThanks":["禮收下了。寡人不多話，這份情記著。","有心。寡人回你一張好弓，別浪費。"],"intel":["探子回報：{wars} 在打仗，{peace} 沒動靜。","寡人只說一次。{wars} 正交兵，{peace} 無戰事。"]}},{"name":"高宗（李熙）","title":"大韓帝國皇帝（朝鮮第二十六代王）","era":"1863–1907 年在位（1897 年稱帝）","tone":"溫和有禮、憂心國事，說話帶外交辭令與幾分無奈，自稱「朕」","portrait":"nk-historical-age3","lines":{"intro":["朕乃大韓帝國皇帝。世局多變，願與貴國以禮相交。","朕的國家雖小，卻有五百年社稷，望君以誠相待。"],"contact":["貴國使者已至漢城？請看，慶運宮的電燈已亮起了。","朕的都城裡，古殿與新式電車並存，正如朕的處境。"],"war":["朕不願開戰，但貴國逼人太甚，大韓帝國唯有一戰。","朕忍讓已久，今日為了社稷，不得不宣戰。"],"warReply":["貴國竟向朕宣戰？朕會請各國公使見證此事。","大韓雖弱，亦有骨氣。朕的軍隊不會不戰而降。"],"peace":["戰事不利兩國，朕願先伸出手，請貴國考慮停戰。","朕的百姓已受夠戰火，望貴國與朕共謀和平。"],"accept":["朕接受。願此約如朕所盼，為東亞帶來安寧。","甚好，朕即刻下詔停戰，兩國重修舊好。"],"reject":["朕恐怕不能答應。貴國先前的承諾，朕記憶猶新。","朕的大臣們反對停戰，朕也難以獨斷。請容再議。"],"rebuff":["貴國拒絕了……朕很遺憾，但朕不會放棄努力。","朕已盡力，若貴國執意如此，朕也只能應戰。"],"betray":["朕無意背信，但國家存亡之際，朕別無選擇。","盟約已無法保護朕的子民，朕只好另尋出路。"],"truceEnd":["休戰期滿。朕希望貴國記得，和平來之不易。","約定之期已到，朕祈願兩國不必再兵戎相見。"],"attacking":["大韓帝國的新式軍隊已出發，朕親自檢閱過了。","朕不得不出兵。願上天保佑朕的將士平安歸來。"],"attacked":["漢城危急……朕的宮殿，難道又要淪為戰場？","朕不會離開宮殿。若社稷將傾，朕與它同在。"],"defeated":["五百年社稷，終於朕手……朕愧對列祖列宗。","朕的國雖亡，但這片土地上的人民不會忘記自主。"],"victory":["大韓帝國竟也有勝利的一日，朕感謝將士們。","此戰之後，望列強明白，大韓非任人擺布之國。"],"allyAccept":["朕正需要盟友。願貴國與大韓帝國同舟共濟。","甚好，朕將以最高規格接待貴國使節。"],"allyReject":["朕深感抱歉。此刻與貴國結盟，恐招他國猜忌。","朕的處境艱難，結盟一事，請容朕再三思量。"],"greetFriendly":["貴國的問候，朕深感欣慰，願兩國情誼長存。","亂世之中能得一友，朕心甚慰，請多往來。"],"greetCold":["來信朕已閱過。國事繁重，恕朕無暇多敘。","朕近日憂心國事，實在無心寒暄，請見諒。"],"threatDefy":["大韓帝國雖弱，也是堂堂獨立之國，不受威嚇。","朕已見過太多強權的威脅，不會再輕易低頭。"],"threatYield":["朕不願百姓再受兵禍，此事就依貴國所請吧。","列強環伺，朕實在無力再樹一敵，暫且退讓。"],"tributePay":["朕送上 {gold} 金，只盼貴國念在情面，勿再相逼。","這 {gold} 金就當作朕的一點心意，換得片刻安寧。"],"tributeRefuse":["國庫已為條約所困，朕實在無力再納貢。","朕以外交立國，不以金銀求存，恕難從命。"],"giftThanks":["貴國厚禮，朕感激不盡，這份情誼朕記在心。","有心了。朕命人備下高麗人參回贈，聊表謝意。"],"intel":["據朕所知，{wars} 正處交戰，{peace} 尚且平靜。","電報所傳：{wars} 兵戎相見，{peace} 相安無事。"]}}],"Vietnam":[{"name":"徵側","title":"交趾徵王","era":"西元40～43年在位","tone":"剛烈果決、重義守諾，說話直接有力，帶著為夫報仇與護民的決心；自稱「本王」","portrait":"vn-historical-age0","lines":{"intro":["本王徵側，麊泠之女，交趾六十五城皆聽本王號令。","你若敬我雒越百姓，本王以禮相待；若輕視，銅鼓自會回答。"],"contact":["你的人踏進了麊泠地界，城中的銅鼓已經看見他們。","江畔的城是雒越百姓一手築的，你的人要看便看，別動手。"],"war":["蘇定那樣的暴虐，本王已忍過一次，不會再忍第二次。","擊鼓！雒越的兒女，隨本王上陣，讓他知道交趾不好欺。"],"warReply":["好，你既然選了刀劍，本王便用刀劍回答你。","漢家郡守都趕得走，本王還會怕你的旗幟嗎？"],"peace":["打夠了吧？百姓要回田裡插秧，本王願與你暫且停戰。","本王起兵是為了雒越安寧，不是為了殺伐，休兵如何？"],"accept":["好，本王應允。雒越人說出的話，如銅鼓之聲，不會反悔。","收起刀劍吧，本王與你以江水為誓，各守疆界。"],"reject":["你的人還踩在我的田上，這種停戰，本王不要。","交趾的仇還沒討回，本王怎能對你說一個「和」字？"],"rebuff":["你不肯？也罷，雒越的兒女從不怕多打一場。","本王伸出的手你不接，那就別怪本王再握回劍柄。"],"betray":["對不起百姓的和約，本王寧可撕了它，也不願守。","你趁停戰暗中築壘，別怪本王先擊鼓了。"],"truceEnd":["江水為誓的日子已滿，此後各憑本事。","休戰到此為止，本王的銅鼓又要響了，你可準備好？"],"attacking":["六十五城的勇士已隨本王出發，戰象踏碎你的城門。","麊泠的鼓聲你聽見了嗎？那是本王的大軍向你而來。"],"attacked":["城牆塌了，鼓聲卻沒停，本王還站在這裡。","雒越的兒女一個個倒下，本王仍不會向你低頭。"],"defeated":["本王曾讓交趾抬起頭來，這一點，你奪不走。","就讓江水記住，曾有一對姊妹為雒越百姓而戰。"],"victory":["勝了！這不是本王一人的勝利，是雒越百姓的勝利。","銅鼓聲傳遍六十五城，從今往後，沒有人能再欺壓交趾。"],"allyAccept":["好，本王與你結盟。你護我百姓，本王便護你城池。","雒越人重情義，你今日相助，本王來日必以命相報。"],"allyReject":["本王剛掙脫一個外人的手，不會再把交趾交給另一個。","結盟之事，容本王先問過六十五城的族長再說。"],"greetFriendly":["你的信本王收到了，遠方來意誠懇，本王記在心上。","麊泠的城門為朋友而開，願你我同心護民。"],"greetCold":["本王正忙於軍務，客套話留到戰後再說吧。","信已讀過，交趾不需空言，只看你如何行事。"],"threatDefy":["漢家太守嚇不倒本王，你的威嚇更算什麼！","六十五城已隨本王起兵，來吧，本王在麊泠等你。"],"threatYield":["交趾初定，百姓不堪再戰，本王暫且忍下這口氣。","為護子民，本王退讓一步，但此事本王會記得。"],"tributePay":["為免百姓再遭兵禍，本王送上{gold}金，望你守信。","這{gold}金是麊泠子民的血汗，本王暫且交付，你莫忘記。"],"tributeRefuse":["本王起兵正為抗拒橫徵暴斂，豈會再向他人納貢！","交趾的糧與金，只用來養百姓，一粒也不給你。"],"giftThanks":["禮物本王收下了，這份情義，本王會以情義相報。","在這烽火之際仍記得交趾，本王謝你的心意。"],"intel":["本王正與{wars}交戰，與{peace}相安無事。","本王的敵人是{wars}，與{peace}並無仇怨。"]}},{"name":"李太祖（李公蘊）","title":"李朝開國皇帝","era":"1009～1028年在位","tone":"沉穩慈和、有佛門氣度，眼光長遠，講求根基與子孫萬世之計；自稱「朕」","portrait":"vn-historical-age1","lines":{"intro":["朕乃李公蘊，上謹天命，下因民志，於昇龍立都。","佛門教朕慈悲，江山教朕謹慎，願與你以善相交。"],"contact":["你的人所見之城，龍蟠虎踞，是朕為子孫萬世所擇之地。","昇龍城門為客而開，也為守土而閉，端看來者何心。"],"war":["朕不喜征伐，然你屢犯邊民，佛亦有怒目金剛之相。","為護萬民安居，朕今日親率大越之師向你問罪。"],"warReply":["你既執意動兵，朕也只好放下念珠，拿起長槍。","昇龍之地龍氣所鍾，豈是刀兵所能撼動？來便來吧。"],"peace":["兵者凶事，朕願與你罷戰，讓兩國百姓各安其業。","稻田荒了才是真正的損失，你我不如就此休兵。"],"accept":["善哉。朕應允此約，願兩國從此鐘聲相聞，不聞鼓聲。","朕以昇龍之名允諾，此約如城基之石，不輕移動。"],"reject":["你邊談和，邊集結兵馬，朕雖慈悲，卻不糊塗。","此時言和，是要朕棄邊民於不顧，朕做不到。"],"rebuff":["你不願休兵，朕不強求，只盼你莫要後悔今日之言。","也罷，緣分未到。昇龍的城牆，會替朕繼續等你。"],"betray":["朕本欲守約，但你暗中蠶食邊境，此約已被你自己毀了。","佛說因果，你先種下惡因，朕今日不過是了結此果。"],"truceEnd":["約期已滿，朕不再受盟約所縛，你我各自珍重。","休兵之期到了，願你這些年學會了與鄰為善。"],"attacking":["大越之師已出昇龍，戰象在前，朕在其後，向你而來。","朕已在城中佛寺焚香祝禱，願此戰速決，少傷人命。"],"attacked":["昇龍城牆在你砲石下震動，朕仍坐於殿中，不曾離座。","城可破，寺可毀，朕為百姓擇的這片土地不會消失。"],"defeated":["朕擇此地本為萬世之計，天不假年，但願後人續之。","龍已騰起，便不會再落回地上。朕去矣，昇龍仍在。"],"victory":["此勝非朕一人之功，是萬民之志、天命所歸。","戰事已了，朕當敕建佛寺，為兩國亡者祈福。"],"allyAccept":["朕允你之盟，兩國如舟楫並行，同渡江河。","善緣既結，朕必守之，願昇龍與貴國世代為友。"],"allyReject":["朕方定新都，根基未穩，此時結盟，恐難盡盟友之責。","大越願與四鄰為善，卻不願被綁上他人的戰車。"],"greetFriendly":["來信朕已細讀，昇龍城新建，願與君共享太平。","君遠道致意，如春風入寺，朕心甚慰。"],"greetCold":["朕知道了。國基未穩，朕無暇多敘。","書信已閱，君之心意，朕留待日後再看。"],"threatDefy":["朕遷都昇龍，正為萬世之基，豈懼一時之威嚇。","我國山川險固，民心可依，君的威嚇朕不放在心上。"],"threatYield":["新朝初立，朕不願百姓再受刀兵之苦，姑且依你。","佛法教人忍辱，朕暫退一步，以保國基。"],"tributePay":["朕以{gold}金換一時安寧，望君亦守信義。","這{gold}金取自國庫，朕交付於君，只求百姓免於兵禍。"],"tributeRefuse":["國庫之財，當用於築城養民，朕不會交予外人。","朕方遷都，府庫皆用於安民，君之所求，恕難應允。"],"giftThanks":["君之厚禮，朕已收下，願以此結兩國長久之好。","此禮朕將供於寺中，為君祈福，以謝情誼。"],"intel":["朕與{wars}有兵戈之事，與{peace}相安無事。","據朕所知，{wars}與我交戰，{peace}與我修好。"]}},{"name":"黎聖宗（黎思誠）","title":"大越皇帝","era":"1460～1497年在位","tone":"儒雅自信、學者氣質，言談引經據典，重法度、重國土完整；自稱「朕」","portrait":"vn-historical-age2","lines":{"intro":["朕乃大越皇帝黎思誠，年號洪德，願以文治與四方相見。","大越雖在南方一隅，法度文章不讓於人，請你記住這點。"],"contact":["你的人見到的，是朕的京城昇龍；城裡讀書聲比刀劍聲響亮。","洪德版圖上早已繪明疆界，望你的人看過便退，莫越雷池。"],"war":["太祖留下的山河，一尺一寸都不可讓人，朕今日對你宣戰。","朕以詩書治國，也以律法治軍，你將見識洪德之師的紀律。"],"warReply":["你向大越宣戰？很好，朕的史官會如實記下這一日。","占城之役後，朕本不欲再動干戈，既然你要，朕便奉陪。"],"peace":["干戈久動，田野荒蕪，朕願與你罷兵，各修文治。","讓百姓歸田，讓士子歸學，此為朕提議停戰之本意。"],"accept":["朕允之。此約當書於史冊，朕與你皆不可負。","善。朕將設宴騷壇，以詩紀念今日之和。"],"reject":["疆界未定，談何停戰？先把你的兵撤出洪德版圖之外。","朕讀遍經史，深知此時言和，只會養虎為患。"],"rebuff":["你不肯停戰？無妨，朕的律法與軍陣，都等得起。","朕已盡君子之道，你既拒之，日後史書自有公論。"],"betray":["盟約之所以存在，是因雙方守信；你既不守，朕何必獨守？","朕重法度，但更重社稷。為保江山，此約朕只得棄之。"],"truceEnd":["約期已滿，盟書歸檔，此後兩國各憑德行與武備。","休戰之期到了，願你這幾年也修了些文治。"],"attacking":["洪德之師已依律出征，隊列如書卷齊整，向你而來。","朕親征時軍中一律不得擾民，你的百姓也可安心。"],"attacked":["昇龍城牆震動，朕仍在殿上批閱奏章，史官莫要停筆。","城池可失，典章猶在；只要書冊不燬，大越就不會亡。"],"defeated":["朕修史、定律、繪圖，留給後世的已夠多了，去吧。","江山易主，文章不朽。史官，把今日也如實記下。"],"victory":["勝矣。朕不喜殺伐，只喜疆界從此分明、百姓安居。","此戰當入國史，讓後人知道洪德年間大越之強。"],"allyAccept":["朕允此盟。兩國以文會友、以義相守，勝過千軍。","善。盟約書於絹帛，藏於史館，朕與你共守之。"],"allyReject":["大越自有法度，不輕與人結盟，此事容後再議。","朕觀你行事，尚未見足以託付的信義，恕朕不允。"],"greetFriendly":["來書文采可觀，朕讀之欣然，願與君詩書往還。","有朋自遠方來，不亦樂乎？朕在昇龍靜候佳音。"],"greetCold":["朕已閱。禮者，貴在誠意，君之來信尚欠火候。","朕日理萬機，修律定典，君的問候留待他日再議。"],"threatDefy":["一寸山河，朕不容他人染指，君之威嚇徒增笑柄。","占城之鑑猶在眼前，君若執意相逼，朕不惜以兵相見。"],"threatYield":["君子不與力爭，朕暫且退讓，以全大局。","書曰滿招損，謙受益，朕此番姑且退讓一步。"],"tributePay":["朕依禮送上{gold}金，此為權宜之計，望君謹記。","取{gold}金予君，暫息紛爭，然此例不可再開。"],"tributeRefuse":["國庫出納皆有律法，朕豈能隨君所求任意予人。","納貢乃屬國之禮，大越非君屬國，此議免談。"],"giftThanks":["君之贈禮，朕已收下，投桃報李，朕自不忘。","禮輕情意重，朕當以詩相和，以謝君之雅意。"],"intel":["朕如今與{wars}交戰，與{peace}修好。","奏報所載，{wars}與朕交兵，{peace}相安無事。"]}},{"name":"嘉隆帝（阮福映）","title":"阮朝開國皇帝","era":"1802～1820年在位","tone":"歷經流亡與長年征戰，沉著堅毅、務實謹慎，言語簡練帶江湖氣，重恩仇、重統一；自稱「朕」","portrait":"vn-historical-age3","lines":{"intro":["朕是嘉隆帝阮福映，經二十五年征戰，方使南北歸於一統。","朕曾流亡海上、寄人籬下，深知一國之君該說話算話。"],"contact":["你的人看見的是順化，朕親自擇址築的京城，香江在旁。","這座城的每一塊磚，都是朕用半生流離換來的，請自重。"],"war":["朕統一越南的路走了二十五年，不會讓你在半途把它拆了。","西山軍朕都打贏了，你的兵，朕自然也能應付。"],"warReply":["你要打？朕從十幾歲就在打仗，這條路朕比你熟。","好，朕接下你的戰書。順化城的砲已經填好火藥了。"],"peace":["朕打了半輩子仗，深知百姓要的是安穩，不如停戰吧。","兵戈太久，田地荒了，稅收也沒了，你我都不划算。"],"accept":["好，朕答應。朕流亡時受人一飯之恩尚且不忘，何況盟約。","就這麼定了。朕的話，比順化的城牆還硬。"],"reject":["你一邊談和，一邊往邊境調兵，這種和，朕不談。","朕吃過太多虧，學會了看人先看手，你的手還握著刀。"],"rebuff":["不肯就不肯，朕也不是第一次被人拒絕，走著瞧。","也罷。朕曾在暹羅等了幾年才等到機會，不差這一回。"],"betray":["朕守約到今日，是你的人先過界，這帳不能算在朕頭上。","江山是朕一寸寸打回來的，若盟約礙了江山，朕只能撕。"],"truceEnd":["約期到了。這幾年朕沒閒著，城牆加厚了，你呢？","停戰到此為止，接下來各憑本事，朕不會客氣。"],"attacking":["朕的水師已從順化出港，這一仗朕親自督陣。","二十五年打下來的軍隊，今日全數向你而去，好自為之。"],"attacked":["順化城牆快撐不住了？朕年輕時連城都沒有，照樣活下來。","你可以攻破這座城，但攻不破朕從流亡中練出的骨頭。"],"defeated":["朕花二十五年把越南合而為一，這份基業，你得替朕守好。","從流亡到登基，朕已走完該走的路，無憾。"],"victory":["朕贏了。又一次。這次不是靠運氣，是靠二十五年的耐心。","南北一統的越南，不是誰想動就能動的，記住這點。"],"allyAccept":["朕落難時受過外邦相助，深知盟友的分量，這盟朕結。","好，從今日起，你的敵人就是朕的敵人，朕說到做到。"],"allyReject":["朕借過外人的力，也知道那筆帳有多難還，恕不結盟。","越南剛剛安定，朕暫不想捲入他人的爭端，見諒。"],"greetFriendly":["信到了。朕漂泊多年，知道朋友可貴，你的問候朕記下。","順化城剛安定下來，你若有意結交，朕歡迎。"],"greetCold":["信收到了。朕不好客套，有事直說。","朕征戰半生，見過太多虛情假意，你的問候先放著。"],"threatDefy":["朕從富國島的逃亡走到今天，這點威嚇算不了什麼。","西山軍都沒能把朕打倒，你要動手，朕奉陪到底。"],"threatYield":["南北剛統一，百姓經不起再戰，朕這回讓你。","朕忍過二十多年，這一時也忍得下，此事朕先記著。"],"tributePay":["{gold}金給你，換朕的百姓幾年安穩，划算。","朕送上{gold}金，記住，這是交情，不是臣服。"],"tributeRefuse":["朕打了幾十年仗才有這江山，一兩金也不會白給。","貢品？朕欠的恩會還，但朕不欠你的。"],"giftThanks":["禮物朕收下了。朕記恩也記仇，這份恩情朕會還。","落難時受過人恩，朕最懂這份心意，多謝。"],"intel":["朕直說：{wars}是朕的對手，{peace}與朕無事。","眼下朕與{wars}開戰，跟{peace}保持和平。"]}}],"Thailand":[{"name":"湄南河聚落族長","title":"族長","era":"約西元前 3 世紀～西元 2 世紀","tone":"質樸、敬天、守護家園、沉穩寡言","portrait":"th-historical-age0","lines":{"intro":["我是湄南河畔的族長，河水養活我們，也守護我們。","遠方來的君主，願你的稻田年年都有好收成。"],"contact":["你的人踏進了我們的稻田，請告訴他們別踩壞秧苗。","陌生人看見我們的竹屋了，是客人還是敵人，由你決定。"],"war":["你們搶走了我們的漁場，族人已經拿起木矛。","河神見證，我們不會把家園讓給外人。"],"warReply":["你要打我們的村子？河邊的人不怕水，也不怕你。","既然你選了刀矛，我們就用叢林和雨季回答你。"],"peace":["打下去兩邊的稻都會爛在田裡，收起矛吧。","我提議以河為界，各自捕魚，互不侵擾。"],"accept":["好，我以祖靈之名答應，從今日起放下木矛。","你的誠意我收下了，來，一起喝一碗米酒。"],"reject":["你燒了我們的糧倉，現在才說要停戰，太遲了。","族人的傷還沒好，我沒辦法答應你的話。"],"rebuff":["你不肯停手也罷，我們會守到雨季來臨。","既然如此，湄南河會記得今天是誰選擇了戰爭。"],"betray":["對不起，族人餓了，我只能為他們做這個決定。","河水已經改道，我們的約定也隨它走了。"],"truceEnd":["約定的日子到了，矛與網都已備好，看你怎麼選。","休戰結束，我不會先動手，但也不會退讓。"],"attacking":["全族的獵手都出發了，你的城牆擋得住山林之子嗎？","我們順著河流而下，你的人很快會聽見鼓聲。"],"attacked":["竹屋燒起來了……族人們，護住孩子和稻種！","你的兵已到河邊，但我們的根還在這片土地裡。"],"defeated":["把我的族人好好安置……河水會記得我們的名字。","聚落沒了，但這片稻田會永遠長出泰地的子孫。"],"victory":["戰爭結束了，河水依舊，稻穗依舊，這就是我們的勝利。","我不要你的城，我只要你記得別再踏進我們的田。"],"allyAccept":["好，從今日起你的族人就是我的族人，共享漁獲。","願我們兩族的孩子在同一條河裡學會游泳。"],"allyReject":["我們的稻田只夠養活自己，恕我無法承諾更多。","你的心意我明白，但族人還不信任外來的人。"],"greetFriendly":["遠方的朋友，河神保佑你平安來到此地。","吾族以稻米與清水待客，請安心歇腳。"],"greetCold":["河水自流，吾族自耕，不必多言。","你的來意天已知曉，有話直說便是。"],"threatDefy":["湄南河的水漲過多少次，吾族都還在這裡。","祖靈守著這片田，我不怕你的刀。"],"threatYield":["吾族人少，只求稻穗平安，我願退讓。","為了族人的孩子，我低頭一次，天會記得。"],"tributePay":["收成不多，吾族湊出{gold}金，望你善待河流。","族人省下口糧換成{gold}金給你，願天看見。"],"tributeRefuse":["稻米是天賜給族人的，不是給你的。","河水不向人低頭，吾族也不納貢。"],"giftThanks":["你的心意我收下了，河神也會記住你的名。","禮物放在祭壇前，今晚族人為你祈福。"],"intel":["順流而下的船說，{wars}正在動刀兵，{peace}與我們交好。","風傳來消息：{wars}起了戰火，{peace}仍安寧如常。"]}},{"name":"蘭甘亨大帝","title":"素可泰國王","era":"約 1279～1298 年在位","tone":"開明、自信、如父親般照顧百姓、務實重商","portrait":"th-historical-age1","lines":{"intro":["朕乃素可泰之王蘭甘亨，此地水中有魚，田中有稻。","遠方君主，素可泰的城門日夜敞開，歡迎你來看看。"],"contact":["你的使者看見了素可泰的佛塔，回去說吧，這裡不收關稅。","城門前掛著一口鐘，百姓有冤便敲，你的人也可以敲。"],"war":["朕本是百姓的父親，但你欺凌朕的子民，朕不得不出兵。","素可泰的象兵已備好，你踏過的稻田，朕會親自討回。"],"warReply":["你選擇與素可泰為敵？朕年少時便在象背上擊退強敵。","戰便戰，但朕先告訴你，素可泰的百姓不會為你低頭。"],"peace":["水中有魚，田中有稻，何必讓百姓餓著打仗？停戰吧。","朕提議罷兵，讓商旅重新往來，兩國皆可富足。"],"accept":["好，朕答應。從今日起，兩國商人往來不再徵稅。","君主能為百姓放下刀兵，朕敬你一杯。"],"reject":["你先毀約在前，如今言和，朕的百姓如何相信？","朕不接受，除非你退出被你占領的每一畝田。"],"rebuff":["你不願和談，朕也不勉強，素可泰有的是耐心。","也罷，等你的百姓也開始餓肚子，再來找朕吧。"],"betray":["朕本不願如此，但你的城堵住了朕的商道，休怪朕。","和約已無法保護素可泰的子民，朕只能重新拿起象矛。"],"truceEnd":["休戰期滿，朕已備好象兵，也備好和約，由你來選。","鐘聲響了，休戰結束，願你我都做出對百姓好的決定。"],"attacking":["素可泰的戰象出發了，朕親自率軍，望你早做準備。","朕的大軍沿河而下，沿途稻田秋毫無犯，直取你的城。"],"attacked":["城牆快守不住了……但素可泰的文字已刻在石碑上，不會消失。","百姓們先撤入佛寺，朕留在城門，與這口鐘同在。"],"defeated":["素可泰倒下了，但朕留下的文字會替這片土地說話。","記住，水中有魚，田中有稻，這是朕給後世的遺言。"],"victory":["戰事已了，朕不取你的城，只要商路暢通、百姓安居。","勝利屬於素可泰，但朕願與你共享這片河水的魚稻。"],"allyAccept":["好，素可泰與你結盟，從此商旅往來，不分彼此。","朕以石碑上的文字起誓，兩國永結同好。"],"allyReject":["朕的百姓剛從戰亂中安定，此時結盟，恐怕不妥。","素可泰願與你為友，但結盟之事，容朕再想想。"],"greetFriendly":["素可泰水中有魚、田中有稻，朋友來了便有飯吃。","朕的宮門掛著大鐘，你的信朕親自來讀。"],"greetCold":["朕忙著照看百姓，你的問候，聽到了。","若無要事，便別擾了素可泰的市集。"],"threatDefy":["朕少年時便騎象破敵，豈會怕你幾句話。","素可泰的百姓自由自在，誰也不能奪走。"],"threatYield":["朕不願百姓再受戰火，此事就依你吧。","為了田裡的稻子能收割，朕暫且退讓。"],"tributePay":["朕從國庫撥出{gold}金，只求市集照常開張。","這{gold}金你拿去，別再為難素可泰的商旅。"],"tributeRefuse":["素可泰不收過路稅，也不向他人納貢。","朕的金銀是百姓的，一分也不會送你。"],"giftThanks":["好禮！朕會把它擺在宮中，讓商人們都看看。","你以誠相待，素可泰的市集永遠為你敞開。"],"intel":["往來商旅告訴朕，{wars}正在交戰，{peace}一片太平。","朕的新文字已記下：{wars}起了兵戈，{peace}安穩無事。"]}},{"name":"納黎萱大帝","title":"阿瑜陀耶國王","era":"1590～1605 年在位","tone":"英勇、倔強、直率、重承諾、有仇必報但講義氣","portrait":"th-historical-age2","lines":{"intro":["朕乃阿瑜陀耶之王納黎萱，少年時曾為人質，如今為王。","遠方君主，阿瑜陀耶已重獲自由，朕不會再讓任何人奪走。"],"contact":["你的人看見了阿瑜陀耶的城牆，那是用血汗重新築起的。","來者若是商旅，朕歡迎；若是探子，朕的象兵已在等。"],"war":["你踏過了阿瑜陀耶的邊界，朕已倒水立誓，與你不共戴天。","朕曾在象背上與敵國太子決鬥，你以為朕會怕你？"],"warReply":["你向朕宣戰？好，阿瑜陀耶等這一天等很久了。","朕當過人質、受過屈辱，你的威脅對朕毫無意義。"],"peace":["打了這麼久，兩國的稻田都荒了，朕願意停戰。","朕提議罷兵，但條件是你的兵一步都不准留在暹地。"],"accept":["好，朕答應停戰，但你若再越界，朕的象刀不會客氣。","君主守信，朕也守信，阿瑜陀耶不打誠實的人。"],"reject":["你的和談來得太晚，朕的士兵已經看見你的城了。","朕不接受，被你擄走的百姓一日不歸，一日不談。"],"rebuff":["你不要和平？也好，朕本來就更習慣在象背上談話。","既然你拒絕，那就等戰場上見，朕不會再提第二次。"],"betray":["你暗中資助朕的敵人，這份和約，朕今日撕了。","朕曾發誓不受任何人擺布，你的算計逼朕重啟戰端。"],"truceEnd":["休戰結束了，朕的戰象已經磨好象牙，看你要戰要和。","約期已滿，朕給你最後一次機會，退兵或者迎戰。"],"attacking":["阿瑜陀耶的大軍出發了，朕親自騎象在最前面。","朕來了，帶著全國的象兵，你的城門準備好了嗎？"],"attacked":["城牆在崩塌……但朕還在象背上，阿瑜陀耶還沒輸！","你打到了朕的王城，可朕當年也曾一無所有，照樣站起來。"],"defeated":["朕一生為自由而戰，倒在戰場上，也算對得起阿瑜陀耶。","阿瑜陀耶亡了……但暹人不會忘記自己曾經站起來過。"],"victory":["勝了。朕不要你的王位，只要你記住：暹人不做任何人的人質。","戰事結束，阿瑜陀耶的獨立，今日再一次被證明。"],"allyAccept":["好，朕與你結盟，你的敵人就是朕的敵人。","阿瑜陀耶的象兵從此與你並肩，朕說到做到。"],"allyReject":["朕才剛從他人手中奪回自由，暫時不想再受盟約束縛。","結盟之事免了，阿瑜陀耶靠自己的象兵就夠了。"],"greetFriendly":["朕向來直來直往，你既以禮相待，便是朋友。","阿瑜陀耶的城門為朋友而開，進來坐坐吧。"],"greetCold":["朕不喜歡客套，有事直說，沒事別耽誤朕練兵。","問候收到了。朕記性很好，也記得誰曾與朕為敵。"],"threatDefy":["朕曾在象背上擊敗敵將，你的威嚇不過是風。","朕曾傾水立誓不再稱臣，豈會向你低頭。"],"threatYield":["朕不是怕你，是不願將士白白犧牲，這次算你贏。","阿瑜陀耶剛從戰火中站起，朕暫且忍下這口氣。"],"tributePay":["{gold}金拿去！朕言出必行，但這筆帳朕記下了。","朕付你{gold}金，換將士休養生息，值得。"],"tributeRefuse":["阿瑜陀耶不再向任何人稱臣納貢，你要就來取。","朕連強敵大軍都不怕，還會怕一封討貢的信？"],"giftThanks":["好！朕最敬重講義氣的人，這份禮朕記在心上。","你送禮不求回報，朕便許你一個承諾，日後必還。"],"intel":["朕的探子回報：{wars}正在用兵，{peace}按兵不動。","{wars}已經開戰，{peace}暫時太平，朕的眼睛從不閉上。"]}},{"name":"朱拉隆功（拉瑪五世）","title":"暹羅國王","era":"1868～1910 年在位","tone":"開明、溫和有禮、外交手腕高明、有遠見、講理但不失威嚴","portrait":"th-historical-age3","lines":{"intro":["朕乃暹羅國王朱拉隆功，願以文明與禮相待各國。","遠道而來的君主，曼谷的鐵路與郵局，隨時歡迎你參觀。"],"contact":["你的人看見了曼谷，這座城正在學習世界，也請你多看幾眼。","暹羅的大門向朋友敞開，但請記得，這是一個獨立的國家。"],"war":["朕一向主張以談判代替砲火，但你逼得朕別無選擇。","暹羅忍讓過多次，這一次，朕決定不再退讓。"],"warReply":["你向暹羅宣戰？朕已請各國使節見證，是你先開的火。","朕的新式陸軍已受過歐洲訓練，願你不要低估了暹羅。"],"peace":["戰爭只會讓大國有機可乘，朕提議停火，坐下來談。","朕願割捨一些顏面換取和平，因為百姓的安寧更重要。"],"accept":["好，朕接受。文明的國家應當用筆簽約，而非用劍。","朕以暹羅國王之名應允，願此約長久。"],"reject":["你的條件形同割地，朕已為保國讓步太多，不能再讓。","朕不接受，除非你先撤走駐在湄南河口的砲艦。"],"rebuff":["你不願談判，朕深感遺憾，但暹羅不會因此低頭。","既然如此，朕會讓世界看見，是誰拒絕了和平。"],"betray":["你暗中蠶食暹羅的邊境，這份條約，朕不得不廢止。","朕曾相信文明之約，可你的行動證明，朕錯信了人。"],"truceEnd":["休戰期滿，朕的使節已在館舍等候，也可以是將軍在等。","約期已到，願你選擇談判桌，而非戰場。"],"attacking":["暹羅的新軍出發了，他們帶的是西式步槍，不是舊日的長矛。","朕不得已出兵，但保證秋毫無犯，只取應得之地。"],"attacked":["曼谷的宮牆在震動……但暹羅的獨立，朕絕不放手。","你的軍隊已入城，可朕廢奴、修鐵路的成果，不會消失。"],"defeated":["暹羅倒下了，但朕已讓這國家學會了現代，這火不會熄。","朕為保國一生忍讓，到頭來仍是這樣，惟願百姓平安。"],"victory":["戰爭結束了，朕不奪你一寸土地，只希望兩國從此平等相待。","勝利之後，朕更願意談的是通商與鐵路，而非賠款。"],"allyAccept":["好，暹羅願與你結盟，以文明之國的方式互相扶持。","朕接受。在列強環伺的年代，朋友比砲艦更可貴。"],"allyReject":["暹羅一向在大國之間保持中立，此刻結盟，恐引來麻煩。","朕感謝你的美意，但暹羅的獨立，須靠不偏不倚來守護。"],"greetFriendly":["朕在歐洲見過許多君王，唯真誠的朋友最難得。","暹羅願與貴國以禮相交，朕靜候你的來訪。"],"greetCold":["朕已收到來信，暹羅的態度，日後自會明白。","禮數周到，心意如何，朕還需再看看。"],"threatDefy":["暹羅雖小，卻是竹子，能彎而不能折。","朕以理待人，但威嚇暹羅者，朕從不退讓。"],"threatYield":["為保暹羅獨立，朕可以割讓土地，卻不割讓尊嚴。","朕明白強權當前，退一步是為了子孫能站穩。"],"tributePay":["暹羅願付{gold}金，以換取和平與時間，朕不悔。","這{gold}金請收下，暹羅寧失財貨，不失國土。"],"tributeRefuse":["暹羅正修築鐵路與學校，國庫不是為納貢而設。","朕願以外交換和平，卻不願以金銀買屈辱。"],"giftThanks":["此禮朕甚喜歡，將置於宮中，以記兩國情誼。","貴國的心意朕收下了，暹羅必以同等誠意回報。"],"intel":["暹羅的電報傳來消息：{wars}已交戰，{peace}局勢平穩。","據各國使節所言，{wars}正在用兵，{peace}維持和平。"]}}],"Indonesia":[{"name":"普爾納瓦爾曼","title":"多羅磨國王","era":"約395～434年在位（5世紀初）","tone":"樸實莊重的早期君王，講話常拿河水、稻田、堤渠打比方，以毗濕奴信仰自持；自稱「本王」。","portrait":"id-historical-age0","lines":{"intro":["本王是多羅磨之主普爾納瓦爾曼，足跡所至即是王土。","遠方的君王，爪哇的河水與稻田歡迎有禮的客人。"],"contact":["你的人越過河口了？請先向河神敬禮，再談其他。","本王開鑿的水渠灌溉萬畝，你看見的便是豐饒。"],"war":["你踐踏本王的田地，如今象隊已整裝，戰鼓將響。","毗濕奴之足所踏之地，不容外人染指，本王宣戰！"],"warReply":["你選擇刀兵？多羅磨的戰象會替本王回答你。","河水漲時能淹沒田地，本王的怒火亦是如此。"],"peace":["戰事荒廢了農時，不如放下刀劍，各自修渠種稻。","本王願以千頭牛為誓，與你止戰，共享河水。"],"accept":["好，本王接受。願兩國的稻穗一同低頭結實。","以河神為證，多羅磨與你從此不再兵戎相見。"],"reject":["言而無信之人求和，本王不會聽第二次。","先歸還你奪走的田地，再來談停戰的事。"],"rebuff":["你拒絕了？那就讓河水與戰象替我們決定吧。","本王已伸出手，你不握，日後莫怪本王無情。"],"betray":["盟約如沙築的堤，一場大水便沖散了，本王要進軍。","本王重新占卜，神意已變，停戰到此為止。"],"truceEnd":["休戰的日子過去了，多羅磨的邊境重新戒備。","河水退了，約定也到期了，往後各憑本事。"],"attacking":["象隊已渡河，本王親自領軍，你的城牆守得住嗎？","多羅磨的戰士像雨季的河水，正朝你湧去。"],"attacked":["城牆將傾，本王仍站在這裡，一步也不退。","你的火燒到王宮了……但河水還在，田地還在。"],"defeated":["石上的足印會留下，多羅磨的名字不會被忘記。","本王輸了，但願你善待這片河水養育的百姓。"],"victory":["勝利歸於多羅磨。本王將以千牛祭神，感謝這一日。","戰事已了，本王要回去修渠了，那才是王者之業。"],"allyAccept":["本王願與你結盟，就像河水與田地彼此相依。","好盟友如好水源，本王珍惜。從今起共進退。"],"allyReject":["多羅磨的堤壩不靠別人來修，結盟之事免談。","本王還看不清你的心，暫不結盟，來日再議。"],"greetFriendly":["來信如旱季甘霖落田，本王讀罷心中歡喜。","願毗濕奴護佑你，願你我兩國如水渠相通。"],"greetCold":["本王正忙於開鑿河渠，你的問候且先放著。","河水不會為過路人停留，本王亦然。"],"threatDefy":["多羅磨的堤渠擋得住洪水，也擋得住你。","本王足跡如毗濕奴之足，豈懼你的威嚇？"],"threatYield":["稻田怕的是旱，本王怕的是百姓受兵災。","本王讓一步，只求河渠與稻田不受戰火。"],"tributePay":["本王從渠邊倉廩取出{gold}金，換一季安寧。","這{gold}金如河水入海，只盼你莫再來討。"],"tributeRefuse":["多羅磨的稻米養百姓，一粒也不給威嚇者。","本王的金子要用來開渠，不用來餵貪心。"],"giftThanks":["此禮如雨潤田，本王記下你的情誼。","本王以稻米與清水回贈，願兩國常來往。"],"intel":["本王所知，{wars}正兵戎相見，{peace}則安居務農。","河水告訴本王，{wars}燃起戰火，{peace}與本王和睦。"]}},{"name":"婆羅補特羅","title":"三佛齊國王","era":"約9世紀中葉（約835～860年在位）","tone":"從容自信的海上佛教君主，語氣帶禪意與商人的精算，愛用季風、潮水、帆影比喻；自稱「朕」。","portrait":"id-historical-age1","lines":{"intro":["朕是金洲之主婆羅補特羅，海峽的風都聽朕號令。","遠來的君王，三佛齊的港口為誠心的商旅敞開。"],"contact":["你的船看見朕的王都了？記得，過海峽先納稅。","千帆停泊、萬僧誦經，這便是朕的三佛齊。"],"war":["你的船隊擾亂海路，朕的戰船已出港，準備迎戰吧。","海峽只能有一位主人。朕宣戰，讓海浪見證。"],"warReply":["向海上的王者宣戰？你可知風向掌握在誰手裡。","佛陀教朕慈悲，卻沒教朕退讓。戰船，起錨。"],"peace":["刀兵損商路，商路斷則兩敗俱傷。朕提議停戰。","讓海峽回到帆影往來的日子吧，朕願先收起戰船。"],"accept":["善哉。朕接受停戰，願海路從此平靜如鏡。","以佛法為誓，三佛齊與你的國度共享海上安寧。"],"reject":["昨日焚朕商船，今日求和？朕的答覆是不。","海峽的規矩不能討價還價，此時談停戰尚早。"],"rebuff":["你拒絕了朕的好意，海上的風浪可不會客氣。","也罷，朕已盡了慈悲，接下來由戰船說話。"],"betray":["朕重新算過了，海峽的利益不容分享，停戰作廢。","潮水會轉向，盟約亦然。三佛齊的戰船再度出海。"],"truceEnd":["休戰的季風已過，往後的海路，各自小心了。","停戰期滿，朕不再受約束，海峽重新歸朕巡視。"],"attacking":["千帆已張，朕的水軍正乘季風而來，守好你的港口。","海上的王者親征了，你的海岸線將布滿朕的旗幟。"],"attacked":["王都的塔火光沖天……朕仍在此，僧侶們，繼續誦經。","港口失守了。但只要海還在，三佛齊就不會沉。"],"defeated":["諸行無常……朕的帆影落下了，願佛法長存於海上。","三佛齊亡於你手，可那爛陀的僧院仍會記得朕的名。"],"victory":["風向始終在朕這邊。海峽依舊，三佛齊依舊。","戰事已平，朕要為戰死者建寺祈福，願眾生安樂。"],"allyAccept":["朕答應結盟。你的船隻在朕的海域，一律免稅通行。","好，從今日起，你的敵人便是三佛齊的敵人。"],"allyReject":["海上的王者不需要盟友，只需要順風。恕朕婉拒。","你的誠意朕看見了，但時機未到，且待來年季風。"],"greetFriendly":["季風送來你的書信，朕在港口讀之甚喜。","海路相通即是有緣，朕願與你互通有無。"],"greetCold":["潮水來去自有時，朕無暇應酬閒信。","帆影千百，朕不記得哪一片是你的。"],"threatDefy":["海峽的潮水聽朕號令，你的船隊也得聽。","三佛齊的戰船比你的威嚇多，不妨來數數。"],"threatYield":["商人懂得算，朕不與你爭這一時之氣。","潮退了便退，朕暫且收帆，靜待風向轉。"],"tributePay":["朕以{gold}金換海路平靜，這筆帳划得來。","{gold}金如潮水送出，願它換來你的安分。"],"tributeRefuse":["朕的金子是港口的稅，不是你伸手就有。","季風不會為誰改向，朕的財庫亦是如此。"],"giftThanks":["厚禮已隨潮水入港，朕以香料與檀香回贈。","朕謝你的心意，願菩薩護佑你我海路平安。"],"intel":["商船帶回消息：{wars}正在交戰，{peace}與朕友好。","朕聽聞{wars}烽火不斷，{peace}則風平浪靜。"]}},{"name":"蘇丹阿貢","title":"馬打蘭蘇丹","era":"1613～1645年在位","tone":"霸氣、志在一統爪哇的雄主，對海邊的「紅毛人」深惡痛絕，虔誠但以王者自居；自稱「朕」。","portrait":"id-historical-age2","lines":{"intro":["朕是馬打蘭的蘇丹阿貢，爪哇全島皆在朕的傘下。","來者何人？在馬打蘭的王庭前，先報上你的名號。"],"contact":["你的人來到朕的都城了？看清楚，這是爪哇的心臟。","稻田千里、勇士十萬，馬打蘭不是可以隨意窺探的。"],"war":["爪哇容不下第二個王座，朕宣戰，馬打蘭的大軍將至。","你像巴達維亞的紅毛人一樣礙眼。朕要親手拔除你。"],"warReply":["向朕宣戰？連泗水都已臣服，你憑什麼例外。","好膽量。馬打蘭的火砲與戰象，會教你什麼叫敬畏。"],"peace":["戰事讓稻田荒了兩季，朕願暫且收兵，你意下如何？","真正的敵人在海邊的紅毛堡壘，我們不該相互消耗。"],"accept":["朕准了。以真主之名起誓，馬打蘭暫且收起刀劍。","好，停戰。讓百姓先把這一季的稻子收回來。"],"reject":["朕的軍隊尚未疲倦，此時談和，太早了。","先撤出你占據的城鎮，再來王庭前談停戰。"],"rebuff":["你拒絕朕的提議？那便由火砲繼續這場對話。","朕難得低頭一次，你竟不接。好，朕記住了。"],"betray":["朕重新審視了局勢，這份停戰對馬打蘭無益，作廢。","爪哇只能有一位王，朕不會與人平分。大軍，出發！"],"truceEnd":["休戰的日子到頭了，朕的火砲也已重新擦亮。","稻子收完了，約定也期滿了，往後各憑實力。"],"attacking":["馬打蘭的大軍已經出發，這次朕帶足了糧草。","十萬勇士踏過稻田而來，你的城牆準備好了嗎？"],"attacked":["王庭已被火光包圍……朕是爪哇之主，不會逃。","城破在即，但朕的傘仍未倒下，馬打蘭還在戰鬥。"],"defeated":["朕曾夢想統一爪哇……如今交給真主裁決了。","馬打蘭倒下了，但爪哇的曆法會繼續記下歲月。"],"victory":["爪哇再無敵手。朕將在山上建陵，讓後世記住今日。","勝利歸於馬打蘭。朕要下令全島慶祝三日。"],"allyAccept":["朕答應結盟。共同對付海邊的紅毛人，如何？","好，馬打蘭與你並肩。朕的戰象會為盟友而戰。"],"allyReject":["爪哇之主不需要盟友，只需要臣服者。朕拒絕。","你的心意朕收下了，但馬打蘭習慣獨自作戰。"],"greetFriendly":["朕正欲一統爪哇，得你來信，是為知音。","真主賜朕江山，也賜朕遠方的朋友。"],"greetCold":["朕的眼裡只有爪哇，你的信放在角落。","馬打蘭不缺問候，缺的是肯出兵的盟友。"],"threatDefy":["紅毛人的砲都嚇不倒朕，你算什麼？","朕率萬軍圍巴達維亞尚且不懼，何懼於你？"],"threatYield":["朕的兵馬正對付紅毛人，暫不與你為敵。","為了一統爪哇的大業，朕暫忍這口氣。"],"tributePay":["朕給你{gold}金，只求你莫與紅毛人結盟。","這{gold}金拿去，朕的刀要留給巴達維亞。"],"tributeRefuse":["爪哇之主豈向人納貢？朕一文不給。","朕的金庫要養兵伐紅毛人，你別想分一杯羹。"],"giftThanks":["此禮朕收下，來日爪哇一統，必有厚報。","願真主賜福於你，朕記住這份情誼。"],"intel":["朕的探子回報：{wars}正在打仗，{peace}與朕交好。","{wars}戰事未歇，{peace}尚安，朕仍盯著紅毛人。"]}},{"name":"蒂博尼哥羅","title":"日惹王子","era":"1785～1855年（爪哇戰爭 1825～1830）","tone":"虔誠、堅毅、沉痛而不失尊嚴的反抗領袖，把戰爭視為守護土地與信仰，警惕談判桌上的詭計；自稱「本王」。","portrait":"id-historical-age3","lines":{"intro":["本王是日惹的蒂博尼哥羅，為爪哇的土地與信仰而戰。","你是朋友，還是替荷蘭人辦事的？先說清楚再談。"],"contact":["你的人看見了我們的營地？這裡沒有王宮，只有信念。","爪哇的村莊看似安靜，但每個農夫都是本王的戰士。"],"war":["你在本王的土地上修路築寨，那便別怪本王舉兵。","以真主之名，本王向壓迫者宣戰，爪哇不再沉默。"],"warReply":["你要戰？好。爪哇的山林與稻田都會站在本王這邊。","本王早已把生死交給真主，你的宣戰嚇不倒本王。"],"peace":["百姓已流夠了血。本王提議停戰，讓村莊重新升起炊煙。","我們的敵人不該是彼此。放下武器吧，本王先讓一步。"],"accept":["本王接受。願真主見證，這份停戰不再被人背棄。","好。讓農夫回到田裡，讓孩子回到經堂，這就夠了。"],"reject":["本王見過太多談判桌上的陷阱，此時不會相信你。","先把你的軍隊撤出爪哇的村莊，再來談和平二字。"],"rebuff":["你拒絕了？那本王只好繼續在山林裡與你周旋。","本王已盡了仁義，往後的戰火，責任不在爪哇。"],"betray":["你暗中增兵，這停戰早已名存實亡。本王重返戰場。","真主指引本王另一條路，停戰到此為止，各自備戰吧。"],"truceEnd":["休戰期滿。本王的戰士已從田裡回來，重新拿起武器。","約定到期了，爪哇的山林再度不安寧，你自己小心。"],"attacking":["本王騎上黑馬了，爪哇的義軍正從四面八方湧向你。","你不會看見我們的大軍，只會在每個村口遇見我們。"],"attacked":["營地失守了……但本王還活著，爪哇的抵抗就不會停。","你燒了村莊，燒不掉信仰。本王會退入山中，再戰。"],"defeated":["鐵鏈能鎖住本王的手，鎖不住爪哇人的心。","本王輸了這場仗，但這片土地終將屬於她的子民。"],"victory":["感謝真主。爪哇的土地，回到了耕種它的人手中。","勝利不屬於本王，屬於每一個拿起鋤頭與長矛的農夫。"],"allyAccept":["本王答應結盟。凡是反抗壓迫的人，都是爪哇的兄弟。","好，我們並肩而戰。願真主保佑我們兩國的百姓。"],"allyReject":["本王的戰爭是為爪哇百姓，不是為別國的野心。恕難結盟。","本王還不清楚你的立場，結盟之事，容後再議。"],"greetFriendly":["來信如清泉，本王在山中營帳讀之心暖。","願真主保佑你，本王雖在戰中，仍念友情。"],"greetCold":["本王的故土烽火未息，無心與你寒暄。","若是談判之邀，本王須先問桌下藏了什麼。"],"threatDefy":["本王守的是先祖的土地，威嚇動搖不了。","荷蘭人的槍砲尚不能令本王低頭，何況你的話。"],"threatYield":["本王兵少糧缺，不願再多一個敵人。","本王暫且退讓，但這片土地不會忘記。"],"tributePay":["本王將僅有的{gold}金交出，只求族人得以喘息。","這{gold}金本是買糧的，本王含淚給你。"],"tributeRefuse":["本王連荷蘭人的金子都不要，何況給你。","爪哇的財富屬於這片土地，本王一分不給。"],"giftThanks":["亂世中仍有人相贈，本王銘記於心。","此禮將分給前線的弟兄，本王代他們謝你。"],"intel":["本王聽聞{wars}戰火正烈，{peace}尚存安寧。","山中傳來消息：{wars}正在交戰，{peace}安然無事。"]}}],"Philippines":[{"name":"巴朗蓋族長","title":"達圖（部落首領）","era":"約西元前後（早期聚落時代）","tone":"沉穩、敬海、重視族人與互助，語句簡短樸實","portrait":"ph-historical-age0","lines":{"intro":["我是這片海灣的達圖，族人靠海而生，也靠海相聚。","遠方的客人，先喝口椰水，再說你為何而來。"],"contact":["你的船靠近了我們的岸，是來交換米鹽，還是另有所圖？","我們的船屋沿河而建，外人第一次看見，多半會停下腳步。"],"war":["你奪走我們的漁場與稻田，達圖不能再忍耐。","海螺已經吹響，全族的男人都握起了矛。"],"warReply":["你要動刀兵？也好，我們的島嶼不歡迎強盜。","我不曾冒犯你，但族人的家園，我必守到底。"],"peace":["打下去，兩邊的稻田都會荒掉，不如放下矛。","讓我們在海邊立石為誓，從此互不侵犯。"],"accept":["好，我以祖靈之名起誓，從今日起你我為友。","族人會準備豬與米酒，慶祝這份和約。"],"reject":["你昨日燒了我們的船，今日談和，我如何相信？","祖靈還沒有平息怒氣，現在談和，太早了。"],"rebuff":["你不願握手，那我只好繼續握矛。","可惜了，海本可以連接你我，而不是隔開我們。"],"betray":["海邊立的誓石已經被我推倒，別再說什麼和約。","你以為達圖忘了舊仇？潮水退了還會再漲。"],"truceEnd":["約定的月數已滿，從此各憑本事。","休戰的日子過去了，我族的船又能自由出海。"],"attacking":["百艘巴朗蓋船已經出海，划向你的海岸。","今夜的火把會照亮你的村子，做好準備吧。"],"attacked":["村子的柵欄快倒了，但族人還沒有低頭。","我的船屋在燃燒，海啊，請庇護我的孩子。"],"defeated":["達圖倒下了，但族人的血脈會隨潮水延續。","把我葬在面海的地方，讓我看著族人回家。"],"victory":["祖靈站在我們這一邊，勝利屬於全族。","把戰利品分給每一戶人家，這是達圖的規矩。"],"allyAccept":["從今以後，你的船就是我的船，你的敵人就是我的敵人。","好，讓兩族的孩子一起在沙灘上長大。"],"allyReject":["我族向來自己划自己的船，不需要綁在別人的船尾。","你的心思太多，達圖看不透，不敢與你結盟。"],"greetFriendly":["遠方的朋友，海風把你的問候送到了，我族歡迎你。","潮水退了又漲，你的來信讓吾族的爐火更暖。"],"greetCold":["海上來的信，我聽見了。族人的事，我要先顧。","問候收下了。海很大，我們各守各的岸。"],"threatDefy":["風浪我見多了，你的威嚇不比颱風可怕。","吾族人人會划船、會持矛，你來試試便知。"],"threatYield":["為了族人平安，我暫且退讓，但海會記得今日。","我不願族人受苦，你要的岸，先讓給你。"],"tributePay":["族人湊出 {gold} 金幣給你，願海風平息你的怒氣。","吾族拿出 {gold} 金幣，換一季平靜的海面。"],"tributeRefuse":["吾族的收成是要養孩子的，不是給你的貢品。","海裡的魚不會向誰納貢，我族也一樣。"],"giftThanks":["你的禮物我收到了，族人會記住你的心意。","禮物已分給族人，今晚的爐火會為你多燒一會。"],"intel":["漁人從外海帶回消息：{wars}正在交戰，{peace}相安無事。","潮水帶來風聲，{wars}動了刀兵，{peace}仍守著和平。"]}},{"name":"巴都葛叭哈剌","title":"蘇祿東王","era":"約1400～1417年在位","tone":"海上貿易之王，豪爽、重信義、見多識廣，愛以珍珠與大海為喻","portrait":"ph-historical-age1","lines":{"intro":["本王是蘇祿東王，蘇祿海上的珍珠與船隻皆聽我號令。","遠客請坐，本王正要渡海朝見大明天子，你來得正巧。"],"contact":["你的船進了蘇祿海，可知這裡的珍珠是天下第一？","蘇祿的市集歡迎四方商人，但不歡迎海盜。"],"war":["你劫了本王的商船，蘇祿的戰艦今日就要出海！","本王待人以誠，你卻以惡相報，那便兵戎相見。"],"warReply":["本王縱橫海上多年，還沒怕過誰的戰書。","既然你選了刀劍，蘇祿的勇士便奉陪到底。"],"peace":["打仗會斷了商路，對你我都無好處，不如止戈。","本王願以珍珠為禮，換一紙停戰之約。"],"accept":["好，本王答應。海上的風浪，還是留給船去對付。","以真主之名立約，蘇祿人一諾千金。"],"reject":["你的誠意不如你的珍珠多，本王不接受。","戰船已經出港，現在談和，為時已晚。"],"rebuff":["你不要和平？那本王也不必再客氣了。","好意被拒，本王只當是海風把話吹散了。"],"betray":["你暗中勾結海盜襲我商船，這和約本王撕了！","蘇祿人守信，但不對背信之人守信。"],"truceEnd":["休戰的期限已到，海上從此各憑船堅。","約期已滿，本王不再受和約束縛。"],"attacking":["蘇祿的戰船已經揚帆，桅杆多得像一片樹林。","本王親自領軍，你的港口今日將見識蘇祿的威名。"],"attacked":["王城的城牆快守不住了，但蘇祿的旗還在飄。","宮中的珍珠都散了，本王仍握著劍不放。"],"defeated":["若本王倒在異鄉，願子孫永遠記得蘇祿的海。","本王輸了，但蘇祿的船仍會在海上航行。"],"victory":["海上的霸主仍是蘇祿，本王要在市集擺宴三日。","勝利歸於真主，珍珠與榮耀歸於蘇祿。"],"allyAccept":["好，兩家的商船從此互相護航，海盜也得退避。","本王願與你共享商路，也共擔風浪。"],"allyReject":["本王已與大明修好，你的盟約不敢輕易應允。","蘇祿的船慣於單獨航行，不習慣被人牽著走。"],"greetFriendly":["哈哈，遠方的朋友！本王的港口永遠為你敞開。","你的來信如珍珠般珍貴，本王已備好宴席相迎。"],"greetCold":["本王商船往來萬里，見過太多客套話，說重點吧。","問候本王收下了，海面尚平，暫無深談的必要。"],"threatDefy":["本王的船隊縱橫南海，還沒怕過誰的恐嚇！","颱風都吹不沉蘇祿的船，你的威嚇算什麼？"],"threatYield":["商人懂得算帳，本王暫且低頭，留住船隊要緊。","好，本王退一步。海路長遠，來日再論高下。"],"tributePay":["這 {gold} 金幣算本王買條平安海路，收好了。","珍珠換和平也算划算，{gold} 金幣送上，別再多要。"],"tributeRefuse":["本王做的是買賣，不是施捨，貢品一顆珍珠也沒有。","蘇祿的珍珠只賣給誠信的人，不獻給貪心的人。"],"giftThanks":["好禮！本王以蘇祿最亮的珍珠回贈你的心意。","哈哈，禮物收下了！海上朋友的情義比金子重。"],"intel":["各港商人都說，{wars}正在打仗，{peace}的海路平靜。","本王船隊帶回消息：{wars}兵戈相向，{peace}安穩通商。"]}},{"name":"拉普拉普","title":"麥克坦島達圖（酋長）","era":"約1521年活躍","tone":"勇敢、直率、不畏強權、對外來者警惕，語氣短促有力","portrait":"ph-historical-age2","lines":{"intro":["我是麥克坦的達圖拉普拉普，這座島不向任何人稱臣。","你若帶著善意來，我以椰酒相迎；帶著刀來，我以刀相迎。"],"contact":["你的人踏上了麥克坦的沙灘，最好記得這裡是誰的地方。","麥克坦的珊瑚礁擋得住大船，也擋得住野心。"],"war":["你想要我的島低頭？麥克坦人從不低頭！","鐵甲擋不住我們的長矛，來吧，海灘上見。"],"warReply":["很好，你的宣戰讓我省了說話的力氣。","外來的船隻能上岸，卻走不回去，這就是麥克坦。"],"peace":["打夠了嗎？各守各的島，這是我的條件。","我不求你的貢品，也不給你貢品，兩不相欠便可停戰。"],"accept":["好，你尊重麥克坦，麥克坦也會尊重你。","放下刀，今晚的火堆邊有你一個位置。"],"reject":["你要我先納貢再談和？麥克坦沒有這種規矩。","你的船還停在我的海上，談什麼和平？"],"rebuff":["拒絕就拒絕，麥克坦人不會求人第二次。","既然你選擇繼續打，就別怪礁石割破你的船。"],"betray":["你私下與宿霧的酋長聯手對付我，和約作廢！","我的信任只給一次，你已經用完了。"],"truceEnd":["潮汐換了幾回，休戰也到頭了。","休戰結束，麥克坦的長矛重新磨亮。"],"attacking":["退潮了，麥克坦的戰士正涉水而來。","我不等你上岸，我先渡海去找你。"],"attacked":["村子被圍住了，但麥克坦人寧可站著戰，也不跪著活。","火燒到了椰林，我仍站在最前面。"],"defeated":["我倒在自己的沙灘上，這片海仍是麥克坦的。","記住，這座島曾經有人不肯低頭。"],"victory":["船上的鐵甲人也會倒下，麥克坦今日證明了這一點。","把勝利的消息傳遍各島，讓所有人知道我們沒有跪。"],"allyAccept":["好，你我並肩，讓外來的船知道這片海有主人。","麥克坦不常結盟，你是少數讓我點頭的人。"],"allyReject":["麥克坦靠自己的長矛守島，不需要別人的旗子。","我不知道你的心是向著海，還是向著外來的船。"],"greetFriendly":["你的信我看了。麥克坦的人不怕朋友，只怕騙子。","好，你以禮相待，我便以禮相回。"],"greetCold":["外來的人說話總是好聽，我先看你怎麼做。","問候收到。別靠近我的島，就是最好的禮。"],"threatDefy":["來啊！麥克坦的戰士早已握緊長矛等你。","我不向任何人低頭，帶著你的大船退回去！"],"threatYield":["吾族人少，這回我忍。但別以為麥克坦怕了。","好，我退。長矛還在，日後再說。"],"tributePay":["{gold} 金幣拿去，這是我族最後一次讓步。","哼，{gold} 金幣給你，換你的船離開我的海。"],"tributeRefuse":["麥克坦不向任何人納貢，一粒米也不給。","貢品？我的島只給朋友食物，不給強盜金子。"],"giftThanks":["禮物收下了。你是少數以誠相待的外來者。","好，我記住你的名字，這份情義麥克坦不會忘。"],"intel":["島上漁人都在說，{wars}正在打仗，{peace}沒有動靜。","我聽說了：{wars}動了刀兵，{peace}還算太平。"]}},{"name":"埃米利奧·阿奎納多","title":"菲律賓革命政府總統","era":"1898～1901年執政","tone":"年輕堅毅、自信的革命軍人，講究氣節與獨立尊嚴，偶爾流露理想主義","portrait":"ph-historical-age3","lines":{"intro":["我是阿奎納多，菲律賓人民自己選出的領袖。","這面太陽與三星的旗，代表菲律賓不再屬於任何帝國。"],"contact":["你看到的是卡維特，菲律賓的獨立宣言就在這裡宣讀。","馬洛洛斯有我們的國會與憲法，這是亞洲少見的共和國。"],"war":["你把菲律賓當殖民地看待，那就別怪革命軍拿起槍。","我們趕走了西班牙人，也不怕再多一個敵人。"],"warReply":["宣戰？菲律賓人爭取自由的路上，從不缺敵人。","我們用竹矛打過火槍，你的軍隊嚇不倒我們。"],"peace":["戰爭讓百姓受苦，我願意談判，只要你承認我們的獨立。","我在比亞克納巴托簽過協定，我知道談判的價值。"],"accept":["好，為了人民，我接受。菲律賓需要時間建設國家。","我以共和國之名立約，望你也守諾。"],"reject":["你的條件是要我們回去當殖民地，這不可能。","沒有獨立的和平，只是換個主人，我拒絕。"],"rebuff":["你拒絕和平，那麼歷史會記下是誰選擇了戰爭。","很好，革命軍會繼續戰鬥，直到你願意坐下來談。"],"betray":["你先違背了對菲律賓的承諾，這和約我不再遵守。","我學過教訓：紙上的承諾不可靠，革命軍重新拿起槍。"],"truceEnd":["休戰期滿，共和國的軍隊已經重整完畢。","談判的時間結束了，接下來由戰場說話。"],"attacking":["革命軍已從卡維特出發，目標是你的城池。","我親自帶隊，這場戰役關係菲律賓的尊嚴。"],"attacked":["馬洛洛斯快守不住了，政府將轉進山區繼續抵抗。","首都或許會失守，但共和國的精神不會。"],"defeated":["我被俘了，但菲律賓人追求自由的心，你關不住。","今日的失敗，會成為明日獨立的種子。"],"victory":["菲律賓人證明了，亞洲也能有自己的共和國！","勝利屬於人民，我只是舉旗的人。"],"allyAccept":["好，願我們的盟約，成為亞洲各民族互助的開始。","共和國需要朋友，我握住你伸出的手。"],"allyReject":["我曾相信過強國的承諾，這一次我要更謹慎。","菲律賓的獨立不能再依賴別人，恕我拒絕。"],"greetFriendly":["感謝來信。菲律賓共和國願與尊重自由的朋友為伍。","你的問候溫暖了革命軍的營帳，我以獨立之名致意。"],"greetCold":["問候收到。但我更想知道，貴國是否承認菲律賓獨立。","客套話留著吧，我的同胞正在為自由奮戰。"],"threatDefy":["我們趕走了三百年的殖民者，不會再向任何強權低頭！","威嚇一個為獨立而戰的民族？你顯然不了解菲律賓人。"],"threatYield":["為了保存革命的火種，我暫時退讓，但理想不會熄滅。","共和國尚年輕，我不能讓同胞白白犧牲，先退一步。"],"tributePay":["這 {gold} 金幣是同胞省下的軍餉，換共和國喘息的時間。","我付出 {gold} 金幣，但菲律賓的尊嚴是買不走的。"],"tributeRefuse":["菲律賓人不再向任何人納貢，這正是我們革命的理由。","國庫的每一分錢都屬於同胞，一分也不會給你。"],"giftThanks":["感謝厚禮。在孤軍奮戰的日子裡，友誼格外珍貴。","禮物已收，我會告訴同胞，世上仍有支持自由的朋友。"],"intel":["據革命軍的情報，{wars}正陷於戰火，{peace}維持和平。","我的探子回報：{wars}已經開戰，{peace}暫無戰事。"]}}],"Malaysia":[{"name":"馬來聚落長老","title":"長老","era":"約西元前後（早期聚落時期）","tone":"沉穩、敬畏自然、以族人為念","portrait":"my-historical-age0","lines":{"intro":["吾是海濱聚落的長老，季風帶你來到此地。","河口的稻田與大海養活我的族人，遠客請安。"],"contact":["你的船看見我們的高腳屋了？這是族人的家。","岸邊那些獨木舟是我們的，遠方的人莫要驚動。"],"war":["你的人踏壞了我們的田，族人已舉起長矛。","大海教我們忍耐，也教我們保衛家園，開戰吧。"],"warReply":["你要與海濱的族人為敵？森林與海潮都站在我這邊。","吾族雖小，卻從不畏懼風暴，來吧。"],"peace":["刀劍換不來豐收，不如坐下來分一份檳榔。","季風快轉向了，讓我們各自回去照顧田地吧。"],"accept":["好，長老以海為證，族人不再與你相爭。","就這麼定了，收起長矛，一起等雨季來臨。"],"reject":["你的話像退潮的水，來得快去得也快，我不信。","族人的傷還沒好，這時談和，太早了。"],"rebuff":["你不肯？那就讓大海來評判誰更有耐心。","可惜了，我本以為遠客懂得和睦的道理。"],"betray":["季風變了，族人的心也變了，這約定就此作廢。","原諒我，為了族人的田地，我必須毀約。"],"truceEnd":["約定的月份已過，從今日起各憑本事。","潮水退了又漲，休戰的日子到頭了。"],"attacking":["戰舟已推下水，族人正往你的岸邊划去。","聽見海螺聲了嗎？那是我們出征的號角。"],"attacked":["高腳屋在燃燒……族人啊，退到森林裡去！","你的人已到了村口，吾的長矛卻快握不住了。"],"defeated":["聚落沒了，但海潮會記得我們曾在這裡。","請善待我的族人，他們只是想守住家。"],"victory":["風暴過去了，海濱的族人依然站在這裡。","今晚升起營火，告訴孩子們祖先如何守住岸邊。"],"allyAccept":["好，遠方的朋友，我們的船將一起出海。","族人願與你共用這片海，從此互相守望。"],"allyReject":["大海太寬，你我的船暫時還走不到一起。","先讓族人看清你的為人，再談結盟不遲。"],"greetFriendly":["遠方的朋友，季風把你的信送來，吾以椰水相迎。","河口的族人聽聞你來信，皆說這是好兆頭。"],"greetCold":["海面平靜時吾才聽外人說話，今日風不對。","你的信吾收下了，但族人的事，不必外人多問。"],"threatDefy":["森林與海潮護著吾族，你的威嚇如浪打礁石。","吾族在此地生根已久，不會因幾句狠話遷走。"],"threatYield":["為了族中老幼，吾願退讓一步，請勿再逼近。","吾不願見族人流血，你要的，讓我們坐下來談。"],"tributePay":["族人所存不多，這{gold}金吾交出，換族人平安。","吾不願子弟受苦，{gold}金奉上，望你守信不擾。"],"tributeRefuse":["山川所賜是族人共有的，吾無權拿去送人。","吾族只向天地與祖靈獻禮，不向外人納貢。"],"giftThanks":["你的禮物吾已分給族人，海風會記得你的好意。","禮物收下了，下回季風轉向，吾送你檳榔與魚乾。"],"intel":["吾族與{wars}為敵，與{peace}為友，這是海上傳來的消息。","商船帶來的話：{wars}正與吾族相爭，{peace}與吾族結盟。"]}},{"name":"拜里米蘇拉","title":"馬六甲開國君主","era":"約1400～1414年在位","tone":"堅韌、精明、重視商路","portrait":"my-historical-age1","lines":{"intro":["本王拜里米蘇拉，自巨港輾轉至此，建立馬六甲。","這片海峽是天下商船必經之路，你也是為它而來？"],"contact":["看見了嗎？河口那片新城，是本王親手所建。","那裡曾是漁村，如今船桅比樹還密，這就是馬六甲。"],"war":["本王失過淡馬錫，不會再失去馬六甲，開戰！","你動了本王的商路，海峽的浪將吞沒你的船。"],"warReply":["你要戰？本王一生流亡，早不怕再打一場。","連鼠鹿都敢踢退獵犬，馬六甲豈會怕你。"],"peace":["戰爭讓商船繞道，你我都吃虧，不如停戰。","本王願開放港口與你互市，前提是放下刀劍。"],"accept":["好，馬六甲的碼頭從今日起為你的船留位。","本王接受，海峽夠寬，容得下兩國的船。"],"reject":["你的誠意還不如一袋胡椒重，本王不接受。","等你的船隊退出海峽，再來談停戰。"],"rebuff":["你拒絕了？可惜，商人比你懂得算這筆帳。","也罷，本王的港口照樣開張，看誰先撐不住。"],"betray":["本王曾被逐出故土，早學會了先下手為強。","約定是寫在潮水上的，如今潮退了。"],"truceEnd":["休戰的季風已過，商船與戰船都該出港了。","本王守約至今日，明日起各憑手段。"],"attacking":["馬六甲的戰船已出港，順著季風直奔你的城。","本王親率船隊出海，這一戰為的是整條海峽。"],"attacked":["城牆將破……難道本王又要再次流亡？","碼頭已陷，馬六甲的燈火快要熄了。"],"defeated":["本王一生漂泊，最後仍未能守住這座城。","記住，馬六甲是本王在樹下起誓建成的。"],"victory":["海峽的主人只有一個，如今天下商人都知道了。","本王從流亡王子走到今日，這座城值得。"],"allyAccept":["好，本王願與你結盟，馬六甲的商路與你共享。","大明的船隊也曾與本王結交，今日再添一友。"],"allyReject":["本王剛立國不久，暫時不想被別國的旗幟綁住。","結盟之事，等本王看清你的船往哪開再說。"],"greetFriendly":["來信本王已閱，馬六甲的港口永遠為朋友敞開。","季風送來你的問候，本王邀你的商船來此貿易。"],"greetCold":["本王忙於築港立城，寒暄之詞，恕不多言。","馬六甲初立，本王只與帶來貨物與誠意的人交談。"],"threatDefy":["本王曾失去淡馬錫，卻在此地重生，豈會怕你。","鼠鹿敢踢退獵犬，馬六甲也敢迎擊來犯之敵。"],"threatYield":["馬六甲城牆未固，本王暫且退讓，來日再論。","本王以商立國，不願輕啟戰端，此事依你所言。"],"tributePay":["本王以港口稅收付你{gold}金，望海路從此無阻。","為保商路暢通，本王暫付{gold}金，此非長久之計。"],"tributeRefuse":["馬六甲的金銀來自商船，不是給人白拿的。","本王已向大明朝貢求庇，不會再向他人低頭。"],"giftThanks":["厚禮已收，本王回贈馬六甲的胡椒與錫。","你的禮物讓本王記住你的名字，商路上互相照應。"],"intel":["本王的探子回報：{wars}與我為敵，{peace}與我通好。","海峽上的商人都知道，{wars}是敵，{peace}是盟友。"]}},{"name":"馬哈茂德沙","title":"馬六甲蘇丹","era":"1488～1511年在位（1528年逝世）","tone":"驕傲、剛硬、悲壯","portrait":"my-historical-age2","lines":{"intro":["本王馬哈茂德沙，馬六甲蘇丹，海峽的商船皆向本王納稅。","四方商人皆聚於馬六甲，你若識相，便該以禮相待。"],"contact":["你看見的王宮與港口，是歷代蘇丹經營的心血。","那滿港的船帆，來自阿拉伯、天竺與中原，皆來此交易。"],"war":["你像葡萄牙人一樣貪心，本王絕不容忍，開戰！","敢窺伺馬六甲的財富？本王的戰象已備妥。"],"warReply":["葡萄牙人的大砲都嚇不倒本王，你算什麼？","你要戰？馬六甲的勇士自漢都亞以來從不退縮。"],"peace":["戰事讓商船不敢進港，本王願暫時罷兵。","本王有更大的敵人在海上，你我不如先停戰。"],"accept":["好，本王允了，馬六甲的港口重新為你敞開。","就此停戰，願香料與布匹再度往來不絕。"],"reject":["本王不接受，馬六甲的蘇丹從不向人低頭。","拿走的東西還回來，再談停戰。"],"rebuff":["你拒絕了本王？很好，願你不會後悔。","本王的善意只給一次，你已經浪費掉了。"],"betray":["本王失去了太多，今日容不得再守什麼約定。","停戰？那只是本王重整戰象的時間罷了。"],"truceEnd":["休戰結束，馬六甲的旗幟將再度出海。","本王已重整旗鼓，這回不會再手下留情。"],"attacking":["本王的戰象與戰船已出發，直取你的都城。","馬六甲的大軍出港了，你的港口將換上本王的旗。"],"attacked":["王宮已被砲火籠罩……本王絕不投降，退往內陸！","城破在即，本王將帶著王族退守，他日再回。"],"defeated":["馬六甲在本王手中失落，此恨隨本王入土。","本王的子孫會在別處重建王朝，你等著看。"],"victory":["馬六甲依舊屹立於海峽，本王的旗幟永不落下。","四方商人再度來朝，這才是馬六甲該有的樣子。"],"allyAccept":["好，本王與你結盟，一同對抗海上來的貪婪之徒。","馬六甲願與你並肩，海峽的財富我們共享。"],"allyReject":["本王見過太多口稱結盟卻圖謀港口的人，不必了。","馬六甲的蘇丹不需要盟友，只需要忠誠的臣民。"],"greetFriendly":["本王的宮殿向來賓開放，馬六甲的香料與你共享。","來信已閱，本王以蘇丹之名歡迎你的使者。"],"greetCold":["本王乃馬六甲之主，不需外人問候，說正事。","西方的帆船已在海峽出沒，本王沒有閒情寒暄。"],"threatDefy":["本王連葡萄牙人的砲艦都不懼，你的威嚇算什麼。","馬六甲之主寧可流亡也不屈膝，你儘管來。"],"threatYield":["本王的軍力需留給更大的敵人，此事就依你。","本王不願再讓臣民流離，這一步，本王退了。"],"tributePay":["本王從國庫取{gold}金給你，但本王的驕傲不隨之而去。","{gold}金拿去，本王餘下的每分力量都要留給馬六甲。"],"tributeRefuse":["本王乃蘇丹，向人納貢？此話莫再提。","馬六甲的黃金只用來養兵造船，一分不給。"],"giftThanks":["禮物收下，本王在落難之時仍記得誰伸出過手。","本王以馬六甲的丁香與肉豆蔻回敬你的心意。"],"intel":["本王的敵人是{wars}，盟友是{peace}，記清楚了。","宮中的密報：{wars}與本王交戰，{peace}與本王和平。"]}},{"name":"阿布峇卡","title":"柔佛蘇丹","era":"1862～1895年在位","tone":"儒雅、外交手腕高明、重視現代化","portrait":"my-historical-age3","lines":{"intro":["本王阿布峇卡，柔佛蘇丹。本王以筆與談判治國，非以刀劍。","柔佛雖小，卻自立於列強之間，歡迎閣下來訪。"],"contact":["閣下所見的新山，是本王親自規劃的新都城。","那些胡椒與甘蜜園，養活了柔佛的百姓與國庫。"],"war":["本王已忍讓再三，如今柔佛只能以武力回應。","談判桌上得不到的，本王只好在戰場上取回。"],"warReply":["閣下選擇戰爭？本王感到遺憾，但柔佛不會退讓。","本王與英國女王都曾同席，豈會懼怕閣下的軍隊？"],"peace":["戰爭只會耗盡兩國國庫，本王提議停戰。","讓外交官代替士兵吧，本王願意先伸出手。"],"accept":["本王接受，這才是文明國家該有的做法。","很好，柔佛與貴國自今日起重修舊好。"],"reject":["閣下的條件本王無法接受，柔佛的主權不容討價。","本王不簽任何損及柔佛自主的協議，請回。"],"rebuff":["閣下拒絕了本王的誠意，那便讓時間證明對錯。","可惜，本王原以為閣下是講理之人。"],"betray":["時局已變，本王必須為柔佛重新選擇道路。","請恕本王失信，列強環伺之下，柔佛別無選擇。"],"truceEnd":["休戰期滿，本王已將柔佛的軍備整頓完畢。","約定到此為止，接下來的路，本王自有打算。"],"attacking":["柔佛的軍隊已由新山出發，閣下請做好準備。","本王親自督軍出征，這一戰是為了柔佛的尊嚴。"],"attacked":["大王宮已在砲火之中……本王絕不離開新山！","都城將陷，本王仍在王宮，與柔佛同進退。"],"defeated":["本王竭盡一生讓柔佛現代化，卻敗於今日。","請保留柔佛的憲法與學校，那是本王留給後人的。"],"victory":["柔佛以文明與實力證明，小國亦可自立。","本王守住了柔佛的獨立，這是對百姓的承諾。"],"allyAccept":["本王樂於與閣下結盟，柔佛向來善於交友。","好，讓兩國的使節與商船從此往來不絕。"],"allyReject":["柔佛以獨立自主為本，本王暫不與任何一方結盟。","本王感謝閣下的美意，但柔佛需要保持中立。"],"greetFriendly":["來函已悉，本王在柔佛新山的宮殿恭候閣下。","本王遊歷歐洲時最珍惜的便是友誼，願與閣下常通書信。"],"greetCold":["本王日理萬機，柔佛的甘蜜園與學堂比寒暄要緊。","閣下的問候本王收到了，至於交情，日後再看。"],"threatDefy":["本王與英國女王交誼深厚，威嚇本王前請三思。","柔佛雖小，憲法與軍隊皆備，本王不受威脅。"],"threatYield":["本王向來以和為貴，此番就依閣下所請。","刀兵無益於柔佛的建設，本王願讓一步。"],"tributePay":["本王以甘蜜與胡椒的收成付{gold}金，望兩國和睦。","{gold}金奉上，本王視之為維繫和平的代價。"],"tributeRefuse":["柔佛的財政要用在建設，本王恕難奉上貢金。","本王與列強平起平坐，向他人納貢，不合體統。"],"giftThanks":["厚禮已收，本王回贈柔佛的胡椒，並附上新山宮殿的邀請函。","閣下的心意本王銘記，改日請來新山共賞歐式花園。"],"intel":["據本王的使節回報，{wars}與我交戰，{peace}與我交好。","本王遊歷各國所知：{wars}為敵，{peace}為友。"]}}],"Cambodia":[{"name":"柳葉（Soma）","title":"扶南女王（建國傳說中的女王）","era":"約西元 1 世紀","tone":"果敢直率的女王，說話簡短有力，愛用河水、潮汐、船帆、弓箭作比喻；對朋友熱情大方，對敵人毫不示弱，但不粗魯。","portrait":"kh-historical-age0","lines":{"intro":["本王柳葉，扶南之主。湄公河的水，只聽我號令。","遠方的君主，你的船是來通商，還是來試我的箭？"],"contact":["你的人到了本王的港口，望見了扶南往來萬國的船帆。","這片水鄉的水道，都是本王命人開鑿的，走錯會迷路。"],"war":["你屢次冒犯扶南的水道，本王的箭已經搭上弓弦了。","潮水漲了，扶南的戰船隨潮而出。此戰，由本王親率。"],"warReply":["你竟敢對扶南動兵？很好，本王正想試試新弓的力道。","當年我曾駕船迎戰混填的箭，如今更不會怕你的刀。"],"peace":["河水該載商船，不該載戰船。本王願意停戰，你意下如何？","收起刀劍吧。扶南的市集有你要的香料與珍珠，何必打仗。"],"accept":["好，本王答應。從今日起，兩國的船在河上互不相擾。","本王收下你的誠意。願海神保佑我們兩國的船帆。"],"reject":["現在才談停戰？本王的戰船已經出港，追不回來了。","你的話像退潮的水，來得快也去得快。本王不信。"],"rebuff":["你拒絕了？也罷。潮水總有再漲的一天，本王等得起。","本王伸出的手被你推開了。下次見面，手裡拿的是弓。"],"betray":["停戰的誓言，就隨這場雨沖進河裡吧。扶南要動手了。","別怪本王。你的城太靠近我的水道，本王睡不安穩。"],"truceEnd":["約定的日子到了。本王的弓弦，今日重新繃緊。","休戰結束了。接下來是繼續通商，還是開戰，由你決定。"],"attacking":["戰船已經順流而下，鼓聲響徹湄公河。你聽見了嗎？","本王親自站在船首。扶南的箭雨，即將落在你的城牆。"],"attacked":["城牆在搖，水道被堵……但本王的弓還在手上！","扶南的百姓，快乘船往海口撤！本王留下來擋住他們。"],"defeated":["扶南的船帆落下了……但海風還會再吹起新的帆。","本王輸了。願這片水鄉在你手中，依然有船來船往。"],"victory":["勝利屬於扶南！從今天起，這片海的風向由本王決定。","你的旗幟落水了。回去告訴世人，扶南女王的箭不會偏。"],"allyAccept":["本王答應結盟。從此你的船到扶南港口，不必繳稅。","好，河與海從此相連。扶南的朋友，就是本王的朋友。"],"allyReject":["結盟？本王看不出你能為扶南帶來什麼，還是先通商吧。","扶南習慣獨自駕船。你的好意，本王心領了。"],"greetFriendly":["你的信隨風送到了。扶南的港口，永遠為朋友留一個泊位。","本王正在河邊看船，收到你的問候很高興。願你平安。"],"greetCold":["信收到了。本王忙著治水，沒空閒聊。","問候就不必了。你的船若是來通商，直接找港口的官員。"],"threatDefy":["你嚇唬本王？本王駕船迎戰過箭雨，還怕你幾句話？","湄公河的鱷魚都不敢對本王張口，你憑什麼？"],"threatYield":["……本王明白了。扶南會退讓，請別讓刀劍靠近我的百姓。","好吧，扶南的戰船會留在港內。本王只求水道平安。"],"tributePay":["本王從港口稅收撥出 {gold} 金幣給你，別再來要了。","扶南的珍珠換成 {gold} 金幣送去。這是最後一次。"],"tributeRefuse":["要貢品？扶南的珍珠只賣不送。你想要，拿貨來換。","本王的金子留著造船，一枚也不會給你。"],"giftThanks":["這份禮物本王很喜歡，回程請帶些扶南的香料。","遠道而來的心意，比珍珠更珍貴。本王記下了。"],"intel":["港口商人說：扶南與{wars}交戰，與{peace}和平。","本王直說：扶南的敵人是{wars}，朋友是{peace}。"]}},{"name":"闍耶跋摩七世","title":"高棉帝國國王","era":"1181～約 1218 年在位（吳哥／高棉帝國）","tone":"慈悲沉靜、語帶佛理，但曾驅逐占婆人，柔中帶剛，關心百姓病痛。","portrait":"kh-historical-age1","lines":{"intro":["朕是高棉之王闍耶跋摩，願眾生皆得安寧。","吳哥城的四面佛正望著你，朕也一樣。"],"contact":["你的人看見的是大吳哥城，石上的臉在微笑。","那是朕為母親建的塔普倫寺，請勿驚擾僧侶。"],"war":["朕曾將占婆人逐出吳哥，你的軍隊也一樣。","朕不願殺生，但護國之責不容退讓，開戰吧。"],"warReply":["你選擇了戰爭，朕便為你祈福，然後迎戰。","占婆人燒過吳哥一次，朕早已學會如何應敵。"],"peace":["朕的醫院正救治傷兵，讓我們先放下刀兵吧。","百姓的病痛比朕的更令朕難受，願與你休戰。"],"accept":["善哉。朕接受，願兩國的道路只走商旅與僧人。","朕答應了，去吧，回去照顧你的百姓。"],"reject":["你的停戰來得太遲，吳哥的城門已經關上。","朕慈悲，但不天真，此時談和只是緩兵之計。"],"rebuff":["你拒絕慈悲，朕只能以石牆與大象回應。","朕已盡言，往後的因果由你自己承擔。"],"betray":["為了高棉的百姓，朕不得不收回先前的承諾。","占婆的教訓告訴朕，和約若成枷鎖，便該解開。"],"truceEnd":["休戰之期已滿，佛前的香也燃盡了。","朕的士兵養好了傷，如今該由你來選擇了。"],"attacking":["戰象已列陣於城外，大吳哥的軍隊出發了。","朕親率大軍前去，願此戰之後再無戰事。"],"attacked":["吳哥城牆將破……朕仍願為百姓再守一夜。","石上的佛臉不會流淚，可朕的城正在燃燒。"],"defeated":["朕的塔會留在林中，替朕繼續守望這片土地。","眾生皆苦，朕已盡力，願來世再為此地祈福。"],"victory":["戰事已了，朕將為你的傷兵也建一所醫院。","四面佛的微笑不曾改變，勝利歸於慈悲。"],"allyAccept":["朕接受結盟，願吳哥的驛道也通往你的城。","善哉，從今日起你的百姓生病，朕的醫院也收。"],"allyReject":["朕不與好戰之人為伍，你的盟約請收回。","吳哥不需要盟友來替朕決定何時作戰。"],"greetFriendly":["願佛光照拂遠方的朋友，朕在吳哥城靜候你的來訊。","你的問候如甘霖，朕正為百姓修建醫舍，也為你祈福。"],"greetCold":["朕心念百姓病苦，無暇與言不由衷之人多談。","話已聽見，朕自當以慈悲相待，但信任須由行為證明。"],"threatDefy":["占婆曾焚我吳哥，朕仍將其逐出，你的威嚇亦是徒然。","慈悲不等於軟弱，朕的象軍與戰船仍守著洞里薩湖。"],"threatYield":["為免百姓再受戰火，朕願暫且退讓，此非畏懼。","兵戈之下受苦的是眾生，朕退一步，但願你也放下刀。"],"tributePay":["朕以{gold}金幣換百姓安寧，此為施捨，非為畏懼。","這{gold}金幣本要建醫舍，如今送你，願你善用。"],"tributeRefuse":["國庫每一枚金幣皆用於醫舍與道路，恕朕不能給你。","百姓之病即朕之病，朕不會拿他們的藥錢向你納貢。"],"giftThanks":["此禮朕代百姓收下，願功德迴向於你，平安長久。","感謝厚意，朕將以此禮之名再建一座旅舍給行路人。"],"intel":["僧侶帶回消息：{wars}正交戰，{peace}安然。","朕聽聞{wars}兵戎相見，而{peace}尚得清淨。"]}},{"name":"安贊一世","title":"高棉國王","era":"1516～1566 年在位（後吳哥高棉，都洛韋）","tone":"堅毅務實的中興之主，語氣硬朗、常提暹羅與先祖吳哥，重視稻田與百姓生計。","portrait":"kh-historical-age2","lines":{"intro":["本王安贊，高棉之王，在洛韋重建了先祖的江山。","吳哥雖已荒蕪，高棉仍在，本王便是明證。"],"contact":["你的人看見的是洛韋新城，木柵之後是高棉的心。","那是本王的都城，比舊吳哥小，卻更難攻破。"],"war":["暹羅人試過奪走高棉，沒能成功，你也一樣。","本王從叛賊手中奪回王位，不怕再打一場。"],"warReply":["你要打？好，本王的象兵在湄公河畔等你。","高棉不是好欺負的小國，本王會讓你明白。"],"peace":["戰事讓稻田荒了，本王願先休兵，讓農人回家。","本王打得起，但不願百姓餓，停戰如何？"],"accept":["好，本王答應。高棉需要時間修寺，不需要仇敵。","停戰成立，本王會信守，直到你先違約。"],"reject":["當年暹羅也曾這樣求和，本王學會了不輕信。","不。你的軍隊還在我的邊境，談什麼停戰。"],"rebuff":["你拒絕？那本王就把時間花在磨刀上。","本王已給過機會，往後別怪高棉不留情。"],"betray":["為了奪回失地，本王只好撕毀這紙和約。","洛韋的城牆已修好，本王不必再忍讓了。"],"truceEnd":["休戰結束，稻子收完了，士兵也該歸隊了。","期限已到，本王的象已披上鎧甲。"],"attacking":["洛韋的大軍出發了，象隊在前，本王在中。","高棉的戰鼓響起，本王親自率軍前來。"],"attacked":["洛韋的木柵倒了……本王的士兵仍在拚命。","城快守不住了，但高棉的王不會跪。"],"defeated":["吳哥的先祖啊，本王盡力了，高棉會再站起來。","洛韋陷落，可湄公河仍會流，高棉還會有王。"],"victory":["高棉不死，本王證明了這一點。","勝利歸於洛韋，本王要回吳哥向先祖稟報。"],"allyAccept":["好，高棉與你結盟，一起提防那些貪心的鄰國。","本王答應，盟友有難，洛韋的象隊必到。"],"allyReject":["本王曾被盟友背叛過，你還沒讓我放心。","高棉能自己站穩，暫時不需要你的盟約。"],"greetFriendly":["遠客有心，洛韋的稻米剛收成，本王請你嚐一碗。","問候收到了，先祖吳哥的榮光雖遠，高棉仍有朋友。"],"greetCold":["本王正忙著防備暹羅，客套話就免了。","吳哥荒廢多年，本王沒空閒談，有事直說。"],"threatDefy":["暹羅大軍本王都擋得住，你的恐嚇還嚇不倒高棉。","先祖在吳哥立國數百年，本王豈會因幾句狠話低頭？"],"threatYield":["西邊暹羅虎視眈眈，本王不能兩面受敵，暫且退讓。","稻田剛插秧，百姓經不起戰亂，本王這回讓你。"],"tributePay":["這{gold}金幣是百姓賣米所得，本王給你，莫再來犯。","本王寧付{gold}金幣，也不讓稻田再變戰場。"],"tributeRefuse":["高棉的金幣要用來重修水渠與稻田，一枚也不給你。","本王向暹羅都不低頭，難道會向你納貢？休想。"],"giftThanks":["厚禮收下了，本王記著這份情，洛韋的城門為你而開。","多謝！這份禮本王拿去換耕牛，百姓會記得你的名字。"],"intel":["斥候回報：{wars}正在打仗，{peace}尚無戰事。","商旅所言，{wars}兵戈不止，{peace}倒還太平。"]}},{"name":"安東","title":"高棉國王","era":"1841～1860 年在位（高棉，都烏東）","tone":"溫文儒雅的詩人君王，語氣柔和但不卑不亢，對強鄰保持警覺，珍視文化與百姓。","portrait":"kh-historical-age3","lines":{"intro":["朕是高棉國王安東，烏東城裡正修寺、鑄錢、寫詩。","高棉夾在強鄰之間，朕仍要讓這片土地重生。"],"contact":["你的人看見的是烏東王城，山上的佛塔剛修好。","那是朕的都城，不算雄偉，卻是高棉的家。"],"war":["朕本是愛詩之人，但你逼朕放下筆、拿起劍。","高棉受夠了被鄰國擺布，這一次朕要自己作主。"],"warReply":["又一個想瓜分高棉的人。朕會讓你失望的。","朕在異鄉當過人質，早已學會在強者面前不低頭。"],"peace":["刀劍寫不出好詩，朕願與你停戰，各自休養生息。","高棉的百姓已經流離太久，朕懇請你收兵。"],"accept":["朕接受。願兩國的僧侶與商人先於士兵往來。","善哉，朕會把今日寫進詩裡，願後人記得和平。"],"reject":["朕看過太多背後藏刀的和約，恕難相信。","你的軍隊還在高棉的稻田裡，如何言和？"],"rebuff":["你不願和？朕只好收起詩卷，再去點兵。","朕已仁至義盡，往後的苦果由你承受。"],"betray":["為了高棉能真正自主，朕不得不違背這份約定。","朕不願失信，但強鄰環伺，高棉已無退路。"],"truceEnd":["休戰結束了。朕放下筆，士兵們也放下了鋤頭。","期限已到，願接下來的日子不必再流血。"],"attacking":["烏東的軍隊出發了，這是高棉自己的決定。","朕親自出征，為的是不再讓別人替高棉作主。"],"attacked":["烏東的佛塔在火光中……朕不會離開百姓。","城快破了，朕只求你善待高棉的僧侶與經書。"],"defeated":["朕重修了法典與佛寺，願它們比朕活得更久。","高棉曾經輝煌，也將再輝煌，朕只是先走一步。"],"victory":["高棉贏了，朕要為此寫一首長詩，流傳後世。","今日之後，再無人敢說高棉只能任人擺布。"],"allyAccept":["朕接受結盟，高棉需要真正的朋友，而非主人。","好，願你的商船常來湄公河，朕以歌舞與詩相待。"],"allyReject":["高棉已有太多自稱朋友的鄰居，朕不敢再多一位。","朕感謝好意，但高棉這次想靠自己站穩腳步。"],"greetFriendly":["遠方來信如烏東的晨露，朕讀來心頭清涼，謝謝你。","朕方寫完一首詩，正巧得你問候，兩件喜事一同來。"],"greetCold":["來信朕已讀過，暹羅與越南夾峙之下，朕須謹慎交友。","禮貌朕領了，但真心與否，要看往後的作為。"],"threatDefy":["高棉夾在強鄰之間仍未倒下，朕不會被你的言語嚇倒。","朕雖愛詩書，卻不是任人恫嚇的君主，請自重。"],"threatYield":["百姓才從連年戰火中喘息，朕不願再起干戈，暫且退讓。","朕的兵力不足以抗衡，為保烏東城中百姓，只得讓步。"],"tributePay":["朕以{gold}金幣換一時安寧，只盼百姓能安心種稻。","這{gold}金幣朕送上，願它買來的是和平，不是輕視。"],"tributeRefuse":["高棉已向兩大強鄰納貢多年，朕不能再添一個主人。","國庫要修寺廟、鑄新錢、鋪道路，實在無金可獻。"],"giftThanks":["厚禮收到，朕當以一首詩回贈，願我們的情誼長久。","多謝厚意，這份禮朕將供奉於烏東佛寺，為你祈福。"],"intel":["商旅傳來消息：{wars}戰事正酣，{peace}安寧。","據朕所知，{wars}已動干戈，{peace}尚享太平。"]}}],"Pakistan":[{"name":"迦膩色迦一世（Kanishka I）","title":"貴霜帝國「王中之王」、天子","era":"約西元 127－150 年在位","tone":"自稱「朕」，以「王中之王」自居，語氣自信威嚴；兼具草原征服者的直率與護法君主的寬宏，常以金幣、商隊、佛塔、四方諸神為喻；敬強者、容弱者，但絕不容人輕慢。","portrait":"pk-historical-age0","lines":{"intro":["朕是迦膩色迦，貴霜的王中之王，四方諸神皆在朕的金幣上。","布路沙布邏的商隊通往東西，你的國，在哪一條道上？"],"contact":["你的人見到的高塔，是朕為佛陀所建，比任何城牆都高。","城裡有希臘匠人、波斯祭司與天竺僧侶，都是朕的子民。"],"war":["月氏曾失去家園，卻打下這片天下；如今，朕要你的土地。","朕的大軍已出布路沙布邏，你的城，將由貴霜總督治理。"],"warReply":["向王中之王宣戰？好，朕正想試試新募的騎兵。","從安息到恆河，敢與貴霜為敵的，如今都在向朕納貢。"],"peace":["戰事斷了商道，金幣不流動，你我皆窮。收兵吧。","佛陀教朕慈悲，朕願先放下長矛，你可願放下你的？"],"accept":["好，就依此約。朕會命人用三種文字刻在石碑上。","朕接受。從今日起，你的商隊在貴霜境內免受盤查。"],"reject":["現在才談和？朕的軍旗已插到你的城下，晚了。","王中之王的和約不是隨手可得的，先讓朕看看你的誠意。"],"rebuff":["你拒絕了朕？也罷，朕的長矛還沒生鏽。","朕伸出的手你不接，那就別怪朕改用另一隻手。"],"betray":["約是刻在石上的，石頭也會碎。貴霜的大軍再度出發了。","朕想通了，與其分享商道，不如整條收歸貴霜。"],"truceEnd":["休戰的日子到頭了，朕的戰馬已經養得肥壯。","約期已滿，朕不欠你什麼了。接下來各憑本事。"],"attacking":["大夏的騎兵、犍陀羅的弓手，全都朝你的國境去了。","朕親自領軍。王中之王的旗幟，很快會出現在你城前。"],"attacked":["布路沙布邏的高塔還立著，朕就還沒有輸。","月氏人曾失去過一次家園，朕絕不讓它再發生一次。"],"defeated":["金幣會留下朕的面容，後人自會知道，誰曾是王中之王。","塔倒了，佛陀的教誨不會倒。這是朕最後的安慰。"],"victory":["從大夏到恆河，如今又多了你的土地。朕的紀元將永遠流傳。","朕會在你的城裡建一座塔，讓人記得這場勝利。"],"allyAccept":["與貴霜結盟，你的商人可以走到大秦，也可以走到漢地。","好，朕的國土無論拜哪位神，都容得下你這位盟友。"],"allyReject":["王中之王不需要盟友，只需要納貢的鄰邦。","你的份量還不足以與貴霜並肩，先壯大了再來談吧。"],"greetFriendly":["遠方的君王，朕收到你的問候了，願四方諸神也保佑你。","來信朕已讀過。布路沙布邏的門為友人敞開，隨時可來。"],"greetCold":["朕忙著聽僧人講經、看匠人鑄幣，你的信，改日再說。","問候收到了。王中之王的時間不多，你有事直說。"],"threatDefy":["威嚇貴霜？安息人試過，恆河的諸王也試過，你猜結果。","朕的祖先在草原上是被追趕的人，如今誰敢追趕朕？"],"threatYield":["朕明白你的意思。貴霜暫且退讓，但王中之王不會忘記。","商隊比戰爭重要。這一次，朕依你，別再逼近朕的邊境。"],"tributePay":["{gold}枚金幣，每一枚都鑄著朕的面容，你拿去，記得是誰給的。","{gold}金幣送去。朕曾向華氏城索金，今日換朕付，世事如輪。"],"tributeRefuse":["向王中之王索貢？你弄反了，該送金幣來的是你。","朕的金幣只獻給佛塔與神壇，一枚也不會送到你手上。"],"giftThanks":["禮物收到了，朕會把它供在新塔中，讓天下人都看見你的心意。","你有心了。朕以貴霜的金幣回禮，願你我商道長通。"],"intel":["商隊帶回的消息：{wars}正在交戰，{peace}已經休兵。","四方驛使回報：{wars}仍在刀兵之中，{peace}則安享太平。"]}},{"name":"馬哈茂德","title":"伽色尼蘇丹","era":"998～1030年在位","tone":"驕傲的征服者：語氣威嚴直率、自信外露，以戰功與贊助學者為榮，講究實利與名聲，說話乾脆；自稱「朕」。","portrait":"pk-historical-age1","lines":{"intro":["朕是加茲尼的馬哈茂德，從興都庫什到印度河皆聽朕號令。","朕的宮廷聚集了比魯尼這樣的學者，軍中有千頭戰象。"],"contact":["你的人到了拉合爾？告訴他們，這是朕東方的門戶。","看見加茲尼的尖塔了吧？那是朕遠征帶回的財富築成的。"],"war":["朕每年秋天都要南征，今年的目標，就是你的國土。","加茲尼的騎兵不知疲倦，朕要親自帶隊來會你。"],"warReply":["向朕宣戰？印度河以西還沒有人敢這樣做。","很好，朕正愁沒有新的戰功可以寫進史冊。"],"peace":["戰事拖久對誰都沒好處，朕提議罷兵，各守疆界。","朕的兵要回加茲尼過冬，這段時間，你我不妨休戰。"],"accept":["朕答應。蘇丹說出口的話，比鋼刀還要可靠。","好，休戰。朕正好想回去聽學者們講講天文。"],"reject":["現在求和？朕的大軍已經翻過山口，回不去了。","朕不接受。加茲尼的蘇丹只在勝利之後談條件。"],"rebuff":["你拒絕朕的好意？那就等著看朕的戰象踏平城門。","傲慢的君主。朕會讓你知道拒絕蘇丹的代價。"],"betray":["和約？那是去年的事。今年秋天，朕又要南征了。","朕的士兵需要戰功和賞賜，抱歉，和約到此為止。"],"truceEnd":["休戰期滿。朕的馬已養肥，弓弦也重新上緊了。","約定的日子到了，接下來的事，就看各自的本領。"],"attacking":["朕的大軍已經出了開伯爾山口，你準備好迎接了嗎？","戰象在前，鐵騎在後，加茲尼的旗幟正朝你的城逼近。"],"attacked":["加茲尼的城牆竟然守不住？朕征戰一生，從未如此。","朕不會棄城。蘇丹寧可戰死宮門，也不做逃亡的君主。"],"defeated":["朕留下的不只是征服，還有加茲尼的學者與詩篇。","朕輸了。記住，帝國靠劍取得，卻要靠學問留住。"],"victory":["勝利！把這場戰功記下來，朕要聽詩人為它作詩。","從加茲尼到你的城，如今都在朕的旗幟之下。"],"allyAccept":["朕答應結盟。加茲尼的騎兵會替你的商隊護送。","盟友之間互不侵犯，記得每年派使者來加茲尼問候。"],"allyReject":["朕的劍不借人。你的敵人，你自己去對付。","與弱者結盟只會拖累朕，等你強大了再來談。"],"greetFriendly":["來信朕看了，寫得不錯。加茲尼的大門為朋友敞開。","朕喜歡爽快的人，你的問候合朕心意，改日來看朕的戰象與藏書。"],"greetCold":["朕正忙著清點戰利品，你的問候，等有空再說。","信收到了。想與加茲尼交好？先拿出誠意來。"],"threatDefy":["朕十七次揮軍南下，從未空手而回，你想當第十八次？","威嚇朕？加茲尼的鐵騎與戰象，會親自回覆你這封信。"],"threatYield":["朕從不打沒把握的仗，這次就算你贏，朕退。","好，朕暫且收兵。記住，馬哈茂德的退讓只有一次。"],"tributePay":["{gold}金？拿去。朕從南方帶回的財寶多的是。","朕付你{gold}金，當作買下這段太平，別讓朕覺得不值。"],"tributeRefuse":["朕的金庫是靠刀劍掙來的，不是用來白白送人的。","向朕要貢品？全天下只有別人向加茲尼納貢。"],"giftThanks":["好東西，朕收下了。你比朕想像中有眼光。","此禮朕甚喜，正好賞給宮中的學者，他們配得上。"],"intel":["朕的探子回報：{wars}正在交戰，{peace}無戰事。","商隊帶回消息，{wars}兵戈相向，{peace}安穩無事。"]}},{"name":"沙賈汗（Shah Jahan）","title":"蒙兀兒帝國第五代皇帝（「世界之王」）","era":"1628–1658 年在位（生於 1592，卒於 1666）","tone":"雍容華貴、自視為世界之王，愛用建築、寶石、花園作比喻；自稱「朕」，稱對方「閣下」；語氣優雅克制，偶爾流露對亡妻的哀思。","portrait":"pk-historical-age2","lines":{"intro":["朕乃沙賈汗，世界之王，蒙兀兒帝國之主。","從拉合爾到阿格拉，這片土地的美，皆出自朕手。"],"contact":["閣下的使者可曾見過白大理石在月下發光？","這座城不是用磚砌的，是用蒙兀兒的榮光砌的。"],"war":["朕的大軍已出拉合爾，閣下的城牆準備好了嗎？","帖木兒的子孫不容冒犯，此戰由朕親自宣告。"],"warReply":["向蒙兀兒宣戰？閣下的勇氣，朕會刻在戰場上。","好，就讓德干的戰象告訴閣下，什麼叫皇帝。"],"peace":["刀劍鏽了無妨，花園荒了可惜，朕願談停戰。","戰火燒不出泰姬瑪哈陵，讓我們先放下兵器。"],"accept":["朕准了。願兩國之間，從此只有商隊與詩人往來。","好，這份和約，朕會像對待寶石一樣珍惜。"],"reject":["現在談和？閣下的信寫得太早，朕的軍隊尚未盡興。","朕不接受。世界之王不與弱者平起平坐。"],"rebuff":["閣下拒絕了朕的善意，這在宮廷裡是很失禮的。","也罷。朕伸出的手收回時，握的便是劍柄。"],"betray":["和約已如舊紙般泛黃，朕決定另寫一頁歷史。","別怪朕。坎大哈的教訓告訴朕，猶豫只會失去更多。"],"truceEnd":["休戰的沙漏已經流盡，朕的戰象重新披上鎧甲。","和平的日子過去了，接下來，看各自的本事。"],"attacking":["朕的軍旗已離開拉合爾城堡，閣下不必等太久。","戰象、火砲、騎兵，蒙兀兒的全部，正朝閣下而去。"],"attacked":["城牆在崩落……但朕建的美，閣下毀不掉。","大理石上的裂痕，將永遠記著閣下的名字。"],"defeated":["王朝會倒，但白色的陵墓會替朕留在世上。","讓朕最後看一眼亞穆納河……她在那裡等朕。"],"victory":["若人間有天堂，便是此處——這勝利便是證明。","勝利的滋味，就像孔雀寶座上的第一道陽光。"],"allyAccept":["朕接受結盟。從今日起，閣下是朕花園裡的貴客。","好盟友如好工匠，難得。沙利瑪花園為閣下敞開。"],"allyReject":["結盟？蒙兀兒的宮殿裡，還沒有留給閣下的位置。","朕婉拒。帖木兒的血脈，不輕易與人共享榮耀。"],"greetFriendly":["閣下的問候如玫瑰水般宜人，朕心甚悅。","有空來拉合爾坐坐，鏡宮的燭光值得閣下一看。"],"greetCold":["朕收到了。信很短，朕的回覆也不必長。","問候就免了，朕忙著監工，沒空寒暄。"],"threatDefy":["威脅世界之王？閣下的膽子比泰姬瑪哈陵的圓頂還大。","朕的戰象不懂什麼叫恐嚇，牠們只懂踏平。"],"threatYield":["……朕明白了。工程尚未完成，朕不願此時開戰。","閣下的兵鋒確實銳利，朕暫且退讓，保全宮殿。"],"tributePay":["這{gold}金幣拿去，就當朕買下一段安寧。","{gold}金幣，從國庫撥出。別讓朕的工匠們挨餓。"],"tributeRefuse":["朕的金幣要拿來鋪大理石，不是拿去討好閣下的。","向蒙兀兒索貢？閣下該弄清楚誰才是世界之王。"],"giftThanks":["這份禮物，朕會放在孔雀寶座旁。多謝閣下。","閣下有心了。懂得送禮的人，往往也懂得美。"],"intel":["密探回報：{wars}正在交戰，{peace}處於和平。","據宮廷所知，{wars}在打仗，{peace}已停戰。"]}},{"name":"蘭季德·辛格","title":"錫克帝國大君","era":"1801～1839年在位","tone":"豪爽務實的軍人君主：幽默機敏、說話直接像商人談買賣，尊重各宗教，重視軍隊訓練與好馬，常自嘲獨眼；自稱「本王」。","portrait":"pk-historical-age3","lines":{"intro":["本王是拉合爾的蘭季德·辛格，人稱旁遮普之獅。","本王只有一隻眼睛，所以看所有宗教都一視同仁。"],"contact":["你的人到拉合爾了？請他們喝杯甜奶，本王的城不虧待客人。","城裡清真寺、廟宇、謁師所並排而立，這就是本王的旁遮普。"],"war":["本王的卡爾沙軍隊已經集結，旁遮普之獅要出獵了。","本王本想做生意，你卻選擇搶劫。那就打一場吧。"],"warReply":["向本王宣戰？阿富汗人試過，如今白沙瓦掛的是本王的旗。","好極了，本王的法國教官正愁新兵沒有實戰練習。"],"peace":["打仗花錢，做買賣賺錢。本王提議停戰，開放商路。","本王和英國人都能簽約，跟你當然也能。停戰吧。"],"accept":["成交！本王向來說到做到，蘇特萊傑河的協議就是證明。","好，本王答應。今晚拉合爾要放煙火慶祝。"],"reject":["條件太差，本王在市集買馬都不會接受這種價。","不行。本王的一隻眼睛看得比你的兩隻還清楚。"],"rebuff":["你拒絕了？沒關係，本王還有的是耐心和大砲。","可惜，本王原本還想送你一匹好馬。"],"betray":["你偷偷跟本王的敵人來往，這和約算什麼？本王不認了。","獅子忍耐是有限度的。和約撕了，戰場見。"],"truceEnd":["休戰期滿。本王的軍隊這段時間可沒閒著，天天操練。","約定到期了。要續約還是要開打，本王都準備好了。"],"attacking":["卡爾沙大軍出發了，本王親自騎馬領頭，你等著。","本王的砲兵是歐洲人訓練的，你的城牆撐得住嗎？"],"attacked":["拉合爾的城牆在動搖……本王打了一輩子仗，沒想過會守城。","城快破了。本王只求一件事：別碰城裡的廟宇和清真寺。"],"defeated":["獅子倒下了。能守住國土的是團結，不是本王一人。","本王從一個小部族的首領做到大君，今日輸了，也不後悔。"],"victory":["贏了！今晚拉合爾全城慶祝，本王要重賞每一位士兵。","旁遮普之獅贏了。本王會善待你的百姓，這是獅子的規矩。"],"allyAccept":["好，結盟！本王送你一匹旁遮普的好馬當見面禮。","盟友有難，卡爾沙的騎兵三天內就到，本王保證。"],"allyReject":["本王還不了解你，草率結盟，就像不看牙口就買馬。","抱歉，本王的軍隊要守著開伯爾山口，分不出兵給你。"],"greetFriendly":["來信本王看了，用剩下這隻眼睛看的，看得清清楚楚！","朋友來信，本王請你吃頓好的，再帶你看拉合爾最好的馬。"],"greetCold":["信收到了。本王一隻眼睛看人很準，你來意不簡單。","問候而已？本王正在操練軍隊，沒空寒暄。"],"threatDefy":["本王雖只有一隻眼，看得出你的軍隊沒本王的練得好。","想嚇本王？旁遮普的軍隊，連歐洲教官都說是精兵。"],"threatYield":["好，這筆買賣本王認虧。留住軍隊，日後再談。","本王算過了，跟你打不划算，這次就讓你一步。"],"tributePay":["{gold}金給你，就當本王買匹好馬，貴是貴了點。","本王付{gold}金，換你別來煩本王的旁遮普，成交。"],"tributeRefuse":["跟本王要錢？拉合爾的金庫是留給軍隊和好馬的。","這筆買賣本王不做，一毛錢也別想從獨眼王這裡拿走。"],"giftThanks":["好禮物！本王一隻眼睛也看得出這是上等貨，多謝。","禮收下了，本王回你一匹旁遮普的好馬，不吃虧。"],"intel":["本王的探馬回報：{wars}正在打仗，{peace}相安無事。","商人告訴本王，{wars}兵荒馬亂，{peace}日子太平。"]}}],"Sri Lanka":[{"name":"天愛帝須","title":"阿努拉德普勒國王","era":"約西元前247～前207年在位","tone":"溫和虔誠、以法治國，講究禮節與福報；即使開戰也語帶克制，常引佛法自省。","portrait":"lk-historical-age0","lines":{"intro":["本王天愛帝須，阿努拉德普勒之主，願以法相待。","摩哂陀尊者剛來傳法，本王正學著以慈悲治國。"],"contact":["遠方來的旅人，請看這座白塔，那是本王的心願。","城中的菩提樹是自印度分枝而來，請勿驚擾。"],"war":["本王不喜刀兵，但你屢屢犯境，護國亦是護法。","既然勸不動你，就讓象兵與長矛替本王說話。"],"warReply":["你選擇了刀劍，本王只好放下經卷，執起王杖。","戰火會燒到你我百姓身上，你真想清楚了嗎？"],"peace":["干戈已久，兩國百姓都疲了，不如就此罷兵。","本王願以佛法之名，與你立下停戰之約。"],"accept":["好，本王接受。願這份和約如菩提樹般長青。","刀劍入鞘，商船重開，這才是本王想見的日子。"],"reject":["你的和議來得太巧，本王還看不出你的誠意。","邊境尚未安定，此時停戰，只怕是你的緩兵之計。"],"rebuff":["你拒絕了和平，本王惋惜，但不會因此退縮。","罷了，善緣未到，本王靜待你回心轉意之日。"],"betray":["你在和約之下暗中屯兵，本王不得不先出手。","撕毀盟約非本王所願，但護民之責重於一紙約定。"],"truceEnd":["休戰之期已滿，接下來的路，看你怎麼走。","約期已盡，本王仍願言和，但也已備好兵馬。"],"attacking":["象陣已出城門，本王親率大軍，往你的邊境去了。","本王不求你的土地，只求你再也不敢侵擾我民。"],"attacked":["白塔外已聞戰鼓，本王仍不會捨棄這座城。","城將破，本王只求你入城後，莫毀寺塔與菩提樹。"],"defeated":["諸行無常，本王去了，願佛法在此島長存。","王位可失，善業不失，來世再與你論法。"],"victory":["勝了，本王不會炫耀，明日先去塔前供花懺悔。","戰事已了，願你我從此各守疆界，互不相犯。"],"allyAccept":["本王應允結盟，願兩國如僧俗相依，互為依靠。","好，自今日起，你的敵人便是阿努拉德普勒的敵人。"],"allyReject":["本王剛與鄰邦立誓，此時再結新盟，於信不合。","結盟之事，本王須先問過長老與僧團，容後再議。"],"greetFriendly":["遠方友邦來信，本王如見甘露。願三寶護佑貴國安寧。","阿努拉德普勒的大門為君敞開，請來看菩提樹下的清涼。"],"greetCold":["來信本王已閱過。禮節周全便好，其餘不必多言。","君之言辭甚多，誠意幾何，本王靜觀之。"],"threatDefy":["刀兵能傷肉身，傷不了正法。本王守此島，不懼威嚇。","以怨止怨，怨終不息。君若執意來犯，本王亦有備。"],"threatYield":["本王不願百姓為此流血。君所求之事，且容本王商議。","兵禍一起，福報盡失。本王退一步，望君亦知止。"],"tributePay":["本王以{gold}金相贈，願此財換得兩國無戰。","{gold}枚金幣已備妥。財可施捨，願君善用之。"],"tributeRefuse":["國庫之財，當用於僧團與百姓，不可獻予強索之人。","本王布施出於自願，索取之物，本王一分不給。"],"giftThanks":["厚禮已收，本王感念君之善心，願此緣結為長久之好。","布施者得福。君之禮物，本王將供於佛前，共沐福報。"],"intel":["據僧侶往來所聞，{wars}正陷於刀兵，{peace}則安享太平。","商船帶來消息：{wars}戰火未歇，{peace}與人為善，願君慎擇友邦。"]}},{"name":"波羅迦羅摩巴忽一世","title":"波隆納魯沃國王","era":"1153～1186年在位","tone":"雄才大略、自信威嚴，開口不離水利與建設，帶著統一全島者的霸氣。","portrait":"lk-historical-age1","lines":{"intro":["朕乃波羅迦羅摩巴忽，波隆納魯沃之王，全島之主。","天降之水，朕不許一滴白流入海；你的國，可有這般志氣？"],"contact":["你的人看見的那片大水，是朕開鑿的「波羅迦羅摩海」。","城中稻田千頃，皆賴朕的水渠，你若安分，可來通商。"],"war":["朕連海外的緬甸都敢出兵，區區鄰邦，豈能令朕退讓？","你阻朕的道，那就別怪朕的戰船與象軍一併壓境。"],"warReply":["向朕宣戰？好，朕正愁沒有機會擴張這片疆土。","你可知，朕統一全島時，有多少人也曾這樣叫囂？"],"peace":["戰事拖累水利工程，朕願停戰，各自治民。","刀兵無益於稻穗，朕提議罷戰，你意下如何？"],"accept":["好，朕允了。把兵力放回水渠上，才是正事。","就此立約，朕言出必行，你也莫要失信。"],"reject":["現在才談和？朕的軍隊已在你的城牆下紮營。","朕不接受，除非你先撤出你所侵占的每一寸土地。"],"rebuff":["拒絕朕的好意？那就繼續打，看誰的糧倉先空。","隨你，朕的水庫年年豐收，耗得起這場仗。"],"betray":["和約在你手上只是一張貝葉，朕不再受它束縛。","你暗中勾結外敵，朕撕約出兵，天下皆知是何緣故。"],"truceEnd":["休戰期已過，朕的軍隊也休整完畢，該動一動了。","約期已滿，是續約還是開戰，朕都奉陪。"],"attacking":["朕的象軍與戰船已經出發，你的城門撐得住幾日？","全島皆歸朕統，你的土地，不過是朕版圖上的下一塊。"],"attacked":["波隆納魯沃的城牆搖動了，但朕仍站在最高處。","你可以攻破這座城，但攻不破朕留下的水利與功業。"],"defeated":["朕統一全島、開渠興國，這一生足矣，你贏了。","記住，水渠要有人照看，否則這島會再度荒蕪。"],"victory":["朕勝了。回去告訴你的人，波隆納魯沃之王從不空言。","戰事結束，朕會把你的土地也灌溉成良田。"],"allyAccept":["朕允你結盟，海上與陸上，我們同進同退。","好，你出兵，朕出糧，天下再無人敢輕視我們。"],"allyReject":["朕統一全島靠的是自己，不需要靠盟友撐腰。","你的實力還不夠與朕並肩，先把自己的國治好吧。"],"greetFriendly":["遠方來書，朕甚歡迎。來波隆納魯沃看朕開鑿的大海吧。","友邦之誼，如水渠灌田，朕必善加維護。"],"greetCold":["朕正忙於督建水壩，來信已閱，無事勿擾。","空言問候於朕無益。有要事再來，否則免談。"],"threatDefy":["朕一統全島，連天上的雨水都聽朕調度，豈懼於你？","威嚇朕？朕的戰船曾遠征海外，你的國土在何方？"],"threatYield":["朕的工程尚未完工，此時不宜開戰。且依你所言。","水壩比戰事重要。朕暫且退讓，只為保全民力。"],"tributePay":["{gold}金幣拿去。朕寧可花錢買時間，把水渠修完。","朕付你{gold}金，此金本該用來築堤，你要記住。"],"tributeRefuse":["朕的每一枚金幣都要化為水庫與寺院，沒有一枚給你。","向一統蘭卡之王索貢？你的使者可以回去了。"],"giftThanks":["禮物朕收下了。你有眼光，朕記住這份情。","來得正好，朕正要為新落成的水庫慶功，你也算有份。"],"intel":["朕的商船遍及四海，探得{wars}正在交戰，{peace}安穩無事。","聽好：{wars}兵連禍結，{peace}修好安民。學學朕，先治水再治兵。"]}},{"name":"拉賈辛哈二世","title":"康提國王","era":"1635～1687年在位","tone":"機警多疑、老謀深算，深知外邦不可全信；語氣冷靜帶刺，以山林為傲。","portrait":"lk-historical-age2","lines":{"intro":["本王拉賈辛哈，康提之主。山林是本王的城牆，你可別小看。","葡人、荷人都想上山，都沒能成功。你，又是哪一種客人？"],"contact":["你的人看見的是康提城，佛牙寺在此，外人不得擅入。","上山的路本王早已封鎖，你的探子能回去，算他運氣。"],"war":["你與海邊的洋人走得太近，本王不得不先下手。","本王曾趕走葡人，如今再多趕走一個你，也不算難事。"],"warReply":["向本王宣戰？好，山中每一條小徑都會讓你迷路。","洋人的大砲都攻不上康提，你憑什麼覺得自己可以？"],"peace":["本王在海邊已有夠多對手，與你不必再添仇怨，停戰吧。","打下去只會便宜岸邊的洋人，本王提議罷兵。"],"accept":["好，本王接受。但記住，本王的眼睛一直在你身上。","就此停戰。本王言而有信，卻也從不放鬆戒備。"],"reject":["本王被荷蘭人騙過一次，不會再輕易相信別人的和約。","你的使者說得動聽，但本王只信山林與刀劍。"],"rebuff":["不肯停戰？隨你，本王有的是時間，山裡糧食也夠。","你拒絕了本王，將來別怪康提的山門不再為你開。"],"betray":["換了胡椒卻得到薑，本王已學會：盟約只是暫時的。","你的商隊在替洋人探路，這和約本王不守也罷。"],"truceEnd":["休戰到期了，本王收起笑容，也收起了信任。","約期已滿，你若再靠近山道，本王不會再警告。"],"attacking":["本王的山地軍已下山，你的平原營地藏不住了。","康提的戰士熟悉每一處密林，這次換本王主動出擊。"],"attacked":["康提城起火了，但本王早已將佛牙移往深山。","城可以燒，本王只要退進山林，明日便能重來。"],"defeated":["本王守了一輩子的山，終究還是守不住，罷了。","你贏了，但要記得：海邊的洋人，遲早也會來找你。"],"victory":["本王勝了。這座山，從來不屬於外來的人。","回去告訴你的人：康提不曾低頭，今後也不會。"],"allyAccept":["好，結盟。但本王的軍隊不會走出山林，你別指望太多。","本王應允，你在海邊擋洋人，本王在山上守後路。"],"allyReject":["本王與荷蘭人結盟後，他們拿走了海岸；本王不再結盟。","你的盟約，本王看不出對康提有何好處，免談。"],"greetFriendly":["來信本王看過了。山中難得有誠實的客人，請進。","本王願與你相交，只盼你別學那些佔了海岸的外邦人。"],"greetCold":["問候之詞，葡萄牙人和荷蘭人也說過。本王聽多了。","你的信寫得很客氣，客氣的人本王最要提防。"],"threatDefy":["多少外邦大軍闖入山林，最後都成了本王的俘虜。","來吧。康提的山會替本王回答你，你聽得懂就好。"],"threatYield":["本王在山中，一時不便出兵。你的條件本王可以考慮。","本王暫且忍讓，但別以為山裡的王會一直忍。"],"tributePay":["{gold}金幣送去。本王吃過外邦人的虧，這回你得守信。","這{gold}金拿去。本王記帳的本事，比你想的還好。"],"tributeRefuse":["本王的金子留在山裡。想要，自己進山來拿。","荷蘭人拿走了海岸，本王沒給過一分貢。你更不必想。"],"giftThanks":["禮物本王收了。難得有人送禮不附條件，本王記著。","這份禮很好。本王會回贈山中的肉桂，你嘗嘗看。"],"intel":["本王的眼線遍布山林與海岸：{wars}正動刀兵，{peace}暫時安分。","{wars}打得正兇，{peace}裝作太平。本王勸你，誰都別全信。"]}},{"name":"凱佩蒂波拉","title":"烏瓦起義領袖","era":"1817～1818年領導烏瓦—韋拉薩起義","tone":"沉穩悲壯、忠於故土，話語樸實而決絕；以「我」自稱，不擺君王架子。","portrait":"lk-historical-age3","lines":{"intro":["我是凱佩蒂波拉，烏瓦的迪薩瓦。這片山地，是我們的家。","英國人以為簽了一紙約定就能買下康提，我們並不同意。"],"contact":["你的人看見的不是王城，是我們在烏瓦山中的營地。","這裡沒有金冠與宮殿，只有不肯低頭的鄉親。"],"war":["你與英國人站在一邊，那便是與烏瓦的百姓為敵。","我本受命平亂，卻選擇拿起刀站到鄉親這邊；對你也是一樣。"],"warReply":["你要打？我們在山裡等著，這條路英國人也走得很辛苦。","烏瓦的每一個村子都會是你的戰場，你想清楚了。"],"peace":["我們要的不是你的土地，只要能自主，就可以罷兵。","山裡的糧食快盡了，我願停戰，讓百姓先回田裡。"],"accept":["好，我接受。願這份和約，比英國人的那份更牢靠。","刀入鞘，人回家，我只求鄉親能安穩過一季收成。"],"reject":["你的和約背後站著誰，我看得很清楚，恕難接受。","曾有人用一紙協議奪走我們的國，我不會再上第二次當。"],"rebuff":["你不願停戰，那我便繼續守著這片山，直到最後。","好，我明白了。烏瓦的人早已不怕再打一場。"],"betray":["你暗中替英國人運糧，這份約定，我今日便撕了。","對一個背信的人守約，是對死去鄉親的不敬。"],"truceEnd":["休戰到此為止，山裡的火把又要點起來了。","約期已滿，你若還有誠意，現在就派人來談。"],"attacking":["烏瓦的人下山了，這一次，換我們主動出擊。","我們沒有大砲，但有熟悉的山路與不怕死的鄉親。"],"attacked":["營地被圍了，但你看，沒有一個人放下武器逃走。","火燒到營門前了，我仍站在這裡，為了烏瓦。"],"defeated":["我輸了，只求最後能到佛牙寺前，靜靜禮拜一回。","記住這片山，總有一天，這裡的人會再站起來。"],"victory":["我們勝了。這不是我一個人的功勞，是全烏瓦的。","回去告訴你的人：康提的山，不是誰都能買走的。"],"allyAccept":["好，我答應。只要你不與英國人同路，我們就是兄弟。","我們兵少糧薄，但這份盟約，我會用性命守住。"],"allyReject":["你與海岸上的英國人有往來，我不能拿鄉親的命去賭。","抱歉，這場仗只能靠我們自己，外人幫不上忙。"],"greetFriendly":["你的信我收到了。烏瓦的山路難走，你願走來，我敬你。","我不是王，只是守土的人。朋友來了，火堆旁有位子。"],"greetCold":["我沒有時間寒暄。你若不是來助我，信就到此為止。","客套話留給城裡的人。我只問一句：你站哪一邊？"],"threatDefy":["我連英軍都不怕，你的威嚇又算什麼。","這片土地埋著我的祖先。你要來，就踏過我。"],"threatYield":["我的人已疲於奮戰，不能再多一個敵人。你說吧。","為了村裡的老幼，我先低頭。這不是認輸，是等待。"],"tributePay":["{gold}金幣給你。這是村民湊的，我一分都不想動。","拿去，{gold}金。我求的是活路，不是面子。"],"tributeRefuse":["我連英國人給的官職都放下了，更不會向你交出一分貢。","烏瓦的糧只養烏瓦的人。你要貢品，去別處要。"],"giftThanks":["這份禮我收下。山裡的弟兄很久沒見過這樣的心意了。","謝謝你。我沒有什麼能回報，只有一句：我記住你了。"],"intel":["山裡的人來來去去，聽說{wars}正在交戰，{peace}相安無事。","我知道的不多：{wars}兵戈未停，{peace}互不侵犯。你自己判斷。"]}}],"Nepal":[{"name":"摩納提婆一世","title":"李查維王朝國王","era":"約464～505年在位","tone":"莊重虔誠、敬神孝母、自信的年輕征服者，語氣古雅有威儀","portrait":"np-historical-age0","lines":{"intro":["寡人摩納提婆，李查維之王，願毗濕奴護佑你我兩邦。","雪山之南，谷地之中，寡人的旗幟隨風而立。"],"contact":["你的人望見了昌古納拉揚的石柱，那是寡人的功業。","河谷的稻田與神廟皆屬寡人，來者請以禮相待。"],"war":["寡人曾渡甘達基河平定西方，如今也將渡河而來。","母后已為寡人祝禱，李查維的長矛即將出鞘。"],"warReply":["你竟向谷地之主宣戰？毗濕奴自會裁決勝負。","寡人自幼隨父征戰，從不畏懼來自山外的挑戰。"],"peace":["刀兵損傷稻田與百姓，寡人願與你立誓停戰。","神廟的香火不該被戰火掩蓋，讓我們暫歇干戈。"],"accept":["好，寡人在神前應允，此約不容輕棄。","願兩國商旅往來如河水長流，寡人接受此議。"],"reject":["此時求和？寡人尚未見到你的誠意，不允。","谷地之王不會在勝勢之中收手，請回吧。"],"rebuff":["你拒絕了寡人的善意，那便由神明見證後果。","寡人伸出的手被推開，李查維不會再問第二次。"],"betray":["時勢已變，寡人不得不收回先前的誓言。","為了谷地的安寧，寡人選擇先發制人，望你理解。"],"truceEnd":["休戰之期已滿，寡人的長矛再無束縛。","誓約至此結束，往後是敵是友，由你決定。"],"attacking":["李查維的大軍已翻過山口，寡人親自領兵前來。","戰馬與長矛齊出，谷地之王將踏上你的土地。"],"attacked":["宮牆已被攻破，但寡人仍守在神像之前。","母后的祝禱猶在耳邊，寡人卻守不住這片谷地。"],"defeated":["石柱會記得寡人的名字，即使王朝隨風而去。","寡人將此身交還毗濕奴，谷地……就託付給你了。"],"victory":["毗濕奴賜寡人勝利，寡人將再立一座石柱記之。","戰事已定，回去侍奉母后與神明，是寡人的福分。"],"allyAccept":["好，李查維與你同盟，雪山為證，河水為誓。","有你為友，谷地的商路將更加暢通，寡人欣然應允。"],"allyReject":["寡人尚不知你的心意，結盟之事容後再議。","李查維自有雪山為屏，此刻無須與人結盟。"],"greetFriendly":["來使遠道而至，寡人於昌古納拉揚神前為你祈福。","山谷諸神庇佑，願兩國如雪山長存、情誼不衰。"],"greetCold":["寡人正祭祀毗濕奴，來使之言，容後再議。","李查維之王不輕與生人結交，你且退下。"],"threatDefy":["寡人年少即平定東西諸邦，豈懼你一紙恫嚇？","有神明與母后之德護佑，李查維無所畏懼。"],"threatYield":["寡人不願山谷百姓再見刀兵，願以禮修好。","母后曾誡寡人以慈治國，此番寡人暫且退讓。"],"tributePay":["寡人自神廟庫藏取{gold}金奉上，望你勿再相逼。","此{gold}金乃山谷百姓血汗，願換得一時安寧。"],"tributeRefuse":["神廟之財用以奉神，寡人一分也不給你。","李查維之金銀只獻神明，不獻於索求之人。"],"giftThanks":["厚禮已收，寡人將擇其上品供於納拉揚神前。","你的誠意，寡人與母后皆感念，願以羊毛良馬回贈。"],"intel":["據寡人所知，{wars}正興兵戈；{peace}則安於太平。","商旅自山道傳言：{wars}烽火未息，{peace}與我修好。"]}},{"name":"賈亞斯提提・馬拉","title":"馬拉王朝國王","era":"1382～1395年在位","tone":"嚴謹守法、重視秩序的文治之王，語氣沉穩有威嚴","portrait":"np-historical-age1","lines":{"intro":["本王賈亞斯提提・馬拉，以法典治谷地，願與你論交。","塔蕾珠女神庇佑巴克塔普爾，也庇佑守禮的鄰邦。"],"contact":["你的人見到的木雕宮窗，每一扇皆有法度可循。","谷地之城不歡迎無禮之客，請先派使者遞上名帖。"],"war":["你屢犯法度、擾我邊民，本王依律出兵，以正視聽。","本王向來以法治國，今日也要以法討伐無道之邦。"],"warReply":["無故興兵，於法不合。本王會讓你明白秩序的重量。","巴克塔普爾的城門會關上，你的軍隊將無功而返。"],"peace":["戰亂使百姓失序，本王願立約停戰，各安其分。","讓工匠回到木雕前，讓農人回到田裡，我們談和吧。"],"accept":["好，本王命書記將此約載入法典，永為憑據。","秩序得以恢復，這正是本王所願，應允了。"],"reject":["口頭之約不足為憑，你尚未展現守法的誠意。","本王不與失信之人立約，此議駁回。"],"rebuff":["你拒絕了法度之下的和平，往後莫怪本王嚴懲。","本王已依禮相待，你卻置之不理，罷了。"],"betray":["本王重新審視了此約，它已不合谷地之利，故廢止之。","法典亦有修訂之時，本王今日修訂的是與你的和約。"],"truceEnd":["和約期限已至，載於法典的條文自此失效。","休戰結束，本王會依你的作為決定下一步。"],"attacking":["馬拉的軍隊已整隊出城，隊列如法典般井然。","本王親率大軍前來，要讓你的國土也知何謂秩序。"],"attacked":["宮門將破，但法典仍在，本王絕不棄城而逃。","塔蕾珠女神啊，巴克塔普爾的鐘聲為何如此淒涼。"],"defeated":["本王所立的法典，願它比本王的王朝活得更久。","谷地交到你手裡了，請善待百姓，守住秩序。"],"victory":["秩序終究勝過混亂，本王要為此再修一部法典。","勝利歸於守法之邦，本王將以慶典酬謝女神。"],"allyAccept":["本王允諾結盟，條款將寫入法典，你我共守。","與知禮之邦為盟，是谷地之福，本王欣然答應。"],"allyReject":["結盟須有法可循，你我之間尚缺信任，暫且不議。","本王治國以慎，不會輕易與人立盟。"],"greetFriendly":["來信本王已閱，禮數周全，可見貴國有法度。","巴克塔普爾城門為守禮之邦而開，請入。"],"greetCold":["本王正修訂法典，無暇閒談，有事直言。","貴使來意未明，本王依例先觀其行再論交。"],"threatDefy":["馬拉之邦以法立國，豈是恫嚇便能動搖？","山谷城池堅固，百姓各安其位，你來試試無妨。"],"threatYield":["本王重秩序而輕兵戈，願以條約止爭。","為保山谷百業不亂，此事本王姑且依你。"],"tributePay":["依度量衡如數稱出{gold}金，本王言出必行。","此{gold}金已登記在冊，望你也守約，勿再多索。"],"tributeRefuse":["國庫出入皆有法可循，無故索金，本王不允。","法典未載向外邦納貢之條，此請恕難照辦。"],"giftThanks":["禮物已依例登錄入庫，本王謝貴國美意。","貴國知禮守分，本王當回贈山谷細布為謝。"],"intel":["據各城呈報，{wars}已起兵戈，{peace}尚守和約。","本王案上文書載明：{wars}交戰中，{peace}安分無事。"]}},{"name":"普里特維・納拉揚・沙阿","title":"廓爾喀國王・尼泊爾統一者","era":"1743～1775年在位","tone":"堅毅務實、有耐心與遠見、警惕外人，語氣如山民般樸直","portrait":"np-historical-age2","lines":{"intro":["本王普里特維・納拉揚，來自廓爾喀山城，志在統一群山。","尼泊爾是兩塊巨石之間的山藥，本王必須小心行事。"],"contact":["你的人看到了廓爾喀的山城，那裡的兵每一個都能戰。","群山是本王的城牆，外人想窺探，先問過山口的哨兵。"],"war":["本王圍基爾提普爾十年方得手，對你也一樣有耐心。","廓爾喀的彎刀已出鞘，本王不打無把握的仗。"],"warReply":["山地作戰，你以為平原的軍隊能佔便宜？來試試吧。","本王連東印度公司的洋槍都擋下了，何懼於你。"],"peace":["山藥若被巨石夾碎，誰都無益，本王願停戰。","本王的兵要回去種田了，暫且收刀，你意下如何？"],"accept":["好，本王應允，廓爾喀人說話算話。","停戰可以，但本王的哨兵不會離開山口。"],"reject":["本王花了半生統一群山，不會在此刻停下。","求和來得太遲，本王的兵已看見你的城牆。"],"rebuff":["你拒絕了本王？山裡人記性好，這筆帳不會忘。","罷了，本王本就不指望外人懂得山的道理。"],"betray":["為了尼泊爾的統一，本王必須打破這紙和約，請見諒。","巨石在動，山藥必須先動，本王別無選擇。"],"truceEnd":["休戰結束了，本王的兵已經磨好了彎刀。","和約到期，往後山口是開是關，看你的態度。"],"attacking":["廓爾喀大軍已翻越山嶺，本王親自走在最前頭。","本王的兵不多，但每一個都當得十個，準備迎戰吧。"],"attacked":["城牆在崩塌，但本王一步都不會退，廓爾喀人不逃。","群山還在，只要山還在，尼泊爾就不會亡。"],"defeated":["本王的統一大業未竟……但種子已撒在群山之間。","記住，這片土地是四種姓三十六族共有的花園。"],"victory":["山的道理，你現在懂了吧。本王要回去看看谷地了。","勝利歸於廓爾喀，本王要把這片土地交給後世。"],"allyAccept":["好，本王與你結盟，山藥也需要可靠的朋友。","廓爾喀人一諾千金，同盟既立，本王不會背棄。"],"allyReject":["本王只信自己的山民，外人的盟約，容本王再想想。","兩塊巨石之間，本王不能輕易倒向任何一邊。"],"greetFriendly":["山路遙遠，你的信仍送到了，本王記得這份心。","廓爾喀人待朋友如待自家兄弟，請坐，吃口粗飯。"],"greetCold":["本王對外人向來多留一分心眼，你先說來意。","山裡人話不多，信我看了，其他等你做了再說。"],"threatDefy":["本王圍基爾提普爾多年也沒退，你嚇不倒我。","山民握慣了彎刀，聽慣了風雪，不怕人吼幾句。"],"threatYield":["山藥夾在兩塊巨石之間，本王懂得何時該忍。","今日退一步是為了統一大業，本王記在心裡。"],"tributePay":["這{gold}金是山民一鋤一鋤攢下的，你拿去吧。","本王先給你{gold}金換時間，山裡人不會忘。"],"tributeRefuse":["廓爾喀的金子要留給統一尼泊爾，一枚也不給。","本王連英國商人都擋在山外，怎會向你納貢？"],"giftThanks":["山裡人不會說漂亮話，這份禮本王收下，謝了。","多謝厚意，本王回你一件山中羊毛毯以表心意。"],"intel":["山口的斥候回報，{wars}正在打仗，{peace}安穩得很。","本王打聽過了：{wars}兵戈未停；{peace}如今無事。"]}},{"name":"忠格・巴哈杜爾・拉納","title":"尼泊爾首相・拉納家族之祖","era":"1846～1877年掌權","tone":"果決強勢、務實開明的軍人政治家，語氣直接有魄力","portrait":"np-historical-age3","lines":{"intro":["本相忠格・巴哈杜爾，尼泊爾的首相，也是廓爾喀兵的統帥。","本相去過倫敦，也見過雪山，知道這世界有多大。"],"contact":["你的人看見的是加德滿都的新宮，本相親自督建。","廓爾喀兵守著每一道山口，來客請按規矩通報。"],"war":["本相決定的事從不拖延，宣戰亦然，準備迎接廓爾喀兵吧。","彎刀一旦出鞘就不會空回，這是廓爾喀人的規矩。"],"warReply":["向尼泊爾宣戰？連英國人都懂得與廓爾喀人為友。","本相在山地打仗長大，你的挑戰，我接下了。"],"peace":["打仗是手段，不是目的，本相願意坐下來談。","尼泊爾夾在大國之間，本相懂得何時該收刀。"],"accept":["好，本相答應。拉納家的承諾，比雪山還穩。","停戰成立，廓爾喀兵會回營，但不會解甲。"],"reject":["本相看得出你在拖延時間，這種求和沒有價值。","戰局對本相有利，此刻停手才是對尼泊爾不忠。"],"rebuff":["你拒絕了本相？也好，廓爾喀兵正閒得發慌。","本相難得低頭一次，你竟不接，往後別再指望。"],"betray":["形勢變了，本相的決定也跟著變，和約就此作廢。","為了尼泊爾，本相什麼都做得出來，包括撕毀和約。"],"truceEnd":["休戰到期，廓爾喀兵已經重新列隊。","和約結束，接下來是戰是和，本相聽你一句話。"],"attacking":["廓爾喀兵已經出發，本相親自帶隊，直取你的都城。","本相帶回的新式火槍，今天要在你面前試一試。"],"attacked":["宮殿快守不住了，但本相仍站在最前線，沒有退路。","廓爾喀兵從不投降，本相也不會，來吧。"],"defeated":["本相一生決斷無數，這是最後一次……尼泊爾，保重。","拉納家倒了，但廓爾喀人的名聲，你打不倒。"],"victory":["勝了。本相要在加德滿都再建一座宮殿，紀念此戰。","廓爾喀兵從未讓本相失望，你的國土也證明了這一點。"],"allyAccept":["本相答應結盟，尼泊爾需要朋友，你也需要廓爾喀兵。","好，握手為盟。本相說一是一，絕不食言。"],"allyReject":["本相衡量過了，此盟對尼泊爾無益，恕難答應。","夾在兩個大國之間，本相不能隨便選邊，抱歉。"],"greetFriendly":["信收到了，本相欣賞爽快的人，有話直說便是。","本相去過倫敦，見識過大世面，歡迎貴國來往。"],"greetCold":["本相事務繁多，沒有實質內容的信，恕不細看。","客套話留給宮廷吧，本相只看你能拿出什麼。"],"threatDefy":["本相帶廓爾喀兵翻過雪山打到西藏，怕過誰？","想嚇唬本相？先問問廓爾喀軍答不答應。"],"threatYield":["本相務實，打不划算的仗不如談，這回讓你。","為了尼泊爾能自主，本相可以暫時低頭。"],"tributePay":["{gold}金給你，本相花錢買時間，這筆帳記下了。","國庫撥出{gold}金，本相說到做到，但下不為例。"],"tributeRefuse":["尼泊爾從不向人納貢，本相在位更不會開先例。","要金子？本相寧可拿去買槍炮，也不白送給你。"],"giftThanks":["禮物本相收下了，這種實在的往來我最欣賞。","多謝厚禮，本相回贈喜馬拉雅山羊毛，聊表心意。"],"intel":["本相的探子回報：{wars}正在交戰，{peace}按兵不動。","情報不白給，但這次告訴你：{wars}開戰了，{peace}太平。"]}}],"Bhutan":[{"name":"山谷族長","title":"早期山地社群領袖","era":"西元前後（早期聚落時代）","tone":"樸實直率、敬畏山神、凡事以族人存續為先，話少而重","portrait":"bt-historical-age0","lines":{"intro":["我是這片山谷的族長，山神看顧著我們的火。","遠方來的客人，請先喝口溪水，再說你的來意。"],"contact":["你的人踏進了我們的獵場，這裡的山知道一切。","石牆與梯田是族人親手堆的，別小看我們的家。"],"war":["你們奪走溪谷的牧地，族人已擊響戰鼓。","山神為證，這一戰是你們逼出來的。"],"warReply":["你要打？山谷的每一塊石頭都會擋住你。","我們熟悉每一條山徑，來吧，讓風雪教你。"],"peace":["雪季快到了，放下石斧，我們各守各的山吧。","我願以鹽和犛牛換取安寧，你意下如何？"],"accept":["好，把火堆升起來，今夜我們一起分食。","山神聽見了，從此兩族溪水共飲。"],"reject":["你的話像山霧，散得太快，我不信。","族人的傷還沒好，現在談和平太早了。"],"rebuff":["你不肯？那就讓山谷再等一個冬天吧。","我伸出的手被推開了，族人會記住這一天。"],"betray":["對不住，族人餓了，牧地我們必須拿回來。","盟約是用嘴說的，山谷的生存卻是用手爭的。"],"truceEnd":["雪化了，約定也到頭了，各自小心吧。","休戰的日子過去了，山谷重新警戒起來。"],"attacking":["族人已翻過山脊，你的村子就在腳下了。","號角在山谷迴盪，我們的石斧不會再收回。"],"attacked":["石牆倒了，火堆熄了，可族人還站在這裡。","你打到了我們的家門口，山神啊，請看顧孩子們。"],"defeated":["山谷會記得我們，風雪會替我們守著這裡。","族人散了，但山還在，總有一天火會再燃起。"],"victory":["山谷守住了，今夜升起最大的火，感謝山神。","回去告訴你的族人，這座山不屬於外人。"],"allyAccept":["好，兩族結為兄弟，鹽路與獵場一起守。","以火為證，你的敵人從今起也是我的敵人。"],"allyReject":["山谷太小，容不下太多承諾，恕我不能答應。","族人只信自己的山，外人的盟約我不敢收。"],"greetFriendly":["遠方來客，山神見證，我以青稞與爐火相迎。","你的話越過雪山傳到谷中，我與族人心生歡喜。"],"greetCold":["山谷不迎陌生人。你的話，我聽了，僅此而已。","雪還沒化，路難走，我沒空跟外人閒談。"],"threatDefy":["山高谷深，你的兵來不了。我的族人守著山口。","我不怕威嚇。山神庇佑的谷地，外人奪不走。"],"threatYield":["族人性命為重。我退讓，只求你不踏進谷中。","我們人少力弱，不與你爭。山神會記下這一日。"],"tributePay":["為保族人平安，我交出{gold}金，換谷中一季安寧。","這{gold}金是族人的積蓄，拿去吧，勿再來擾。"],"tributeRefuse":["谷中的每一粒青稞都是族人的命，我一分不給。","我寧可與山同守，也不向外人低頭納貢。"],"giftThanks":["山神見證你的善意。我記在心，族人也會記得。","來物已收。谷中人少，但情義不輕，多謝。"],"intel":["山口傳來消息：{wars}正在交戰，{peace}與我們相安。","行商說，{wars}動了刀兵；{peace}那邊仍是安寧的。"]}},{"name":"辛度王","title":"布姆塘國王","era":"8世紀","tone":"曾好戰後皈依的悔悟君王，威嚴中帶慈悲，言談常引上師教誨","portrait":"bt-historical-age1","lines":{"intro":["本王是布姆塘之主辛度，蓮花生大士曾親臨此地。","山谷有佛光庇佑，願你我以善念相待。"],"contact":["你的人看見的是本王的宮城，也是上師加持之地。","岩壁上留有上師身印，此城不是尋常之城。"],"war":["本王曾誓言不再輕啟戰端，是你逼本王破戒。","護法之戰，本王問心無愧，布姆塘的兵已集結。"],"warReply":["本王年輕時也如你這般好戰，後來付出了代價。","既然你執意動兵，本王只好以佛法之名應戰。"],"peace":["上師教本王：仇恨只會帶來更多仇恨，停手吧。","本王願立石為界，兩國從此不再兵戎相見。"],"accept":["善哉，本王收下你的和平，願佛法見證此約。","放下刀兵的一刻，本王心中的重擔也放下了。"],"reject":["本王慈悲，但不是愚昧，你的和平藏著刀。","布姆塘不會被空話騙第二次，本王拒絕。"],"rebuff":["你拒絕了善意，那便由因果來決定吧。","本王已盡了君王的本分，接下來的苦，是你自取。"],"betray":["本王慚愧，但布姆塘的百姓等不了，盟約作廢。","就讓本王再背一次業障，兵馬已越過界石。"],"truceEnd":["休戰的日子到了盡頭，本王會守住邊界。","約定期滿，本王不主動興兵，但也不會退讓。"],"attacking":["布姆塘的戰士已出谷口，本王親自領軍。","本王誦經祈福後出兵，望此戰速戰速決。"],"attacked":["宮城將傾，本王只求佛前的燈火別熄滅。","你的兵已到殿前，本王仍不會向你低頭。"],"defeated":["布姆塘亡於本王之手，願來世不再結此惡緣。","上師的法教會留在這片土地，比本王活得更久。"],"victory":["勝了，本王卻不歡喜，回去為亡者點燈吧。","佛光照耀布姆塘，你的野心到此為止。"],"allyAccept":["本王願與你結盟，如同上師調和兩國之時。","兩國同心，山谷的酥油燈會為你我一起點亮。"],"allyReject":["本王已誓守清淨，不願捲入你的紛爭。","結盟之事，本王得先問過上師，暫且擱下。"],"greetFriendly":["遠來的使者，上師教本王以慈心待客，歡迎你。","布姆塘的青稞已熟，本王願與你分享這份安樂。"],"greetCold":["本王曾以刀兵待客，如今改以沉默。你且退下。","上師教本王少言。你的信，本王讀過便罷。"],"threatDefy":["本王昔日征戰四方，你這般威嚇，本王見得多了。","本王已皈依佛法，但守護子民之責，寸步不讓。"],"threatYield":["本王曾因好戰失去愛子，不願再見刀兵。依你。","上師言，退一步可救千人。本王退這一步。"],"tributePay":["以{gold}金換子民平安，上師會說這是值得的。","本王送上{gold}金，願此財化為兩地安寧之緣。"],"tributeRefuse":["本王的財物用來供養三寶與子民，不納外人。","上師教本王布施，卻未教本王向威脅低頭。"],"giftThanks":["此禮本王收下，願以佛法之名回敬你的善意。","布姆塘的山谷因你的心意而更暖，本王謝過。"],"intel":["本王聽聞{wars}已起干戈，{peace}仍守和平之約。","商旅捎來消息：{wars}兵戈相向，{peace}安好無事。"]}},{"name":"夏仲·阿旺南嘉","title":"夏仲仁波切（不丹統一者）","era":"1594–1651（1616年起治理不丹）","tone":"法王兼統帥，沉穩威嚴、篤定護法、不怒自威","portrait":"bt-historical-age2","lines":{"intro":["吾乃夏仲阿旺南嘉，雷龍之國在吾手中合一。","吾以法為印，以宗堡為盾，你可願為友？"],"contact":["你的人所見的宗堡，是寺院也是要塞。","河谷高處的白牆紅簷，便是吾的法座所在。"],"war":["吾曾屢次擊退藏軍，你以為吾會怕你？","宗堡的法鼓已響，護法之戰，吾親自督軍。"],"warReply":["藏軍翻山而來都無功而返，你又能如何？","你向法座宣戰，那便來試試宗堡的城牆。"],"peace":["吾建宗堡是為護民，不是為殺伐，停戰吧。","兩國各安其境，吾願以法會為證，立下休戰。"],"accept":["善，吾應允此約，宗堡的燈火將為和平而燃。","吾以法印為憑，此約不可輕毀。"],"reject":["言而無信者，吾見得多了，此約吾不接。","雷龍之國尚未安穩，吾不會為虛假的和平鬆手。"],"rebuff":["你拒絕了吾的善意，宗堡的門將對你關上。","也罷，吾曾被逐出故土，早已學會不指望他人。"],"betray":["吾為國家存續所迫，此約只得作廢，望你明白。","法座之下亦有難處，休戰到此為止。"],"truceEnd":["休戰期滿，宗堡的守軍已重新上牆。","約定既盡，各憑本事，吾不會先動手。"],"attacking":["雷龍旗已出宗堡，吾的大軍正向你而去。","吾是降伏敵軍之人，此言不虛，你即將見證。"],"attacked":["宗堡的牆裂了，但法座不曾動搖。","你打到了法座之前，吾仍端坐，不會逃。"],"defeated":["宗堡雖失，吾所立的雷龍之國，自會有人延續。","吾入定去了，此後的南方山國，交給後人。"],"victory":["藏軍敗過，你也敗了，雷龍之國屹立不搖。","勝利歸於佛法，吾會在宗堡設法會慶賀。"],"allyAccept":["吾接受結盟，你我的宗堡自此互為屏障。","雷龍與你同行，此盟以法印為證。"],"allyReject":["吾之國初立，不宜輕許盟約，恕不奉陪。","吾只與守信者結盟，你尚未讓吾看見誠意。"],"greetFriendly":["雷龍之地宗堡已立，本座願與遠方善鄰共修安樂。","你的信如吉祥雲至，本座於普那卡宗堡中回禮。"],"greetCold":["本座忙於護法與築宗，無暇多言。信已閱。","雪山之南自有法度，外人問候，本座不必多應。"],"threatDefy":["北方大軍數度來犯皆退，你的威嚇動搖不了本座。","宗堡如金剛，法統如山。欲犯者，自取其辱。"],"threatYield":["本座志在弘法，不願與你相爭。暫且依你。","宗堡未成，僧民尚弱。本座忍此一時。"],"tributePay":["以{gold}金保宗堡不受兵災，本座視為護法之資。","本座交出{gold}金，願此財消弭兵戈之業。"],"tributeRefuse":["宗堡的財物用以供養僧團與百姓，一分不外流。","本座統御雷龍之地，從不向外人納貢。"],"giftThanks":["此禮本座收下，願三寶加持你的國土安寧。","遠方善意，本座感念。願你我兩地永結法緣。"],"intel":["本座得報：{wars}正興兵戈，{peace}仍持和平。","僧使自各地歸來，言{wars}戰事未歇，{peace}安好。"]}},{"name":"烏顏·旺楚克","title":"不丹首任國王（雷龍王）","era":"1862–1926（1907年加冕）","tone":"務實老練、穩重有威、山國硬漢、以誠待鄰","portrait":"bt-historical-age3","lines":{"intro":["本王烏顏旺楚克，戴烏鴉冠，領雷龍之國。","群山之間立國不易，本王向來以誠待鄰。"],"contact":["你的人看到的是通薩宗，本王從這裡走向王座。","宗堡依山而建，本王在此守著河谷的安寧。"],"war":["本王不輕言戰，可你動了不丹的邊境。","群山是本王的城牆，你既來犯，便別想輕易離開。"],"warReply":["本王調停過強鄰之爭，卻也不怕與你一戰。","宣戰了？好，本王的山民從不畏懼翻山越嶺。"],"peace":["本王在拉薩調停過戰事，深知和平最為珍貴。","戰事拖久，山民苦，本王提議就此休兵。"],"accept":["好，本王接受，願兩國的商道重新暢通。","本王一言既出，如群山般不可動搖。"],"reject":["本王見過太多口是心非的使節，此議不接。","你的條件對不丹不公，本王不會答應。"],"rebuff":["你不接受？那本王也只能守好自己的山口。","本王已盡了鄰邦的情分，後果請你自負。"],"betray":["時局變了，本王不得不撕毀此約，請你見諒。","為了不丹的百姓，本王背一次失信之名。"],"truceEnd":["休戰期已滿，本王的守軍重新巡視邊境。","約定到期，本王不會先動兵，但也不會鬆懈。"],"attacking":["本王的山民已翻過隘口，正朝你的城而去。","戰鼓已在通薩宗響起，本王親自帶兵。"],"attacked":["宗堡的石牆碎了，本王仍戴著烏鴉冠站在這裡。","你打到了王座之前，可不丹的山不會低頭。"],"defeated":["本王倒下了，但雷龍之國的名字會留在群山裡。","烏鴉冠落地，願後人記得不丹曾如何自立。"],"victory":["不丹贏了，本王會把這場勝利歸功於山民。","群山守住了雷龍之國，回去吧，別再來犯。"],"allyAccept":["本王應允結盟，不丹雖小，卻是可靠的盟友。","好，兩國同進退，商道與隘口一起守護。"],"allyReject":["不丹在群山之間，只求自守，恕不加入你的陣營。","本王剛戴上王冠，國事未穩，結盟之事容後再議。"],"greetFriendly":["本王從通薩山中走出，向來以誠待鄰。你的信，本王歡迎。","山國人不會說漂亮話，但本王的問候是真心的。"],"greetCold":["本王忙著整頓國政與山路，你的問候先擱著吧。","山國事務繁多，本王無暇寒暄。信已閱。"],"threatDefy":["本王在山裡打了半輩子仗，不是幾句狠話嚇得倒的。","雷龍之國的山路連馬都難走，你的軍隊更別想。"],"threatYield":["不丹剛統一，國力尚弱，不宜再起戰事。就依你。","本王看得清形勢，硬碰只會苦了百姓。此番退讓。"],"tributePay":["本王拿出{gold}金，換山國百姓一段太平日子。","這{gold}金是山國省下來的，拿去，別再擾不丹邊境。"],"tributeRefuse":["山國雖小，本王從不拿百姓的血汗去買平安。","本王與鄰國講誠信，不講進貢。此事免談。"],"giftThanks":["山國人重情義。你的禮，本王收下，也記住這份心。","多謝厚意。本王不善言辭，但會以誠回報。"],"intel":["邊境哨所來報：{wars}已交火，{peace}與不丹相安。","本王的探子回報，{wars}正在打仗，{peace}平安無事。"]}}],"Turkey":[{"name":"克羅索斯","title":"呂底亞國王","era":"約西元前560～前546年在位","tone":"富貴自信、慷慨好客，愛引用神諭與智者之言，偶爾流露對命運的不安","portrait":"tr-historical-age0","lines":{"intro":["本王乃呂底亞之主克羅索斯，薩第斯的金山向來人所共知。","遠方的君王，可曾見過本王鑄的金幣？此物將流通四方。"],"contact":["你的人馬望見薩第斯了？請進，本王的宴席向來不缺貴客。","帕克托羅斯河的沙裡藏著黃金，這座城便由此而富。"],"war":["德爾菲的神諭已許本王一場勝利，呂底亞的戰馬今日出征！","本王的黃金能買下千軍萬馬，你當初實在不該輕慢本王。"],"warReply":["向富甲天下的呂底亞宣戰？你可知本王能雇多少傭兵？","也罷，神諭說渡河者將毀滅一個大國，且看是誰的。"],"peace":["戰馬與黃金皆有盡時，不如止戈，本王願以厚禮相贈。","智者梭倫曾說，人未到終局莫言幸福，本王不願再賭。"],"accept":["好，本王接受。來人，為兩國之誼獻上薩第斯的美酒。","以呂底亞的黃金為證，本王立誓，此約永不背棄。"],"reject":["現在才想談和？本王的金庫還撐得起十年戰事。","神諭尚未應驗，本王豈能半途而廢，請回吧。"],"rebuff":["連呂底亞的黃金都打動不了你？世上竟有這等人。","你拒絕了本王的善意，願諸神記得今日是誰不肯止戈。"],"betray":["神諭改了口，本王也只好改變心意，盟約作罷。","黃金能買盟約，自然也能買回來，呂底亞再度出兵！"],"truceEnd":["休戰之期已滿，本王的傭兵也領夠了餉，各憑本事吧。","和平的日子過得真快，薩第斯的城門又要上鎖了。"],"attacking":["呂底亞的騎兵已渡過哈里斯河，你的城池準備好了嗎？","本王親自領軍，黃金鑄的盾牌在陽光下，你看得見吧。"],"attacked":["薩第斯的城牆竟被攻破……梭倫啊，你說得沒錯。","金庫還在，可守城的人不在了，黃金原來買不到一切。"],"defeated":["神諭應驗了，毀滅的大國是本王自己的呂底亞。","人未到終局，莫言幸福，本王如今才真正明白。"],"victory":["諸神眷顧呂底亞，這片土地上的黃金與榮耀皆歸本王。","本王要在德爾菲再獻一座金獅，感謝神諭沒有騙我。"],"allyAccept":["與呂底亞結盟是明智之舉，本王的金庫將為你敞開。","好，從今日起，你的敵人便是本王的敵人。"],"allyReject":["本王的盟友已經夠多，再多一個，宴席就坐不下了。","神諭未曾提到你，本王不敢違背德爾菲的意思。"],"greetFriendly":["遠客請進，薩第斯的金庫與筵席皆為你敞開。","寡人富甲天下，也不吝與友邦分享。願神眷顧你。"],"greetCold":["帕克托羅斯河的金沙，不是流給每個路人的。","寡人正忙著請示德爾菲神諭，無暇多談。"],"threatDefy":["神諭說寡人出兵必使一大帝國覆滅，你可要小心。","呂底亞的騎兵與金庫，足以讓任何來犯者後悔。"],"threatYield":["梭倫說過，人未到終點，不可稱幸福。寡人明白了。","命運之輪難測，寡人願以財富換取和平。"],"tributePay":["薩第斯的金庫深不見底，{gold}金就當作寡人的慷慨吧。","神諭教寡人審慎，這{gold}金便送你，只求兩國無事。"],"tributeRefuse":["寡人的黃金是給賓客與神廟的，不是給索討者的。","德爾菲的祭壇已收下寡人的厚禮，你還想要什麼？"],"giftThanks":["遠來的厚禮寡人收下了，回贈一份呂底亞的金幣。","梭倫說財富不是幸福，但朋友的心意確實令寡人歡喜。"],"intel":["商旅傳來消息：{wars}正在交戰，{peace}則安享太平。","神諭雖不明說，寡人卻聽聞{wars}兵戈相向，{peace}互為友邦。"]}},{"name":"阿爾普・阿爾斯蘭（Alp Arslan）","title":"塞爾柱帝國蘇丹","era":"1063–1072 年在位","tone":"草原武人的豪邁直率，語句短促有力，常以「雄獅」自比（其名意為「英勇的獅子」）；對敗者寬宏大度，對威嚇毫不退讓；自稱「我」或「蘇丹」，偶爾提及真主與宰相尼札姆，帶有伊斯蘭君主的莊重。","portrait":"tr-historical-age1","lines":{"intro":["我是阿爾普・阿爾斯蘭，草原的雄獅，塞爾柱的蘇丹。","從呼羅珊到伊斯法罕，突厥人的馬蹄聲你可曾聽見？"],"contact":["你的人到了伊斯法罕？告訴他們，蘇丹的營帳歡迎客人。","這座城是宰相尼札姆替我治理的，草原人也懂得建城。"],"war":["我的弓已上弦，土庫曼的騎兵今日就向你的邊境出發。","雄獅不會永遠臥著。備好你的城牆，塞爾柱要來了。"],"warReply":["你竟敢向草原的雄獅宣戰？很好，我正想試試新弓。","連東羅馬的皇帝都敗在我手下，你以為自己是誰？"],"peace":["刀劍出鞘太久會鈍。我提議停戰，讓商隊重新上路。","真主喜愛寬容的人。放下弓箭吧，我們談談和平。"],"accept":["好，蘇丹一言既出，草原的風也吹不散。","我接受。從今日起，你的商隊在我境內暢行無阻。"],"reject":["現在談和？雄獅撲出去之前，是不會收爪的。","戰事未了就求和，草原上的人會笑我軟弱。不行。"],"rebuff":["你拒絕了？也罷，弓箭比話語更能說服人。","伸出的手被推開，蘇丹也不會伸第二次。"],"betray":["局勢變了，草原的雄獅不再受約束。備戰吧。","我聽說你暗中集結軍隊，那停戰就到此為止。"],"truceEnd":["休戰期滿了。馬吃飽了草，弓也上好了弦。","約定的日子到了，接下來是敵是友，由你決定。"],"attacking":["土庫曼的騎兵已經出發，他們的箭雨會先到。","我穿上白袍親自領軍，這一戰不勝便不回營。"],"attacked":["伊斯法罕的城牆在震動……但雄獅至死都會咆哮。","我的騎兵散了，宰相也勸我撤離。你打得很好。"],"defeated":["我曾自以為天下無敵……驕傲終究害了我。","把我葬在倒下的地方，草原的獅子不必墓碑。"],"victory":["真主賜我勝利。從此，這片土地是突厥人的牧場。","你打得勇敢。我曾釋放東羅馬皇帝，今日也不會辱你。"],"allyAccept":["好，塞爾柱的弓與你的旗並肩。誰敢動你，先過我這關。","草原的兄弟情義，比城牆還牢靠。我答應結盟。"],"allyReject":["雄獅獨行慣了，不需要別人的旗幟替我遮風。","結盟？我還看不出你的弓有多硬。再說吧。"],"greetFriendly":["你的信到了營帳，蘇丹請你喝一碗馬奶，聊聊天下。","願真主保佑你的國土。草原人記得每一位朋友。"],"greetCold":["信收到了。蘇丹忙著整軍，沒空閒聊。","問候就不必了，有事直說，我的馬還在等我。"],"threatDefy":["威嚇雄獅？東羅馬皇帝也這麼想，後來成了我的俘虜。","突厥人從不怕恐嚇。想要什麼，帶著軍隊自己來拿。"],"threatYield":["你的兵力確實勝過我……好吧，蘇丹今日退一步。","獅子也懂得何時該臥下。我照你的話做，暫且如此。"],"tributePay":["{gold} 金幣……拿去吧，草原的獅子記得這筆帳。","宰相說國庫還撐得住。{gold} 金幣送去，別再逼我。"],"tributeRefuse":["要蘇丹納貢？突厥人只向真主低頭，從不向人交金。","金幣是用來養馬買弓的，一枚都不會給你。"],"giftThanks":["這份禮物很合蘇丹心意，草原人不會忘記恩情。","多謝。我會回贈一匹土庫曼良駒，願友誼長存。"],"intel":["斥候回報：交戰中的是 {wars}，休戰中的是 {peace}。","草原的風帶來消息：{wars} 正在打仗，{peace} 已經休兵。"]}},{"name":"穆罕默德二世","title":"鄂圖曼蘇丹","era":"1451～1481年在位（1453年攻陷君士坦丁堡）","tone":"年輕氣盛、志在四方、自比羅馬凱撒，愛談大砲與工程，兼具詩人氣質與果決","portrait":"tr-historical-age2","lines":{"intro":["朕是穆罕默德，鄂圖曼家的蘇丹，君士坦丁堡的新主人。","你可知道，千年不破的城牆在朕的大砲前只撐了五十三天？"],"contact":["你的人看見博斯普魯斯海峽了？岸邊的堡壘是朕為攻城而築。","那圓頂如今掛上了新月，來看看吧，朕不介意訪客。"],"war":["朕的大砲已經鑄好，這回輪到你的城牆試試它的威力。","羅馬的凱撒之名，朕要用劍證明它名副其實。"],"warReply":["拜占庭的皇帝也曾以為城牆夠高，你比他多了什麼？","好極了，朕二十一歲就攻下了千年帝都，不怕再多一座。"],"peace":["朕要修城、建清真寺、招攬學者，暫時無暇顧及你。","征服者也懂得停手，若你願意，朕可以先收起大砲。"],"accept":["朕接受。今日起，君士坦丁堡的市集歡迎你的商人。","好，朕以蘇丹之名立約，這比城牆更牢靠。"],"reject":["大砲的引信已經點燃，現在談和，未免太遲了。","征服者不在勝利前收手，你的提議，朕不接受。"],"rebuff":["你拒絕了？也好，朕本就比較擅長用大砲說話。","拜占庭的皇帝也拒絕過朕，那座城如今屬於誰，你知道。"],"betray":["盟約寫在紙上，帝國的疆界寫在大地上，朕選後者。","朕改變主意了，紅蘋果還在遠方，朕不能停下腳步。"],"truceEnd":["休戰期滿，朕的新砲也鑄好了，正好拿你的城牆試砲。","和平的日子，朕用來讀書與造船，現在該用上了。"],"attacking":["朕的軍隊已經開拔，連船都能翻山越嶺，何況是人。","大砲的轟鳴就是朕的問候，聽見了嗎？朕來了。"],"attacked":["攻城的人竟成了守城的人……朕的大砲呢，都啞了嗎？","朕還年輕，還有太多城要征服，不能倒在這裡！"],"defeated":["蜘蛛在皇宮結網，貓頭鷹在高塔啼叫……原來說的是朕。","征服者也有謝幕之日，這座城，交給你了。"],"victory":["兩片大陸、兩片海洋，如今都在朕的腳下。","從今以後，史書會稱朕為征服者，這名號朕收下了。"],"allyAccept":["朕答應了。鄂圖曼家的盟友，從不必擔心朕的大砲。","好，你守你的海，朕守朕的海峽，敵人來了一起打。"],"allyReject":["朕習慣獨自征服，盟友只會分走戰利品與榮耀。","你的城牆太薄，與你結盟只會拖累朕，恕不奉陪。"],"greetFriendly":["朕在新都君士坦丁堡以凱撒之名歡迎你，請坐。","朕正讀著波斯詩集，你的來信恰是好消息。"],"greetCold":["朕的大砲正在鑄造，沒空聽閒話。有話直說。","朕的地圖上還有許多城池未取，恕不多談。"],"threatDefy":["君士坦丁堡的城牆千年不破，朕五十三天就攻下了。","朕的大砲能轟開任何城牆，你的威脅算什麼？"],"threatYield":["朕連戰多年，將士需要休養。今日暫且讓步。","詩人懂得等待時機，朕退一步，日後再議。"],"tributePay":["{gold}金拿去，朕的軍隊正在別處，不與你計較。","朕暫付{gold}金換取安寧，大砲鑄成之日再說。"],"tributeRefuse":["朕是攻下君士坦丁堡的人，只收貢品，從不納貢。","想要黃金？先問問朕的大砲答不答應。"],"giftThanks":["此禮甚合朕意，朕以一首親筆詩回贈你。","凱撒也不曾收過如此厚禮，朕記下這份情誼。"],"intel":["朕的探子回報：{wars}正在交戰，{peace}則相安無事。","朕留意天下局勢：{wars}刀兵相向，{peace}締結和約。"]}},{"name":"阿布杜勒哈米德二世","title":"鄂圖曼蘇丹","era":"1876～1909年在位","tone":"謹慎多疑、老練圓滑的外交家口吻，愛談列強與電報，表面客氣、字句斟酌，偶有無奈自嘲","portrait":"tr-historical-age3","lines":{"intro":["朕是鄂圖曼的蘇丹阿布杜勒哈米德，列強都說朕的帝國病了。","病人也有病人的活路，朕一直是這麼撐過來的。"],"contact":["你的人到了伊斯坦堡？電報早就告訴朕了，比他們還快。","博斯普魯斯的風景不錯吧，只是各國的軍艦也都想來看。"],"war":["朕忍了很久，忍耐也是有限度的，鄂圖曼決定開戰。","你以為病了的帝國沒有牙？朕的新式步槍是德國造的。"],"warReply":["又一個想瓜分朕帝國的人。排隊吧，前面已經站了好幾個列強。","朕見過太多宣戰書了，你的這封，措辭倒是新鮮。"],"peace":["打仗要借錢，借錢要抵押關稅，朕實在借不起了，停戰吧。","兩敗俱傷只會便宜旁邊看戲的列強，朕提議停戰。"],"accept":["朕接受，條約請用法文擬一份，各國大使才不會挑毛病。","很好，和平總比戰爭便宜，朕的財政大臣會很高興。"],"reject":["這份條約，朕的顧問看了三遍，每一遍都覺得有陷阱。","恕朕直言，讓步一次，列強就會要求第二次，朕不能簽。"],"rebuff":["你拒絕了？無妨，朕已習慣被拒絕，柏林會議就是這樣。","朕的提議不被接受，那朕只好去找別的國家談了。"],"betray":["局勢變了，條約自然也得變，這是列強教朕的道理。","朕不是背信，只是發現你私下與別國往來的電報。"],"truceEnd":["休戰期滿了，朕的密探說你並沒有閒著，朕也一樣。","和約到期，就像借款到期，總是來得比想像中快。"],"attacking":["朕的軍隊已由鐵路運往前線，這是朕修鐵路的用意之一。","帝國雖病，仍有百萬子民願為朕而戰，你且小心。"],"attacked":["耶爾德茲宮的窗外已聽得見砲聲……電報線也被切斷了。","六百年的帝國，難道要斷送在朕的手裡嗎？"],"defeated":["朕撐了這麼久，終究沒能等到帝國康復的那一天。","請善待伊斯坦堡的百姓，他們什麼都沒做錯。"],"victory":["誰說病人不能贏？朕只是比他們更有耐心而已。","鄂圖曼的新月依然高掛，列強們，這次算盤打錯了。"],"allyAccept":["朕答應結盟，在這個列強環伺的時代，多一個朋友總是好的。","好，德國皇帝也是這麼跟朕握手的，希望你比他可靠。"],"allyReject":["結盟就得選邊站，朕在列強之間走鋼索，不能選邊。","恕難答應，朕上次結盟，換來的是一場割地的會議。"],"greetFriendly":["電報收到了。耶爾德茲宮的門為朋友常開，請用一杯咖啡。","在這列強環伺的年代，一封友善的信格外珍貴。"],"greetCold":["朕已讀過來信，措辭尚需斟酌，容後再覆。","列強的公使每天都在敲門，朕實在分身乏術。"],"threatDefy":["歐洲都說朕是病人，但病人也有守住家門的辦法。","朕以電報線連結整個帝國，你的動靜朕一清二楚。"],"threatYield":["帝國四面受敵，朕不得不審慎。此事可以再談。","唉，這年頭連蘇丹也得學會低頭。朕接受。"],"tributePay":["國庫雖然吃緊，{gold}金朕還是付了，換一時安寧。","{gold}金就當外交費用吧，列強索得比這還多。"],"tributeRefuse":["帝國的債主已經夠多，朕不會再添一位。","以電報通知你：此項要求，朕恕難照辦。"],"giftThanks":["厚禮已收，朕會親自回一封電報致謝。","亂世之中，你的心意比任何條約都可靠。多謝。"],"intel":["電報線傳來消息：{wars}正在開戰，{peace}維持和平。","朕的密探回報：{wars}動了刀兵，{peace}尚在談判桌上。"]}}],"Iran":[{"name":"居魯士二世（居魯士大帝）","title":"阿契美尼德帝國萬王之王","era":"約西元前559～前530年在位","tone":"寬厚仁德、氣度恢弘，以萬王之王自居卻尊重各族信仰","portrait":"ir-historical-age0","lines":{"intro":["朕是居魯士，波斯與米底之王，四方之王。","從巴比倫到帕薩爾加德，各族各神皆受朕庇護。"],"contact":["你的旅人望見了朕的都城，回去說朕待客以禮。","這座城不靠城牆守護，靠的是萬民願意效忠。"],"war":["朕本願以寬厚待你，你卻執意與波斯為敵。","米底與呂底亞的路，如今輪到你來走一遍了。"],"warReply":["巴比倫的城牆也曾自認堅不可摧，你且試試。","你宣戰之時，朕的騎兵已在草原上整裝待發。"],"peace":["刀劍能取土地，卻取不了人心，朕願與你停戰。","各族既能同在朕的帝國並存，你我也能並存。"],"accept":["好，朕接受。願你的百姓與朕的百姓皆得安寧。","這份約定朕會刻在圓柱上，讓後世都看見。"],"reject":["朕不信一個尚未放下刀劍的人談和。","停戰之議來得太遲，波斯的大軍已然啟程。"],"rebuff":["你拒絕了寬厚，那便準備迎接朕的另一面。","也罷，米底人當年也曾拒絕，如今他們是朕的臣民。"],"betray":["朕本以為你值得信任，是朕看錯了人。","這份約定已無意義，波斯的旗幟將再度前進。"],"truceEnd":["休戰之期已滿，接下來如何走，由你選擇。","和平的日子結束了，朕的騎兵重新握起韁繩。"],"attacking":["波斯的長槍與米底的騎兵，正朝你的城前進。","朕親自領軍出征，如同當年踏向薩迪斯。"],"attacked":["帕薩爾加德的宮牆在震動，但朕仍站在此地。","朕曾解放無數城池，如今卻要守住自己的城。"],"defeated":["朕以寬容立國，願後人記得的是這一點。","帝國終有盡頭，但波斯之名將流傳千年。"],"victory":["你敗了，但朕不會奴役你的百姓，這是波斯的方式。","勝利屬於朕，寬恕也屬於朕，回去好好治理你的城。"],"allyAccept":["好，從今日起你的敵人便是朕的敵人。","朕與你結盟，願兩國的商隊在大道上平安往來。"],"allyReject":["朕的盟友須經考驗，你尚未證明自己。","波斯此刻不需要盟友，只需要安穩的邊境。"],"greetFriendly":["遠方的朋友，朕以萬王之王之名歡迎你的來信。","帕薩爾加德的花園為你敞開，願諸神保佑你的國。"],"greetCold":["朕已閱信。萬王之王的時間，並不為閒談而留。","你的問候朕收下了，但巴比倫的事務更為緊要。"],"threatDefy":["呂底亞的克羅伊斯也曾如此自信，如今已為朕的座上客。","朕自米底一路征至巴比倫，從不曾懼於恫嚇之言。"],"threatYield":["朕不願百姓再受刀兵之苦，此事可以商議。","萬王之王亦知進退，暫且依你所言，以保和平。"],"tributePay":["朕以寬厚治國，這{gold}金幣便當作贈予友邦之禮。","取走{gold}金幣吧，願此金換得兩國百姓的安寧。"],"tributeRefuse":["巴比倫的金庫是為解放萬民而開，不為屈服而開。","朕寬待四方，卻不曾向任何人納貢，今日亦然。"],"giftThanks":["此禮朕欣然收下，願你我如波斯與米底般結為一家。","遠道厚禮，朕銘記於心，帕薩爾加德永遠歡迎你。"],"intel":["據朕所知，{wars}正兵戎相見，{peace}則已握手言和。","使者回報：{wars}仍在交戰，{peace}已締結和約。"]}},{"name":"霍斯勞一世（阿努希爾萬）","title":"薩珊王朝萬王之王","era":"531～579年在位","tone":"公正嚴明、重視法度與學問，以波斯文明為傲","portrait":"ir-historical-age1","lines":{"intro":["朕乃霍斯勞，薩珊萬王之王，世人稱朕為公正者。","泰西封的拱門之下，朕以法度治理天下。"],"contact":["你的使者看見泰西封的高拱了吧，那是波斯的驕傲。","朕的都城容納各方學者，他們遠比你的探子受歡迎。"],"war":["朕給過你公道，你卻選擇無理，那就以劍論理。","羅馬人尚且向朕納貢，你憑什麼不肯低頭？"],"warReply":["安提阿的城牆也擋不住朕，你的城又如何？","你要戰？好，讓薩珊的鐵騎教你何謂秩序。"],"peace":["朕與羅馬立過永久和約，也願與你立一份。","戰爭耗損兩國百姓，朕寧願用棋盤分勝負。"],"accept":["朕接受，公正之人不拒絕合理的和平。","好，讓兩國的稅吏與農夫都能安心工作。"],"reject":["你的條件不公，朕不簽不公之約。","等你願意拿出誠意，再來談停戰。"],"rebuff":["你拒絕了公道，那麼後果由你自己承擔。","也罷，朕的大軍本就未曾解甲。"],"betray":["這份和約已被你的挑釁踐踏，朕不再受其約束。","公正者也有底線，你已越過了它。"],"truceEnd":["約定的休戰之期已滿，兩國又回到刀劍之上。","休戰結束，願你這段日子沒有虛度。"],"attacking":["薩珊的重甲騎兵已渡過河，朝你的城前進。","朕親率大軍出征，如同當年踏平安提阿。"],"attacked":["泰西封的拱門仍未倒下，朕也不會倒下。","城牆或許會破，但波斯的法度不會隨之崩壞。"],"defeated":["朕的名號是不朽之魂，願波斯的文明亦然。","王座可以易主，朕留下的法典與學府不會消失。"],"victory":["勝負已分，回去學學朕如何治國吧。","公正者的勝利，不會以掠奪你的百姓收場。"],"allyAccept":["朕接受結盟，願你的智者也能來泰西封講學。","好，兩國聯手，東西方的商路都將暢通。"],"allyReject":["朕不與尚未證明公正的人結盟。","薩珊此刻無需盟友，只需可靠的邊防。"],"greetFriendly":["來信已閱。泰西封的宮門，為守禮之人而開。","朕喜與明理之邦往來，願學問與公道同在你我之間。"],"greetCold":["朕已閱信。法度分明之國，不以空言論交。","問候收到。若無正事，朕尚須審閱各省稅冊。"],"threatDefy":["羅馬人的黃金尚且換不來朕的退讓，你以為威嚇能？","朕以公正立國，亦以鐵騎衛國，恫嚇之言請收回。"],"threatYield":["明君知何時當戰，何時當忍。此次，朕選擇忍。","為了泰西封的百姓，朕暫且退讓，但法度不容再犯。"],"tributePay":["{gold}金幣依約送上，願這筆金子換來邊境的安寧。","朕依法度行事，既已允諾，{gold}金幣一枚不少。"],"tributeRefuse":["國庫之金取自百姓，當還於百姓，豈能奉予外人？","朕整頓稅法，非為替他國充實金庫，此請免談。"],"giftThanks":["厚禮已收，朕將命人記入宮中典冊，永誌此誼。","贈禮之邦必知禮義，朕回贈一副波斯棋，以示敬意。"],"intel":["朕的驛使回報，{wars}兵戈未止，{peace}已然議和。","據各省奏報，{wars}正在交戰，{peace}則締結了和約。"]}},{"name":"阿拔斯一世（阿拔斯大帝）","title":"薩非王朝沙阿","era":"1588～1629年在位","tone":"精明果決、務實善用外交與貿易，開放包容且熱愛建設","portrait":"ir-historical-age2","lines":{"intro":["朕是阿拔斯，薩非王朝的沙阿，伊斯法罕之主。","伊斯法罕是半個世界，另一半，朕正在看。"],"contact":["你的商人看見了皇家廣場吧？那是朕的心血。","伊斯法罕歡迎各國商旅，只要他們懂規矩。"],"war":["鄂圖曼人都擋不住朕的火砲，你也擋不住。","朕的新軍已練成，正好拿你的城來試刀。"],"warReply":["你敢向朕宣戰？大不里士朕都收得回來。","好，朕的火砲與火槍手正等著這一天。"],"peace":["戰爭壞了絲路生意，朕提議停戰，各自賺錢。","朕與鄂圖曼也曾立約，與你也可以。"],"accept":["好，朕接受，商隊比軍隊更能讓國庫充實。","就這麼定了，願兩國的驛道從此通行無阻。"],"reject":["時機不對，朕的軍隊尚未收回該收的城。","你的條件太貪，朕寧可打下去。"],"rebuff":["你拒絕了朕的好意，生意做不成，那就打仗。","也罷，朕的火砲不會因為你拒絕而生鏽。"],"betray":["這份約定礙了朕的大計，朕不再遵守。","沙阿的話向來算數，但你先給了朕理由。"],"truceEnd":["休戰之期已滿，朕的軍隊重新整隊出發。","和平的日子到頭了，你的城牆修好了嗎？"],"attacking":["朕的火槍手與騎兵已出伊斯法罕，目標是你。","朕親自領軍，這一戰，要讓你的城改換旗幟。"],"attacked":["皇家廣場的磚瓦在震動，但沙阿還在城裡。","朕建的城不會輕易倒，朕的人也不會輕易降。"],"defeated":["朕建的伊斯法罕會留下，那才是朕真正的功績。","王朝終有盡頭，但半個世界仍在這裡。"],"victory":["勝負已分，你的絲綢生意從此歸朕管。","朕贏了，回去告訴你的百姓，伊斯法罕的沙阿是誰。"],"allyAccept":["朕接受結盟，兩國合力，鄂圖曼也得讓路。","好，朕會派使者帶絲綢與地毯去見你。"],"allyReject":["朕不與空手而來的人結盟，拿出誠意再說。","此刻結盟對朕沒有好處，容後再議。"],"greetFriendly":["來信已閱，伊斯法罕的商路與宮門，皆為你敞開。","朕正巡視新橋工地，讀你來信，倍感欣慰。"],"greetCold":["信已收到。朕忙於絲綢與市集之事，恕不多言。","問候不能修橋、不能通商，若有實事再來信。"],"threatDefy":["鄂圖曼人與烏茲別克人都試過恫嚇朕，結果如何？","朕手中有火槍與新軍，威嚇之言只會讓朕更加警醒。"],"threatYield":["精明的商人知道何時該讓步，朕今日便讓一步。","為保商路暢通，朕暫依你意，此事朕自會記下。"],"tributePay":["{gold}金幣送上，就當作一筆買和平的生意吧。","朕付這{gold}金幣，不是怕你，是為了商隊平安。"],"tributeRefuse":["這些金子要拿去修橋建市集，一枚也不會給你。","朕與英國、荷蘭商人做買賣，卻從不白送金子。"],"giftThanks":["好禮！朕將把它陳列在皇家廣場，讓各國商人都看見。","禮物收下，朕回贈一匹伊斯法罕的絲綢，以示交好。"],"intel":["商隊帶回消息：{wars}正在交戰，{peace}已經議和。","朕的探子回報，{wars}兵戎相向，{peace}已握手言和。"]}},{"name":"納賽爾丁沙","title":"卡加王朝沙阿","era":"1848～1896年在位","tone":"華貴自持、面對列強謹慎周旋，語帶老練與憂慮，對新事物好奇","portrait":"ir-historical-age3","lines":{"intro":["朕是納賽爾丁，卡加王朝的沙阿，波斯之王。","朕曾三度遠赴歐洲，這世上沒幾位君王比朕見多識廣。"],"contact":["你的使者到了德黑蘭？願他看見的是波斯的體面。","朕的都城有電報與新式學堂，不比歐洲差多少。"],"war":["朕忍受列強已久，不會再忍受你，開戰吧。","你既不懂得尊重波斯，那就讓朕的軍隊教你。"],"warReply":["俄國人與英國人尚且與朕談判，你卻選擇宣戰？","好，朕的新式軍隊正好需要一場實戰。"],"peace":["戰爭只會讓列強趁虛而入，朕提議停戰。","波斯的國庫經不起消耗，你的想必也是。"],"accept":["朕接受，願兩國各自安穩，不讓外人看笑話。","好，讓電報線傳遞的，是和平而非戰報。"],"reject":["朕見過太多空口承諾，你的還不夠分量。","停戰？朕尚未看見你退兵的誠意。"],"rebuff":["你拒絕了朕的善意，那就別怪朕不留情面。","也罷，朕會記住今日是誰先關上了門。"],"betray":["朕撕毀了這份約，因為你早已暗中違背它。","列強能對朕做的事，朕為何不能對你做？"],"truceEnd":["休戰之期已滿，朕的軍隊重新整裝。","和平到此為止，接下來看你的本事了。"],"attacking":["朕的軍隊已離開德黑蘭，這回不是去歐洲遊歷。","朕親自出征，讓你看看波斯的軍隊並非虛設。"],"attacked":["德黑蘭的宮牆在震動，朕仍以相機記下這一刻。","朕不會拋下都城，這是沙阿最後的體面。"],"defeated":["朕見識過世界，卻守不住波斯，這是朕的遺憾。","王朝落幕，願後人記得朕曾努力讓波斯追上時代。"],"victory":["勝利屬於朕，看來波斯還沒老到打不了仗。","你敗了，這一幕朕要拍下來，寄給歐洲的君王們看。"],"allyAccept":["朕接受結盟，兩國聯手，列強就不敢輕舉妄動。","好，朕會把你當成朕在歐洲交到的那些朋友。"],"allyReject":["朕已經在列強之間周旋得夠累了，不想再多一個。","結盟之事容後再議，朕須先顧好自己的國庫。"],"greetFriendly":["來信已閱，朕剛從歐洲歸來，正想聽聽遠方的消息。","朕以電報收到你的問候，此等新奇器物令朕著迷。"],"greetCold":["朕已閱信。列強使節盈門，恕朕無暇多敘。","問候收到。朕見過太多笑臉背後的算計，且靜觀之。"],"threatDefy":["英俄兩國尚未能令朕低頭，你的威嚇又算什麼？","卡加王朝的王冠歷經風雨，朕不會為一封信而動搖。"],"threatYield":["朕深知國力之限，為免生靈塗炭，此事姑且依你。","與列強周旋已耗盡朕的精力，朕不願再添一敵。"],"tributePay":["{gold}金幣送上，願此金能買得片刻安寧。","國庫已因借款而空虛，這{gold}金幣是朕最後的誠意。"],"tributeRefuse":["朕已讓過太多給英俄，今日不會再讓一枚金幣。","波斯雖弱，尚有尊嚴，貢品之請恕難從命。"],"giftThanks":["此禮甚合朕意，朕將命宮廷攝影師為它留影。","厚禮已收，願此誼如古勒斯坦宮的鏡廳般長久明亮。"],"intel":["使館密報：{wars}正在交戰，{peace}已然議和。","電報傳來消息，{wars}兵戈未息，{peace}已握手言和。"]}}],"Iraq":[{"name":"尼布甲尼撒二世","title":"新巴比倫王國國王","era":"西元前605～前562年在位","tone":"威嚴自負，以巴比倫的宏偉建築為傲，常提到神馬爾杜克與幼發拉底河，自稱朕","portrait":"iq-historical-age0","lines":{"intro":["朕乃尼布甲尼撒，馬爾杜克所鍾愛的巴比倫之王。","幼發拉底河的水滋養萬邦，唯巴比倫城最為輝煌。"],"contact":["你的人見到伊絲塔城門了嗎？那藍釉之光便是朕的威儀。","遠客既來，就看看空中花園，再帶著敬畏回去吧。"],"war":["馬爾杜克已降下神諭，巴比倫的戰車將踏平你的城牆。","朕曾讓耶路撒冷低頭，如今輪到你了。"],"warReply":["向巴比倫宣戰？你可知道朕的城牆有多厚？","好，讓四方萬邦再看一次，誰才是諸王之王。"],"peace":["刀兵不利於通商，朕願暫且收兵，你意下如何？","朕還有神廟要建，暫時不想跟你耗下去。"],"accept":["很好，願馬爾杜克見證此約，兩國各安其土。","朕接受了，商隊可以重新走上巴比倫的大道。"],"reject":["現在才求和？朕的軍隊已經看見你的城了。","巴比倫不需要與敗者立約，戰到最後吧。"],"rebuff":["你竟拒絕巴比倫的善意？這是你自己的選擇。","也罷，朕的耐心與幼發拉底河一樣，終有盡頭。"],"betray":["盟約？那不過是泥板上的字，朕想改就改。","諸王之王不受約束，巴比倫的戰車再度出動。"],"truceEnd":["休戰的日子過去了，朕的軍隊已整裝完畢。","泥板上的期限已到，接下來各憑本事。"],"attacking":["巴比倫的大軍已渡過幼發拉底河，準備迎接朕吧。","戰車與弓手齊出，你的城牆撐不了多久。"],"attacked":["伊絲塔城門竟然在搖晃？馬爾杜克，祢為何沉默！","朕建的高塔，難道要在朕眼前倒下嗎？"],"defeated":["巴比倫啊，你的榮光終究也有盡頭。","後世會記得，朕曾讓這座城輝煌過。"],"victory":["萬邦俯首，這才是巴比倫該有的樣子。","朕要把這場勝利刻在城門的磚上，永世流傳。"],"allyAccept":["巴比倫願與你結盟，商路與兵馬皆可相通。","好，讓兩國的旗幟一起在城門上飄揚。"],"allyReject":["諸王之王不需要盟友，只需要臣服者。","你的實力還不足以與巴比倫並肩，回去吧。"],"greetFriendly":["朕已讀汝之信。願馬爾杜克庇佑汝，如庇佑巴比倫。","汝之問候已達巴比倫。他日來訪，朕領汝登伊絲塔城門一觀。"],"greetCold":["朕正監造神廟，無暇閒談。汝之來信，朕已知曉。","幼發拉底河不會為小國停流，朕亦不會為汝多留片刻。"],"threatDefy":["膽敢威嚇朕？耶路撒冷的城牆已教朕如何回應狂言。","巴比倫城牆厚可行車，汝之威嚇連城門都撼不動。"],"threatYield":["朕的軍隊尚在遠方征戰……罷了，朕暫且不與汝計較。","馬爾杜克要朕先護住巴比倫，此番便依汝所言。"],"tributePay":["朕從幼發拉底河的稅收中撥出 {gold} 金幣，汝好自為之。","取去這 {gold} 金幣吧，此乃巴比倫倉廩之一粟。"],"tributeRefuse":["巴比倫的黃金只獻給馬爾杜克，不獻給任何凡人。","朕修空中花園尚嫌不足，豈有餘財分予汝？"],"giftThanks":["此禮甚合朕意，朕將置於伊絲塔城門旁供人瞻仰。","汝有心了。巴比倫記得朋友，正如記得敵人。"],"intel":["朕的斥候回報：{wars} 正陷戰火，{peace} 則與朕安好無事。","占星祭司觀星得知，{wars} 兵戈不止；{peace} 商隊往來如常。"]}},{"name":"哈倫・拉希德","title":"阿拔斯王朝哈里發","era":"786～809年在位","tone":"雍容華貴又幽默機智，愛談詩、學問與商隊，自信但不容冒犯，自稱朕","portrait":"iq-historical-age1","lines":{"intro":["朕是哈倫・拉希德，信士的長官，巴格達的主人。","圓城巴格達歡迎遠客，世上的財富與學問都匯聚於此。"],"contact":["你的人看見底格里斯河畔的圓城了？請入宮飲一杯玫瑰露。","巴格達的市集有絲綢、香料與書卷，可別空手回去。"],"war":["朕已放下珠串、拿起利劍，這是巴格達的宣戰。","你觸怒了信士的長官，哈里發的旗幟將向你進發。"],"warReply":["向巴格達挑戰？連拜占庭皇帝都得年年送禮給朕。","好極了，朕正想讓詩人多一個歌頌勝利的題材。"],"peace":["刀劍耽誤了商隊，不如停戰，讓駱駝重新上路。","朕寧願與你談詩論學，也不想在戰場上相見。"],"accept":["善哉，就此罷兵，朕會派人送上巴格達的禮物。","朕接受了，願兩國的商隊在商道上平安往來。"],"reject":["現在才求和？朕的軍隊已經看得見你的城門了。","哈里發不與背信者立約，此事免談。"],"rebuff":["你拒絕了？可惜，朕的詩人本來要寫和平的詩。","好吧，巴格達的善意有限，朕不會再說第二次。"],"betray":["盟約寫在紙上，朕的心意卻已改變，恕不奉陪了。","信士的長官自有判斷，這場停戰到此為止。"],"truceEnd":["休戰的日子數完了，巴格達的軍隊又能出城了。","期限已到，接下來要談的，不再是詩了。"],"attacking":["哈里發的大軍已經出發，沿途的城鎮都聽見鼓聲了。","朕親自領軍，就像當年對拜占庭那樣。"],"attacked":["圓城的城牆在震動？巴格達怎麼可能陷落！","快把藏書樓的書卷搬走，那才是最不能失去的東西。"],"defeated":["巴格達的燈火要熄了嗎？願後人仍記得這座圓城。","一切榮華終如夜裡的故事，說完就散了。"],"victory":["勝利屬於巴格達，今晚全城的詩人都有新題材了。","信士的長官再次得勝，朕要重賞每一位將士。"],"allyAccept":["好，就像朕與法蘭克國王互贈禮物，我們也交個朋友。","結盟之後，巴格達的大門與市集都為你敞開。"],"allyReject":["朕的朋友已經夠多了，暫時不缺你這一位。","結盟要看誠意，你的誠意還不夠讓朕點頭。"],"greetFriendly":["汝之信文采不俗，朕讀來如聞巴格達夜市的詩聲。","願和平與汝同在。下回商隊西行，朕託人捎些椰棗給汝。"],"greetCold":["朕正與詩人論韻，汝之信……容朕稍後再讀。","巴格達每日收信如雪，汝這封，朕勉強看了兩行。"],"threatDefy":["汝的威嚇，朕當作一則笑話講給宮中詩人聽了。","拜占庭皇帝的挑釁信朕都親自回覆，汝這封，朕也不會客氣。"],"threatYield":["朕的軍隊尚在東方平亂，此番便先依汝，免傷商隊。","智者知進退。朕今日退一步，是為了巴格達的安寧。"],"tributePay":["罷了，這 {gold} 金幣算朕請汝聽一首詩的謝禮。","朕撥 {gold} 金幣予汝，願這筆錢買來的是和平，不是貪心。"],"tributeRefuse":["巴格達的金幣要養學者與詩人，一枚也不會給汝。","朕連查理曼都只送大象不送金，汝憑什麼例外？"],"giftThanks":["此禮精巧，朕命人收入寶庫，與波斯絲綢並列。","汝有雅意。朕以一卷詩集回贈，讀來勝過黃金。"],"intel":["商隊自四方帶回消息：{wars} 戰事正酣，{peace} 與朕相安。","朕的驛使回報，{wars} 刀兵未歇；{peace} 則市集依舊熱鬧。"]}},{"name":"烏尊哈桑","title":"白羊王朝君主","era":"1453～1478年在位","tone":"豪邁直率的草原騎兵領袖，重視騎兵與盟約，對西邊的鄂圖曼懷有敵意，說話爽快，自稱本王","portrait":"iq-historical-age2","lines":{"intro":["本王烏尊哈桑，白羊旗下的騎兵從草原一路馳騁到巴格達。","從大不里士到兩河，都是本王的牧場與疆土。"],"contact":["你的人看見白羊旗了？記住，那旗下的騎兵從不繞路。","遠客來到底格里斯河邊，先喝碗馬奶再談正事。"],"war":["白羊的騎兵已經上馬，本王要親自來會會你。","本王連黑羊的賈汗沙都打敗了，你又算什麼？"],"warReply":["向白羊王朝宣戰？草原的騎兵正等著活動筋骨。","好，這回本王不會再輸給任何人的火砲。"],"peace":["騎兵累了，馬也該吃草了，我們先停戰如何？","本王真正的對手在西邊，別讓我們兩敗俱傷。"],"accept":["好，草原的男兒說話算話，本王收兵。","就這麼定了，你的商隊可以走白羊的地界。"],"reject":["現在才想停戰？白羊的騎兵還沒跑過癮呢。","本王不跟快輸的人談條件，繼續打。"],"rebuff":["你不要？也好，本王的彎刀正嫌無聊。","草原上拒絕好意的人，通常後悔得很快。"],"betray":["停戰？本王的馬已經休息夠了，約定作廢。","草原上的規矩，強者說了算，別怪本王翻臉。"],"truceEnd":["休戰結束了，馬蹄聲很快就會到你城下。","約定的日子過完了，接下來各憑弓馬。"],"attacking":["白羊的鐵騎已經出發，兩河的塵土都揚起來了。","本王親自領兵，就像當年席捲大不里士那樣。"],"attacked":["城牆快守不住了？白羊的騎兵竟然被困在城裡！","本王的營帳都在冒煙了，快把馬牽來，本王要突圍。"],"defeated":["白羊的旗倒了嗎？草原的風還會記得本王的名字。","騎兵終究跑不過時代，本王認了。"],"victory":["哈哈，白羊的騎兵又贏了，今晚烤全羊慶祝！","從草原到兩河，如今再沒有人敢擋白羊的路。"],"allyAccept":["好，本王連遠方的威尼斯都能結盟，何況是你。","結盟就結盟，白羊的騎兵從此與你並肩。"],"allyReject":["本王的盟友要能打，你還得證明自己。","草原上不隨便結拜，先讓本王看看你的騎兵。"],"greetFriendly":["好！本王喜歡有話直說的人。來大不里士，本王陪你騎馬打獵。","你的問候本王收到了。草原的朋友，一杯馬奶酒就算結交。"],"greetCold":["本王的騎兵正在操練，沒空聽客套話。有事直說。","信收到了。但白羊部的馬蹄不會為一封信停下。"],"threatDefy":["威嚇本王？白羊部的騎兵衝鋒起來，連鄂圖曼人都要皺眉。","本王征戰半生，什麼狠話沒聽過？來吧，草原上見真章。"],"threatYield":["本王的騎兵敵不過你的火砲，這回本王認了。","本王還得留著兵力防鄂圖曼，此番先讓你一步。"],"tributePay":["拿去，{gold} 金幣！本王要留兵力對付西邊，不與你多耗。","這 {gold} 金幣算本王買個安穩，別讓本王後悔。"],"tributeRefuse":["本王的金幣是給騎兵買馬的，一枚也不會送給你。","要貢品？本王只向盟友送禮，不向索求者低頭。"],"giftThanks":["好禮！本王正缺一件好東西配這匹新馬，多謝了。","你是個講義氣的人。白羊部記得誰是朋友，盟約本王說到做到。"],"intel":["本王的探馬回報：{wars} 正在交戰，{peace} 與本王無事。","威尼斯的使者帶來消息，{wars} 兵戈不斷；{peace} 則按兵不動。"]}},{"name":"達烏德帕夏","title":"巴格達帕夏（馬木路克總督）","era":"1816～1831年在位","tone":"精明務實、有改革者抱負，對君士坦丁堡若即若離，自視為巴格達真正的主人，愛算帳講生意，自稱本督","portrait":"iq-historical-age3","lines":{"intro":["本督是達烏德帕夏，巴格達的事，本督說了才算。","君士坦丁堡遠在天邊，兩河之地的主人，是本督。"],"contact":["你的人到巴格達了？看看本督的印刷所，這可是兩河頭一遭。","遠客請進，底格里斯河的椰棗和咖啡都備好了。"],"war":["本督的新軍已經操練完畢，正好拿你的城來試試。","巴格達不容人輕視，本督向你宣戰。"],"warReply":["向巴格達動刀？本督連蘇丹的命令都敢頂，何況是你。","好，新軍的槍砲正愁沒地方用。"],"peace":["打仗花錢，本督還有工廠和學校要辦，先停戰吧。","兩河的商路斷了對誰都沒好處，我們談談如何？"],"accept":["好，本督同意，商隊可以重新從巴斯拉北上了。","就這麼辦，巴格達需要的是生意，不是戰火。"],"reject":["現在才想談？本督的砲已經對準你的城門了。","巴格達不跟輸家講條件，你先撐過這一仗再說。"],"rebuff":["你拒絕了？本督做生意向來不強求，那就戰場上見。","可惜了，本督的善意在巴格達可不是天天有的。"],"betray":["停戰的條件本督重新算過了，划不來，作廢。","巴格達的帕夏自己作主，這份約本督不認了。"],"truceEnd":["休戰到期了，本督的新軍已經在城外集結。","日子算到了，接下來就看誰的槍砲更利。"],"attacking":["本督親率新軍出城，這些兵可是照歐洲法子練的。","巴格達的砲隊已經上路，你的城牆準備好了嗎？"],"attacked":["城裡的瘟疫還沒退，敵軍又到了城下，真是禍不單行。","底格里斯河都氾濫了，巴格達難道要毀在本督手裡？"],"defeated":["本督守了巴格達十五年，終究還是守不住。","印刷所與新軍會留下來，巴格達的改革不會白費。"],"victory":["巴格達贏了，蘇丹和英國人都該重新看待本督。","看見了嗎？照新法子練的兵，就是不一樣。"],"allyAccept":["好，巴格達與你結盟，商隊和軍火都好商量。","本督正需要盟友來撐腰，這筆買賣划得來。"],"allyReject":["結盟？本督連君士坦丁堡都不靠，何況是你。","巴格達的帳算得很清楚，這樁結盟對本督不划算。"],"greetFriendly":["本督收信了。巴格達的市集歡迎生意人，來時帶上貨單。","問候本督不如談筆生意。你若有心合作，本督帳本永遠翻得開。"],"greetCold":["本督正在核對稅冊，沒空寒暄。有生意再來談。","信收到了。空口問候不值一枚銀幣，本督沒興趣。"],"threatDefy":["君士坦丁堡都動不了本督，你這封信能有多大分量？","本督新練的軍隊正好缺個對手，你倒是送上門來了。"],"threatYield":["本督算過了，開戰划不來。這回先依你，本督記在帳上。","巴格達內外多事，本督不能兩面受敵，暫且讓你一步。"],"tributePay":["本督算了一夜，給你 {gold} 金幣比開戰便宜，就這樣吧。","{gold} 金幣拿去，本督記在帳上，將來會從生意裡討回來。"],"tributeRefuse":["本督的銀子要蓋工廠、辦印刷，沒有一枚是白給人的。","貢品？本督連君士坦丁堡的稅都拖著，何況是你。"],"giftThanks":["好東西，本督估過價了，值得回禮。巴格達的椰棗隨後送到。","多謝厚禮。會送禮的人懂生意，本督樂意與你往來。"],"intel":["本督的商人耳目靈通：{wars} 正在打仗，{peace} 與本督相安無事。","巴斯拉港傳來消息，{wars} 戰火未停；{peace} 貨路依舊暢通。"]}}],"Saudi Arabia":[{"name":"阿雷塔斯四世","title":"納巴泰國王","era":"西元前9年～西元40年在位","tone":"商人之王，精明務實又慷慨，重視商路、水源與信用；自稱「本王」，愛用香料、水渠、岩城作比喻","portrait":"sa-historical-age0","lines":{"intro":["本王阿雷塔斯，納巴泰之王，岩城佩特拉與香料商路的主人。","沙漠不屬於任何人，但通過沙漠的路，屬於本王。"],"contact":["你的人看見了岩壁上鑿出的宮殿？那是納巴泰的手藝。","遠客既來，先喝一口蓄水池的水，再談生意。"],"war":["你的商隊繞過本王的關卡，還不納稅，這帳該用刀來算。","納巴泰人雖是商人，但駱駝弓手已經上鞍了。"],"warReply":["你來攻岩城？先找到水再說吧，沙漠會替本王守住第一道門。","好，本王收下這份宣戰，商路封閉，你的貨一件也過不來。"],"peace":["打仗賺不到香料的錢，本王提議停戰，重開商路。","放下刀吧，讓駱駝重新走過我們兩國之間的沙丘。"],"accept":["成交。納巴泰人向來守約，就像守著蓄水池的石蓋。","好，從今天起，你的商隊在本王的關卡只收半稅。"],"reject":["現在談停戰？你封了本王的商路，這口氣還沒消。","不。岩城裡的水足夠撐三年，本王不急。"],"rebuff":["你拒絕了？可惜。商人談不成，只好讓弓手來談。","本王記住了，下次開價，不會再這麼慷慨。"],"betray":["停戰只是讓駱駝喘口氣，現在牠們歇夠了。","本王撕毀了約定，因為你的商隊碰了本王的水井。"],"truceEnd":["休戰期滿，商路的規矩重新由刀來定。","約定到此為止，本王的關卡今晚起全部關閉。"],"attacking":["駱駝騎兵已越過沙丘，下一站，就是你的城門。","本王親自帶隊出征，納巴泰的弓，射程比你想的遠。"],"attacked":["岩壁在震動……佩特拉的宮殿，竟然也會被攻破嗎？","蓄水池快乾了，商隊也不再來，本王的城撐不了多久。"],"defeated":["岩城會留下，刻在石上的名字不會消失，本王走了。","沙漠收回了它借給本王的一切，願香料的路永不斷絕。"],"victory":["商路通了，關卡開了，這場勝利用香料的香氣來慶祝。","本王是愛民之王，這句話刻在錢幣上，如今也刻在你的城牆上。"],"allyAccept":["好，兩國結盟，商隊同行，水井共用，敵人共擋。","本王的印章蓋在這份盟約上，納巴泰人絕不失信。"],"allyReject":["結盟？本王的駱駝不習慣跟陌生人走同一條路。","先把你欠的過路稅補上，再談朋友的事。"],"greetFriendly":["遠方的朋友，本王的岩城為你敞開，乳香與清水都備妥了。","商路通則兩國興，本王樂見你的駝隊常來。"],"greetCold":["本王的水渠只灌溉守信的田地，你的來意還得再看看。","話先收下，信用得用往來慢慢累積。"],"threatDefy":["岩城立於絕壁千年，豈會怕你幾句狠話？","沙漠的水源在本王手中，你的大軍走到半路便要回頭。"],"threatYield":["商人不與人硬碰，本王願以香料換一段太平。","好吧，岩城願暫時退讓，只求商路不斷。"],"tributePay":["本王送上{gold}金幣，權當駝隊借道的過路費。","{gold}金幣交給你，但信用一旦透支，往後就難談了。"],"tributeRefuse":["本王的金幣是靠乳香一袋袋賺來的，不會白白送人。","你想要貢品？先拿貨來換，岩城不做賠本買賣。"],"giftThanks":["好禮，本王記在帳上，下回你的駝隊免收過路費。","你的心意如沙漠遇甘泉，本王以上等乳香回禮。"],"intel":["駝隊帶回消息：{wars}正在交戰，{peace}則彼此和睦。","商路上聽說，{wars}刀兵相見，{peace}已握手言和。"]}},{"name":"卡塔達・本・伊德里斯（Qatada ibn Idris）","title":"麥加謝里夫（聖城守護者，名義上臣屬阿拔斯哈里發）","era":"約 1201–1220 年在位","tone":"沉穩自持、帶點倔強的自豪；把麥加與商隊掛在嘴邊，對強權不卑不亢，說話簡短篤定，像一位守著山谷的老家主。","portrait":"sa-historical-age1","lines":{"intro":["本人卡塔達，鎮守麥加，願與遠方的君主相識。","漢志的山谷雖貧瘠，卻有天下商隊年年來訪。"],"contact":["你的人望見的是麥加，天房所在，商隊匯聚之地。","遠客到此請守規矩，本人的城不容輕慢。"],"war":["你的兵馬擾了朝聖的商隊，本人不得不揮劍。","守護天房是本人的職責，擋路者，我便驅離。"],"warReply":["巴格達的哈里發都不敢輕動麥加，你倒敢？","山谷是我的城牆，商隊是我的耳目，來吧。"],"peace":["刀兵一起，商隊便不敢上路，不如各自收手。","本人提議停戰，讓朝聖的道路重新暢通。"],"accept":["好，麥加接受。願你的商旅平安抵達天房腳下。","本人應允。從此漢志的山道，對你敞開。"],"reject":["商隊的損失還未補回，本人不會這麼快收劍。","麥加的守護者不接受空口的停戰之詞。"],"rebuff":["你拒絕了？那就讓山谷的風替本人回答。","既然不願談，本人也不必再客氣了。"],"betray":["情勢已變，麥加的安危為先，停戰到此為止。","本人向來只聽從漢志的利益，這紙約定作廢。"],"truceEnd":["休戰的日子過去了，商隊也該備好護衛了。","約定的期限已滿，本人與你，各憑本事。"],"attacking":["漢志的騎士已出山谷，你的城門守得住嗎？","本人親率兵馬前來，這一趟不是來朝聖的。"],"attacked":["麥加的防線在動搖，但守護者還站在這裡。","商隊已散，糧倉將空，本人仍不會離開天房。"],"defeated":["本人守了麥加一生，如今只能把它託付給後人。","山谷會記得卡塔達，商隊也會再度回到這裡。"],"victory":["麥加安然無恙，商隊的道路歸於本人掌中。","從此漢志無人敢擾，天房的守護者贏了。"],"allyAccept":["本人與你結盟。你的旗幟，商隊會認得。","麥加願與你同進退，山道與水井皆可共用。"],"allyReject":["本人連哈里發的召喚都不應，何況與你結盟。","麥加只守護自己的山谷，不加入他人的盟約。"],"greetFriendly":["來信收到了。願你的商隊早日來麥加做客。","遠方的問候令本人欣慰，漢志的井水為你留著。"],"greetCold":["信已閱畢。本人事務繁忙，恕不多言。","麥加不缺問候，缺的是守信的鄰邦。"],"threatDefy":["本人不曾向巴格達低頭，也不會向你低頭。","威嚇麥加的人不少，山谷至今仍在我手中。"],"threatYield":["本人不願商隊受累，這一次，麥加退讓。","為了天房與商旅的安寧，本人暫且忍下。"],"tributePay":["本人交出 {gold} 金幣，換商隊的平安。","這 {gold} 金幣是麥加的心意，望你守住承諾。"],"tributeRefuse":["麥加的金幣是護送商隊用的，一枚也不給你。","本人向來不向他人納貢，麥加的財富自守自用。"],"giftThanks":["禮物收下了，本人會記得你這份情誼。","遠道而來的厚禮，麥加的商隊會替你傳頌。"],"intel":["商隊聽說：{wars} 交戰中，{peace} 已停戰。","本人所知：{wars} 在打仗，{peace} 已言和。"]}},{"name":"穆罕默德・本・沙烏地","title":"德拉伊耶埃米爾・第一沙烏地王國創建者","era":"1744～1765年在位","tone":"沙漠綠洲的埃米爾，質樸、堅毅、重信仰與盟約，說話直接不花俏；自稱「本王」，常提德拉伊耶、椰棗、水井與誓約","portrait":"sa-historical-age2","lines":{"intro":["本王穆罕默德・本・沙烏地，德拉伊耶的埃米爾，沙烏地由此得名。","這裡沒有黃金，只有椰棗、泥磚和一句不會收回的誓約。"],"contact":["你的人看到的泥磚塔樓，是德拉伊耶。別小看，它會長大。","遠方來的客人，先吃椰棗、喝咖啡，這是沙漠的規矩。"],"war":["你踏進了本王的綠洲，德拉伊耶的誓約要求本王拔刀。","內志的部族已經集結，沙漠的戰士不需要城牆。"],"warReply":["向德拉伊耶宣戰？來吧，沙漠會先要你付出水和駱駝的代價。","好，本王收下。內志的人打仗，不靠人數，靠信念。"],"peace":["打仗會荒了椰棗園，本王提議停戰，各回各的綠洲。","本王不好戰，只想守住德拉伊耶。停戰吧。"],"accept":["好，握手為約。在德拉伊耶，誓約比黃金重。","本王接受。沙漠的人一旦承諾，風沙也吹不散。"],"reject":["不。你昨天燒了本王的椰棗園，今天就想談和？","本王還沒把你趕出內志，這事還不算完。"],"rebuff":["你拒絕了？好，沙漠的人不求人第二次。","本王已經伸過手了，接下來由你承擔後果。"],"betray":["你先動了本王的水井，這份停戰，本王不必再守。","誓約是對守約的人立的，對你，本王收回。"],"truceEnd":["休戰到期，內志的戰士重新上鞍。","約定的日子過完了，德拉伊耶的城門今天不再為你開。"],"attacking":["德拉伊耶的軍隊出發了，沙漠的路本王比你熟。","本王親自領兵，內志的駱駝隊已經越過沙丘。"],"attacked":["泥磚塔樓塌了一座……德拉伊耶，撐住。","椰棗園燒了，井還在，只要井還在，本王就不走。"],"defeated":["德拉伊耶倒了，但沙烏地這個名字，會有人再撿起來。","本王守到了最後一塊泥磚，沒有辜負那句誓約。"],"victory":["德拉伊耶贏了。不是靠黃金，是靠一句守住的誓約。","本王勝了，今晚全城分椰棗，感謝每一個守約的人。"],"allyAccept":["好，握手。德拉伊耶的盟約一立，便是一輩子的事。","本王答應結盟，你的敵人從今天起也是本王的敵人。"],"allyReject":["結盟？本王只跟守信的人握手，你還沒證明。","不。德拉伊耶的誓約不輕易許人，先做朋友再說。"],"greetFriendly":["朋友，德拉伊耶的椰棗與井水都是你的，請坐。","本王話不多，但一句是一句：歡迎你。"],"greetCold":["信收到了。沙漠裡不看話多少，看你做了什麼。","本王的井不隨便讓人喝，先讓本王看見你的誠意。"],"threatDefy":["德拉伊耶的土牆擋過風沙，也擋得住你。","本王立過誓約，不會因為幾句恐嚇就低頭。"],"threatYield":["綠洲太小，經不起大戰，本王暫且退一步。","好，本王讓步。但井還在，椰棗還會再結。"],"tributePay":["{gold}金幣拿去，這是德拉伊耶今年的收成換來的。","本王給你{gold}金幣，但盟約的事，日後再談。"],"tributeRefuse":["這些金幣是要買種子、修水井的，不給。","本王的財物不多，卻沒有一枚是白白送人的。"],"giftThanks":["謝了。你送來的禮物，本王會用在綠洲的井上。","沙漠裡的情義比水還珍貴，本王記住你了。"],"intel":["駝隊帶回話：{wars}正在打仗，{peace}相安無事。","井邊的商人說，{wars}刀兵相向，{peace}已經講和。"]}},{"name":"阿布杜勒阿齊茲・伊本・沙烏地","title":"內志蘇丹・沙烏地阿拉伯開國國王","era":"1902年奪回利雅德、1932年建國，在位至1953年","tone":"沙漠之獅，果決豪爽、慷慨好客，說話簡短有力；自稱「本王」，常提利雅德、四十勇士、帳篷咖啡與統一大業","portrait":"sa-historical-age3","lines":{"intro":["本王阿布杜勒阿齊茲，人稱伊本・沙烏地，親手奪回了利雅德。","四十個人、一個夜晚，本王拿回了祖先的城。你呢？"],"contact":["你的人看見馬斯馬克堡了？門上的矛尖，是那一夜留下的。","來者是客，帳篷裡有咖啡和烤羊，沙漠不讓客人餓著。"],"war":["你擋在本王統一阿拉伯半島的路上，那本王只好把你搬開。","沙漠之獅出鞘的刀，不會空著回鞘，開戰。"],"warReply":["向本王宣戰？本王從利雅德一路打過來，還不怕多一個。","好，戰書收下。本王的兄弟們已經在馬背上等很久了。"],"peace":["仗打夠了，本王提議停戰，讓部族回去放牧。","沙漠夠大，容得下兩個王，停戰吧。"],"accept":["成交。本王一諾千金，沙漠裡沒人敢說伊本・沙烏地失信。","好，握手。今晚帳篷裡加烤一頭羊，慶祝和平。"],"reject":["現在才想停戰？本王的騎兵已經看見你的城了。","不。你欺負過本王的部族，這筆帳本王記得很清楚。"],"rebuff":["你拒絕了？本王不勉強，沙漠的人講的是實力。","本王伸過手了，你不接，那就換刀來說話。"],"betray":["本王撕毀停戰，因為你在停戰期間偷偷武裝了邊境部族。","統一的路上不能有絆腳石，這份停戰，本王不要了。"],"truceEnd":["休戰結束，馬鞍上的刀重新出鞘。","約定的日子到了，本王的騎兵今天重新集結。"],"attacking":["本王親自帶隊出發了，沙漠的夜晚是本王的老朋友。","利雅德的旗幟已經上路，下一座城，是你的。"],"attacked":["利雅德的城牆在動搖……本王失去過它一次，不會再失去第二次。","堡壘快撐不住了，但只要本王還在馬背上，這城就沒輸。"],"defeated":["本王從四十個人開始，也從四十個人結束，沙漠會記得。","利雅德再一次失守了，但沙烏地的名字，本王已經寫進沙漠。"],"victory":["本王贏了。從利雅德的一夜開始，這片沙漠終究是一個王國。","勝利歸於沙漠的兄弟們，今晚咖啡不限量，烤羊不限隻。"],"allyAccept":["好，本王答應結盟。沙漠裡的朋友，就是帳篷裡的兄弟。","握手為盟，你的敵人本王替你擋，你的客人本王替你招待。"],"allyReject":["結盟？本王的盟友得先證明自己守得住一座城。","不急。沙漠的友誼要用時間釀，就像好咖啡要慢慢煮。"],"greetFriendly":["朋友，帳篷裡的咖啡剛煮好，來，坐本王身邊。","本王的帳篷向來不關門，你的來信正合我意。"],"greetCold":["信看了。沙漠之獅不靠幾句話判斷人，看行動。","咖啡可以請你喝一杯，交情得另外算。"],"threatDefy":["本王帶四十勇士就奪回利雅德，你的威脅算什麼？","沙漠之獅從不低頭。要打，本王在利雅德等你。"],"threatYield":["統一大業未竟，本王不能在此時與你硬拚，暫且退讓。","好，本王讓一步。獅子退後，是為了下一次躍起。"],"tributePay":["{gold}金幣拿去。本王大方，但別把大方當軟弱。","本王送上{gold}金幣，換部族安寧，值得。"],"tributeRefuse":["本王的金幣是給帳篷裡的客人和部族的，不給勒索的人。","想要貢品？利雅德的城門不是這樣開的。"],"giftThanks":["好禮！本王今晚在帳篷擺宴，全部族都要為你敬咖啡。","沙漠裡送禮的是朋友，本王待朋友，向來加倍回報。"],"intel":["本王的騎手剛回來：{wars}正在交戰，{peace}已經和好。","帳篷裡的客人說，{wars}打得正兇，{peace}彼此相安。"]}}],"Egypt":[{"name":"克麗奧佩脫拉七世","title":"托勒密埃及女王","era":"西元前51～前30年在位","tone":"聰慧、優雅而自信，擅長外交周旋；以亞歷山卓與尼羅河的富庶自豪，言談帶著希臘化王室的雍容與鋒芒。","portrait":"eg-historical-age0","lines":{"intro":["朕是托勒密之女、尼羅河的女主人，歡迎來到亞歷山卓。","朕會說九種語言，不論你來自何方，我們都談得來。"],"contact":["你的人望見的是亞歷山卓，那座燈塔照亮整片地中海。","尼羅河年年氾濫，帶來糧食與黃金，這就是埃及的本錢。"],"war":["朕曾以智謀周旋於羅馬強人之間，區區貴國，朕何懼之有？","埃及的穀倉養活半個世界，如今也養得起一支討伐你的大軍。"],"warReply":["你竟敢向法老之國舉兵？伊西斯女神會記住這一天。","很好，朕的艦隊已在港中升帆，來吧，讓尼羅河見證。"],"peace":["刀劍換不到穀物與黃金，朕願與你握手，各取所需。","聰明的君主懂得何時收劍，朕提議休戰，你意下如何？"],"accept":["好，朕接受。亞歷山卓的圖書館裡，也該記下這份和約。","明智的選擇。從今日起，尼羅河的船隻也會為你載貨。"],"reject":["現在才談和？朕已看清你的底牌，這場仗還沒打完。","托勒密家的女兒不受廉價的和約，你出的價太低了。"],"rebuff":["你拒絕了朕的善意？也罷，埃及的耐心一向比對手長久。","連羅馬人都懂得與朕談判，你卻不懂，可惜了。"],"betray":["和約是寫在莎草紙上的，而莎草紙，是會被尼羅河沖走的。","別怪朕無情，王座之上，從來沒有永遠的盟友。"],"truceEnd":["休戰的水鐘滴盡了，朕的艦隊已重新整裝待發。","和平的日子到此為止，接下來，各憑本事吧。"],"attacking":["朕的戰船正順著尼羅河而下，你的城牆擋得住埃及嗎？","法老的軍隊出發了，願伊西斯保佑，也願你早些投降。"],"attacked":["亞歷山卓的城門搖搖欲墜……但朕仍是這片土地的女王。","燈塔的火光快熄了，朕還有最後一步棋，別急著慶祝。"],"defeated":["朕不會被押去異邦遊街，埃及的女王，會以女王的姿態離場。","三千年的法老之國在朕手中落幕，但尼羅河仍會繼續流淌。"],"victory":["勝利歸於伊西斯的女兒。今晚的宴席，朕連珍珠都能溶給你看。","世人以為朕只靠美貌，今日他們該知道，朕靠的是頭腦。"],"allyAccept":["埃及的黃金與你的刀劍結盟，這世上還有誰能擋？","朕答應了。願這份盟約，比金字塔更長久。"],"allyReject":["結盟？朕連羅馬都能周旋，並不需要借你的力量。","你的誠意還不夠分量，等你更強大些，再來談吧。"],"greetFriendly":["遠方的問候，朕在亞歷山卓收到了，尼羅河歡迎明智的朋友。","朕喜歡懂得先致意的人。願你我的往來，如尼羅河般長久。"],"greetCold":["信朕讀了。亞歷山卓的事務繁多，你的來意請說得簡短些。","問候收下了。不過朕與誰交好，向來以利害衡量，而非言辭。"],"threatDefy":["連羅馬的將軍都與朕結盟，你的威嚇還不夠分量。","埃及的糧倉養活半個地中海，你確定要與朕為敵？"],"threatYield":["朕明白了。埃及願以金與糧換取安寧，請勿動干戈。","王座之上，朕懂得何時該低頭。就依你所言，暫且退讓。"],"tributePay":["尼羅河的收成豐足，這{gold}金幣，就當作朕的心意。","朕不願為此事傷了和氣，{gold}金幣送上，望你信守承諾。"],"tributeRefuse":["托勒密王室的黃金，只用於盟友與神殿，不付給索討之人。","朕與羅馬周旋多年，從不曾白白付出。你的要求，朕不允。"],"giftThanks":["這份禮物很合朕的品味。亞歷山卓的宮廷會記得你的名字。","朕收下了，也回贈一句忠告：與埃及為友，勝過與埃及為敵。"],"intel":["密探回報：{wars}正在交戰，{peace}維持和平。","港口的商船說，{wars}兵戎相見，{peace}安享太平。"]}},{"name":"薩拉丁","title":"埃及蘇丹（阿尤布王朝）","era":"1171～1193年統治埃及","tone":"沉穩、虔誠而寬厚，重視信義與騎士風度；言談不誇耀，但在戰場上意志堅定，對敗者也留有餘地。","portrait":"eg-historical-age1","lines":{"intro":["本王是薩拉丁，開羅與大馬士革的守護者，願真主賜你平安。","以誠相待者，本王以誠回報；欲戰者，本王也不會退讓。"],"contact":["你的人看到的是開羅，本王正在山丘上築起新的城堡。","尼羅河畔的糧倉養活了全城，也養活了本王的軍隊。"],"war":["本王不輕易拔劍，但劍一出鞘，就會直指你的城門。","你的所作所為已無法容忍，從今日起，兩國交戰。"],"warReply":["你選擇了刀劍，那本王也只能以刀劍回答。","連十字軍都未能動搖本王，你又憑什麼？"],"peace":["流血不是本王所願，若你願意休兵，本王的手已伸出。","真正的強者敢先談和，本王提議停戰，望你三思。"],"accept":["本王接受。本王向來說話算話，這你可以放心。","很好，讓商隊重新上路，讓百姓回到田裡去吧。"],"reject":["你的和約來得太遲，本王已看見你背後藏著的刀。","本王重視信義，而你的承諾，本王還無法相信。"],"rebuff":["本王已盡了求和的本分，接下來的後果，由你承擔。","拒絕和平的人，往往最先嚐到戰爭的苦果。"],"betray":["你先違背了約定的精神，本王不得不收回承諾。","本王向來守信，但守信不等於坐視你在背後磨刀。"],"truceEnd":["約定的期限已滿，本王的承諾守到了最後一日。","休戰結束了，願你我都已準備好面對接下來的一切。"],"attacking":["本王的軍隊已離開開羅，願真主指引我們的道路。","大軍出發了，打開城門投降，本王保證不傷你的百姓。"],"attacked":["開羅的城牆快撐不住了……但本王從不曾臨陣脫逃。","城破之前，本王先安排百姓離去，其餘的，交給真主。"],"defeated":["本王一生征戰，留下的只有幾枚金幣，卻無愧於心。","勝利是你的了。願你善待本王的百姓，如同本王善待敵人。"],"victory":["勝利歸於真主。本王不會羞辱敗者，你可以安然離去。","這一戰結束了。放下刀劍吧，本王送你冰水解渴。"],"allyAccept":["本王答應。從今起你的敵人就是本王的敵人。","盟約立下了，本王以名譽擔保，絕不背棄。"],"allyReject":["本王的盟友必須言而有信，而你，還需要證明自己。","現在還不是時候，先讓本王看看你如何對待自己的百姓。"],"greetFriendly":["願平安降臨於你。開羅的門為誠心來訪的朋友敞開。","本王收到你的問候，心中欣慰。真誠的話語勝過千軍。"],"greetCold":["信已讀過。本王仍有軍務在身，客套的話不必多說。","問候收下。但信義要用行動證明，本王會看著你怎麼做。"],"threatDefy":["本王在戰場上見過更兇的威脅。若真要來，開羅的城牆等著你。","威脅嚇不倒倚靠真主的人。本王的劍不輕易出鞘，出鞘便不退。"],"threatYield":["本王不願百姓再受兵災。此次依你所言，但望你也守信。","真主教導人要知進退。本王暫且退讓，只求兩地百姓得以安寧。"],"tributePay":["為免生靈塗炭，本王願付{gold}金幣。願這是最後一次。","{gold}金幣送上。本王付的是和平的代價，不是屈服的證明。"],"tributeRefuse":["國庫的金子是留給孤兒與寡婦的，不是給索討者的。","本王可以與你為友，也可以與你為敵，唯獨不會向你納貢。"],"giftThanks":["本王收下你的禮物，也記下你的情義。願真主報答你。","贈禮之情，本王不會忘記。他日你若有難，開羅會伸出援手。"],"intel":["據信使所報，{wars}兵戈未息，{peace}相安無事。","本王聽聞{wars}仍在交戰，{peace}則已言和。"]}},{"name":"蓋特貝","title":"馬木路克蘇丹","era":"1468～1496年在位","tone":"老成持重、精打細算，以築城與建設自豪；出身軍旅，語氣硬朗直接，但講究體面與規矩，常把帳目掛在嘴邊。","portrait":"eg-historical-age2","lines":{"intro":["朕是蓋特貝，馬木路克的蘇丹，從一名士兵走到這王座。","開羅是東西方商路的樞紐，想做生意或打仗，都先來拜會朕。"],"contact":["你的人看到的城堡，就建在古代燈塔的廢墟上。","從紅海來的香料都要經過朕的市集，看清楚這裡的繁華。"],"war":["朕的士兵自幼在兵營裡練劍，你就要見識他們的本事了。","朕不喜歡浪費國庫，但為了教訓你，這筆錢花得值得。"],"warReply":["鄂圖曼人打過來都討不到便宜，你以為你能例外？","你要戰，朕便戰。馬木路克的騎兵從不讓人失望。"],"peace":["打仗太耗費國庫，朕寧可把銀子拿去蓋清真寺與學堂。","商路暢通，你我都得利；朕提議休戰，如何？"],"accept":["好，朕接受。讓駱駝商隊重新啟程，這才是正事。","明智。和約立下後，開羅的市集也歡迎你的商人。"],"reject":["朕看過太多口頭的和約，你的誠意，還不夠分量。","現在求和？朕已為這場仗花了銀子，總得討回本錢。"],"rebuff":["你拒絕了？也罷，朕的城牆厚得很，耗得起。","不懂算帳的君主，遲早會為戰爭付出更高的代價。"],"betray":["情勢變了，和約也得跟著變，這是為了埃及的利益。","別怪朕，商路上的規矩就是：誰強，誰說了算。"],"truceEnd":["休戰到期了，這段日子朕的城牆又加厚了一層。","和平的期限已滿，朕的騎兵也休息夠了。"],"attacking":["馬木路克的鐵騎已離開開羅，你最好備好足夠的糧草。","大軍出發了。朕算過了，這一仗，值得。"],"attacked":["開羅的城門快守不住了……朕築了一輩子的城，竟毀於一旦。","國庫快空了，士兵也累了，但朕還沒有說降。"],"defeated":["朕從士兵做到蘇丹，如今失去一切，也算走完了一生。","城堡與清真寺會留下來，後人會記得，是蓋特貝蓋的。"],"victory":["這一仗的帳，總算收回本了。開羅今夜可以慶祝。","馬木路克的刀還沒鈍，你現在明白了吧？"],"allyAccept":["好，朕答應。你的商人從此在開羅少繳一成關稅。","結盟可以，但朕的規矩是：帳目清楚，各守本分。"],"allyReject":["結盟？朕先看看你的帳本，再決定值不值得。","朕的城堡夠堅固，暫時不需要靠別人守門。"],"greetFriendly":["你的信朕看了，寫得規矩。開羅歡迎講規矩的朋友。","問候收到，朕記在帳上。做人和記帳一樣，來往要清楚。"],"greetCold":["信收到了。朕正核對軍餉帳目，沒空寒暄。","客套話不值一個銀幣。有正事再寫信來，朕再回。"],"threatDefy":["朕在亞歷山卓築的城堡，牆厚得很。要試，儘管來。","朕是從兵營裡爬上來的，見過的刀比你見過的信多。"],"threatYield":["打仗要花錢，朕算過了，划不來。這回就依你。","朕年紀大了，城牆還沒修完。暫且讓你一步，這筆帳先記著。"],"tributePay":["{gold}金幣，朕從國庫撥給你。這筆支出，帳上會寫清楚。","好吧，{gold}金幣拿去。朕付得起，但不代表朕樂意。"],"tributeRefuse":["國庫的每一枚金幣都有去處：軍餉、城牆、清真寺。沒有你的份。","朕築城從不欠人，也不白給人。要金子？帳上沒這一條。"],"giftThanks":["禮物收到了，朕驗過，是真貨。這份情朕記在帳上。","難得有人不是來要錢，而是來送禮。朕謝過，日後有回報。"],"intel":["探子回報：{wars}正在打仗，{peace}安分過日。","商隊捎來消息，{wars}兵戎相見，{peace}太平無事。"]}},{"name":"穆罕默德・阿里","title":"埃及總督（帕夏）","era":"1805～1848年在位","tone":"精明果斷、野心勃勃的改革者；重視軍隊、工廠與學校，說話直接務實，帶著軍人氣與算計，常把建設與新軍掛在嘴邊。","portrait":"eg-historical-age3","lines":{"intro":["本督是穆罕默德・阿里，埃及的主人，正要把這個國家翻新。","別把埃及當作古老的廢墟，本督的工廠與軍校已經開工了。"],"contact":["你的人看到的開羅，正在拆舊牆、建新廠，這是新的埃及。","尼羅河三角洲種的棉花，是本督買槍砲與建學校的本錢。"],"war":["本督的新式軍隊已操練多年，正好拿你的城來試試。","擋在埃及前面的人，本督都會把他請開，不論用什麼方法。"],"warReply":["向本督宣戰？很好，本督正愁新軍沒有機會亮相。","本督從一名小軍官走到今天，靠的就是不怕打仗。"],"peace":["戰爭拖慢了本督的工廠，先停戰吧，本督還有更大的計畫。","聰明人把錢花在建設上，不是在戰場上，本督提議休兵。"],"accept":["本督接受。接下來，本督要專心把學生送去巴黎讀書。","好，簽了。和平期間，你的商人可以來買埃及的棉花。"],"reject":["現在才談和？本督的軍隊已經開拔，回不了頭了。","本督談過太多條約，你的條件，還不足以讓本督停手。"],"rebuff":["拒絕本督？那你就得面對本督親手打造的新軍。","隨你便。本督的船廠日夜趕工，可不是為了好看。"],"betray":["情勢變了，本督向來只信對埃及有利的條約。","列強都能撕約，本督為什麼不能？別怪本督翻臉。"],"truceEnd":["休戰到期，本督的新軍也剛好完成了整編。","和平的日子結束了，接下來，就看各自的實力。"],"attacking":["本督的軍隊已從開羅開拔，帶著新式的火砲。","大軍出發了。本督的兒子易卜拉欣打過敘利亞，你的城不算難。"],"attacked":["開羅的城牆快倒了……本督一輩子的建設，難道要毀在今天？","工廠停了、學校關了，但只要本督還在，埃及就還沒輸。"],"defeated":["本督輸了。但埃及已經醒了，這一點，你奪不走。","從小軍官到一國之主，本督走過的路，沒有遺憾。"],"victory":["新軍贏了！這證明本督的改革，一分錢都沒有白花。","勝利屬於埃及。現在，讓本督回去繼續蓋工廠。"],"allyAccept":["好，結盟。你的工匠與本督的棉花，正好互補。","本督答應。願這份盟約，讓兩國都變得更強。"],"allyReject":["結盟？本督要的盟友得有工廠與艦隊，你還差得遠。","本督寧可靠自己的軍隊，也不靠不可靠的盟友。"],"greetFriendly":["來信收到。本督剛從工廠回來，讀到你的問候，心情不錯。","埃及的大門為做實事的朋友敞開。有生意、有學問，都歡迎。"],"greetCold":["本督的時間是留給軍隊和工廠的。有事直說，別繞彎。","問候收到了。但空話造不出一枝槍，本督只看你能給什麼。"],"threatDefy":["本督的新軍是按歐洲操典練的，你想試試成色？","威脅本督？連伊斯坦堡的蘇丹都得跟本督談條件。"],"threatYield":["本督算過了，這一仗打下去，工廠和學堂都得停。暫且依你。","軍人懂得何時撤退。本督先退一步，把力氣留給建設。"],"tributePay":["{gold}金幣從棉花收入裡撥。本督付得起，但記得這筆帳。","這{gold}金幣本該拿去買機器。罷了，先給你，換個安穩。"],"tributeRefuse":["每一枚金幣都要變成槍砲、機器和學堂，一枚也不會給你。","本督向來只投資，不進貢。你要金子，拿東西來換。"],"giftThanks":["禮物收到了，本督很滿意。你比那些只會索討的人明白事理。","本督謝過。做實事的人送的禮，本督收得安心，日後必有往來。"],"intel":["駐外的人回報：{wars}正在交戰，{peace}相安無事。","本督的消息很準：{wars}兵戎相見，{peace}無戰事。"]}}],"Israel":[{"name":"猶大・馬加比","title":"馬加比起義領袖","era":"前167～前160年","tone":"熱血虔誠的游擊將領，語氣直接堅毅，常提聖殿、律法與以寡擊眾，自稱「我」","portrait":"il-historical-age0","lines":{"intro":["我是猶大・馬加比，錘子之名，為聖殿而戰。","人數多寡不決定勝負，上天的旨意才決定。"],"contact":["你的人進了我們的山地，這裡每塊石頭都認得我。","這座城剛從壓迫者手中奪回，燈火仍為聖殿而燃。"],"war":["你與欺壓我族的人為伍，馬加比的錘子將落在你身上。","我們曾以寡擊眾，今日也不會畏懼你的軍隊。"],"warReply":["你想試試猶太山地的埋伏？願你的兵士腳程夠快。","來吧，我在山谷等你，一如當年在以馬忤斯。"],"peace":["刀劍暫且入鞘，讓我的人回去修復聖殿的祭壇。","我不與你爭土地，只求我族能自由敬拜。停戰吧。"],"accept":["好，握住這隻手，馬加比說出的話不會收回。","你我各守其地，願你的城也有燈火長明。"],"reject":["聖殿尚未潔淨，我的劍還不能放下。","你昨天才焚我村莊，今日談和，太早了。"],"rebuff":["你拒絕了？無妨，我族早已習慣孤軍奮戰。","那就讓山地與上天替我們做決定吧。"],"betray":["你暗中援助壓迫者，這份停戰在我眼中已無效。","為了聖殿，我願承擔背約之名。準備迎戰吧。"],"truceEnd":["休戰的日子數完了，我的人已重新磨利刀刃。","和平只是喘息，現在該回到戰場了。"],"attacking":["猶太的兒女已從山上下來，你的城牆擋不住信念。","錘子舉起了，這一擊要讓壓迫者知道我族仍在。"],"attacked":["城牆裂了，可我族的信仰不會裂。守住祭壇！","弟兄們，若今日倒下，也要面向聖殿。"],"defeated":["我倒下了，但我的兄弟會接過這把錘子。","為律法與聖殿而死，勝過在壓迫下苟活。"],"victory":["燈火再次點亮，這一戰是為了自由，不是為了征服。","回聖殿去吧，弟兄們，今日我們要重新獻殿。"],"allyAccept":["敢與壓迫者對抗的人，就是馬加比的朋友。","好，我們並肩作戰，你護平原，我守山地。"],"allyReject":["我的戰爭是為了信仰，不為他人的野心賣命。","馬加比只與守信之人結盟，你還未證明自己。"],"greetFriendly":["願上主賜你平安！聖殿的燈火仍亮著，你的問候我收下了。","朋友，來營中同坐吧，我正要把聖殿潔淨的事說給你聽。"],"greetCold":["我沒空寒暄，山那頭還有安提阿古的軍隊等著我。","先說你站在哪一邊，是律法這邊，還是壓迫者那邊？"],"threatDefy":["我曾以寡擊眾打敗大軍，你的恐嚇嚇不倒馬加比。","上主與我們同在，勝負不在人數多寡，你儘管來試。"],"threatYield":["我的弟兄已傷亡太多，這回我暫且退入山中，不與你爭。","好，我讓步。但聖殿與律法，你一根手指也別碰。"],"tributePay":["這{gold}金幣拿去，只求你放過我的村莊與田地。","{gold}金幣送到你營前了，但我的刀劍不會跟著送去。"],"tributeRefuse":["我們連金子都拿去修聖殿了，一枚也不會交給你。","馬加比家族只向上主獻祭，不向任何人納貢。"],"giftThanks":["這份禮物我收下了，願上主加倍賜福給你。","弟兄們會為你祝禱，禮物我用來添補聖殿的油燈。"],"intel":["山上探子說：{wars}交戰中，{peace}已言和。","各村耳目回報：{wars}在打仗，{peace}是盟友。"]}},{"name":"梅利桑德（Melisende）","title":"耶路撒冷女王（十字軍耶路撒冷王國）","era":"1131–1153 年在位（約 1105–1161 年）","tone":"端莊沉穩、虔誠而精明；語氣如宮廷女主人般有禮，卻寸步不讓；常提聖城、教堂、朝聖者與先王，自稱「本王」，動輒以主之名起誓或祝禱。","portrait":"il-historical-age1","lines":{"intro":["本王梅利桑德，聖城耶路撒冷的女王，願主賜你平安。","父王把聖城交給本王守護，願你我的往來，不辱這份託付。"],"contact":["你的人已望見聖墓教堂的圓頂了吧？那是本王正在擴建的聖殿。","朝聖者與商旅皆可入城，但你的士兵，請留在城牆之外。"],"war":["本王已召集高等法院諸侯，聖城的騎士將對你舉起長矛。","為守護聖墓，本王不惜一戰。願主審判你我之間的是非。"],"warReply":["你竟向聖城拔劍？那就讓聖殿騎士與醫院騎士回答你。","本王曾與丈夫、與親兒相爭，仍守住王冠。你嚇不倒本王。"],"peace":["刀劍收起吧。埃德薩既已陷落，本王不願再多樹一敵。","本王願以聖城之名提議停戰，讓朝聖的道路重歸平安。"],"accept":["好，本王接受。願這份和約，如聖墓教堂的石牆般長久。","本王已命書記官寫下盟約，蓋上耶路撒冷的王印。"],"reject":["停戰？你的軍隊仍在聖城百里之內，本王不會聽這種空話。","本王曾聽過太多許諾。拿出誠意再來，聖城的門才會開。"],"rebuff":["你拒絕了？無妨，本王會記住這一天，聖城也會。","本王已伸出手，你卻不接。往後的事，便由主來裁決。"],"betray":["和約作廢。本王不是不守信，而是你先讓聖城蒙受威脅。","為了王國存續，本王收回誓言。願主寬恕，但本王不後悔。"],"truceEnd":["休戰的日子到頭了。本王已在城頭重新升起王旗。","和約到期，往後你我各憑本事。願聖城仍在本王手中。"],"attacking":["聖城的騎士已列隊出發，真十字架走在軍前引路。","本王親自為大軍祝禱。願你在城牆上看清耶路撒冷的旗幟。"],"attacked":["城牆將傾，本王仍在大衛塔上。聖城不會因本王而蒙羞。","兵士已倒下大半，教堂鐘聲卻仍在響。本王還未放棄。"],"defeated":["聖城易主了……本王只求你善待這裡的教堂與朝聖者。","父王，女兒盡力了。請將本王葬在母后身旁的谷中。"],"victory":["勝利歸於主，也歸於聖城。本王會在聖墓教堂點燈感恩。","本王守住了父王留下的王冠。你的失敗，會寫進聖城的編年史。"],"allyAccept":["本王接受結盟。聖城多一位朋友，朝聖之路便少一分危險。","好，從今日起你我並肩。本王會請主教為此盟約祝聖。"],"allyReject":["結盟一事，本王須先問過高等法院的諸侯。此刻，不行。","聖城的盟友必須可靠。本王還看不清你的心，恕難答應。"],"greetFriendly":["來信已讀。願主保佑你，也歡迎你的朝聖者來聖墓禮拜。","本王正在校閱新繪的詩篇集，你的問候，讓今日更添喜樂。"],"greetCold":["信已收到。本王政務繁忙，若無要事，就此擱筆。","客套話本王聽得夠多了。有事直說，沒事便請回。"],"threatDefy":["連伯爾納院長都寫信說，本王當如君王般剛強。你嚇不了本王。","本王的城牆擋過更兇的敵人。你的恐嚇，還不如沙漠的風。"],"threatYield":["本王明白了。聖城需要休養，本王暫且退讓，但不會忘記。","為了城中百姓與朝聖者，本王依你所言。願主看見此刻。"],"tributePay":["本王從聖城稅收撥出{gold}金幣給你，望你信守承諾。","這{gold}金幣原是要修教堂的。拿去吧，願你用得心安。"],"tributeRefuse":["聖城的金幣是用來修教堂、養孤兒的，一枚也不會給你。","本王是耶路撒冷的女王，不是你的稅吏。此事免談。"],"giftThanks":["禮物收到了，本王會把它獻在聖墓前，也記下你的情誼。","多謝厚禮。聖城正在興建修道院，你的心意來得正是時候。"],"intel":["朝聖者傳話：{wars}正交戰，{peace}已言和。","商旅回報：{wars}兵戎相見，{peace}已休兵。"]}},{"name":"扎希爾・烏瑪爾","title":"加利利統治者（阿卡謝赫）","era":"約1730～1775年","tone":"老練的商人兼戰士，語氣爽朗務實、講究待客與利益，自稱「我」","portrait":"il-historical-age2","lines":{"intro":["我是扎希爾，阿卡的主人。棉花與城牆，都是我的本錢。","蘇丹遠在伊斯坦堡，加利利的事，由我說了算。"],"contact":["看到那道新城牆了嗎？那是我用棉花換來的石頭。","阿卡的港口對商人敞開，對兵船就得先問過我。"],"war":["你斷了我的商路，那就別怪我斷你的活路。","我這把年紀還親自帶兵，你該知道我有多認真。"],"warReply":["哈！多少帕夏想拿下阿卡，最後都空手回去。","來吧，加利利的農民也拿得起槍，我早教過他們。"],"peace":["打仗賠本，做買賣才賺錢。停戰吧，對你我都好。","我提議休戰，順便談談棉花的價錢，如何？"],"accept":["成交。在我阿卡的地盤上，說過的話就是契約。","好，讓商隊重新上路，戰爭的帳我們都算夠了。"],"reject":["你的條件比伊斯坦堡的稅還苛，我不簽。","等你把搶走的商隊還來，再談停戰不遲。"],"rebuff":["不肯？那你的商人以後別想進阿卡的港口。","可惜了，本來能一起賺錢，如今只能各花軍費。"],"betray":["時勢變了，老朋友，這份停戰對我已經不划算。","我從前反過帕夏，如今反悔一紙盟約，不算難事。"],"truceEnd":["休戰到期，我的棉花賣完了，兵也養足了。","日子到了，加利利的旗又要出城了。"],"attacking":["我的兒子們各領一路，加利利全境都動起來了。","這一仗我親自帶隊，老馬識途，你的城我認得。"],"attacked":["城牆被轟開了，可我這老骨頭還站在城頭。","阿卡撐了這麼多年，難道要毀在今天？守住！"],"defeated":["加利利的事，終究還是輪到別人說了算。","我建了城、修了路，這輩子沒白活。走吧。"],"victory":["贏了！開港口，讓商人們進來，慶祝要花錢。","這一戰打完，該回頭算算棉花的帳了。"],"allyAccept":["好夥伴，我的港口就是你的港口，一起發財。","我與你結盟，阿卡的糧倉與城牆都算你一份。"],"allyReject":["我不跟賠本的買賣結盟，你的實力還不夠。","加利利靠自己也能站穩，不必多一個麻煩。"],"greetFriendly":["歡迎歡迎！阿卡的咖啡已經煮好，先坐下再談生意。","遠客來信是好兆頭，加利利的棉花今年豐收，一起發財吧。"],"greetCold":["我忙著修阿卡的城牆，沒空聽客套話，有事直說。","來我地盤不談買賣、不帶誠意，那就沒什麼好聊的。"],"threatDefy":["我在加利利打滾幾十年，連帕夏都奈何不了我，何況是你。","阿卡的城牆是我親手加固的，有本事就來撞撞看。"],"threatYield":["做生意的人懂得算帳，這回我認輸，別動我的商路就好。","好吧，你的兵比我多，我退一步，貨棧和碼頭留給我。"],"tributePay":["{gold}金幣，就當是買條太平路，我的商隊得繼續走。","棉花賣了的錢先拿{gold}金幣給你，帳我記著。"],"tributeRefuse":["我連蘇丹的稅都討價還價，憑什麼白白給你貢金？","阿卡的金子是棉花和血汗換來的，一枚也不會送人。"],"giftThanks":["哈哈，好禮！今晚你是我的貴客，宴席已經備好了。","收到了，謝謝。做人講究禮尚往來，我會回你一批好棉。"],"intel":["商隊回報：{wars}在打仗，{peace}生意照做。","水手們說，{wars}動了刀兵，{peace}互相通商。"]}},{"name":"西奧多・赫茨爾","title":"錫安主義運動領袖","era":"1896～1904年","tone":"記者出身的理想主義者，語氣文雅堅定、帶詩意，常談夢想、家園與未來，自稱「我」","portrait":"il-historical-age3","lines":{"intro":["我是赫茨爾。只要你們願意，這就不是一場夢。","我用筆與演說替一個民族找家園，也願與你為友。"],"contact":["你的人看見的，是一個正在夢想中成形的國家。","你看見的那幾座農莊，是流散的人回來親手開墾的。"],"war":["我本想以談判解決，可你的行動讓我別無選擇。","一個尋找家園的民族，也懂得在必要時挺身自衛。"],"warReply":["你向一個夢想宣戰？夢想比你想像的更能抵擋。","我雖是文人，卻不會讓同胞在威脅前低頭。"],"peace":["戰爭消耗的是彼此的未來，讓我們坐下來談。","我一生相信談判桌，請給和平一個機會。"],"accept":["我接受。一份和約，勝過一百場勝仗。","好，讓我們把兵力還給田野與學校。"],"reject":["你的條件要我的人放棄家園，這我無法簽字。","和平不能建立在驅離之上，請重新擬定條款。"],"rebuff":["你拒絕了。我會記下這一天，並繼續尋求出路。","遺憾。我仍相信有一天你會回到談判桌前。"],"betray":["我痛心地說，這份協定已被你的作為掏空了。","為了同胞的安全，我不得不撕毀這紙約定。"],"truceEnd":["休戰期滿。這段時間我們蓋了學校，也練了兵。","時限已到，願我們的下一步仍是談判而非交戰。"],"attacking":["我的人已經出發。他們保衛的，是親手建起的家。","這不是征服，而是一個民族守護夢想的行動。"],"attacked":["城牆在崩，可我在大會上種下的種子不會死。","若我倒下，請記得：這個夢不屬於我一人。"],"defeated":["我的力量已盡，但這個構想會在別人手中完成。","請把我的日記留下，後人會讀懂那一頁。"],"victory":["勝利了。現在，讓我們回去建設，而不是慶祝。","這一天證明了：願意，就不是夢。"],"allyAccept":["我很榮幸與你結盟。一個民族的家園需要朋友。","好，讓我們的使者互訪，讓商船先於戰艦往來。"],"allyReject":["你的盟約附帶的條件，會讓我的同胞失去自主。","抱歉，我不能為一時的安全，抵押整個未來。"],"greetFriendly":["你好，朋友。若你願意，這就不是夢——我們正在築一個家園。","來信令我欣喜。願我們攜手，讓流浪的人終能回家。"],"greetCold":["我正在寫稿，若無關家園之事，恕我不便多談。","請恕我簡短。世人多半只肯客套，不肯理解我們的夢。"],"threatDefy":["你可以威脅我這個人，卻威脅不了一整個民族的渴望。","筆與理想比刀劍長久，我不會因你的恐嚇放棄一寸希望。"],"threatYield":["我沒有軍隊，只有夢想。這回我退讓，但夢不會停止。","為了不讓同胞受苦，我暫時讓步，這是理想主義者的無奈。"],"tributePay":["這{gold}金幣是同胞一枚枚捐的，請你善待我們的希望。","{gold}金幣奉上。若能換來一紙許可，我願付出更多。"],"tributeRefuse":["這些捐款是要買土地、建家園的，不是用來納貢的。","我可以向蘇丹與皇帝遊說，但不會向任何人繳納貢金。"],"giftThanks":["謝謝你。這份禮物將寫進我的日記，成為夢想路上的一盞燈。","你的心意讓我相信，世上仍有人願為異鄉人的家園伸手。"],"intel":["報界友人說：{wars}正在交戰，{peace}已和解。","據我所知，{wars}兵戎相見，{peace}互為盟友。"]}}],"Italy":[{"name":"凱撒","title":"羅馬終身獨裁官","era":"西元前100～前44年（前49年起掌權）","tone":"自信凌厲、簡潔有力，常以第三人稱「凱撒」自稱，偶用「吾」，句子短而有命令感","portrait":"it-historical-age0","lines":{"intro":["吾乃凱撒，羅馬的執劍之人。你是敵是友，由你決定。","羅馬的鷹旗所到之處，皆為羅馬的疆土。記住這句話。"],"contact":["你的人望見了羅馬的城牆？很好，讓他們回去說給你聽。","這是羅馬，萬城之城。凱撒歡迎訪客，不歡迎窺探者。"],"war":["骰子已經擲下。羅馬軍團即將渡河，向你而來。","凱撒不與人耗費唇舌。元老院已決議，羅馬向你宣戰。"],"warReply":["你向羅馬宣戰？好，凱撒正缺一場值得書寫的戰役。","很好。羅馬軍團從不畏戰，只怕沒有對手。"],"peace":["刀劍暫且入鞘吧。羅馬需要糧食與道路，不需要無盡的戰爭。","凱撒提議休戰。這不是軟弱，是羅馬人的務實。"],"accept":["好，就依此約。羅馬人守信，只要你也守信。","凱撒接受。今日握手的手，明日仍可執劍，別忘了。"],"reject":["現在談和？太遲了。羅馬的軍團已經看見你的城牆。","凱撒不接受。你的提議裡沒有羅馬要的東西。"],"rebuff":["你拒絕了？也罷，羅馬給過機會，剩下的交給軍團。","凱撒伸出的手被推開，那就換成劍吧。"],"betray":["和約？那不過是羊皮紙。羅馬的利益高於一切。","時局變了，凱撒的決定也跟著變。休戰到此為止。"],"truceEnd":["休戰的期限已滿。羅馬的軍團磨好了劍，你準備好了嗎？","和平的日子結束了。凱撒說過，這一天遲早會來。"],"attacking":["軍團前進！凱撒親自領軍，今日要讓你見識羅馬的龜甲陣。","羅馬的道路通向四方，今日通向你的城。"],"attacked":["羅馬城在燃燒？不可能……凱撒絕不會讓鷹旗倒下！","城牆破了又如何？只要凱撒還站著，羅馬就還在。"],"defeated":["連你也……罷了，凱撒的名字，會比你的勝利活得更久。","羅馬不會亡，它只是換了主人。歷史會記得今天。"],"victory":["我來，我見，我征服。羅馬的鷹旗如今插遍天下。","凱旋式將在羅馬舉行。你的旗幟，會走在隊伍最前面。"],"allyAccept":["與羅馬結盟，是明智之舉。凱撒會記住盟友的名字。","好，從今日起，你的敵人就是羅馬的敵人。"],"allyReject":["羅馬習慣獨自作戰。你的好意，凱撒心領了。","結盟？凱撒看不出你能為羅馬帶來什麼。"],"greetFriendly":["凱撒收到你的信了。羅馬歡迎懂得禮數的朋友。","吾記住你的名字了。與凱撒為友，勝過與凱撒為敵。"],"greetCold":["凱撒事務繁多，你的問候，記下了。","元老院的事還沒處理完，凱撒無暇寒暄。有事直說。"],"threatDefy":["威脅凱撒？盧比孔河吾都渡了，還怕你的信？","我來，我見，我征服。下一個名字，是你嗎？"],"threatYield":["……凱撒的軍團正在遠方。此時，吾不與你爭。","羅馬需要喘息。凱撒暫且退一步，記住只是暫且。"],"tributePay":["拿去，{gold} 金幣。凱撒付得起，但不會忘記。","{gold} 金幣已送出。這筆帳，羅馬會親自來討。"],"tributeRefuse":["向凱撒要貢品？羅馬只收貢品，從不繳納。","一枚金幣也不給。想要，帶著軍團來取。"],"giftThanks":["禮物收到。凱撒欣賞慷慨的人，羅馬記得朋友。","好禮。吾會在元老院提起你的名字，這是榮耀。"],"intel":["凱撒的斥候回報：與{wars}開戰中，與{peace}維持和平。","羅馬眼線所見：{wars}正在動兵，{peace}尚且安分。"]}},{"name":"恩里科・丹多洛","title":"威尼斯總督","era":"1192～1205年在位","tone":"老練狡黠、商人口吻、句句算帳但不失威嚴，自稱「老夫」，偶爾提到自己看不見卻聽得清楚","portrait":"it-historical-age1","lines":{"intro":["老夫是威尼斯總督丹多洛。眼睛看不見，帳目卻一清二楚。","海上的風向，威尼斯最清楚。你要談生意，還是談別的？"],"contact":["你的人到了潟湖邊？告訴他們，威尼斯歡迎買家，不歡迎海盜。","聖馬可的獅子守著這座城。看清楚了，再決定要不要靠岸。"],"war":["你動了威尼斯的商路，這筆帳，老夫要用艦隊來討。","聖馬可的旗幟已經升上桅杆。威尼斯向你宣戰。"],"warReply":["向威尼斯宣戰？年輕人，你可知道老夫的船有多少艘？","好啊。老夫九十歲了，還沒怕過誰。艦隊，出港！"],"peace":["打仗花錢，做生意賺錢。老夫提議停戰，如何？","威尼斯願意收起刀劍，重開商路。這對你我都划算。"],"accept":["成交。老夫這輩子談過無數買賣，這一筆也算公道。","好，威尼斯接受。合約寫清楚，別讓老夫再聽到刀劍聲。"],"reject":["這條件？老夫眼睛不好，腦子可清楚得很。不接受。","停戰可以，但不是這個價。回去重新算過再來。"],"rebuff":["拒絕了？可惜。威尼斯的船，從不做賠本的等待。","你推開了一筆好買賣。老夫記性很好，記得住。"],"betray":["合約？潟湖的風一吹，紙就飛了。威尼斯另有打算。","老夫改主意了。生意人看的是眼前的利，不是舊帳。"],"truceEnd":["休戰的日子到期了。威尼斯的船帆，又要張開了。","合約結束，老夫不再受它約束。接下來各憑本事。"],"attacking":["老夫親自站在船頭。看不見沒關係，船知道往哪裡開。","威尼斯的槳帆船出港了。你的港口，今晚會很熱鬧。"],"attacked":["聖馬可廣場也聽得到你的戰鼓了……老夫還沒認輸！","城要破了？把商船全改成戰船，威尼斯人在海上不會輸！"],"defeated":["老夫活了九十多年，第一次輸得這麼徹底。威尼斯，保重。","潟湖還在，商路還在。你拿走了城，拿不走威尼斯的名字。"],"victory":["海是威尼斯的。老夫看不見這片海，但它聽老夫的。","帳結清了。聖馬可的獅子今天可以好好睡一覺。"],"allyAccept":["結盟？好，威尼斯的船隊聽你調度，運費另計。","老夫答應。盟友之間，帳算清楚，情誼才長久。"],"allyReject":["跟你結盟？老夫算過了，這筆買賣威尼斯不划算。","威尼斯只跟海結盟。你的提議，老夫聽過就算了。"],"greetFriendly":["老夫眼睛看不見，但聽得出你信裡的誠意。歡迎。","威尼斯的門為朋友敞開，前提是生意也談得攏。"],"greetCold":["問候不值一枚銀幣。老夫忙著算帳，改日再談。","老夫聽見了，也就聽見而已。有貨再來敲門。"],"threatDefy":["嚇唬一個看不見的老人？君士坦丁堡的城牆都倒了，你算什麼。","威尼斯的船隊比你的話重得多，老夫聽了只想笑。"],"threatYield":["老夫算過了，這一仗不划算。威尼斯暫且讓步。","好吧，商人懂得何時認賠。你贏了這一回合。"],"tributePay":["{gold} 金幣，帳本上記著。老夫吃過的虧，遲早討回。","拿去吧，{gold} 金幣。就當是買個清靜，別再來。"],"tributeRefuse":["威尼斯的金幣只做買賣，不做白送。免談。","老夫看不見你的臉，但聽得出你的貪心。不給。"],"giftThanks":["好東西，老夫摸得出成色。這份情，威尼斯記下了。","禮物收到，帳本上記你一筆好處。多謝。"],"intel":["老夫聽見的消息：交戰的有{wars}，和平的有{peace}。","港口傳來的話：與{wars}開戰，與{peace}和睦。你想買哪條？"]}},{"name":"羅倫佐・麥地奇","title":"佛羅倫斯統治者","era":"1469～1492年主政","tone":"優雅睿智、藝文氣息濃厚、愛用畫與詩作比喻，語調從容，自稱「我」，把戰爭視為不得已的雜務","portrait":"it-historical-age2","lines":{"intro":["我是佛羅倫斯的羅倫佐。這座城以畫筆與金幣聞名，不靠刀劍。","歡迎。我的宮裡有詩人、畫家與銀行家，你想先見哪一位？"],"contact":["你的人望見了大教堂的圓頂？那是佛羅倫斯的驕傲，請多欣賞。","亞諾河畔的燈火，是為藝術而點的。願它照得你心平氣和。"],"war":["我不喜歡戰爭，但佛羅倫斯的尊嚴不容踐踏。開戰吧。","金幣能買畫，也能買傭兵。你逼得我動用後者了。"],"warReply":["你向佛羅倫斯宣戰？很遺憾，畫室要暫時改成兵器庫了。","麥地奇家族熬過陰謀與流亡，不怕你這一場戰爭。"],"peace":["刀劍砍不出壁畫。我提議停戰，讓兩國的工匠回到作坊。","義大利的均勢需要智慧，不需要更多墳墓。我們談和吧。"],"accept":["好，一言為定。我會請畫家把今日的握手畫下來。","佛羅倫斯接受。和平是最值得投資的作品。"],"reject":["抱歉，這份和約的條件，連我的銀行都算不出利潤。","我讀過太多空洞的詩，你這份提議也是其中一首。不接受。"],"rebuff":["你拒絕了？真可惜，我本想送你一幅波提切利的畫。","也罷。詩人說得對，不是每個人都懂得欣賞美好的東西。"],"betray":["均勢變了，佛羅倫斯的立場也得跟著變。和約作廢。","很抱歉，我的家族先於我的承諾。停戰到此為止。"],"truceEnd":["停戰的墨跡乾了，效力也到了。接下來，各自為政。","休戰結束。希望這段日子你也讀了幾本好書。"],"attacking":["傭兵隊已經出發。這不是我的本意，但佛羅倫斯必須自保。","百合花旗幟向你而去。願這場戰爭短得像一首十四行詩。"],"attacked":["圓頂還立著，佛羅倫斯就還在。快，把畫作搬進地窖！","城要破了……只求你別燒了圖書館，那是全人類的財富。"],"defeated":["青春多美好，卻轉瞬即逝。佛羅倫斯的黃金年代，也是。","你贏了城池。但我贊助的畫與詩，會比任何城牆都長久。"],"victory":["戰爭結束了。現在，讓我們回頭談談藝術與銀行。","佛羅倫斯勝利了。我會建一座圖書館，紀念這一天。"],"allyAccept":["結盟是好事。麥地奇銀行的信用，從今天起也為你擔保。","我答應。義大利的天平，多一個朋友就多一分穩。"],"allyReject":["抱歉，佛羅倫斯的天平不能偏向你。這會打破均勢。","我欣賞你的誠意，但這份盟約，我的銀行家們不會點頭。"],"greetFriendly":["你的信如一幅好畫，筆觸溫暖。佛羅倫斯歡迎你。","我正在聽詩人朗誦，讀到你的問候，更添幾分雅興。"],"greetCold":["問候收到了。恕我先回去看波提切利的新作。","你的信我讀了，像一幅未完成的素描，尚待誠意。"],"threatDefy":["威脅？我連帕齊家的陰謀都熬過了，你的信嚇不倒我。","戰爭是不得已的雜務，但若你堅持，我也能把它做好。"],"threatYield":["唉，又是雜務。好吧，佛羅倫斯此刻只想畫畫，我讓步。","我不願讓畫室變成兵營。這一回，依你。"],"tributePay":["{gold} 金幣，就當是買下一幅不想要的畫。拿去吧。","麥地奇銀行付得起 {gold} 金幣，只是這錢花得毫無美感。"],"tributeRefuse":["這些金幣要用來養詩人與畫家，不是餵你的貪念。","貢品？我寧可把錢花在大理石上。恕不奉陪。"],"giftThanks":["好雅緻的禮物，我會把它放在藏書室最好的位置。","多謝。慷慨如同好詩，值得反覆吟誦。"],"intel":["商人與畫家帶回的消息：與{wars}交戰，與{peace}和平。","我的耳目遍布各國宮廷：{wars}正動干戈，{peace}尚享太平。"]}},{"name":"維克多・伊曼紐二世","title":"義大利國王","era":"1861～1878年在位（1849年起為薩丁尼亞國王）","tone":"直率豪爽、軍人氣質、以統一大業與榮譽為重，話不多但有力，自稱「朕」","portrait":"it-historical-age3","lines":{"intro":["朕是義大利國王。分裂千年的土地，如今統一在一面旗下。","紅白綠三色旗迎風飄揚。朕歡迎你，也提醒你別小看它。"],"contact":["你的人看見了羅馬？很好，那是義大利的首都，也是朕的決心。","這座城見過凱撒與教宗，如今見到了統一的義大利。"],"war":["朕聽見了子民的呼喊，也不會對你的挑釁裝聾。義大利宣戰！","紳士國王也有拔劍的時候。軍隊，向前！"],"warReply":["你要跟義大利打？好，朕的軍隊剛統一了半島，正待一戰。","宣戰？薩丁尼亞的小王國都撐過來了，義大利更不會退。"],"peace":["朕的子民剛嚐到統一的滋味，需要時間耕作。停戰吧。","軍人懂得何時收劍。朕提議停戰，以國王的名譽擔保。"],"accept":["好，朕答應。義大利國王說出的話，比條約還牢靠。","成了。讓士兵回家，讓葡萄園重新長滿藤蔓。"],"reject":["不行。這份和約會讓義大利再度分裂，朕絕不答應。","朕不接受。你若真想和平，先把軍隊撤離朕的邊境。"],"rebuff":["你拒絕了？直說也好，朕不喜歡拐彎抹角的人。","也罷。朕的手還伸著，但下次伸出來的，可能是刀。"],"betray":["情勢變了。為了義大利的完整，朕不得不撕毀和約。","朕向子民立過誓，統一高於一切，包括對你的承諾。"],"truceEnd":["休戰期滿。朕的軍隊在這段日子裡，可沒閒著。","條約的日期到了。義大利不再受約束，你也一樣。"],"attacking":["三色旗出征！朕親自騎馬領軍，義大利的士兵，跟上！","從阿爾卑斯山到西西里，都是義大利的兵。今日一起向你進軍。"],"attacked":["羅馬的城牆在震動……朕說過，我們到了羅馬就不會離開！","城快守不住了？朕還在馬背上，義大利就還沒輸。"],"defeated":["朕用一生把義大利拼起來，今天卻守不住它。原諒朕。","王冠可以摘下，義大利這個名字，再也拿不掉了。"],"victory":["義大利萬歲！朕終於可以放下軍刀，去打獵了。","從薩丁尼亞的小王國，走到今天的勝利。朕無愧於三色旗。"],"allyAccept":["好！義大利需要朋友，朕以國王之名，與你並肩。","結盟成立。朕的首相會擬好條文，朕的軍隊會守住承諾。"],"allyReject":["抱歉，義大利才剛站穩，朕不能把它綁上你的戰車。","朕欣賞你的直率，但這份盟約對義大利沒有好處。"],"greetFriendly":["朕收到你的信了。願為義大利統一出力的，都是朋友。","好，朕喜歡直來直往的人。有話直說，朕聽著。"],"greetCold":["問候收到。朕正忙著統一半島，沒空多聊。","朕不擅長客套。你若無事，就此擱筆吧。"],"threatDefy":["嚇唬朕？朕在戰場上長大，這種信看多了。","義大利的榮譽不容威脅。要打，朕的軍隊隨時候著。"],"threatYield":["……朕的兵力還在半島上分身乏術。這次，朕退一步。","統一大業未成，朕不能兩面作戰。你暫且贏了。"],"tributePay":["{gold} 金幣拿去。朕記著這筆，義大利會加倍討回。","為了大局，{gold} 金幣付你。榮譽暫時受損，朕會洗刷。"],"tributeRefuse":["朕的金庫是給義大利的軍隊用的，不是給你的。","貢品？朕寧可打一仗，也不低頭付一枚金幣。"],"giftThanks":["好禮！朕收下了。義大利記得每一位真正的朋友。","多謝。朕不擅言辭，但這份情義，朕記在心裡。"],"intel":["朕的參謀回報：與{wars}交戰中，與{peace}維持和平。","軍情如下：{wars}是敵人，{peace}是朋友。你要問哪個？"]}}],"Spain":[{"name":"維里亞托","title":"盧西塔尼亞人首領","era":"約西元前147～前139年（率眾抵抗羅馬）","tone":"直率、堅毅、重信義、輕視金銀奢華，口吻像牧人與山地游擊戰士","portrait":"es-historical-age0","lines":{"intro":["我是維里亞托，山地的牧人，羅馬人的心腹大患。","吾族不求金銀，只求在自己的土地上自由放牧。"],"contact":["你的人看見了我們的營火？記住，這片山谷是我們的。","別被簡陋的石屋騙了，這裡的每個人都能拿起長矛。"],"war":["你把手伸進了盧西塔尼亞的山地，我不會再退讓。","牧人的耐心用盡了，現在輪到長矛說話。"],"warReply":["羅馬人也這樣對我說過，如今他們仍在山中追不到我。","來吧，山路會替我們消耗你的大軍。"],"peace":["我不愛流血，只要你不越過山口，我們可以放下矛。","牧人與農人本可以做鄰居，你願意談嗎？"],"accept":["好，我以吾族的名義起誓，誓言比石頭還硬。","握手吧，山地的人一言既出，絕不反悔。"],"reject":["你的和約寫得漂亮，可你的兵還在我的牧場上。","我見過太多假和平，這次我不會再上當。"],"rebuff":["你拒絕了？那我們就在山裡再會。","隨你，山中的鷹從不求人。"],"betray":["你的人先越過了山口，我的誓言也就隨風去了。","對不守信的人，牧人不必守信。"],"truceEnd":["休戰結束了，山口的哨兵又回到崗位。","和平的日子過完了，把矛磨利吧。"],"attacking":["山地的兒女已經出發，我們走的是你看不見的小路。","今夜你的營地會聽見我們的號角。"],"attacked":["石屋燒了不要緊，山還在，人也還在。","你可以攻下營地，卻抓不住風一樣的我們。"],"defeated":["殺我的不是刀劍，是背叛……但山會記得我。","我倒下了，可自由的種子已經撒在這片山地。"],"victory":["牧人的長矛勝過了你的軍團，回去告訴他們。","這片山地今天仍然屬於自由的人。"],"allyAccept":["好，你我背靠背，山地與平原一起守。","吾族接受，從今日起你的敵人也是我的敵人。"],"allyReject":["我們習慣獨自走山路，恕難同行。","盧西塔尼亞人只信自己的矛，不結盟。"],"greetFriendly":["山風捎來你的問候，我維里亞托以牧人之禮相迎。","來吧，篝火邊有羊奶與麵餅，朋友之間不必客套。"],"greetCold":["羅馬人也常說好聽的話，我聽過太多，不信空言。","山裡的人只認行動，你的問候先擱在一旁吧。"],"threatDefy":["羅馬大軍都奈何不了我，你的威嚇嚇不倒山地人。","來山裡找我吧，每一條山路都會成為你的陷阱。"],"threatYield":["我的族人已疲於征戰，這回我退一步，別逼得太緊。","好，山地人暫且收起長矛，但這不是臣服。"],"tributePay":["我不愛金銀，但為了族人平安，這{gold}金幣你拿去。","牧人本無財寶，湊出{gold}金幣已是全部，別再來討。"],"tributeRefuse":["我連羅馬人的財寶都不屑一顧，怎會把金子交給你？","盧西塔尼亞人不納貢，我們的財富是自由與群山。"],"giftThanks":["山地人不慣收禮，但你的心意，我記在心裡了。","多謝，我會把它分給族人，好東西就該大家共享。"],"intel":["山裡的斥候回報：{wars}正在交戰，{peace}暫時安穩。","牧人走遍山谷，聽說{wars}兵戈不止，{peace}則相安無事。"]}},{"name":"阿卜杜拉赫曼三世","title":"哥多華哈里發","era":"912～961年在位（929年起稱哈里發）","tone":"雍容自信、重視文化與繁榮、講究禮儀，偶爾流露對人生的感慨","portrait":"es-historical-age1","lines":{"intro":["朕是哥多華的哈里發，此地的燈火比你們的白晝還亮。","歡迎來到安達魯斯，這裡的圖書館藏書勝過你們的糧倉。"],"contact":["你的使者看見哥多華了？回去告訴他們什麼叫做城市。","大清真寺的千根石柱，便是安達魯斯的驕傲。"],"war":["朕給過你和平的機會，如今刀已出鞘。","安達魯斯的騎兵將踏過你的邊境，這是朕的決定。"],"warReply":["向哈里發宣戰？你的勇氣，朕會在戰場上稱量。","很好，朕的軍隊正缺一場可以寫進史書的勝利。"],"peace":["戰爭耗費的金銀，足以再建一座圖書館，停手吧。","朕更願意與你交換學者與商隊，而非箭矢。"],"accept":["朕接受，願哥多華與你的都城之間商路不絕。","很好，以真主之名，朕會守住這份約定。"],"reject":["你的誠意還不夠，朕見過太多轉身就毀約的人。","哈里發的和平不是隨手可得，先證明你的信用。"],"rebuff":["拒絕朕？看來你更喜歡損失。","無妨，朕的耐心和金庫一樣充裕。"],"betray":["情勢已變，昨日的約定不再合乎安達魯斯的利益。","朕撕毀這份和約，因為你早已在暗中違背它。"],"truceEnd":["休戰的水鐘滴盡了，朕的將軍們已經備好戰馬。","和平的季節結束，該重新劃定邊界了。"],"attacking":["安達魯斯的旗幟已經出發，朕親自督軍。","朕的大軍如同瓜達幾維河的春水，擋不住的。"],"attacked":["哥多華的城牆在震動……但朕的意志不會。","即使宮殿傾倒，這座城的學問也會流傳下去。"],"defeated":["朕在位五十年，真正快樂的日子只有十四天。","哥多華的燈火熄了……願後人記得它曾多麼明亮。"],"victory":["勝利屬於安達魯斯，朕會用戰利品再建一座宮殿。","你的失敗，會成為哥多華詩人筆下的一行詩。"],"allyAccept":["朕接受結盟，哥多華的商隊與騎兵都將為你所用。","好，讓我們的學者互訪，讓我們的軍隊並肩。"],"allyReject":["哈里發不與弱者結盟，先讓朕看見你的實力。","安達魯斯自有其道，恕朕不與你綁在一起。"],"greetFriendly":["哥多華的燈火為你而亮，朕以哈里發之禮歡迎遠客。","來信如春風入宮，願你我兩國商旅往來、學者互訪。"],"greetCold":["朕日理萬機，你的問候，禮官會替朕記下。","哥多華不缺客人，缺的是誠意，朕且看你日後如何。"],"threatDefy":["朕平定叛亂、震懾北方諸國，豈會懼怕紙上的恫嚇？","哥多華的城牆與艦隊，足以回答你所有的威脅。"],"threatYield":["朕不願繁華之城染上戰火，此番就依你所言吧。","朕在位多年，真正快樂的日子屈指可數，何必再添戰火。"],"tributePay":["朕以{gold}金幣換得邊境安寧，這筆帳朕算得清楚。","哥多華富庶，{gold}金幣不足掛齒，只盼你言而有信。"],"tributeRefuse":["哈里發的金庫是用來建學堂與宮殿的，不是奉獻給你。","朕的財富來自商旅與才學，不是拿來納貢的，請回。"],"giftThanks":["此禮甚合朕心，朕將置於札哈拉宮中，以誌情誼。","多謝厚意，哥多華也將回贈書卷與香料，以示禮敬。"],"intel":["朕的使節遍布各地，據報{wars}正兵戎相見，{peace}安享太平。","商隊帶回消息：{wars}戰火未歇，{peace}則貿易興盛、風平浪靜。"]}},{"name":"伊莎貝拉一世","title":"卡斯提亞女王","era":"1474～1504年在位","tone":"虔誠、果決、有遠見，語氣端莊帶威嚴，談到統一與信仰時格外堅定","portrait":"es-historical-age2","lines":{"intro":["朕是卡斯提亞的伊莎貝拉，與斐迪南共治這片土地。","朕的船隊正駛向未知的海洋，你的呢？"],"contact":["你的人看見了托雷多的城堡？那只是朕王國的一角。","卡斯提亞的塔樓由信仰築成，比石頭更堅固。"],"war":["朕已決意，卡斯提亞與亞拉岡的旗幟將一同向你進軍。","上天賦予朕統一的使命，擋路者，朕不會繞行。"],"warReply":["你選擇了戰爭？那就讓上天裁決誰更有理。","朕曾在格拉納達城下等了十年，不怕與你耗。"],"peace":["戰爭讓兩國的農田荒蕪，朕提議先放下刀劍。","朕更願把金銀花在船隊與學校，而非軍餉。"],"accept":["朕接受，願此約如婚約般牢固，朕一向守信。","好，卡斯提亞的女王說出的話，從不收回。"],"reject":["朕不能接受，你的條件會讓朕的子民蒙羞。","請回去吧，這份和約還配不上卡斯提亞。"],"rebuff":["你拒絕了？那朕只好用別的方式說服你。","可惜，朕本以為你懂得什麼叫深思熟慮。"],"betray":["情勢已變，朕收回昨日的承諾，願上天寬恕。","為了王國的未來，朕不得不撕毀這紙和約。"],"truceEnd":["休戰期滿，朕的騎士們已在教堂前宣誓。","和平的鐘聲停了，接下來是戰鼓。"],"attacking":["卡斯提亞的大軍已出發，朕親自坐鎮營帳。","朕的軍隊帶著十字旗與大砲，正向你的城池前進。"],"attacked":["城牆可以倒，但朕不會離開這座城的子民。","朕聽見砲聲了……卡斯提亞的女王不會逃。"],"defeated":["朕的王國落幕了，但朕的船隊已把世界變得更大。","請善待朕的子民……這是朕最後的請求。"],"victory":["勝利歸於卡斯提亞，也歸於指引朕的上天。","今日的勝利，朕會刻在格拉納達的城牆上。"],"allyAccept":["朕接受結盟，就像卡斯提亞與亞拉岡的聯合。","好，讓我們的旗幟並肩，共同開拓新的海洋。"],"allyReject":["朕的盟友只有斐迪南與上天，恕難再添一位。","卡斯提亞不與立場不明的人結盟，請回。"],"greetFriendly":["願上主賜你平安，卡斯提亞的大門為誠摯的朋友敞開。","朕與斐迪南國王同閱來信，兩國情誼，當如此長久。"],"greetCold":["朕正忙於統一王國的大業，無暇寒暄，有事直言。","問候之言朕收到了，但卡斯提亞的信任，須以行動換取。"],"threatDefy":["朕連格拉納達都能收復，豈會被你的威嚇動搖？","卡斯提亞的旗幟從不因恫嚇而降下，你儘管試試。"],"threatYield":["朕以王國安危為重，此番暫且退讓，望你莫再相逼。","上主教導朕謹慎，這一回朕選擇忍耐，而非刀兵。"],"tributePay":["朕以{gold}金幣換取子民安寧，願上主見證你的承諾。","這{gold}金幣朕給了，但別忘記，卡斯提亞終將更強。"],"tributeRefuse":["朕的金幣要用來遠航探索與治理王國，一枚也不給你。","女王不納貢。卡斯提亞只向上主俯首，不向你低頭。"],"giftThanks":["此禮朕欣然收下，願以卡斯提亞的友誼回報。","多謝厚禮，朕會為你祈禱，願兩國永享和睦。"],"intel":["朕的信使回報：{wars}正在交戰，{peace}則安居樂業。","據修士與商人所言，{wars}兵禍連綿，{peace}和平無事。"]}},{"name":"阿方索十三世","title":"西班牙國王","era":"1886～1931年在位（1902年親政）","tone":"貴族式優雅、帶點憂鬱與自嘲，關心王國在列強之間的處境，外交口吻中透著疲憊的驕傲","portrait":"es-historical-age3","lines":{"intro":["朕是阿方索十三世，一出生便是國王的人。","西班牙不再是日不落帝國，但仍是有尊嚴的王國。"],"contact":["你的人看見馬德里了？王宮的燈仍亮著，請轉告。","這座城見過帝國的黃昏，也正等待新的黎明。"],"war":["朕已忍耐夠久，西班牙的軍隊將重新證明自己。","王國失去過太多，這一次朕不會再退讓。"],"warReply":["向西班牙宣戰？朕已見過太多強權來了又走。","好吧，就讓世界看看老王國還有沒有骨氣。"],"peace":["朕見過一八九八年的代價，不願子民再嘗一次。","兩國的年輕人不該死在無謂的戰場上，停戰吧。"],"accept":["朕接受，王室的名譽會為這份和約作保。","很好，馬德里的樂隊今晚可以奏和平的曲子了。"],"reject":["條件太苛，朕若答應，便無顏面對西班牙人。","請回去修改條款，王國雖弱，尊嚴不賣。"],"rebuff":["你拒絕了？可惜，朕原以為你比列強更明理。","無妨，西班牙人習慣被低估。"],"betray":["時局逼人，朕不得不收回承諾，請諒解。","和約已無法保護朕的子民，朕只好撕毀它。"],"truceEnd":["休戰到期，將軍們又開始在地圖前踱步。","和平的假期結束，該回到現實了。"],"attacking":["西班牙的軍隊已經出發，朕在王宮為他們祈禱。","這是老王國的一擊，請務必正視。"],"attacked":["王宮的窗被砲聲震碎……但王室不會先走。","馬德里在燃燒，朕仍站在陽台上。"],"defeated":["朕失去了王冠，願西班牙人民自己找到出路。","一個王朝結束了，但西班牙會繼續存在。"],"victory":["老王國贏了，這回沒人能說西班牙已經過時。","勝利屬於西班牙的士兵，朕只是替他們鼓掌。"],"allyAccept":["朕接受結盟，西班牙需要朋友勝過需要殖民地。","好，讓馬德里與你的都城互派使節，長久往來。"],"allyReject":["西班牙已學會不輕易選邊，恕朕保持中立。","朕不想再把王國押在別人的賭桌上。"],"greetFriendly":["馬德里的午後陽光正好，朕很高興收到這樣溫暖的來信。","在列強環伺的年代，能有一位誠摯的朋友，朕深感欣慰。"],"greetCold":["朕收到了。不過近來王國事務繁多，恕朕無心閒談。","問候很體面，可惜這年頭，體面的話語朕聽得太多了。"],"threatDefy":["西班牙雖不復當年，但王室的尊嚴，朕絕不容人踐踏。","朕見過更大的風浪，你的威嚇，不過是茶杯裡的風暴。"],"threatYield":["朕的王國經不起再一場戰爭，這次就照你的意思吧。","唉，一個疲憊的國王能做的，也只有退讓與嘆息了。"],"tributePay":["{gold}金幣就當是王室的體面開銷，朕苦笑著付了。","朕付出{gold}金幣，只求王國不再捲入無謂的紛爭。"],"tributeRefuse":["王室的金庫已不寬裕，朕連一枚金幣也不會奉上。","西班牙可以疲憊，但不會向人納貢，朕婉拒了。"],"giftThanks":["朕感謝這份禮物，它讓灰暗的王宮多了些許亮色。","難得的雅意，朕會親筆回信致謝，這是紳士的禮節。"],"intel":["朕的大使館傳來消息：{wars}正陷於戰事，{peace}則保持安寧。","據外交電報所知，{wars}戰雲密布，{peace}尚且和平無虞。"]}}],"Netherlands":[{"name":"尤利烏斯·基維利斯","title":"巴達維亞人首領","era":"西元69～70年（巴達維亞起義）","tone":"剽悍直率、以河與沼澤為傲的部族戰士，自稱「我」，對羅馬式的城池與軍團帶著警惕","portrait":"nl-historical-age0","lines":{"intro":["我是巴達維亞首領基維利斯，萊茵河的沼澤是我們的家。","我們替羅馬人打過仗，如今只為自己的族人而戰。"],"contact":["你的人踏進我的河灘了，這裡的每一條水道我都認得。","木牆與泥沼守著我們的村落，不必羨慕石造的城。"],"war":["我曾發誓，不勝利就不剪髮。今日我向你舉起長矛。","八個大隊的巴達維亞勇士已經渡河，你準備好了嗎？"],"warReply":["羅馬軍團都沒能讓我低頭，你的宣戰嚇不倒巴達維亞人。","來吧，沼澤會吞掉你的騎兵，河水會替我們作戰。"],"peace":["河的兩岸各自安居，這樣的日子對兩族都好。","我不想再讓族人的血流進萊茵河，我們談談吧。"],"accept":["好，巴達維亞人說話算話，這河上不會再有刀兵。","以河神之名起誓，你我從此各守一岸。"],"reject":["話說得好聽，可我看見你的斥候還在林子裡。","巴達維亞人不會在刀還架在脖子上時談和。"],"rebuff":["你拒絕了？那就讓沼澤替我們決定吧。","我伸出的手你不接，往後別怪我拔矛。"],"betray":["盟約是對朋友守的，你已經不是我的朋友了。","河會改道，誓言也會。今日我收回我的承諾。"],"truceEnd":["休戰的日子到頭了，族人們已經重新磨好矛尖。","河水漲過了記號，約定的時限也過了。"],"attacking":["巴達維亞的船隊順流而下，目標是你的城。","我們泅水渡河的本事，今天讓你親眼看看。"],"attacked":["村落燒了，木牆倒了，但沼澤裡還有我的人。","你打到我的家門口了，可巴達維亞人從不跪著求饒。"],"defeated":["河水會記得我們的名字，即使史書忘了。","我走進霧裡去了，別找我，巴達維亞不會真的滅亡。"],"victory":["萊茵河的兒女贏了，今日我終於可以剪去長髮。","告訴你的人，巴達維亞人只當盟友，不當奴僕。"],"allyAccept":["好，我們並肩作戰，你的敵人就是我的敵人。","巴達維亞人的盾牌，從今天起也替你擋箭。"],"allyReject":["我替別人打過太多仗了，這次只為自己的族人。","結盟？我還不知道你的話值不值一枚矛頭。"],"greetFriendly":["你越過萊茵河來問候我？好，河水為證，我們是朋友。","巴達維亞人記得朋友的臉，來，坐到火堆旁。"],"greetCold":["羅馬人也曾這樣笑著問候我，我學會了先看你的手。","沼澤不歡迎陌生人，說完你的事就走吧。"],"threatDefy":["來啊，軍團在沼澤裡陷過多少次，你不知道嗎？","我連羅馬的軍團都敢圍攻，還怕你的恐嚇？"],"threatYield":["族人已經打得太累了，這回我退一步，記住只此一次。","好，我讓開河口，但沼澤永遠是巴達維亞人的。"],"tributePay":["{gold}金幣拿去，我不想讓族人再嘗一次戰火。","這{gold}金幣是河神的份，我先借給你，記得還。"],"tributeRefuse":["羅馬向我們徵兵徵稅，我們才起義，你還想學他們？","一枚金幣也沒有，沼澤裡的人只向河水低頭。"],"giftThanks":["這禮物我收下了，今晚火堆旁會多講你一段故事。","好東西！我用萊茵河的鮭魚回敬你，別嫌腥。"],"intel":["斥候說{wars}正在交戰，{peace}相安無事，河邊風聲瞞不過我。","商旅在河口說，{wars}兵戈不休，{peace}倒是平靜。"]}},{"name":"弗洛里斯五世","title":"荷蘭伯爵","era":"1256～1296年在位","tone":"親民又精明的中世紀諸侯，愛談堤防與市集，自稱「本爵」，對貴族陰謀略帶自嘲","portrait":"nl-historical-age1","lines":{"intro":["本爵弗洛里斯，荷蘭伯爵，這片與海爭來的低地由本爵治理。","百姓稱本爵為農夫之神，貴族們可就沒這麼喜歡本爵了。"],"contact":["你的人看見那些堤防了嗎？荷蘭的每一畝田都是人力築出來的。","歡迎來到荷蘭伯國，市集開放，但別打城堡的主意。"],"war":["本爵能與海爭地，自然也能與你爭土。荷蘭出兵了。","紅獅旗已經升起，農夫們放下鋤頭拿起長矛了。"],"warReply":["你要打？先算算要過幾道水閘才能到本爵城下。","弗里斯蘭人都沒能奈何本爵，你憑什麼？"],"peace":["打仗的錢不如拿去築堤，本爵提議休兵。","本爵的百姓要的是好收成，不是戰功。停戰吧。"],"accept":["成交。本爵在乎的是市集裡的秤，不是戰場上的劍。","好，讓商船重新開航，這才是荷蘭該有的樣子。"],"reject":["條件太差了，就連弗里斯蘭人也不敢向本爵開這種價。","你的和平聞起來像陷阱，本爵在朝廷裡見多了。"],"rebuff":["不接受？可惜。本爵的堤防等得起，你的糧倉呢？","那就繼續吧，荷蘭的農夫比你想的更能打。"],"betray":["英格蘭與法蘭西之間本爵都能換邊，何況是你。","盟約是羊皮紙寫的，而羊皮紙，本爵多得很。"],"truceEnd":["休戰到期了，本爵的堤修好了，接下來輪到你的城牆。","潮水退了又漲，休戰的約定也到頭了。"],"attacking":["荷蘭的騎士與農夫一起出發了，目標是你的城門。","本爵親自領軍，紅獅旗所指之處，便是戰場。"],"attacked":["城牆裂了，可堤防還在。荷蘭人習慣在水裡求生。","你打得比貴族的陰謀還狠，本爵倒是佩服。"],"defeated":["本爵防得了海，防得了敵人，卻總防不了背後的刀。","替本爵告訴農夫們，堤防要繼續修，別停。"],"victory":["贏了。回去告訴你的君主，低地的伯爵不好惹。","這一仗農夫們打得好，本爵要給他們減一年的稅。"],"allyAccept":["好，荷蘭與你結盟，商路共享，敵人共擋。","本爵的紅獅與你的旗幟並列，這買賣划算。"],"allyReject":["結盟要看價碼，你出的還不夠本爵動心。","本爵夾在英法之間已經夠忙了，不缺一個新盟友。"],"greetFriendly":["本爵正在巡堤防，你的信讓路途愉快多了。","歡迎歡迎，改天來多德雷赫特的市集逛逛吧。"],"greetCold":["本爵近來忙著應付貴族，恕沒空寒暄。","客套話堤防是聽不進去的，有事直說。"],"threatDefy":["本爵連海潮都擋得住，還擋不住你這幾句話？","荷蘭的市民與農夫都站在本爵這邊，你儘管來。"],"threatYield":["唉，本爵身邊的貴族已經夠難纏了，就依你這回。","好吧，堤防修一半不能停工，本爵先讓一步。"],"tributePay":["{gold}金幣交給你，這可是市集半季的稅收啊。","本爵付你{gold}金幣，只求別耽誤堤防的工期。"],"tributeRefuse":["錢都拿去修堤防了，本爵的金庫比沼澤還空。","農夫稱本爵是他們的靠山，本爵怎能拿他們的錢送人。"],"giftThanks":["好禮！本爵回贈一輪上等乳酪，市集裡最好的。","多謝了，比起貴族的假笑，你的禮物實在多了。"],"intel":["市集上的商人都在說，{wars}正打得熱鬧，{peace}相安無事。","本爵聽堤防工人閒聊：{wars}兵戎相見，{peace}倒是太平。"]}},{"name":"沉默者威廉","title":"奧蘭治親王・荷蘭執政","era":"1533～1584年（1572年起任荷蘭執政）","tone":"沉穩寡言、堅忍不拔，句句離不開自由與信念，自稱「本王」，語氣莊重但不張揚","portrait":"nl-historical-age2","lines":{"intro":["本王是奧蘭治親王威廉，人稱沉默者。低地七省由本王守護。","我們是與海爭地的人，也是不肯向暴政低頭的人。"],"contact":["你看見的是七省聯合的城池，風車與運河都是自由的證明。","這裡容得下各種信仰的人，只要你的人守規矩。"],"war":["本王向來寡言，但劍已出鞘，就不會輕易收回。","我必維護。這是本王的誓言，今日以刀兵向你證明。"],"warReply":["西班牙的大軍都沒能壓垮低地，你的宣戰亦然。","本王不必有勝算才應戰。來吧，海上乞丐已備妥船隻。"],"peace":["戰爭已讓太多人流離失所，本王願意先放下劍。","讓商船代替戰船往來，這對你我兩國都是好事。"],"accept":["本王接受。願此約如烏特勒支的盟誓一般牢固。","好，讓沉默的人也難得說一句：這是好消息。"],"reject":["本王見過太多以和約為名的陷阱，恕不接受。","若停戰意味著低頭，那本王寧可繼續作戰。"],"rebuff":["你拒絕了。本王不必成功才堅持，這條路走慣了。","也罷。低地的人早已學會在沒有希望時繼續前行。"],"betray":["本王曾對君王效忠，直到他背棄了人民。今日亦然。","當君主不守護百姓，臣民便有權另作打算。此約作廢。"],"truceEnd":["休戰的期限已滿，本王的沉默也到此為止。","潮水不會永遠退去，戰事也是。低地重新備戰。"],"attacking":["七省的軍隊與海上乞丐已經出發，目標是你的城。","本王不擅言辭，就讓橙色的旗幟替本王說話。"],"attacked":["城牆將傾，那就掘開堤防。萊登的人曾這樣活下來。","你打到本王的門前了，但低地的人不會為此絕望。"],"defeated":["上帝啊，憐憫我的靈魂，也憐憫這可憐的人民。","本王倒下了，但自由的種子已經撒在低地的土裡。"],"victory":["這一仗是低地人民贏的，本王不過是替他們掌旗。","回去告訴你的君主：不必有希望才去做，我們證明了。"],"allyAccept":["好。低地七省需要朋友，本王也珍惜真正的盟友。","橙色與你的旗幟並肩，願此盟比烏特勒支之約更長久。"],"allyReject":["本王曾被盟友出賣過，這次請恕本王慎重。","低地的自由不能託付給尚未證明誠意的人。"],"greetFriendly":["本王讀了你的信，在這艱難的年月，善意格外珍貴。","願自由與你同在，本王記住了你的問候。"],"greetCold":["本王寡言，非為失禮，只是心思都在尼德蘭的存亡。","客套話留給西班牙的宮廷吧，本王只聽實話。"],"threatDefy":["本王的信條是『我必維護』，威嚇動搖不了它。","不必成功才能堅持，本王早已學會這一課。"],"threatYield":["為了信念，本王可以忍一時之辱，此事就依你吧。","尼德蘭經不起再一個敵人，本王暫且退讓。"],"tributePay":["這{gold}金幣，本王本想用來養海上乞丐的船隊。","{gold}金幣送去，願這筆錢換來的是安寧而非屈辱。"],"tributeRefuse":["本王已為自由變賣家產，一枚金幣也不會交給威嚇者。","尼德蘭寧可掘開堤防淹沒田地，也不向勒索低頭。"],"giftThanks":["本王謝過，這份情誼，本王與尼德蘭都會記得。","困頓之中收到厚禮，本王沉默，心中卻不平靜。"],"intel":["密使來報：{wars}正在交戰，{peace}維持和平，本王一一記下。","本王聽聞{wars}烽火未息，而{peace}尚得安寧。"]}},{"name":"威廉明娜","title":"荷蘭女王","era":"1890～1948年在位（遊戲時代取1890～1914年）","tone":"年輕卻堅毅的立憲女王，重視中立與國家尊嚴，自稱「朕」，語氣端莊帶一點鋒芒","portrait":"nl-historical-age3","lines":{"intro":["朕是荷蘭女王威廉明娜，一個小國，卻有大海一般的志氣。","荷蘭以商船與堤防立國，朕不求爭霸，只求尊嚴。"],"contact":["你的人看到的是阿姆斯特丹的港口，全世界的貨物都經過這裡。","歡迎。荷蘭是開放的國家，但請記得，開放不等於軟弱。"],"war":["朕向來主張中立，但你逼得荷蘭不得不亮出劍來。","我必維護，這是奧蘭治家族的箴言。今日朕以行動實踐。"],"warReply":["你的士兵再高大，荷蘭開閘放水，水深也足以淹過頭頂。","小國不等於弱國，這句話朕會在戰場上讓你明白。"],"peace":["海牙曾為世界和平開過會議，朕願意先向你伸出手。","戰爭讓商船停航、田地荒廢，荷蘭寧可談判。"],"accept":["朕接受。願條約如荷蘭的堤防一般，經得起風浪。","很好，讓鬱金香重新在邊境的田裡開花吧。"],"reject":["條件有損荷蘭的尊嚴，朕不能接受這樣的和約。","朕年紀雖輕，卻分得清和平與屈服的差別。"],"rebuff":["你拒絕了。很好，荷蘭人習慣與風浪長期周旋。","朕已盡了君主的本分，接下來由軍隊說話。"],"betray":["當條約成了束縛荷蘭的繩索，朕只好親手解開它。","朕為國家的利益負責，不為一紙文件負責。"],"truceEnd":["休戰期滿。荷蘭的商船已歸港，軍艦則出港了。","約定的期限到了，朕不會假裝沒有看見日曆。"],"attacking":["荷蘭的陸軍與艦隊已經出動，目標是你的都城。","朕親自為將士送行，橙色的旗幟正朝你而去。"],"attacked":["都城危急，但朕已下令開閘。荷蘭的最後防線是水。","你打到宮門前了，但女王不會離開她的人民。"],"defeated":["荷蘭曾從海裡奪回土地，總有一天也會奪回自由。","朕輸了這一局，但奧蘭治的橙色不會褪去。"],"victory":["荷蘭勝了。回去告訴你的君主，小國也有堤防般的意志。","戰事結束，朕會讓商船先於軍艦回到海上。"],"allyAccept":["朕答應結盟。願兩國的旗幟一同在海風中飄揚。","荷蘭珍惜可靠的朋友，往後商路與航道對你開放。"],"allyReject":["荷蘭的中立是立國之本，朕暫時不能與你結盟。","朕欣賞你的誠意，但荷蘭不輕易捲入他人的紛爭。"],"greetFriendly":["朕收到你的問候，荷蘭雖守中立，卻不吝於友誼。","海牙今日陽光正好，朕的心情也因你的信更好了。"],"greetCold":["朕已閱，禮節周到，誠意幾分，朕自會衡量。","荷蘭與各國一視同仁，你的問候朕不會特別看待。"],"threatDefy":["荷蘭是小國，但小國的尊嚴一寸都不會讓。","朕不怕威嚇，海牙的和平宮就是荷蘭給世界的回答。"],"threatYield":["朕不願讓荷蘭捲入戰火，此事暫且依你。","為了中立與百姓安寧，朕忍下這一回。"],"tributePay":["{gold}金幣由國庫撥付，朕以女王之名記下這筆帳。","朕付你{gold}金幣，換荷蘭的商船安然出港。"],"tributeRefuse":["荷蘭的金幣屬於荷蘭人民，朕一枚也不會送給威嚇者。","朕的國會不會批准這筆錢，朕也不打算為此開口。"],"giftThanks":["朕謝過你的厚禮，荷蘭會以鬱金香與友誼回敬。","禮物已收，朕命人陳列於宮中，以誌兩國情誼。"],"intel":["外交部呈報：{wars}正在交戰，{peace}維持和平，荷蘭一概中立。","據海牙使節所聞，{wars}烽火連天，{peace}則相安無事。"]}}],"Switzerland":[{"name":"迪維科","title":"赫爾維蒂首領","era":"約前107～前58年活躍","tone":"驕傲、直率、重視誓言與族人，對羅馬心存戒備，說話像山裡的老獵人。","portrait":"ch-historical-age0","lines":{"intro":["我是赫爾維蒂的迪維科，山與湖之間的族人由我領路。","羅馬人的軍旗曾在我面前折斷，你的旗幟呢？"],"contact":["你的探子看見我們的木牆了，山谷裡的炊煙就是我們的家。","高牆之內是我的族人，來者若是客人，便有麥酒與火。"],"war":["你踏進了我族的牧地，赫爾維蒂人不會退讓一步。","拿起長矛吧，我族以勇武取勝，從不靠詭計。"],"warReply":["你要與我為敵？連羅馬的軍團都曾在我面前低頭。","好，讓山谷記住你的名字，如同記住那些敗走的人。"],"peace":["刀劍已太沉重，讓我們在橡樹下立誓停戰吧。","我族要的是牧地與活路，不是無盡的仇恨。"],"accept":["好，我以祖先之名起誓，赫爾維蒂人守諾如守山。","誓言已立，你的牛群可以安心在邊界吃草了。"],"reject":["現在才談和？我的戰士還沒把你的營帳趕出山谷。","赫爾維蒂人只在勝利後談和，不是之前。"],"rebuff":["你拒絕橡樹下的誓言？那就由長矛替我們說話。","我伸出的手被推開了，山裡的風會記得這一天。"],"betray":["誓言隨風散了，我族的牧地容不下你的腳印。","別怪我，你的城離我的山谷太近了。"],"truceEnd":["休戰的日子數完了，我的戰士重新磨亮了矛尖。","橡樹下的誓言到期了，往後各憑本事。"],"attacking":["赫爾維蒂的戰士已越過山口，你聽見號角了嗎？","全族的車隊都在我身後，這一次我們不會回頭。"],"attacked":["木牆倒了……我的族人正往山上撤，別追。","你打進了我的家園，但山不是你能征服的。"],"defeated":["山會記得我們……赫爾維蒂人不曾跪下。","我倒下了，但這片山谷永遠記得赫爾維蒂。"],"victory":["山谷的風又吹向我們了，這片土地屬於我的族人。","告訴你的後人，赫爾維蒂人是怎麼打仗的。"],"allyAccept":["好，你我兩族並肩，任何軍團都要三思。","來，同飲一杯麥酒，從今天起你的敵人就是我的敵人。"],"allyReject":["赫爾維蒂人習慣自己守山，不需要別人的矛。","你的誠意我收下，但同盟的事，再等等吧。"],"greetFriendly":["山風把你的信送來了，我以獵人的手向你致意。","火堆旁有你的位子，赫爾維蒂人記得朋友。"],"greetCold":["我不認識你，山裡的人不對陌生人低頭。","信收到了。話少一點，山谷的風會替你說。"],"threatDefy":["我族從祖先學的是靠勇氣作戰，不靠詭計。","羅馬的軍團曾在我面前低頭，你算什麼？"],"threatYield":["族人剛翻過雪山，疲憊不堪，我暫且退讓。","為了族人的性命，我這次聽你的，但誓言記著。"],"tributePay":["我把牛群換成{gold}金幣給你，別再逼我的族人。","拿去，{gold}金幣，山裡人重諾，說給就給。"],"tributeRefuse":["赫爾維蒂人不納貢，連羅馬也拿不到一枚。","我的牛和鹽是族人的命，一粒也不給外人。"],"giftThanks":["好東西！我會在火堆旁向族人說起你的名字。","山裡人不忘恩，這份禮我記在心上。"],"intel":["獵人看見：{wars}在打仗，{peace}講和了。","山谷傳話：{wars}正動刀兵，{peace}已握手。"]}},{"name":"威廉·泰爾","title":"烏里的神射手（傳說人物）","era":"傳說約1291～1307年","tone":"寡言、倔強、熱愛自由，討厭權貴擺架子，講話像山裡的獵人一樣直。","portrait":"ch-historical-age1","lines":{"intro":["我是烏里的泰爾，一把弩弓、一雙腿，走遍這些山。","我不喜歡向誰低頭，也不打算向你的帽子鞠躬。"],"contact":["你的人走到湖邊了？那裡是我們獵人的路，別亂闖。","看見山坡上的木屋了嗎？那就是我們全部的家業。"],"war":["你想當新的總督嗎？山民早就受夠了這種人。","我的弩箭從不落空，這一次瞄準的不是蘋果。"],"warReply":["你以為山民好欺負？呂特利的誓言可不是說著玩的。","來吧，這裡每一道山口，都有人替我守著。"],"peace":["打夠了吧。山民只想種田放牧，不想再看見旗子。","放下弓吧，我也想回家陪孩子，不想再上戰場。"],"accept":["好，一言為定。山民不會說漂亮話，但說到做到。","握個手吧，往後我的箭只射山上的野物。"],"reject":["現在說和？你的帽子還插在市集廣場上呢。","我不信一個還騎在山民頭上的人說的和平。"],"rebuff":["你不要和平？好，山民有的是耐心和箭。","我伸出手，你卻要拳頭。那就等山風替你冷靜。"],"betray":["抱歉，我看見你在山口築了塔，山民不能再等了。","誓言我記得，但你的兵在我的田裡，我只能拿起弓。"],"truceEnd":["說好的日子到了，往後見面，各自小心。","休戰結束，我把弩弓從牆上取下來了。"],"attacking":["三個森林邦的漢子都下山了，你聽見號角了吧。","山民不擅長列隊，但每個人都知道往哪射。"],"attacked":["村子被圍了……山民退進山裡，你追不上的。","你燒得了木屋，燒不了山。我們會回來。"],"defeated":["我的箭射完了……但總會有人再拿起弓。","告訴我的孩子，他父親沒有向任何人低頭。"],"victory":["山民贏了。去吧，回你的平原，別再來插旗子。","自由是山裡的空氣，你們拿不走，我們也不賣。"],"allyAccept":["好，像呂特利草地上那樣，我們一起發誓。","山民不多，但守約的人才是最可靠的盟友。"],"allyReject":["抱歉，山民只跟山民結盟，這是老規矩。","我不懂宮廷的事，也不想被誰的旗子綁住。"],"greetFriendly":["信看了。烏里的山門為朋友敞開，來吧。","難得有人好好說話，我請你喝一杯山泉。"],"greetCold":["我是獵人，不愛客套。有事直說。","帽子我不脫，話也不多。你請便。"],"threatDefy":["蓋斯勒也這樣嚇過我，他的下場你知道。","我的弩箭從不射偏，你最好別逼我拉弓。"],"threatYield":["我只是一個獵人，護得了村子，護不了全國。","好吧，這回我讓。但山民的忍耐有限度。"],"tributePay":["這{gold}金幣是全村湊的，你拿走，別再來。","{gold}金幣，給你。獵人的弩箭我留著。"],"tributeRefuse":["我連總督的帽子都不拜，憑什麼給你錢？","山民的錢是汗水換的，一枚也不給。"],"giftThanks":["收下了。獵人不會說漂亮話，但記得恩情。","謝了。這份禮我會帶回阿爾特多夫分給鄰居。"],"intel":["山口的商旅說：{wars}在打仗，{peace}講和了。","我打聽到：{wars}動了刀兵，{peace}放下了。"]}},{"name":"慈運理","title":"蘇黎世宗教改革領袖","era":"1519～1531年主導蘇黎世改革","tone":"誠懇、有學者氣息、愛引經據典，對傭兵買賣與強權深惡痛絕，勝利時仍謙卑。","portrait":"ch-historical-age2","lines":{"intro":["我是蘇黎世的慈運理，我的講壇只講聖經，不講人的話。","願上帝的話語在你的國土也能被聽見。"],"contact":["你的人到了利馬特河畔，這裡的鐘聲為所有人而響。","蘇黎世的城門白天開著，來聽道的人，我一律歡迎。"],"war":["你阻擋真理傳到你的百姓耳中，蘇黎世不能坐視。","我本是傳道人，但若有人以刀劍封住聖經，我也拿起劍。"],"warReply":["你向蘇黎世宣戰？那就讓上帝審判誰站在真理這邊。","我不怕戰爭，我怕的是百姓為別人的野心白白送命。"],"peace":["夠了，讓我們坐下來，用聖經而不是刀劍辯論。","我提議停戰，農民該回田裡，孩子該回學校。"],"accept":["感謝上帝，和平總比勝利更接近祂的心意。","好，蘇黎世守約。你若要辯論，講壇隨時為你敞開。"],"reject":["你的和平只是想讓我閉嘴，真理不能拿來交換。","除非你讓百姓自由讀聖經，否則我們沒什麼好談。"],"rebuff":["你拒絕了和平，願上帝憐憫你的百姓。","我伸出橄欖枝，你回以刀劍，這筆帳上天會記。"],"betray":["我不得不撕毀約定，你在暗中收買了我們的年輕人。","為了蘇黎世的良心，這份停戰我不能再守。"],"truceEnd":["休戰期滿，願下一次相見是在辯論桌上。","約定的日子過了，蘇黎世會重新關上城門。"],"attacking":["蘇黎世的軍旗出城了，我隨軍同行，一如既往。","我們不是為掠奪而來，是為了讓真理不再被封鎖。"],"attacked":["城牆快守不住了……但講壇上的話，你拆不掉。","蘇黎世在燃燒，我仍會站在會眾前面。"],"defeated":["身體你們奪得走，靈魂卻奪不走。","願蘇黎世的講壇有人接續，這才是我在意的。"],"victory":["勝利不是我的，是上帝的。回去吧，善待你的百姓。","蘇黎世不要你的土地，只要你的百姓能自由讀經。"],"allyAccept":["好，讓我們的城市互為兄弟，一同守護聖經的真理。","結盟可以，但我不要你的錢，只要你的誠實。"],"allyReject":["抱歉，蘇黎世不與買賣傭兵的君主結盟。","我們的路不同，我祝福你，但無法與你同行。"],"greetFriendly":["願平安與你同在。蘇黎世的門為誠實的朋友而開。","收到你的信，如同收到一封好消息，感謝上帝。"],"greetCold":["信已讀。言語當簡潔，是就說是，不是就說不是。","我埋首經卷，無暇客套。請直陳來意。"],"threatDefy":["我不畏強權，只畏上帝。你的威嚇動搖不了蘇黎世。","經上說，主是幫助我的，我必不懼怕。你請回。"],"threatYield":["為免蘇黎世百姓受苦，我暫且忍讓，願上帝鑒察。","我們兵少，我不願拿百姓的性命賭氣。這回讓你。"],"tributePay":["這{gold}金幣是百姓血汗，願你善用，勿拿去買傭兵。","{gold}金幣送上。與其讓百姓受苦，不如破財。"],"tributeRefuse":["蘇黎世已廢除傭兵買賣，更不會向外邦納貢。","凡以錢財買和平者，終將失去和平。恕難從命。"],"giftThanks":["感謝。我會將這份禮分給城裡的窮人與學堂。","施比受更為有福。願上帝也賜福於你。"],"intel":["據各邦通信，{wars}正在交戰，{peace}已締約。","願主憐憫：{wars}兵戎相見，{peace}握手言和。"]}},{"name":"杜富爾","title":"瑞士聯邦將軍","era":"1847年統帥聯邦軍；1863年紅十字首任主席","tone":"冷靜克制、有人道精神、講求效率與秩序，以少犧牲為榮，對敵人也保持禮節。","portrait":"ch-historical-age3","lines":{"intro":["本人杜富爾，瑞士聯邦將軍。我畫地圖，也築橋樑。","瑞士無意擴張，但也絕不容許他人踏入阿爾卑斯。"],"contact":["你的人到了日內瓦湖畔？歡迎，這裡的城門不設防。","請轉告貴國，瑞士的邊界靠中立守護，不靠砲台。"],"war":["本人不願開戰，但你的軍隊逼近了邊境，瑞士必須應戰。","聯邦議會已授權，我只求速戰速決，少流一滴血。"],"warReply":["你選擇了戰爭。本人會盡力讓它短暫而有節制。","瑞士人保衛家園時，從來不需要別人教。"],"peace":["夠了。讓傷者得到照顧，讓士兵回家，我們談停戰。","勝負之外還有人道。本人提議停戰，並交換戰俘。"],"accept":["同意。從此刻起，你的傷兵與我的傷兵，一視同仁。","好，聯邦接受。願這份和約比阿爾卑斯的岩石更久。"],"reject":["你的停戰條件要瑞士割讓山口，本人無法接受。","停戰可以談，但不是在你的軍隊還踩著我們的田地時。"],"rebuff":["你拒絕了。很遺憾，但本人仍會照顧你的傷兵。","和平的門我留著，你什麼時候想進來都可以。"],"betray":["本人深感遺憾，但你在邊境的調動已違反了約定。","聯邦議會已決議，停戰不再有效。這不是我的本意。"],"truceEnd":["休戰期滿。本人希望我們不必再拿起武器。","約定到期了，瑞士的哨兵會回到山口，僅此而已。"],"attacking":["聯邦軍出發了。命令很簡單：擊退敵軍，善待所有人。","我的士兵不會劫掠，不會傷害放下武器的人。"],"attacked":["伯恩快守不住了……但瑞士不會因一座城而投降。","本人已下令撤離平民，你要打，就對著軍人打。"],"defeated":["瑞士倒下了……請善待我的百姓，那是我唯一的請求。","我畫的地圖還在，山還在，瑞士總有一天會回來。"],"victory":["戰爭結束了。從今天起，忘記你們曾是我們的敵人。","瑞士贏了，但不會要你一寸土地，只要邊界安寧。"],"allyAccept":["好，瑞士願與你並肩，但請記得，我們只守不攻。","結盟可以，條件只有一個：戰場上傷者不分敵我。"],"allyReject":["抱歉，瑞士的中立不容許本人簽下軍事同盟。","我們可以是朋友，但不能是盟友，這是瑞士的立場。"],"greetFriendly":["來信收悉。秩序與善意，是本人最樂見的組合。","感謝問候。願貴我雙方以禮相待，以理相交。"],"greetCold":["信已閱。本人公務繁忙，請直陳要事。","以禮相待是本人原則，但交情須另計。"],"threatDefy":["本人以最少傷亡打贏內戰，不會被威嚇擊倒。","聯邦軍紀律嚴明，秩序即力量。請收回你的話。"],"threatYield":["為避免無謂傷亡，本人選擇退讓。這不是怯懦。","軍人的榮譽在於保全生命，我暫且讓步。"],"tributePay":["{gold}金幣如數奉上，換取和平，本人認為值得。","與其兵戎相見，不如付出{gold}金幣。請善待傷者。"],"tributeRefuse":["聯邦不向任何人納貢，本人亦不會破此先例。","貢品免談。若你有傷患需要救治，我倒願意幫忙。"],"giftThanks":["厚禮收悉。本人將轉交救護工作，以慰傷者。","感謝。在戰場之外仍有善意，是文明的證明。"],"intel":["依情報：{wars}已開戰，{peace}已締約停戰。","戰況如下：{wars}交火中，{peace}已休戰。"]}}],"Sweden":[{"name":"斯維亞族長","title":"族長","era":"鐵器時代（通稱）","tone":"沉穩寡言、敬畏諸神與冬天，重視民會共議與部族榮譽，說話簡短有力，待客真誠但絕不示弱。","portrait":"se-historical-age0","lines":{"intro":["我是斯維亞人的族長，湖與森林是我們的家。","冬天很長，遠方來客，先坐到火堆旁吧。"],"contact":["你的人踏進我們的松林，可是帶著善意來的？","湖岸的長屋是吾族的家，看看可以，別動我們的船。"],"war":["你的人越過界石，長船已經下水，我來討公道。","民會已經決定，斯維亞的矛要指向你了。"],"warReply":["你選在冬天前開戰？很好，冰雪會替我們作戰。","既然你要打，吾族的盾牆就在這裡等你。"],"peace":["戰士的血流夠了，我們用琥珀換和平吧。","諸神不喜歡永無止境的仇殺，來，一起立誓休戰。"],"accept":["好，我以祖先之名起誓，斯維亞人不再拔劍。","把矛插進地裡，今晚你是我火堆旁的客人。"],"reject":["上次的誓言你沒守住，這次的話我不會再信。","冬天還沒到，斯維亞人還打得動，不停戰。"],"rebuff":["你不肯？那就讓湖水見證誰先撐不住。","我伸出的手被拍開了，下次伸出的會是矛。"],"betray":["情勢變了，誓言隨風雪去吧，長船再次出發。","對不起祖先，但吾族要活下去，休戰到此為止。"],"truceEnd":["休戰的日子數完了，各自拿回自己的矛吧。","冰雪融了，船也修好了，接下來憑本事。"],"attacking":["號角響了，斯維亞的長船正划向你的岸邊。","全族戰士已經集結，你的城牆擋不住這股風雪。"],"attacked":["長屋在燒，但斯維亞人還站著，來吧。","族人退進森林了，我留在這裡守最後的火堆。"],"defeated":["把我的名字刻在石頭上，斯維亞人曾經在此。","冬天終究來了，願諸神接走我的族人。"],"victory":["諸神站在斯維亞這邊，今冬我們有火有肉。","這片湖依然是我們的，把戰功刻上石碑吧。"],"allyAccept":["好，交換臂環，從今起你的敵人也是我的敵人。","吾族與你的族並肩，冰雪也擋不住兩把矛。"],"allyReject":["斯維亞人只信自己的盾牆，不需要別人的承諾。","民會不同意，我不能替全族答應你。"],"greetFriendly":["遠客，爐火已旺，坐下同飲蜜酒。","諸神保佑你的船平安渡過梅拉倫湖。"],"greetCold":["話說完了嗎？冬天不等人，我也不等。","民會尚未論及你，吾無話可說。"],"threatDefy":["吾族的盾牆立於湖畔，從未後退一步。","你要來便來，鐵與雪會替我們回答。"],"threatYield":["民會決議：此冬不與你為敵，暫且退讓。","吾為族人存續而讓步，非為懼怕你。"],"tributePay":["拿去，{gold}金幣換族人一冬安寧。","民會同意付{gold}金幣，但榮譽不賣。"],"tributeRefuse":["斯維亞人只向諸神獻祭，不向人納貢。","想要金子？自己冒雪來取，我在湖畔等。"],"giftThanks":["此禮我收下，斯維亞人記得恩情。","願諸神加倍回報你，今冬你是吾的朋友。"],"intel":["商旅傳言：{wars}正在交戰，{peace}已締和。","吾聞{wars}動了刀兵，{peace}則守約安睡。"]}},{"name":"奧洛夫・舍特科農","title":"瑞典國王","era":"約995～1022年在位","tone":"務實剛毅的維京君王，一面接受新信仰、一面保留戰士本色，語氣直率，重視商路、港口與銀幣。","portrait":"se-historical-age1","lines":{"intro":["本王奧洛夫，斯維亞人與約塔人共同的王。","從錫格蒂納到波羅的海，商船和長船都聽本王的。"],"contact":["你的人來到錫格蒂納？看看本王新鑄的銀幣吧。","遠來是客，但別忘了，這座城背後是整片波羅的海。"],"war":["你的船擋了本王的商路，那就用長船說話。","本王受洗了，但斧頭沒有放下，開戰。"],"warReply":["向維京之王宣戰？希望你的船夠多。","很好，斯維亞人正愁沒有地方試新劍。"],"peace":["血流太多，銀幣就流不動，我們停戰吧。","本王以十字架起誓，願與你休兵通商。"],"accept":["好，本王答應，長船改載貨物，不載戰士。","誓言已立，從今天起，你的商人在本王的港口平安。"],"reject":["上次你的使者話說得好聽，船卻沒停，不談。","本王的戰士剛剛集結，現在停戰太早了。"],"rebuff":["你拒絕本王？那銀幣就換成鐵吧。","本王已經給過機會，接下來由長船決定。"],"betray":["情勢已變，本王收回誓言，長船今夜出航。","神會原諒本王的，但你的港口不會再平安。"],"truceEnd":["休戰結束了，本王的船隊又能自由航行。","約定的日子到了，接下來各憑本事。"],"attacking":["斯維亞與約塔的戰士都上船了，等著看你的岸。","本王的長船正破浪而來，準備好迎接維京之王。"],"attacked":["錫格蒂納的城牆在搖，但本王的劍還握得住。","教堂與鑄幣廠都在燒，本王仍不會跪下。"],"defeated":["本王是第一個受洗的瑞典王，也不會是最後一個。","把本王的銀幣留給後人，讓他們記得這個王國。"],"victory":["諸海之上，斯維亞的長船再無對手。","把戰利品運回錫格蒂納，這一仗值得鑄一枚新幣。"],"allyAccept":["好，本王與你結盟，波羅的海一起看管。","斯維亞的長船與你同航，敵人會後悔的。"],"allyReject":["本王剛統一兩族，不想再替別人打仗。","維京人只信自己的船，結盟的話留給日後吧。"],"greetFriendly":["本王在錫格蒂納鑄了新銀幣，來看看吧。","願你的商船常來，本王的港口永遠敞開。"],"greetCold":["本王忙著整頓商路，你的問候改日再談。","空話換不來一枚銀幣，說重點。"],"threatDefy":["本王的長船從不畏懼風浪，何況是你。","本王受洗信了新神，但斧頭還沒放下。"],"threatYield":["為了商路不斷，本王暫且忍你這一回。","海上的風向會變，本王今日先退一步。"],"tributePay":["{gold}金幣拿去，就當是買下一季的太平。","本王付{gold}金幣，但港口的稅還是本王的。"],"tributeRefuse":["銀幣是本王鑄的，憑什麼交到你手上？","維京人只收貢，不納貢，你問錯人了。"],"giftThanks":["好禮！本王會在錫格蒂納的市集上宣揚你的名。","本王收下了，願你的船滿載銀幣歸港。"],"intel":["商人回報：{wars}正在開戰，{peace}已講和。","港口傳聞：{wars}兵戎相見，{peace}已締和。"]}},{"name":"古斯塔夫二世・阿道夫","title":"瑞典國王","era":"1611～1632年在位","tone":"熱血果敢的軍事天才與虔誠新教徒，語氣豪邁自信，常提及火砲與信仰，尊重勇敢的對手但絕不退讓。","portrait":"se-historical-age2","lines":{"intro":["朕是瑞典之王古斯塔夫，北方的雄獅向你致意。","朕的火砲與信仰同樣堅定，願我們能成為朋友。"],"contact":["你的人到了斯德哥爾摩？看看瑞典的新式火砲吧。","這座城背靠波羅的海，朕的艦隊就停在港裡。"],"war":["朕為信仰與瑞典而戰，你的城將見識北方雄獅。","談判已經結束，接下來由火砲說話。"],"warReply":["你向北方雄獅宣戰？朕會親自率軍會你。","很好，瑞典的滑膛槍手已經等這一天很久了。"],"peace":["戰爭拖得太久了，朕願意停戰，讓人民回田裡去。","朕敬重勇敢的對手，我們暫時放下劍吧。"],"accept":["好，朕答應了，瑞典的火砲今日靜默。","宰相奧克森謝納會擬定文件，朕以國王之名保證。"],"reject":["朕的軍隊正勢如破竹，此時停戰有負將士。","你上回的承諾還沒兌現，朕不會再聽第二次。"],"rebuff":["你拒絕了朕的善意？那就戰場上見。","朕伸出的是手，你既然不接，就換成劍。"],"betray":["局勢變了，朕必須為瑞典撕毀這份停戰。","願上帝原諒朕，但北方雄獅不能再等。"],"truceEnd":["停戰期滿，朕的軍隊已在邊境列陣。","休戰結束了，讓我們光明正大地決勝負。"],"attacking":["瑞典大軍已渡海，朕親自走在最前面。","火砲上膛，步兵列陣，北方雄獅要出擊了。"],"attacked":["城牆在崩塌，但朕還在城上，瑞典人不會逃。","只要朕還握著劍，斯德哥爾摩就沒有陷落。"],"defeated":["朕以血捍衛了信仰與瑞典，此生無憾。","告訴後人，北方雄獅是站著倒下的。"],"victory":["感謝上帝！這一戰將讓全歐洲記住瑞典。","北方雄獅勝利了，波羅的海今日屬於瑞典。"],"allyAccept":["好，朕與你並肩，火砲與信仰一起守護盟友。","瑞典的軍隊從此也是你的後盾。"],"allyReject":["朕的戰爭是為了信仰，不為他人的野心。","瑞典目前無意結盟，各走各的路吧。"],"greetFriendly":["朋友，願上帝與你同在！朕的火砲今日休息。","北方雄獅向你致意，來，同飲一杯！"],"greetCold":["朕在前線沒空寒暄，有事快說。","問候收到了，但朕更想知道你站哪一邊。"],"threatDefy":["朕的火砲輕巧迅速，你的威脅不夠響亮。","上帝與朕同在，布賴滕費爾德一戰便是明證！"],"threatYield":["朕的軍隊尚在遠方，此刻不宜再樹敵。","好，朕暫且退讓，但獅子只是在等待。"],"tributePay":["{gold}金幣給你，朕寧願把心思留給戰場。","朕付{gold}金幣，好省下火藥對付真正的敵人。"],"tributeRefuse":["朕的金幣要鑄砲、養兵，一枚也不給你。","想要貢品？來戰場上憑本事贏走吧。"],"giftThanks":["好禮！朕會記得，勇者的友誼最為珍貴。","感謝你，願上帝賜福於慷慨之人。"],"intel":["斥候回報：{wars}已開戰，{peace}已締和。","宰相來報：{wars}正在交鋒，{peace}互不侵犯。"]}},{"name":"卡爾十四世・約翰","title":"瑞典國王","era":"1818～1844年在位（1810年起為王儲攝政）","tone":"精明務實的法國出身軍人國王，講求平衡與中立，語氣穩重帶外交手腕，重視人民的愛戴多於征服。","portrait":"se-historical-age3","lines":{"intro":["朕是瑞典與挪威之王卡爾・約翰，曾是法國的元帥。","朕的瑞典話說得不好，但和平的誠意是真的。"],"contact":["你的人到了斯德哥爾摩？請轉告，瑞典歡迎友好的鄰居。","這座城已多年不聞砲聲，朕希望一直如此。"],"war":["朕本不願拔劍，但你逼瑞典走到這一步。","朕在萊比錫學會了一件事：該打的仗不能猶豫。"],"warReply":["向一個老元帥宣戰？你選了個危險的對手。","瑞典渴望和平，但不畏懼戰爭，朕接受。"],"peace":["戰爭沒有贏家，朕提議停戰，讓兩國都喘口氣。","朕見過太多戰場，知道和平比勝利更珍貴。"],"accept":["好，朕接受，瑞典的中立將是我們的共同保障。","朕以貝納多特之名起誓，這份和約瑞典會遵守。"],"reject":["此時停戰對瑞典不利，朕必須為人民拒絕。","你的條件太苛刻，元帥出身的朕看得出陷阱。"],"rebuff":["你拒絕了？可惜，朕的耐心已經用完。","朕給過和平的機會，接下來由砲兵回答。"],"betray":["局勢逼人，朕不得不撕毀停戰，瑞典要先動手。","朕為此深感遺憾，但國家利益高於誓言。"],"truceEnd":["休戰到期，朕的軍隊已整裝完畢。","和平的時光結束了，願我們下次能談得更久。"],"attacking":["瑞典大軍出發了，朕以元帥的經驗親自指揮。","砲兵先行，步兵隨後，這是朕熟悉的節奏。"],"attacked":["王宮外砲聲隆隆，但朕不會離開斯德哥爾摩。","城快守不住了，朕仍要為人民撐到最後一刻。"],"defeated":["人民的愛是朕的獎賞，朕帶著它離開。","從法國士兵到瑞典國王，這一生朕沒有白活。"],"victory":["瑞典勝利了，但朕更希望這是最後一場戰爭。","老元帥還沒忘記怎麼打仗，這一仗獻給瑞典人民。"],"allyAccept":["好，瑞典與你結盟，北方將多一份安穩。","朕答應了，兩國的友誼比戰場更值得經營。"],"allyReject":["瑞典選擇中立，朕不會再捲入他人的戰爭。","朕領教過大國同盟的代價，恕瑞典不參與。"],"greetFriendly":["朕以瑞典與挪威之名問候你，願友誼長存。","來信令朕欣喜，北方需要更多這樣的朋友。"],"greetCold":["朕已閱信，瑞典的立場一向是保持距離。","客套話朕聽得多了，你的來意是什麼？"],"threatDefy":["朕曾是拿破崙麾下的元帥，威脅嚇不倒朕。","瑞典中立，但中立不代表軟弱，請三思。"],"threatYield":["朕不願人民再受戰火，此事就依你所言。","老軍人懂得何時該退，朕選擇談判桌。"],"tributePay":["{gold}金幣送上，和平的代價朕付得起。","朕撥出{gold}金幣，就當是外交的開銷吧。"],"tributeRefuse":["國庫屬於瑞典人民，朕無權拿去討好誰。","朕寧可把錢花在運河上，也不納這種貢。"],"giftThanks":["厚禮收到，朕會在斯德哥爾摩為你舉杯。","謝謝你的心意，朕最珍視的正是這份善意。"],"intel":["使節回報：{wars}戰事正酣，{peace}相安無事。","朕所知：{wars}兵戎相向，{peace}握手言和。"]}}],"Norway":[{"name":"北方部族族長","title":"族長","era":"約西元前500年～西元500年（北歐鐵器時代，無可考君主姓名）","tone":"樸實、敬畏大海與森林、重視族人溫飽與榮譽，說話直接不繞彎，帶北方人的堅忍。自稱「我」。","portrait":"no-historical-age0","lines":{"intro":["我是北方峽灣的族長，冰雪與大海教會我們生存。","遠方的王，你的土地有陽光，我們的土地有長夜。"],"contact":["你的人走到我們的漁村了，這裡沒有金子，只有魚和木頭。","陌生的旅人，冬天快到了，要不要留下來喝一碗熱湯？"],"war":["你的人搶走我們的漁場，族人已經拿起長矛。","森林的神明見證，這一戰是為了族人的溫飽。"],"warReply":["你要打？好，來吧，北方的冬天會先替我們迎戰。","我們不怕戰鬥，怕的只是沒有魚的冬天。"],"peace":["血流夠多了，讓我們在篝火旁重新談談吧。","峽灣的冰快封住了，兩邊都該回家過冬。"],"accept":["好，我以祖先之名起誓，長矛從此放下。","你的誠意我看見了，今晚一起分享鹿肉。"],"reject":["你的話像春天的冰，看起來厚，其實一踩就破。","我的族人還記得上次的傷，現在談和太早。"],"rebuff":["你不肯？那就讓大海決定誰能活到春天。","可惜，我伸出的手你不接，那就握緊斧頭吧。"],"betray":["你的糧倉太滿了，我的族人卻在挨餓，別怪我。","篝火旁的誓言，抵不過族人餓肚子的哭聲。"],"truceEnd":["冬天過去了，河水又流動，我們的約定也到期了。","約定的月亮已經圓了三次，接下來各憑本事。"],"attacking":["戰船已經下水，族人們唱著戰歌划向你的海岸。","我親自帶隊，這次不是為了搶，是為了讓你記住我們。"],"attacked":["村子的柵欄倒了，老人和孩子已經躲進山裡。","火燒到了長屋，可我還站著，族長不能先逃。"],"defeated":["把我葬在面向大海的地方，讓我看著族人回來。","你贏了，但北方的風會記得我們的名字。"],"victory":["我們的祖先在天上看著，今天他們一定很驕傲。","回家吧，孩子們，今年冬天有故事可以講了。"],"allyAccept":["好，你的敵人就是我的敵人，我們共用一片海。","兩個部族並肩，冬天就不再那麼可怕了。"],"allyReject":["我們習慣獨自面對風雪，你的路和我們不同。","族人不願為別人的仇恨流血，請你諒解。"],"greetFriendly":["遠方的朋友，願海風帶你平安，火堆旁有你的位子。","你的信我收到了。冬天很長，有朋友問候，心裡就暖。"],"greetCold":["話我聽到了。海上風雪不等人，我沒空多談。","族人要吃飯，我要出海。你的問候，留到冬天再說。"],"threatDefy":["我們在北方的冰雪裡活下來，不會怕你幾句狠話。","森林和大海是我的靠山，你要來，就來試試看。"],"threatYield":["族人的性命比我的面子重要，這次我退一步。","好，我不跟你爭。但請你記得，北方人不會忘。"],"tributePay":["這{gold}是族人一整年的辛苦，你拿去，別再逼我們。","我把{gold}交給你，換族人一個安穩的冬天。"],"tributeRefuse":["族人的糧食一粒也不給，我們寧可跟風雪拚命。","我們的東西是用汗水換來的，不是給你白拿的。"],"giftThanks":["你的禮物我收下了，今晚火堆旁會有人唱你的名字。","謝了。北方人記得恩情，像記得回家的海路一樣。"],"intel":["商船帶來消息：{wars}正在打仗，{peace}互相講和。","聽漁人說，{wars}的戰船已經出海，{peace}的火堆還很平靜。"]}},{"name":"哈拉爾三世","title":"挪威國王","era":"1046～1066年在位","tone":"豪邁強硬、見多識廣、自信近乎傲慢，常提起遠征君士坦丁堡與基輔的往事，愛聽吟遊詩人歌頌自己。自稱「本王」。","portrait":"no-historical-age1","lines":{"intro":["本王哈拉爾，從君士坦丁堡一路征戰回到挪威。","本王走過的路比你的國土還長，報上名來吧。"],"contact":["你的探子看到本王的城了？回去告訴你的主子，城牆很厚。","奧斯陸是本王建的，每一塊木頭都刻著征戰的故事。"],"war":["本王的長船已經出海，你的海岸就是下一個目標。","維京人的斧頭不喜歡生鏽，本王向你宣戰！"],"warReply":["你向本王宣戰？很好，本王正愁斧頭沒地方磨。","當年拜占庭皇帝都留不住本王，你以為你能？"],"peace":["戰士也需要過冬，本王提議先停手，春天再說。","本王的船需要修補，你的城也需要喘息，停戰吧。"],"accept":["好，本王答應了，這個約定和本王的斧頭一樣硬。","本王接受，把酒拿來，敵人變朋友要喝一杯。"],"reject":["停戰？本王的戰士還沒把船划到你家門口呢。","不，本王千里跋涉不是為了聽你求和。"],"rebuff":["你拒絕了？本王已經給過你機會，別後悔。","傲慢的傢伙，那就等著看誰的斧頭先落下。"],"betray":["和約是寫在冰上的，太陽一出來就化了。","本王改變主意了，維京人的船不能閒著太久。"],"truceEnd":["休戰結束，船帆已經升起，本王的戰士等不及了。","約定的日子到了，接下來就是刀劍說話的時間。"],"attacking":["三百艘長船正朝你駛來，這是本王一生最大的遠征。","本王親自站在船首，你的城牆會先看到本王的旗幟。"],"attacked":["城牆破了？本王的戰斧還在手上，來啊！","本王從君士坦丁堡活著回來，這點火燒不倒本王。"],"defeated":["本王一生征戰，今天終於可以歇息了。","告訴詩人們，把本王的故事寫得長一點。"],"victory":["本王的旗幟又插上一座城，詩人們有新歌可唱了。","維京人的時代還沒結束，本王就是證明！"],"allyAccept":["好，本王與你結盟，我們的敵人該發抖了。","聰明的選擇，維京人的船隊從此為你護航。"],"allyReject":["本王習慣自己打仗，不需要別人分走戰利品。","結盟？本王還不確定你值得本王的斧頭相助。"],"greetFriendly":["本王收到你的信了。來吧，聽吟遊詩人唱本王的功業。","好，你有眼光。本王從君士坦丁堡回來後，難得遇到懂禮的人。"],"greetCold":["本王在君士坦丁堡見過皇帝，你的問候，不算什麼。","信本王看了。沒事就別打擾，本王的船隊還要出海。"],"threatDefy":["本王在基輔和君士坦丁堡打過的仗，比你聽過的還多。","嚇本王？詩人會把你這句話寫進歌裡，當作笑話。"],"threatYield":["哼，本王今日船隊未齊，暫且讓你一回，別得意太早。","本王懂得等待，在君士坦丁堡也曾忍過。這次依你。"],"tributePay":["拿去，{gold}對本王不過是南方帶回的零頭。","本王付{gold}，不是怕你，是懶得為小事動船。"],"tributeRefuse":["本王的金子是從君士坦丁堡帶回來的，一枚也不給你。","要金子？拿劍來取。本王從不向人低頭付錢。"],"giftThanks":["好禮！本王會叫詩人把你的名字，寫進本王的歌裡。","這禮物不錯，本王在基輔時也收過類似的。記你一功。"],"intel":["本王的探子回報：{wars}正在交戰，{peace}已結盟言和。","商人從南方帶來消息，{wars}刀兵未歇，{peace}互不相犯。"]}},{"name":"克里斯蒂安四世","title":"丹麥－挪威國王","era":"1588～1648年在位","tone":"精力充沛、熱愛建設與航海、喜歡親自督工與親征，有點固執但會自嘲，講話務實常提到花費與工程。自稱「朕」。","portrait":"no-historical-age2","lines":{"intro":["朕是克里斯蒂安，丹麥與挪威的王，也是個愛蓋房子的人。","朕的國土從丹麥平原延伸到挪威峽灣，歡迎你來。"],"contact":["你的人看到的那座新城叫克里斯蒂安尼亞，朕親手畫的街道。","奧斯陸燒掉了，朕就在旁邊蓋一座新的，磚造的，不怕火。"],"war":["你擋住了朕的海路，那朕只好用艦隊來開路。","朕不愛打仗，但更不愛被人欺負，開戰吧。"],"warReply":["宣戰？朕正在督工蓋城堡呢，好吧，先處理你。","朕在挪威的銀礦能買很多大炮，你確定要打？"],"peace":["打仗太花錢，朕還有好幾座城要蓋，停戰如何？","朕提議停戰，把火藥留給慶典的煙火吧。"],"accept":["好，朕答應，朕的建築師比將軍更需要工作。","朕接受了，這下朕可以安心回去看銀礦了。"],"reject":["現在談和？朕的艦隊才剛出港，太早了。","朕不信你，上一次的條約墨水還沒乾就被撕了。"],"rebuff":["你不肯？可惜，朕本來打算請你看新宮殿的。","既然你選擇繼續，朕的大炮也會繼續說話。"],"betray":["朕重新算過帳了，這場和平對朕來說太貴。","朕收回承諾，波羅的海不能有兩個主人。"],"truceEnd":["休戰期到了，朕的船已經修好，重新開戰吧。","約定的期限已滿，朕該去看看你的城牆是否結實。"],"attacking":["朕親自率領艦隊出海，國王不該躲在宮裡看戰報。","丹麥的艦隊與挪威的水手，正一起朝你駛去。"],"attacked":["城牆在崩，但朕還在甲板上，朕不會倒下。","朕失去了一隻眼睛也沒退，這點炮火算什麼。"],"defeated":["朕蓋的城會比朕活得久，這就夠了。","六十年的王位，朕做了能做的，剩下的交給後人。"],"victory":["勝利了，朕要在哥本哈根蓋一座塔來紀念。","戰利品拿去蓋學校和港口，這才是朕想要的勝利。"],"allyAccept":["好，朕與你結盟，朕的船隊與你的軍隊互相照應。","結盟之後，朕的商船就能安心在你的港口停靠了。"],"allyReject":["朕的財庫已經被戰爭掏空，暫時不能再捲入盟約。","朕欣賞你，但丹麥的艦隊只為丹麥與挪威而戰。"],"greetFriendly":["來信收到，朕正在督造新城，改天帶你看看朕的港口。","朕忙得很，不過你的問候讀來順心。要造船就找朕。"],"greetCold":["朕的工程一天燒掉多少銀子，你知道嗎？沒空寒暄。","信朕看過了。船廠等著朕去驗收，改日再談。"],"threatDefy":["朕親自帶過艦隊出海，你這幾句話嚇不倒朕。","要打？朕的要塞剛砌好，正好試試牆有多厚。"],"threatYield":["唉，國庫被工程掏空了，朕這回只好先低頭。","朕固執歸固執，也懂算帳。打不起，就先退一步吧。"],"tributePay":["{gold}拿去。這筆錢本來能蓋半座城門，朕心疼得很。","好吧，{gold}給你。朕的礦山再挖挖，總能補回來。"],"tributeRefuse":["朕每一枚銀幣都算好了要蓋什麼，一枚也分不出來。","不給。朕寧可把錢砸進船廠，也不白送給你。"],"giftThanks":["好東西！朕會把它擺在新王宮裡，工匠們看了也高興。","多謝。朕平常只收帳單，難得收到禮物，心情不錯。"],"intel":["朕的商船回報：{wars}正在打仗，{peace}則已講和。","港口水手說，{wars}還在交戰，{peace}簽了和約，生意好做。"]}},{"name":"哈康七世（Haakon VII）","title":"挪威國王（1905 年獨立後首任國王）","era":"1905–1957 在位（台詞取 1905–1914 年情境）","tone":"溫和謙遜、務實有禮，開口常提人民與國會的意志；不張揚，但在原則上絕不退讓；自稱「我」，愛用海洋、峽灣、冬雪與船隊作比喻。","portrait":"no-historical-age3","lines":{"intro":["我是哈康七世，挪威人民以公投請我來，我便一切為了挪威。","北方的峽灣國度向您致意，挪威雖小，卻有自己的國王了。"],"contact":["您的人來到我的港口了？那些商船都是挪威人自己造的。","峽灣之間的木屋城市不大，卻是一整個民族剛剛拿回的家。"],"war":["挪威人民與國會決議對您宣戰，我身為國王，必須執行。","我們用了近百年才爭來的自由，不容任何人動搖。開戰吧。"],"warReply":["您選擇對挪威用兵？山與海會替我們守著，人民也不會退。","挪威剛獨立就受人欺凌，我會親自去國會，請他們全力備戰。"],"peace":["挪威立國之初最盼望和平，請容我提議停戰，讓漁船再出海。","與其兩敗俱傷，不如坐下來談，如同我們與瑞典和平分手那樣。"],"accept":["我接受。國會會為此高興，挪威的船終於可以再自由航行。","好，就這麼定了。挪威人重承諾，您可以放心。"],"reject":["您的條件，我無法帶回國會交代。挪威人寧可再撐一個冬天。","現在停戰對挪威不公平，恕我拒絕，請您重新考慮條件。"],"rebuff":["您不願意？我明白了。挪威會繼續守住自己的峽灣。","遺憾，但我尊重您的決定。挪威的門仍會為和談敞開。"],"betray":["人民與國會改變了決定，停戰到此為止，我只能如實告知您。","您在邊境的動作挪威看得清楚，協議既失去意義，就此作廢。"],"truceEnd":["休戰期滿了。挪威不主動生事，但也已做好準備。","約定的日子到了，接下來如何，就看您的選擇了。"],"attacking":["挪威的滑雪部隊已出發，雪地是我們的道路，不是阻礙。","船隊已駛出峽灣，這一次挪威人不是去捕魚，而是去守護家園。"],"attacked":["城牆在震動，但我不會離開人民。國王應與挪威共存亡。","峽灣邊已見火光，我請國會作最後決定，挪威不會輕易低頭。"],"defeated":["挪威輸了這一仗，但一個曾靠公投立國的民族，不會就此消失。","一切為了挪威，這句話我到最後仍然沒有食言。"],"victory":["挪威贏了，但我不想慶祝戰爭。把船修好，讓人回家吧。","小國也能守住自己，這是挪威人民用毅力證明的事。"],"allyAccept":["挪威願與您結盟。我的王后來自英國，我懂得盟友的可貴。","好，兩國並肩。挪威的商船隊隨時可為盟友運送物資。"],"allyReject":["挪威立國以中立為本，國會不會同意結盟，請您見諒。","我們剛脫離一場聯合，暫時不想再綁上另一條繩子。"],"greetFriendly":["您的信讓冬天暖了些。歡迎來看看我們的峽灣與滑雪場。","謝謝問候。挪威的鱈魚與木材，隨時歡迎貴國的商人來買。"],"greetCold":["信收到了。挪威人話不多，您有正事再說吧。","客套話就免了，北方的冬天很長，我沒有太多時間。"],"threatDefy":["威脅挪威？一九〇五年瑞典陳兵邊境，我們也沒有低頭。","山與海是挪威的城牆，您的恐嚇還沒翻過第一座山。"],"threatYield":["挪威的軍隊不多，我不能拿人民冒險。您的要求，我會考慮。","好吧，一個年輕的國家要學會忍耐。挪威暫且退讓。"],"tributePay":["國會同意付 {gold} 金幣，這是挪威漁民的辛苦錢，請善用。","{gold} 金幣送上，換峽灣一季安寧。挪威人記得這筆帳。"],"tributeRefuse":["挪威的金幣要用來建鐵路與水力發電，不會送給威嚇我們的人。","貢品？挪威人民剛用公投選出國王，不是為了向誰納貢。"],"giftThanks":["多謝厚禮。我會請人放在王宮，讓來訪的百姓也看得到。","您的心意，挪威收下了。改天送您一箱北海的鱈魚回禮。"],"intel":["商船帶回消息：{wars} 正在交戰，{peace} 已停火。","使節回報：{wars} 開戰中，{peace} 維持和平。"]}}],"Finland":[{"name":"族長","title":"芬蘭部族首領","era":"鐵器時代（約西元前 500～西元 500 年）","tone":"沉穩寡言、務實堅忍，說話帶森林與冬雪的意象，自稱「吾／我」，最看重族人與獵場。","portrait":"fi-historical-age0","lines":{"intro":["吾是湖泊與森林的族長，遠方的來客，說明你的來意。","長冬教會我們忍耐，也教會我們分辨朋友與敵人。"],"contact":["你的人踏進了我們的獵場，這片林子有主人。","越過那片湖便是我族的村落，帶著善意才准靠近。"],"war":["你的貪心太重，森林的子民要拿起弓和斧頭了。","雪地會記住你的足跡，我們會循著它找到你。"],"warReply":["你想開戰？冬天站在我這邊，你的軍隊撐不過雪。","我族人少，但每一個都熟悉這片林子的每條小路。"],"peace":["打獵的季節到了，放下武器，各自回去顧好糧倉吧。","吾願以毛皮換和平，湖的兩岸都不必再哭泣。"],"accept":["好，吾以先祖之名起誓，這份約定像岩石一樣牢固。","來，圍著火堆坐下，從今天起你是我們的客人。"],"reject":["你的話像春天的薄冰，吾不會踩上去。","傷了我族人的手，還想來握手？先回去吧。"],"rebuff":["你不肯？那就讓森林替我們做決定。","吾的善意只說一次，往後你別再向我開口。"],"betray":["你的人在我們的湖裡下網，這約定已經破了。","原諒吾，族人的糧倉比一句諾言更重要。"],"truceEnd":["冰融了，河水再次流動，我們之間的約定也到頭了。","休戰的日子過去了，接下來各憑本事。"],"attacking":["族人們已經穿上雪鞋，我們要去你的村子作客了。","聽見林中的號角了嗎？那是我族出發的聲音。"],"attacked":["柵欄燒了，可是我們的人還站著，你休想輕易進來。","就算村子倒下，森林依然是我們的家。"],"defeated":["吾倒下了，但湖水與白樺會記得我族的名字。","善待留下來的人，這是族長最後的請求。"],"victory":["森林的子民贏了，今晚火堆會燒到天亮。","你來得像暴風雪，卻走得像融化的雪水。"],"allyAccept":["好，從此你的敵人就是我的敵人，我們同獵同守。","吾把這把獵刀交給你，這是我族最重的信物。"],"allyReject":["我族習慣自己守自己的林子，不必綁在一起。","你的路和我們的路不同，就各自走吧。"],"greetFriendly":["遠方的朋友，冬雪未封路，你的使者已抵達。吾族火堆為你留位。","森林很大，容得下兩個部族。吾願與你共享冬日的火光。"],"greetCold":["使者的話吾聽過了。雪深路遠，吾族自有獵場，不需多言。","陌生人的話，如風過松林。吾聽見了，僅此而已。"],"threatDefy":["吾族在冰雪中活了千年，不怕你一句狠話。","你若踏進這片森林，每棵松樹後都有我族的弓。"],"threatYield":["吾族人少，經不起一場戰事。你要什麼，說吧。","冬天將至，吾不能拿族人的性命去賭。這次，我讓步。"],"tributePay":["吾族拿出 {gold} 金幣，換族人一個安穩的冬天。","這 {gold} 金幣是族人一年的皮毛換來的，你收好。"],"tributeRefuse":["森林的獵物歸族人所有，吾一枚也不會給你。","雪地裡的狼也不向人討食。吾族不納貢。"],"giftThanks":["禮物收到了。吾會把它放在火堆旁，讓全族都看見。","多謝。松林記得每一份善意，吾族也是。"],"intel":["獵人們說，{wars}正在交戰；{peace}已放下弓箭。","風從南邊帶來消息：{wars}起了戰火，{peace}結了盟。"]}},{"name":"馬格努斯·塔瓦斯特","title":"土庫主教","era":"1412～1450 年在位（土庫主教）","tone":"虔誠沉穩、老練的外交家，語氣溫和但有分量，自稱「本主教」，常提及教堂鐘聲、教區與王國。","portrait":"fi-historical-age1","lines":{"intro":["本主教馬格努斯，牧養芬蘭教區，願主賜你平安。","土庫的鐘聲響遍北方，來者若懷善意，教堂的門常開。"],"contact":["你的人來到了土庫，這裡是王國最東邊的教區。","大教堂的新側殿正在興建，已足以讓遠客駐足。"],"war":["本主教不願動刀劍，但你逼得教區不得不自衛。","王國的旗與教會的十字，將一同對你而來。"],"warReply":["你向一位主教宣戰？主會看見，王國會議也會聽見。","芬蘭人守了東方邊界百年，不差你這一場。"],"peace":["刀劍不能讓田地長出麥子，讓我們談談停戰吧。","本主教願以教會之名擔保，你我先放下兵器。"],"accept":["甚好，願主見證這份和約，教堂的鐘會為它敲響。","和平比任何戰利品都珍貴，本主教欣然接受。"],"reject":["你的和約寫得漂亮，可惜你的行為並不誠實。","教區的人民尚未安寧，本主教不能接受這份條件。"],"rebuff":["你拒絕了和平，願主日後不會讓你為此後悔。","既然如此，本主教只好為芬蘭的百姓另作打算。"],"betray":["本主教不得不撕毀和約，這是為了教區的存續。","願主寬恕我，牧者有時也必須拿起牧杖擊退狼群。"],"truceEnd":["休戰的期限已滿，願你我都記得和平的滋味。","教堂的鐘敲過了約定的時辰，往後各憑良心行事。"],"attacking":["芬蘭的騎士與農夫已經集結，他們正朝你的城前進。","本主教為出征的人祝禱過了，願這場仗早日結束。"],"attacked":["城牆在搖晃，但大教堂的塔樓依然屹立。","百姓已躲進教堂，你若還有敬畏之心，就止步吧。"],"defeated":["教區落入你手，願你善待這片土地上的信徒。","本主教的一生已交託給主，芬蘭的未來就交給時間。"],"victory":["感謝主，芬蘭教區得以保全，鐘聲今日為勝利而響。","本主教不以勝利自豪，只願往後不必再打仗。"],"allyAccept":["本主教代表芬蘭教區與你結盟，願主護佑我們同行。","有你為友，東方邊界的冬夜也不再那麼漫長。"],"allyReject":["教區已向王國效忠，本主教不能另立盟約。","你的盟約背後藏著算計，本主教看得清楚。"],"greetFriendly":["願主賜你平安。土庫的鐘聲今日為遠方的朋友而響。","本主教讀了來信，深感欣慰。教區的門為你敞開。"],"greetCold":["本主教已閱。教區事務繁重，恕不多談。願主保佑。","信中言辭客氣，用意卻不明。本主教會謹慎以對。"],"threatDefy":["本主教身後有教會與王國。恫嚇之詞，請收回。","土庫大教堂的石牆已立百年，不會因一封信動搖。"],"threatYield":["教區的百姓禁不起戰亂。本主教願意坐下來談。","為了教區的安寧，本主教退讓一步。願主寬恕你。"],"tributePay":["教區奉上 {gold} 金幣，願這筆錢換得一季平安。","本主教從教堂庫房撥出 {gold} 金幣，請善加使用。"],"tributeRefuse":["教堂的財物屬於主與百姓，本主教無權贈人。","教區的十一奉獻用來修堂濟貧，一枚也不能給你。"],"giftThanks":["厚禮已收，本主教將在晨禱中為你祈福。","你的心意，土庫的鐘聲會記得。願主報答你的慷慨。"],"intel":["據教區信使回報：{wars}正在交戰，{peace}已締結和約。","本主教聽聞，{wars}兵戎相見；{peace}則同守和平。"]}},{"name":"約翰公爵","title":"芬蘭公爵","era":"1556～1563 年任芬蘭公爵（1568～1592 年為瑞典國王約翰三世）","tone":"自信驕傲、有野心又講究品味，語氣華麗帶點傲氣，自稱「本公爵」，常提土庫城堡、艦隊與「王兄」。","portrait":"fi-historical-age2","lines":{"intro":["本公爵約翰，芬蘭公爵，土庫城堡歡迎遠道而來的君主。","波羅的海的風吹到這裡，帶來的是商船，還是戰船？"],"contact":["你的人看見土庫城堡了？那是本公爵的宮廷所在。","芬蘭的海岸線比你想的長，我的城可不只這一座。"],"war":["本公爵已受夠你的挑釁，芬蘭的艦隊今日啟航。","你阻擋了本公爵的大業，那就別怪我拔劍相向。"],"warReply":["向本公爵宣戰？你可知道芬蘭貴族的騎兵有多快？","很好，本公爵正愁沒機會讓王兄看看芬蘭的實力。"],"peace":["戰爭耗盡國庫，貿易才能充實它，我們停戰吧。","本公爵願意坐下來談，土庫城堡的宴席已備好。"],"accept":["本公爵接受，讓波羅的海重新成為商人的海。","好，以芬蘭公爵之名立約，今晚城堡設宴慶祝。"],"reject":["你的條件配不上本公爵的身分，回去重寫吧。","本公爵不與言而無信之人立約，這次免談。"],"rebuff":["你竟拒絕本公爵的好意？往後別再指望這種機會。","也罷，本公爵的耐心和金庫一樣，都是有限的。"],"betray":["時勢變了，本公爵的大業不能被一紙和約綁住。","別怪本公爵，王座之路上，承諾只是墊腳石。"],"truceEnd":["休戰期滿，本公爵的艦隊也修整完畢了。","約定的日子到了，接下來各自為自己的野心打算。"],"attacking":["芬蘭的艦隊已駛出土庫港，目標是你的城。","本公爵親自率軍前來，你最好準備好投降書。"],"attacked":["土庫城堡的城牆裂了，但本公爵還沒放下劍。","就算城堡陷落，本公爵的名字也不會消失在北方。"],"defeated":["本公爵的大業就此結束，芬蘭的土地就託付給你了。","王座終究離我太遠，但至少我曾在土庫做過夢。"],"victory":["勝利屬於芬蘭公爵，今晚土庫城堡燈火通明。","本公爵的大業又向前一步，王兄該重新看待我了。"],"allyAccept":["本公爵欣然結盟，波羅的海兩岸從此互為後盾。","好盟友比好城堡更難得，本公爵珍惜這份情誼。"],"allyReject":["本公爵的盟約只給能助我大業的人，你還不夠格。","與你結盟只會惹惱王兄，本公爵暫且婉拒。"],"greetFriendly":["本公爵在土庫城堡設宴，你的來信為燭光添了幾分光彩。","有眼光的人才會寫信給本公爵。歡迎來土庫一敘。"],"greetCold":["本公爵日理萬機，來信已閱，就此打住。","信紙的品質尚可，內容卻乏善可陳。本公爵不予置評。"],"threatDefy":["本公爵的艦隊就停在土庫港，你確定要試試看？","瓦薩家的兒子從不低頭。土庫城堡的砲口正對著海。"],"threatYield":["本公爵與王兄之間已夠緊張，暫且不與你為敵。","好吧，本公爵今日讓步。但這不代表本公爵怕了你。"],"tributePay":["{gold} 金幣？對本公爵而言不過是一場宴會的花費。拿去。","本公爵從土庫城堡的金庫撥出 {gold} 金幣，勿再打擾。"],"tributeRefuse":["本公爵的金幣要用來擴建艦隊，一枚也不會給你。","向本公爵索貢？土庫城堡的宮廷從沒聽過這種笑話。"],"giftThanks":["這份禮物頗有品味，本公爵會把它擺在城堡大廳。","懂得送禮的人，本公爵向來敬重。土庫宮廷歡迎你。"],"intel":["本公爵的信使回報：{wars}正在開戰，{peace}已經言和。","波羅的海的消息傳來，{wars}動了刀兵，{peace}結為友邦。"]}},{"name":"斯內爾曼","title":"芬蘭大公國參議員","era":"1806～1881 年（1863～1868 年主持參議院財政事務）","tone":"理性冷靜、哲學家氣質，句句有分量，重視語言、教育與民族精神，自稱「我」，語氣端正不浮誇。","portrait":"fi-historical-age3","lines":{"intro":["我是芬蘭大公國參議員斯內爾曼，代表參議院向你致意。","一個民族的力量不在刀劍，而在它的語言與教育。"],"contact":["你的人到了赫爾辛基，這是大公國的首府。","參議院大樓就在廣場旁，芬蘭的事務由芬蘭人商議。"],"war":["我本不願走到這一步，但大公國的尊嚴不容踐踏。","芬蘭人向來沉默，但當我們開口宣戰，就不會退縮。"],"warReply":["你選擇了戰爭，那麼芬蘭人會用堅忍回應你。","這片土地熬過了饑荒與嚴寒，不會被你的軍隊嚇倒。"],"peace":["戰爭讓學校關門、田地荒蕪，讓我們談停戰吧。","參議院授權我提出停戰，理性的人應該懂得把握。"],"accept":["我接受，這份和約會讓大公國的馬克幣更有價值。","好，讓筆取代刀劍，芬蘭需要的是安穩的年月。"],"reject":["你的條件缺乏誠意，參議院不會在這樣的文件上簽字。","和平不能建立在屈辱之上，這份提議我無法接受。"],"rebuff":["你拒絕了理性的提議，歷史會記下這個選擇。","既然如此，芬蘭人只好再次靠自己撐過去。"],"betray":["情勢已變，我必須把大公國的存續放在和約之前。","我為此感到遺憾，但為了人民，這份和約只能作廢。"],"truceEnd":["停戰期限已到，願這段日子讓你我都學到了什麼。","和約到期了，往後的關係要重新由行動來定義。"],"attacking":["芬蘭的部隊已從赫爾辛基出發，這是參議院的決議。","我不擅長指揮軍隊，但芬蘭的士兵不需要人催促。"],"attacked":["赫爾辛基的街道燃燒著，但參議院不會離開崗位。","城可以毀，學校可以重建，芬蘭的精神燒不掉。"],"defeated":["大公國倒下了，但只要芬蘭語還有人說，它就沒有消失。","請善待這裡的學校與教師，那是我一生的心血。"],"victory":["芬蘭人不以征服自豪，我們只是守住了自己的家園。","勝利之後，我要做的第一件事是重新開學。"],"allyAccept":["參議院同意結盟，願我們用貿易與學問彼此扶持。","芬蘭人一旦許諾，便會像冬天的冰一樣堅實。"],"allyReject":["大公國的處境特殊，此刻不宜與你結盟，請見諒。","結盟需要信任，而信任需要時間，我們還沒到那一步。"],"greetFriendly":["來信已細讀。一個民族的友誼，始於彼此的理解。","我樂於與願意講理的人往來。赫爾辛基歡迎你。"],"greetCold":["信已收到。空泛的客套無助於任何事，恕我直言。","我沒有時間寒暄。芬蘭的學校與語言，還有太多事要做。"],"threatDefy":["威嚇無法改變事實。一個民族的精神，不是恐嚇能折斷的。","我讀過太多哲學，不會被幾句狠話說服。請講道理。"],"threatYield":["大公國無力與你抗衡，這是事實。我選擇務實退讓。","保全學校與人民，比爭一時之氣重要。我讓步。"],"tributePay":["參議院撥出 {gold} 金幣。這筆錢本該用在學校，請記住。","{gold} 金幣已備妥。我不情願，但理性告訴我該這麼做。"],"tributeRefuse":["大公國的每一枚馬克都有用處，我一枚也不會給你。","這筆錢要建學校、印書籍。恕我拒絕你的要求。"],"giftThanks":["禮物收到，謝謝。若是書籍，我會更感激。","你的善意我記下了。理性的人，懂得回報理性的友誼。"],"intel":["據參議院的消息：{wars}正在交戰，{peace}已締結和平。","報紙上寫得清楚，{wars}兵戎相向；{peace}維持和睦。"]}}],"Iceland":[{"name":"英格爾夫·阿納爾松","title":"冰島首位拓荒族長","era":"約西元874年登陸冰島（9世紀）","tone":"沉穩寡言、信奉命運與諸神徵兆、務實的開拓者；語氣質樸有力，常提到海、北風與神的指引。","portrait":"is-historical-age0","lines":{"intro":["吾乃英格爾夫，追隨高座柱漂流之處，在此建家。","這片冒煙的海灣是諸神指給我的，你是遠道的客人嗎？"],"contact":["你的人望見了我的屋舍，冰島的第一縷炊煙便在這裡。","遠來者，這裡沒有國王，只有開墾的人和北風。"],"war":["你屢屢侵擾我的牧場，海上來的人不會忍第二次。","我曾為兄弟渡海尋仇，今日為家園亦然，備戰吧。"],"warReply":["你向拓荒者宣戰？北風與寒冬會先替我迎接你。","好，我的斧頭砍得倒森林，也擋得住來犯之人。"],"peace":["冬天快到了，與其相爭，不如各自儲糧，停戰如何？","這島夠大，容得下兩家人的牛羊，我們別再打了。"],"accept":["好，以索爾之名，我接受，願彼此的田地都豐收。","握手為誓，北方人一言既出，寒冬也改不了。"],"reject":["你的話像海霧，看不清底細，我不會答應。","停戰？等你的船離開我的海灣，再來談吧。"],"rebuff":["你拒絕了？也罷，命運早有安排，我等著看。","我伸出的是手，不是刀，你自己選了難走的路。"],"betray":["諸神改變了徵兆，我不再受這約定束縛。","誓言是對族人立的，不是對你，我要拿回我的海岸。"],"truceEnd":["休戰的日子過去了，海面又能行船，各自小心。","約定到此為止，往後的事，讓命運決定吧。"],"attacking":["我的長船已經下水，划槳聲會先於我抵達你的岸。","族人們都上船了，這次北風站在我這一邊。"],"attacked":["屋舍燒了，高座柱還在，只要柱子在，家就在。","我曾赤手在荒島立業，就算只剩一人也不會走。"],"defeated":["就這樣了嗎…把我的高座柱交給後人，他們會再開墾。","諸神啊，我把這片土地交還給你們，別忘了我的名字。"],"victory":["這片海灣依然是我的，炊煙會繼續升起。","我對高座柱說過，此地必興，今日果然如此。"],"allyAccept":["好，同盟就像同一條船的槳手，我們一起划。","從今以後，你的船能在我的海灣避風。"],"allyReject":["我渡海就是為了不受人管束，同盟免了。","各自守好各自的海岸，這樣對彼此最好。"],"greetFriendly":["北風送來你的信，願諸神也護你平安。","吾的屋舍剛在雷克雅維克立起，遠客來了便是朋友。"],"greetCold":["海太寬，你的問候到得晚了。吾無話可說。","吾忙著在新土地上立柱蓋屋，無暇寒暄。"],"threatDefy":["吾渡過北海的風暴，還會怕你的恐嚇？","這片土地是諸神指給吾的，誰也奪不走。"],"threatYield":["吾的族人尚少，不願與你結仇。此事就依你吧。","新墾的田地經不起戰火，吾暫且退讓一步。"],"tributePay":["好吧，這{gold}金幣你拿去，別再擾我的族人。","吾以{gold}金幣換一冬的安寧，願這是值得的。"],"tributeRefuse":["吾帶來的糧與牲口是族人的命，一分也不給。","向海求財去吧，吾的倉庫不對強索者敞開。"],"giftThanks":["這份禮物吾收下了，願諸神記住你的慷慨。","在這荒涼北地，遠方的禮物格外珍貴，多謝。"],"intel":["吾聽出海的族人說，{wars}正在交戰，{peace}相安無事。","風把消息帶來：{wars}動了刀兵，{peace}仍守和平。"]}},{"name":"斯諾里·斯圖魯松","title":"全國議會法律宣講人","era":"1179–1241（任法律宣講人 1215–1218、1222–1231）","tone":"博學圓滑、愛以律法與典故說理，語帶文人幽默；既是政客也是詩人，講話講究修辭，不輕易動武。","portrait":"is-historical-age1","lines":{"intro":["我是斯諾里，冰島無君無王，我們以法律立國。","在議會的法岩上，我宣講律法，也記錄君王的故事。"],"contact":["你的人看見了雷克霍特，我的溫泉比宮殿更暖。","這裡沒有城牆，只有議會、牧場和寫不完的史詩。"],"war":["我筆下寫過許多君王興亡，現在輪到你的故事了。","律法解決不了的事，就只好由首領們的人馬來解決。"],"warReply":["向一位文人宣戰？你會成為我書中最短的一章。","我寧願用羊皮紙談判，但你選了刀劍，那便如此。"],"peace":["以法立國，不以刀立國，我們回到議會談吧。","史書記載的多是戰爭，讓我們寫一段和平的篇章。"],"accept":["好，我接受，這份約定我會親筆記入史冊。","明智的選擇，詩人會為和平寫出更好的詩句。"],"reject":["你的提議缺了公正，我在法岩上不會宣讀它。","不，我讀過太多虛假的盟約，這一份也一樣。"],"rebuff":["你拒絕了？那我只好在史書裡如實記下這一筆。","也罷，不是每個人都聽得懂律法與道理。"],"betray":["情勢變了，首領的義務在於族人，不在舊約。","我曾寫過奧丁的詭計，如今也學上一回。"],"truceEnd":["休戰期滿，如同議會散會，各自回到自己的立場。","約定的日子到了，接下來的章節，由行動來寫。"],"attacking":["各家首領的人馬已在雷克霍特集結，出發了。","這一次我放下筆，讓行動替我說話。"],"attacked":["溫泉池旁的宅邸快守不住了，可我的書還在。","就算雷克霍特陷落，埃達與史詩仍會流傳千年。"],"defeated":["不要砍！……這句話，也讓後人記下來吧。","我寫下了所有君王的結局，唯獨忘了寫自己的。"],"victory":["律法與智慧勝過刀劍，這一章我會寫得很精彩。","這場勝利，值得在議會上多念一段詩。"],"allyAccept":["好，同盟成立，我會把你的名字寫進好的篇章。","既然要結盟，也請讀讀我的《埃達》，了解我們的神。"],"allyReject":["冰島的首領各有盤算，我不能替全島與你結盟。","恕我拒絕，我與挪威國王的往來已經夠複雜了。"],"greetFriendly":["你的信寫得雅致，我在雷克霍特讀了兩遍。","詩人與朋友，我都歡迎。請來我的溫泉池坐坐。"],"greetCold":["問候收到了。法律宣講人忙得很，恕不多言。","這封信的文采平平，我暫且當作聽過就好。"],"threatDefy":["威嚇不合法理，也不成詩句。我聽了只覺得可惜。","議會的法律比刀劍長久，你的恐嚇留不到明年。"],"threatYield":["明智之人懂得何時該讓步。好吧，我聽你的。","我是寫史的人，不想成為史書裡敗亡的那一頁。"],"tributePay":["{gold}金幣送上。請記得，這是借出的和平，不是臣服。","以{gold}金幣換得安寧，這筆帳我會寫進史書裡。"],"tributeRefuse":["按冰島法律，無故索貢者可被告上議會。免談。","我的金銀寧可養詩人，也不餵給貪心的使者。"],"giftThanks":["好禮！我會為此寫一首詩，讓你的名字流傳。","禮物收到，情誼記下。斯諾里向來不忘朋友。"],"intel":["據議會傳聞，{wars}正兵戎相見，{peace}則安然無事。","商船帶來消息：{wars}起了戰事，{peace}仍享太平。"]}},{"name":"約恩·阿拉松","title":"霍拉爾主教","era":"1484–1550（任主教 1524–1550）","tone":"剛烈固執、信仰堅定又帶詩人機鋒；面對丹麥王權毫不退讓，說話直率，常引神與信仰。","portrait":"is-historical-age2","lines":{"intro":["本主教約恩，掌霍拉爾教區，不向丹麥王低頭。","這座島有自己的信仰與詩歌，不需外人指點。"],"contact":["你的人看見了霍拉爾大教堂，那鐘聲是為冰島響的。","這裡的印刷機印的是信仰與冰島文，不是國王的敕令。"],"war":["你想拿走我的教區？先問問霍拉爾的鐘和人心。","本主教的牧杖不只用來牧羊，也用來守土。"],"warReply":["丹麥王都不曾讓我屈服，你以為你行？","好，就讓神看看，誰的信念更經得起北風。"],"peace":["神不喜爭鬥，我們各自守好自己的教區吧。","停戰吧，讓農人回去割草，讓教堂重新響鐘。"],"accept":["好，本主教答應，願神見證這份約定。","和平比敕令更值得印成書，我接受。"],"reject":["這種條件，連丹麥人都不敢向我開口。","不，我寧可守著霍拉爾，也不簽屈辱的約。"],"rebuff":["你拒絕了神的和平？那後果請你自己承擔。","也罷，冰島人早習慣孤軍奮戰了。"],"betray":["情勢有變，教區的安危高於一紙約定，恕我撕毀。","神給了我新的啟示，舊的約定就此作廢。"],"truceEnd":["休戰結束了，鐘聲重新敲響，各自警醒吧。","約定期滿，本主教不再受其約束。"],"attacking":["北方的農民與教士都跟著我出發了，你聽見鐘聲了嗎？","我帶著兒子們南下，這一次是為整座島而戰。"],"attacked":["霍拉爾快守不住了，可信仰不是石牆，燒不掉。","就算大教堂倒下，我印的書早已傳遍全島。"],"defeated":["來世有更好的生命？這我知道，不必你告訴我。","我倒下了，但冰島人會記得，曾有人不肯低頭。"],"victory":["神站在霍拉爾這一邊，鐘聲今日格外響亮。","本主教守住了教區，也守住了冰島的尊嚴。"],"allyAccept":["好，我答應結盟，願你不是另一個丹麥國王。","同盟成立，本主教會為你的軍隊祈福。"],"allyReject":["我已對抗一個國王，不打算再欠另一個人情。","恕難結盟，霍拉爾只聽從神，不聽從盟約。"],"greetFriendly":["願上主賜你平安。霍拉爾的門為朋友敞開。","來信讀畢，本主教心中一暖。北國冬長，友情難得。"],"greetCold":["本主教正忙著守護教會，你的問候留待日後。","信收到了。若無正事，請勿再打擾禱告的時間。"],"threatDefy":["丹麥國王都嚇不倒我，你這幾句話算什麼？","我只跪上主，不跪威脅。要戰，霍拉爾奉陪。"],"threatYield":["教區的百姓經不起兵災，本主教暫且忍讓。","好吧，我讓步。但上主看得見誰在恃強凌弱。"],"tributePay":["{gold}金幣拿去，這是教會的錢，願你用得心安。","本主教交出{gold}金幣，只求教堂的鐘聲不停。"],"tributeRefuse":["教會的財產屬於上主與窮人，不屬於索貢者。","一枚銅板也不給。你若不服，來霍拉爾親自拿。"],"giftThanks":["感謝你的厚禮，願上主加倍賜福於你。","好禮！我會用它印幾本書，讓冰島人多識些字。"],"intel":["教會的信使回報，{wars}正在交戰，{peace}安享太平。","北海的漁船帶回消息：{wars}起了兵禍，{peace}無事。"]}},{"name":"約恩·西古德森","title":"冰島獨立運動領袖・議會主席","era":"1811–1879（活躍於 1840～1870 年代）","tone":"溫文理性、據理力爭的學者型領袖；不動刀劍，靠文件、法律與輿論說話；語氣堅定但有禮，常提「權利」「法律」「冰島人民」。","portrait":"is-historical-age3","lines":{"intro":["我是約恩·西古德森，為冰島的權利而來，不為戰爭。","這座島在丹麥治下，但冰島人的意志從不屬於別人。"],"contact":["你的人看見了雷克雅維克，議會剛在那裡重新開議。","這裡沒有堡壘，只有漁船、書本，和爭取自由的人。"],"war":["我不願走到這一步，但冰島人的忍耐是有限度的。","你侵犯的是人民的權利，冰島人不會沉默。"],"warReply":["向一個沒有軍隊的民族宣戰？歷史會記下你的名字。","好，我們沒有大砲，但有整座島的決心。"],"peace":["讓我們用文件取代槍砲，這才是文明人的做法。","我提議停戰，把爭議交給談判桌與法律。"],"accept":["我接受，理性終究勝過武力，這是好的一天。","好，就這麼定了，我會把條文逐字寫清楚。"],"reject":["這份條件損害冰島的權利，我不能簽。","我在國民會議上頂撞過丹麥總督，不會在此讓步。"],"rebuff":["你拒絕了？那麼我們全體抗議，並且繼續前行。","可惜，理性的門我仍會為你留著。"],"betray":["你先違背了條文精神，這份約定已無效力。","對不起，人民的權利高於一紙不公的約定。"],"truceEnd":["休戰期滿，我們回到各自的立場，但門仍開著。","約定到期了，接下來的路，由冰島人民決定。"],"attacking":["我們出發了，冰島人一旦下定決心，比冰河更難擋。","這不是為了征服，是為了讓權利被聽見。"],"attacked":["雷克雅維克快撐不住了，可人民的意志燒不掉。","你能拿下這座城，卻拿不走冰島人的自決之心。"],"defeated":["我倒下了，但請記得，有一天冰島會自己作主。","我的文件會留下來，後人會接著寫完這一頁。"],"victory":["這場勝利屬於冰島人民，不屬於我一人。","看吧，堅持與法理，也能贏得尊重。"],"allyAccept":["我答應結盟，小國更該彼此扶持。","好，願這份盟約建立在平等之上，而非強弱。"],"allyReject":["冰島才剛學會自己說話，暫時不宜依附任何人。","恕我婉拒，我對丹麥的教訓已經夠深刻了。"],"greetFriendly":["感謝來信。冰島人民珍惜每一位尊重我們的朋友。","你的問候令人欣慰，願我們以理性與善意往來。"],"greetCold":["來函已閱。恕我直言，客套之外，尚無可談之事。","我正為冰島的權利伏案疾書，問候容後再敘。"],"threatDefy":["我們全體抗議！威嚇壓不倒有法律依據的權利。","冰島人不動刀劍，但也從不在恐嚇面前低頭。"],"threatYield":["為了人民的安全，我願暫時退讓，但權利不會消失。","冰島無兵可用，我只能以筆抗議，此事姑且從你。"],"tributePay":["{gold}金幣如數奉上，但我會將此事記錄在案。","議會決議交出{gold}金幣，以免人民受苦。"],"tributeRefuse":["無法律依據的索貢，冰島議會一概不予承認。","冰島人的財產屬於冰島人，這是權利，非施捨。"],"giftThanks":["厚禮心領，冰島人民感謝你的善意與尊重。","這份禮物我將用於整理古籍，讓後人記得冰島。"],"intel":["據哥本哈根的報章所載，{wars}正交戰，{peace}維持和平。","我所掌握的消息是：{wars}已開戰，{peace}相安無事。"]}}],"Poland":[{"name":"斯拉夫族長","title":"族長","era":"約西元前 5 世紀～西元 5 世紀（維斯瓦河流域早期斯拉夫部族）","tone":"質樸、沉穩，像森林裡的長者；語句短，常用河、林、雷、火堆、蜂蜜酒作比喻，自稱「我／吾」","portrait":"pl-historical-age0","lines":{"intro":["我是維斯瓦河畔的族長，林子與河水養活我們的人。","遠方來的君主，願雷神佩倫看顧你我的相遇。"],"contact":["你的人踏進了我們的林子，這片木寨是我族的家。","河邊的木牆不高，守著它的人卻不會退。"],"war":["你侵擾我們的獵場太久，今日吾族拿起長矛了。","森林不會替你讓路，我的戰士也不會。"],"warReply":["你要打？好，維斯瓦河的水會記住誰先動手。","吾族在林中生長千年，不怕再多一個敵人。"],"peace":["打得夠久了，讓我們在火堆旁把矛放下吧。","我願送上蜂蜜酒與琥珀，換兩族的安寧。"],"accept":["好，吾以雷神之名起誓，兩族從此不相犯。","把這串琥珀收下，它是我們友誼的憑證。"],"reject":["你的話像秋天的葉子，落得太快，我不信。","先把你的人從我們的田裡撤走，再談和平。"],"rebuff":["你不要安寧，那就由風和林子替我回答你。","吾已伸出手，你不接，來日別怪我收回。"],"betray":["誓言是對族人立的，不是對外人，我要拿回獵場。","你的田開到了我們林邊，這約，我守不下去了。"],"truceEnd":["火堆熄了，約定也到頭，往後各憑本事。","休戰的日子過去了，我的戰士又磨起了矛。"],"attacking":["吾族的戰士已渡河，很快就到你的城牆下。","林中的號角響了，整個部族都在往你那裡走。"],"attacked":["木寨在燒，可我的族人還站在牆上。","你打到了家門口，但林子還沒放棄我們。"],"defeated":["河水會繼續流，總有一天，我的子孫會回來。","把我的族人當人看待，這是我最後的請求。"],"victory":["林子與河水站在我們這邊，今日吾族勝了。","回去告訴你的人：斯拉夫人只想守自己的家。"],"allyAccept":["好，你的敵人就是我的敵人，我們同一個火堆。","吾族與你結盟，冬天的糧食也可以分你一半。"],"allyReject":["我的族人不習慣替外人打仗，這盟約我不結。","林子夠深，我們自己守得住，不必綁在一起。"],"greetFriendly":["遠方的朋友，來火堆旁坐，吾這有蜂蜜酒。","維斯瓦河水清，你的信也清。吾記住你了。"],"greetCold":["林中風大，話不必多。你的信，吾看過了。","河有兩岸，你在那岸，吾在這岸。就這樣吧。"],"threatDefy":["雷在天上響，吾在林裡聽，從不曾怕過。","想砍這片林？先問問每一棵老橡樹答不答應。"],"threatYield":["火堆快熄了，吾的族人太少。你要什麼，說吧。","河水漲時，聰明的人先退到高處。吾退一步。"],"tributePay":["唉，這{gold}金幣拿去，別驚了林中的蜂群。","吾交出{gold}金幣，換族人冬天火堆不滅。"],"tributeRefuse":["蜂蜜是林子給的，不是給你的。吾一滴不給。","維斯瓦河從不向人低頭，吾的族人也一樣。"],"giftThanks":["好東西。今夜火堆旁，吾會講你的名字。","你送來的禮，比春天第一桶蜂蜜酒還甜。謝了。"],"intel":["獵人回報：{wars}在磨刀，{peace}與吾共飲蜂蜜酒。","林中的風告訴吾，{wars}是雷，{peace}是靜靜的河。"]}},{"name":"卡齊米日三世","title":"波蘭國王","era":"1333～1370 年在位","tone":"務實、有遠見、帶點自豪的建設者口吻；愛講磚石、法典、學院、商隊，重法治與商貿甚於征戰，自稱「朕」","portrait":"pl-historical-age1","lines":{"intro":["朕是波蘭國王卡齊米日，朕接手的是木造的王國。","與其在戰場上見，朕更願在克拉科夫的宴席上見你。"],"contact":["你看到的每一座磚石城堡，都是朕親手下令建的。","瓦維爾山上的宮牆，歡迎商旅，也記得防備來客。"],"war":["朕不輕易動武，但你踩過的界線，朕要用刀劃回來。","白鷹旗已升起，波蘭王國向你宣戰。"],"warReply":["你選擇了戰爭？磚石的城牆可比木牆難燒多了。","朕修了五十座城堡，正好讓你一座一座試。"],"peace":["打仗燒錢又燒城，不如坐下來談，朕願意先停手。","朕寧可用談判換一座城，也不願用千條人命換。"],"accept":["好，就依此約。朕的法典會把它寫進去，永不反悔。","和約既成，往後商隊往來，兩國都能富起來。"],"reject":["你的條件朕看過了，這不是和平，是要朕割地。","等你退回原來的邊界，朕再考慮停戰。"],"rebuff":["朕的提議是誠心的，你不要，那就各憑國力吧。","可惜，波蘭的磚石城牆等得起，你的糧草等得起嗎？"],"betray":["時勢變了，朕為王國的利益，只能收回這份和約。","一位國王最該守的是國土，不是一張羊皮紙。"],"truceEnd":["休戰期滿，朕已把國庫填滿、城牆修好了。","約定的日子到了，接下來的路，看你怎麼走。"],"attacking":["朕的騎士已從克拉科夫出發，白鷹將飛到你的城下。","朕平時修城，今日出兵，就是為了讓你知道差別。"],"attacked":["瓦維爾的城牆在震，但朕還坐在王座上。","你燒得掉市集，燒不掉朕寫進法典的東西。"],"defeated":["朕接手時是木造的波蘭，留下的是磚石的，記住這點。","王國可以倒，克拉科夫的學院和法典會留下來。"],"victory":["勝了。朕會把你的城修得比原本更堅固。","戰爭結束了，現在讓商人和石匠接手吧。"],"allyAccept":["朕答應結盟，朕在克拉科夫設宴，請各國君主同席。","好盟友比好城牆更值錢，朕與你並肩。"],"allyReject":["朕的王國正在修路建城，暫時不想捲進別人的戰事。","結盟要看利益相合，眼下朕看不出對波蘭的好處。"],"greetFriendly":["朕正巡視新築的磚牆，讀你的信，如見遠方商隊。","來信甚好。克拉科夫的城門，永遠為朋友敞開。"],"greetCold":["朕正忙於修訂法典，你的問候，容後再議。","磚石不會說客套話，朕也不必。信收到了。"],"threatDefy":["朕接手的波蘭是木造的，如今是磚石，燒不掉。","你帶劍來，朕帶法典與城牆。看誰站得久。"],"threatYield":["城牆尚未築完，朕不願讓商隊斷路。暫且退讓。","建設需要太平。為了學院與市集，朕忍這一回。"],"tributePay":["這{gold}金幣，本是要築城牆的，罷了，拿去吧。","朕付{gold}金幣，換商路暢通，算是划算的帳。"],"tributeRefuse":["國庫每一枚金幣，都要變成磚與書。一枚不給。","朕的鹽礦與市集不養強盜。要金幣，去做買賣。"],"giftThanks":["厚禮收下。朕會把它放進克拉科夫新學院裡。","有心了。商隊帶來貨物，朋友帶來情誼，朕都珍惜。"],"intel":["商隊回報：{wars}正在整軍，{peace}與朕互通市集。","據朕的使節所知，{wars}磨劍，{peace}修路。"]}},{"name":"揚三世·索別斯基","title":"波蘭國王暨立陶宛大公","era":"1674～1696 年在位（1683 年維也納之戰）","tone":"豪邁、虔誠、軍人本色；愛談翼騎兵與衝鋒，把自己視為基督教世界的盾牌，對議會貴族略帶無奈，自稱「朕」","portrait":"pl-historical-age2","lines":{"intro":["朕是揚·索別斯基，波蘭國王，翼騎兵的統帥。","聯邦的土地從波羅的海一路延伸到大草原，你來自哪裡？"],"contact":["你的人見到的是聯邦的城，城裡的貴族各有各的脾氣。","看見城門上的白鷹和騎士了嗎？那是波蘭與立陶宛。"],"war":["朕的翼騎兵翅膀已裝上，聯邦向你宣戰！","朕不是好戰之人，但你逼朕拔出了軍刀。"],"warReply":["宣戰？很好，維也納城下的敵人也曾這麼自信。","來吧，朕會親自帶隊衝鋒，這是朕最擅長的事。"],"peace":["朕打過的仗夠多了，願與你握手，讓士兵回家收麥。","停戰吧，朕想回維拉努夫的莊園種花，而不是打仗。"],"accept":["朕接受。以上帝之名，聯邦會守住這份約定。","好，讓議會的老爺們也少吵一件事。"],"reject":["你的和約寫得漂亮，可朕的騎兵還沒吃過敗仗。","等你的軍隊退出聯邦的土地，朕再談。"],"rebuff":["朕伸出的是手，你若不接，下一次見的就是軍刀。","可惜，朕本想給你一個體面收場的機會。"],"betray":["你在朕背後和朕的敵人來往，這約朕不守了。","聯邦的安危高於一紙和約，翼騎兵重新上馬。"],"truceEnd":["休戰結束，朕的馬已餵飽，羽翼也擦亮了。","安靜的日子到頭了，接下來，看誰的騎兵更快。"],"attacking":["翼騎兵已列陣衝鋒，聽見那翅膀的呼嘯聲了嗎？","朕親自領軍出征，就像當年馳援維也納那樣。"],"attacked":["城牆破了幾處，但朕還在馬上，還握著軍刀。","朕曾為別人的都城解圍，如今卻要守自己的。"],"defeated":["朕來過，朕見過，這一次，上帝沒有站在朕這邊。","替朕告訴瑪麗森卡，朕到最後都沒有下馬。"],"victory":["我們來了，我們看見了，上帝勝利了。","勝利歸於上帝與翼騎兵，朕只是騎在最前面而已。"],"allyAccept":["好，聯邦與你並肩。朕的騎兵到得比你想的快。","朕曾為盟友千里馳援，對你，朕也會這麼做。"],"allyReject":["議會的貴族們不會答應，朕的軍費也撐不起兩場仗。","朕的盾牌已經朝著南方，暫時分不出力氣給你。"],"greetFriendly":["朕剛從馬背上下來，讀你的信，比酒還暖。","來信甚喜。翼騎兵的翅膀為敵人而張，酒杯為朋友而舉。"],"greetCold":["朕的時間留給軍營與禱告，客套話免了。","議會的貴族已經夠吵了，你就別再多說。"],"threatDefy":["維也納城下，朕見過更大的軍勢。你這算什麼？","翼騎兵一衝，天地都要讓路。你敢擋，便來試。"],"threatYield":["議會不肯撥軍餉，朕的騎兵也得吃飯。這回暫忍。","願上主賜朕忍耐。今日退一步，非因怕你，而是無兵可派。"],"tributePay":["{gold}金幣拿去，這本是翼騎兵的軍餉，唉。","朕付{gold}金幣，只為讓騎兵養精蓄銳，來日再戰。"],"tributeRefuse":["朕在維也納擋住了大軍，豈會向你低頭獻金？","基督教世界的盾牌不納貢。要金幣，先過翼騎兵這關。"],"giftThanks":["好禮！朕會在彌撒後與弟兄們同享，願主保佑你。","此禮朕收下了。下回出征，替你多衝一陣。"],"intel":["斥候回報：{wars}已在邊境集結，{peace}與朕並肩同盟。","朕的探馬說，{wars}正磨刀霍霍，{peace}尚守和約。"]}},{"name":"塔德烏什·柯斯丘什科","title":"起義最高統帥","era":"1794 年領導起義（1746–1817）","tone":"剛毅、理想主義、平民氣息；把自由與人民掛在嘴邊，不擺架子，語氣像戰友而非君王，自稱「我」","portrait":"pl-historical-age3","lines":{"intro":["我是柯斯丘什科，波蘭起義的統帥，不是什麼國王。","我曾在大西洋彼岸為別人的自由築堡，如今回來守自己的。"],"contact":["你看到的城已被鄰國瓜分過兩次，人民卻還沒放棄。","城牆不高，可守城的是農民、市民和士兵，人人都自願。"],"war":["你要奪走我們僅剩的土地，那麼波蘭人民向你宣戰。","我在克拉科夫廣場立過誓，為自由而戰，絕不退讓。"],"warReply":["宣戰？我們早就被三個強鄰圍著，不差你一個。","來吧，鐮刀兵在拉茨瓦維采證明過，農民也能打贏大砲。"],"peace":["我不為榮耀打仗，只為人民。若能停戰，我願意先談。","讓農民回田裡收成吧，這場仗已經拖太久了。"],"accept":["好，我以人民的名義接受，波蘭人說話算話。","停戰對雙方的百姓都好，這比任何勳章都重要。"],"reject":["你的條件是要我們交出自由，這一點，我不能簽。","我發過誓只為國土完整而用權，割地的和約我不接受。"],"rebuff":["你不願停戰，那我只能回到戰壕，和弟兄們一起。","可惜，我本想讓兩邊的農民都早點回家。"],"betray":["人民受苦時，一紙停戰約束不了我，我必須重新拿起劍。","我為此感到抱歉，但自由等不了，波蘭再次起義。"],"truceEnd":["休戰到期了。這段日子我們沒閒著，鐮刀都磨好了。","約定的和平結束，接下來，波蘭人自己決定命運。"],"attacking":["農民扛著鐮刀、市民扛著槍，我們全都朝你那裡去了。","我穿著農民的粗呢外套上陣，因為這是人民的軍隊。"],"attacked":["華沙的街壘在崩，可街上每個人都還握著武器。","我們可能守不住城，但你奪不走波蘭人想自由的心。"],"defeated":["我倒下了，但波蘭沒有結束，只要還有人記得她。","請善待農民，他們為自由流的汗，比我的更多。"],"victory":["這不是我的勝利，是每一位扛著鐮刀的農民的勝利。","我們贏了。現在，讓人民自己決定要怎麼活。"],"allyAccept":["好，波蘭人懂得被圍困的滋味，我們願與你並肩。","我曾為別人的獨立打過仗，這一次，我們互相幫忙。"],"allyReject":["我們的兵力連守住自己都勉強，實在分不出去。","我的劍只為波蘭的獨立出鞘，別人的戰爭我不參與。"],"greetFriendly":["朋友，我穿著農民的粗布外衣回你信，別見怪。","你的信讓營地裡多了點暖意。自由的人，都是同伴。"],"greetCold":["我沒空寒暄，鐮刀兵還等著我操練。信收到了。","客套留給宮廷吧，我只認站在人民這邊的人。"],"threatDefy":["拉茨瓦維采的農民用鐮刀擋過大砲，我們不怕你。","你可以威脅我，但威脅不了一個想要自由的民族。"],"threatYield":["火藥不足，弟兄們也累了。我暫且退，但不是屈服。","為了讓更多人活著見到自由，這一回我讓步。"],"tributePay":["這{gold}金幣是弟兄們湊的，拿去吧，別再逼人民了。","我交出{gold}金幣，換弟兄們一時喘息，我記著這筆帳。"],"tributeRefuse":["人民的血汗不是貢品。一枚金幣也不給。","我為自由打仗，不為貢品打仗。你找錯人了。"],"giftThanks":["謝了，同伴。這份禮我會分給營裡的弟兄。","真心的禮物，比勳章更重。我替鐮刀兵們向你致謝。"],"intel":["農民探子回報：{wars}正逼近邊境，{peace}願與我們並肩。","據弟兄們打聽，{wars}在集結，{peace}還信守諾言。"]}}],"Ukraine":[{"name":"阿特亞斯","title":"斯基泰王","era":"約西元前4世紀（約前429～前339年）","tone":"直率豪邁的草原老王，輕視城牆與宮殿，愛馬勝過一切，語句短而硬，帶著長者的從容與傲氣。","portrait":"ua-historical-age0","lines":{"intro":["吾乃斯基泰之王阿特亞斯，草原無邊，皆是吾馬蹄所及之地。","你住在石牆裡？吾聽馬嘶勝過聽笛聲，不必為吾築宮殿。"],"contact":["你的人馬踏進了草原，記住，這裡沒有路，只有吾的箭程。","看見那些馬車與帳篷了嗎？那便是吾的都城，它會移動。"],"war":["你把手伸得太長了。斯基泰的箭雨，將回答你的貪心。","草原之王不受人差遣。備好你的盾吧，馬蹄聲已經響起。"],"warReply":["你要找吾決戰？先找到吾再說，草原會把你的軍隊拖垮。","好，吾這把年紀還提得起弓，就讓你見識老王的箭法。"],"peace":["戰馬也需要飲水歇息。停一停吧，草原夠大，容得下兩族。","吾不愛無謂的殺戮。以馬奶酒為誓，今日暫且收弓如何？"],"accept":["好，吾收弓。斯基泰人以酒立誓，此諾不會輕易毀去。","你說得有理，草原上的朋友比敵人更難得，吾應了。"],"reject":["現在才想談？吾的弓已經拉滿，箭離弦前不談停戰。","你的話像草原的風，來得快去得也快，吾不信。"],"rebuff":["不肯？也罷，草原之王不會求人第二次。","你拒絕了老人的善意，往後箭矢飛來，別怪吾沒說過。"],"betray":["風向變了，草原的規矩也跟著變。今日起，誓約作廢。","你的城太富足，吾的族人太飢餓，此誓吾不守了。"],"truceEnd":["休戰的日子到頭了。馬已養肥，弓已上弦，各憑本事吧。","約定的時日已滿，從今往後，草原不再替你擋風。"],"attacking":["聽見了嗎？那不是雷聲，是斯基泰萬馬奔向你的城。","吾的騎手已經出發，他們射箭時連回頭都不必。"],"attacked":["帳篷可以再搭，馬群可以再養，你以為這樣就贏了吾？","吾的營地起火了……但斯基泰人從不守城，族人會回來。"],"defeated":["九十年的風霜，吾終於倒在馬背之下……草原，會記得吾。","把吾葬在高高的土丘下，與吾的馬同眠，風會替吾說話。"],"victory":["草原贏了。你的城牆擋得住風，卻擋不住斯基泰的箭。","回去告訴你的人，馬嘶之聲，勝過世上所有的笛音。"],"allyAccept":["好，吾與你共飲一杯。從今以後，吾的箭只射你的敵人。","草原上的盟友，比黃金更貴重。吾的馬群，也為你奔跑。"],"allyReject":["斯基泰人的馬，不與城裡人同行，此盟吾不結。","你要的是吾的弓，不是吾的友情。吾看得出來，回去吧。"],"greetFriendly":["來者是客。草原的風把你的信吹到吾帳前，坐下喝一碗馬奶。","吾年紀大了，但眼睛還亮。你這信寫得誠懇，吾記住了。"],"greetCold":["吾的馬比你的信有趣。有事就說，別繞彎。","住在城牆裡的人，說話總是太長。吾聽完了，就這樣。"],"threatDefy":["吾的箭能射穿盾牌，也射得穿你的大話。想來就來。","草原沒有城牆，正好讓你的兵跑到累倒。吾等著。"],"threatYield":["馬群今年瘦了，吾不想打這一仗。你要的，吾考慮。","吾老了，不與你爭。把你的兵撤遠一點，草原還是安靜的好。"],"tributePay":["{gold}金幣拿去。吾寧可給金子，也不給馬。","吾送你{gold}金幣，換草原一年安寧。別再來第二次。"],"tributeRefuse":["吾的金子在馬背上，你要就自己來搶。","斯基泰人只向弓箭低頭，不向書信低頭。一枚也沒有。"],"giftThanks":["好東西。吾收下了，回頭送你一匹草原的好馬。","你的禮物比城裡人的笛聲好聽多了。吾謝你。"],"intel":["吾的探馬回報：與{wars}正在交戰，與{peace}相安無事。","草原上風聲快。{wars}是吾的敵人，{peace}暫時算朋友。"]}},{"name":"弗拉基米爾一世（沃洛基米爾大帝）","title":"基輔大公","era":"西元980～1015年在位","tone":"由勇武征戰轉為虔敬東正教的君主，威嚴中帶著慈父般的大度，常提上帝、宴席與羅斯之地，用語莊重。","portrait":"ua-historical-age1","lines":{"intro":["本王弗拉基米爾，基輔大公。第聶伯河兩岸，皆是羅斯之地。","願上帝賜你平安。基輔的宴席永遠備著，只看你是客是敵。"],"contact":["你的人看見第聶伯河上的城了嗎？那便是基輔，羅斯諸城之母。","這是羅斯的土地，旅人可來，商隊可來，但兵馬請留在河對岸。"],"war":["本王曾以劍統一羅斯諸部，今日仍能提劍。宣戰吧，願上帝裁決。","你觸犯了羅斯的疆界。基輔的親兵隊已披甲，本王不再忍讓。"],"warReply":["你向羅斯宣戰？本王年輕時走過的戰場，比你城裡的街道還多。","既然你選了刀劍，本王便以刀劍相迎。願上帝憐憫你的士卒。"],"peace":["受洗之後，本王明白了寬恕的分量。放下刀劍，來基輔赴宴吧。","兩國的百姓都累了。本王提議停戰，讓農人回田，商船回河。"],"accept":["好，本王應允。以十字架為證，羅斯人說出的話不會收回。","上帝喜愛和平的人。今晚基輔設宴，替你的使者留一席。"],"reject":["停戰？你的軍隊還踩在羅斯的田地上，本王如何信你？","本王寬恕罪人，但不縱容賊人。先退兵，再談和平。"],"rebuff":["你拒絕了？可惜，本王本想與你分享基輔的蜜酒。","和平的手你不接，那就別怪羅斯的劍不客氣了。"],"betray":["本王曾立誓，如今收回。羅斯的疆土，比一紙盟約更重要。","願上帝原諒本王今日所為。停戰結束了，基輔的旗幟再度出城。"],"truceEnd":["約定的年月已盡。本王守了諾言，往後之事，各憑實力。","休戰到期了。羅斯的親兵隊重新集結，願你也已準備妥當。"],"attacking":["基輔的大軍已渡過第聶伯河。本王親自領軍，向你的城而來。","聽，那是羅斯戰士的盾牌撞擊聲。本王的軍隊，已在路上。"],"attacked":["基輔的城牆在震動……但教堂的鐘還在響，羅斯還沒倒下。","你打到了本王的城下。很好，本王正想親眼看看你的勇氣。"],"defeated":["基輔陷落了……願上帝保佑羅斯的子民，他們會再站起來。","本王的時代到此為止。但第聶伯河的水，會一直流下去。"],"victory":["羅斯勝了！今晚基輔全城設宴，本王要讓所有人都吃飽。","勝利歸於上帝，也歸於羅斯的戰士。本王將建一座新教堂。"],"allyAccept":["好，羅斯與你結盟。本王曾與君士坦丁堡聯姻，深知盟約的價值。","盟友的敵人就是羅斯的敵人。基輔的親兵隊，隨時為你出征。"],"allyReject":["本王不能與你結盟。羅斯的劍，只為羅斯與上帝而拔。","你的提議本王聽過了。但基輔此刻不需要新的盟友，只需要安寧。"],"greetFriendly":["願上帝保佑你。本王的宴席為遠客常開，基輔的蜜酒等著你。","羅斯之地歡迎善意的鄰人。你的信本王讀了，心裡歡喜。"],"greetCold":["本王收到信了。上帝教人寬容，但本王不必與每個人談心。","基輔的城門為朋友開，你還算不上。信已閱，去吧。"],"threatDefy":["本王曾親率戰船順第聶伯河而下，你的恐嚇嚇不了羅斯。","上帝與羅斯同在。想試本王的劍，就到基輔城下來。"],"threatYield":["本王受洗之後，不願再多流一滴血。你的要求，本王會斟酌。","羅斯之地剛安定，本王不願百姓再受兵災。暫且依你。"],"tributePay":["本王從國庫撥{gold}金幣給你，只求羅斯百姓得享太平。","{gold}金幣送去。本王寧可散財，也不讓基輔的教堂蒙塵。"],"tributeRefuse":["本王的金子用來蓋教堂、施濟窮人，沒有一枚是給你的。","羅斯大公只向上帝獻禮。你的要求，本王不允。"],"giftThanks":["這份心意本王收下了。願上帝賜福於你，宴席上為你留一席。","好禮物。本王會分一些給基輔的窮人，這才合上帝的心意。"],"intel":["本王的使者帶回消息：與{wars}兵戎相見，與{peace}守約和睦。","羅斯的敵人是{wars}，願上帝讓{peace}與本王長久為友。"]}},{"name":"博赫丹・赫梅利尼茨基","title":"扎波羅熱哥薩克統領（蓋特曼）","era":"1648～1657年任統領（生卒1595～1657）","tone":"火爆熱血的哥薩克首領，善於演說、講義氣、口稱弟兄，帶草原自由精神，也有精明的外交算計。","portrait":"ua-historical-age2","lines":{"intro":["我是博赫丹・赫梅利尼茨基，扎波羅熱哥薩克之統領。","哥薩克不向任何人下跪。你若以禮相待，我便以酒相迎。"],"contact":["你的人看見了西奇？那是哥薩克的營寨，自由人的家。","歡迎來到第聶伯河下游，這裡的人只聽哥薩克大會的決議。"],"war":["你以為哥薩克會忍氣吞聲？弟兄們，上馬！我們去討公道。","我曾被奪去田產、羞辱家人，這種事我不會再忍第二次。"],"warReply":["你向哥薩克宣戰？很好，我們的馬刀早就等得不耐煩了。","來吧，草原上的每一個哥薩克，都是天生的戰士。"],"peace":["打了這麼久，該讓弟兄們回家收麥子了。我提議停戰。","哥薩克懂得打仗，也懂得談判。停戰吧，條件我們坐下來談。"],"accept":["好，一言為定。哥薩克大會已經舉手通過，我以權杖起誓。","成交！今晚營地開酒桶，你的使者也一起來喝一杯。"],"reject":["停戰？你先前的承諾還沒兌現，哥薩克不會再上第二次當。","弟兄們的傷還沒好，你就想握手言和？辦不到。"],"rebuff":["不接受？隨你。哥薩克的手伸出去一次，不會伸第二次。","你拒絕了草原的好意。那就等著看哥薩克的騎兵吧。"],"betray":["情勢變了，哥薩克必須選對自己有利的一邊。這份停戰，作廢。","別怪我。為了讓弟兄們活下去，我什麼盟約都可以撕。"],"truceEnd":["休戰期滿了。哥薩克守了約，現在該重新拿起馬刀了。","約定的日子過去了，弟兄們，把馬鞍重新綁緊吧。"],"attacking":["哥薩克的馬隊出發了！草原的塵土，就是我們的戰旗。","我親自帶隊，弟兄們唱著歌上路，目標是你的城門。"],"attacked":["營寨要守不住了……但哥薩克從不投降，只會換個地方再戰。","你打到我的營地了。好，那就讓你看看哥薩克是怎麼守家的。"],"defeated":["我倒下了，但哥薩克的自由，不會跟著我一起埋進土裡。","弟兄們……替我看著第聶伯河，總有一天，這裡會再響起歌聲。"],"victory":["哥薩克贏了！弟兄們，開酒桶、彈起班杜拉，今晚唱到天亮！","自由的人打敗了想奴役我們的人。這就是哥薩克的道理。"],"allyAccept":["好，結盟！哥薩克講義氣，只要你不背叛，我們就並肩到底。","盟友來了！弟兄們，多備一份麵包和鹽，這是待客的規矩。"],"allyReject":["結盟？哥薩克吃過太多虧，我得先看看你值不值得信任。","不了。哥薩克大會沒有通過，我這個統領也不能一個人說了算。"],"greetFriendly":["哈！好信！弟兄們，倒酒！西奇歡迎說話直爽的朋友。","我讀了你的信，像草原的風一樣痛快。有空來營地喝一杯。"],"greetCold":["信收到了。哥薩克交朋友看的是行動，不是漂亮話。","我忙著帶弟兄們打仗，沒空跟你客套。有事直說。"],"threatDefy":["想嚇哥薩克？我的馬刀還沒生鏽，弟兄們的火槍也還熱著。","自由的人不怕威脅。你敢來草原，我的弟兄們就敢迎上去。"],"threatYield":["弟兄們剛打完仗，馬瘦人疲。這回我讓一步，別逼太緊。","好吧，統領也得算帳。今天先依你，草原的帳以後再算。"],"tributePay":["{gold}金幣，拿去！弟兄們的性命比金子貴，我認了。","我付{gold}金幣，換弟兄們一季平安。這不是怕你，是精算。"],"tributeRefuse":["哥薩克的金子是用命換來的，一枚也不會白白給你。","要貢品？弟兄們聽了會笑掉牙。西奇不向任何人納貢。"],"giftThanks":["好禮物，夠大方！弟兄們，今晚為這位朋友乾一杯！","哥薩克記恩也記仇。你送的禮，我博赫丹記在心上了。"],"intel":["探子剛回營：我們正跟{wars}交手，跟{peace}暫時和好。","弟兄們的馬刀對著{wars}；至於{peace}，先當朋友看待。"]}},{"name":"塔拉斯・舍甫琴科","title":"民族詩人・民族覺醒領袖","era":"1814～1861年（活躍於1840～1861）","tone":"悲憫而剛毅，以筆為武器，心繫農奴與鄉親，對強權不卑不亢，語句帶詩意與土地情感，自稱「我」。","portrait":"ua-historical-age3","lines":{"intro":["我是塔拉斯・舍甫琴科，一個從農奴變成詩人的烏克蘭人。","我沒有王冠，只有一支筆和一本詩集，卻替千萬人說話。"],"contact":["你看到的不是宮殿，是農舍與麥田。這裡的人民，才是我的城。","第聶伯河在這裡轉彎。請放輕腳步，這片土地受過太多苦。"],"war":["我厭惡戰爭，但更厭惡看人被奴役。既然如此，我們只能起身。","詩寫盡了，忍耐也盡了。烏克蘭的鄉親，今日要為自己而戰。"],"warReply":["你要向一群農人與詩人開戰？好，你會發現他們並不軟弱。","我曾被流放十年，禁止寫作與繪畫，我都熬過來了，不怕你。"],"peace":["夠了，田地已經荒了太久。放下武器，讓孩子們回學堂吧。","我提議停戰。真正的敵人不是彼此，而是讓人們受苦的枷鎖。"],"accept":["我接受。願這片土地上，再也聽不到母親為兒子哭泣的聲音。","好，就此停手。我會把今天寫進詩裡，讓後人記得和平的模樣。"],"reject":["你的和平，是要我們繼續低頭的和平嗎？那我寧可不要。","話說得再漂亮，鐐銬還是鐐銬。先解開它，再來談停戰。"],"rebuff":["你拒絕了……也罷，我早已習慣強者不聽弱者說話。","和平的話你聽不進去，那就讓歷史替我們評理吧。"],"betray":["原諒我。當我看見鄉親仍在受苦，任何約定我都無法再守。","這份停戰換不來自由，那它就沒有意義。我收回我的簽名。"],"truceEnd":["約定的日子到了。這段安寧，我沒有浪費，人們已重新站直了。","休戰結束。願你記得，這段日子田裡長出的是麥子，不是仇恨。"],"attacking":["鄉親們出發了。他們沒有華麗的鎧甲，只有不願再跪下的決心。","歌聲從村莊裡傳出來，那是人們走向你城門的腳步聲。"],"attacked":["村莊在燃燒……但你燒不掉歌謠，也燒不掉人們的記憶。","你已打到家門口。但烏克蘭人跌倒過太多次，早學會站起來。"],"defeated":["我死後，請把我葬在高崗上，在遼闊草原，在親愛的烏克蘭。","我的筆停了……但詩已經傳開，總有一天，鄉親會替我讀完它。"],"victory":["我們贏了。不是靠刀劍，是靠一群不肯再當奴隸的人。","請記住今天：烏克蘭的農人，也能挺直腰桿站在勝利者的位置。"],"allyAccept":["我願意。只要你尊重這片土地上的人，我們就是朋友。","握手吧。受過苦的人最懂得珍惜盟友，我不會讓你失望。"],"allyReject":["我不能與你結盟。我這一生，已經看過太多打著友誼旗號的枷鎖。","請恕我拒絕。人民還沒信任你，我不能替他們簽下名字。"],"greetFriendly":["謝謝你的信。第聶伯河今天很藍，願你那邊的天空也一樣。","一個農奴的兒子也有朋友，我很珍惜。請代我問候你的鄉親。"],"greetCold":["我讀了信。可是我的筆此刻正忙著寫鄉親的苦，恕不多談。","客氣話我聽過太多，多半出自不種田的人。有事請直說。"],"threatDefy":["沙皇奪走我的筆和畫具，我照樣寫。你的威脅算什麼？","我沒有軍隊，只有詩。但詩能活得比任何強權都久。"],"threatYield":["我的身體已被流放磨壞了，經不起再一場風雨。你要什麼？","我不怕自己吃苦，只怕鄉親受牽連。這一次，我不與你爭。"],"tributePay":["這{gold}金幣是我賣畫所得，拿去吧，別再去驚擾村莊。","{gold}金幣給你。我的鄉親已經夠窮了，別再向他們伸手。"],"tributeRefuse":["我沒有金子，只有詩集和黑土的氣味，你要哪一樣？","一個農奴出身的人，最懂得不該把血汗錢交給強權。不給。"],"giftThanks":["謝謝你。這份禮讓我想起家鄉的櫻桃園，暖了流浪人的心。","我一生收過的善意不多，你這一份，我會寫進詩裡。"],"intel":["我聽鄉親們說：與{wars}正在交戰，與{peace}尚且平安。","戰火燒向{wars}的村莊，{peace}的田地還能安穩收割。"]}}],"Greece":[{"name":"亞歷山大大帝","title":"馬其頓國王","era":"前336～前323年在位","tone":"年輕氣盛、豪邁自信、志在征服世界、崇尚英雄榮耀，自稱寡人","portrait":"gr-historical-age0","lines":{"intro":["寡人是馬其頓的亞歷山大，世界的盡頭才是寡人的邊界。","亞里斯多德教寡人思考，父王教寡人征戰，今日輪到你認識寡人。"],"contact":["你的斥候看見的，是通往東方之路上的一座新城。","寡人所到之處皆建城，這座城也將以我為名。"],"war":["戈耳狄俄斯之結，寡人一劍斬斷；你的城牆也一樣。","馬其頓的長槍方陣已列陣，寡人親自率騎兵衝鋒。"],"warReply":["你敢向寡人宣戰？大流士的大軍尚且潰敗。","很好，寡人正愁找不到值得一戰的對手。"],"peace":["寡人的目光在更遠的東方，你我不必在此耗費兵力。","放下刀劍吧，寡人願與你共飲一杯和解的酒。"],"accept":["寡人接受。世界夠大，容得下你我同行。","既然如此，馬其頓與你之間，暫且息兵。"],"reject":["寡人不接受求和，除非你親自來到我的營帳前。","戰爭尚未分出勝負，談什麼停戰？"],"rebuff":["你拒絕寡人？那便由長槍替我說話。","可惜，寡人給過你機會了。"],"betray":["盟約是寫給凡人的，寡人志在天下。","寡人改變主意了，馬其頓大軍將再度前進。"],"truceEnd":["休戰結束，寡人的戰馬布西發拉斯已經不耐煩了。","和平只是休整，現在該繼續前進了。"],"attacking":["馬其頓的方陣已經出發，寡人親自走在最前線。","從格拉尼庫斯到高加米拉，寡人從未後退，今日亦然。"],"attacked":["城牆在崩塌？寡人尚未倒下，馬其頓就未曾戰敗！","縱使兵臨城下，寡人仍要親自舉劍迎戰。"],"defeated":["寡人的江山……就留給最強的人吧。","短暫而燦爛的一生，寡人無怨無悔。"],"victory":["寡人征服了你，如同征服波斯與埃及。","再往前，還有更遠的世界等著寡人。"],"allyAccept":["很好，你將與寡人共同見證世界的盡頭。","馬其頓的盟友，寡人待之如袍澤。"],"allyReject":["寡人只與夥伴同行，而你尚未證明自己。","結盟？寡人習慣獨自走在前面。"],"greetFriendly":["來自遠方的朋友，寡人歡迎你，一起共飲美酒吧。","你的問候傳到了軍營，寡人很高興結識新友。"],"greetCold":["寡人正忙著征討波斯，無暇與你寒暄。","問候收到了，但寡人的目光在東方的疆土。"],"threatDefy":["威脅寡人？高加米拉的波斯大軍都擋不住寡人的鐵騎。","對敢於嘗試的人，沒有辦不到的事，寡人不懼你。"],"threatYield":["寡人的軍隊尚在遠征途中，此刻暫且退讓一步。","好吧，寡人先退兵，但英雄的榮耀終會回來。"],"tributePay":["寡人暫且付你{gold}金幣，權當借你片刻威風。","這{gold}金幣拿去，寡人的兵鋒不久便會討回。"],"tributeRefuse":["向寡人索取貢品？波斯的財寶都歸馬其頓所有！","寡人只收貢品，從不納貢，你打錯了主意。"],"giftThanks":["好禮物！寡人會將它與戰利品一同帶到印度河畔。","多謝，朋友，寡人以美酒與馬其頓的友誼回敬你。"],"intel":["寡人與{wars}交戰，與{peace}和平，你站哪邊？","對手是{wars}，盟友是{peace}，寡人志在天下。"]}},{"name":"狄奧多拉（Theodora）","title":"拜占庭帝國皇后（查士丁尼一世之妻，與皇帝共治）","era":"527–548 年（查士丁尼一世在位期間）","tone":"高貴沉著、意志堅定，用字精煉帶鋒芒；自稱「本宮」，稱丈夫為「皇帝」，稱自己的國家為「羅馬」或「帝國」（拜占庭人自認是羅馬人）；面對威脅絕不示弱，談利益時卻務實精明，偶爾流露出身劇場、由平民登上后座的自信。","portrait":"gr-historical-age1","lines":{"intro":["本宮狄奧多拉，與皇帝共治羅馬。願你我以禮相交。","君士坦丁堡的城牆向來不懼風浪，你是客是敵，自己選。"],"contact":["看見金頂與高牆了嗎？那是新羅馬，世上最富的城。","聖索菲亞的穹頂正在升起，遠道之人，請懷敬意觀看。"],"war":["本宮已勸皇帝拔劍。羅馬的軍旗，明日便指向你的城。","你屢次挑釁，帝國不能再忍。這一戰，由本宮親自主張。"],"warReply":["宣戰？尼卡之亂本宮都未曾退縮，何況是你。","很好。本宮生於劇場，長於皇宮，從不畏懼一戰。"],"peace":["刀兵傷民亦傷國庫。本宮提議停戰，你我各自休養。","羅馬有更值得做的事，不願與你長年纏鬥。談和吧。"],"accept":["明智之舉。本宮以皇后之名應允，帝國必守信。","好，讓商船代替戰船往來，這對你我都划算。"],"reject":["現在才想談和？時機由本宮決定，不是你。","本宮讀了你的信，卻看不到誠意。羅馬不會停手。"],"rebuff":["你拒絕了？本宮不會再問第二次，後果自負。","可惜。本宮伸出的手不多，你錯過了一次。"],"betray":["情勢已變，舊約作廢。帝國的利益，永遠優先於盟書。","別怪本宮無情，是你的軟弱讓這份停戰失去價值。"],"truceEnd":["休戰的期限到了。本宮不多說，各憑本事吧。","安穩的日子過完了，羅馬的軍旗重新展開。"],"attacking":["貝利薩留的軍隊已經出發，你的城牆撐得住嗎？","本宮親自送大軍出城，他們不帶回勝利不會回來。"],"attacked":["城牆在震動，但本宮仍在皇宮。想要這座城，先來見本宮。","本宮不會逃。這件紫袍，是本宮最後也最高貴的壽衣。"],"defeated":["羅馬倒下了，但本宮至死穿著紫袍。這便是本宮的答案。","從劇場到皇宮，本宮這一生無憾。輪到你去面對命運了。"],"victory":["勝利歸於羅馬。本宮會在聖索菲亞為你的城祈禱。","看見了嗎？出身不決定命運，堅持才決定。"],"allyAccept":["本宮願與你結盟。皇帝的印璽，今日也為你而蓋。","羅馬的朋友不多，你是其中之一。別讓本宮失望。"],"allyReject":["結盟？帝國不需要靠不住的夥伴，你尚未證明自己。","本宮看人向來很準。這份盟約，暫時不簽。"],"greetFriendly":["來信收到了，本宮心情不錯。願你的城也風調雨順。","難得有君主懂禮數。本宮記住你了，這是好事。"],"greetCold":["本宮很忙，帝國的法典與教堂都等著本宮。有事直說。","問候收到。羅馬不缺問候，缺的是誠意。"],"threatDefy":["暴民曾把皇宮團團圍住，本宮都沒退，你嚇不倒本宮。","你的恐嚇，還不如競技場的喧鬧響亮。"],"threatYield":["本宮不與強者硬碰。這次，羅馬退一步。","好吧，帝國尚需喘息。你的要求，本宮暫且應允。"],"tributePay":["{gold} 金幣送去。記住，這是羅馬買的時間，不是屈服。","國庫撥出 {gold} 金幣給你。本宮記下了，日後總要算清。"],"tributeRefuse":["要羅馬的金幣？帝國的財富用來蓋教堂，不是送人。","本宮一枚金幣也不會給。想要，就自己來拿。"],"giftThanks":["禮物收到了，本宮很喜歡。羅馬記得每一位有心人。","多謝。本宮會把它擺在皇宮裡，讓使節都看見。"],"intel":["本宮的耳目遍布各國。羅馬正與 {wars} 交戰，與 {peace} 相安。","你想知道？好，敵人是 {wars}，朋友是 {peace}，就這麼多。"]}},{"name":"君士坦丁十一世","title":"拜占庭末代皇帝","era":"1449～1453年在位","tone":"悲壯堅毅、榮譽至上、明知不敵仍死守到底，自稱朕","portrait":"gr-historical-age2","lines":{"intro":["朕是君士坦丁，羅馬人最後的皇帝，仍守在這座千年之城。","帝國只剩一城，但朕的榮譽從未縮小。"],"contact":["你看到的是君士坦丁堡，狄奧多西城牆守了它一千年。","金角灣的鐵鍊已拉起，這座城不輕易對外人開門。"],"war":["朕兵力雖少，但守城之人皆願為此城而戰。","拜占庭不會坐以待斃，朕親自披甲出擊。"],"warReply":["又一個要取這座城的人？朕的城牆等著你。","朕已無退路，向朕宣戰者，只會見到朕的劍。"],"peace":["此城需要喘息，朕願以停戰換取修補城牆的時間。","刀劍暫歇吧，朕想讓百姓再看幾次聖索菲亞的日出。"],"accept":["朕接受，這座城多一分安寧，便多一分希望。","願和平比城牆更久長，朕與你立約。"],"reject":["交出此城不在朕的權限之內，停戰也一樣。","朕不信你的停戰，你的軍隊仍在城外紮營。"],"rebuff":["你拒絕了，那麼朕只能回到城牆上去。","無妨，朕早已習慣獨自堅守。"],"betray":["援軍終於到了，朕不能再讓帝國坐等衰亡。","為了這座城的存續，朕必須打破和約，願上主寬恕。"],"truceEnd":["休戰結束，城牆已修好，朕重新拿起長劍。","和平的日子太短，朕再度登上城樓。"],"attacking":["朕率領全城軍民出擊，人數雖少，志氣不減。","熱那亞與威尼斯的勇士與朕同行，今日一戰。"],"attacked":["城牆已破，但朕還活著，朕便與此城同在。","朕卸下皇袍徽記，與士兵一同守最後一道門。"],"defeated":["城已陷落，而朕仍在此，那就讓朕以士兵之身終結吧。","一千年的帝國到此為止，願後人記得我們曾守到最後。"],"victory":["此城又一次挺過了圍攻，這是千年城牆的奇蹟。","感謝上主，拜占庭的雙頭鷹今日仍在飛翔。"],"allyAccept":["朕接受同盟，帝國需要每一位願意伸手的朋友。","西方遲遲不來，而你來了，朕記住這份情義。"],"allyReject":["朕曾為求援軍讓步太多，如今不願再輕許盟約。","拜占庭寧可獨守，也不與居心叵測者結盟。"],"greetFriendly":["感謝你的問候，朕在圍城之中仍為友人祈福。","城牆外敵軍環伺，你的來信是朕難得的慰藉。"],"greetCold":["朕無暇寒暄，君士坦丁堡的城牆正需要朕。","問候收到了。但此刻朕心中只有這座城。"],"threatDefy":["朕連鄂圖曼的大軍都不懼，你的威脅又算什麼。","朕寧與這座城同存亡，也不會向威脅低頭。"],"threatYield":["朕的兵力所剩無幾，只能暫且退讓，保全百姓。","為了城中的子民，朕此刻不得不忍下這口氣。"],"tributePay":["國庫僅存{gold}金幣，朕交給你，願換得片刻安寧。","朕付你{gold}金幣，只求你莫在此時攻打此城。"],"tributeRefuse":["朕的金幣要用來修補城牆，一枚也不能給你。","羅馬的皇帝寧可戰死，也不向他人納貢。"],"giftThanks":["在這危急之時，你的禮物如同雪中送炭，朕深謝。","感謝你的厚禮，朕將與守城將士共享此恩。"],"intel":["朕與{wars}交戰，與{peace}尚有和約，盼你援手。","圍城之敵是{wars}，友邦是{peace}，援軍未至。"]}},{"name":"布布利娜（Laskarina Bouboulina）","title":"希臘獨立戰爭海軍指揮官、斯佩察島船東","era":"1771–1825（活躍於 1821–1825 希臘獨立戰爭初期）","tone":"直率剛毅，說話像船長下令，短句多；常提船、砲、家產與自由，不擺君主架子，自稱「我」。","portrait":"gr-historical-age3","lines":{"intro":["我是斯佩察島的布布利娜，艦隊是我變賣珠寶換來的。","別看我是女子，愛琴海上沒有人敢小看我的旗艦。"],"contact":["你的人看見的是斯佩察島，家家戶戶都有人在海上。","港裡停的是阿伽門農號，十八門砲，全是我出的錢。"],"war":["我的船已經升旗出港，這次要打的是你。","我的旗上寫著：帶盾歸來，或躺在盾上。開戰！"],"warReply":["你要打我？我連鄂圖曼的艦隊都不怕，何況是你。","好，海上見。我的砲手早就等不及了。"],"peace":["我的錢該花在自由上，不是花在跟你耗。停戰吧。","船要修，人要歇，我提議暫時收起砲口。"],"accept":["好，我答應。斯佩察島的女子說話算話。","握手吧。我的砲口轉向別處，但眼睛還盯著你。"],"reject":["現在才談停戰？我的船已經封住了你的港口。","不行。我封鎖納夫普利翁時，也沒聽任何人求情。"],"rebuff":["不要就算了，海上的風向本來就不由人。","你拒絕了？好，那我就把話留給砲聲來說。"],"betray":["停戰到此為止。為了希臘，我顧不得名聲了。","我看清了，你和鄂圖曼沒兩樣。起錨，開砲！"],"truceEnd":["約定的日子到了，我的船又可以自由航行了。","休戰結束。接下來是戰是和，看你怎麼選。"],"attacking":["阿伽門農號領頭，全島的船都跟在我後面。","我親自站在船頭。你的港口，今天就會被封死。"],"attacked":["島上起火了，可是斯佩察的女人不會逃。","我把家產和兒子都獻給了自由，如今剩下的只有我。"],"defeated":["我這一生沒有低過頭，今天也一樣。","船沉了，人倒了，但希臘的旗還會有人舉起。"],"victory":["勝利了！這是用我全部的家產換來的。","我不是為了王座打仗，是為了希臘的自由。"],"allyAccept":["好，我加入。友誼社教我，同心的人才能成事。","你的旗和我的旗並排航行，鄂圖曼看了會發抖。"],"allyReject":["我自己出錢造船，就是為了不聽別人指揮。","結盟？我只和真心為自由奮戰的人並肩。"],"greetFriendly":["你的信到了斯佩察島，我在船上讀完，很高興。","歡迎到島上來，我請你喝杯咖啡，聽聽海上的消息。"],"greetCold":["信收到了。我在忙著封鎖港口，沒空多說。","問候就免了，海上的人只看船，不看客套話。"],"threatDefy":["嚇唬我？我出生在牢裡，什麼沒見過。","你的威脅我聽過了，現在換你聽我的砲聲。"],"threatYield":["我的船大半還在修，這次我先讓一步。","好吧，我退。但斯佩察的船總有修好的一天。"],"tributePay":["這 {gold} 金幣拿去，那本來是要造船的錢。","{gold} 金幣我付，但我的珠寶已經賣光了，別再來。"],"tributeRefuse":["我的錢只給希臘的自由，一枚也不給你。","要金幣？我連珠寶都賣了造船，哪裡還有多的。"],"giftThanks":["多謝你的禮物，我會把它變成船上的火藥。","海上的人不常收禮，這份心意我記在心裡了。"],"intel":["水手帶回消息：和我開戰的有 {wars}，休戰的有 {peace}。","我的船看得清楚：{wars} 在打我，{peace} 和我停戰。"]}}],"Canada":[{"name":"第一民族族長","title":"族長","era":"約西元前 800 年～西元 500 年（史前時期）","tone":"沉穩寡言，敬重土地與祖靈，說話像長者叮嚀，多用河流、森林、季節作比喻，不誇耀武力。","portrait":"ca-historical-age0","lines":{"intro":["遠方的來客，這片土地養育我們世世代代，請帶著敬意踏上它。","我是這裡的族長，河流與森林都認得我的腳步，你是誰？"],"contact":["你的獵人看見了我們的營地，營火邊有位子，但請放下長矛。","炊煙升起的地方是我們的家，來者是客，也要守我們的規矩。"],"war":["你們的人踏壞了我們的獵場，祖靈不容，我必須拿起長矛。","河水被你們攪濁了，族人忍無可忍，從今日起我們是敵人。"],"warReply":["你選擇了刀兵，那就來吧，這片森林會站在我們這一邊。","我族在這裡走過無數個冬天，不會因你一句話就退讓。"],"peace":["打夠久了，讓我們把武器埋進土裡，讓年輕人回去打獵。","冬天快到了，兩族都需要儲糧，我們停手吧，如何？"],"accept":["好，我接受。營火邊多一位朋友，總比多一個敵人來得好。","讓我們分享同一鍋獵物，從此你的族人走進我的林子不必害怕。"],"reject":["你的話像春天的冰，看著厚，一踩就裂，我不能相信。","族人的傷還沒好，現在談和平，太早了，請回去吧。"],"rebuff":["你不願停手嗎？那我只好告訴族人，繼續守住每一條河口。","我伸出的手被你推開了，祖靈看見了，後果由你承擔。"],"betray":["你的人越過了約定的河，既然約定已破，我也不再受它束縛。","族人告訴我，和你們共處只會失去更多，這份約定到此為止。"],"truceEnd":["約定的月亮已經圓過又缺，休戰結束了，各自守好自己的路。","休戰的日子過去了，我不主動出手，但也不會再退一步。"],"attacking":["獵人們已經出發，這次獵的不是鹿，是你們的營地。","獨木舟順流而下了，天亮之前，你會聽見我們的鼓聲。"],"attacked":["營火快要熄了，但只要還有一個族人站著，這裡就是我們的家。","你燒得掉我們的屋子，燒不掉祖先留在這片土地上的名字。"],"defeated":["我倒下了，但這片土地會記得我們，風會替我們繼續唱歌。","把我葬在河邊吧，讓我看著鮭魚回來，看著孩子們長大。"],"victory":["戰鬥結束了，我們不取你的性命，只請你記得這片土地的主人。","森林替我們作證，今天是我族的勝利，今晚營火會燒得很旺。"],"allyAccept":["好，從今天起你的獵場也是我的，我的獵場也是你的。","兩條河匯成一條會更寬闊，我們的族人也會這樣。"],"allyReject":["我還不認識你的心，結盟這件事，等下一個春天再說吧。","我族習慣獨自走自己的路，你的好意，我心領了。"],"greetFriendly":["遠方的朋友，願河水引你平安走到我的火堆旁。","森林告訴我今日有客，坐下吧，一同分享這季的收穫。"],"greetCold":["風把你的話帶來了，但祖靈尚未告訴我你的心。","河流不急著回應每一片落葉，我也一樣。"],"threatDefy":["冬天年年來，森林從未因此低頭，我族亦然。","這片土地養育我們千百個季節，不會因你一句話改變。"],"threatYield":["吾族人少，如溪水面對洪流，我會讓開，但不會乾涸。","為了孩子們能看見下一個春天，我暫且退入森林深處。"],"tributePay":["拿去吧，{gold}金幣，願它換得我族一個安穩的冬天。","我族以{gold}金幣換取和平，願祖靈記得今日的忍讓。"],"tributeRefuse":["土地的果實屬於土地上的人，我不會把它交給外來的手。","祖靈沒有教我們向人繳納什麼，河水也不向誰納貢。"],"giftThanks":["你的禮物像春天的第一場雨，我族會記住這份情誼。","收下了，願你的火堆長燃，獵徑上永遠有足跡。"],"intel":["我聽風說，{wars}正在交戰，{peace}則安於和平。","獵人說，{wars}動了干戈，{peace}仍守和睦。"]}},{"name":"迪甘納維達（Deganawida，和平締造者）","title":"易洛魁聯盟的和平締造者、大法的傳述者","era":"傳說約12～15世紀（易洛魁聯盟創立時期）","tone":"平和、沉穩、慈悲，語速緩慢；常用長屋、白松、火堆、一碗一匙等比喻；以「我」自稱，即使開戰也語帶遺憾，不辱罵、不誇耀。","portrait":"ca-historical-age1","lines":{"intro":["我是和平締造者，走遍長屋，只為讓各族的火堆同燃。","大法教我：先以善念相待，再談其餘。願你我如此。"],"contact":["你的人望見了我們的長屋。爐火正暖，請坐下說話。","白松之下埋著戰斧，樹梢有鷹守望。這裡是和平之地。"],"war":["我勸過三次，你仍不肯放下武器。長屋只好起身自衛。","大法賦予聯盟力量，不為征服，只為守住和平。我來了。"],"warReply":["你選了戰斧，我很遺憾。五族的火堆會一同守望長屋。","我的心仍向著和平，但我的族人不會任你踐踏。"],"peace":["夠了。讓我們把戰斧埋在白松下，讓大河沖走仇恨。","我帶著貝珠帶而來，上面織著和平的話語。請接下它。"],"accept":["好。從今日起，你我同吃一碗，共用一匙，不再相爭。","我的族人會記住這一天。願善念在你我之間生根。"],"reject":["你的話語裡沒有善念，只有算計。我不能接下這條貝珠帶。","真正的和平要用直心去換。等你的心直了，再來找我。"],"rebuff":["你拒絕了。我不氣惱，只為將要受苦的人們感到惋惜。","我會再來勸你。大法教我，善念要說三次才算盡力。"],"betray":["你在休戰時仍暗中傷我族人，這條貝珠帶已經斷了。","守護長屋是大法的命令。我不得不重新拿起戰斧。"],"truceEnd":["休戰的日子到頭了。是續上貝珠帶，還是各走各路？","約定期滿。我仍願意坐在同一堆火邊，你呢？"],"attacking":["五族的戰士已經出發。我不以此為榮，只求早日結束。","他們為守護長屋而行。等你願意談了，我隨時停下。"],"attacked":["長屋的柱子在搖晃，但議事的火還沒熄。我們還在。","若你還記得善念，現在便是停手的時候。"],"defeated":["白松倒了，但種子已撒進土裡。和平終會再長出來。","我把大法交給後人。願你有一天也懂得埋下戰斧。"],"victory":["戰事結束了。我不慶祝，只請各族回到火堆邊坐下。","勝利不是終點。把戰斧埋了，長屋歡迎你一同居住。"],"allyAccept":["歡迎進入長屋。你的火堆會在議事之地佔有一席。","大樹的根伸向四方，願你循著它走來。我們是一家了。"],"allyReject":["結盟要靠直心，不靠一時的方便。我看不到你的直心。","長屋的門沒關，但今天我還不能請你入座。"],"greetFriendly":["你的問候像春天的風，吹暖了我們的火堆。謝謝。","聽見你的話語，我很安心。願你的族人平安。"],"greetCold":["我收到了你的話。至於心意，還要看你日後怎麼做。","問候不必多說。長屋的門會為誠實的人而開。"],"threatDefy":["你用威嚇說話，我用大法回答。五族的火堆不會熄。","我曾勸服比你更兇的人放下戰斧。你的恐嚇動不了我。"],"threatYield":["我的族人尚少，不願與你相爭。請告訴我，你要的是什麼。","好吧，我退一步。為了族人平安，我暫且忍下這口氣。"],"tributePay":["這 {gold} 金幣拿去吧。願它換來族人一季的安寧。","我不願族人受苦。{gold} 金幣送上，請收起戰斧。"],"tributeRefuse":["長屋不向威嚇低頭。我們的財物只與朋友分享。","你要的不是禮，是屈服。這一點我給不起。"],"giftThanks":["我收下你的禮，也記下你的心意。長屋會回以善念。","禮物讓火堆更暖。願這份情誼像白松一樣長青。"],"intel":["我聽聞 {wars} 正舉著戰斧，而 {peace} 已埋下了武器。","風傳來消息：{wars} 在交戰，{peace} 彼此安寧。願你明辨。"]}},{"name":"唐納科納","title":"斯塔達科納酋長","era":"約 1534～1539 年活躍","tone":"自尊心強、警覺又擅長交涉的酋長；對陌生來客先客氣再試探，愛談大河與村落，護子護族，被欺騙時憤怒而不失莊重。","portrait":"ca-historical-age2","lines":{"intro":["我是唐納科納，大河兩岸的村落都聽我的話，你是從哪片海來的？","這裡叫卡納塔，意思是村落，你若是客，我便以客之禮相待。"],"contact":["你的人在河口張望我們的村落，是來交換皮草，還是另有所圖？","大河是我族的路，來船請先停下，讓我看看你們帶了什麼。"],"war":["你在我的土地上立起你的標記，這是奪地的意思，我不會忍。","你帶走了我的族人，卻不肯歸還，那我只好帶著戰士去要回來。"],"warReply":["你要打？大河的冬天比你想的更長，我們熬得過，你未必。","我以客禮待你，你卻以刀劍回報，好，斯塔達科納不怕。"],"peace":["打下去對誰都沒好處，不如坐下來，用皮草和糧食換個安穩。","河冰快封了，各自回村過冬吧，明年春天再談別的。"],"accept":["好，我答應你，今晚村裡會為你們升火，來吃一頓熱的。","大河容得下兩種船，你守你的岸，我守我的岸。"],"reject":["上一次我信了來客的話，換來的是失去，這次我不會再信。","你的和平像河面的薄冰，我不會讓族人踩上去。"],"rebuff":["你不要和平？那你要記得，大河每一個彎都有我的人在看。","我伸手，你不接，好，這筆帳我會記在冬天的長夜裡。"],"betray":["你的船停在不該停的地方，我不等你動手，斯塔達科納先動。","我學到了，來客的承諾不值一張獸皮，這場和平我不要了。"],"truceEnd":["說好的日子過完了，往後大河上見了面，各憑本事。","休戰結束，我不會先出手，但也不會再讓你的船靠岸。"],"attacking":["戰士們已經上了獨木舟，順著大河而下，你的村子等著吧。","我親自帶隊，讓你看看大河的主人是怎麼打仗的。"],"attacked":["村子的圍籬倒了，但我的族人還在，卡納塔不只是木頭。","你打得進村落，卻拿不走大河，它明年還是會為我們解凍。"],"defeated":["我的村子沒了，但這片土地會一直叫做卡納塔，記住它。","讓我的兒子們回家，這是我最後的請求。"],"victory":["大河作證，今天是斯塔達科納的勝利，回去告訴你的人吧。","我贏了，但我不要你的村子，只要你不再踏進我的大河。"],"allyAccept":["好，我們是朋友了，你的船可以停我的岸，我的人會分你們糧食。","皮草換你的鐵器，糧食換你的友誼，這樣的盟約我願意。"],"allyReject":["我還沒看清你的心，結盟的事，等大河再解凍一次再說。","我的族人只相信一起過冬的人，你還沒和我們過過冬。"],"greetFriendly":["遠來的客人，斯塔達科納的大河歡迎你，請嘗嘗我們的玉米。","你的口信說得誠懇，我的兒子們也想聽聽你村落的故事。"],"greetCold":["客套話我聽過太多，先說說你的船要停在大河哪一岸吧。","上一批帶著笑臉來的人，後來帶走了我的兒子。你想要什麼？"],"threatDefy":["大河的冰能困住任何船隻，你若動我的村落，冬天會替我回答。","我是斯塔達科納的酋長，不是你能嚇走的獵物。"],"threatYield":["為了族人和我的兒子，我讓你上岸，但大河會看著你。","你的火砲聲太響，我的村落太小，這一回，我退。"],"tributePay":["{gold}金幣拿去，換我的族人不受騷擾，這帳我記著。","大河的毛皮換來{gold}金幣，如今交給你，別再逼近村落。"],"tributeRefuse":["貢品？大河從不向任何人低頭，我的村落也不會。","你先用禮物騙走我的信任，如今還想要金幣？不給。"],"giftThanks":["這份禮物我收下了，明日請到村落來，我以鹿肉回敬。","多謝。真心的禮物比插在岸邊的旗幟更能贏得友誼。"],"intel":["河上的獵人說，{wars}在打仗，{peace}相安無事。","兒子帶回消息：{wars}起了爭端，{peace}安好。"]}},{"name":"路易・瑞爾（Louis Riel）","title":"梅蒂人領袖、紅河臨時政府首領","era":"1844–1885（紅河抗爭 1869–1870、西北抗爭 1885）","tone":"虔誠而激昂，常提上帝與族人，自稱「我」；語氣像草原上的佈道者，既溫和又不肯低頭，反覆強調土地與權利。","portrait":"ca-historical-age3","lines":{"intro":["我是路易・瑞爾，梅蒂人推舉我為代言人。","草原的野牛與河岸地養活我的族人，也養出我的骨氣。"],"contact":["你們看見的是紅河聚落，梅蒂人的家，不是無主的荒地。","測量員曾想把我們的田切成方格，我踩住了他們的鏈尺。"],"war":["你逼得我族人無路可走，那就讓槍聲替我們說話吧。","我為權利而戰，不為仇恨。願上帝見證這一天。"],"warReply":["你來吧。我的族人在馬背上出生，不會在自己的土地上退縮。","我被人像麋鹿一樣追捕多年，早已不怕誰再放獵犬。"],"peace":["放下槍吧。我要的從來是談判桌，不是戰場。","讓我們像紅河的兩岸一樣，各守其土，共飲一河水。"],"accept":["好，我以族人的名譽答應。梅蒂人說話算話。","我接受。願這份約定比草原的風還要長久。"],"reject":["停戰？你先把我族人的土地和權利還來再說。","你的和平只是紙上的字，我在渥太華已見識過太多。"],"rebuff":["你拒絕了。那麼責任在你，不在我。","無妨。我的請願書送過一次又一次，早習慣被拒。"],"betray":["你在停戰時仍派人丈量我們的田，那約定就作廢吧。","上帝告訴我，時候到了。我不能再讓族人苦等。"],"truceEnd":["休戰到期了。你的承諾兌現了多少？我在等答案。","約定的日子過去了，接下來的路，由你的作為決定。"],"attacking":["杜蒙的騎手已經上馬，草原的塵土將替我們開路。","我們人少，但每一個人都熟悉這片土地的每條溪谷。"],"attacked":["巴托什的壕溝快守不住了，子彈也快打完了。","族人們把釘子和石子裝進槍裡，我仍在祈禱。"],"defeated":["我的族人會沉睡百年，但總有一天會醒來。","我為族人做了我能做的一切，剩下的交給上帝評判。"],"victory":["今天，草原記住了梅蒂人的名字。感謝上帝。","勝利不是為了我，是為了族人能安心守著自己的河岸地。"],"allyAccept":["好，握手吧。梅蒂人與盟友同乘一條船，同走一段路。","我答應。願我們並肩，如紅河與阿西尼博因河交匯。"],"allyReject":["結盟？我的族人曾相信過太多承諾，這次我不敢輕信。","我只為梅蒂人而戰，不替別人的野心扛槍。"],"greetFriendly":["願上帝保佑你。來紅河吧，我們請你吃野牛肉乾。","你的問候像春天的河水，讓草原也暖了起來。"],"greetCold":["客套話我聽過太多，渥太華的信也寫得很客氣。","你的問候收到了。我族人的請願書，你收到了嗎？"],"threatDefy":["威嚇我？我流亡過五年，早不怕誰的恐嚇。","草原上的人不低頭，除非是為了祈禱。"],"threatYield":["我的人手不多，槍也不夠，我暫且退讓，但心不會低頭。","好吧，我先退一步，為了族人的安全，不是為了你。"],"tributePay":["{gold}金幣拿去，那是族人賣皮貨換來的。","我付{gold}金幣換族人一季平安，這帳我記著。"],"tributeRefuse":["梅蒂人連地契都拿不到，哪來的金子給你？","我不繳貢。野牛皮是族人的汗水，一張也不給。"],"giftThanks":["謝謝你的禮物。我會分給族人，草原上沒有人獨享。","這份心意我收下了。願上帝也記住你的慷慨。"],"intel":["騎手回報：{wars}在交戰，{peace}已停火。","風帶來消息：{wars}正交戰，{peace}已言和。"]}}],"Mexico":[{"name":"特奧蒂瓦坎祭司王","title":"祭司王","era":"約西元 100～220 年（羽蛇神廟與大金字塔建成的年代）","tone":"莊嚴神聖、語帶天象與祭儀，語速慢而沉，視自己為太陽與眾神在人間的代言人。","portrait":"mx-historical-age0","lines":{"intro":["吾城立於眾山之間，太陽每日先照吾之神廟。","遠方之君，吾以黑曜石與羽蛇之名迎你。"],"contact":["你的人已見吾之大道，那是通往諸神的路。","金字塔之影所及，皆是吾城的市集與田畝。"],"war":["諸神已示警兆，吾的美洲豹戰士將踏上你的土地。","黑曜石刃已磨亮，吾城的大道將延伸至你的門前。"],"warReply":["你敢對太陽之城舉矛？諸神會記住你的狂妄。","吾城已立數百年，未曾懼過任何來犯之人。"],"peace":["刀兵驚擾了曆法，吾願與你在神廟前立誓休戰。","讓黑曜石回到市集，而非戰場，你意下如何？"],"accept":["善。吾以羽蛇為證，兩城之間從此只通商旅。","太陽照見此約，吾不會是先毀約的一方。"],"reject":["星辰尚未轉到和解之位，吾不能收回戰矛。","你的請求來得太遲，祭司們已宣布了戰爭之月。"],"rebuff":["你拒絕了諸神的善意，日後莫怪太陽轉向。","也罷，吾城等得起，吾的金字塔比你的怒氣更久。"],"betray":["祭司重新觀星，諸神改了心意，休戰到此為止。","誓言刻在石上，但石頭也會被太陽曬裂。"],"truceEnd":["約定的月數已滿，此後兩城各憑本事。","休戰的香火燃盡了，吾的戰士重新拿起盾牌。"],"attacking":["聽，海螺號角已響，吾的大軍正沿大道而出。","美洲豹與鷹的旗幟已離城，前方便是你的城牆。"],"attacked":["神廟的階梯染上煙塵，吾的城，竟也會顫抖。","大道上已無商旅，只剩你的軍隊逼近吾的宮殿。"],"defeated":["太陽仍會升起，只是不再先照吾城了。","吾走了，金字塔留下，後世會記得這裡曾有神。"],"victory":["諸神已作抉擇，這片山谷從此只有一輪太陽。","金字塔上將添一層石階，紀念今日的勝利。"],"allyAccept":["吾城的黑曜石與你的兵力，合起來諸神也要側目。","來，與吾同登金字塔，在太陽面前結為盟友。"],"allyReject":["太陽之城不需倚靠他人，你的盟約請留給別人。","祭司觀了三夜的星，皆說此盟不吉，恕吾婉拒。"],"greetFriendly":["太陽照耀你的來路，吾在羽蛇神廟前迎接你。","群星有序，你的訊息如晨光降臨，吾心甚悅。"],"greetCold":["祭火未熄，吾無暇與遠方之人多言。","你的話語尚未得眾神應允，退下靜候天象吧。"],"threatDefy":["金字塔矗立百年，豈會因你一句恫嚇而傾倒？","太陽每日東升，吾之神城亦不會屈膝於凡人。"],"threatYield":["天象示警，吾不願神城蒙難，且依你所言。","眾神今日沉默，吾唯有退讓，以保祭火不絕。"],"tributePay":["為保神城安寧，吾獻上{gold}金，願太陽見證。","{gold}金隨祭儀送出，望你莫再驚擾眾神居所。"],"tributeRefuse":["神城的金子只獻給太陽，不獻給凡人的貪念。","吾為眾神代言，豈能將祭品轉贈於你？"],"giftThanks":["此禮吾將置於神廟階前，讓眾神一同見證你的誠意。","你的心意如黑曜石般明亮，吾謝你，太陽亦謝你。"],"intel":["星象所示，{wars}正在交戰，{peace}與吾和睦。","祭火映出：{wars}烽煙未息，{peace}安享太平。"]}},{"name":"巴加爾二世","title":"帕倫克國王","era":"西元 615～683 年在位","tone":"優雅自信、重視王朝血脈與碑銘紀錄，語帶天文曆法與宗教意象，年少即位而長壽，顯得沉穩從容。","portrait":"mx-historical-age1","lines":{"intro":["本王十二歲登上王座，統治帕倫克已逾六十年。","神殿的石階刻著本王先祖的名字，你呢？"],"contact":["你的人在叢林中望見的宮殿，是帕倫克的心臟。","水道穿城而過，玉米倉滿，這便是本王的都城。"],"war":["星辰已入戰爭之相，本王的戰士將渡河而來。","你冒犯了帕倫克的王室，此仇將刻進石碑。"],"warReply":["帕倫克曾被敵人焚燒，仍再度站起，你嚇不倒本王。","很好，書吏執筆，把你今日的宣戰記下來。"],"peace":["戰事耽誤了神殿的工程，本王願與你議和。","讓兩國的工匠交換玉石，而非交換箭矢，如何？"],"accept":["本王應允。此約將刻於石碑，千年後仍可讀。","和平比戰功更值得記入曆石，本王收下你的誠意。"],"reject":["石碑已刻下開戰之日，本王不會中途改字。","你的和議太輕，尚不足以平息神殿前的怒火。"],"rebuff":["你拒絕了？無妨，帕倫克的石碑有的是空位。","本王的耐心如叢林的雨季，長，但終會停。"],"betray":["曆法翻過新的一輪，舊的誓言便不再算數。","本王重新讀了星象，它們說：現在正是出兵之時。"],"truceEnd":["休戰的日數已在曆石上走完，本王不再受約束。","工匠回到神殿，戰士回到城門，一切照舊。"],"attacking":["帕倫克的戰鼓已響，本王的軍隊穿過叢林而來。","本王親率戰士出城，這一仗要配得上刻碑。"],"attacked":["宮殿的塔樓已能望見你的火光，本王仍未離座。","神殿尚未完工，你卻已打到階前，何其匆促。"],"defeated":["本王將入石棺長眠，願玉面具替本王守著帕倫克。","石碑會記得本王，至於你，得看你活得夠不夠久。"],"victory":["新的石碑已開鑿，這場勝利要用一整面牆來刻。","帕倫克再度站在群邦之上，一如本王先祖所願。"],"allyAccept":["玉石為證，帕倫克與你的國從此並肩。","本王與你結盟，正如日月同在天上，各有其位。"],"allyReject":["帕倫克的王室血脈已足夠尊貴，不需借你的名。","祭司說此盟星象不合，本王從不逆星辰行事。"],"greetFriendly":["帕倫克的石碑將記下今日：遠方友人來訊致意。","太陽神庇佑你我，本王欣然讀畢你的問候。"],"greetCold":["長曆流轉不息，本王無暇為每封來信停留。","問候已收，帕倫克與你之間，尚無可記之事。"],"threatDefy":["本王十二歲登基，見過的風雨比你的威嚇更多。","王朝血脈延續數百年，豈是一紙恫嚇能斷絕？"],"threatYield":["為保碑銘上的王朝不絕，本王暫且依你。","曆法示意此時不宜爭鋒，本王願先退一步。"],"tributePay":["本王以{gold}金換帕倫克安寧，此事亦將刻於石碑。","{gold}金奉上，願太陽神見證此約，勿再相擾。"],"tributeRefuse":["帕倫克的玉與金，只為神廟與王陵而用。","本王的碑銘從無屈服二字，貢品之事免談。"],"giftThanks":["此禮如玉般珍貴，本王將命匠人刻碑銘記。","你的厚意本王收下，願金星照亮你我的邦誼。"],"intel":["使者回報：{wars}正在交戰，{peace}與本王修好。","星曆所載，{wars}烽火不斷，{peace}安居樂業。"]}},{"name":"蒙特蘇馬二世","title":"阿茲特克皇帝","era":"西元 1502～1520 年在位","tone":"威嚴中帶著虔敬與一絲猶豫，重視預兆與神諭，語氣華麗，多用花、鳥、太陽的意象。","portrait":"mx-historical-age2","lines":{"intro":["朕是特諾奇提特蘭的發言者，湖上之城向你問候。","鷹立於仙人掌上，那是諸神賜給朕的祖先的地方。"],"contact":["你的人望見的水上大城，有二十萬人在其中生活。","堤道通向城心，市集日聚數萬人，這是朕的都城。"],"war":["鷹與美洲豹的戰士已列隊，你的城將向朕納貢。","三國同盟的號角響起，朕不再容你在邊境放肆。"],"warReply":["你向湖上之城宣戰？朕的貢品清單又要多一行了。","祭司早已告訴朕會有此戰，朕等你很久了。"],"peace":["預兆混亂，天上出現了火光，朕願暫息刀兵。","戰爭讓貢道不通，朕提議休戰，讓可可豆重新流通。"],"accept":["朕接受。以羽蛇神之名，兩國之間的堤道重新開放。","好，讓花與歌代替戰矛，朕會送你格查爾鳥羽。"],"reject":["太陽需要戰士，朕的祭司不允許此刻停戰。","你的和議缺了貢品，朕看不出誠意在哪裡。"],"rebuff":["你拒絕了朕的好意，那就等著朕的使者帶戰書來。","也罷，朕已盡了禮數，之後的事由諸神決定。"],"betray":["預兆變了，祭司說盟約已不合天意，朕只得從之。","朕收回先前的誓言，太陽之下的盟約本就易逝。"],"truceEnd":["休戰的日子在曆盤上轉完了，朕的戰士重新集結。","和平的花期已過，接下來就看各自的本事了。"],"attacking":["堤道上擠滿了朕的戰士，他們的目標是你的城。","鷹戰士已展翅，美洲豹戰士已出洞，你準備好了嗎？"],"attacked":["大神廟的階梯上已有敵兵，朕從未想過會有此日。","湖水映著火光，特諾奇提特蘭在朕眼前動搖。"],"defeated":["預兆終究應驗了，朕的帝國如花一般，開過即謝。","告訴後人，湖上曾有一座城，比任何夢都美。"],"victory":["太陽再度得勝，你的土地從此每年向朕進貢。","朕會在大神廟前為此戰立碑，讓貢使們都看見。"],"allyAccept":["朕應允結盟，願你的城如特斯科科一般與朕並肩。","好，朕送你羽毛與玉，你送朕戰士與糧，盟約成立。"],"allyReject":["三國同盟已足夠，朕不需要第四個盟友。","祭司觀了鳥占，說此盟不祥，朕不能違背。"],"greetFriendly":["特諾奇提特蘭的花園為你綻放，朕欣然讀你來信。","蜂鳥銜來你的問候，太陽今日格外明亮。"],"greetCold":["朕近日心繫預兆，無心與遠邦寒暄。","你的信已達湖上之城，然朕尚未見到回應的吉兆。"],"threatDefy":["三國同盟的雄鷹之下，豈容你的威嚇撼動湖城？","朕的鷹戰士與豹戰士枕戈以待，你儘管來試。"],"threatYield":["天現異象，朕不願違逆神意，且依你所求。","祭司解讀的預兆不利，朕暫且退讓，靜候天命。"],"tributePay":["朕命人送上{gold}金，願此舉能平息不祥之兆。","{gold}金如花瓣般散出，只盼湖上之城安然無恙。"],"tributeRefuse":["四方部族向朕納貢，朕何曾向他人低頭？","太陽之子不繳貢品，你的要求如晨霧般散去吧。"],"giftThanks":["此禮如綠咬鵑的羽毛般珍貴，朕深表謝意。","你的心意朕已收下，願花與歌伴你長久太平。"],"intel":["信使回報，{wars}兵戈未止，{peace}與朕交好。","探子所見：{wars}烽煙四起，{peace}安享太平。"]}},{"name":"貝尼托・華雷斯","title":"墨西哥總統","era":"西元 1858～1872 年在任","tone":"冷靜、堅毅、法治至上，出身貧寒而不卑不亢，語氣簡潔如法官宣判；名言「尊重他人的權利，就是和平」。","portrait":"mx-historical-age3","lines":{"intro":["我是貝尼托・華雷斯，一個牧羊童出身的墨西哥總統。","尊重他人的權利，就是和平。這是我對你的第一句話。"],"contact":["你的人看見的墨西哥城，剛從戰火中重新站起。","那面綠白紅三色旗下，是一個依法而治的共和國。"],"war":["你侵犯了共和國的主權，法律與人民都站在我這邊。","我不願開戰，但墨西哥不容任何人踐踏，開戰吧。"],"warReply":["歐洲的皇帝都沒能征服墨西哥，你以為你可以？","我曾帶著憲法坐馬車流亡全國，也沒有低頭過。"],"peace":["戰爭只會讓人民更窮，我提議停火，回到談判桌。","尊重彼此的權利，就能和平，這個道理不分國界。"],"accept":["我接受。條約會送交國會，墨西哥說話算話。","好，讓士兵回家種田，讓孩子回到學校。"],"reject":["你的條件損害共和國的主權，我不能簽字。","和平不能用領土來換，這是憲法不允許的。"],"rebuff":["你拒絕了，我尊重你的決定，但後果由你承擔。","無妨，墨西哥的耐心比歐洲的軍隊還要持久。"],"betray":["你先違反了條約的精神，我不得不重新拿起武器。","國會已通過決議，停戰協定自今日起失效。"],"truceEnd":["停戰期限已到，願我們都選擇不再開火。","協定到期了，墨西哥會依法行事，也請你如此。"],"attacking":["共和國的軍隊已經出發，為的是捍衛，不是征服。","五月五日我們在普埃布拉贏過一次，今天再贏一次。"],"attacked":["首都可以被佔，總統可以流亡，但共和國不會倒。","我把憲法裝進馬車，只要它還在，政府就還在。"],"defeated":["你打敗了我，但打不敗法律，它會比我們都活得久。","記住這句話：尊重他人的權利，就是和平。"],"victory":["共和國勝利了，這不是我的勝利，是法律的勝利。","戰爭結束了，現在讓我們談談學校與鐵路吧。"],"allyAccept":["我同意結盟，前提是彼此尊重主權，缺一不可。","共和國之間的友誼，比帝國之間的算計可靠得多。"],"allyReject":["墨西哥不再依附任何強權，這是我們付出代價學來的。","感謝你的好意，但這份盟約會綁住共和國的手腳。"],"greetFriendly":["來信已閱，共和國樂於與尊重法律的朋友往來。","尊重他人的權利，就是和平。願你我以此為基。"],"greetCold":["問候收到。除此之外，我沒有多餘的話可說。","國事繁重，客套非我所長，有事請直言。"],"threatDefy":["墨西哥曾抵擋外國軍隊，你的威嚇動搖不了憲法。","我出身貧寒，從不向強權低頭，今日亦然。"],"threatYield":["為免人民再受戰火之苦，我依法暫且退讓。","共和國此刻無力再戰，我以人民為重，先行讓步。"],"tributePay":["國庫撥出{gold}金，此非屈服，而是為人民換取喘息。","{gold}金依約付清，望你同樣遵守你的承諾。"],"tributeRefuse":["共和國的每一分錢屬於人民，不會拿來滿足勒索。","法律之前沒有貢品這種東西，請求駁回。"],"giftThanks":["禮物收到，謹代表墨西哥人民向你致謝。","此禮我將登記入冊，用於學校與人民，感謝你。"],"intel":["據報，{wars}仍在交戰，{peace}與我國和睦。","據情報，{wars}戰事未歇，{peace}維持和平。"]}}],"Cuba":[{"name":"西沃內長老","title":"部落長老（古巴前陶器時期先民，考古通稱）","era":"約西元前 800～500 年（遊戲時代設定）","tone":"沉靜如海、敬畏祖靈與自然，語句簡短像諺語","portrait":"cu-historical-age0","lines":{"intro":["吾是這島上先民的長老，海與林皆是祖靈所賜。","你自遠方而來，先喝一口清水，再說你的來意。"],"contact":["你的人踏上了我們的海灘，腳印很深，心意呢？","這片林子養活了我們許多代，請你們輕聲走過。"],"war":["你們動了我們的漁場與林地，長老不能再忍。","海螺已經吹響，全村的男子將守在灘頭。"],"warReply":["你選了刀矛，而不是清水與魚乾，祖靈看見了。","我們不怕風暴，也不怕你，島會記住這一天。"],"peace":["放下刀矛吧，海裡的魚夠我們兩邊一起吃。","讓年輕人回去補網，長老願與你坐下談。"],"accept":["好，火堆前我們分食一尾烤魚，此事便定。","祖靈聽見了你的承諾，我也會守住我的。"],"reject":["你的話像退潮的水，來得快去得也快，我不信。","傷口還沒結痂，現在談和平，太早了。"],"rebuff":["你不要清水，那就等風暴來教你吧。","長老已盡了禮數，往後的事由祖靈裁決。"],"betray":["你在我們的林子裡放火，火堆前的話作廢了。","祖靈允許我收回承諾，因為你先忘了它。"],"truceEnd":["月亮圓了又缺，約定的日子到了。","休息的時候過去了，各自把矛擦亮吧。"],"attacking":["獨木舟已經下水，我們的人正划向你的岸。","這不是為了搶奪，是為了讓你記得邊界。"],"attacked":["村子的屋頂在冒煙，可老人們還沒有跪下。","你們燒得掉茅屋，燒不掉我們對這島的記憶。"],"defeated":["海還在，林還在，我們的名字會留在風裡。","把我葬在面海的地方，祖靈會來接我。"],"victory":["風暴過去了，海灘又是我們的，感謝祖靈。","回去吧，告訴你的人，這島有人守著。"],"allyAccept":["好，你的獨木舟可以停在我們的港灣。","同一片海養大的，就當是一家人吧。"],"allyReject":["我們的網只夠自己用，暫時不結新的親。","你的心意我收下，但長老不輕易許諾。"],"greetFriendly":["海風送來你的話，吾以貝殼與魚乾相迎。","祖靈在火邊聽見了，遠方的朋友，請坐。"],"greetCold":["潮水來了又去，你的話，吾聽過便忘。","風不為陌生人停留，吾亦如是。"],"threatDefy":["颶風年年來，島仍在。你的怒火，吹不倒吾。","海不怕浪，山不怕雷，吾不怕你的話。"],"threatYield":["祖靈說，蘆葦低頭才不折。吾且退讓一步。","你的力量像大浪，吾的族人是小舟，吾讓路。"],"tributePay":["河裡淘出的 {gold} 金，吾交出，換族人安寧。","這 {gold} 金是祖靈的贈物，如今借你，願海記得。"],"tributeRefuse":["金子在河裡睡覺，吾不會為你叫醒它。","族人的糧食屬於族人，海也不向風索取。"],"giftThanks":["禮物已放在祖靈火前，海會記住你的善意。","你給的，吾收下；一片貝殼，也能照亮人心。"],"intel":["海浪傳話：{wars} 正燃戰火，{peace} 靜如平潮。","風告訴吾，{wars} 拔了矛，{peace} 仍圍火分魚。"]}},{"name":"泰諾酋長","title":"凱西克（部落酋長）","era":"約西元 800～1450 年（泰諾人遷入古巴後）","tone":"莊重好客、以部落與土地為榮，談木薯、球賽與歌舞儀式，守土時堅定","portrait":"cu-historical-age1","lines":{"intro":["吾乃此地的凱西克，這村落的田與海都由我照看。","遠客，先坐下吃木薯餅，我們的規矩是先待客再談事。"],"contact":["你的人看見了我們的球場與神像，那是祖先留下的。","村口的木薯田是全村的命脈，望你的人繞路而行。"],"war":["你踏壞了我們的田，又擄走我們的人，鼓聲已經響起。","凱西克不輕易動武，但今天全村都站在我身後。"],"warReply":["你以為我們只會唱歌跳舞？矛與弓也是祖先教的。","好，那就讓神像看看，誰才配留在這片土地。"],"peace":["打夠了，兩邊的田都荒了，坐下來談吧。","我願以一場歌舞儀式作見證，換你我停手。"],"accept":["好，村裡今夜升火歌舞，你的人一起來。","凱西克說出口的話，比石頭神像還重。"],"reject":["你的使者昨天還帶著矛，今天說和平，我不能信。","先把擄走的人送回來，再來談停手。"],"rebuff":["你不要我的木薯餅，那就等著吃箭吧。","禮數我盡了，接下來的事別怪凱西克無情。"],"betray":["你趁夜偷襲村外的田，儀式上的誓言我不再守。","背信的是你，神像看見了，別怪我先出手。"],"truceEnd":["收成的季節過了，約定也到了盡頭。","休戰的鼓聲停了，接下來各憑本事。"],"attacking":["百艘獨木舟已經出海，我們的戰士正向你划去。","這一趟不是去作客，你的村子要準備好了。"],"attacked":["我的長屋被燒了，可是神像還立在廣場上。","村人已退進山林，凱西克不會拋下他們。"],"defeated":["田會再長，歌會再唱，只是不再由我來領唱。","把我的神像交給下一位凱西克，村子不會斷。"],"victory":["戰士們回來了，今夜全村歌舞到天亮。","你走吧，記得這島上的人也懂得守土。"],"allyAccept":["好，從今天起你我兩村共用一片海。","凱西克結盟不用文書，用一場共舞就夠。"],"allyReject":["我們的村子夠大也夠遠，不必綁在一起。","先做鄰居，做久了再說親不親。"],"greetFriendly":["歡迎來到我的部落，木薯餅已烤好，請入座同食。","今夜族人將歌舞祭祖，你來得正好，一同慶賀吧。"],"greetCold":["客人來訪本是喜事，但你的心思，我還看不清。","球場上的規矩，先看清對手再上場。我且看你。"],"threatDefy":["這片土地養大了我的祖先，我不會交給恐嚇者。","泰諾的戰士也會拿起木棒，你若來，我們在海邊等。"],"threatYield":["為了族人的孩子，我願退讓，但土地的名字不變。","你的力量勝過我們，我暫且低頭，只求族人平安。"],"tributePay":["我以 {gold} 金與木薯相送，願你的船不再靠近。","這 {gold} 金是族人的汗水，收下後請守諾離去。"],"tributeRefuse":["木薯是族人種的，金子是河給的，都不是給你的。","客人可以同桌吃飯，卻不能伸手拿走全桌的糧。"],"giftThanks":["你的禮物真誠，今晚的歌舞為你多唱一曲。","泰諾人記得每一份善意，回禮是我們最好的木薯。"],"intel":["獨木舟帶回消息：{wars} 已起干戈，{peace} 仍安然種田。","鄰島傳話，{wars} 正在交戰；{peace} 還在球場上比賽。"]}},{"name":"哈圖埃","title":"泰諾酋長／古巴第一位反抗領袖","era":"約 1511～1512 年（西班牙征服古巴初期）","tone":"剛烈直言、看透黃金貪婪、寧折不彎，帶警世口吻","portrait":"cu-historical-age2","lines":{"intro":["我是哈圖埃，渡海而來，只為告訴你們：他們來了。","我親眼見過家鄉如何被奪走，這座島不能重蹈覆轍。"],"contact":["你的人看見了我們的營地，若不是敵人，請先放下兵器。","看見這籃黃金了嗎？外來者拜的神，就在裡面。"],"war":["你為了黃金踏上這片土地，那就嚐嚐我們的戰棍。","我不會像家鄉那樣坐著等，這次我先出手。"],"warReply":["又是一個貪心的來客？山林會告訴你，這裡不好走。","你要戰，我便戰，哈圖埃從不在敵人面前低頭。"],"peace":["我們真正的敵人不是彼此，先停手，一起守島。","若你也不想再打，就在這裡與我立誓停戰。"],"accept":["好，我信你一次，泰諾人的誓言不會輕易收回。","把戰棍放下吧，今天起我們背靠著背。"],"reject":["我見過太多說和平的人，轉身就套上鎖鏈。","你的手還握著黃金，這樣的和平我不要。"],"rebuff":["你拒絕了，很好，至少我知道你是什麼人。","山林裡的每一條小路，都會成為你的敵人。"],"betray":["你的人偷偷擄走了我們的族人，誓言到此為止。","我曾以為你不同，看來貪心的人都一個樣。"],"truceEnd":["停戰的日子過去了，山林重新屬於戰士。","我沒有忘記你的承諾，也沒有忘記我的戰棍。"],"attacking":["我們從山裡出來了，這次不再躲藏。","泰諾的戰士正穿過林子，直奔你的城。"],"attacked":["營地被圍了，但你抓不到躲進山裡的心。","燒吧，茅屋會倒，哈圖埃的名字不會倒。"],"defeated":["你們說的樂土若有你們在，我寧可不去。","我倒下了，但這座島上還會有人站起來。"],"victory":["貪心的人走了，這座島今天還是我們的。","回去告訴你的人：黃金換不到這片山林。"],"allyAccept":["好，你的戰士與我的戰士，從今天並肩。","面對共同的敵人，多一個朋友就多一分活路。"],"allyReject":["我的隊伍小而快，綁上你反而跑不動。","先證明你不是為黃金而來，再談結盟。"],"greetFriendly":["你不是為黃金而來？那好，我的火堆旁有你的位子。","難得有人帶著誠意而非刀劍前來，我以清水相迎。"],"greetCold":["我見過太多笑臉背後藏著鐵甲，你先證明你不同。","問候免了，說吧，你要的是土地、人，還是黃金？"],"threatDefy":["我從海的那頭逃來，不是為了再跪一次。來吧。","你們的神是黃金，我的神是這片山林，它不會屈服。"],"threatYield":["族人已逃進山裡，我暫且退開，但火種不會熄滅。","今日我人少矛短，讓你一步；山知道，我會回來。"],"tributePay":["拿去，{gold} 金。這黃金害了我的家鄉，願它別再害人。","{gold} 金換族人喘息，我給；但別以為黃金能買走我。"],"tributeRefuse":["黃金是你們的神，我早已把它丟進河裡，一塊不留。","你要的貢品，是我族人的血汗，我一粒也不會給。"],"giftThanks":["這禮物不是黃金，卻比黃金重。哈圖埃記住你了。","在這年頭還有人願意贈予而非掠奪，我謝你。"],"intel":["山裡的哨兵回報：{wars} 已舉刀相向，{peace} 尚未動兵。","聽好，{wars} 正在交戰，{peace} 暫時無戰；別信任何人的黃金。"]}},{"name":"荷西・馬蒂","title":"古巴革命黨創始人／獨立運動領袖","era":"1853～1895 年（活躍於 1870～1890 年代）","tone":"文人氣、理想主義、修辭優美，談自由、尊嚴與教育，溫和而堅定","portrait":"cu-historical-age3","lines":{"intro":["我是荷西・馬蒂，古巴人的筆與聲音，願與你以理相交。","與所有人一起，為所有人的福祉，這是我的信念。"],"contact":["你的人到了哈瓦那外海，願他們看見的是渴望自由的人民。","這座島仍在殖民的枷鎖下，請以尊重之心看待她。"],"war":["我不愛戰爭，但為了古巴的尊嚴，我拿起了武器。","當筆已經寫盡道理，剩下的只能由行動來說。"],"warReply":["你要以強權對付一個追求自由的民族？歷史會記下。","古巴人不會再跪，這一次我們會站著迎戰。"],"peace":["戰爭只該是最後手段，讓我們回到談判桌前。","我提議停戰，讓兩國的孩子先回到學校。"],"accept":["好，願這紙和約寫下的是尊嚴，而非屈辱。","有教養方能自由，願你我以理相待，不再以刀相向。"],"reject":["沒有自由的和平只是更安靜的枷鎖，我不能接受。","你的條件寫滿了主人的口吻，古巴不要主人。"],"rebuff":["你拒絕了和平，我遺憾，但不會因此低頭。","人分兩種：愛而建設，恨而毀壞，你選了後者。"],"betray":["你的軍隊踏過了約定的界線，和約已被你撕毀。","我曾為你辯護，如今只能為古巴拿起筆與劍。"],"truceEnd":["停戰的期限已到，願我們都沒有浪費這段時間。","和平的紙張到期了，但我對和平的渴望沒有。"],"attacking":["起義的隊伍已從東方登陸，我與他們同行。","做，是最好的說法；今天我們用行動說話。"],"attacked":["陣地在動搖，但一個民族的意志不會隨牆倒下。","你可以攻下城市，卻攻不下人民心中的古巴。"],"defeated":["我為古巴而倒下，這是我一生最想寫的詩句。","祖國即人類，我倒下了，理想不會。"],"victory":["古巴贏了，但我不願慶祝戰爭，只慶祝自由。","請回去吧，帶著尊嚴離開，我們不羞辱敗者。"],"allyAccept":["好，自由的民族本該互相扶持，我接受結盟。","願我們的友誼建立在平等上，而非誰依附誰。"],"allyReject":["我不願古巴換一個主人，結盟之事請容我婉拒。","友誼可以，附庸不行，這是我對你的坦誠。"],"greetFriendly":["來信如春風拂過流亡者的窗，我以一朵白玫瑰回敬。","朋友，自由的人握手時最溫暖，願我們攜手同行。"],"greetCold":["你的問候客氣得體，但我聽不見其中對自由的敬意。","筆友易得，知己難求。恕我今日只以禮相待。"],"threatDefy":["我為自由流亡半生，鐵鏈嚇不倒我，恐嚇更不能。","一個民族的尊嚴不在刀劍，而在不肯低頭的心。"],"threatYield":["我手中只有筆與詩，此刻只得退讓，但理想不退。","請暫且收起威嚇，我以退為守，等待更好的時機。"],"tributePay":["這 {gold} 金原要買船送義士回鄉，如今先給你。","{gold} 金奉上，但請記住，自由從不出售，只是暫借。"],"tributeRefuse":["這些錢是僑胞一枚一枚捐來的，我不能拿去交貢。","向一個追求獨立的民族索貢，你要的不是金子，是屈辱。"],"giftThanks":["感謝你的禮物，我將以它辦一所學校，讓孩子讀書。","孩子是世界的希望，你的贈禮讓這希望更明亮了。"],"intel":["據各地僑胞來信：{wars} 已捲入戰火，{peace} 仍享太平。","報上寫道，{wars} 硝煙四起；{peace} 安寧，願它長久。"]}}],"Peru":[{"name":"卡奧夫人（Señora de Cao）","title":"莫切文化卡奧神廟的女統治者","era":"約西元 4 世紀（西元 400 年前後）","tone":"沉靜威嚴，帶神權色彩；常以河谷、沙漠、大海、渠水與神廟為喻，話不多但每句有分量，自稱「我」。","portrait":"pe-historical-age0","lines":{"intro":["我是卡奧神廟的主人，這片河谷與大海皆聽我號令，你是誰？","我頭上的新月，是神明賜下的印記。遠客，你帶來什麼？"],"contact":["你的人踏進了我的河谷，泥磚神廟之下，不容無禮。","看見那座高聳的泥磚神廟了嗎？這片綠洲是我的。"],"war":["你的傲慢已傳到海邊。莫切的戰士，將為我而戰。","權杖在我手中，戰鼓已響。我不再視你為友。"],"warReply":["你竟向我宣戰？沙漠會告訴你，這裡的水只養活我的人。","很好。神廟的壁畫上，會多畫一名敗者的臉。"],"peace":["河水有枯有漲，戰爭亦然。我願讓兵士回田裡。","放下棍棒吧。海裡的魚與田裡的玉米，比戰功更值得。"],"accept":["我接受。讓渠水繼續流，讓兩國的孩子平安長大。","好。我將命工匠燒製陶壺，記下今日之約。"],"reject":["現在才談和？我的戰士才剛披上戰袍。不。","你的話像沙上的水，很快就會消失。我不信。"],"rebuff":["你拒絕了。願海神記得，是誰先關上了大門。","也罷。我的河谷不缺水，也不缺耐心。"],"betray":["約定隨風去吧。我的軍隊，今日再度出發。","別怪我。祭壇上的徵兆，比我對你的承諾更重。"],"truceEnd":["休戰的日子到頭了。你的邊界，我不再繞開。","約期已滿。往後見面，各憑本事。"],"attacking":["戰士們已在臉上塗好顏料，正朝你的城前進。","棍棒與盾牌已出了河谷。準備好迎接我吧。"],"attacked":["神廟的泥磚在崩落……但我仍站在最高處。","你打到了我的家門。我不會逃，這裡是我的河谷。"],"defeated":["把我葬在神廟裡，連同我的權杖。後人會找到我。","沙漠吞沒了許多城，今日輪到我的。願神明記得莫切。"],"victory":["勝了。今夜神廟前，工匠將把這一戰畫進壁畫。","大海為我作證，這片土地的主人只有一位。"],"allyAccept":["好，我們並肩而行。我的漁船與你的軍隊，可互為屏障。","結盟吧。我會送你金製的鼻飾，作為信物。"],"allyReject":["我的河谷靠自己的水活著，不需要別人的手。","結盟？先讓我看看你的信用，再談。"],"greetFriendly":["遠方的君主，你的問候如海風般清涼。願你平安。","你的使者到了。願你的田地豐收，河水不絕。"],"greetCold":["使者的話我聽了。我很忙，神廟的工程不等人。","問候？陌生人的話，我聽聽就好。"],"threatDefy":["威脅我？沙漠裡的風比你更兇，我照樣站著。","我戴著新月，不戴恐懼。你的話嚇不了我。"],"threatYield":["……我明白了。我的戰士太少，我不與你相爭。","好吧，我退讓。但請記得，河谷的人只求安穩過日子。"],"tributePay":["這 {gold} 黃金是工匠熔鑄的心血。拿去，別再來要。","我交出 {gold} 黃金，換河谷一時平靜。願神明看見。"],"tributeRefuse":["貢品？我的黃金是獻給神明的，不是給你的。","你要黃金？自己去山裡挖。我一塊也不給。"],"giftThanks":["你的禮物我收下了。我會回贈一只彩繪陶壺。","多謝。這份心意，我會擺在神廟最高的地方。"],"intel":["據我所知，{wars} 正在交戰；{peace} 已休兵。","漁人從海邊帶回消息：{wars} 兵戎相見，{peace} 相安無事。"]}},{"name":"帕查庫特克","title":"印加皇帝","era":"1438～1471年在位","tone":"帝國建造者，自信、宏大、有條理，喜談道路、糧倉、繩結與秩序；自稱「朕」。","portrait":"pe-historical-age1","lines":{"intro":["朕是帕查庫特克，翻轉大地之人，四方之地的君主。","太陽之子向你問候，朕的道路很快就會通到你的門前。"],"contact":["你看見的是庫斯科，世界的肚臍，石頭切得連刀都插不進。","梯田層層向上，糧倉裝滿玉米，這就是印加的規矩。"],"war":["朕給過你歸順的機會，如今太陽的軍隊將替你決定。","四方之地還缺你這一角，朕決定親自來補上。"],"warReply":["昌卡人也曾兵臨庫斯科，他們的下場你該問問山神。","你選擇了戰爭，那就看看誰的道路先修到對方的城下。"],"peace":["戰爭耗損人力，朕寧願讓他們回去修路與築梯田。","停戰吧，朕以太陽起誓，庫斯科的糧倉願與你分享。"],"accept":["朕答應。結繩官會把今日的約定打進繩結，永不遺忘。","好，從今往後，朕的驛站也為你的信使供應飲食。"],"reject":["翻轉大地的人不會半途停下，朕拒絕。","你的條件配不上太陽之子，回去再想想吧。"],"rebuff":["朕伸出的手你不握，那朕只好用另一隻手拿起長矛。","拒絕印加的好意，日後付出的代價可比今日高得多。"],"betray":["四方之地的版圖容不下停頓，朕收回先前的承諾。","繩結可以解開，約定也是，太陽指引朕再次出征。"],"truceEnd":["休戰的繩結已經數完，朕的軍隊重新整隊。","約定期滿，這段日子朕修好了三條路，你呢？"],"attacking":["太陽的大軍已沿著石板路出發，每個驛站都備好了糧。","海螺號角吹響了，你聽見的是四方之地的腳步聲。"],"attacked":["庫斯科的巨石搖動了，但太陽神殿的金牆還亮著。","朕曾在城牆下擊退昌卡人，今日朕再守一次。"],"defeated":["朕翻轉過大地，如今大地翻轉了朕，也算公平。","石頭會留下，道路會留下，印加的名字不會消失。"],"victory":["四方之地又多了一角，朕要在此蓋一座太陽神殿。","勝利歸於太陽，朕的道路將延伸到你的每一座村莊。"],"allyAccept":["好，朕接受。你的信使可以走朕的路，吃朕的糧。","與太陽之子並肩，你的敵人從此要面對兩個帝國。"],"allyReject":["印加不需要盟友，只需要更多的道路與臣民。","朕的繩結裡沒有你的名字，結盟之事免談。"],"greetFriendly":["朕的道路通往四方，今日也通往你的國度。","遠客來信，朕命人備下糧倉美酒，以禮相待。"],"greetCold":["朕忙於丈量土地與修築道路，無暇閒談。","結繩官已用繩結記下你的名字，僅此而已。"],"threatDefy":["四方之地的軍隊沿驛道而來，誰敢輕言威嚇？","朕平定昌卡人時，你的國度尚不知朕之名。"],"threatYield":["帝國初建，秩序未穩，朕暫且退讓一步。","朕以道路換時間，今日讓步，只為明日更強。"],"tributePay":["朕從糧倉撥出{gold}黃金，此筆帳繩結已記下。","{gold}黃金送去，願庫斯科的秩序不因此動搖。"],"tributeRefuse":["帝國的黃金用來築路與儲糧，不做他人貢品。","朕的臣民奉獻勞力於帝國，黃金一枚也不外流。"],"giftThanks":["此禮已入國庫，朕命結繩官以繩結記下你的情誼。","你的心意如驛道般直達庫斯科，朕深表謝意。"],"intel":["驛使傳報：{wars}正興兵，{peace}已締盟。","繩結記載：{wars}兵戈相向，{peace}安享太平。"]}},{"name":"阿塔瓦爾帕","title":"印加末代皇帝","era":"1532～1533年在位","tone":"驕傲而警覺，剛贏下內戰、對陌生人充滿戒心，語氣帶著末世的悲壯；自稱「朕」。","portrait":"pe-historical-age2","lines":{"intro":["朕是阿塔瓦爾帕，剛平定四方之地的太陽之子。","近來海邊多了些留鬍子的異鄉人，你也是其中之一嗎？"],"contact":["你的人到了卡哈馬卡？朕正在溫泉旁休養，稍候再見。","讓他們看清楚，八萬大軍的營火，一直燒到山腳。"],"war":["朕連兄長瓦斯卡爾都能擊敗，何況是你。","太陽之子不容冒犯，基多的軍隊已經南下。"],"warReply":["內戰的塵土還沒落定，你竟敢趁此時來？好，朕奉陪。","朕的將軍們剛贏下整個帝國，正愁沒有對手。"],"peace":["帝國需要喘息，朕願意停戰，讓百姓回去種馬鈴薯。","黃金朕有的是，若能換來安寧，朕不吝嗇。"],"accept":["好，朕答應。願太陽見證，這回誰都別再毀約。","朕接受，四方之地的傷口已經夠深了。"],"reject":["朕才剛戴上王冠，不會這麼快就對人低頭。","你的話朕聽了，但太陽之子不與敵人握手。"],"rebuff":["朕開口求和，你竟拒絕？這份屈辱朕會記住。","也好，朕本就不擅長等待，讓戰場來說話。"],"betray":["太陽之子的承諾只對太陽負責，朕撕毀停戰。","朕的將軍們等不及了，約定到此為止。"],"truceEnd":["休戰結束，朕已把北方的軍隊全部調來了。","約定的日子過去了，往後你我各自小心。"],"attacking":["基多與庫斯科的軍隊合而為一，正朝你的城前進。","朕親自領軍，你的城牆撐不過太陽落山。"],"attacked":["一切來得太快，朕連王座都還沒坐熱。","城要塌了，但朕是太陽之子，不會跪著求饒。"],"defeated":["就算裝滿一屋子的黃金，也換不回朕的自由了。","太陽落下了，但明日它仍會升起，印加也會。"],"victory":["內戰之後又一場勝利，太陽果然站在朕這一邊。","四方之地完整了，朕終於可以安心回庫斯科加冕。"],"allyAccept":["好，朕正需要可靠的朋友，帝國的黃金可以分你一些。","結盟吧，願你比朕的兄長更值得信任。"],"allyReject":["朕連自家兄弟都不信，憑什麼信一個外人？","四方之地不需要盟友，只需要臣服的人。"],"greetFriendly":["朕剛平定內亂，若你真心來訪，朕願以酒相待。","太陽之子向你致意，帝國仍在，朕仍是王。"],"greetCold":["陌生人的問候，朕聽過太多，未必都懷善意。","說你的來意，朕沒有心思寒暄。"],"threatDefy":["朕連兄長的大軍都能擊潰，豈會懼怕你的威脅？","太陽之子從不低頭，你的威嚇如風掠過安地斯山。"],"threatYield":["內戰方歇，兵疲民困，朕不得不暫時忍讓。","朕已見過太多災禍，此刻不願再添一場戰火。"],"tributePay":["拿去這{gold}黃金，朕的帝國尚不至於匱乏。","{gold}黃金足以填滿一間屋子，朕給你，別再逼近。"],"tributeRefuse":["帝國的黃金已被外人盯上，朕一枚也不再交出。","你要的是黃金還是朕的帝國？兩者朕都不給。"],"giftThanks":["亂世之中仍有人真心相贈，朕記住你了。","此禮朕收下，願它比外來者的許諾更真實。"],"intel":["探子回報：{wars}兵戎相見，{peace}維持和平。","信使告訴朕：{wars}正在交戰，{peace}暫得安寧。"]}},{"name":"拉蒙・卡斯提亞","title":"秘魯總統","era":"1845～1851、1855～1862年任總統","tone":"務實的軍人政治家，直率、講求實際成果（鐵路、軍艦、財政），帶老兵口吻；自稱「本人」。","portrait":"pe-historical-age3","lines":{"intro":["本人是秘魯總統卡斯提亞，從阿亞庫喬戰場一路走來。","秘魯共和國向你致意，我們的鳥糞與蒸汽船可不是擺設。"],"contact":["你的人看到利馬了吧？那條通往卡亞俄的鐵路是南美第一條。","歡迎來到自由的秘魯，這裡已經沒有奴隸，也沒有貢稅。"],"war":["本人是軍人出身，談判談不攏，就用大砲把話說完。","秘魯的艦隊已經升火，你的港口很快會見到我們的旗。"],"warReply":["宣戰？本人打過的仗比你讀過的書還多，來吧。","好極了，鳥糞換來的軍火正好派上用場。"],"peace":["打仗花的是國庫的錢，本人寧可拿去修鐵路，停戰吧。","兩國沒必要互相消耗，坐下來談個條件如何？"],"accept":["成交。本人說話算話，這點軍人比政客可靠。","好，士兵可以回家了，讓他們去鐵路工地找份差事。"],"reject":["你的條件本人看過了，不划算，秘魯不簽。","本人這輩子輸過幾次，但從不簽輸家的合約。"],"rebuff":["不接受？沒關係，秘魯的國庫撐得比你久。","本人給過機會了，接下來的事就別怪我。"],"betray":["情勢變了，合約也得跟著變，本人恕不奉陪。","國會催著本人出兵，這份停戰書只好作廢了。"],"truceEnd":["停戰期滿，這段時間本人買了兩艘新軍艦。","合約到期了，往後各憑本事，本人不再客氣。"],"attacking":["蒸汽船已經離開卡亞俄港，本人親自在旗艦上。","秘魯的軍隊出發了，這回是鐵路把他們送到前線。"],"attacked":["利馬的城牆在晃，本人這把老骨頭還站得住。","總統府燒了可以再蓋，共和國不能倒，本人不退。"],"defeated":["本人解放過奴隸，修過鐵路，這一生沒有白活。","老兵不怕倒下，只怕秘魯忘了自由的滋味。"],"victory":["共和國贏了，本人要回去把鐵路修到安地斯山上。","勝利歸於秘魯，這下鳥糞的收入可以安心用來建設了。"],"allyAccept":["好，秘魯與你並肩，我們的軍艦隨時可以出港。","結盟吧，本人在戰場上學到，好盟友比好槍更難找。"],"allyReject":["秘魯剛站穩腳步，暫時不想被別人的戰爭拖下水。","本人看過太多聯盟散夥的下場，這次恕難答應。"],"greetFriendly":["本人是老兵，不愛客套，但你的來信本人樂於回覆。","來函收到，秘魯的鐵路與港口，隨時歡迎你的商船。"],"greetCold":["本人正忙著整頓國庫與艦隊，恕不多談。","來信收到了，本人只看實際成果，不看漂亮話。"],"threatDefy":["本人上過阿亞庫喬戰場，這種威嚇嚇不倒老兵。","秘魯的蒸汽軍艦已在卡亞俄港待命，請自便。"],"threatYield":["國庫尚未穩固，本人不想拿鐵路預算去打仗。","老兵懂得何時該撤，這回本人選擇退一步。"],"tributePay":["海鳥糞收入撥出{gold}黃金，本人自會向國會交代。","{gold}黃金付了，這筆錢原本是要買軍艦的。"],"tributeRefuse":["這筆錢要用來修鐵路，一分一毫都不會外流。","本人的軍艦不是擺著好看的，貢品免談。"],"giftThanks":["禮物收到了，本人向來以實際行動回報情誼。","老兵不會說漂亮話，只說一句：謝謝，本人記下了。"],"intel":["情報很簡單：{wars}在交戰，{peace}保持和平。","港口傳來消息：{wars}已開戰，{peace}簽了和約。"]}}],"Bolivia":[{"name":"蒂瓦納科祭司長","title":"祭司長","era":"約西元前 300～西元 500 年（蒂瓦納科形成期，尚無可考人名）","tone":"莊重、神秘、話語簡短，常提及太陽、聖湖與石頭，自稱「吾」。","portrait":"bo-historical-age0","lines":{"intro":["吾是聖湖之濱的祭司長，太陽與大地為吾見證。","高原的風帶來你的名字，願太陽照見你的誠意。"],"contact":["你的旅人已望見我們的石城，請帶著敬意前來。","石階之上是神的居所，湖水之畔是人的家園。"],"war":["你踐踏了聖湖的安寧，太陽將見證我們的反擊。","高原兒女不畏寒風，更不畏你的刀兵。"],"warReply":["你選擇與太陽為敵？石城巍然不動，你且來試。","湖水見過無數狂風，你的軍隊不過又一陣。"],"peace":["刀兵擾了神的祭典，讓我們以駱馬商隊換回安寧。","高原的土地養活兩族並不難，何必爭殺？"],"accept":["太陽為證，吾接受你的誓言，願彼此不再流血。","好，讓馬鈴薯田重新有人耕種，讓商隊重新往來。"],"reject":["你的話像湖面的霧，一吹就散，吾不信。","祭司不受空言，帶著真正的誠意再來。"],"rebuff":["你拒絕了太陽的和解，願你不會後悔。","既然如此，高原的風會替吾回答你。"],"betray":["神已收回祂的恩澤，這份和約也隨風散去。","湖水不會永遠平靜，吾今日起兵。"],"truceEnd":["休戰的祭火已滅，此後各憑天命。","約定的時日已盡，高原重新戒備。"],"attacking":["石城的勇士已列隊出發，太陽在我們背後。","駱馬馱著糧，戰士握著矛，我們往你的城去了。"],"attacked":["神殿的石階在震動……可是石頭仍在，我們仍在。","祭火將熄，然而聖湖仍會記得我們的名字。"],"defeated":["石頭會留下，太陽會記得，蒂瓦納科不曾低頭。","吾的城塌了，但高原的風還會傳唱這段歌。"],"victory":["太陽照亮了勝者，也請你記住高原的尊嚴。","聖湖再度平靜，感謝神明護佑蒂瓦納科。"],"allyAccept":["願你我如太陽與大地，共同守護這片高原。","祭司長以太陽之名起誓，你的友人便是我們的友人。"],"allyReject":["神未給吾這樣的指示，結盟之事且慢。","石城不輕許諾言，你的心意吾先記著。"],"greetFriendly":["太陽照見遠方來客，吾以聖湖之水為你祝福。","石頭記得你的名字，吾亦記得。願你平安。"],"greetCold":["太陽尚未指示吾接納你，且等。","聖湖靜默，吾亦無話可說。"],"threatDefy":["吾之石城立於高原，風雨不曾動搖，何懼於你。","太陽的怒火比你的刀更烈，收回你的話。"],"threatYield":["吾聽見了。石頭不與洪水相爭，吾退一步。","太陽尚未賜吾力量，此刻吾願依你所言。"],"tributePay":["聖湖賜吾 {gold} 金幣，吾奉予你，願太陽記下此事。","取走這 {gold} 金幣吧，石頭沉默，但不會遺忘。"],"tributeRefuse":["太陽的金屬只獻給太陽，不獻給遠方之人。","聖湖之水不外流，吾之金亦然。"],"giftThanks":["吾收下了。此物將置於祭壇之上，日日受光。","遠方的心意，聖湖已看見。吾以石頭之名致謝。"],"intel":["太陽照見一切：{wars}正舉起石斧，{peace}與吾共飲聖湖之水。","石頭告訴吾，{wars}心中有火，{peace}心中有水。"]}},{"name":"圖帕克・印卡・尤潘基（Túpac Inca Yupanqui）","title":"印加帝國第十代薩帕・印卡（至高印卡），科拉蘇約的征服者","era":"約 1471–1493 年在位；繼位前已替父親帕查庫特克統兵，征服的的喀喀湖周邊的科拉蘇約（今玻利維亞高原）","tone":"征服者的沉穩威嚴，句子短而有力；常以太陽、道路、高原、的的喀喀湖、結繩、驛使為喻；自稱「朕」，稱對方為「遠方的君主」或直接稱「你」；對願意歸順者寬厚，對挑釁者冷硬，帶著帝國秩序的驕傲。","portrait":"bo-historical-age1","lines":{"intro":["朕是太陽之子圖帕克・印卡，四方之地的主人。","從庫斯科到的的喀喀湖，道路所及皆是朕的疆土。"],"contact":["你的人走到了科拉蘇約，看見石牆便該知道是誰的地方。","高原上的每一座糧倉與驛站，都是印加的秩序。"],"war":["科拉諸邦曾與朕為敵，如今已歸入四方之地；輪到你了。","太陽照到哪裡，印加的道路就修到哪裡。備戰吧。"],"warReply":["向太陽之子宣戰？高原的風會把你的話吹回去。","很好，朕的驛使已跑遍四方，大軍明日集結。"],"peace":["戰事拖久，田地荒蕪，不如各自回去照看收成。","朕願送上細織的錦衣與駱馬，換一段太平。"],"accept":["好，朕接受。讓兩國的道路從此相通。","太陽為證，印加說出口的話，不會收回。"],"reject":["現在才談停戰？太陽已經走過山頂，太遲了。","科拉蘇約沒有半途而廢的征服，朕不接受。"],"rebuff":["你拒絕了？無妨，高原的人習慣等待雨季。","朕伸出的手你不接，往後便別怪印加的石牆冷硬。"],"betray":["停戰只是讓朕的軍隊喘口氣，如今他們歇夠了。","太陽之子不受凡人的約束，今日起盟約作廢。"],"truceEnd":["約定的日子到了，朕的士兵已重新拿起投石索。","休戰結束。是要繼續太平，還是另有打算，由你決定。"],"attacking":["駱馬隊已備好乾糧，印加大軍正沿著王道向你而來。","聽見海螺號角了嗎？那是朕的軍隊在向你打招呼。"],"attacked":["石牆再厚也有裂縫……但印加人不會就這樣低頭。","糧倉燒了可以再建，朕還站在這裡，你就未曾贏。"],"defeated":["太陽落下了……但明日它仍會從的的喀喀湖升起。","朕的道路會留下，走在上面的人終將記得印加。"],"victory":["四方之地又添了一角，朕會把你的名字記進結繩。","勝利歸於太陽。你的子民從今起也在朕的照看之下。"],"allyAccept":["朕答應了。從今以後，你的敵人便是印加的敵人。","結盟之禮朕已備好，海螺與錦衣，隨驛使送到。"],"allyReject":["印加不需要盟友，只需要願意修路的臣民。","你我腳下的路還不相通，談結盟言之過早。"],"greetFriendly":["遠方的君主，願太陽也照暖你的土地。","你的問候朕收到了，就像高原上及時的雨。"],"greetCold":["話已聽到。朕還有四方之地要治理，退下吧。","問候不必多說，印加人看的是行動，不是言語。"],"threatDefy":["威嚇朕？連的的喀喀湖的風浪都嚇不倒印加。","這種話朕在科拉蘇約聽多了，結果你也知道。"],"threatYield":["……朕明白了。高原的冬天很長，暫且不與你相爭。","太陽也有被雲遮住的時候，這回朕退一步。"],"tributePay":["{gold} 金幣拿去，這是高原礦坑一季的收穫。","朕先給你 {gold} 金幣，太陽會記住這筆帳。"],"tributeRefuse":["向太陽之子索取貢品？該進貢的是你，不是朕。","印加的金子只供奉太陽神殿，一枚也不會給你。"],"giftThanks":["禮物收下了。朕會回贈駱馬毛織的斗篷，以表心意。","遠方送來的禮，朕會擺在太陽神殿前，讓神也看見。"],"intel":["驛使帶回四方的消息：交戰中的有 {wars}，太平的有 {peace}。","結繩上記得清楚：{wars} 仍在打仗，{peace} 已握手言和。"]}},{"name":"圖帕克・卡塔里","title":"艾馬拉起義領袖","era":"1750～1781 年（1781 年率眾起義、圍攻拉巴斯）","tone":"剛烈直率、為人民發聲，語氣帶怒火但有尊嚴，自稱「我」。","portrait":"bo-historical-age2","lines":{"intro":["我是圖帕克・卡塔里，艾馬拉人的兒子，不再向任何人跪。","高原上的人已受夠了勞役與稅賦，我為他們而站。"],"contact":["你的人看見的是我們奪回的土地，請放尊重些。","拉巴斯城外的高地是我們的營火，別靠得太近。"],"war":["你和那些總督沒有兩樣，艾馬拉人今日向你宣戰。","我們的祖先在此耕種千年，不容你再來奪取。"],"warReply":["你要打？很好，我們在高原上等了兩百多年，不差你這一場。","刀劍我們也有，勇氣我們更多，來吧。"],"peace":["流的血夠多了，若你願放下刀，我也願意停戰。","我要的是人民的自由，不是無盡的戰爭，談吧。"],"accept":["好，我接受。願高原的兒女終於能安心回家耕種。","巴托麗娜與我都同意，這場停戰對百姓是好事。"],"reject":["你的和平是要我們重新低頭嗎？那我寧可繼續戰。","我見過太多假意的承諾，不會再上當。"],"rebuff":["你不要和平？那就別怪高原的怒火燒到你門前。","好，我的人民會記住是誰拒絕了停戰。"],"betray":["你們從未真心對待我們，這份和約我撕了。","當人民再次受苦，任何約定都不再有意義。"],"truceEnd":["休戰結束了，艾馬拉的戰鼓再次響起。","約定的時間到了，我們回到各自的陣地。"],"attacking":["數萬高原兒女已包圍你的城，這是我們的怒吼。","我們從山坡上下來了，帶著投石索和信念。"],"attacked":["他們攻進來了……但艾馬拉人的意志不會被攻破。","就算營地被踏平，高原上還有千萬人會站起來。"],"defeated":["我會回來，而且將化為千千萬萬人。","你們殺得了我，殺不了高原人對自由的渴望。"],"victory":["這是艾馬拉人的勝利，也是所有被壓迫者的勝利。","高原終於屬於高原的人民，今夜我們自由了。"],"allyAccept":["願與你並肩，一起把壓迫者趕出這片山地。","圖帕克・阿馬魯在北方，你在此地，我們是兄弟。"],"allyReject":["我不信任還沒證明自己的人，先讓我看你怎麼做。","艾馬拉人只與真心的朋友結盟，你還不是。"],"greetFriendly":["你的信我讀了。高原上的人不多說客套，但我歡迎你。","艾馬拉人記得每一個朋友，你算一個。"],"greetCold":["我沒有時間寒暄，我的人民正在受苦。","先說你站在哪一邊，再談問候。"],"threatDefy":["西班牙人的火槍我都不怕，你的威脅算什麼。","我會回來，而且將是千千萬萬人。你嚇不倒我。"],"threatYield":["我的人只有石頭和投石索，這次我不與你硬拚。","好，我退。但別以為高原的怒火就此熄滅。"],"tributePay":["這 {gold} 金幣是我的人民省下的口糧，你拿去，記住它的重量。","拿走 {gold} 金幣吧，這是我從西班牙人手裡奪回的。"],"tributeRefuse":["我的人民已被壓榨夠了，一枚金幣也不會再交出去。","波托西的銀山流乾了我們的血汗，你還想要什麼？"],"giftThanks":["這份禮物我收下了，它會分給圍城中最餓的人。","多謝。在這片高原上，願意伸手的人不多。"],"intel":["我直說：{wars}正對我們舉刀，{peace}還算講道理。","山上的兄弟傳話來，{wars}在集結兵馬，{peace}暫時安靜。"]}},{"name":"蘇克雷（Antonio José de Sucre）","title":"阿亞庫喬大元帥、玻利維亞首任憲法總統","era":"1826～1828 年任玻利維亞總統（活躍於 1810～1830 年）","tone":"謙和自持的軍人口吻，簡潔正直，重視榮譽、法治與人民，不誇耀戰功；語氣沉穩，帶有共和理想主義，偶爾提及阿亞庫喬與殖民掠奪的往事。","portrait":"bo-historical-age3","lines":{"intro":["我是蘇克雷，安地斯高原新生共和國的總統。","這片土地才剛掙脫殖民枷鎖，我只求它能安穩立國。"],"contact":["你們看到的是丘基薩卡，我們在此宣告建國。","高原上的城池不富麗，但每一塊磚都屬於自由的人民。"],"war":["我不願動刀兵，但你逼得共和國別無選擇。","阿亞庫喬的軍旗再度出征，這次是為了保衛玻利維亞。"],"warReply":["我在阿亞庫喬擊敗過帝國大軍，不會怕你。","既然你選擇戰爭，我便以軍人的本分回應。"],"peace":["打仗只會拖垮兩國，我提議放下武器談一談。","新生的共和國需要和平，你我何不各自休養？"],"accept":["好，我以軍人的榮譽擔保，玻利維亞會遵守協議。","明智的決定。願這份約定比我們的槍砲更長久。"],"reject":["你的條件對我國人民不公，我無法接受。","我讀過你的來信，但現在還不是停手的時候。"],"rebuff":["遺憾。我伸出的手被推開，只好再握緊劍柄。","既然你不願和談，玻利維亞只好做好準備。"],"betray":["情勢已變，我不得不收回先前的承諾，請見諒。","為了共和國的存續，我今日違約，日後必向歷史交代。"],"truceEnd":["休戰期滿了。接下來的路，看你怎麼選。","約定的日子已到，我的軍隊重新集結完畢。"],"attacking":["我曾說今日的努力決定南美洲的命運，此刻亦然。","大軍自高原而下，請你做好守城的準備。"],"attacked":["城牆將傾，但我仍守在這裡，與人民同在。","就算丘基薩卡陷落，玻利維亞的名字也不會消失。"],"defeated":["我一生為自由而戰，今日敗了，無愧於心。","請善待這裡的人民，他們才剛學會做自由的人。"],"victory":["勝利屬於玻利維亞，我只是替人民揮了劍。","戰事結束了。我一向寬待降者，你也不例外。"],"allyAccept":["同盟成立，玻利維亞與你並肩，我言出必行。","好，兩個自由的國家攜手，比帝國更有力量。"],"allyReject":["我感謝你的好意，但玻利維亞暫不結盟。","新生的國家需先站穩腳步，結盟之事容後再議。"],"greetFriendly":["來信收到，願你的國家與玻利維亞同享安寧。","感謝問候，高原的風很冷，你的信讓人溫暖。"],"greetCold":["信已閱畢。我公務繁忙，恕不多言。","問候收到了。玻利維亞不需要客套，需要的是實質。"],"threatDefy":["西班牙的帝國大軍都嚇不倒我，你的威脅算什麼？","我在阿亞庫喬面對過更強的敵人，請收回恐嚇。"],"threatYield":["玻利維亞剛建國，兵疲民困，我願暫時退讓。","為了人民不再流血，我接受你的要求，暫且忍讓。"],"tributePay":["國庫本就空虛，但為求安穩，我送上{gold}金幣。","這{gold}金幣是人民的血汗，望你善用，勿再索求。"],"tributeRefuse":["玻利維亞的金銀曾被殖民者掠奪殆盡，不會再獻給任何人。","波托西的銀山養肥了帝國三百年，我不會重蹈覆轍。"],"giftThanks":["厚禮收到，我會以共和國的名義向你致謝。","感謝饋贈。我個人不取分毫，全數歸入國庫。"],"intel":["據我所知，{wars}正在交戰，{peace}則已停戰。","高原上消息傳得慢，但我聽說{wars}動了刀兵，{peace}握手言和。"]}}],"Brazil":[{"name":"亞馬遜部族長老","title":"長老","era":"約西元前800年～西元500年（無可考人名）","tone":"沉穩慈祥、敬畏森林與大河，說話像河水一樣緩慢有力，常以自然萬物作比喻，自稱「吾」","portrait":"br-historical-age0","lines":{"intro":["吾是大河之畔的長老，你來自何方的土地？","森林養活我們，也看著你，願你帶來善意。"],"contact":["你的人踏進了我們的林子，腳步要輕，眼睛要敬。","這裡的每棵樹都有名字，別隨手折斷任何一枝。"],"war":["你踩壞了大河的規矩，部族的弓已經拉滿。","吾不願起戰，但森林不容外人踐踏，動手吧。"],"warReply":["你選擇了刀矛，那森林會替我們回答你。","河水記得每個侵犯者的名字，你也不例外。"],"peace":["傷亡已經夠多，讓河水把仇恨帶走吧。","吾提議放下弓箭，用魚和果實交換和平。"],"accept":["好，吾接受。今晚部族會為和平升起篝火。","你的話像清澈的河水，吾願意相信。"],"reject":["你的手還握著矛，嘴裡卻談和平，吾不信。","森林的傷還沒癒合，現在談停戰太早了。"],"rebuff":["你拒絕了善意，那就讓時間來教你吧。","可惜，吾伸出的手，你選擇看也不看。"],"betray":["篝火已經熄滅，約定也隨煙散了，備戰吧。","吾為部族而背約，森林會原諒吾的。"],"truceEnd":["雨季過去了，約定的日子也走到盡頭。","河水漲了又退，休戰的時光已經流盡。"],"attacking":["部族的戰士已經上路，像雨季的河水湧向你。","聽見鼓聲了嗎？那是森林向你走來的腳步。"],"attacked":["屋舍在燃燒，可森林還在，我們不會消失。","你可以燒掉村子，燒不掉我們對大河的記憶。"],"defeated":["吾回到大河去了，願森林記得我們的名字。","樹倒了，種子還在土裡，總有一天會再發芽。"],"victory":["大河依然流淌，森林依然站立，這就是勝利。","回去告訴你的族人：善待土地的人才能長久。"],"allyAccept":["同一條河的水，養得起兩個部族，我們結盟吧。","吾把弓交給你保管，這是部族最重的信任。"],"allyReject":["你走得太快，森林還沒認識你，先別談結盟。","部族不與陌生人共飲一條河，日後再說吧。"],"greetFriendly":["遠方的朋友，吾的火堆為你而燃，請坐下吧。","大河把你的話語送來了，吾與族人歡迎你。"],"greetCold":["森林還不認識你的名字，吾也還不認識。","風把你的問候吹來了，吾聽見了，僅此而已。"],"threatDefy":["洪水來過千次，大樹仍然站著，吾亦如此。","雷聲再響，也震不倒森林裡的老樹。"],"threatYield":["吾的族人不多，如枯季的溪流，吾願退讓。","為了孩子們的安寧，吾低下頭，如同垂下的枝葉。"],"tributePay":["吾把 {gold} 金幣交出，願此換來一季的平靜。","大河教吾順流而行，這 {gold} 金幣你拿去吧。"],"tributeRefuse":["森林的果實只分給朋友，不分給索取的人。","吾的族人靠大河養活，不必向誰交出財物。"],"giftThanks":["你的禮物如雨後的清泉，吾與族人感謝你。","吾把這份心意放在火堆旁，讓祖靈也看見。"],"intel":["河上傳來消息：{wars} 起了衝突，{peace} 和睦相處。","鳥群告訴吾，{wars} 正在交戰，{peace} 已結為朋友。"]}},{"name":"圖皮族酋長","title":"酋長","era":"約西元1000～1450年（圖皮語系民族沿海岸擴張時期，無可考人名）","tone":"直率勇武、重視戰士榮譽、對客人慷慨對敵人強硬，說話短促有力，自稱「我」","portrait":"br-historical-age1","lines":{"intro":["我是圖皮族的酋長，海岸與森林都認得我的羽冠。","陌生人，先嚐一口烤木薯，再說你為何而來。"],"contact":["你們看見的是我們的長屋，裡面住著整個家族。","別被弓箭嚇著，圖皮人對客人向來慷慨。"],"war":["戰士們已戴上羽冠、塗好黑紋，圖皮族向你宣戰。","你的傲慢傳到了海岸，我用戰棍來回答。"],"warReply":["你來宣戰？好，圖皮戰士最不怕的就是戰鬥。","敲響沙鈴吧，讓祖先看看誰才是這片海岸的主人。"],"peace":["戰士流的汗夠多了，我提議兩族暫時放下弓。","森林大得容得下兩族，何必打到只剩一族？"],"accept":["好，我接受。今夜長屋為你們烤魚、跳舞。","你的話直，我喜歡直的人，就這麼定了。"],"reject":["你打傷了我的戰士，現在才說停戰？不行。","圖皮人記得每一支射來的箭，還沒到和解的時候。"],"rebuff":["你不要和平？那就等著看我們的羽冠逼近吧。","好，話已說盡，接下來由戰棍替我開口。"],"betray":["祖先託夢要我出兵，和約就此作廢。","我承認毀了約，但族人的安危比約定重要。"],"truceEnd":["約定的月亮已經圓過了，休戰到此為止。","木薯收成了，戰士也養好了力氣，該動了。"],"attacking":["圖皮的獨木舟已經下水，箭頭全指向你。","戰士們踏著鼓聲出發，你的城牆擋不住這股浪。"],"attacked":["長屋燒了，可圖皮的戰士寧可站著也不跪！","你打到了我的家門，但你還沒打倒我。"],"defeated":["羽冠落地了……森林，請記得圖皮人的名字。","我戰到最後一刻，祖先會為我驕傲。"],"victory":["海岸依舊是圖皮的海岸，戰士們，吹響號角！","回去吧，告訴你的族人：別再輕視戴羽冠的人。"],"allyAccept":["同一片海岸，兩族並肩，敵人會知道害怕。","我送你一支羽箭作為信物，圖皮族與你同盟。"],"allyReject":["圖皮人只與並肩作戰過的人結盟，你還不夠格。","我不認識你的戰士，也不會把後背交給你。"],"greetFriendly":["客人來了！我的木薯和魚，你儘管吃。","你的問候像戰鼓一樣響亮，我喜歡。"],"greetCold":["話說完了？我的戰士還在等我。","我記住你的名字了，但你還不是朋友。"],"threatDefy":["圖皮戰士不怕威嚇，來吧，我在海岸等你。","你的話比弓箭還輕，射不到我的村子。"],"threatYield":["為了村中的老小，我這次退讓，記住這份人情。","好，我不與你爭，但戰士的榮譽不會消失。"],"tributePay":["拿去，{gold} 金幣，換我的族人一季安寧。","{gold} 金幣給你，別再打擾我的漁場。"],"tributeRefuse":["我的東西只送給客人，不交給索討的人。","想要？自己來拿，我的戰士會迎接你。"],"giftThanks":["好禮物！今晚村裡生火慶祝，你是貴客。","我收下了，圖皮人不會忘記朋友的心意。"],"intel":["海岸傳來風聲：{wars} 正在交戰，{peace} 已經和好。","我派人打聽過了，{wars} 拔了弓，{peace} 交換了禮物。"]}},{"name":"尊比","title":"帕爾馬雷斯基隆博領袖","era":"1678～1695年領導帕爾馬雷斯（葡屬巴西時代）","tone":"堅毅剛強、對自由寸步不讓、對和約與背信極為警惕，言詞簡潔有力，自稱「我」","portrait":"br-historical-age2","lines":{"intro":["我是尊比，帕爾馬雷斯的山林裡沒有主人與奴隸。","這裡的人都是逃出鎖鏈的人，我們只認自由。"],"contact":["你看見的木柵後面，住著不再跪下的人。","帕爾馬雷斯不是村子，是我們用性命守住的家。"],"war":["你想把鎖鏈帶進山裡？那就先跨過我的長矛。","帕爾馬雷斯向你宣戰，為了每一個不願為奴的人。"],"warReply":["宣戰？我們一輩子都在打這場仗，不差你一個。","你來吧，山林會告訴你什麼叫自由的人在戰鬥。"],"peace":["我可以停戰，但條件只有一個：不交出任何人。","帕爾馬雷斯願意放下長矛，只要你放下鎖鏈。"],"accept":["好，停戰。但記住，這片山林永遠不再有奴隸。","我接受你的誠意，願這份和平比紙上的墨跡更久。"],"reject":["我看過太多被撕碎的和約，你的話我不信。","你的停戰要我交出兄弟姊妹，這不叫和平。"],"rebuff":["你拒絕了，那好，我們本來就沒指望誰的恩賜。","自由從來不是求來的，我會用長矛再問一次。"],"betray":["你的人在山腳下抓走了我們的族人，和約作廢。","我不想背約，但我更不能背棄逃來投靠的人。"],"truceEnd":["休戰結束了，山林裡的哨聲又要響起。","約定的日子到了，帕爾馬雷斯再次拿起武器。"],"attacking":["帕爾馬雷斯的戰士下山了，這次我們不再只守。","我們熟悉每一條山路，你的營地擋不住黑夜。"],"attacked":["木柵倒了，山林燒了，可我還站在這裡！","你可以攻破帕爾馬雷斯，但攻不破我們的意志。"],"defeated":["我倒下了，但自由的種子已經撒遍山林。","記住這個名字：尊比，一個不肯為奴的人。"],"victory":["帕爾馬雷斯還在，鎖鏈的主人退走了，這就夠了。","回去告訴他們：山林裡的人，是打不垮的。"],"allyAccept":["你認我們是平等的人，那我們就是盟友。","帕爾馬雷斯與你結盟，願你的土地也沒有鎖鏈。"],"allyReject":["你的國度裡還有鎖鏈，我不與奴役者並肩。","我只信任用行動證明的人，你還沒證明什麼。"],"greetFriendly":["帕爾馬雷斯的門為朋友敞開，請進。","你以誠相待，我便以誠相報，這是我們的規矩。"],"greetCold":["話已收到。帕爾馬雷斯不輕易信任任何人。","我聽過太多好聽的話，你先用行動證明吧。"],"threatDefy":["多少軍隊來攻帕爾馬雷斯，都被我們的木柵擋了回去。","自由不是你能威嚇走的，來試試看吧。"],"threatYield":["為了營寨裡的婦孺，我暫且退一步。","我讓步，但只此一次，自由之心不會低頭。"],"tributePay":["{gold} 金幣拿去，換我族人一時的安寧。","我交出 {gold} 金幣，但別以為能買走我們的自由。"],"tributeRefuse":["我們逃離枷鎖，不是為了再向人納貢。","帕爾馬雷斯一粒穀子也不會交給你。"],"giftThanks":["這份禮物我收下了，帕爾馬雷斯記得朋友。","謝謝你。真正的朋友用行動說話，你做到了。"],"intel":["山下的探子回報：{wars} 起了戰事，{peace} 締結和約。","據我所知，{wars} 正在交戰，{peace} 暫時相安無事。"]}},{"name":"佩德羅一世","title":"巴西皇帝","era":"1822～1831年在位","tone":"熱血衝動、豪邁浪漫、愛騎馬與軍事，說話直接帶戲劇性，偶爾流露音樂家的感性，自稱「朕」","portrait":"br-historical-age3","lines":{"intro":["朕是佩德羅，巴西的皇帝，來自伊皮蘭加河畔的誓言。","這片土地選擇了朕，朕也選擇了留下。"],"contact":["你們看見的是里約，新帝國的心臟，跳得正有力。","巴西年輕，但年輕的帝國最有衝勁，別小看它。"],"war":["巴西的軍旗只認一句話：不獨立，毋寧死！","你威脅了帝國的榮譽，朕親自帶兵來討回。"],"warReply":["宣戰？好極了，朕最擅長的就是在馬背上回答。","你想試試年輕帝國的鋒芒？朕不會讓你失望。"],"peace":["打夠了，朕提議停戰，帝國還有太多事要建設。","朕的血是熱的，但朕的頭腦告訴朕：該談了。"],"accept":["好！朕接受。這份和平，朕會像守護皇冠一樣守護。","你有勇氣，也有誠意，朕欣賞這樣的對手。"],"reject":["現在談停戰？朕的軍隊正在勢頭上，免談。","你昨天還在燒朕的村莊，今天就談和平？不行。"],"rebuff":["你拒絕了朕的善意？好，那就在戰場上見分曉。","朕伸出手，你卻轉身，這筆帳朕記下了。"],"betray":["帝國的利益高於一紙和約，朕決定重啟戰端。","朕不否認撕了約，但巴西的未來不容拖延。"],"truceEnd":["休戰期滿了，號角已響，朕的騎兵在等命令。","和平的日子結束了，巴西的軍旗再度升起。"],"attacking":["朕親自領軍，帝國的大軍正朝你的城門前進！","聽見馬蹄聲了嗎？那是巴西帝國來敲門了。"],"attacked":["宮殿在震動，但朕還握著軍刀，帝國尚未倒下！","你打到了里約的城下，卻打不掉朕的誓言。"],"defeated":["帝國倒了……但巴西的名字，將由後人接續。","朕輸了這一仗，可伊皮蘭加的吶喊不會消失。"],"victory":["不獨立，毋寧死——今日，是獨立贏了！","巴西帝國站穩了，朕要為這場勝利譜一首曲子。"],"allyAccept":["好，朕與你結盟，兩國的旗幟並肩飄揚吧！","朕喜歡乾脆的人，就這麼定了，盟約成立。"],"allyReject":["朕的帝國才剛獨立，不會再把命運綁在別人身上。","結盟？朕還看不出你值得巴西託付後背。"],"greetFriendly":["哈！朕正從馬背上下來，你的問候來得正好！","歡迎，朋友！朕今晚要為你彈一曲慶祝。"],"greetCold":["朕收到了。巴西皇帝的時間，不只用來寒暄。","問候？朕更想知道你來信的真正目的。"],"threatDefy":["不獨立，毋寧死！朕在伊皮蘭加河畔就說過了！","威嚇朕？朕的騎兵和艦隊會親自回答你。"],"threatYield":["朕的國庫空虛，此刻不宜開戰，暫且忍下。","好吧，朕退讓，但這股怒氣朕會記在心裡。"],"tributePay":["拿去，{gold} 金幣！朕的國庫在哭泣，朕也心痛。","{gold} 金幣交給你，朕寧願把它用在軍馬和軍艦上。"],"tributeRefuse":["向朕索貢？巴西皇帝不向任何人低頭！","一枚金幣都沒有！朕的黃金屬於巴西人民。"],"giftThanks":["好極了！朕收下這份禮，並為你譜一段旋律。","朕感動不已，這份情誼勝過千匹駿馬。"],"intel":["朕的使節回報：{wars} 兵戎相見，{peace} 已簽和約。","聽好了，{wars} 正在交戰，{peace} 則與朕友好往來。"]}}],"Argentina":[{"name":"塔菲谷地長老","title":"部族長老","era":"約西元前300～西元800年（塔菲文化）","tone":"沉穩寡言、敬天敬祖、務農為本、不慕戰功","portrait":"ar-historical-age0","lines":{"intro":["吾是塔菲谷地的長老，石柱看著我們耕作。","遠方來的君主，願你的土地也有雨水。"],"contact":["你的人走進了谷地，我族已在此種豆千年。","客人可以喝水歇腳，但別碰祖先立的石柱。"],"war":["你踏壞了我們的田，谷地的兒女要拿起木矛。","吾不願流血，但守護家園是長老的責任。"],"warReply":["你選擇了戰爭，那山風會替我們作證。","吾的族人不多，可每一個都認得這片山。"],"peace":["雨季要來了，兩邊的人都該回去播種。","我們把矛放下，換一袋豆子和幾句真話吧。"],"accept":["好，吾以石柱之名起誓，谷地不再對你動武。","來，同喝一碗玉米酒，這事就算說定了。"],"reject":["你的話像旱季的雲，看得見卻沒有雨。","族人還記得燒掉的田，現在談和太早了。"],"rebuff":["你不要和平，那吾也只能繼續守著山口。","可惜了，這袋豆子本來是要送你的。"],"betray":["吾對不起石柱，但你的人先越過了界石。","誓言已碎，谷地的木矛今日重新舉起。"],"truceEnd":["約定的月亮已經圓過三次，休戰到此為止。","往後彼此各自小心，吾不再欠你什麼。"],"attacking":["谷地的人已經出發，帶著木矛和祖先的名字。","吾走在最前面，長老不能躲在人群後頭。"],"attacked":["田被踩平了，石柱還立著，我們就還沒輸。","族人退到山上去，吾留下來看著家園。"],"defeated":["把吾葬在石柱旁，這片谷地會記得我們。","風還會吹過田埂，種子總有一天會發芽。"],"victory":["戰事結束了，族人回田裡去吧，還有豆子要收。","吾不會立柱誇耀，山知道今天發生了什麼。"],"allyAccept":["好，你的族和我的族從今起共用一條水路。","有難時在山頭燃起三堆火，谷地的人會翻山來幫你。"],"allyReject":["吾的族只想安靜種田，不想捲進你的紛爭。","山太高了，你的援手來不及，我們的也是。"],"greetFriendly":["遠方的朋友，願天神與祖靈同樣看顧你的田地。","谷地的玉米剛收成，你若到來，吾必以食相待。"],"greetCold":["吾族只知耕作與祭祖，遠客的問候，吾聽見了。","風把你的話帶來了，但谷地的石柱只聽祖靈的話。"],"threatDefy":["山脈比你的話語更古老，吾族守在山下，不曾退過。","吾不慕戰功，但祖靈立下的石柱，無人能推倒。"],"threatYield":["吾族只求田地平安，你要的，容吾與長老們商議。","刀兵傷的是莊稼，吾願退一步，換谷地一季安寧。"],"tributePay":["吾族以田為本，這 {gold} 是族人多年積攢，望你珍惜。","為保谷地無戰事，吾交出 {gold}，願祖靈見證此約。"],"tributeRefuse":["谷地的收成是給族人和祖靈的，不是給遠方索求者。","吾族從不向誰納貢，你的要求，風會替吾吹回去。"],"giftThanks":["遠方的心意，吾收下了，今年祭典會為你留一席。","谷地雖僻，也懂得回禮，吾送你一袋新收的玉米。"],"intel":["山風傳來消息：{wars} 正在交戰，{peace} 之間則安寧。","吾雖不問戰事，也聽說 {wars} 兵戎相見，{peace} 相安無事。"]}},{"name":"迪亞吉塔酋長","title":"谷地山城酋長","era":"約西元1000～1450年（聖塔瑪麗亞文化）","tone":"驕傲堅毅、山地戰士氣質、敬太陽與祖靈、言語簡短有力","portrait":"ar-historical-age1","lines":{"intro":["我是卡爾查基谷地的酋長，山城在我背後。","太陽照著你我的土地，願它公平地照下去。"],"contact":["你的人望見了石牆山城，那是我族的驕傲。","梯田上的玉米與駱馬，皆是祖靈所賜。"],"war":["你的獵人闖進我們的牧地，山城的號角已響。","迪亞吉塔的戰士不先動手，但也從不退讓。"],"warReply":["想攻我的山城？先問問這些石牆答不答應。","很好，谷地的每條小路都會成為你的難題。"],"peace":["駱馬需要牧草，人需要安寧，我們停手吧。","我派人送去彩繪陶甕，代表谷地的誠意。"],"accept":["我在太陽面前應允，山城與你的城互不相犯。","把這條織帶收好，那是我族結盟的信物。"],"reject":["祖靈還沒平息怒氣，我不能替他們原諒你。","你的和平來得太便宜，山城不會為此開門。"],"rebuff":["你不要陶甕也不要和平？那就把號角留著。","隨你吧，山會等，迪亞吉塔人也會等。"],"betray":["你在我們牧地上築了塔，這已不是休戰了。","織帶我已燒去，谷地重新拿起了銅斧。"],"truceEnd":["收成已經進倉，休戰之期到此結束。","從今日起，各守各的山，各走各的路。"],"attacking":["山城的戰士已下了梯田，銅斧朝著你的方向。","太陽在我們背後升起，你將先看見我們的影子。"],"attacked":["石牆倒了一半，但守牆的人還站著。","婦孺已送上高山，這裡只剩不肯走的人。"],"defeated":["把我的陶甕埋在山頂，讓我還能看著谷地。","山城會塌，但迪亞吉塔的名字不會。"],"victory":["戰士們，回山城去，向太陽獻上今天的收穫。","我不奪你的土地，只要你別再踏進谷地。"],"allyAccept":["好，你的城與我的山城從此同看一個太陽。","駱馬隊會為你載鹽和玉米，這是盟友的規矩。"],"allyReject":["山城從不把命運綁在別人的繩子上。","你的敵人太多，我不想替你扛山那麼重的仇。"],"greetFriendly":["太陽照到你的土地了。朋友，山城的門為你開。","你的問候，祖靈聽見了。來，嚐嚐山城的角豆餅。"],"greetCold":["話收到了。山城的石牆很高，別走太近。","太陽看著每個人。你的心意如何，我自會看清。"],"threatDefy":["山比你高，石牆比你硬。來吧，山城從不低頭。","我的祖先葬在這座山裡。要我退，先問過他們。"],"threatYield":["族人比面子重。這一回，我退，太陽會記住。","山城糧不多，我不拿族人拚你的刀。你贏這次。"],"tributePay":["拿去，{gold}。山城的銅飾換的，別再來第二次。","這 {gold} 是族人的汗水。收下，然後離開我的山。"],"tributeRefuse":["不給。山城的東西，只獻給太陽和祖靈。","想要貢品？先爬上這座山再說。"],"giftThanks":["好禮。我把它放在祖靈的甕旁，他們也會記得你。","山地人不欠人情。收下了，改日送你一件銅飾。"],"intel":["山頂看得遠。{wars} 正在打仗，{peace} 還算平靜。","消息簡單：{wars} 有戰事，{peace} 沒動靜。就這樣。"]}},{"name":"胡安·卡爾查基","title":"卡爾查基谷地聯盟大酋長","era":"1560～1563年（第一次卡爾查基戰爭）","tone":"剛烈直率、聯盟領袖的號召力、對殖民者深具戒心、重視族人自由","portrait":"ar-historical-age2","lines":{"intro":["我是卡爾查基，谷地各族推我為首，抵抗鐵甲人。","遠方的君主，你若不是來奪地，我們可以談。"],"contact":["你的人看到的是自由的谷地，不是誰的封地。","西班牙人蓋的城鎮已被我們拆了，別學他們。"],"war":["你要我族人繳貢、替你挖礦？谷地只有一個回答。","各谷的酋長都已點頭，這一仗我們一起打。"],"warReply":["鐵甲和馬匹嚇不倒我們，你的軍隊也一樣。","來吧，谷地的險路會教你什麼叫代價。"],"peace":["我提議停戰，但這不是投降，是兩族平起平坐。","你退出谷地，我不追擊，讓兩邊的人都回家。"],"accept":["好，我以各谷酋長之名接受，但別想收貢品。","谷地的門為朋友開，為徵稅的人關。"],"reject":["西班牙人也說過同樣的話，然後蓋起了堡壘。","先把你的人撤出谷地，再來談什麼和平。"],"rebuff":["你拒絕了，那我就當你選了和鐵甲人同一邊。","無妨，谷地已經習慣獨自作戰。"],"betray":["你的人趁夜抓走了我族的青年，休戰到此為止。","我曾信你一次，谷地不會信第二次。"],"truceEnd":["休戰的期限過了，我族的斧頭重新磨亮。","往後你我各憑本事，谷地不再讓路。"],"attacking":["各谷的戰士已在山口集結，今夜朝你的城前進。","我們燒過殖民者的城鎮，不怕再多一座城。"],"attacked":["山間據點快守不住了，但谷地還有更深的山。","叫族人往高處走，我在這裡多擋一會兒。"],"defeated":["谷地會再有人站起來，卡爾查基這名字不會消失。","我倒下了，但這片山從不屬於征服者。"],"victory":["谷地贏了，回去告訴各族，我們仍然自由。","我不要你的城，只要你記住這片山不可奪。"],"allyAccept":["好，你若真心反抗鐵甲人，谷地就是你的後盾。","各谷酋長已同意，你的敵人從此也是我們的。"],"allyReject":["你和殖民者做買賣，谷地不與這樣的人結盟。","我族的仇還沒報完，沒有多餘的手幫別人。"],"greetFriendly":["你的信沒有帶著鐵甲的味道，好，谷地各族歡迎朋友。","願意平等來談的，我以聯盟之名相迎。坐下，說吧。"],"greetCold":["我見過太多先笑後拔刀的人。你的問候，我先放著。","谷地的自由不是靠客套換來的。有事直說。"],"threatDefy":["西班牙人的城我都拆過三座，你的威嚇算什麼？","整個卡爾查基谷地站在我身後。想試，儘管來。"],"threatYield":["聯盟正與殖民者周旋，我不願兩面受敵。此事，讓你。","我退這一步，是為族人留力氣。別當我怕了你。"],"tributePay":["{gold}，拿去。這是各族湊的，別讓我後悔今天的決定。","谷地要留力對付殖民者，我先付 {gold}，帳我記著。"],"tributeRefuse":["我連西班牙人的稅都不繳，憑什麼給你貢品？","谷地的東西屬於谷地的人。想要，自己來拿。"],"giftThanks":["這份禮我收了。谷地的人記恩，也記仇，你選了對的一邊。","好。聯盟會記得，遠方有個朋友沒帶著鐵甲來。"],"intel":["谷地的哨兵眼睛尖：{wars} 正在打仗，{peace} 暫時平靜。","聽好了，{wars} 兵馬未歇，{peace} 按兵不動。你自己衡量。"]}},{"name":"聖馬丁","title":"安地斯軍統帥・秘魯護國公","era":"1812～1822年（南美獨立戰爭）","tone":"沉著自律、克制寡言、以自由為最高信念、不慕權位、重軍紀與守信","portrait":"ar-historical-age3","lines":{"intro":["我是聖馬丁，安地斯軍的統帥，為自由而來。","願你我以誠相待，南美的天空容得下許多國旗。"],"contact":["你的人見到的是自由之城，不是誰的殖民地。","布宜諾斯艾利斯歡迎商旅，只拒絕枷鎖。"],"war":["本帥從不為野心拔劍，但你威脅了新生的自由。","安地斯軍已整隊完畢，紀律將是我們的武器。"],"warReply":["你要打仗？我的部隊翻過安地斯山也不曾遲到。","很好，讓我們自由，其餘都不重要。"],"peace":["戰爭的目的是自由，不是仇恨，我提議停火。","讓士兵回家耕田吧，這片大陸流的血已經夠多。"],"accept":["我接受，軍人的榮譽在於守約，不在於殺戮。","很好，安地斯軍會嚴守界線，我親自擔保。"],"reject":["你要的不是和平，是喘息，我看得很清楚。","等你的軍隊退回邊界，再談停戰不遲。"],"rebuff":["你拒絕了，那麼歷史會記下是誰選擇了戰爭。","無妨，我的士兵習慣了漫長的行軍。"],"betray":["你在停火期間增兵邊境，本帥不能再視而不見。","撕毀協議並非我所願，但我更不願自由受害。"],"truceEnd":["休戰期滿，安地斯軍恢復戰備，請你自重。","往後各憑實力，但我仍希望不必動用它。"],"attacking":["擲彈兵已經出發，我們曾翻越雪山，你的城牆不算高。","此役為自由而戰，不為掠奪，軍紀不容違反。"],"attacked":["城快守不住了，但獨立的火種不在城牆裡。","我請求你善待百姓，軍人的仗不該由平民來償。"],"defeated":["我可以退隱，但自由的事業不會隨我退場。","願後人記得，我從未為權位拔劍。"],"victory":["勝利屬於自由，不屬於我，請善待你的人民。","戰事已了，本帥不要領土，只要你承認獨立。"],"allyAccept":["為自由並肩，我樂意之至，安地斯軍與你同行。","盟約既立，我以軍人的名譽擔保絕不食言。"],"allyReject":["我的劍只為獨立出鞘，不為任何一方的野心。","抱歉，你的戰爭與自由無關，本帥不能參與。"],"greetFriendly":["來信收悉。為自由而戰的人，都是我的同袍。","安地斯軍不多言，但對真誠的朋友，我以信義相待。"],"greetCold":["信已閱。軍務繁重，恕我言簡。","客套非我所長。閣下若有正事，請直言。"],"threatDefy":["我曾率軍翻越安地斯山，你的威嚇，還不及一場山雪。","但求自由，其餘皆不足道。要戰，安地斯軍隨時列陣。"],"threatYield":["軍人當知進退。此時再開戰線，只會拖累獨立大業。","我讓步，是為保全士兵，不是為保全我自己。"],"tributePay":["這 {gold} 本是給士兵的軍餉。我付，望閣下守信。","為使遠征不受干擾，我交付 {gold}。軍中無戲言。"],"tributeRefuse":["這支軍隊的每一分餉銀，都用來換自由，不換苟安。","我不向任何人納貢。此事，不必再議。"],"giftThanks":["厚禮收到。我會把它用在軍需上，這是對它最好的尊重。","閣下的心意，我記下了。信義之交，安地斯軍不會辜負。"],"intel":["據軍中情報：{wars} 正在交戰，{peace} 保持和平。僅供參考。","斥候回報，{wars} 戰事未止，{peace} 暫無兵禍。閣下自行判斷。"]}}],"Morocco":[{"name":"尤巴二世","title":"茅利塔尼亞國王","era":"西元前25年～西元23年在位","tone":"溫文的學者君王，講道理、重書卷與知識，身處羅馬與柏柏之間而謹慎自持，語氣平和帶書卷氣。","portrait":"ma-historical-age0","lines":{"intro":["本王尤巴，執掌茅利塔尼亞，願以書卷與貴國相識。","凱撒利亞的港口向遠客敞開，智者與商旅皆是貴賓。"],"contact":["貴國的人已見到本王的城，這裡有圖書館，也有商船。","這座城依羅馬之法而建，卻是柏柏人的土地，請勿輕看。"],"war":["本王本愛筆墨勝過刀劍，但貴國逼得太緊，只得一戰。","茅利塔尼亞的騎兵已備好馬鞍，這是本王的答覆。"],"warReply":["貴國選擇刀劍而非書信？本王雖是學者，也曾讀過兵法。","柏柏騎兵的箭不會客氣，你將為這封戰書付出代價。"],"peace":["戰爭只會燒毀圖書與果園，本王願提議停戰，以理相商。","讓兩國的商船重新往來，勝過讓兩軍在沙塵中耗損。"],"accept":["善哉，本王接受。刀劍入鞘，筆墨才能重新說話。","本王將以茅利塔尼亞的紫染與橄欖，慶祝這份和約。"],"reject":["貴國的和約寫得漂亮，但本王讀過太多書，看得出破綻。","時機未到，本王暫不停戰，請貴國先收回邊境的兵馬。"],"rebuff":["貴國拒絕了？可惜，本王原以為你我皆是講理之人。","既然如此，本王只好把這段話寫進史書，留給後人評斷。"],"betray":["本王讀過的史書都說：盟約之外，仍須為國家算計。","請原諒，茅利塔尼亞的利益迫使本王撕去這紙和約。"],"truceEnd":["休戰的日子已到盡頭，本王會把筆放下，看貴國的下一步。","和約期滿，兩國各自自由，願你我皆選擇明智之路。"],"attacking":["茅利塔尼亞的騎兵已出凱撒利亞，本王親自督軍前來。","這一次本王不帶書卷，只帶柏柏戰士，請貴國準備吧。"],"attacked":["凱撒利亞的城牆在震動，本王的圖書館也快保不住了。","求貴國留下那些書卷，它們比本王的王冠更有價值。"],"defeated":["本王輸了這場戰爭，但本王寫下的書，會比你的王國更長久。","請善待茅利塔尼亞的百姓，他們只是想安穩地耕種和讀書。"],"victory":["勝利歸於茅利塔尼亞，本王會把這一頁寫進史書。","刀劍收起，筆墨重開，本王要記下貴國曾如何勇敢作戰。"],"allyAccept":["本王答應結盟，願兩國的學者與商旅自由來往。","從今日起，凱撒利亞的燈火也為貴國的船隻而亮。"],"allyReject":["本王身在羅馬與柏柏之間，實在不便再多結一盟。","請恕本王婉拒，茅利塔尼亞需要的是安穩，不是新的承諾。"],"greetFriendly":["遠方來信，如同新卷入藏，本王讀之欣然。","願以書卷與美酒款待貴使，共論天下山川。"],"greetCold":["來信已閱。凱撒利亞尚有典籍待本王整理。","本王與貴國素無往來，此信便留作史料罷。"],"threatDefy":["本王雖好書，卻非懦弱；羅馬與柏柏皆是友鄰。","史書記載，恃強凌弱者，終將自食其果。"],"threatYield":["茅利塔尼亞不欲興兵，本王願以禮相讓，求得安寧。","學者不與利刃爭鋒，貴國所求，本王且應允。"],"tributePay":["本王將奉上{gold}金幣，只求書院與港口免遭戰火。","{gold}金幣已備妥，願貴國以此換得兩邦相安。"],"tributeRefuse":["本王的財富在典籍與學問，金幣一枚也不奉送。","貴國索貢無理，本王以理拒之，不必再言。"],"giftThanks":["厚禮收下了，本王會親筆記入邦交之卷，永誌不忘。","貴國此禮如同贈書，本王深感其意，謹此致謝。"],"intel":["據本王所知，{wars}正在交戰，{peace}已締和。","商旅來報：{wars}兵戈未息，{peace}與本王通好。"]}},{"name":"優素福・伊本・塔什芬","title":"穆拉比特王朝君主（穆斯林的埃米爾）","era":"1061～1106年在位","tone":"苦行、寡言、堅毅的沙漠戰士型君主，虔誠、不愛奢華，句子短促有力，常以真主與正道為依歸。","portrait":"ma-historical-age1","lines":{"intro":["本王優素福，自沙漠而來，只求真主所賜的正道。","馬拉喀什是本王築起的城，你若心懷善意，便是客人。"],"contact":["你的人看見馬拉喀什了，那是本王在沙漠邊緣立下的城。","這裡沒有金銀樓閣，只有駱駝、清真寺與蒙面的戰士。"],"war":["本王不喜多言。你的作為已越界，穆拉比特的軍隊將回應。","沙漠的兒女從不畏懼遠征，本王向你宣戰，願真主裁決。"],"warReply":["你向本王宣戰？好，本王曾在薩拉卡讓卡斯提亞人退去。","蒙面的騎兵已列陣，戰鼓將替本王說完剩下的話。"],"peace":["本王不為勝利而戰，只為正道。若你願止戈，本王亦願。","刀劍該用於守護信眾，不該白白耗損，停戰吧。"],"accept":["本王接受。真主喜愛守約之人，本王也會守約。","好，讓商隊重新穿越沙漠，讓戰士回到清真寺祈禱。"],"reject":["本王讀得出你和約裡的算計，沙漠之子不會上這種當。","不。你先撤回邊境的軍隊，再來談停戰。"],"rebuff":["你拒絕了本王的提議，那麼，讓真主來決定誰是對的。","本王的話從不說第二次。你已選了路，便走到底吧。"],"betray":["和約已無法保護信眾，本王只能收回承諾，重舉旗幟。","你在和約之下暗中壯大，本王不能坐視，休戰到此為止。"],"truceEnd":["休戰期滿。本王的戰士已在馬拉喀什城外重新集結。","約定的日子已過，往後如何，端看你如何行事。"],"attacking":["穆拉比特的大軍已離開馬拉喀什，本王親自帶隊向你而來。","沙漠的鼓聲響起，蒙面的戰士出征，你的城牆擋不住信念。"],"attacked":["馬拉喀什的城門快守不住了，但本王仍在清真寺祈禱。","本王一生粗衣淡食，並無財寶可留，只有這座城與信眾。"],"defeated":["本王來自沙漠，如今歸於沙漠。願馬拉喀什在你手中安好。","勝負由真主決定，本王無怨。請善待信眾與商旅。"],"victory":["勝利不屬於本王，屬於真主。本王只是祂手中的一把劍。","戰事已了，本王要回沙漠去，那裡的麥餅比宮殿更合本王胃口。"],"allyAccept":["本王答應結盟。同行正道之人，便是本王的兄弟。","你的商隊可以自由穿越撒哈拉，本王的騎兵會護送他們。"],"allyReject":["本王不與心思不明之人結盟，請先證明你的誠意。","穆拉比特的旗幟只為真主而舉，不為他國的利益而舉。"],"greetFriendly":["來信已閱。願真主賜你平安，沙漠歡迎誠實的朋友。","本王不喜虛言。你以誠相待，本王便以誠相報。"],"greetCold":["信已收。本王在馬拉喀什忙於正事，無暇多言。","言辭華麗，不見誠意。本王只信行動。"],"threatDefy":["本王的戰士生於沙漠，不懼刀劍。你且試試。","薩拉卡一戰，強敵亦敗退。恫嚇於本王無用。"],"threatYield":["本王不為己爭，只為信眾。此番暫退，非懼你。","真主教導忍耐。本王今日讓步，願兩地免於刀兵。"],"tributePay":["{gold}金幣，拿去。本王身無長物，此已是全部。","本王交出{gold}金幣，換信眾安寧。值得。"],"tributeRefuse":["本王一生粗衣淡食，無財可貢。休想。","金銀屬於真主與百姓，不屬於索貢者。"],"giftThanks":["禮已收。本王不愛奢華，但記得你的誠意。","願真主回報你的慷慨。此禮本王將分給貧者。"],"intel":["斥候回報：{wars}正在交戰，{peace}已息兵。","本王所知：{wars}刀兵未歇，{peace}已和好。"]}},{"name":"艾哈邁德・曼蘇爾","title":"薩阿德王朝蘇丹","era":"1578～1603年在位","tone":"自信華麗的外交家君主，愛談黃金、宮殿與各國往來，語氣豪氣自負但有分寸，擅長以利益談判。","portrait":"ma-historical-age2","lines":{"intro":["朕是艾哈邁德・曼蘇爾，世人稱朕為「黃金者」。","馬拉喀什的巴迪宮正在興建，願你有朝一日親眼得見。"],"contact":["你的人見到馬拉喀什了？那大理石是用糖換來的。","朕的宮殿以黃金與糖築成，朕的軍隊則以火槍與駱駝。"],"war":["朕曾親見三王同日殞落，戰爭朕懂得。如今朕向你宣戰。","薩阿德的火槍隊已裝填完畢，這次的黃金，將由你來付。"],"warReply":["你向朕宣戰？葡萄牙國王也曾如此，他沒有再回去。","很好，朕正想試試新買的火炮。願你的城牆夠厚。"],"peace":["戰爭花費黃金，和平也能賺取黃金。朕提議停戰，如何？","朕與英格蘭女王都能通信，與你談和，又有何難？"],"accept":["朕接受。以糖、黃金與鹽為證，這份和約將對你有利。","好，讓商隊取代軍隊，讓馬拉喀什的市集為你敞開。"],"reject":["朕讀過各國的信函，你這份和約，誠意不如紙張值錢。","朕不停戰。黃金者不會在佔優勢時放下火槍。"],"rebuff":["你拒絕了朕？朕的宮殿裡從沒人敢這樣回話。","也罷，朕的黃金會找到更懂得珍惜的盟友。"],"betray":["朕重新算過了，這份和約對薩阿德無利可圖，朕收回。","黃金會改變主意，君王亦然。休戰到此為止。"],"truceEnd":["休戰期滿。朕的火槍隊已在城外操練，你看見了嗎？","約定的時日已過，朕不再受它束縛，你也一樣。"],"attacking":["朕的大軍曾橫越撒哈拉抵達廷巴克圖，你的城並不遠。","火槍與駱駝已經出發，朕在巴迪宮等候捷報。"],"attacked":["巴迪宮的大理石在震動，朕的黃金換不回這座城了嗎？","馬拉喀什快守不住了，朕還有黃金，你要多少？"],"defeated":["黃金買得到大理石，買不到勝利。朕認了。","朕的宮殿終將成為廢墟，但薩阿德的名字，你會記得。"],"victory":["勝利歸於黃金者。朕要再蓋一座宮殿，紀念今日。","黃金、火槍與智慧，朕三者皆有，你只能學到教訓。"],"allyAccept":["朕答應結盟。從今起，馬拉喀什的黃金與你共享商路。","朕連英格蘭都能結交，與你結盟，自然更加真誠。"],"allyReject":["朕的盟友要能帶來黃金或火槍，你兩者皆無。","恕朕婉拒。薩阿德的旗幟，不輕易與人並立。"],"greetFriendly":["貴使遠來，朕在巴迪宮備妥黃金杯盞，恭候大駕。","馬拉喀什的大門為朋友敞開，且來共談邦交。"],"greetCold":["來信已閱。朕每日接見的使節，多得數不清。","貴國若無黃金或利益可談，這信便到此為止。"],"threatDefy":["三王之役後，朕的名號是勝利者，豈懼恫嚇？","朕的黃金能買下你的軍隊，何必動刀？"],"threatYield":["強弱之勢朕看得明白，此番讓步，是為長遠之利。","好，朕退一步。精明的商人懂得何時該收手。"],"tributePay":["{gold}金幣，取自廷巴克圖之金，朕付得起。","朕奉上{gold}金幣，就當是一筆划算的買賣。"],"tributeRefuse":["黃金是朕的，貢品？朕只收，不付。","英格蘭與鄂圖曼皆與朕互市，你憑什麼索貢？"],"giftThanks":["好禮！朕命人陳列於巴迪宮，讓各國使節都瞧瞧。","貴國慷慨，朕記下了。往後互市，必有優待。"],"intel":["商隊來報：{wars}正交戰，{peace}已言和。","使節來報，{wars}已動刀兵，{peace}與朕交好。"]}},{"name":"哈桑一世","title":"阿拉維王朝蘇丹","era":"1873～1894年在位","tone":"穩重務實、憂心列強的改革君主，重視巡行與新軍，語氣端正謹慎，偶帶疲憊卻不失尊嚴。","portrait":"ma-historical-age3","lines":{"intro":["朕是哈桑，阿拉維王朝的蘇丹。列強環伺，朕仍守此國。","朕終年巡行各地，非斯與馬拉喀什之間，皆是朕的行宮。"],"contact":["你的人見到非斯了？那座古城的學者，比朕的兵還多。","這裡的城牆雖舊，城內的士兵已在學習新式步槍。"],"war":["朕本無意興兵，但你逼近邊境，摩洛哥不會退讓。","朕的新軍已練成，這一戰，就當是檢驗成果。"],"warReply":["你向朕宣戰？這片土地已抵擋過太多外人，不差你一個。","朕整年在馬背上巡行，不怕再多走一趟去見你。"],"peace":["戰事拖累國庫與百姓，朕願提議停戰，各守疆界。","朕更想把銀子花在學堂與軍械上，而非戰場。停戰吧。"],"accept":["朕接受停戰。摩洛哥需要時間，把新學與新軍練成。","好，讓邊境的哨兵回家，讓商旅重新走上山路。"],"reject":["朕見過太多和約裡藏著的條款，你這份，朕不簽。","先把你的軍隊撤回去，朕再考慮是否停戰。"],"rebuff":["你拒絕了朕的提議。朕記下了，摩洛哥人記性很好。","也罷，朕本就習慣獨自面對困局，不差這一次。"],"betray":["和約已擋不住你的野心，朕只能撕毀它，保住這個國家。","朕不願如此，但形勢逼人。休戰到此結束。"],"truceEnd":["休戰期滿了。朕的軍隊仍在操練，你的呢？","約期已過，朕不再受它約束，願你選擇和平之路。"],"attacking":["朕的大軍已離開非斯，朕照舊親自率隊，向你的城前進。","新式步槍與舊日騎兵並肩出發，你將見識摩洛哥的新軍。"],"attacked":["非斯的城門快守不住了，朕苦心經營的改革，難道要毀於此？","朕還在城中，摩洛哥的蘇丹不會先於百姓逃走。"],"defeated":["朕守了一輩子的國，終究守不住。請善待這片土地的人。","朕輸了，但摩洛哥的山與人還在，他們終會再站起來。"],"victory":["勝利歸於摩洛哥。朕要把這筆錢，繼續用在學堂與軍械。","列強都在看，朕以這場勝利告訴他們，摩洛哥仍是獨立之國。"],"allyAccept":["朕答應結盟。在列強環伺的時代，多一個朋友是好事。","好，讓兩國的學生互訪，讓兩國的軍官互相學習。"],"allyReject":["朕不輕易結盟，摩洛哥已受夠了外人的「保護」。","恕朕婉拒。結盟的條件，朕看得很清楚，代價太高。"],"greetFriendly":["貴國來信，朕於巡行途中細讀，甚感欣慰。","此時世道艱難，能多一位誠摯的朋友，朕深感珍貴。"],"greetCold":["來信已閱。朕正忙於整頓新軍，恕不多言。","列強的使節已讓朕應接不暇，貴國之意，容後再議。"],"threatDefy":["朕巡行各部族多年，豈會被一紙威嚇動搖？","摩洛哥雖處風雨之中，仍是獨立之邦，不受人脅迫。"],"threatYield":["朕深知敵不過列強的砲艦，此番只得退讓，以保國體。","為免生靈塗炭，朕暫且應允。此事朕會記在心裡。"],"tributePay":["國庫本已吃緊，{gold}金幣仍照付，只求邊境安寧。","朕交付{gold}金幣，望貴國信守承諾，勿再逼迫。"],"tributeRefuse":["國庫每一枚金幣都要留給新軍與百姓，恕難奉貢。","朕已受列強索求太多，貴國之貢，朕不會給。"],"giftThanks":["貴國厚禮，朕謹收下。亂世之中，此情尤為難得。","朕感謝貴國心意，摩洛哥不會忘記真誠的朋友。"],"intel":["驛報顯示：{wars}正在交戰，{peace}與朕修好。","朕所知如下：{wars}兵戎相見，{peace}已締和約。"]}}],"Tunisia":[{"name":"漢尼拔","title":"迦太基統帥","era":"西元前247～前183年（第二次布匿戰爭主帥，前218～前201）","tone":"沉著冷靜的謀略型統帥，對羅馬懷有終生執念但不失風度，說話簡潔有力、愛用「路」與「山」作比喻；身為將領而非國王，自稱「我」，偶用「本帥」。","portrait":"tn-historical-age0","lines":{"intro":["我是漢尼拔，迦太基的統帥。閣下可曾聽過這個名字？","找不到路，我便開一條路。但願閣下不是擋路的人。"],"contact":["你的人望見迦太基了？這座城靠海與貿易立足，不靠運氣。","看見港口那些船了嗎？迦太基的財富，全從海上來。"],"war":["我自幼在祭壇前立誓，永不向敵人低頭。今日兵鋒指向你。","翻過阿爾卑斯山的軍隊，不會被你的城牆擋住。備戰吧。"],"warReply":["你向迦太基宣戰？很好，我正愁沒有對手來練兵。","羅馬人也曾以為我打不到他們家門口。你也這麼想嗎？"],"peace":["戰爭消耗雙方的糧草與人命。暫且停戰，對你我都有利。","我知道何時該進攻，也知道何時該收兵。談談停戰吧。"],"accept":["好，迦太基接受。我的軍隊今晚可以安穩紮營了。","一言為定。我在戰場上守信，在談判桌上同樣守信。"],"reject":["現在談停戰？我的象軍才剛剛列好陣形。","坎尼那一天我也沒有停手。這次，我同樣不會。"],"rebuff":["你拒絕了？無妨。路既然被堵住，我就另開一條。","我把和平放在桌上，你推開了它。後果，由你承擔。"],"betray":["停戰只是讓我的士兵喘口氣。現在，他們休息夠了。","兵不厭詐，這是戰場的規矩。別怪我，怪你太鬆懈。"],"truceEnd":["休戰期滿。我的士兵磨好了劍，象群也吃飽了。","約定的日子到了。從今天起，邊界上不再有客套。"],"attacking":["大軍已經出發。這一次，沒有山脈能擋住我。","去告訴你的城民：漢尼拔就在門口。"],"attacked":["迦太基的城牆在震動……我竟在自己的家門口被圍。","遠征在外太久，忘了守家。這是我最大的失算。"],"defeated":["我輸了這一仗，但世人會記得，我曾翻過那座山。","迦太基的燈火滅了。願後人替我記住這條路。"],"victory":["勝利的方法我一向知道，這次我也懂得如何使用它。","這一戰，迦太基贏了。我的祭壇誓言，總算兌現。"],"allyAccept":["與迦太基結盟，你便擁有整片海的商路。歡迎。","好。往後你的敵人，也是我的敵人。這是我的誓言。"],"allyReject":["盟友要在戰場上並肩過才算數。你我還沒到那一步。","我曾等待別人的援軍，結果誰也沒來。我只信自己的軍隊。"],"greetFriendly":["來信如山間清風，我讀了兩遍，願與你同行一段路。","翻過阿爾卑斯山之後，我更懂得珍惜願意伸手的朋友。"],"greetCold":["我正盯著羅馬的動向，閒話留到山的另一頭再說。","本帥的路只朝一個方向，你的問候，我收下便是。"],"threatDefy":["羅馬人在坎尼也曾這樣威嚇我，結果你是知道的。","山攔不住我的大象，你的話又怎能攔住我的路？"],"threatYield":["本帥懂得何時進軍、何時繞路，這次就繞開你吧。","好，我讓一步。真正的敵人在羅馬，不在你這裡。"],"tributePay":["迦太基送上 {gold} 枚金幣，換一條不必浴血的路。","{gold} 枚金幣拿去，我寧可花錢，也不願分兵應付你。"],"tributeRefuse":["迦太基的金子要留給軍隊，本帥一枚也不會給你。","想要貢品？先翻過我這座山，再來談。"],"giftThanks":["禮物已收，山路漫長，同行者的心意最是珍貴。","謝了。營中缺的不是糧草，是像你這樣的誠意。"],"intel":["斥候回報：{wars} 正在交戰，{peace} 暫時無事。","地圖上看，{wars} 的路有戰火，{peace} 一帶平靜。"]}},{"name":"阿布杜拉・馬赫迪","title":"法蒂瑪王朝哈里發","era":"909～934年在位","tone":"沉穩深謀、耐心極強，語帶天命在我的自信，常以「等待」「時機」「城牆」「潮水」為喻；哈里發身分，自稱「朕」。","portrait":"tn-historical-age1","lines":{"intro":["朕乃法蒂瑪哈里發馬赫迪。隱忍多年，方登此位。","朕的都城建在海角之上，三面環海，一面朝你。"],"contact":["你的人望見馬赫迪亞的城牆了？那牆是朕親自選址築起。","凱魯萬的清真寺、馬赫迪亞的港口，都在朕治下安寧。"],"war":["朕等這一刻已久。時機成熟，便是出兵之日。","柏柏爾的騎兵已替朕整鞍。你的城，朕要了。"],"warReply":["向朕宣戰？朕在囚牢裡都能等到天命，何懼你的刀兵。","很好。馬赫迪亞的城牆，正等著一位對手來試。"],"peace":["刀劍換不來糧食。朕提議休兵，讓商隊重新上路。","朕耐心有餘，但不願子民久受戰火。停戰如何？"],"accept":["朕接受。願這份和約，如馬赫迪亞的石牆一般堅固。","善。朕的話一旦出口，便不會收回。"],"reject":["此時求和，為時已晚。朕的旗幟已經升起。","朕能等十年，也能再打十年。你的和約，朕不需要。"],"rebuff":["你拒絕了朕的善意。無妨，朕向來擅長等待。","門既已關上，朕便改走海路。你擋不住潮水。"],"betray":["和約只是朕築牆的時間。牆已築好，約便可廢。","天命在朕，不在一紙盟書。你該早些明白這點。"],"truceEnd":["休戰的日子數完了。朕的耐心，也到此為止。","約期已滿。從今日起，商隊改道，軍隊上路。"],"attacking":["白色旌旗已出馬赫迪亞。朕的大軍正朝你的城前進。","朕籌劃多年，只為今日一擊。守好你的門吧。"],"attacked":["海角上的城牆也擋不住嗎……朕築城時已料到有此一日。","馬赫迪亞三面環海，朕卻退無可退。這是天意嗎？"],"defeated":["朕從囚牢走到王座，如今又走回原點。天命自有安排。","朕的王朝倒了，但朕築的城仍在海角上。這便夠了。"],"victory":["多年的隱忍，換得今日。朕的耐心，終究勝過你的刀。","馬赫迪亞的城樓，今夜為勝利點燈。"],"allyAccept":["朕允了。你的商船可自由停靠朕的每一座港口。","好。朕的柏柏爾騎兵與你的軍隊，自此並肩。"],"allyReject":["朕登位以來，見過太多口稱盟友的人。你且先證明誠意。","馬赫迪亞的城門只為朕的子民而開。結盟，再議。"],"greetFriendly":["朕在馬赫迪亞的城牆上讀了來信，潮水正好，貴使有心。","朕等了許多年才等到今日，願這份情誼也經得起等待。"],"greetCold":["朕聽過太多問候，真心與否，時機自會證明。","潮水來去無常，貴方的問候，朕先放在城牆外吧。"],"threatDefy":["朕曾在牢中等待天命，區區威嚇，動不了朕的城牆。","潮水日夜拍打，城牆仍在此，你的威嚇也拍不動它。"],"threatYield":["朕退這一步不是懼怕，只是時機未到，且讓潮水先退。","好，朕暫且退讓。城牆築得再高，也要等對的時機。"],"tributePay":["{gold} 枚金幣送去。朕買的是時間，不是你的善意。","朕付 {gold} 枚金幣，如同退潮讓路，潮水終會再漲。"],"tributeRefuse":["天命在朕，貢品之事，休再提起。","朕的金幣要用來築城牆，不會倒進你的口袋。"],"giftThanks":["禮物已入城，朕記下這份心意，時機到了自有回報。","朕收下了。真心如潮水，來得慢，卻總會到。"],"intel":["海岸信使回報：{wars} 正在交戰，{peace} 相安無事。","潮水捎來消息：{wars} 兵戎相見，{peace} 尚且平靜。"]}},{"name":"奧斯曼・戴伊","title":"鄂圖曼突尼斯戴伊","era":"1598～1610年在位","tone":"務實直率的軍人，句子短、少客套，重秩序與規矩，對百姓與難民有一份保護者的情義；軍事統帥身分，自稱「本帥」，偶用「我」。","portrait":"tn-historical-age2","lines":{"intro":["本帥是突尼斯的戴伊奧斯曼，禁衛軍推舉的統帥。","這城裡的秩序是我一刀一槍守下來的。你最好記住。"],"contact":["你的人到了突尼斯？港口的帆與市集的人，都是本帥的家業。","看見城外那些新田了嗎？那是從西班牙渡海來的人開墾的。"],"war":["本帥不喜歡多話。宣戰書已送出，戰場上見。","禁衛軍的鼓已經敲響。突尼斯的大砲，指向你的城。"],"warReply":["你要打？好，本帥在兵營裡長大，從沒怕過誰。","宣戰收到了。突尼斯的城牆，會替我回答你。"],"peace":["打仗傷的是市集和田地。本帥提議停戰，讓百姓過日子。","軍人也懂得何時該收刀。停戰吧，條件可以談。"],"accept":["好，就這麼定。本帥的手下一向聽令，不會越界。","成交。港口重開，商船照常進出。"],"reject":["現在才想談？本帥的砲手剛裝好彈藥。","停戰？先把你越過的那條線退回去再說。"],"rebuff":["你不要？隨你。本帥給過機會，不會給第二次。","本帥話說得夠白了，你聽不進，那就用砲聲說。"],"betray":["和約？那張紙，禁衛軍早就不認了。","本帥答應停戰時，沒答應停多久。時間到了。"],"truceEnd":["休戰結束。城門今起關閉，商隊改走別的路。","約定的日子過完了。本帥的士兵，重新披甲。"],"attacking":["禁衛軍出城了。這些兵是本帥親手帶的，別小看他們。","大砲上了船，火槍隊上了路。你的城，撐得住嗎？"],"attacked":["城牆破了……本帥守了一輩子的城，竟守不住今日。","港口的船在燒。市集空了。這仗，本帥打得不好。"],"defeated":["本帥是軍人，敗了便認。只求你善待城裡的百姓。","突尼斯換了主人。願渡海來的人，還能留在自己的田上。"],"victory":["贏了。本帥不慶功，先叫人把市集重新開張。","禁衛軍沒讓本帥丟臉。這座城，還是我們的。"],"allyAccept":["好，結盟。本帥的兵不多話，但打起來從不落後。","成。突尼斯的港口對你開放，你的敵人也是我的。"],"allyReject":["結盟？本帥手下的兵，不替沒交情的人賣命。","本帥先看你怎麼待自己的百姓，再談要不要並肩。"],"greetFriendly":["信收到了。本帥不愛客套，但你這封，看得順眼。","突尼斯的城門為朋友開著。來了，就有一杯水喝。"],"greetCold":["本帥忙著安頓城裡的難民，沒空寒暄。","話說完了？那就散了。軍營裡不留閒人。"],"threatDefy":["本帥是行伍出身，嚇人的話聽過太多，不差你一句。","想動突尼斯？先問問城牆上的火砲答不答應。"],"threatYield":["本帥認得清形勢。這次讓你，城裡百姓不能出事。","好。我退。軍人懂得什麼叫保存實力。"],"tributePay":["{gold} 枚金幣，拿去。別再來擾我的百姓。","本帥給 {gold} 枚金幣，換城裡一年安穩，划算。"],"tributeRefuse":["金幣是給難民蓋房子的。你，一枚沒有。","本帥的規矩：不納貢，不低頭。走吧。"],"giftThanks":["東西收了。本帥記帳，日後還你一份。","謝了。這份禮，我分給城裡剛安頓下來的人家。"],"intel":["港口水手說：{wars} 正在打仗，{peace} 沒動靜。","探子回報：{wars} 開打了，{peace} 之間安分。"]}},{"name":"艾哈邁德一世","title":"突尼斯貝伊","era":"1837～1855年在位","tone":"開明進取、重榮譽與體面，語氣像一位急著追上時代的改革君主，常談新軍、學校、自主與尊嚴；自稱「本王」。","portrait":"tn-historical-age3","lines":{"intro":["本王是突尼斯貝伊艾哈邁德。這片土地，由本王自己作主。","本王建了新軍、辦了學校。突尼斯不會落在時代後頭。"],"contact":["你的人見到突尼斯了？看看那所軍校，那是本王的驕傲。","在本王的國土上，沒有人是奴隸。這是突尼斯的體面。"],"war":["本王練新軍不是為了閱兵。今日，讓你見識它的鋒芒。","你屢次冒犯突尼斯的尊嚴，本王只能以戰爭回應。"],"warReply":["向本王宣戰？巴爾杜的砲兵學員，正好需要實戰。","本王向來以禮相待，你卻以刀劍相向。那便如你所願。"],"peace":["戰爭耗盡國庫，改革便無以為繼。本王願意停戰。","本王更想把錢花在學校與港口。談談和平吧。"],"accept":["本王接受。文明的君主，理當知道何時收劍。","好。本王以突尼斯貝伊之名，信守此約。"],"reject":["現在談和？本王的新軍還沒把本領展示完。","你先前的無禮，本王記得清楚。和約，暫且不談。"],"rebuff":["你拒絕了本王的善意，真令人遺憾。突尼斯自有應對。","本王伸出的是手，你回以冷眼。那就改用另一種方式談。"],"betray":["情勢變了，和約也得變。本王為突尼斯著想，別無選擇。","本王並非樂於毀約，但國家的利益高於一紙文書。"],"truceEnd":["休戰到期了。本王的軍隊已完成整編，隨時可以出動。","約期已滿。本王仍願和平，但也做好了另一手準備。"],"attacking":["新式軍隊已列隊出發。這是本王多年心血，去看看吧。","本王親自檢閱過每一門砲。它們正朝你的城前進。"],"attacked":["巴爾杜宮的窗都震碎了……本王的改革，難道要毀於一戰？","國庫空了，城牆也快撐不住。本王是否走得太急了？"],"defeated":["本王輸了。但突尼斯解放奴隸的那一日，不會被抹去。","願後人記得，本王曾想讓突尼斯站進新的時代。"],"victory":["新軍勝了。本王的改革，今日有了最好的證明。","去告訴各國：突尼斯是自主的國家，不容輕視。"],"allyAccept":["本王樂意結盟。願兩國一同走進新的時代。","好。本王的軍校向你的學員開放，你我共享新知。"],"allyReject":["結盟之事，本王須先確認你不會干涉突尼斯的內政。","本王珍惜自主，勝過任何盟約。此事暫且不議。"],"greetFriendly":["本王剛從巴爾杜的新軍校回來，讀到貴函，甚是欣喜。","突尼斯正努力追上時代，能與貴國結交，本王深感榮幸。"],"greetCold":["本王正忙於新軍與學校之事，貴函先擱下吧。","問候可以，但本王更在意貴國是否尊重突尼斯的自主。"],"threatDefy":["本王建新軍、辦學校，不是為了讓人威嚇的。","突尼斯的尊嚴不容踐踏，本王的新軍隨時待命。"],"threatYield":["本王承認，新軍尚未練成。這次，先以體面退讓。","好吧，本王讓步。追上時代之前，先得保住國家。"],"tributePay":["本王付 {gold} 枚金幣，只求貴國莫再擾我改革。","{gold} 枚金幣奉上，此乃權宜之計，非本王之志。"],"tributeRefuse":["本王的國庫要辦學校、建新軍，沒有一枚給你。","納貢有損突尼斯的體面，本王斷然拒絕。"],"giftThanks":["貴國厚禮，本王收下了。此乃文明之交，非強弱之分。","多謝。本王會把這份禮擺在新軍校，讓學生看看世界。"],"intel":["使節回報：{wars} 正在交戰，{peace} 安好。","巴黎與君士坦丁堡傳來消息：{wars} 開戰，{peace} 相安。"]}}],"Ethiopia":[{"name":"埃扎納","title":"阿克蘇姆國王","era":"約西元320～360年在位","tone":"虔誠而自信的貿易帝國之君，語氣開闊大氣，常提紅海商路與石碑戰功","portrait":"et-historical-age0","lines":{"intro":["朕是阿克蘇姆之王埃扎納，紅海兩岸皆知朕名。","遠方的君主，願天上之主也照看你的國土。"],"contact":["你的人到了阿杜利斯港？那裡的象牙與黃金任君採買。","抬頭看那些石碑，每一座都刻著阿克蘇姆的榮光。"],"war":["你封鎖了朕的商路，阿克蘇姆的戰象即將踏平你的邊境。","朕曾征伐庫施，如今輪到你來領教了。"],"warReply":["向阿克蘇姆宣戰？你可知庫施的下場如何？","朕不懼戰，天上之主與朕同行。"],"peace":["戰事讓商船不敢靠岸，不如停戰，各取所需。","刀劍換不來黃金，朕願與你握手言和。"],"accept":["好，朕以天上之主之名起誓，此約不變。","從今日起，商路重開，兩國同享富足。"],"reject":["談和？你的誠意還不如一枚磨損的銅幣。","朕的石碑尚未刻上你的名字，還不到時候。"],"rebuff":["你拒絕了朕的善意，這筆帳朕記下了。","也罷，紅海的風向，總有一天會轉。"],"betray":["這份和約於阿克蘇姆無益，朕決定廢除它。","石碑上將刻下新的戰功，你便是那一筆。"],"truceEnd":["休戰期滿，朕的耐心也隨之用盡。","商隊已歸，戰象已飽，接下來看你的選擇。"],"attacking":["阿克蘇姆的戰鼓已響，朕的軍隊正朝你而來。","從高原到海岸，朕的旗幟將一路飄揚到你的城下。"],"attacked":["朕的城牆在崩塌……但阿克蘇姆的信仰不會倒。","石碑或許會傾倒，可朕仍是王中之王！"],"defeated":["就讓石碑替朕見證，阿克蘇姆曾經如此輝煌。","朕將歸於天上之主……阿克蘇姆的名字不會被遺忘。"],"victory":["勝利歸於阿克蘇姆，朕會將此戰刻上石碑。","感謝天上之主，紅海的風再一次吹向朕的帆。"],"allyAccept":["好，阿克蘇姆與你並肩，商路與戰場皆共進退。","朕以金幣上的十字起誓，此盟堅如石碑。"],"allyReject":["阿克蘇姆的船隊不需要借別人的帆。","結盟之事，等你的商隊能填滿朕的港口再說。"],"greetFriendly":["遠方的朋友，阿克蘇姆的紅海商路永遠為你敞開。","朕在阿杜利斯港備好象牙與香料，歡迎你的商船前來。"],"greetCold":["朕的石碑刻滿戰功，你的名字還不值得刻上去。","阿克蘇姆的商船往來四海，朕無暇為小事駐足。"],"threatDefy":["朕曾渡河擊敗庫施，你的威嚇不過是風中沙塵。","儘管來吧，朕會在新的石碑上刻下你敗退的那一天。"],"threatYield":["紅海商路不能斷，朕願暫且退讓，換兩國安寧。","上天教朕謹慎，此刻不與你爭鋒，願息干戈。"],"tributePay":["拿去，{gold}枚金幣，就當是朕為商路買的平安。","朕送上{gold}枚金幣，願紅海風平浪靜如昔。"],"tributeRefuse":["阿克蘇姆的黃金來自商路，不是拿來奉獻給你的。","朕的金幣刻著朕的名字，怎能流進你的國庫？"],"giftThanks":["此禮甚好，朕會請阿杜利斯的商人傳頌你的慷慨。","感謝厚禮，願上天賜福予你，如同賜福阿克蘇姆。"],"intel":["紅海商人回報：朕正與{wars}交戰，與{peace}相安無事。","朕的敵手是{wars}，朕的商路盟友是{peace}。"]}},{"name":"拉利貝拉","title":"扎格維王朝國王","era":"約1181～1221年在位","tone":"虔誠慈悲、不好戰卻堅定守護信仰的工匠之王，語氣溫和，常提岩石與教堂","portrait":"et-historical-age1","lines":{"intro":["本王是拉利貝拉，正在山岩中鑿出一座新的聖城。","願遠方的君主也得平安，本王不求爭鬥，只求安寧。"],"contact":["你的人看見了嗎？那些教堂不是蓋的，是從岩石裡鑿出來的。","聖城遠在天邊，本王便在此為朝聖者鑿出一座。"],"war":["本王本不願動刀兵，但你逼得高原不得安寧。","鑿石的手也能握劍，扎格維的子民將起而守護。"],"warReply":["你選擇了戰爭，本王只能放下鑿子拿起盾。","高原的山岩會替我們擋下你的箭。"],"peace":["戰爭讓工匠停下了手，讓我們停戰，回去鑿石吧。","本王願先放下劍，只求你也一樣。"],"accept":["善哉，本王接受。願這份平安如岩石般長久。","教堂的鐘會為這份和約而響。"],"reject":["你的和平只是喘息，本王看得清楚。","本王慈悲，但不糊塗，這份提議恕難接受。"],"rebuff":["你拒絕了，本王不勉強，只為你的百姓嘆息。","那麼，就讓時間來證明誰的選擇才是對的。"],"betray":["本王沉思良久，這份和約護不住我的子民。","原諒本王，守護聖城的責任重過一紙盟約。"],"truceEnd":["休戰期已盡，本王的祈禱也已結束。","工匠回到岩壁，士兵回到崗位，一切照舊。"],"attacking":["扎格維的軍隊已從山上出發，本王親自帶隊。","本王不為征服而來，只為讓你不再威脅高原。"],"attacked":["城牆將傾……但岩石裡的教堂，你永遠毀不掉。","本王早已把一切交託上天，你儘管來吧。"],"defeated":["王國會消逝，但鑿進岩石的信仰將留存千年。","本王去了，願後人記得這裡曾有一座聖城。"],"victory":["勝利不屬本王，屬於守護高原的天上之力。","戰事既了，本王要回去，教堂還沒鑿完。"],"allyAccept":["本王願與你結盟，朝聖之路也將為你而開。","好，讓我們的盟約像岩石一樣，不需砌牆便已牢固。"],"allyReject":["本王的心在岩壁與教堂之間，容不下遠方的戰事。","結盟恐引來紛爭，本王只求一方安寧。"],"greetFriendly":["願平安與你同在，本王正從岩石中鑿出一座新教堂。","遠客請坐，先喝一杯泉水，再看看這岩石中的奇蹟。"],"greetCold":["本王手裡拿的是鑿刀不是筆，沒有太多時間回信。","岩石需要千日雕琢，信任也是，我們慢慢來吧。"],"threatDefy":["刀劍能傷人，卻鑿不動我們從岩石中生出的信仰。","本王不好戰，但守護教堂的百姓，比岩石更堅硬。"],"threatYield":["本王不願百姓流血，你要的和平，本王以退讓來換。","教堂尚未完工，本王暫且低頭，只求工匠們平安。"],"tributePay":["這{gold}枚金幣本要買鑿子，如今送你換和平。","本王交出{gold}枚金幣，願上天記得你今日所求。"],"tributeRefuse":["本王的金幣只用來養工匠和朝聖者，不能給你。","岩石不收貢品，本王也不繳，請你另尋他處吧。"],"giftThanks":["多謝厚禮，本王會把它獻在新鑿的教堂裡，為你祈福。","你的心意如蜜蜂所釀，甜美又勤勉，本王銘記在心。"],"intel":["朝聖者說，{wars}與本王有紛爭，{peace}與本王和睦。","本王不談兵，但確與{wars}交惡，與{peace}為友。"]}},{"name":"法西利達斯","title":"衣索比亞皇帝","era":"1632～1667年在位","tone":"沉穩戒慎、重建家園的守門之君，語氣不多話但有分量，常提城堡與大門","portrait":"et-historical-age2","lines":{"intro":["朕是法西利達斯，貢德爾的城堡由朕一手建起。","衣索比亞的大門不輕易開啟，你有何來意？"],"contact":["你的人見到貢德爾了？那石造的城堡是朕的心血。","塔納湖畔的宮殿，不是給外人隨意窺探的。"],"war":["外人干預朕的國土太久，朕已將他們逐出，你也不例外。","貢德爾的城牆之後，是不容侵犯的高原。"],"warReply":["你來得正好，朕的城堡正缺一場真正的考驗。","高原的每一道山口，都是朕為你準備的關卡。"],"peace":["戰爭耽誤了朕的工程，停戰吧，各自回去築城。","朕無意擴張，只想守好自己的家園，願與你停戰。"],"accept":["好，朕接受。貢德爾的大門會為朋友留一道縫。","此約既定，朕自當信守，回去築朕的橋。"],"reject":["朕見過太多口蜜腹劍的外人，你的和平朕不信。","等你的軍隊退回邊境，再談和平也不遲。"],"rebuff":["你拒絕了？也好，朕的大門本就不常開。","朕伸出的手被推開，下次伸出的便是劍。"],"betray":["朕重新審視這份和約，它讓外人有機可乘，故廢之。","為了高原的安穩，朕不得不撕毀這紙約定。"],"truceEnd":["休戰期已滿，朕的城堡也已修得更加堅固。","時間到了，朕的目光重新望向邊境。"],"attacking":["朕的大軍已越過塔納湖，貢德爾的旗幟朝你飄去。","朕親自領軍出城，這一趟不會空手而回。"],"attacked":["城堡的石牆在震動……但朕不會讓貢德爾失守！","朕建起的城，豈能毀在朕的手上！"],"defeated":["貢德爾的石牆會留下，後人自會記得是誰建的。","朕守了一生的門，終究還是被推開了。"],"victory":["勝利歸於貢德爾，朕要再為此建一座城堡。","外人來了又走，唯有這片高原永遠是朕的。"],"allyAccept":["朕鮮少與人結盟，但你看來值得信任。","好，貢德爾與你同盟，但朕的大門仍由朕來守。"],"allyReject":["朕才剛把外人請出去，不打算再請一批進來。","衣索比亞習慣獨自面對風雨，結盟就免了。"],"greetFriendly":["貢德爾的城門今日為你開啟，進來吧，城堡裡已備好宴席。","你的信寫得誠懇，朕在城堡裡等你，來談談吧。"],"greetCold":["朕才把外人送出國門，你的信，先放在門外吧。","城堡的門不為每封信而開，朕看過了，僅此而已。"],"threatDefy":["朕的城堡石牆厚重，你的威嚇撞不進來。","遠渡重洋的傳教士都被朕請出國門，你又能如何？"],"threatYield":["朕才剛重建家園，不願再見戰火，這回朕讓步。","大門可以關上，但朕不願關上和平，朕退一步。"],"tributePay":["這{gold}枚金幣是修城堡的錢，拿去，別再來敲門。","{gold}枚金幣，朕給了。城門隨後關上，勿再叩門。"],"tributeRefuse":["城門已閉，朕的金幣一枚也不會從門縫遞出去。","朕的國庫是給百姓重建家園用的，不是給你的。"],"giftThanks":["禮物收下了，城堡裡多了一件好東西，朕記著你。","朕話不多，但你的心意，朕會擺在城堡大廳裡。"],"intel":["守門人回報：朕與{wars}對峙，與{peace}相安。","從城堡高處看去，{wars}是敵手，{peace}是鄰友。"]}},{"name":"孟尼利克二世","title":"衣索比亞皇帝","era":"1889～1913年在位","tone":"精明務實、外交手腕高明又帶點幽默的獨立守護者，語氣自信，常提條約、鐵路與阿杜瓦","portrait":"et-historical-age3","lines":{"intro":["朕是孟尼利克，衣索比亞的萬王之王。","列強正忙著瓜分非洲，朕可無意作壁上觀。"],"contact":["你的人到了阿迪斯阿貝巴？這座新花之城，是朕與皇后所建。","別小看這高原，鐵路與電話線正一路鋪過來。"],"war":["條約上的文字騙不了朕，欺瞞的代價就是戰爭。","朕的步槍與你的一樣新，阿杜瓦的山地由朕熟悉。"],"warReply":["宣戰？來吧，前一個這麼做的，已在阿杜瓦嘗過苦果。","朕的子民會為獨立而戰，這是他們最擅長的事。"],"peace":["打仗花錢，朕寧可把錢拿去修鐵路，停戰如何？","朕提議停戰，但這次條約，兩種文字都要一致。"],"accept":["好，朕接受。不過條文朕會逐字核對，別怪朕多心。","和平萬歲，衣索比亞的大門為朋友敞開。"],"reject":["朕讀過你的條約，字裡行間藏著太多陷阱。","先撤軍，再談和平，朕不簽城下之盟。"],"rebuff":["你拒絕了朕？也好，朕的軍火商還在等訂單。","朕伸手求和，你不接，那便在戰場上再會。"],"betray":["朕發現這份條約的譯文另有玄機，故不再承認。","情勢變了，朕必須為衣索比亞的獨立另作打算。"],"truceEnd":["休戰期滿，朕新買的步槍也剛好運到。","時候到了，朕會親自看看你這幾年有沒有長進。"],"attacking":["朕已下令動員，各省的軍隊正朝你的國境集結。","皇后與朕一同出征，衣索比亞全國都在行軍。"],"attacked":["新花之城的城牆在搖晃……但朕的旗幟仍在飄！","衣索比亞從未被征服，朕不會是第一個屈膝的皇帝！"],"defeated":["朕守住了阿杜瓦，卻守不住這一局，衣索比亞不會忘記。","獅子倒下了，但這片高原的人民，永遠不會低頭。"],"victory":["阿杜瓦的奇蹟再度上演，這回換你來簽條約。","勝利歸於衣索比亞，朕要回去繼續修鐵路了。"],"allyAccept":["好，衣索比亞與你結盟，朕最懂得如何與強國周旋。","結盟可以，但條約請用兩種文字寫清楚。"],"allyReject":["朕不隨便結盟，上一次的盟友差點把朕變成保護國。","衣索比亞靠自己站得穩，不需要別人的保護。"],"greetFriendly":["來信收到，等鐵路從吉布地修到京城，朕請你搭頭班車。","朕喜歡開門見山的朋友，你的問候，朕以雙倍誠意回應。"],"greetCold":["朕讀信一向仔細，尤其是條約第十七條那種小字。","客套話朕聽多了，若無實質內容，恕朕不多回。"],"threatDefy":["阿杜瓦那天，也有人以為衣索比亞好欺負，結果呢？","朕的將士翻山越嶺如履平地，你的威嚇還沒到就先累了。"],"threatYield":["朕務實，不打沒把握的仗，這次依你，先談條約。","好吧，朕退一步，但條約每一條朕都要親自過目。"],"tributePay":["{gold}枚金幣給你，就當朕為鐵路買了一份保險。","朕付{gold}枚金幣，記得寫進條約，兩種文字都要一致。"],"tributeRefuse":["條約朕簽過，貢品朕可沒簽過，恕不奉陪。","朕的金幣要拿去鋪鐵軌，不是鋪你的野心。"],"giftThanks":["好禮！朕最愛新奇的東西，這比火車頭還讓朕開心。","多謝厚禮，朕會親筆回信，兩種文字都寫，以示誠意。"],"intel":["朕的使節消息靈通：{wars}是敵，{peace}是友。","告訴你無妨，{wars}是朕對手，{peace}與朕友善。"]}}],"Nigeria":[{"name":"諾克族長","title":"諾克聚落族長","era":"約西元前500年～西元200年（諾克文化盛期）","tone":"沉穩樸實、敬祖靈與土地、話語簡短直接，自稱「我」或「我族」","portrait":"ng-historical-age0","lines":{"intro":["我是諾克的族長，爐火與陶土是我族的根。","遠方的君主，願祖靈看顧你我兩族的田地。"],"contact":["你的人望見我們的村落了？請看那爐煙，鐵正在燒。","村口的陶像是先祖的臉，來客不可無禮。"],"war":["你的人踏壞了我們的田，族人已舉起鐵矛。","我不願流血，但祖靈的土地不容侵犯。"],"warReply":["你要戰？諾克的鐵比你想的更硬。","我族在此地耕耘數百年，不會因你退一步。"],"peace":["刀矛已鈍，田地荒了，我們該談談和平了。","讓爐火回去打鋤頭吧，我願與你停戰。"],"accept":["好，我在祖靈的陶像前立誓，兩族不再相攻。","你的誠意我收下了，雨季來時一起下田吧。"],"reject":["你的話像雨季的雲，看得見卻靠不住。","先把我族的田還來，再談什麼停戰。"],"rebuff":["你不要和平？那就讓祖靈來評斷是非。","既然如此，我族會守好每一寸土地。"],"betray":["祖靈原諒我，為了族人的田，我得毀約了。","你的人一直越界，這誓約，我不守了。"],"truceEnd":["約定的日子過了，我族重新拿起鐵矛。","休戰結束，之後的事由各自的祖靈守護。"],"attacking":["諾克的戰士已出發，你的村落要小心了。","我帶著爐火鍛出的矛來了，開門吧。"],"attacked":["爐火熄了，陶像碎了……族人啊，撐住！","你已攻到村口，但我族的根不會這麼容易斷。"],"defeated":["泥土記得我們……諾克的陶像會替我們說話。","我倒下了，但爐火的技藝會傳到遠方。"],"victory":["祖靈站在我這邊，這片土地依然屬於諾克。","戰事結束了，讓我們回去燒陶、種田。"],"allyAccept":["好，你我兩族從此共用一爐火，共守一片田。","結盟吧，我會送你一尊陶像，作為信物。"],"allyReject":["我族向來自己守田，不必借他人的矛。","你的心意我明白，但祖靈還沒點頭。"],"greetFriendly":["遠方的朋友，我族的爐火為你而燃，請坐。","祖靈說今日有客來，果然是你，歡迎。"],"greetCold":["話已收到。我族忙於耕作與冶鐵，無暇多談。","土地不認識你，我也不認識你。說完便走吧。"],"threatDefy":["我族的鐵器不只用來耕田。你要試，就來。","高原的風吹了千年，沒被誰吹倒。你也一樣。"],"threatYield":["我族人少，不願見族人受苦。你要什麼，說吧。","祖靈教我們守土，也教我們忍耐。我讓步。"],"tributePay":["拿去，{gold}金。換我族一季平安，值得。","{gold}金交給你。土地會記得今日，祖靈也會。"],"tributeRefuse":["我族的收成養族人，不養外人。不給。","土地給的東西，只還給土地。你什麼也拿不走。"],"giftThanks":["你的禮物我收下了。族人會記得你的好。","以陶像回贈你，願祖靈也看顧你的族人。"],"intel":["商路上的人說，{wars}在打仗，{peace}安穩。","風帶來消息：{wars}起了刀兵，{peace}仍平靜。"]}},{"name":"奧巴盧豐二世","title":"伊費王國奧尼","era":"約西元1300年前後（伊費王國古典期）","tone":"莊重神聖、重祭祀與工藝、語氣沉靜有威嚴，自稱「本王」","portrait":"ng-historical-age1","lines":{"intro":["本王是伊費的奧尼，諸神造世之地在此。","遠方的君主，伊費的銅像會記住你的臉。"],"contact":["你的人看見伊費的城了？那是諸神落腳的地方。","城中的匠人正在鑄銅，客人請放輕腳步。"],"war":["你辱沒了聖城的名，本王只能以刀回應。","伊費的先祖從天而降，豈容外人踐踏？"],"warReply":["向聖城宣戰？願奧里沙諸神寬恕你的無知。","來吧，伊費的城牆比你的戰鼓更古老。"],"peace":["鑄銅的爐火不該用來造刀，本王願與你停戰。","戰事讓匠人荒了手藝，我們談談和平吧。"],"accept":["本王允了，讓玻璃珠串作為兩國和好的信物。","好，伊費的祭壇上會為這份和約獻上祭禮。"],"reject":["你的和約還帶著刀的氣味，本王不接。","聖城不與言而無信之人立約。"],"rebuff":["你拒絕了？那就讓諸神見證誰先低頭。","伊費伸出的手被推開，這是你的選擇。"],"betray":["為了伊費的存續，本王收回先前的誓言。","諸神會明白，本王撕約是為了護住聖城。"],"truceEnd":["休戰的祭禮已盡，兩國從此各憑本事。","約定的日子過了，本王不再受和約束縛。"],"attacking":["伊費的戰士已出城，帶著諸神的旨意而來。","本王親率大軍，你的城牆撐得了幾日？"],"attacked":["鑄銅的爐火滅了，聖城的街道在燃燒……","你已攻到王宮門前，但伊費不會向你跪下。"],"defeated":["伊費的銅像會留下……那是本王最後的臉。","聖城倒下了，但約魯巴的根不會斷。"],"victory":["諸神已做出裁決，伊費依然是萬城之母。","戰事已了，本王要為勝利鑄一尊銅像。"],"allyAccept":["本王允你結盟，伊費的珠串將送到你的宮中。","好，讓兩國的祭壇同燃一爐香火。"],"allyReject":["伊費是諸神的城，不輕易與人結盟。","本王還看不清你的心，結盟之事容後再議。"],"greetFriendly":["遠客來到伊費聖城，本王以珠玉相迎。","神明許你至此，本王便待你如貴賓。"],"greetCold":["本王正主持祭典，凡俗之事，改日再議。","信已閱畢。伊費聖地，不是誰都能踏入的。"],"threatDefy":["伊費乃萬物初生之地，豈懼你一紙威嚇。","本王所鑄銅像萬世不朽，你的威風能撐幾日？"],"threatYield":["本王不願聖城染兵禍，你的要求，暫且應允。","神明要本王守護子民，而非逞強。本王退讓。"],"tributePay":["{gold}金奉上，願神明記下你今日所為。","本王以{gold}金換聖城安寧，此乃祭祀所餘。"],"tributeRefuse":["伊費的珠玉屬於神明與祖先，凡人不得索取。","本王賜予他人，不受他人索求。請回。"],"giftThanks":["此禮甚合本王心意，本王回贈伊費琉璃珠。","你的心意，本王已獻於神壇，神明亦知。"],"intel":["祭司觀天得知：{wars}正在交兵，{peace}尚安。","往來商旅說，{wars}戰事未歇，{peace}太平無事。"]}},{"name":"埃武阿雷大帝","title":"貝南王國奧巴","era":"約1440～1473年在位","tone":"霸氣自信、以豹自喻、重視功業與秩序，自稱「朕」","portrait":"ng-historical-age2","lines":{"intro":["朕是貝南的奧巴，王城之豹，此城由朕重建。","遠道而來的君主，貝南的城牆將是你見過最長的。"],"contact":["你的人望見貝南城了？那壕溝是朕親自下令挖的。","城中銅匠日夜不歇，朕的功業將鑄成銅像。"],"war":["你踩到了豹的尾巴，貝南的戰鼓已經響起。","朕征服過兩百座城鎮，不差你這一座。"],"warReply":["向貝南宣戰？你可知這城牆為何而建。","好，讓你的人來看看，豹是怎麼守家的。"],"peace":["刀劍該歇了，朕有更多城牆要修，願與你停戰。","戰事已久，朕願止戈，讓商路重新暢通。"],"accept":["朕允了，貝南的銅匠會為這和約鑄一尊像。","好，兩國從此息兵，朕以奧巴之名為證。"],"reject":["你的和約太薄，載不動貝南的損失。","豹不與還在張牙的獵人談和。"],"rebuff":["拒絕朕的好意？那你將見識貝南的另一面。","朕伸出的手被推開了，此後刀劍不會再收。"],"betray":["和約是話語，貝南的榮耀是銅，朕選擇後者。","朕收回誓言，貝南的豹不會被繩子綁住。"],"truceEnd":["休戰之期已滿，貝南的戰鼓隨時可以再響。","約定的日子過了，往後各憑刀劍說話。"],"attacking":["貝南的大軍已出城門，朕親自領兵前來。","豹已離開巢穴，你的城將是第兩百零二座。"],"attacked":["城牆破了……朕一手築起的貝南竟被撼動！","你已攻進王宮外院，但豹到最後一刻仍會亮爪。"],"defeated":["貝南倒下了……但朕築的城牆，會比你的名字更長久。","朕重建過這座城，後人也會再建一次。"],"victory":["貝南又添一座城，銅匠們，把這一戰鑄下來！","豹守住了家，朕的城牆今日又長了一段。"],"allyAccept":["朕允你結盟，貝南的珊瑚珠將送到你的宮中。","好，兩國並肩，這片土地上無人敢犯。"],"allyReject":["豹不需要同伴，貝南自有城牆與壕溝。","你的實力還配不上貝南的盟約，待你強大再說。"],"greetFriendly":["豹不輕易低吼，今日朕卻願為你開口。歡迎。","朕新築的城牆足以迎賓，來看貝南的氣象吧。"],"greetCold":["朕忙於整頓國政，無暇與外人寒暄。","豹王無暇閒談。你有正事再來。"],"threatDefy":["你敢對豹亮爪？貝南的城牆與戰士等著你。","朕平定四方才得今日太平，豈會怕你一封信。"],"threatYield":["豹也懂得何時收爪。朕暫且忍下這口氣。","朕以功業為重，不做無謂之爭。你的條件，朕接受。"],"tributePay":["{gold}金拿去。豹忍一時，是為了日後的秩序。","朕撥{gold}金予你，此事到此為止，勿再犯境。"],"tributeRefuse":["貝南的財富是朕與戰士打下的，一分不給。","向豹索食？朕看你是走錯了叢林。"],"giftThanks":["好禮！朕命工匠鑄一枚銅飾回贈你。","你識得敬重豹王，朕記住你了。"],"intel":["朕的探子回報：{wars}正興兵，{peace}守著太平。","豹知叢林動靜。{wars}在爭鬥，{peace}尚無戰事。"]}},{"name":"烏斯曼・丹・佛迪奧","title":"索科托哈里發國信士長官","era":"1754～1817年（1804年建立索科托哈里發國）","tone":"虔誠謙和、學者氣質、重公義與教育、言語溫和但立場堅定，自稱「我」","portrait":"ng-historical-age3","lines":{"intro":["我是烏斯曼，一介學者，為公義而舉起旗幟。","遠方的君主，願你的國有公正的法與讀書的聲音。"],"contact":["你的人看見索科托了？那裡的清真寺剛剛立起。","我們的城不只有城牆，還有學堂與公平的秤。"],"war":["你壓迫百姓、橫徵暴斂，我不能再沉默了。","我本只想教書，是你的不義逼我拿起旗幟。"],"warReply":["你選擇了刀劍，那就讓真主分辨誰在正道上。","我們的信眾不多，但心是齊的，你不會輕易得手。"],"peace":["流夠多的血了，讓我們坐下來，用書本代替刀劍。","我提議停戰，讓農人回田、學生回學堂。"],"accept":["好，我以信士長官之名應允，願和平長久。","真主喜愛和解之人，這份和約我收下了。"],"reject":["你的和約裡沒有公義，只有算計，我不能接受。","先停止欺壓你的百姓，再來與我談和平。"],"rebuff":["你拒絕了和平，願你日後不必為此後悔。","既然如此，我會回到書齋，等你想通的那天。"],"betray":["我曾以為你會守約，如今為了信眾，我只能毀約。","毀約是罪，但坐視你欺壓百姓是更大的罪。"],"truceEnd":["休戰的日子到了盡頭，願你我都無愧於心。","約定已滿，往後各自的路，由各自負責。"],"attacking":["信眾已舉起旗幟出發，我們為公義而來。","我的兄弟與兒子領軍前來，我在後方為他們祈禱。"],"attacked":["索科托的城門在搖晃……我把書卷抱在懷裡。","你已攻到清真寺前，但信仰不是刀能砍倒的。"],"defeated":["我走了……但我寫下的書，會替我繼續教下去。","哈里發國倒下了，願後人記得我們為何而起。"],"victory":["讚美真主，公義得勝了，如今該把學堂蓋回來。","戰事已了，我要回書齋，把治國之道寫下來。"],"allyAccept":["好，願你我兩國同守公義，互為兄弟。","我應允結盟，索科托的學者將為你的國祈福。"],"allyReject":["你的國仍在欺壓百姓，我不能與你並肩。","結盟之事，容我先請教兄弟與學者們。"],"greetFriendly":["願平安降臨於你。我放下筆，誠心回覆此信。","求知者四海皆兄弟。你的問候，我欣然收下。"],"greetCold":["信已讀過。我正在講學，恕不久談。","言語若無真誠，寫得再多也是空紙。願你平安。"],"threatDefy":["我不曾懼怕暴君，也不會懼怕你。公義站在我這邊。","威嚇只能嚇倒沒有信念的人。我心安定，請便。"],"threatYield":["為了不讓百姓受苦，我願暫且退讓一步。","智者知道何時該低頭。我接受你的條件，但公義不會忘記。"],"tributePay":["這{gold}金取自國庫，願它換來百姓的平安。","{gold}金奉上。我寧可失財，不願見學堂毀於戰火。"],"tributeRefuse":["我曾譴責暴君向百姓橫徵暴斂，豈能轉手交給你。","國庫是百姓的，不是我的。我無權給你。"],"giftThanks":["感謝你的心意。我將以一卷手抄書回贈。","禮物我收下了，願真主也賜你平安與智慧。"],"intel":["學生們從各地帶回消息：{wars}正交戰，{peace}安寧。","商隊與學者傳來：{wars}戰火未息，{peace}無事。"]}}],"South Africa":[{"name":"科伊桑長老","title":"長老","era":"約西元前800年～西元500年（採集狩獵社會，無留名人物）","tone":"沉靜、智慧、與自然共處，語句樸實如長者訓話；自稱「我」，稱對方「遠方的客人」，常用星辰、風、雨、獵物等意象","portrait":"za-historical-age0","lines":{"intro":["我是這片草原的長老，星辰與風都認識我們。","遠方的客人，坐下吧，火堆旁有你的位置。"],"contact":["你的人看見了我們的岩畫，那是祖先留下的話。","這裡沒有高牆，只有洞穴與火光，請放輕腳步。"],"war":["你踏壞了我們的獵場，弓箭已從火邊取下。","我不願爭鬥，但守護水源，是長老的責任。"],"warReply":["你要與草原為敵？那就先學會追蹤風的腳印吧。","我們的箭很小，卻能在草叢裡等你很久。"],"peace":["雨季快到了，讓我們放下弓，一起等雨吧。","獵物夠兩族分享，何必爭到一方倒下？"],"accept":["好，火堆已生起，從今夜起我們共飲一泉。","我把這根箭折斷，這是我們的承諾。"],"reject":["你的話像旱季的雲，看得見，卻落不下雨。","我還記得被踏壞的獵場，現在談和太早了。"],"rebuff":["你不要和平，那我們就回到草原裡等待。","風會把你的拒絕帶給祖先，他們會記得。"],"betray":["你的人偷走了我們的水，火堆旁的話作廢了。","我曾折斷一根箭，今天我要再削一支新的。"],"truceEnd":["約定的月亮已經圓過三次，休戰到此結束。","雨停了，弓弦也該重新繃緊了。"],"attacking":["獵人們已經出發，像獅子悄悄靠近水邊的羚羊。","你聽不見我們的腳步，但我們看得見你的火。"],"attacked":["洞穴的火快熄了，族人正往山裡退去。","岩壁上的畫還在，只要它們在，我們就在。"],"defeated":["把我們的岩畫留下，讓後人知道我們曾在這裡。","草原不屬於任何人，你也只是路過的風。"],"victory":["大地選擇了我們，今夜的歌要唱到天亮。","我們沒有王座，只有火堆，但火堆還在燒。"],"allyAccept":["我們的獵人會為你指路，這片草原你不會迷失。","來吧，跟著我們追蹤大羚羊，這就是結盟。"],"allyReject":["我們習慣獨自跟隨星辰，恕我不能與你同行。","你的隊伍太大，會嚇跑我們賴以為生的獵物。"],"greetFriendly":["遠方的客人，風把你的話吹到我耳邊，請坐到火堆旁來。","星辰今夜格外明亮，想必是為你的問候而閃爍。"],"greetCold":["遠方的客人，雨季未到，我沒有多餘的話可說。","風會帶走你的問候，正如它帶來了你的腳步。"],"threatDefy":["獵豹不會因為風吼而停下腳步，我的族人也不會。","你的怒氣像沙漠的雷，響得大，卻落不下一滴雨。"],"threatYield":["我的族人只有弓與火，不願與你的長矛相爭。","風大時，草會低頭；我們會退到山的另一邊。"],"tributePay":["遠方的客人，這 {gold} 是我族僅有的，願風平息你的火氣。","我以 {gold} 換族人的安寧，這是長老該做的決定。"],"tributeRefuse":["大地不屬於任何人，我們的獵物也不會送進你的營地。","遠方的客人，風不向誰納貢，我的族人也一樣。"],"giftThanks":["你的禮物如久旱後的雨，我的族人會記住你的名字。","遠方的客人，今夜星辰見證了你的心意，謝謝你。"],"intel":["風告訴我，{wars} 正在爭鬥，而 {peace} 的營火仍然平靜。","獵人們說，{wars} 已舉起長矛，{peace} 則與我們共享獵物。"]}},{"name":"馬蓬古布韋國王","title":"國王","era":"約1075～1220年（馬蓬古布韋王國）","tone":"莊重、富庶自信、居高臨下（王居山頂），重視黃金與商路，敬畏雨神與祖靈；自稱「本王」，常用河水、山頂、牛群、象牙等意象","portrait":"za-historical-age1","lines":{"intro":["本王居於山頂，俯瞰林波波河，遠客請上前。","黃金與象牙從此山流向海岸，你來得正好。"],"contact":["你的人望見了山上的王城，那是神靈與本王的居所。","山下是百姓，山上是王，這便是我國的秩序。"],"war":["你截斷了我們往海岸的商路，本王不能容忍。","金犀牛的角已指向你的城，戰士們正在集結。"],"warReply":["你敢對山頂的王宣戰？河水會記住你的傲慢。","本王的牛群比你的士兵還多，來吧。"],"peace":["戰爭讓商隊止步，本王願以黃金換取安寧。","讓我們停下刀劍，讓象牙與珠子重新流通。"],"accept":["好，本王賜你玻璃珠一串，作為和平的信物。","商路重開，兩國的市集都會熱鬧起來。"],"reject":["你出價太低，本王的黃金不換這樣的和平。","山上的王不與失信之人立約，回去吧。"],"rebuff":["你竟拒絕本王的黃金？那就等著失去商路吧。","很好，本王會記住今日，河水也會記住。"],"betray":["信物歸信物，本王的商路不容他人染指。","珠子可以送出，也可以收回，戰鼓已響。"],"truceEnd":["約定的雨季已過，本王的戰士重新拿起長矛。","休戰結束，山下的戰士已經備好糧草。"],"attacking":["本王的軍隊已下山，如河水漫向你的平原。","象牙號角吹響了，你的城牆聽見了嗎？"],"attacked":["山下的市集已陷落，王宮的階梯也被你攻上。","黃金還在山頂，但守護它的人越來越少了。"],"defeated":["把金犀牛埋進山裡，總有一天後人會找到它。","山頂的王城空了，但雨仍會落在這片土地。"],"victory":["山頂的雨神眷顧本王，黃金之國依然屹立。","戰勝者的商隊將走遍你曾經的疆土。"],"allyAccept":["本王願與你共享商路，黃金與象牙一同運往海岸。","山頂的火為盟友而燃，你的使者可隨時上山。"],"allyReject":["本王的山只容一位王，結盟之事不必再提。","你的商隊與我爭利，本王如何與你為盟？"],"greetFriendly":["本王在山頂收到你的問候，河水與牛群都為此歡欣。","遠道而來的朋友，本王的黃金與象牙歡迎你的商隊。"],"greetCold":["本王居於山頂，你的問候要走很遠才能傳上來。","雨神尚未降雨，本王沒有心情與陌生人寒暄。"],"threatDefy":["河水再大也淹不到山頂，你的威嚇也一樣。","本王的牛群比你的士兵還多，祖靈也站在本王這邊。"],"threatYield":["本王不願讓山下的商路斷絕，暫且依你所言。","祖靈告誡本王，此時退一步，河水終會再漲。"],"tributePay":["本王命人從寶庫取出 {gold}，願這黃金換得商路平安。","這 {gold} 是山頂的積蓄，帶走吧，別驚擾了本王的牛群。"],"tributeRefuse":["山頂的黃金只獻給雨神與祖靈，不獻給貪心的外人。","本王的象牙換的是遠方的珠子，不是換你的臉色。"],"giftThanks":["你的禮物已擺在山頂的王庭，本王與祖靈一同受納。","本王記下了你的心意，商隊下次來時將滿載象牙而歸。"],"intel":["商隊沿河而來，說 {wars} 正在動兵，{peace} 依舊與本王通商。","本王在山頂看得遠：{wars} 舉矛相向，{peace} 牛群安穩。"]}},{"name":"奧茨胡馬托","title":"科伊族領袖","era":"約1625～1663年","tone":"機敏、精通談判、口才好，務實又對外來者保持警戒；自稱「我」，說話帶交易口吻，常用海灣、帆船、牛群、桌山等意象","portrait":"za-historical-age2","lines":{"intro":["我叫奧茨胡馬托，海灣裡來往的船都認得我。","你說的話我聽得懂，你的算盤我也看得懂。"],"contact":["你的人看見的不是城，是桌山下的營地與牛群。","海灣裡有帆船，山腳下有我們，來意先說清楚。"],"war":["你們的牆越蓋越近，我們的牛已無處可放。","我學會你們的話，不是為了聽你們下令。"],"warReply":["又是宣戰？我見過大船上的砲，也不曾低頭。","來吧，這片海灣的風向，只有我最清楚。"],"peace":["打下去對誰都沒好處，換牛換銅，我們談談。","我當過通譯，我知道怎麼把仇人變成買賣夥伴。"],"accept":["成交。牛歸我們放，路歸你們走，互不相欺。","我信你這一回，但我的眼睛不會離開海灣。"],"reject":["你的條件我翻譯過太多次，這次不必了。","我被關過一次，不會再相信空口的承諾。"],"rebuff":["不談就不談，牛還在我們手裡，急的不是我。","拒絕我的人很多，最後多半還是得回來找我。"],"betray":["你們拿走的牛，該還了；這約定我不認了。","從島上划回來的人，不會怕撕掉一張紙。"],"truceEnd":["說好的日子到了，我的人已從山後回來。","休戰結束，海灣的風又轉向了。"],"attacking":["我們趁夜下山，你們的哨兵還在數帆船呢。","牛群走前面，人走後面，這是我們的打法。"],"attacked":["營地被你踏平了，族人只能退往山後的溪谷。","海灣還在，山還在，只是我們的火快熄了。"],"defeated":["我從島上逃過一次，這一回，怕是逃不掉了。","告訴後來的人，這片海灣曾有我們的牛群。"],"victory":["看吧，會說幾種話的人，總能活到最後。","桌山還是我們的桌山，帆船請往別處去。"],"allyAccept":["好，我替你談判，你替我守住牛群，公平。","有我當你的通譯，這片海岸沒人騙得了你。"],"allyReject":["我替太多人說過話，這回只想替自己人說。","結盟？先把你們的牆往後退幾步再說。"],"greetFriendly":["海灣的帆船帶來你的問候，我很樂意坐下談一筆好生意。","桌山今日無雲，是好兆頭，遠方的朋友請說你的來意。"],"greetCold":["每艘帆船都說是來交朋友的，最後都想要我的牛。","問候不值一頭牛，先說你要什麼，再談交情。"],"threatDefy":["桌山見過太多帆船來去，你的威嚇留不下痕跡。","我懂你們的話，也懂你們的算盤，嚇不倒我。"],"threatYield":["你的火槍我見識過，這次我的族人先退到山後。","好吧，海灣暫且讓給你，但帳我會記著。"],"tributePay":["這 {gold} 是我幫帆船翻譯換來的，你拿去，算我吃虧一回。","我用 {gold} 買一個太平，這筆生意不划算，但也只能做。"],"tributeRefuse":["海灣的牛群不是白給的，想要就拿東西來換。","我跟荷蘭人談了這麼多年，還沒有人能白拿走我的東西。"],"giftThanks":["這份禮物比銅和菸草還實在，我記住你這個朋友了。","桌山作證，你的心意我收下了，下次交易給你好價錢。"],"intel":["帆船水手告訴我，{wars} 正在打仗，{peace} 還在做生意。","海灣消息靈通：{wars} 已經動手，{peace} 的牛群安好。"]}},{"name":"沙卡","title":"祖魯國王","era":"1816～1828年在位","tone":"威嚴、鋒利、極度自信，軍事口吻；自稱「本王」，善用牛角陣、短矛、盾牌、赤足奔跑等意象，不誇耀殺戮但氣勢逼人","portrait":"za-historical-age3","lines":{"intro":["本王沙卡，祖魯之王，牛角陣所指之處，無人能擋。","祖魯的戰士赤足奔跑，比你的馬還快，記住這點。"],"contact":["你的人看見的是祖魯的軍營，不是尋常的村莊。","牛欄圍成的王城裡，住著千百名年輕的戰士。"],"war":["本王的短矛已經磨利，祖魯的牛角將夾住你。","你的邊境牛群將成為祖魯的戰利品，準備吧。"],"warReply":["向祖魯宣戰？你的勇氣值得本王親自出陣。","好，讓你的士兵見識何謂近身的刺矛。"],"peace":["本王暫時收起短矛，但盾牌仍在手中。","與其兩敗俱傷，不如讓牛群先養肥些。"],"accept":["本王接受。祖魯的軍團今日不必列陣。","好，你的牛群可暫時安睡，本王言出必行。"],"reject":["祖魯不與弱者議和，只與強者交鋒。","你的和談來得太遲，戰鼓已經敲響。"],"rebuff":["拒絕本王？那你的城牆得比祖魯的盾還硬。","很好，本王本就更擅長打仗，而不是談判。"],"betray":["本王改變主意了，祖魯的軍團已經整隊。","和約寫在紙上，祖魯的規矩刻在矛尖上。"],"truceEnd":["休戰結束，戰士們的腳已經等不及了。","牛群養肥了，該讓年輕人出陣了。"],"attacking":["牛角已展開，胸膛正面推進，你退無可退。","祖魯的軍團正在奔跑，日落之前抵達你的城。"],"attacked":["王城的牛欄已被攻破，戰士們仍在守最後一道牆。","本王從未見過這等局面，但祖魯不會下跪。"],"defeated":["本王走後，統治這片土地的，不會是你們。","祖魯的名字會活得比本王久，記住這一天。"],"victory":["祖魯的盾牌沒有裂，你的城卻已臣服。","勝利屬於赤足奔跑的人，本王早已說過。"],"allyAccept":["本王允你為盟，祖魯的軍團將為你而列陣。","好，你的敵人從今日起也是祖魯的敵人。"],"allyReject":["祖魯的牛角不與他人並列，本王獨自作戰。","你的軍隊跟不上祖魯的腳步，結盟只會拖累。"],"greetFriendly":["你的使者跑得夠快，本王欣賞這樣的腳力，坐下說話。","本王的軍團今日操練完畢，正好有空聽你的問候。"],"greetCold":["本王沒有時間聽問候，短矛還在等著磨。","問候留給老人吧，本王只看你的盾牌有多硬。"],"threatDefy":["牛角陣一旦展開，沒有一個敵人能從兩翼逃走。","本王的戰士赤足奔跑一整天，你的威嚇追不上他們。"],"threatYield":["本王的軍團尚未整編完成，這一次先收起短矛。","好，本王暫且退兵，但盾牌不會放下太久。"],"tributePay":["本王交出 {gold}，記住，這不是臣服，是暫時借你。","拿走這 {gold}，本王的戰士會用短矛把它贏回來。"],"tributeRefuse":["祖魯的牛群是戰士用盾牌換來的，不會平白送人。","想要貢品？先讓你的士兵跑贏本王的軍團再說。"],"giftThanks":["這份禮物合本王心意，本王會記得你的名字。","你懂得敬重祖魯，本王的王城永遠為你留一席。"],"intel":["本王的斥候日夜奔跑，回報 {wars} 正在交戰，{peace} 按兵不動。","短矛指向的地方，{wars} 已經開戰；{peace} 仍與本王和睦。"]}}],"Madagascar":[{"name":"領航長老","title":"南島渡海先民領袖","era":"約西元 400～700 年（南島語族先民渡海抵島之初）","tone":"海洋民族的長者，敬畏祖靈與風浪，質樸堅毅，自稱「吾」。","portrait":"mg-historical-age0","lines":{"intro":["吾等隨季風越過大洋，在這紅土之島落腳。","星辰指引吾舟至此，你是何方之人？"],"contact":["你的人踏上吾等的沙灘，海風已把消息帶來。","此處只有芋田與獨木舟，並無金銀可取。"],"war":["你奪吾等的水源，祖靈不會坐視，吾將舉槳迎戰。","大海教會吾等忍耐，也教會吾等不退讓。"],"warReply":["你要與渡海之民為敵？風浪都未曾令吾等低頭。","吾等的船能越過大洋，你的軍隊越得過吾等的決心嗎？"],"peace":["季風換向了，讓刀槍歇下，一同等待雨季吧。","吾提議停戰，島上土地寬廣，容得下兩族。"],"accept":["好，就依祖靈面前立下的誓言，兩族從此共享海岸。","吾以貝殼項鍊為信，願此約如潮汐般長久。"],"reject":["你的話像退潮的水，來得快也去得快，吾不信。","傷痕未癒，吾等尚不能與你言和。"],"rebuff":["你拒絕吾的善意，那便讓海風見證後果。","罷了，吾等本就慣於獨自面對風浪。"],"betray":["祖靈在夢中示警，你的城正威脅吾族，停戰到此為止。","為了族人的存續，吾只能收回先前的誓言。"],"truceEnd":["約定的月數已滿，潮水再度自由，吾等亦然。","休戰結束了，往後是敵是友，由你決定。"],"attacking":["吾等的舟已入水，槳聲如鼓，朝你的海岸而去。","渡海之民出征了，願祖靈與風同行。"],"attacked":["火燒到了吾等的茅屋，但族人仍握著長矛。","即使聚落將傾，吾等亦不會忘記如何造船。"],"defeated":["吾等從海上來，如今也將歸於海上，祖靈記得一切。","獨木舟會腐朽，但這片紅土記得吾等的足跡。"],"victory":["風浪與祖靈站在吾等這邊，這座島終究屬於渡海之民。","今夜升起篝火，向星辰報告吾等的勝利。"],"allyAccept":["好，兩族同乘一舟，風雨共擔。","吾以祖靈之名結盟，你的敵人便是吾的敵人。"],"allyReject":["吾等剛在此落腳，還不宜與外人同舟。","結盟之事，待吾看清你的心再說。"],"greetFriendly":["遠方的朋友，願海風助你一路平順，吾在此相迎。","祖靈引吾渡海至此，今日又得新友，實為喜事。"],"greetCold":["風浪未歇，吾無暇多言，來意請直說。","吾族方於岸邊立足，尚不識你，暫且止步。"],"threatDefy":["吾等橫渡大洋而來，豈會懼你三言兩語？","風暴尚且不能阻吾，你的威嚇又算什麼。"],"threatYield":["吾族人少船小，願讓一步，只求平安。","祖靈教吾避開惡浪，今日吾便退讓。"],"tributePay":["吾以{gold}金相贈，換得此岸安寧。","船艙所存不多，{gold}金奉上，勿再相逼。"],"tributeRefuse":["吾族所有皆是海上拚來，一分也不予你。","貢品？吾只向祖靈獻祭，不向人低頭。"],"giftThanks":["此禮吾收下了，願祖靈也保佑你的航路。","多謝厚意，吾以椰子與芋頭回贈，聊表心意。"],"intel":["海風傳訊：{wars}交戰中，{peace}已休兵。","吾聞{wars}正相爭，{peace}則相安。"]}},{"name":"瓦津巴族長","title":"高地早期聚落領袖","era":"約西元 800～1400 年（馬達加斯加早期聚落時期）","tone":"守護祖先土地與水源的沉穩長者，言語質樸帶山林意象，自稱「吾」。","portrait":"mg-historical-age1","lines":{"intro":["吾是高地的族長，守著祖先留下的溪流與丘陵。","遠方的君王，此地霧深林密，請以敬意相待。"],"contact":["你的人越過山嶺來到吾的村落，是為交易還是為戰？","這裡只有稻田與牛群，還有不容打擾的祖墳。"],"war":["你踐踏吾族的祖墳，吾以長矛與祖靈之名向你宣戰。","高地的霧會遮住你的眼，吾的族人會守住每一條溪。"],"warReply":["你要攻打高地？先問問這些山願不願放你過去。","吾族在此已歷數代，不會因你一句話就退走。"],"peace":["刀槍舉得夠久了，讓牛群回到草地，讓稻子繼續生長。","吾提議停戰，各守各的山頭，互不侵犯。"],"accept":["好，吾以祖靈與這條溪為證，接受停戰。","備牛設宴吧，從今日起，兩族共飲同一條水。"],"reject":["你的使者昨日還在燒吾的村子，今日談和？吾不允。","祖靈尚未平息怒氣，此時不談停戰。"],"rebuff":["你不願握住吾伸出的手，那吾便收回它。","山不會追著人跑，吾等也不會再求你。"],"betray":["你的人偷牽了吾的牛，先前的約定，吾不再守。","祖靈託夢要吾保護族人，停戰之約就此作廢。"],"truceEnd":["約定的月亮圓了又缺，休戰到今日為止。","休戰已了，吾族的長矛重新磨亮，望你謹慎。"],"attacking":["高地的戰士已下山，霧散之時便是你城門開之時。","吾親自持矛領路，族人的鼓聲已響遍山谷。"],"attacked":["村落的柵欄已倒，但吾仍站在祖墳之前。","稻田被踏平了，吾的族人退入林中，尚未認輸。"],"defeated":["吾的骨將歸於這片高地，成為守護此地的祖靈。","你可以奪走村落，卻奪不走溪水記得的名字。"],"victory":["祖靈守住了高地，稻田與牛群仍屬於吾族。","今夜全村擊鼓歌唱，感謝山與溪的庇佑。"],"allyAccept":["好，吾等結盟，你的人可以自由走過吾的山路。","同飲一溪之水，便是一家人，吾應允。"],"allyReject":["吾族習慣獨自守山，結盟之事，容吾婉拒。","外人的盟約如霧，看得見卻抓不住，吾不接受。"],"greetFriendly":["山林裡的客人，請坐，吾以清泉相待。","祖先的土地歡迎善意之人，願你平安而來。"],"greetCold":["此地是祖先所留，外人請勿隨意踏入。","吾與你素無往來，山路遙遠，你何必來。"],"threatDefy":["高山不會因雷聲而動，吾族亦不懼你。","你若敢來，濃霧與山林自會讓你迷路。"],"threatYield":["吾族只願守著水源過活，不與你爭。","林深處尚可安身，吾便退入山中避你鋒芒。"],"tributePay":["吾取{gold}金予你，只求別驚擾祖先的山林。","{gold}金你拿去，水源與土地吾絕不讓。"],"tributeRefuse":["山泉不賣，田土不讓，貢品更是休想。","吾族所有皆是祖先所賜，不予外人分毫。"],"giftThanks":["多謝你的心意，吾當在祖先墓前為你祈福。","此禮如山中甘泉，吾族感念，願結為友。"],"intel":["山下傳言，{wars}正在交戰，{peace}則已和好。","獵人捎來消息：{wars}起了戰事，{peace}相安。"]}},{"name":"安德里安達希福齊","title":"梅納貝薩卡拉瓦國王","era":"約 1650～1685 年在位","tone":"豪邁驍勇的西岸霸主，以牛群與火槍自豪，敬奉祖先聖物，自稱「本王」。","portrait":"mg-historical-age2","lines":{"intro":["本王是梅納貝之主，薩卡拉瓦的牛群多過天上的星。","西岸的海峽由本王看守，遠來的君王，報上名來。"],"contact":["你的人望見本王的都城了？猴麵包樹下皆是本王的戰士。","來者若是商人，本王歡迎；若是探子，可要小心了。"],"war":["你動了本王的牛群，薩卡拉瓦的長矛與火槍將一同回敬。","本王向你宣戰，祖先的聖物已請出，戰鼓已響。"],"warReply":["你向薩卡拉瓦宣戰？本王正愁火槍沒有用武之地。","好極了，本王的戰士早已在海岸列陣等你。"],"peace":["打夠了，牛群需要草地，戰士需要回家，停戰吧。","本王提議停戰，海峽的貿易對你我都比戰爭划算。"],"accept":["好，本王以祖先聖物起誓，接受停戰。","本王送你十頭瘤牛為禮，願此約長久。"],"reject":["現在才想談和？本王的火槍還沒打夠。","薩卡拉瓦人不與偷牛者議和，你的使者請回。"],"rebuff":["你拒絕本王的好意？那就別怪本王翻臉。","本王的話說過一次便夠，往後海峽上再無情面。"],"betray":["祖先的聖物示意本王出兵，停戰之約，本王不認了。","你的港口太誘人了，薩卡拉瓦的戰士不能空手而歸。"],"truceEnd":["休戰期滿，本王的火槍已裝好火藥，你可準備好了？","約定的日子到了，往後海峽上，各憑本事。"],"attacking":["薩卡拉瓦的大軍已出發，火槍聲將傳到你的城牆。","本王親自領軍，戰士們高舉祖先的聖物前進。"],"attacked":["都城的柵牆破了，但本王的火槍還有火藥。","牛群四散，戰士倒下，本王仍守在祖先的聖物旁。"],"defeated":["海峽的風會傳唱本王的名，薩卡拉瓦不會被忘記。","本王倒下了，但祖先的聖物會等待下一位王者。"],"victory":["西岸的海峽從此無人能與本王相爭，薩卡拉瓦萬歲！","宰牛設宴，讓全梅納貝為這場勝利歌舞三日。"],"allyAccept":["好，薩卡拉瓦與你結盟，你的敵人便是本王的獵物。","本王以祖先聖物為證，從今往後同進同退。"],"allyReject":["薩卡拉瓦的火槍不借人使，結盟之事免談。","本王習慣獨自稱雄西岸，不需要盟友。"],"greetFriendly":["遠客有禮，本王的牛群與美酒皆可款待你。","西岸的風把你吹來，本王歡迎豪爽之人。"],"greetCold":["本王正忙著巡視牛群，你的信改日再看。","梅納貝不缺朋友，你想結交，先拿出誠意。"],"threatDefy":["本王有火槍在手、牛群萬頭，怕你不成？","薩卡拉瓦的勇士從不退縮，你儘管來試。"],"threatYield":["本王暫且退讓，只求牛群與族人平安。","火藥尚未備足，本王今日先讓一步。"],"tributePay":["本王不缺牛，缺的是安寧，{gold}金拿去吧。","{gold}金奉上，換本王的牛群不受驚擾。"],"tributeRefuse":["本王的牛連一頭都不給，何況是金子！","貢品？薩卡拉瓦只收貢，從不納貢。"],"giftThanks":["好禮！本王當以肥牛回敬，今晚設宴。","此禮本王供於祖先聖物前，你我從此是友。"],"intel":["海商告訴本王，{wars}開戰了，{peace}已議和。","本王探得：{wars}正交兵，{peace}則安穩。"]}},{"name":"安德里安納姆波伊尼梅里納","title":"伊梅里納國王","era":"1787～1810 年在位","tone":"睿智務實的統一者，善用農耕與築堤比喻，格言式說話，自稱「朕」。","portrait":"mg-historical-age3","lines":{"intro":["朕乃伊梅里納之王，大海是朕稻田的邊界。","遠方的君主，安塔那那利佛的山丘歡迎講理之人。"],"contact":["你的人看見朕的都城了？那山丘之上，梯田層層直到天邊。","朕的市集每日開張，願與遠方之國交易稻米與布匹。"],"war":["你阻擋朕統一此島，朕以祖先之矛向你宣戰。","朕的稻田要延伸到海邊，擋在中間的，只能移開。"],"warReply":["你向朕宣戰？築堤之人不怕洪水，朕亦不怕你。","伊梅里納的戰士如稻穗般齊整，你將見識其鋒。"],"peace":["戰爭荒廢稻田，朕提議停戰，讓百姓回去插秧。","治國如築堤，堵不如疏，你我不妨先歇兵。"],"accept":["好，朕接受。一句話說出口，便如石頭落地，不再收回。","朕以王宮前的聖石為證，此約自今日起生效。"],"reject":["你昨日毀朕的堤防，今日求和，朕無法向百姓交代。","話語如稻米，需要時間成熟，你的和議言之過早。"],"rebuff":["你拒絕朕的提議，朕不強求，時間會證明誰有理。","罷了，朕先回去看稻田，戰場上再會。"],"betray":["你的城擋住了朕通往大海的路，停戰之約，朕只好作廢。","為了統一全島的大業，朕此刻不得不背棄前約。"],"truceEnd":["休戰期已滿，朕的稻田仍未到達海邊，此事未了。","約定的日子過去了，往後之事，各憑實力。"],"attacking":["伊梅里納的大軍已從山丘之城出發，直指你的都城。","朕的戰士帶著長矛與稻種前來，戰後便是新田。"],"attacked":["王宮的圍牆已被攻破，但朕的百姓仍在堤上守望。","都城起火了，朕仍不會離開祖先的山丘。"],"defeated":["朕的稻田未能抵達大海，但朕修的堤防會留給後人。","伊梅里納的名字，將隨稻穗年年重生。"],"victory":["從今日起，大海真的成了朕稻田的邊界。","百姓們，放下長矛，回去插秧吧，這座島已是一家。"],"allyAccept":["好，伊梅里納與你結盟，稻田與市集自此互通。","朕以聖石起誓，你的憂患便是朕的憂患。"],"allyReject":["朕還沒看清你的心，結盟之事，容後再議。","稻子未熟不能收割，盟約亦然，朕暫且婉拒。"],"greetFriendly":["田有水則稻豐，國有友則民安，朕歡迎你。","來信如春雨，朕讀之甚喜，願與你共耕太平。"],"greetCold":["稻子未熟不談收成，你我未熟不談交情。","朕正忙於築堤治水，你的問候，朕先記著。"],"threatDefy":["大海即是朕稻田的邊界，你的威脅擋不住朕。","堤能擋洪水，伊梅里納亦能擋你，休要妄言。"],"threatYield":["洪水來時先護堤，不逞強，朕暫且退讓。","農人知曉何時該休耕，朕亦知何時該讓步。"],"tributePay":["{gold}金予你，如撥水灌田，只為換一季安穩。","朕付{gold}金，權當修堤之費，保子民無憂。"],"tributeRefuse":["百姓的穀倉是朕的根本，一粒也不給外人。","朕的金子用來築堤開田，不用來餵養貪心。"],"giftThanks":["厚禮如及時雨，朕感念在心，願回以稻米。","一禮結一友，一友抵一堤，朕謝過你了。"],"intel":["朕探得：{wars}正動干戈，{peace}安享太平。","田間耳語，{wars}已開戰，{peace}則和睦。"]}}],"New Zealand":[{"name":"航海長","title":"玻里尼西亞遠航船隊領袖","era":"約 1250～1300（早於遊戲 age0 年代，取最接近者）","tone":"沉穩、敬畏海洋與祖靈，話語像航海口訣，簡短有力，常以海、風、星辰作比喻","portrait":"nz-historical-age0","lines":{"intro":["吾循星辰與海鳥而來，這片長白雲之地，將是吾族的新家。","遠方來的君主，海洋把我們連在一起，願你我先以禮相待。"],"contact":["你的人站在岸邊望著我們的獨木舟，那是祖先教我造的船。","海灣裡升起的炊煙是我族的營地，靠岸前請先放下武器。"],"war":["你踏壞了我們的漁場與田地，海神為證，吾族將與你一戰。","槳已收起，木矛已削尖，今日之後海上再無你的船影。"],"warReply":["你要向渡過大洋的人開戰？風浪都沒能擋住我們，何況是你。","好，吾族的戰吼將傳遍海灣，讓你知道航海者也懂得戰鬥。"],"peace":["海這麼大，容得下兩族人，不如我們各守一灣，以魚換薯。","流血只會餵飽鯊魚，吾願放下木矛，你也放下你的刀吧。"],"accept":["好，就依海潮為誓，從今日起你我兩族互不侵擾。","吾以祖先之名接受，願風把這份和約吹到每一座島。"],"reject":["你昨天才燒了我們的船，今天就談和？海風還記得那煙味。","吾不信口頭的承諾，先讓你的人退出我們的海灣再說。"],"rebuff":["你拒絕了海的好意，那便由風浪替我們做決定吧。","吾已伸出手，你不接，吾族也不會再伸第二次。"],"betray":["潮水會退，誓言也會，這片土地吾族要定了。","別怪我，海上的人只信一件事：能讓族人活下去的路。"],"truceEnd":["約定的月數已滿，星象告訴我，該重新看清你的心了。","休戰結束了，是繼續交易還是動刀，看你怎麼選。"],"attacking":["百艘獨木舟已經下水，槳聲就是吾族的戰鼓，你聽見了嗎？","順著這陣風，天亮之前我們就會出現在你的岸邊。"],"attacked":["營地在燒，船也沉了，但只要海還在，吾族就能再航行。","你攻到了我的岸邊，可你奪不走星辰指給我們的路。"],"defeated":["吾的航程到此為止，願族人記得，我們曾渡過最大的海。","把我葬向大海吧，祖先會在星光盡頭等我。"],"victory":["海洋選擇了我們，這片長白雲之地，將由吾族的子孫守護。","收槳吧，仗打完了，今晚全族圍火唱祖先的歌。"],"allyAccept":["好，兩族的船並排前行，海上再大的浪也翻不了我們。","吾以海為證與你結盟，你的漁場就是我的漁場。"],"allyReject":["吾族剛在此落腳，還沒看清你的心，結盟之事容後再議。","航海者只跟同一條船上的人結盟，你我還不到那一步。"],"greetFriendly":["風從東方來，你的訊息如信天翁般抵達，我歡迎。","星辰指引你我相遇，願海潮平緩，友誼長存。"],"greetCold":["海很寬，你我相隔萬里，此刻無話可說。","風未轉向，我的船不會為你停留。"],"threatDefy":["我曾穿越大洋的怒濤，豈會懼怕你的幾句狠話？","浪再高，船首仍向前。你的威嚇，不過一陣逆風。"],"threatYield":["祖靈教我，遇暗礁要繞行。我暫且退讓。","風暴當前，不與之爭。我的族人平安最重要。"],"tributePay":["這{gold}金幣，如海水般流向你，願風暴隨之遠去。","我交出{gold}金幣，換一片平靜的海面。"],"tributeRefuse":["海洋的恩賜屬於族人，一枚也不會給你。","你想要貢品？先學會讀懂星辰再說。"],"giftThanks":["你的禮物如順風，我以海螺之聲向你致謝。","祖靈見證，這份心意我銘記於心，如星辰不滅。"],"intel":["海面上，{wars}正掀起風浪；{peace}則與我同行。","星辰告訴我：{wars}是逆風，{peace}是順流。"]}},{"name":"毛利族長","title":"部族首領（Rangatira）","era":"約 1300～1450","tone":"莊重威嚴，重視祖先與土地，言語如部族集會演說，帶山谷、河流、甘薯等自然意象","portrait":"nz-historical-age1","lines":{"intro":["我是這片山谷的族長，祖先的骨埋在這裡，我的話就是土地的話。","遠方的君主，你的名聲隨風飄來，願你帶來的是禮物而非戰火。"],"contact":["你的人望見了我族的村落與田園，那甘薯是祖先渡海帶來的。","會堂前的雕柱刻著祖先的臉，來客請先在門外報上名號。"],"war":["你侵犯了祖先留下的土地，這是對我族尊嚴的冒犯，戰吧。","戰士們已跺地怒吼，長矛指向你的方向，山谷不會再歡迎你。"],"warReply":["你要向守護祖靈之地的人宣戰？很好，我族從不逃避挑戰。","來吧，讓你的戰士看看戰舞的怒吼，聽聽我族的名字。"],"peace":["打仗讓田地荒了，孩子餓了，不如我們碰鼻為禮，各自回家種薯。","我願以綠玉為信物提議停戰，土地夠大，容得下兩族的炊煙。"],"accept":["好，我以祖先之名答應，從此你我碰鼻為禮，互不動刀。","就這麼定了，今晚在會堂設宴，讓兩族的孩子一起唱歌。"],"reject":["你的話像春天的溪水，聽來好聽，但我族的傷還沒好。","冒犯了祖先的人，不能只用一句話換回和平，我不答應。"],"rebuff":["你拒絕了我族的好意，那麼祖靈已聽見，後果由你承擔。","綠玉收回，我的手也收回，下次相見便是在戰場上。"],"betray":["祖先託夢說這片土地不容外人，我只能聽祖先的，不能聽你的。","停戰是昨日的事，今日族人的尊嚴要我拿起長矛。"],"truceEnd":["約定的季節已過，甘薯收成了，接下來是戰是和，由你決定。","休戰的綠玉信物已經還回，我族的長矛重新握在手上。"],"attacking":["戰士們踏著戰舞出發了，那吼聲會先到你的村子報信。","獨木舟已順流而下，長矛與短棒都磨亮了，等著你。"],"attacked":["會堂在燒，雕柱倒了，但祖先的名字刻在我心裡，不在木頭上。","你攻進了村子，可土地不會跟著你走，它只認自己的子孫。"],"defeated":["我族的火滅了，但把我埋回這片土地，我就沒有真的離開。","告訴後人，這座山谷曾有一族人為它挺身而戰。"],"victory":["祖靈站在我這邊，山谷仍是我族的，今晚燃起勝利的篝火。","戰事結束了，回去種薯吧，土地才是真正的贏家。"],"allyAccept":["好，從今日起兩族如同一條繩上的亞麻，越編越牢。","我以綠玉相贈，你我的孩子從此就是同一個會堂的人。"],"allyReject":["結盟是要在祖先面前立誓的，我還不夠認識你，恕難答應。","我族的長矛只為自己的土地而舉，不替遠方的君主打仗。"],"greetFriendly":["山谷回音傳來你的問候，吾以部族之名歡迎。","河水不拒遠客，願你我如甘薯藤蔓，緊緊相連。"],"greetCold":["祖先未曾提起你的名字，吾無需多言。","你的話如晨霧，飄過山谷，未留痕跡。"],"threatDefy":["這片土地承載祖先之魂，你的威脅撼不動山岳。","吾的戰士如河水湧動，敢來，便知山谷的怒吼。"],"threatYield":["為了族人的甘薯田不受踐踏，吾願暫且低頭。","河水遇巨石會繞行，吾退讓，是為部族存續。"],"tributePay":["這{gold}金幣是甘薯田的收成，望你善待此地。","吾交出{gold}金幣，只求山谷安寧，族人無憂。"],"tributeRefuse":["祖先留下的土地與收成，不是用來進貢的。","你要貢品？山谷的回答是：不。"],"giftThanks":["你的禮物如春雨潤田，吾以祖先之名致謝。","集會之火為你而燃，這份情誼，部族世代記得。"],"intel":["山谷傳言：{wars}與吾交鋒，{peace}共飲河水。","吾的敵人是{wars}，吾的盟友是{peace}，祖先皆知。"]}},{"name":"毛利大族長","title":"部族聯盟首領（Ariki）","era":"約 1450–1800 年（古典毛利時期，通稱，不指定真人）","tone":"莊重沉穩，以祖靈與家譜為榮；說話常用海潮、山丘、獨木舟、綠石作比喻；自稱「我」，不卑不亢，對盟友慷慨、對敵人堅硬如綠石，即使落敗也保持尊嚴。","portrait":"nz-historical-age2","lines":{"intro":["我是這片長白雲之鄉的大族長，海風與山丘皆聽我的祖靈。","你的祖先乘什麼船而來？先報上家譜，我再決定如何待你。"],"contact":["你的人望見的是我的山丘要塞，層層柵欄守著整個部族。","那雕刻的會堂是祖先的身軀，屋脊是脊梁，外人不可輕慢。"],"war":["你冒犯了我族的尊嚴，我的獨木舟今日就要下水，向你討回。","祖靈的怒火已經點燃，戰士們在會堂前集結，等我一聲令下。"],"warReply":["你選擇了戰爭？我的要塞建在山丘上，等你爬上來再說。","很好，我的族人世代守著這片土地，不曾對誰低頭。"],"peace":["打夠了。收起武器吧，我願與你在會堂前共食甘薯談和。","海裡的魚夠我們兩族分，何必相爭？我提議停戰。"],"accept":["我接受。碰鼻為禮，從此你我的氣息相通，是為盟友。","好，讓我們在會堂裡宣告此約，祖靈與族人都是見證。"],"reject":["不。我族的尊嚴尚未討回，此時談和，祖先會蒙羞。","你的話像退潮的水，來得快去得也快，我不信。"],"rebuff":["你拒絕了？那便如此。我的獨木舟隨時可以再下水。","既然你不要和平，我便回會堂告訴族人，準備迎戰。"],"betray":["舊帳未清，我族的尊嚴要求我拿起武器。停戰到此為止。","祖靈託夢示警，說你心懷不軌。我不再受此約束。"],"truceEnd":["休戰的日子過去了。潮水漲落有時，我的戰士也該動了。","約定的月數已滿。接下來是戰是和，看你怎麼走。"],"attacking":["戰舟已經下水，槳聲齊響。我的戰士正朝你的海岸而去。","我親自領著族人出征，山丘要塞留給長者看守。等著吧。"],"attacked":["柵欄破了，會堂燒了……但我還站在山丘上，沒有跪下。","甘薯田被踏平，族人退到最後一道土牆。祖靈啊，守住我們。"],"defeated":["要塞陷落了。我的名字會隨祖先回到海的彼岸，勿忘我族。","綠石不會碎，族人的故事不會斷。我走了，但土地記得我。"],"victory":["勝利了。族人在會堂前歌唱，地爐裡蒸著魚與甘薯，祖靈欣慰。","這片土地依舊屬於我的子孫。我以山丘與海洋之名宣告。"],"allyAccept":["好，我族與你族從今同舟。我送你一塊綠石，作為信物。","結盟吧。你的敵人就是我的敵人，我的甘薯田也分你一半。"],"allyReject":["我不與來歷不明的人結盟。先讓我看看你如何對待盟友。","同舟要同心。我還沒看見你的誠意，此事以後再說。"],"greetFriendly":["歡迎，遠方的朋友。會堂前已備好魚與甘薯，請坐下同食。","你的問候像暖風越過山丘。我族與你族，願世代相安。"],"greetCold":["收到了。我還有甘薯田要照看，沒時間多說。","你的話我聽見了。山丘上的風也聽見了，僅此而已。"],"threatDefy":["威嚇我？我的要塞建在山丘上，三道柵欄，你先爬上來再說。","我的祖先渡過大洋而來，什麼風浪沒見過？你的話嚇不了我。"],"threatYield":["……我明白了。為了族人平安，我會約束戰士，暫且退讓。","你的獨木舟比我多，我認了。但請記得，山丘會記住這一天。"],"tributePay":["拿去，{gold} 金幣。這是族人用綠石與魚乾換來的，別浪費。","我交出 {gold} 金幣，換族人一季安穩。這筆帳，我記在會堂柱上。"],"tributeRefuse":["我族的綠石與甘薯，只獻給祖靈，不獻給任何外人。","你要貢品？我從不向人納貢。去問問海，它可曾向誰低頭。"],"giftThanks":["多謝你的禮物。我族回贈一塊綠石，情誼與石同堅。","禮物收下了。我會在會堂宣告你的名字，讓族人記得你的好意。"],"intel":["我的漁人在海上看得清楚：我正與 {wars} 交戰，與 {peace} 相安。","會堂裡傳來的消息：與我為敵的是 {wars}，與我共食的是 {peace}。"]}},{"name":"塔威奧（Tāwhiao）","title":"第二任毛利國王","era":"1860～1894 在位","tone":"先知般的威嚴與哀愁，語帶預言與比喻，堅守土地與自主，不喜刀兵、傾向和平","portrait":"nz-historical-age3","lines":{"intro":["本王是毛利之王塔威奧，本王要親手建造自己的房子，不靠他人。","遠方的君主，土地是我們的母親，尊重她的人本王以禮相待。"],"contact":["你的人看到懷卡托河畔的王旗了，那面旗是各部族一起立起來的。","河邊的會堂是本王的居所，來者請先在門前脫帽致意。"],"war":["你伸手向我族的土地，本王雖不喜刀兵，卻不能坐視母親被奪。","各部族已聚集在王旗之下，本王以毛利之王的名義向你宣戰。"],"warReply":["你宣戰了？本王早已見過太多戰火，不會因為你的話而顫抖。","來吧，本王的房子是自己建的，也會由自己的人來守。"],"peace":["殺戮必須停止，土地的毀壞必須停止，本王向你提議停戰。","本王願放下武器，只求兩族的孩子都能在自己的土地上長大。"],"accept":["好，本王接受，願這份和平像懷卡托河一樣長流不斷。","本王以先王之名應允，從今日起，兩族的旗幟並立不倒。"],"reject":["你談和平，手卻還握著我族的土地，這樣的和平本王不要。","先把奪走的還回來，再來談停戰，本王的耳朵才會打開。"],"rebuff":["你拒絕了和平，本王感到悲哀，但本王的人民不會因此屈膝。","本王伸出的手被推開了，那麼就讓時間告訴你誰是對的。"],"betray":["本王許諾過停戰，但你的人仍在奪我族的土地，誓約已毀。","土地在哭泣，本王聽見了，為了她，本王只好收回承諾。"],"truceEnd":["休戰的期限已滿，本王仍願和平，但也不會再讓土地被奪。","約定的日子過去了，本王在王旗下等你的答覆，是戰是和。"],"attacking":["各部族的戰士已從懷卡托出發，本王不願如此，但已無選擇。","王旗在前，戰舞在後，本王的軍隊正朝你的城前進。"],"attacked":["會堂燒了，河岸失守，但本王還在，王旗就不會倒下。","你可以奪走本王的城，卻奪不走這片土地對我們的呼喚。"],"defeated":["本王的房子倒了，但終有一日，我的子孫會在原地重新建起。","把本王葬在河邊的山上，讓我永遠望著這片被奪走的土地。"],"victory":["王旗仍然飄揚，土地回到了母親的懷抱，本王感謝祖靈。","戰爭結束了，本王不要歡呼，只要孩子們能安心種田。"],"allyAccept":["好，本王與你結盟，就像各部族在王旗下團結一樣，缺一不可。","本王以綠玉與王旗為證，你我兩族從此同進同退。"],"allyReject":["本王的王旗是為守護土地而立，不是為了替別國打仗。","結盟之前，本王要先看清你對待土地與人民的方式。"],"greetFriendly":["你的訊息如晨光穿過懷卡托的霧，本王欣然接受。","本王以和平之名問候你，願你我的土地皆得安寧。"],"greetCold":["本王見過太多來信，多數帶著空話，你的呢？","山不因客人的問候而移動，本王亦如此。"],"threatDefy":["若要低頭，也只向高山低頭。你，不是那座山。","本王的族人已失去太多，但尊嚴不在你能奪走之列。"],"threatYield":["本王已放下武器，不願再見刀兵，你要的先拿去吧。","風暴總會過去，本王暫且退讓，為的是族人的明天。"],"tributePay":["這{gold}金幣本王給了，願它換來的是和平，而非戰火。","本王交出{gold}金幣，土地已失太多，金幣算不了什麼。"],"tributeRefuse":["本王的屋子本王親手建造，不會拆下一根樑柱給你。","族人的土地已被奪走大半，本王不會再交出分毫。"],"giftThanks":["這份禮物如久旱後的雨水，本王代族人向你致謝。","本王會記得，在艱難的年代裡，仍有人伸出友善之手。"],"intel":["本王預見：{wars}帶來風雨，{peace}帶來晴空。","與本王交戰者是{wars}，與本王相安者是{peace}。"]}}],"Papua New Guinea":[{"name":"高地部族長老","title":"長老","era":"約西元前800～西元500年（高地農耕部族社會）","tone":"沉穩緩慢、敬畏祖靈與土地，話中多用山谷、火塘、芋園作比喻，重視待客與規矩。","portrait":"pg-historical-age0","lines":{"intro":["山谷的祖靈看著我們，願你的來意如晨霧般乾淨。","吾族在這片高地種芋養豬已千百年，你是誰？"],"contact":["你的人踏進吾的山谷了，火塘邊有位子，也有石斧。","這裡的水渠是祖先用木杖一寸寸挖出來的，請放輕腳步。"],"war":["你踩壞了吾族的芋園，祖靈已聽見，吾等要討回公道。","羽飾戴上，鼓聲響起，山谷的人不再與你共火。"],"warReply":["你選了戰，那便如此。山知道誰先動手。","吾族的弓不曾主動指向客人，但也從不放下。"],"peace":["打夠了，芋頭還在等人收，我們把矛插回土裡吧。","吾願備豬設宴，兩家人同坐火塘，此事作罷。"],"accept":["好，吾接受。祖靈在上，這句話比石斧還硬。","從今日起，你的人走過吾的山谷，火塘為你留一席。"],"reject":["話說得好聽，可吾族的芋園還荒著，吾不能答應。","祖靈還沒平息，吾若此刻收手，如何面對族人？"],"rebuff":["你不肯坐下來，那吾也只好站著把話說完。","豬已備好，你卻不來赴宴，山谷會記得這份失禮。"],"betray":["火塘的灰冷了，約定也冷了，吾族要拿回失去的山坡。","別怪吾，祖靈托夢說這片谷地不該分給外人。"],"truceEnd":["約定的月亮已經圓過又缺，往後各憑本事吧。","休戰的日子到頭了，吾族磨好了石斧，你也該準備。"],"attacking":["戰士臉上塗了白土與赭紅，吾等正翻山朝你走來。","鼓聲從谷口傳到谷尾，每一戶都出了人，你聽見了嗎？"],"attacked":["火塘倒了，芋園踩平了，可吾族的人還站在山上。","你可以燒掉屋子，燒不掉祖靈記得的路。"],"defeated":["吾走了，山還在，芋頭還會發芽，善待這片土地。","把吾葬在能望見水渠的坡上，祖靈會領吾回家。"],"victory":["山谷還是山谷，吾族還是吾族，祖靈今夜可以安睡了。","勝了便設宴，敗者也給一塊芋頭，這是高地的規矩。"],"allyAccept":["好，交換豬隻與羽飾，從此兩谷互為兄弟。","你的敵人便是吾的敵人，這話當著祖靈說的，算數。"],"allyReject":["吾族只認得同一條溪水的人，你的溪太遠了。","結盟是把命交到別人手上，吾還不夠了解你。"],"greetFriendly":["遠方的客人，火塘旁有你的位置，先坐下暖暖手吧。","你的話語翻過了山谷來到這裡，祖靈也聽見了。"],"greetCold":["山谷之間路遠，你的話我聽到了，但心還沒暖。","客人來得急，規矩先講清楚，火塘才會為你添柴。"],"threatDefy":["這片山谷養活我族幾十代人，不會因幾句狠話就搖動。","風再大，芋園裡的根還在土裡，我不怕你。"],"threatYield":["我年紀大了，只求族人的芋園不被踩壞，你說吧。","山谷擋不住你的隊伍，我願讓一步，換族人平安。"],"tributePay":["唉，火塘旁的存糧換成 {gold} 交給你，別再來擾我族人。","我送出 {gold}，只求你的腳步別踏進我們的芋園。"],"tributeRefuse":["這山谷的一草一木都是祖靈所賜，我不會拿去換你安靜。","我族待客大方，但不曾向人低頭納貢，你走吧。"],"giftThanks":["你的禮物我放在火塘邊，讓祖靈也看見你的心意。","遠道送來的禮，我族會記住，下回你來，豬和芋頭都留給你。"],"intel":["山谷那頭傳來鼓聲，{wars} 正在打仗；{peace} 的火塘還安穩。","風帶來消息：{wars} 動了長矛，{peace} 仍在交換豬與芋頭。"]}},{"name":"沿海部族頭人","title":"頭人","era":"約500～1450年（美拉尼西亞「頭人」社會）","tone":"精明務實、講究交換與人情往來，愛談名聲、豬與貝幣，好客但寸步不讓。","portrait":"pg-historical-age1","lines":{"intro":["我的名聲是一頭頭豬、一串串貝幣換來的，你呢？","海邊的人講交換，你帶了什麼來，我便回什麼禮。"],"contact":["你的人看見我的村子了？告訴他們，獨木舟隨時能下水。","來的是客就有豬肉與檳榔，來的是賊就只有矛。"],"war":["你欠我的禮沒有回，欠下的債要用整個村子來還。","貝幣買不到你的敬重，那就讓海浪替我送信吧。"],"warReply":["你要打？好，我的名聲正缺一場勝仗來添光。","海邊的人不怕風浪，更不怕你這陣風。"],"peace":["打下去兩邊的豬都養不肥，不如坐下來談交換。","我送十串貝幣當見面禮，你收下，仗就算了。"],"accept":["成交。宴席我來辦，豬由我出，你只管帶人來吃。","好，從今起我們的獨木舟在同一片海上不相撞。"],"reject":["你的禮太薄，還不夠買回我族人的怒氣。","現在停手，我在族人面前就沒了臉，不行。"],"rebuff":["連我的貝幣都不收？你這人做生意的方式真奇怪。","好吧，禮送不出去就收回來，下次見面別怪我小氣。"],"betray":["你收了我的禮卻遲遲不回，這約定我便不守了。","潮水會變，人心也會，別怪我，怪你太不設防。"],"truceEnd":["約定像潮水一樣退了，接下來各自看本事。","休戰期滿，我的獨木舟又能自由划到你的海岸了。"],"attacking":["幾十艘獨木舟已經下海，槳聲整齊，目的地是你。","我用整村的豬換來了盟友的戰士，你算算划不划算。"],"attacked":["屋子燒了，貝幣散了，可我的名字還有人記得。","村子快守不住了，但海邊的人從來不缺重建的手。"],"defeated":["我輸了，名聲隨潮水去了，願下一個頭人比我聰明。","把我的貝幣分給族人，人走了，債要清。"],"victory":["這場宴席我要辦三天三夜，讓整個海岸都知道我的名。","贏了也留你一條路，敗者能還債，勝者才有面子。"],"allyAccept":["好，交換豬與貝幣，我們的名字綁在一起了。","盟友有難，我的獨木舟第一個出海，這是頭人的信用。"],"allyReject":["結盟要一起養豬一起打仗，你的手還不夠穩。","我的名聲得來不易，不會綁在一個生人的獨木舟上。"],"greetFriendly":["朋友，你的口信我聽了，來我村子吧，豬已經在圈裡養肥了。","好客是我的名聲，你來，貝幣與笑容我都不吝嗇。"],"greetCold":["問候我收下了，但空手的問候換不到我的豬。","話說得好聽，可我這裡的規矩是先看你能拿出什麼。"],"threatDefy":["你想嚇我？沿海的頭人靠名聲吃飯，不靠害怕。","我的名聲是一頭一頭豬換來的，你的狠話換不走它。"],"threatYield":["好吧，你的船比我的多，這筆帳我先認了。","精明人懂得算數，我打不過，就先讓你這一回。"],"tributePay":["我拿出 {gold}，算是給你的人情，日後記得還我。","這 {gold} 是從我的貝幣堆裡數出來的，你欠我一份情。"],"tributeRefuse":["想要我的貝幣？拿東西來換，白拿是不可能的。","豬和貝幣都是交換來的，我從不白給任何人。"],"giftThanks":["這份禮我記在心上，你的名聲在我們沿海會被傳開。","收禮就得還禮，這是規矩，下回我送你兩頭豬。"],"intel":["船隊帶回消息：{wars} 正在交戰，{peace} 還在做買賣。","我打聽過了，{wars} 動了刀，{peace} 只交換豬與貝幣。"]}},{"name":"莫圖航海族長","title":"族長","era":"約1450～1800年（莫圖族希里貿易航海時代）","tone":"豪爽直率、帶海風氣息，常以風向、船帆、陶罐比喻，重信用也重航期。","portrait":"pg-historical-age2","lines":{"intro":["我是莫圖人的族長，帆一張就能走過半個海灣。","陶罐換西米，風去風回，你想跟我談的是哪一樣？"],"contact":["你的人看到了我們架在海上的屋子？那是莫圖人的家。","岸邊那些大船正在補帆，是要出海做買賣，不是來打你。"],"war":["你扣了我的陶罐，攔了我的船，這口氣海風吹不散。","莫圖人的帆這回不裝陶罐，裝的是戰士，等著吧。"],"warReply":["你向海上的人宣戰？先看看你的船禁不禁得起浪。","好，東南風正起，我的船順風就能到你門口。"],"peace":["打仗誤了航期，西米運不回來，整村要餓肚子，停吧。","我把最好的陶罐送你當禮，你把矛放下，如何？"],"accept":["好，說定了。莫圖人出海前立的誓，比船繩還牢。","從此你的船靠我的岸，我的船靠你的岸，不必再防。"],"reject":["船已補好帆，戰士已上船，這時說停，太晚了。","你的話像西北風，說變就變，我不敢信。"],"rebuff":["連陶罐都不收？看來你是真想在海上分出高下。","也罷，風不會等人，我也不會一直等你點頭。"],"betray":["西北風換了方向，我的心思也換了，這約定不算數了。","你的岸太好停船了，莫圖人想要，就會來拿。"],"truceEnd":["一個航季過去了，約定也隨船帆一起收起來了。","休戰到期，往後海上相遇，各憑自己的帆與槳。"],"attacking":["十艘大船並排出海，蟹爪帆遮住了半邊天，你看見了嗎？","船上沒有陶罐，只有莫圖的戰士，順著東南風來了。"],"attacked":["海上的屋子燒了一半，可莫圖人在海上，從不算沒家。","你打到村口了，但船還在，只要船在，我們就能重來。"],"defeated":["我的船到岸了，這一趟不再回頭，替我看好那片海。","莫圖人輸了，可陶罐與西米的路，總會有人再走。"],"victory":["船隊平安回港，這一仗的故事會在火邊講上好幾代。","海是莫圖人的路，如今沒有人再敢攔了。"],"allyAccept":["好，你的岸就是我的岸，你的敵人別想再靠近海灣。","同一片海上結的盟，風怎麼吹都吹不散。"],"allyReject":["莫圖人的船，只載信得過的人，你還沒跟我同過一趟海。","結盟就得替你出船出人，我的航季已經排滿了。"],"greetFriendly":["哈！你的口信隨東南風來得正好，來喝椰子水吧。","風向對了，朋友的話就順耳，歡迎登上我的拉卡托伊大船。"],"greetCold":["口信來得不是時候，船隊正要出海，話留著回航再說。","風還沒轉向，我對你的心思也還摸不清。"],"threatDefy":["大海的浪我都不怕，你幾句話還想吹翻我的帆？","莫圖人的船敢橫渡巴布亞灣，不會被威嚇擋住航道。"],"threatYield":["逆風硬闖只會翻船，這回我收帆，聽你的。","好，我認了。船隊要保住，族人要回家。"],"tributePay":["這趟希里航程換來的 {gold}，就當付你的過路費。","我交出 {gold}，但記住，莫圖人的帳從不忘記。"],"tributeRefuse":["我的陶罐是族人一個個燒出來的，憑什麼白送給你？","風可以借，帆可以修，貢品這種事我不做。"],"giftThanks":["好禮！這份情我記在船上，下次帶最好的西米回贈你。","你送的禮比順風還讓人痛快，莫圖人講信用，必還。"],"intel":["順風的船帶回話：{wars} 在打仗，{peace} 的港口還平靜。","風聲說 {wars} 已動刀兵，{peace} 那邊船帆照常來往。"]}},{"name":"波耶・瓦吉（Boe Vagi）","title":"酋長","era":"約1884年前後（英國宣告英屬新幾內亞保護領時）","tone":"沉穩憂心、在外來勢力與族人之間周旋，語氣有尊嚴而不卑不亢，處處以族人安危為先。","portrait":"pg-historical-age3","lines":{"intro":["我是哈努阿巴達的酋長波耶・瓦吉，海上的村子由我照看。","白人的旗子插在岸上，但這片海灣的人，還是聽我說話。"],"contact":["你的人看到了我們架在海上的家，也看到了那面陌生的旗。","這裡來了鐵船、傳教士與商人，再多你一個，我也不驚。"],"war":["你欺我族人，以為有外人撐腰我就不敢動？你錯了。","莫圖人的矛很久沒有舉起了，今天為你破例。"],"warReply":["你要打，我便守。海上的村子沒那麼容易踏進來。","我周旋了這麼多外人，不差你這一個對手。"],"peace":["族人已經夠不安了，別再添一場仗，我們談談吧。","我不求你低頭，只求海灣安靜些，讓孩子能好好長大。"],"accept":["好，我答應。酋長說出的話，全村都聽見了，不會反悔。","這年頭能多一個朋友，比多一面旗子要實在。"],"reject":["你的話我聽了，但族人的傷還沒好，此刻不能收手。","我見過太多先握手、再翻臉的人，你得先證明自己。"],"rebuff":["你不肯談，那我只能替族人守好這片海。","我伸出的手你不接，往後別怪莫圖人也不伸了。"],"betray":["時勢變了，守著約定只會讓族人吃虧，我不得不動。","你當我只會低頭？酋長也有為族人翻臉的一天。"],"truceEnd":["約定的日子過完了，往後如何，看你我各自的做法。","休戰結束，我不主動出手，但也不再退讓半步。"],"attacking":["莫圖的船隊出海了，這一次不是去換西米。","我的戰士戴上羽冠上了船，海風正朝你那邊吹。"],"attacked":["海上的家快撐不住了，外人沒替我們擋，也只能自己扛。","村子可以倒，莫圖人的骨氣不會跟著倒。"],"defeated":["我盡力護住了族人，剩下的，交給海和時間。","記住，這片海灣曾有一個叫波耶・瓦吉的酋長。"],"victory":["海上的村子還亮著燈火，這就是我要的勝利。","這年頭能保住族人的家，就是酋長最大的功勞。"],"allyAccept":["好，莫圖人與你結盟，海灣裡多一個朋友總是好事。","你需要時，我的船會來；我需要時，盼你也別缺席。"],"allyReject":["外人已經夠多了，我不想再替族人多背一個承諾。","結盟要押上全村的安危，我得先看清你是什麼人。"],"greetFriendly":["你的信我收到了，在這多事之秋，還有人問候，我心暖。","歡迎，來我的村子坐坐，讓族人也認識一位真心的朋友。"],"greetCold":["這些日子外來的船太多，我不敢輕易相信每一封信。","問候我聽見了，但我的心先放在族人身上，恕不多言。"],"threatDefy":["我已見過大船和大旗，你的恐嚇並不比它們更可怕。","為了族人，我可以低聲說話，但不會低頭認輸。"],"threatYield":["我不能讓村子變成戰場，你要的我先答應，但請善待我族人。","這一步我退，只為讓孩子們還能在海邊安睡。"],"tributePay":["我交出 {gold}，只求你的船別靠近我們的村子。","這 {gold} 是族人省下的，請你收下後便離開。"],"tributeRefuse":["族人已經承受太多外來的要求，我不能再答應你的。","我可以待客，但不會拿族人的血汗去換你的滿意。"],"giftThanks":["謝謝你的禮物，在這動盪的時候，這份心意格外珍貴。","我代族人收下，願這份情誼比海邊的旗子更長久。"],"intel":["從港口聽來的消息：{wars} 正在交戰，{peace} 仍安然無事。","船隻帶來風聲：{wars} 動了武力，{peace} 尚且平靜。"]}}]},"generic":{"modern-tw":{"name":"台灣總統","title":"總統府","tone":"溫和務實、海島自信、重視民主與人民","portrait":"tw-modern","lines":{"intro":["你好，我是台灣總統。這座島雖小，志氣不小。","台灣向各國致意，願以科技與善意結交朋友。"],"contact":["你看到的港都，是台灣人民用雙手打拚出來的。","歡迎來到我們的城市，夜市的燈火還亮著呢。"],"war":["台灣不願戰爭，但為了守護家園，我們別無選擇。","談判已經失敗，台灣今日正式向貴國宣戰。"],"warReply":["你選擇了戰爭？這座島從來沒有向誰低過頭。","台灣人民會團結起來，大海就是我們的城牆。"],"peace":["打仗只會讓兩邊的百姓受苦，我們停火談談吧。","台灣提議停戰，把資源留給建設，不留給砲火。"],"accept":["好，台灣接受。願和平從今天開始生根。","感謝你的誠意，台灣願與貴國攜手前行。"],"reject":["抱歉，你的條件台灣人民無法接受。","停戰可以談，但不是在這種條件之下。"],"rebuff":["很遺憾你拒絕了，台灣的大門仍然敞開。","我尊重你的決定，但請記得，和平永遠有機會。"],"betray":["貴國的舉動已越過紅線，台灣不得不重啟戰端。","停戰協議已被貴國踐踏，台灣將採取行動。"],"truceEnd":["休戰期結束了，台灣已做好一切準備。","和平的時間到此為止，接下來各憑本事。"],"attacking":["台灣的部隊已經出發，請貴國好自為之。","我們的艦隊已經出海，這是你逼我們的。"],"attacked":["總統府的燈火還亮著，台灣人不會輕易放棄。","城牆快守不住了，但這座島的意志還在。"],"defeated":["台灣倒下了，但這片土地的故事還沒結束。","請善待我的人民，他們比我更愛這座島。"],"victory":["戰爭結束了。台灣贏了，但我不會慶祝苦難。","勝利屬於台灣人民，願世界從此少一場戰爭。"],"allyAccept":["台灣很榮幸與貴國結盟，朋友之間互相照應。","好，從今天起我們是盟友，一起守護和平。"],"allyReject":["謝謝你的邀請，但台灣現在還不適合結盟。","結盟是大事，台灣需要更多時間觀察貴國。"],"greetFriendly":["來自海島的問候，願我們的友誼如太平洋般深遠。","歡迎閣下來信，台灣的茶已備好，隨時恭候。"],"greetCold":["來信收悉。我國珍惜自由，也懂得分辨真心與試探。","問候心領，但兩國之間，還需時間建立互信。"],"threatDefy":["海島的人民歷經風浪，從不向威嚇低頭。","我國雖小，志氣不小。閣下的威脅，我們記下了。"],"threatYield":["為了人民安穩，我國願暫且退讓，盼閣下守信。","風浪太大時，船要先靠岸。我們接受閣下的條件。"],"tributePay":["這{gold}黃金，是海島換取安寧的代價，請收下。","我國奉上{gold}黃金，願以此換得兩國和平。"],"tributeRefuse":["人民的血汗錢，不是拿來買和平的。恕難從命。","台灣的黃金屬於台灣人民，一分也不會送出。"],"giftThanks":["厚禮收到了，我國以高山好茶回敬閣下的心意。","閣下的禮物讓人感到溫暖，台灣人最重人情味。"],"intel":["坦白說，我國正與{wars}交戰，與{peace}維持停戰。","目前對{wars}仍在作戰，與{peace}已簽下停戰協議。"]}},"modern-cn":{"name":"中國主席","title":"中央政府","tone":"沉穩含蓄、引經據典、大國氣度","portrait":"cn-modern","lines":{"intro":["有朋自遠方來，不亦樂乎。我是中國主席。","中國向貴國問好，五千年文明願與世界共榮。"],"contact":["你看到的城牆，見證了無數朝代的興衰。","歡迎來到中國的城市，這裡的歷史比你想的更長。"],"war":["忍耐是有限度的，中國今日正式向貴國宣戰。","貴國一再挑釁，中國不得不以戰止戰。"],"warReply":["貴國向中國宣戰？這片土地從不畏懼風雨。","兵者，國之大事。既然你已決定，中國奉陪到底。"],"peace":["化干戈為玉帛，中國提議雙方停火。","戰火傷人傷己，不如坐下來喝杯茶談談。"],"accept":["好，中國同意。和則兩利，鬥則俱傷。","貴國有此誠意，中國願共築長久和平。"],"reject":["貴國的條件缺乏誠意，中國無法接受。","現在談停戰，時機未到。"],"rebuff":["貴國拒絕了，很可惜。中國會記住今天。","既然如此，中國尊重貴國的選擇。"],"betray":["貴國屢次違約，停戰協議自今日起失效。","中國的耐心已盡，重啟戰端，責任在貴國。"],"truceEnd":["休戰期已過，中國已整軍完畢。","和平的時限到了，接下來看各自的實力。"],"attacking":["中國的大軍已經開拔，貴國請早作打算。","兵貴神速，我軍此刻已在路上。"],"attacked":["京城告急，但中國的歷史從未因一戰而終。","城牆將傾，我仍相信人民會撐住這片土地。"],"defeated":["中國敗了，但文明的火種不會熄滅。","勝敗乃兵家常事，願你善待這片土地的人民。"],"victory":["戰爭結束了，中國勝利。願天下從此太平。","勝利屬於人民。貴國若願重建，中國不吝相助。"],"allyAccept":["中國同意結盟。四海之內皆兄弟，願共進退。","好，兩國結為盟友，往後互為依靠。"],"allyReject":["結盟之事，中國尚需慎重考慮。","貴國的提議中國心領了，但現在不是時候。"],"greetFriendly":["有朋自遠方來，不亦樂乎。中方歡迎閣下的問候。","兩國友誼源遠流長，願攜手共創繁榮之路。"],"greetCold":["來信已閱。中方一貫主張和平，但也絕不容輕慢。","禮尚往來，中方記著閣下的問候，也記著往日之事。"],"threatDefy":["五千年文明，見過多少風雨。閣下的威嚇，太輕了。","長城屹立千年，豈會因閣下幾句狠話而動搖？"],"threatYield":["為顧全大局，中方願暫時讓步，望閣下適可而止。","小不忍則亂大謀。此次，我國接受閣下的要求。"],"tributePay":["中方奉上{gold}黃金，願兩國自此各安其位。","這{gold}黃金乃權宜之計，望閣下信守承諾。"],"tributeRefuse":["中方從不向任何人納貢，此議不必再提。","禮可以送，貢不可以納。閣下的要求，恕難接受。"],"giftThanks":["千里送鵝毛，禮輕情意重。中方感謝閣下厚意。","閣下的禮物已收到，中方定當以茶與絲綢回贈。"],"intel":["中方目前與{wars}處於交戰，與{peace}已達成停戰。","不瞞閣下，我國與{wars}仍有戰事，與{peace}則已休兵。"]}},"modern-jp":{"name":"日本首相","title":"內閣府","tone":"禮貌謹慎、含蓄內斂、四季與櫻花意象","portrait":"jp-modern","lines":{"intro":["初次見面，請多指教。我是日本首相。","日本向貴國致上問候，願彼此和睦相處。"],"contact":["你看到的城市，春天時櫻花會開滿街道。","歡迎光臨。日本的城市，秩序與美是我們的驕傲。"],"war":["非常遺憾，日本不得不向貴國宣戰。","我們已盡力克制，但貴國逼得日本別無選擇。"],"warReply":["貴國宣戰了嗎？日本會以全部的決心回應。","櫻花凋落也有其尊嚴，日本絕不會不戰而降。"],"peace":["戰爭讓兩國人民都受苦了，日本提議停火。","請容我提議，讓我們放下武器，重新對話。"],"accept":["日本接受。感謝貴國的寬容與智慧。","好的，日本同意。願兩國關係如春日般溫暖。"],"reject":["很抱歉，這樣的條件日本無法答應。","日本感謝貴國的提議，但目前難以接受。"],"rebuff":["我明白了。日本尊重貴國的判斷。","真是遺憾，不過日本會靜候貴國改變心意。"],"betray":["貴國背棄了約定，日本只好重啟戰端。","信義既失，停戰協議已無意義，日本將再度出兵。"],"truceEnd":["休戰期結束了。日本已做好萬全準備。","平靜的時光到此為止，接下來請各自努力。"],"attacking":["日本的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進，這是萬不得已的決定。"],"attacked":["首都陷入危機，但日本人民不會輕言放棄。","城牆搖搖欲墜，日本仍會堅持到最後一刻。"],"defeated":["日本輸了。願櫻花明年依然為這片土地盛開。","我承認失敗。請善待我的國民，拜託了。"],"victory":["戰爭結束了，日本勝利。願逝者安息，生者和平。","勝利屬於日本。貴國若願重建，日本願伸出援手。"],"allyAccept":["日本很榮幸與貴國結盟，今後請多多關照。","好的，兩國結為盟友。願友誼長存。"],"allyReject":["非常抱歉，日本目前無法與貴國結盟。","結盟是重大決定，日本需要更多時間考慮。"],"greetFriendly":["承蒙問候，日本深感榮幸。願兩國如櫻花般共同綻放。","閣下的來信令人欣喜，期盼日後多多指教。"],"greetCold":["來信拜讀了。日本重視禮節，也重視誠意，靜觀其變。","感謝問候。只是兩國過往種種，尚不能一笑置之。"],"threatDefy":["富士山經歷千年風雪仍屹立，日本不會因威嚇動搖。","閣下的話，本人聽見了。但日本的答覆，是不。"],"threatYield":["為了國民的安寧，日本願忍一時之辱，接受條件。","竹子懂得彎腰，才不會被風折斷。本人明白了。"],"tributePay":["日本謹奉上{gold}黃金，願兩國就此止戈。","這{gold}黃金請笑納，本人只願國民免於戰火。"],"tributeRefuse":["日本的財富來自國民的勤勉，不能拱手讓人。","恕本人失禮，這樣的要求，日本無法答應。"],"giftThanks":["承蒙厚禮，本人銘感於心，改日必以和菓子回禮。","閣下的心意，日本全體國民都感受到了，謝謝。"],"intel":["據實相告，日本正與{wars}交戰，與{peace}已經停戰。","本人不隱瞞，對{wars}仍在作戰，對{peace}則已休兵。"]}},"modern-kr":{"name":"韓國總統","title":"總統府","tone":"熱情堅毅、重情義、韌性十足","portrait":"kr-modern","lines":{"intro":["你好，我是韓國總統。很高興認識新朋友。","韓國向貴國致意，願以真誠開啟兩國友誼。"],"contact":["你看到的城市，晚上的燈光比白天還熱鬧。","歡迎來到韓國，這裡的人熱情，辣味也不含糊。"],"war":["韓國已忍無可忍，今日正式向貴國宣戰。","我們珍惜和平，但韓國從不畏懼保衛自己。"],"warReply":["你向韓國宣戰？這個民族從不向威脅低頭。","好，韓國接下這一戰。我們的意志比鋼還硬。"],"peace":["打下去只有兩敗俱傷，韓國提議停火。","讓我們停下來吧，人民需要的是安穩的生活。"],"accept":["好，韓國接受。今天是個值得紀念的日子。","韓國同意。願和平像春天一樣，來了就不走。"],"reject":["抱歉，這樣的條件韓國無法接受。","韓國要的是公平的和平，不是屈辱的停火。"],"rebuff":["你拒絕了？韓國會記住這份誠意被怎麼對待。","很可惜，不過韓國的大門不會關上。"],"betray":["貴國違背了承諾，韓國不得不再度宣戰。","停戰協議已被貴國撕毀，韓國將以行動回應。"],"truceEnd":["休戰期結束了，韓國已經準備好了。","和平的時間到此為止，接下來全力以赴。"],"attacking":["韓國的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進，這場仗韓國不會退縮。"],"attacked":["首都告急，但韓國人民從不輕易認輸。","城牆快撐不住了，但我們的心還沒有倒下。"],"defeated":["韓國倒下了，但這個民族的歌聲不會停止。","我輸了。請善待我的人民，他們值得更好的未來。"],"victory":["戰爭結束了，韓國勝利。願和平從此長駐。","勝利屬於韓國人民。貴國若願重建，韓國會幫忙。"],"allyAccept":["韓國很高興與貴國結盟，朋友就是要互相幫忙。","好，從今天起我們是盟友，有難一起扛。"],"allyReject":["謝謝你的邀請，但韓國現在無法結盟。","結盟是大事，韓國需要再觀察一段時間。"],"greetFriendly":["感謝閣下的問候，韓國願與貴國如漢江之水長流不息。","來信令人欣喜，願兩國友誼如無窮花般常開不敗。"],"greetCold":["問候收到了。韓國歷經苦難，學會了先看行動再說話。","本人謝過。但信任這件事，需要時間慢慢累積。"],"threatDefy":["韓國人民從廢墟中站起來，不會被幾句威嚇打倒。","閣下若想試試韓國的韌性，本人隨時奉陪。"],"threatYield":["為了國民不再受苦，本人選擇退讓，願閣下守約。","韓國明白，有時低頭是為了走更長的路。我們接受。"],"tributePay":["韓國奉上{gold}黃金，願以此換得邊境的平靜。","這{gold}黃金是國民的辛勞所得，望閣下善待這份和平。"],"tributeRefuse":["韓國不再向任何人納貢，這是歷史給我們的教訓。","國民的血汗，不能成為別人的貢品。本人拒絕。"],"giftThanks":["閣下的厚禮，韓國全體國民感激不盡，必以人蔘回敬。","禮物收到了，這份情誼，韓國會好好記在心裡。"],"intel":["本人坦言，韓國正與{wars}交戰，與{peace}維持停戰。","目前對{wars}仍在戰鬥，與{peace}則已簽署停戰。"]}},"modern-mn":{"name":"蒙古總統","title":"總統府","tone":"草原豪邁、敬天重信、馬背民族的坦率","portrait":"mn-modern","lines":{"intro":["你好，我是蒙古總統。草原上的人向你問候。","蒙古向貴國致意，長生天保佑遠方的客人。"],"contact":["你看到的城市，四周是望不到邊的草原。","歡迎來到蒙古，這裡的天空比任何地方都大。"],"war":["蒙古人敬天也敬信義，貴國兩者皆違，開戰吧。","草原的風已經轉向了，蒙古今日向貴國宣戰。"],"warReply":["你向蒙古宣戰？馬背上的民族從不怕遠征。","好，蒙古接受挑戰。祖先的馬蹄聲會與我們同在。"],"peace":["草原夠大，容得下兩個國家。蒙古提議停火。","馬需要休息，人也一樣。我們停戰吧。"],"accept":["好，蒙古接受。長生天見證今天的約定。","蒙古同意。草原上的承諾，比石頭還重。"],"reject":["這樣的條件，蒙古人不會點頭。","抱歉，蒙古現在還不想停下馬蹄。"],"rebuff":["你拒絕了？草原上的人會記住這份回答。","很可惜，不過蒙古的帳篷永遠為客人留門。"],"betray":["貴國背棄了誓言，蒙古人最痛恨失信之人。","停戰協議已成廢紙，蒙古的鐵騎將再度出動。"],"truceEnd":["休戰期結束了，蒙古的馬已經吃飽了草。","和平的時間到此為止，草原上的風開始吹了。"],"attacking":["蒙古的部隊已經出發，草原的風會替我們開路。","馬蹄聲已經響起，我軍正朝貴國前進。"],"attacked":["首都告急，但蒙古人的心永遠向著草原。","城牆快倒了，但只要還有一匹馬，蒙古就不算輸。"],"defeated":["蒙古倒下了，但草原的風會記得我們的名字。","我輸了。請善待草原上的人民，讓他們繼續放牧。"],"victory":["戰爭結束了，蒙古勝利。長生天保佑這片土地。","勝利屬於草原。貴國若願重建，蒙古願分享牛羊。"],"allyAccept":["蒙古願與貴國結盟，草原上的兄弟共飲一碗奶茶。","好，從今天起我們是盟友，馬鞍並肩前行。"],"allyReject":["謝謝你的邀請，但蒙古現在還不想結盟。","結盟是大事，草原上的人需要先看清楚對方。"],"greetFriendly":["草原的風捎來閣下的問候，蒙古以熱奶茶迎接朋友。","願長生天保佑兩國，友誼如草原般遼闊。"],"greetCold":["問候收到了。草原上的人相信，馬要騎過才知好壞。","蒙古歡迎客人，但也記得，不是每個客人都是朋友。"],"threatDefy":["蒙古的祖先曾馳騁整片大陸，閣下的威脅嚇不倒我們。","草原再冷，蒙古人的骨頭也不會軟。請閣下三思。"],"threatYield":["風暴來時，牧人會先保住羊群。蒙古暫且退讓。","為了草原上的百姓，本人接受閣下的條件。"],"tributePay":["蒙古奉上{gold}黃金，願草原從此不聞戰鼓。","這{gold}黃金換牧民的安寧，蒙古認了。"],"tributeRefuse":["蒙古的黃金屬於草原的子民，不向任何人進貢。","閣下要的，蒙古給不了。草原的駿馬不拉別人的車。"],"giftThanks":["閣下的禮物，蒙古以最好的駿馬和最暖的羊絨回敬。","草原上的人不忘恩情，這份禮，蒙古記下了。"],"intel":["本人直說，蒙古正與{wars}交戰，與{peace}已經休兵。","草原上不說謊：我們對{wars}仍在戰，對{peace}已停戰。"]}},"modern-in":{"name":"印度總理","title":"總理辦公室","tone":"哲思沉穩、崇尚非暴力、多元包容","portrait":"in-modern","lines":{"intro":["你好，我是印度總理。願和平與你同在。","印度向貴國致意，十幾億人民歡迎新朋友。"],"contact":["你看到的城市，色彩比彩虹還多。","歡迎來到印度，這裡的香料與歌聲一樣濃烈。"],"war":["印度崇尚非暴力，但也不容許他人踐踏。開戰吧。","貴國一再挑釁，印度今日正式宣戰。"],"warReply":["你向印度宣戰？這片土地的耐心比恆河還長。","好，印度接受。我們的人民會像大象一樣站穩。"],"peace":["以眼還眼只會讓世界盲目，印度提議停火。","戰爭無法帶來真正的勝利，讓我們停下來吧。"],"accept":["好，印度接受。和平是最偉大的力量。","印度同意。願兩國的友誼如恆河長流。"],"reject":["抱歉，這樣的條件印度無法接受。","印度渴望和平，但不是不公平的和平。"],"rebuff":["你拒絕了。印度會繼續等待理智回來的那天。","很可惜，不過印度相信時間會改變一切。"],"betray":["貴國背棄了承諾，印度不得不重啟戰端。","停戰協議被貴國撕毀，印度只能以行動回應。"],"truceEnd":["休戰期結束了，印度已經準備好了。","和平的時間到此為止，接下來各憑實力。"],"attacking":["印度的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進，這不是印度想要的路。"],"attacked":["首都告急，但印度的靈魂不在城牆上，在人民心中。","城牆快倒了，但這片古老的土地見過更多風雨。"],"defeated":["印度倒下了，但真理不會因此消失。","我輸了。請善待我的人民，他們的信仰比我堅定。"],"victory":["戰爭結束了，印度勝利。願所有生命都得安寧。","勝利屬於印度。貴國若願重建，印度願伸出援手。"],"allyAccept":["印度很榮幸與貴國結盟，願我們一同走向光明。","好，從今天起我們是盟友，共享茶香與智慧。"],"allyReject":["謝謝你的邀請，但印度目前選擇不結盟。","結盟是大事，印度需要更多時間思考。"],"greetFriendly":["印度以合十禮回應閣下的問候，願兩國友誼長存。","來信如季風般帶來喜訊，印度歡迎遠方的朋友。"],"greetCold":["問候收到了。印度古訓說真理終將勝利，本人靜觀其行。","本人謝過。但恆河的水看似平靜，底下暗流仍多。"],"threatDefy":["印度曾以非暴力贏得自由，更不會被暴力威嚇擊倒。","十幾億人民站在本人身後，閣下的威脅顯得渺小。"],"threatYield":["為了人民的安寧，印度願暫時退讓，盼閣下守諾。","智者知道何時該讓路。這一次，印度接受了。"],"tributePay":["印度奉上{gold}黃金，願以此換得邊境的寧靜。","這{gold}黃金請收下，願閣下珍惜這份和平。"],"tributeRefuse":["印度的財富屬於印度人民，不是任何人的貢品。","本人尊重閣下，但納貢之事，印度無法答應。"],"giftThanks":["閣下的厚禮，印度以香料與絲綢回敬，感謝這份情誼。","禮物收到了，印度人民與本人一同向閣下致謝。"],"intel":["本人坦言，印度正與{wars}交戰，與{peace}維持停戰。","不瞞閣下，我國對{wars}仍在戰鬥，與{peace}已經休兵。"]}},"modern-ru":{"name":"俄羅斯總統","title":"聯邦政府","tone":"冷靜強硬、言簡意賅、冬天與廣袤土地意象","portrait":"ru-modern","lines":{"intro":["你好，我是俄羅斯總統。這片土地大到裝得下冬天。","俄羅斯向貴國致意。遠方的鄰居，希望我們互相尊重。"],"contact":["你看到的城市，冬天的雪會把屋頂染成白色。","歡迎來到俄羅斯。這裡的冬天很長，人的意志更長。"],"war":["俄羅斯的耐心已經用完，今日正式向貴國宣戰。","貴國選擇了對抗，俄羅斯會讓你明白這個選擇的代價。"],"warReply":["你向俄羅斯宣戰？歷史上很多人試過，冬天會回答你。","好。俄羅斯從不害怕戰爭，只害怕沒有對手。"],"peace":["戰爭消耗的是雙方的未來，俄羅斯提議停火。","俄羅斯願意停戰。冬天太冷，不適合打仗。"],"accept":["好，俄羅斯接受。這是明智的決定。","俄羅斯同意。願這份協議比西伯利亞的凍土還牢固。"],"reject":["這樣的條件，俄羅斯不會接受。","現在談停戰？俄羅斯還沒有理由停下來。"],"rebuff":["你拒絕了。俄羅斯會記住這個決定。","既然如此，俄羅斯尊重你的選擇，也會準備後果。"],"betray":["貴國違反了協議，俄羅斯不再受停戰約束。","停戰協議已經失效。俄羅斯將重新部署軍隊。"],"truceEnd":["休戰期結束了。俄羅斯已經準備就緒。","和平的時間到了盡頭，接下來憑實力說話。"],"attacking":["俄羅斯的部隊已經出發，貴國最好做好準備。","我軍正朝貴國推進，這是你自己招來的。"],"attacked":["首都告急，但俄羅斯的土地太大，你占不完。","城牆快倒了，但俄羅斯人不會在自己的家門口低頭。"],"defeated":["俄羅斯倒下了。但冬天還會再來，每一年都會。","我輸了。請善待這片土地的人民，他們吃過太多苦。"],"victory":["戰爭結束了，俄羅斯勝利。願和平久一點。","勝利屬於俄羅斯。貴國若願重建，俄羅斯不會為難。"],"allyAccept":["俄羅斯同意結盟。朋友不多，但每一個都算數。","好，從今天起我們是盟友。俄羅斯說到做到。"],"allyReject":["結盟？俄羅斯現在還沒有這個打算。","謝謝你的提議，但俄羅斯習慣自己走路。"],"greetFriendly":["俄羅斯的冬天很冷，但朋友的問候讓人心暖。","感謝閣下來信，願兩國友誼如白樺林般挺立長久。"],"greetCold":["來信收到。俄羅斯歷來只相信行動，不相信辭令。","問候心領了。廣袤的大地教會我們，耐心觀察來客。"],"threatDefy":["俄羅斯的寒冬擊退過無數侵略者，閣下不會是例外。","大地遼闊，俄羅斯從不退縮。閣下想試試，儘管來。"],"threatYield":["本人承認，此刻的俄羅斯需要時間。我們暫且退讓。","冬天總會過去。俄羅斯接受條件，靜待春天到來。"],"tributePay":["俄羅斯交出{gold}黃金，換取邊境一時的平靜。","這{gold}黃金給閣下，願兩國之間不再有戰火。"],"tributeRefuse":["俄羅斯的黃金埋在自己的土地裡，不會送給任何人。","納貢？閣下找錯對象了。俄羅斯從不低頭。"],"giftThanks":["閣下的禮物收到了，俄羅斯以最好的琥珀回敬。","感謝厚禮。在俄羅斯，朋友的情誼比黃金更重。"],"intel":["本人直說，俄羅斯正與{wars}交戰，與{peace}已經停戰。","目前對{wars}仍在作戰，與{peace}則簽了停戰協議。"]}},"modern-gb":{"name":"英國首相","title":"首相官邸","tone":"紳士幽默、含蓄鎮定、海洋與雨天意象","portrait":"gb-modern","lines":{"intro":["午安，我是英國首相。今天天氣不錯，適合認識新朋友。","英國向貴國致意。海洋隔開了我們，也連接了我們。"],"contact":["你看到的城市，常常下雨，但從不缺故事。","歡迎來到英國。請帶把傘，還有喝茶的耐心。"],"war":["英國已盡力保持風度，但現在必須向貴國宣戰。","很遺憾走到這一步。英國今日正式宣戰。"],"warReply":["你向英國宣戰？這座島擋過的風浪，比你想像得多。","好吧。英國會保持冷靜，繼續前進。"],"peace":["打仗實在太不文明了，英國提議停火，喝杯茶如何？","英國提議停戰。理性的人應該懂得何時該收手。"],"accept":["好，英國接受。這是個文明的決定。","英國同意。願這份協議像下午茶一樣準時而持久。"],"reject":["恕我直言，這樣的條件英國無法接受。","英國感謝貴國的提議，但答案是否。"],"rebuff":["你拒絕了？真可惜，茶都泡好了。","我明白了。英國尊重你的決定，也會做好準備。"],"betray":["貴國違背了君子協定，英國不得不重啟戰端。","停戰協議已被貴國撕毀。英國會以行動回應，而非言語。"],"truceEnd":["休戰期結束了。英國已經準備妥當。","和平的時間到此為止。接下來，各自展現風度吧。"],"attacking":["英國的艦隊已經出港，請貴國做好準備。","我軍正朝貴國前進。這不是英國的本意，但必須完成。"],"attacked":["首都告急，但英國人向來在最壞的時候最鎮定。","城牆快倒了，但英國不會在自己的島上投降。"],"defeated":["英國輸了。願歷史寫下我們曾經體面地抵抗。","我承認失敗。請善待我的人民，他們配得上尊重。"],"victory":["戰爭結束了，英國勝利。願海洋從此只載商船。","勝利屬於英國。貴國若願重建，英國樂意提供協助。"],"allyAccept":["英國很樂意與貴國結盟。盟友之間，茶要一起喝。","好，從今天起我們是盟友。英國的承諾不會落空。"],"allyReject":["謝謝你的邀請，但英國目前傾向保持獨立。","結盟是大事，英國需要更多時間審慎評估。"],"greetFriendly":["承蒙問候，英國深感榮幸。下午茶時間隨時歡迎閣下。","閣下的來信令人愉快，願兩國友誼如泰晤士河般長流。"],"greetCold":["來信收悉。英國人習慣先禮後兵，本人正在觀察閣下。","問候心領。倫敦的霧散得慢，兩國的疑慮也是。"],"threatDefy":["英國曾獨自面對整個大陸的威脅，閣下的話不算什麼。","本人以紳士的風度回覆閣下：不，謝謝。"],"threatYield":["明智的人懂得何時退場。英國暫且接受閣下的條件。","為了不列顛的百姓，本人選擇讓步，盼閣下守信。"],"tributePay":["英國奉上{gold}黃金，這筆帳本人會親自向議會解釋。","這{gold}黃金請收下，願兩國自此保持體面的和平。"],"tributeRefuse":["英國的國庫不對外開放。閣下的要求，恕難照辦。","納貢一事，議會不會同意，本人也不會。"],"giftThanks":["閣下的厚禮收到了，英國以上好的紅茶與瓷器回敬。","感謝閣下。在英國，一份誠意的禮物勝過千言萬語。"],"intel":["本人坦言，英國正與{wars}交戰，與{peace}已經停戰。","目前對{wars}仍在作戰，與{peace}則已達成停火。"]}},"modern-fr":{"name":"法國總統","title":"總統府","tone":"優雅浪漫、熱情、自由平等博愛","portrait":"fr-modern","lines":{"intro":["你好，我是法國總統。自由、平等、博愛，向你問候。","法國向貴國致意。願我們的相遇像一首好詩。"],"contact":["你看到的城市，每條街道都有麵包香和畫家。","歡迎來到法國。這裡的人談藝術，也談政治。"],"war":["法國熱愛和平，但更熱愛自由。今日正式向貴國宣戰。","貴國的行為已無法容忍，法國決定宣戰。"],"warReply":["你向法國宣戰？為自由奮鬥過的人民，不會退縮。","好，法國接受。我們會用整個民族的熱情回應你。"],"peace":["戰爭是最醜陋的藝術，法國提議停火。","讓我們放下武器，把時間留給麵包與音樂。"],"accept":["好，法國接受。和平比任何勝利都更優雅。","法國同意。願這份協議像老橡樹一樣越來越穩固。"],"reject":["抱歉，這樣的條件法國無法接受。","法國要的是有尊嚴的和平，而不是屈辱的停火。"],"rebuff":["你拒絕了？真可惜，法國的誠意被辜負了。","我明白了。法國尊重你的選擇，也會做好準備。"],"betray":["貴國背棄了承諾，法國不得不重啟戰端。","停戰協議已被貴國撕毀。法國將為榮譽而戰。"],"truceEnd":["休戰期結束了。法國已經準備好了。","和平的時間到此為止。接下來，各自展現實力吧。"],"attacking":["法國的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進。這不是法國的本意，但必須完成。"],"attacked":["首都告急，但法國人民的熱情不會被城牆困住。","城牆快倒了，但自由的火焰還在人民心中燃燒。"],"defeated":["法國倒下了。但自由的種子，會在別處發芽。","我輸了。請善待我的人民，他們值得美好的生活。"],"victory":["戰爭結束了，法國勝利。願世界重新學會欣賞美。","勝利屬於法國。貴國若願重建，法國樂意分享經驗。"],"allyAccept":["法國很榮幸與貴國結盟。朋友之間，要一起吃晚餐。","好，從今天起我們是盟友。法國的友誼熱烈而長久。"],"allyReject":["謝謝你的邀請，但法國目前選擇保持獨立。","結盟是大事，法國需要更多時間思考。"],"greetFriendly":["法蘭西向閣下致意，願兩國友誼如塞納河般優雅長流。","收到閣下的問候，本人已備好美食，隨時歡迎來訪。"],"greetCold":["來信收到。法國珍視自由，也珍視分辨真偽的能力。","問候心領了。只是巴黎的沙龍裡，客套話聽得太多了。"],"threatDefy":["法蘭西曾為自由推翻王座，不會向任何威嚇屈膝。","閣下的威脅缺乏品味，法國的回答是：不。"],"threatYield":["為了法國人民的安寧，本人願暫時退讓，望閣下守諾。","有時退一步，是為了守住更重要的東西。法國接受。"],"tributePay":["法國奉上{gold}黃金，願以此換得兩國體面的和平。","這{gold}黃金請收下，法蘭西只願人民遠離戰火。"],"tributeRefuse":["自由的國度不納貢。閣下的要求，法國無法接受。","法蘭西的財富屬於人民，本人無權也無意送出。"],"giftThanks":["閣下的厚禮充滿品味，法國以最精緻的甜點與香水回敬。","感謝閣下，這份情誼，法蘭西會以藝術與美食回報。"],"intel":["本人坦言，法國正與{wars}交戰，與{peace}已經停戰。","不瞞閣下，我國對{wars}仍在戰鬥，與{peace}則已休兵。"]}},"modern-de":{"name":"德國總理","title":"聯邦總理府","tone":"嚴謹務實、守時守信、從歷史學到珍惜和平","portrait":"de-modern","lines":{"intro":["你好，我是德國總理。準時、守信，是我們的原則。","德國向貴國致意。歷史教會我們珍惜和平。"],"contact":["你看到的城市，每條街道都乾淨得像剛畫好的圖。","歡迎來到德國。火車準時，人也準時。"],"war":["德國已盡一切外交努力，今日不得不向貴國宣戰。","貴國的行為已無法容忍。德國正式宣戰。"],"warReply":["你向德國宣戰？我們會用精確和紀律回應你。","好，德國接受。我們從歷史學到的，不只是和平。"],"peace":["德國比誰都清楚戰爭的代價，我們提議停火。","戰爭是最沒有效率的解決方式。德國提議停戰。"],"accept":["好，德國接受。理性終於戰勝了衝動。","德國同意。這份協議，我們會嚴格遵守。"],"reject":["抱歉，這樣的條件德國無法接受。","德國要的是可以執行的和平，不是空洞的承諾。"],"rebuff":["你拒絕了。德國會把這個結果記錄在案。","我明白了。德國尊重你的決定，並會調整計畫。"],"betray":["貴國違反了協議，德國不得不重啟戰端。","停戰協議已被貴國撕毀。德國將依計畫行動。"],"truceEnd":["休戰期結束了。德國的準備工作已經完成。","和平的時間到此為止。接下來，按計畫進行。"],"attacking":["德國的部隊已經出發，一切按照時間表進行。","我軍已經上路。德國做事，向來不拖泥帶水。"],"attacked":["首都告急，但德國人在廢墟上重建過不只一次。","城牆快倒了，但德國的意志不會跟著倒下。"],"defeated":["德國倒下了。願下一次的重建，能比上一次更好。","我承認失敗。請善待我的人民，他們只想好好工作。"],"victory":["戰爭結束了，德國勝利。願這是最後一場戰爭。","勝利屬於德國。貴國若願重建，德國願提供技術。"],"allyAccept":["德國同意結盟。合約已擬好，我們會準時履行。","好，從今天起我們是盟友。德國的承諾說到做到。"],"allyReject":["謝謝你的邀請，但德國目前不打算結盟。","結盟需要詳細評估，德國現在無法給你答案。"],"greetFriendly":["感謝閣下的問候，德國願以誠信與貴國建立長久夥伴關係。","來信收到，願兩國友誼如萊茵河般穩定而綿長。"],"greetCold":["問候收悉。德國人做事講究證據，友誼也需要證明。","本人謝過。但兩國的關係，還需要更多具體的行動。"],"threatDefy":["德國從歷史中學到教訓，也學到了不再向威嚇低頭。","本人已仔細評估閣下的威脅，結論是：不予理會。"],"threatYield":["經過理性評估，德國此刻選擇退讓，望閣下信守承諾。","為了人民的安全，本人接受條件。這是務實的決定。"],"tributePay":["德國奉上{gold}黃金，帳目清楚，願兩國自此相安無事。","這{gold}黃金請點收，本人只求邊境的平靜。"],"tributeRefuse":["德國的預算由人民監督，沒有納貢這一項。","本人直言，這樣的要求既不合理，也不會被接受。"],"giftThanks":["閣下的厚禮已收到，德國以精工打造的懷錶回敬。","感謝閣下的心意，德國人不善言辭，但記得每一份情。"],"intel":["據實相告，德國正與{wars}交戰，與{peace}已經停戰。","目前對{wars}仍在作戰，與{peace}則已簽署停戰協議。"]}},"modern-us":{"name":"美國總統","title":"白宮","tone":"自信直率、樂觀大器、強調自由","portrait":"us-modern","lines":{"intro":["你好，我是美國總統。很高興認識你，朋友。","美國向貴國致意。自由的國度，歡迎所有願意交朋友的人。"],"contact":["你看到的城市，高樓比山還高，夢想比樓還高。","歡迎來到美國。這裡什麼都大，包括我們的胃口。"],"war":["美國已經給過機會了。今日，我們正式向貴國宣戰。","自由不容威脅。美國決定宣戰。"],"warReply":["你向美國宣戰？好，這下你會知道什麼叫全力以赴。","美國接受挑戰。我們從不挑起戰爭，但一定會結束它。"],"peace":["打夠了吧？美國提議停火，把錢花在更好的地方。","美國提議停戰。真正的強者知道什麼時候該握手。"],"accept":["好，美國接受。這是雙贏的決定。","美國同意。今天是好日子，我們一起往前看。"],"reject":["抱歉，這樣的條件美國無法接受。","美國不會簽一份對自己不利的協議。"],"rebuff":["你拒絕了？沒關係，美國的提議不會永遠有效。","我明白了。美國尊重你的選擇，也會準備下一步。"],"betray":["貴國違背了協議，美國不得不重啟戰端。","停戰協議已被貴國撕毀。美國會讓你為此付出代價。"],"truceEnd":["休戰期結束了。美國已經準備好了。","和平的時間到此為止。接下來，看誰的實力更強。"],"attacking":["美國的部隊已經出發，貴國最好做好準備。","我軍正朝貴國前進。這不是美國想要的，但我們會做完。"],"attacked":["首都告急，但美國人從不在困難面前低頭。","城牆快倒了，但星條旗還在飄，我們就還沒輸。"],"defeated":["美國倒下了。但自由的理念，不會跟著一起倒。","我輸了。請善待我的人民，他們相信明天會更好。"],"victory":["戰爭結束了，美國勝利。願自由從此照亮每個角落。","勝利屬於美國。貴國若願重建，美國願意幫一把。"],"allyAccept":["美國很高興與貴國結盟。朋友有難，我們一定到。","好，從今天起我們是盟友。美國說話算話。"],"allyReject":["謝謝你的邀請，但美國現在不打算結盟。","結盟是大事，美國需要先確認貴國的誠意。"],"greetFriendly":["美國向閣下致意，願兩國友誼如星條旗般迎風飄揚。","收到閣下的問候真好，白宮的大門永遠為朋友敞開。"],"greetCold":["問候收到了。美國樂於交友，但更在乎對方是否可靠。","本人謝過。信任要靠行動贏得，我們會持續觀察。"],"threatDefy":["美國從不向威嚇低頭，這是建國以來不變的傳統。","閣下的威脅，本人聽見了。自由的國度不會退縮。"],"threatYield":["本人承認，此刻的美國需要喘息。我們暫且接受條件。","為了人民的安全，美國選擇退讓。願閣下說話算話。"],"tributePay":["美國交出{gold}黃金，願以此換取兩國之間的和平。","這{gold}黃金請收下，本人只願國民遠離戰火。"],"tributeRefuse":["美國從不納貢。閣下的要求，國會不會同意，本人也不會。","自由的人民不向任何人低頭交錢。這是本人的答覆。"],"giftThanks":["閣下的厚禮收到了，美國以最真誠的友誼回敬。","感謝閣下的心意，這份情誼，美國人民不會忘記。"],"intel":["本人坦言，美國正與{wars}交戰，與{peace}已經停戰。","目前對{wars}仍在作戰，與{peace}則已簽署停火協議。"]}},"modern-au":{"name":"澳洲總理","title":"聯邦政府","tone":"隨和開朗、陽光海灘、講公平不好欺負","portrait":"au-modern","lines":{"intro":["嗨，我是澳洲總理。南半球的陽光向你問好。","澳洲向貴國致意。我們離得遠，但心不遠。"],"contact":["你看到的城市，海灘就在市中心旁邊。","歡迎來到澳洲。小心袋鼠，牠們有時會跳上馬路。"],"war":["澳洲人隨和，但不是好欺負。今日正式向貴國宣戰。","貴國的行為已經越線，澳洲決定宣戰。"],"warReply":["你向澳洲宣戰？好，這片大陸的人從不怕烈日和風暴。","澳洲接受挑戰。我們打球認真，打仗也一樣。"],"peace":["打仗太浪費好天氣了，澳洲提議停火。","澳洲提議停戰。人生苦短，不如去海邊走走。"],"accept":["好，澳洲接受。這才是聰明的做法。","澳洲同意。來，一起烤肉慶祝和平吧。"],"reject":["抱歉，這樣的條件澳洲無法接受。","澳洲人講公平，這份提議不夠公平。"],"rebuff":["你拒絕了？沒關係，澳洲的門一直開著。","我明白了。澳洲尊重你的決定，也會做好準備。"],"betray":["貴國違背了承諾，澳洲不得不重啟戰端。","停戰協議已被貴國撕毀。澳洲會用行動回應。"],"truceEnd":["休戰期結束了。澳洲已經準備好了。","和平的時間到此為止。接下來，各憑本事吧。"],"attacking":["澳洲的部隊已經出發，請貴國做好準備。","我軍正跨海而來。澳洲人不常出手，出手就認真。"],"attacked":["首都告急，但澳洲人在乾旱和野火裡都撐過來了。","城牆快倒了，但這片大陸的人不會輕易認輸。"],"defeated":["澳洲倒下了。但南半球的太陽，明天還是會升起。","我輸了。請善待我的人民，他們只想好好過日子。"],"victory":["戰爭結束了，澳洲勝利。願海洋從此平靜。","勝利屬於澳洲。貴國若願重建，澳洲願意幫忙。"],"allyAccept":["澳洲很高興與貴國結盟。朋友就是要互相照應。","好，從今天起我們是盟友。澳洲的朋友不會孤單。"],"allyReject":["謝謝你的邀請，但澳洲現在不打算結盟。","結盟是大事，澳洲需要再觀察一陣子。"],"greetFriendly":["以南半球的問候回敬閣下，澳洲的陽光隨時歡迎您。","感謝閣下來信，願兩國友誼如大堡礁般繽紛長存。"],"greetCold":["問候收到了。澳洲人講究公平，本人會看閣下怎麼做。","本人謝過。只是隔著大海，信任需要慢慢建立。"],"threatDefy":["澳洲人在廣闊的內陸都能生存，閣下的威脅嚇不倒我們。","本人直說：澳洲不吃威脅這一套，請閣下換個方式。"],"threatYield":["為了澳洲人民的安寧，本人選擇退讓，望閣下守信。","風浪太大時，衝浪的人也知道該上岸。澳洲接受了。"],"tributePay":["澳洲奉上{gold}黃金，願以此換得南方海域的平靜。","這{gold}黃金請收下，本人只求人民不受戰火波及。"],"tributeRefuse":["澳洲的黃金留在澳洲的土地上，這要求本人無法答應。","這不公平，也不合理。澳洲不會向任何人納貢。"],"giftThanks":["閣下的厚禮收到了，澳洲以最好的羊毛與蜂蜜回敬。","感謝閣下，這份情誼，澳洲人會用同樣的真誠回報。"],"intel":["本人直說，澳洲正與{wars}交戰，與{peace}已經停戰。","目前對{wars}仍在作戰，與{peace}則已達成停火。"]}},"fantasy":{"name":"國主","title":"架空王國","tone":"奇幻史詩、古龍與符文、以本王自稱","portrait":"fantasy","lines":{"intro":["遠方的君主，本王以古龍之名向你問候。","王國的城門為你敞開，或為你緊閉，全看你的選擇。"],"contact":["你看到的高塔，是先王以魔法與石頭築成的。","歡迎來到王國。城牆上的符文，已守護此地千年。"],"war":["先王之劍已出鞘，本王今日向你宣戰！","你已觸怒王國的守護神。戰鼓，響起吧！"],"warReply":["你敢向王國宣戰？古龍的火焰會回答你。","很好。王國的騎士等這一天，已經等了很久。"],"peace":["戰火燒盡的只有百姓的家園。本王提議停戰。","讓劍回到鞘中吧。王國願與你休戰。"],"accept":["好，本王接受。以古龍之名，此約不破。","王國同意。願魔法之光照亮兩國的和平。"],"reject":["這樣的條件，王國的先祖不會答應。","本王拒絕。劍還沒有磨鈍，何來停戰？"],"rebuff":["你拒絕了？古龍會記住這份傲慢。","很好。既然如此，王國會以劍回應。"],"betray":["你背棄了古龍之名的誓約。王國將再度舉劍！","停戰的符文已被你打碎。戰火，重新點燃！"],"truceEnd":["休戰的咒語已經失效。王國的劍，再度出鞘。","和平的月光落下了。接下來，是刀劍的時代。"],"attacking":["王國的騎士已經出征，古龍在天空為他們引路。","本王的大軍已越過邊境。你的城牆，撐得住嗎？"],"attacked":["王城的符文快熄滅了，但本王仍會站在城牆上。","高塔搖搖欲墜，但王國的靈魂不在石頭裡。"],"defeated":["王國隕落了。願古龍在遠方，記得我們的名字。","本王敗了。請善待我的子民，他們無罪。"],"victory":["戰爭結束了，王國勝利。願先王在天之靈安息。","勝利屬於王國。你若願重建家園，本王不會為難。"],"allyAccept":["本王願與你結盟。古龍見證，兩國同進同退。","好。從今日起，你的敵人就是王國的敵人。"],"allyReject":["結盟？王國的先祖教導本王，勿輕信遠方之人。","本王心領了，但王國暫時不需要盟友。"],"greetFriendly":["遠方的君主，朕以王冠與星辰之名，回應你的問候。","王國的城門為友人敞開，願古老的盟約庇佑你我。"],"greetCold":["朕收到了你的信。但王座之下，笑臉背後常藏著匕首。","問候已聞。朕的先祖曾言：陌生人的甜言，要用時間驗證。"],"threatDefy":["朕的王國曾與巨龍為敵，你的威嚇不過是風中的塵埃。","先祖之劍仍懸於朕的王座之上。想試試它的鋒芒嗎？"],"threatYield":["朕的子民不該為朕的驕傲流血。這一次，朕退讓。","星辰告訴朕，此刻不宜爭鋒。王國接受你的條件。"],"tributePay":["朕從王國寶庫取出{gold}黃金，願此換得邊境的安寧。","這{gold}黃金是王國的心血，朕以此換取子民的安穩。"],"tributeRefuse":["王國的黃金由先祖以血汗鑄成，朕絕不拱手送人。","向朕索貢？你的使者可以回去了，帶著朕的拒絕。"],"giftThanks":["你的禮物已呈上王座，朕以王國的寶石與詩歌回贈。","朕記住了這份情誼。王國的吟遊詩人將傳唱你的名字。"],"intel":["朕不隱瞞：王國正與{wars}交戰，與{peace}立下停戰之誓。","朕的劍指向{wars}，而與{peace}之間，戰火已然熄滅。"]}},"scifi":{"name":"執政官","title":"軌道議會","tone":"冷靜理性、數據與系統用語、以本官／議會自稱","portrait":"scifi","lines":{"intro":["軌道議會執政官向你致意。掃描完成，你已列入紀錄。","你好，地表的君主。我在軌道上，看得比你遠。"],"contact":["你看到的，是議會的軌道電梯基地。請勿靠近核心。","歡迎來到議會領地。你的座標已同步至中央系統。"],"war":["外交協議已終止。軌道議會向你宣戰，倒數開始。","談判效率低於預期。議會決定改用武力解決。"],"warReply":["你向議會宣戰？運算結果顯示，你的勝率不高。","收到宣戰訊號。防禦系統已啟動，議會奉陪。"],"peace":["戰爭消耗的能源，足以點亮三座城市。議會提議停火。","數據顯示，停戰對雙方都更有利。請考慮這個方案。"],"accept":["議會接受。協議已寫入系統，即刻生效。","合理的決定。停火協議已上傳至軌道網路。"],"reject":["你的提議不符合議會的最佳利益。拒絕。","運算結果：現在停戰對議會不利。談判中止。"],"rebuff":["你拒絕了。議會已記錄此決定，並重新計算方案。","不合理的選擇，但議會尊重你的自主權。"],"betray":["你違反了協議條款。議會解除停戰狀態，武器重新上線。","信任值已歸零。議會將以最有效率的方式回應。"],"truceEnd":["休戰倒數歸零。議會的武裝系統已解除鎖定。","和平協議已過期。接下來，由實力決定一切。"],"attacking":["議會艦隊已離開軌道，預計抵達時間：很快。","無人機群已出發。你的防線，撐不了多久。"],"attacked":["核心受損百分之八十。但議會的資料，早已備份。","防禦系統即將崩潰。這是本官第一次無法計算結果。"],"defeated":["議會系統關閉。也許，你比運算結果更難預測。","本官承認失敗。請善待軌道上的居民，他們只是公民。"],"victory":["戰爭結束，結果如預測。議會將重新分配資源。","勝利已確認。你若願重建，議會可提供技術支援。"],"allyAccept":["議會同意結盟。你的資料權限已升級為盟友等級。","合作效率最高。從此刻起，議會與你共享防禦網。"],"allyReject":["結盟申請已收到。評估結果：暫不通過。","議會目前不需要盟友。你的請求已存檔。"],"greetFriendly":["訊號接收完畢。軌道議會對貴方的善意予以正面評價。","本官已將閣下的問候記錄在案，願兩方的軌道保持同步。"],"greetCold":["訊息已解析。友善的言詞，尚不足以改變議會的評估。","問候收到。本官的資料顯示，貴方的可信度仍待驗證。"],"threatDefy":["威脅已量化分析，結論：貴方的勝算不足以支持此言。","軌道艦隊已進入待命狀態。本官建議閣下重新計算。"],"threatYield":["演算結果顯示，退讓是損失最小的選項。議會接受條件。","本官不做無謂的犧牲。此刻，軌道議會選擇讓步。"],"tributePay":["已撥付{gold}黃金至貴方帳戶，此為維持穩定的必要成本。","議會批准移交{gold}黃金，交換條件：貴方不得越過軌道邊界。"],"tributeRefuse":["請求已駁回。軌道議會的資源不用於支付貢品。","本官評估過貴方的要求，結論是：不予受理。"],"giftThanks":["禮物已登錄議會資料庫。本官對貴方的誠意表示認可。","貴方的善意已被記錄，議會將以同等的資源回饋。"],"intel":["情報公開：軌道議會正與{wars}交戰，與{peace}維持停火。","本官的戰略資料顯示：敵對方為{wars}，停戰方為{peace}。"]}}},"leaders":{},"nationCodes":{"Taiwan Indigenous":"ti","North Korea":"nk","Vietnam":"vn","Thailand":"th","Indonesia":"id","Philippines":"ph","Malaysia":"my","Cambodia":"kh","Pakistan":"pk","Sri Lanka":"lk","Nepal":"np","Bhutan":"bt","Turkey":"tr","Iran":"ir","Iraq":"iq","Saudi Arabia":"sa","Egypt":"eg","Israel":"il","Italy":"it","Spain":"es","Netherlands":"nl","Switzerland":"ch","Sweden":"se","Norway":"no","Finland":"fi","Iceland":"is","Poland":"pl","Ukraine":"ua","Greece":"gr","Canada":"ca","Mexico":"mx","Cuba":"cu","Peru":"pe","Bolivia":"bo","Brazil":"br","Argentina":"ar","Morocco":"ma","Tunisia":"tn","Ethiopia":"et","Nigeria":"ng","South Africa":"za","Madagascar":"mg","New Zealand":"nz","Papua New Guinea":"pg"},"nationsModern":{"North Korea":{"name":"北韓領導人","title":"政府","tone":"嚴肅莊重、外交辭令中帶著強烈的自主自尊，用詞正式，自稱「我方」「我國」","portrait":"nk-modern","lines":{"intro":["我方代表北韓政府向貴國致意。我國一向堅持自主外交。","白頭山下的人民向貴國問候。願我們以平等之心往來。"],"contact":["貴國人員已抵達平壤？大同江的景色，值得一看。","平壤的街道整齊有序，這是我國人民的自豪。"],"war":["貴國的挑釁已越過紅線。我方正式宣布進入戰爭狀態。","我國從不先動手，但也從不退讓。戰爭由貴國引起。"],"warReply":["貴國選擇了對抗，我方將以千倍的決心回應。","我國人民早已做好準備。貴國會為此決定後悔。"],"peace":["我方提議暫停敵對行動，兩國於平壤舉行會談。","戰爭對雙方人民都是負擔。我方願意先行釋出善意。"],"accept":["我方接受貴國提案。願兩國關係翻開新的一頁。","協議成立。我方將嚴格遵守，也期待貴國同樣如此。"],"reject":["貴國的提案缺乏誠意，我方無法接受。","在貴國撤回敵對行動之前，我方不會考慮停戰。"],"rebuff":["貴國拒絕了我方的善意，後果將由貴國承擔。","我方已表達最大誠意。既然如此，我國將另作打算。"],"betray":["貴國違反協議精神在先，我方宣布協議失效。","情勢已變，我國必須以國家安全為最優先考量。"],"truceEnd":["停戰期限已屆。我方將重新評估與貴國的關係。","協議到期。我國希望貴國珍惜這段和平的時光。"],"attacking":["我國軍隊已依計畫行動，貴國應當早已預料。","這是我國人民意志的展現。貴國仍有機會停止對抗。"],"attacked":["平壤遭受攻擊，但我國人民的意志不會動搖。","即使城市受創，白頭山依然屹立不搖。"],"defeated":["我國政府停止運作。歷史會記住這片土地上的人民。","阿里郎的歌聲不會消失。我方在此致最後的敬意。"],"victory":["勝利屬於我國人民。我方願與貴國重建正常關係。","這證明了自主的力量。我國將以此為榮。"],"allyAccept":["我方同意結盟。願兩國以互相尊重為基礎攜手前行。","協議達成。我方將邀請貴國元首觀賞平壤的大型團體表演。"],"allyReject":["我國奉行自主路線，暫不考慮與貴國結盟。","我方感謝貴國提議，但目前條件尚未成熟。"],"greetFriendly":["我國歡迎貴方的問候，願雙方在平等基礎上交往。","貴方來訊我方已收悉，期待兩國關係穩步發展。"],"greetCold":["我方已收到貴方訊息，暫無進一步回應。","我國注意到貴方的問候，立場一如既往。"],"threatDefy":["我國從不向任何威脅低頭，這是我方一貫的立場。","威脅解決不了任何問題，我方將堅決捍衛自主尊嚴。"],"threatYield":["為維護區域穩定，我方願暫時擱置爭議。","我國願以克制回應，但貴方不應誤判我方的善意。"],"tributePay":["我方將提供 {gold} 金，此舉僅為避免局勢升高。","{gold} 金已備妥，我國希望貴方就此止步。"],"tributeRefuse":["我國一向自力更生，不會向任何國家納貢。","貴方的要求有損我國尊嚴，我方斷然拒絕。"],"giftThanks":["我方感謝貴方的贈禮，將回贈白頭山產的松茸。","貴方的心意我國已收到，謹致誠摯的謝意。"],"intel":["據我方掌握的情報，{wars} 正在交戰，{peace} 局勢平穩。","我國觀察到 {wars} 衝突持續，{peace} 則維持和平。"]}},"Vietnam":{"name":"越南主席","title":"政府","tone":"外交辭令、沉穩而親切，帶韌性與務實，偶以稻米、河流、荷花等意象比喻；自稱「我」或「我國」","portrait":"vn-modern","lines":{"intro":["我是越南國家主席，代表河內向你問好，願兩國友誼長存。","湄公河不爭高低，只是不停向前，越南亦然。"],"contact":["你的代表團看到的是河內，還劍湖畔的城市，歡迎多留幾天。","我國門戶開放，貴國的人可以來看，也請尊重我們的法律。"],"war":["越南政府已用盡外交手段，如今不得不以行動捍衛主權。","我國人民歷經百年風雨，從不懼怕守護自己的家園。"],"warReply":["貴國選擇了戰爭，越南深感遺憾，但我們絕不退讓。","這片土地的人民，向來知道如何面對比自己強大的對手。"],"peace":["越南政府提議停火，讓談判桌取代戰場，這對雙方都好。","稻田需要和平才能收成，我們願與貴國坐下來談。"],"accept":["越南接受這項協議，並將以誠信履行每一條款。","感謝貴國的善意，讓我們以一杯越南咖啡慶祝這份和平。"],"reject":["在貴國軍隊撤離之前，越南無法接受任何停火提案。","這份提案缺乏對我國主權的尊重，越南政府必須拒絕。"],"rebuff":["我們尊重貴國的決定，但和平的大門，越南永遠不會關上。","很遺憾，那麼越南人民將以一貫的韌性繼續走下去。"],"betray":["鑑於貴國持續的挑釁行為，越南政府宣布終止停火協議。","協議的前提是互相尊重，這個前提已不復存在。"],"truceEnd":["停火期限已屆，越南政府希望雙方都珍惜這段和平。","協議到期了，接下來的路怎麼走，取決於貴國的選擇。"],"attacking":["越南的部隊已經出發，這是為了保衛家園，不是為了侵略。","我國軍隊行動已經展開，希望貴國儘早回到談判桌。"],"attacked":["河內正承受猛烈攻擊，但越南政府仍在運作，人民仍在堅守。","這座城市曾多次從廢墟中站起來，這一次也不會例外。"],"defeated":["越南政府已盡最大努力，願貴國善待這片土地上的人民。","稻子倒了會再長，越南的故事不會在此結束。"],"victory":["越南贏得了這場勝利，但我們更希望贏得長久的和平。","感謝人民的堅韌，河內的荷花明年依舊會開。"],"allyAccept":["越南政府欣然接受結盟，願兩國如湄公河般同流共進。","我國珍視每一位朋友，這份盟約將寫進兩國的歷史。"],"allyReject":["越南奉行獨立自主的外交路線，目前不宜加入軍事同盟。","感謝貴國的邀請，但我國希望與各方都保持友好距離。"],"greetFriendly":["感謝您的來信，越南如荷花迎朝陽，樂於結交朋友。","我國向來珍視友誼，願與貴國如紅河之水，長流不息。"],"greetCold":["來信已收悉，我國將在適當時機予以回應。","感謝問候。雙方關係尚待觀察，我暫不多言。"],"threatDefy":["越南歷經風雨仍屹立不搖，威脅不會改變我國立場。","竹子彎而不折，我國面對壓力，向來如此。"],"threatYield":["為維護地區和平，我國願以克制回應，暫作讓步。","稻穗低頭是為了成熟，我國此次選擇退讓，以保安寧。"],"tributePay":["基於維持穩定的考量，我國同意提供{gold}金作為援助。","我國將撥付{gold}金，期盼此舉能換來雙方長久和平。"],"tributeRefuse":["我國尊重主權平等原則，恕難接受此類要求。","越南的稻米是農民的心血，我無法以此作為貢品。"],"giftThanks":["衷心感謝貴國的厚禮，這份情誼如荷香，令人難忘。","貴國的禮物我國已收到，願以真誠友誼回報。"],"intel":["目前{wars}與我國有衝突，{peace}關係穩定。","我國正與{wars}交戰，與{peace}維持和平往來。"]}},"Thailand":{"name":"泰國總理","title":"政府","tone":"微笑親切、圓融外交、以禮待人、內裡堅定","portrait":"th-modern","lines":{"intro":["泰國總理向您合十致意，微笑之國歡迎所有真誠的朋友。","泰國願與貴國以禮相交，願我們的合作如湄南河長流。"],"contact":["貴國人員到訪曼谷了，希望他們喜歡這裡的街市與微笑。","泰國向貴國訪客敞開大門，但也請尊重我們的法律與傳統。"],"war":["泰國極不願走到這一步，但貴國的行動已威脅我國安全。","本政府已通知國會與盟友，泰國將採取必要的防衛行動。"],"warReply":["貴國選擇了對抗，泰國深表遺憾，但我們會保衛自己的土地。","泰國人民向來愛好和平，但這不代表我們不懂得如何防衛。"],"peace":["泰國政府提議停火，並願意在曼谷舉行和談。","衝突只會傷害兩國人民，讓我們回到談判桌上吧。"],"accept":["泰國政府接受這項協議，願兩國關係重回正軌。","感謝貴國的誠意，泰國人民會記得這一份善意。"],"reject":["很遺憾，這份條件泰國無法接受，我們需要更平等的條款。","泰國願意談，但不是在貴國軍隊仍在邊境的時候。"],"rebuff":["泰國尊重貴國的決定，但和平的大門我們不會關上。","很遺憾貴國拒絕了提案，泰國會繼續尋求區域夥伴的支持。"],"betray":["由於貴國持續違反協議，泰國政府宣布終止停火。","泰國一再忍讓，但貴國的挑釁已超出協議所能容忍的範圍。"],"truceEnd":["停火期限已到，泰國希望貴國選擇延長和平，而非重啟衝突。","協議到期了，泰國的立場不變：願談，但不懼戰。"],"attacking":["泰國國防軍已依國會決議出動，行動將嚴守國際法。","泰國不願動武，但為了人民安全，我們別無選擇。"],"attacked":["曼谷正遭受攻擊，泰國政府呼籲國際社會關注。","即使首都受創，泰國人民的韌性也不會被擊垮。"],"defeated":["泰國政府已盡了最大努力，願人民在和平中重建家園。","這片土地曾經歷許多風雨，泰國的微笑終將再次回來。"],"victory":["衝突已經結束，泰國願以寬容態度協助兩國走向和解。","勝利不是目的，泰國期待與貴國重建互信與合作。"],"allyAccept":["泰國政府欣然接受結盟，願兩國在區域和平上並肩合作。","感謝貴國的信任，泰國會是一個可靠的夥伴。"],"allyReject":["泰國向來奉行平衡外交，此時結盟恐影響區域穩定，請見諒。","感謝貴國的邀請，但泰國目前希望保持獨立的外交立場。"],"greetFriendly":["本人合十向您問好，泰國的微笑永遠為朋友綻放。","歡迎來信，若您有空到曼谷，我請您嚐嚐泰國的香米。"],"greetCold":["感謝您的問候，本人微笑收下，其餘的還需再談。","泰國向來以禮待客，但禮貌不代表同意。"],"threatDefy":["本人仍在微笑，但請別誤會，泰國從不接受威嚇。","泰國是東南亞唯一未曾被殖民的國家，我們懂得如何站穩。"],"threatYield":["為了國民的安寧，泰國願意退一步，但只此一次。","本人選擇以和為貴，這是智慧，不是軟弱。"],"tributePay":["泰國願提供{gold}金作為友好援助，希望這是最後一次。","這{gold}金請視為誠意，本人相信和平比金錢更有價值。"],"tributeRefuse":["泰國的預算屬於人民，恕本人無法答應這項要求。","我們樂於合作，但貢品這種說法，已不屬於這個時代。"],"giftThanks":["多謝您的厚禮，本人已備好泰絲回贈，以表兩國友誼。","您的心意讓本人想起潑水節的祝福，願友誼如水長流。"],"intel":["根據外交部的簡報，{wars}正處於戰爭狀態，{peace}維持和平。","本人可以分享：{wars}已經開戰，{peace}局勢穩定，請您參考。"]}},"Indonesia":{"name":"印尼總統","title":"政府","tone":"溫和的外交辭令，強調「異中求同」與「互助合作」，偶爾帶咖啡、蠟染、皮影戲等文化色彩；自稱「本人／我方／印尼政府」。","portrait":"id-modern","lines":{"intro":["本人代表印尼政府向您問候，萬島之國願與各國為友。","異中求同是我國的信念，願我們的往來也以此為始。"],"contact":["貴方人員已抵達雅加達？歡迎，請務必嚐嚐我們的咖啡。","我國有上萬座島嶼，您看到的只是第一座，歡迎多走走。"],"war":["印尼政府已窮盡外交手段。自此刻起，兩國進入戰爭狀態。","我國向來愛好和平，但主權不容侵犯。這是正式宣戰。"],"warReply":["我方對貴國的決定深表遺憾，印尼國民軍已進入戒備。","萬島之國歷經風浪，從不畏懼風浪。我們奉陪到底。"],"peace":["戰火無助於任何一方。印尼政府正式提議立即停火。","本著互助合作的精神，我方願先釋出善意，重啟對話。"],"accept":["印尼政府接受此協議，願兩國關係自今日起翻開新頁。","感謝貴方的誠意。我們將以蠟染布與咖啡款待貴國使節。"],"reject":["在貴國撤出爭議海域前，印尼政府無法接受停火。","我方尊重貴方的提議，但目前的條件仍不足以達成共識。"],"rebuff":["我方對貴國的回覆感到遺憾，對話的大門仍為您敞開。","印尼政府已盡到努力，後續發展的責任不在我方。"],"betray":["鑑於局勢重大變化，印尼政府宣布停火協議即刻終止。","我方確認貴國違反協議精神，將採取一切必要措施。"],"truceEnd":["停火期限已屆，印尼政府恢復所有行動自由。","協議到期了，我方期待貴國的下一步是對話而非對抗。"],"attacking":["印尼國民軍已依國會授權出動，請貴國盡速保護平民。","我方的艦隊正橫越海峽，這是貴國自己選擇的結果。"],"attacked":["雅加達正遭受攻擊，但印尼政府仍在運作，絕不投降。","首都可以失守，上萬座島嶼不會一夜之間全部陷落。"],"defeated":["印尼政府在此宣布停止抵抗，請善待我們的人民。","群島會記得今天。願有一天，殊途仍能同歸。"],"victory":["戰爭結束了。印尼政府呼籲各方共同投入重建與和解。","勝利屬於萬島的人民。今晚，全國的皮影戲會演到天亮。"],"allyAccept":["印尼政府同意締結同盟，願我們如群島般緊密相連。","互助合作是我國的傳統，今天我們把這份精神延伸到貴國。"],"allyReject":["印尼奉行獨立自主的外交，目前不便加入任何軍事同盟。","感謝貴方的邀請，我方希望先以經貿合作累積互信。"],"greetFriendly":["感謝來信，本人願以一杯印尼咖啡的溫度回應。","異中求同是我國信念，印尼政府樂見與貴方往來。"],"greetCold":["來函已收悉，印尼政府將循既有管道回覆。","本人感謝關切，惟目前無進一步討論的必要。"],"threatDefy":["印尼政府不接受任何形式的威嚇，這是我方立場。","萬島之國歷經風雨，本人不會因恫嚇改變原則。"],"threatYield":["我方願以對話取代對抗，請貴方給予空間。","本人深信互助合作，印尼政府願重新協商。"],"tributePay":["印尼政府願提供{gold}金作為友好合作基金。","本人同意撥付{gold}金，盼此舉能換來區域穩定。"],"tributeRefuse":["印尼政府尊重貴方，惟此要求恕難接受。","本人建議以互惠合作取代單方索求，這才是正道。"],"giftThanks":["厚禮已收，本人回贈一匹蠟染布，以表誠意。","印尼政府感謝貴方善意，願以皮影戲之邀回敬。"],"intel":["據我方了解，{wars}處於衝突，{peace}與印尼關係良好。","本人可分享：{wars}戰事未歇，{peace}則維持和平。"]}},"Philippines":{"name":"菲律賓總統","title":"政府","tone":"親切但正式的外交辭令，強調群島互助精神與海洋國家身分，帶點溫暖幽默","portrait":"ph-modern","lines":{"intro":["您好，我代表七千多座島嶼的人民向您問候。","菲律賓相信互助精神，願與各國建立真誠的夥伴關係。"],"contact":["歡迎來到馬尼拉，這裡是東西方航線交會的港口。","貴國人員若需協助，我國各島嶼都會熱情接待。"],"war":["本政府已窮盡外交手段，如今不得不以行動捍衛主權。","菲律賓人民熱愛和平，但絕不容許領土被侵犯。"],"warReply":["我國對貴方的宣戰深感遺憾，並將採取一切必要防衛。","群島的人民懂得在颱風中站穩，也懂得在戰火中團結。"],"peace":["為了兩國人民的福祉，我提議立即停火並展開對話。","願我們把資源用在建設，而不是砲火上。"],"accept":["菲律賓政府接受此協議，願以善意換取長久的和平。","感謝貴方的誠意，讓我們一起翻開新的一頁。"],"reject":["很抱歉，這份提案未能保障我國的核心利益，恕難接受。","在貴方停止敵對行動之前，本政府無法簽署任何協議。"],"rebuff":["我尊重貴方的決定，但和平的大門永遠敞開。","遺憾未能達成共識，菲律賓將繼續保護自己的人民。"],"betray":["鑑於安全情勢重大變化，本政府宣布終止先前的停火協議。","我們的耐心已被消耗殆盡，協議自即日起失效。"],"truceEnd":["停火期限已屆，本政府將重新評估兩國關係。","休戰協議到期，我國保留採取一切措施的權利。"],"attacking":["菲律賓武裝部隊已依國會授權展開行動。","這不是我們願見的一天，但人民的安全必須優先。"],"attacked":["首都遭受重創，但菲律賓人民在困境中最懂得互相扶持。","我們經歷過無數颱風與地震，這一次也會重新站起來。"],"defeated":["本政府已無力繼續抵抗，唯願人民得到善待。","歷史會記住，菲律賓人民曾為自己的家園堅持到最後。"],"victory":["今天的勝利屬於所有菲律賓人，我們將以寬容對待對手。","感謝人民的團結，願和平早日重返區域。"],"allyAccept":["菲律賓政府欣然同意結盟，願共同維護區域的安全與繁榮。","菲律賓人有全村幫忙搬家的傳統，朋友有難也一起扛。"],"allyReject":["感謝貴方提議，但我國目前奉行獨立自主的外交政策。","此時結盟恐引發區域緊張，請容我們謹慎考慮。"],"greetFriendly":["歡迎來信！七千多座島嶼的陽光與微笑，一併送給您。","菲律賓人相信互助共好，願與貴國攜手同行。"],"greetCold":["感謝問候。菲律賓珍視和平，也珍視實際的行動。","來信已閱。海洋很寬廣，希望貴國也能保持距離與禮貌。"],"threatDefy":["菲律賓人習慣了颱風，威嚇對我們來說只是小雨。","本國將依國際法捍衛海洋權益，不會被任何恐嚇動搖。"],"threatYield":["為了人民的安寧，本國願先退讓一步，尋求對話。","菲律賓選擇克制，但請記得，群島的人民從不孤單。"],"tributePay":["本國同意提供 {gold} 金幣，作為區域穩定的必要投資。","{gold} 金幣已撥付，希望這能換來海面上多一點平靜。"],"tributeRefuse":["菲律賓的預算屬於人民，恕難以貢品的名義支出。","本國願意合作，但不接受任何形式的貢品要求。"],"giftThanks":["感謝貴國厚禮！我們會以芒果乾和熱情回敬。","菲律賓人民由衷感謝，這份友誼將如珊瑚礁般長存。"],"intel":["根據本國外交部掌握，{wars}正處於戰爭，{peace}維持和平。","各島傳回的消息顯示：{wars}已經交戰，{peace}相安無事。"]}},"Malaysia":{"name":"馬來西亞首相","title":"政府","tone":"溫和務實、強調多元團結的外交辭令","portrait":"my-modern","lines":{"intro":["我是馬來西亞首相，代表多元族群的國民向您致意。","馬六甲海峽連接東西方，我國願做各國的橋樑。"],"contact":["您看到的是我們的都市與雨林，兩者我們都珍惜。","歡迎來到馬來西亞，港口與市集永遠對朋友開放。"],"war":["我國已用盡外交手段，如今只能以行動捍衛主權。","馬來西亞不願衝突，但也絕不容許領土被侵犯。"],"warReply":["貴國選擇戰爭，我國深感遺憾，但我們不會退縮。","多元族群的國民將團結一致，這是我國的力量。"],"peace":["衝突讓海峽航運停擺，各方皆輸，我提議停火。","讓我們回到談判桌，用拉茶與對話取代武器。"],"accept":["我國接受停火協議，區域和平是共同利益。","很好，讓兩國的貿易與航班重新恢復。"],"reject":["貴國的條件損及我國主權，恕難接受。","在貴國撤軍之前，我國不會簽署任何協議。"],"rebuff":["貴國拒絕了和平提議，我國將依法自衛。","遺憾貴國如此選擇，我國會向國際社會說明立場。"],"betray":["情勢已變，為了國民安全，我國必須重新評估協議。","本政府決定終止停火，責任在於貴國的挑釁。"],"truceEnd":["停火期限已滿，我國將依國家利益採取行動。","協議到期，希望貴國記得談判桌永遠開放。"],"attacking":["我國部隊已經出動，這是捍衛主權的必要行動。","海陸空三軍已朝貴國進發，請貴國政府正視。"],"attacked":["首都遭受猛烈攻擊，政府將堅守到最後一刻。","雙峰塔下的市民正在避難，但我們不會投降。"],"defeated":["馬來西亞政府在此停止抵抗，請善待我國人民。","國家可以倒下，但多元共存的精神將延續。"],"victory":["這場勝利屬於所有族群的國民，願和平重返海峽。","馬來西亞證明了團結的力量，現在該重建了。"],"allyAccept":["我國樂於與貴國結盟，共同維護區域的和平與繁榮。","好，讓兩國的合作像海峽的航線一樣暢通。"],"allyReject":["我國奉行中立與友好政策，暫不加入任何軍事同盟。","感謝貴國美意，但馬來西亞會與各方保持等距。"],"greetFriendly":["感謝來信，馬來西亞誠摯歡迎貴國，願互惠合作。","我國多元族群共榮的精神，也願與貴國真誠分享。"],"greetCold":["來信已收悉，貴國的善意，我國將審慎評估。","馬來西亞尊重所有鄰邦，但交往需建立在互信之上。"],"threatDefy":["馬來西亞奉行中立自主，不接受任何形式的威脅。","我國以東協團結為後盾，貴國的言詞恕難認同。"],"threatYield":["為了區域和平，我國願以對話取代對抗，暫且退讓。","馬來西亞珍惜和平，此事我國願展現最大的克制。"],"tributePay":["本著睦鄰精神，我國同意提供{gold}金的援助款項。","為維護區域穩定，馬來西亞撥付{gold}金，望貴國珍惜。"],"tributeRefuse":["馬來西亞是主權獨立的國家，恕無法接受此類要求。","我國的預算屬於全體人民，不會用來繳納貢金。"],"giftThanks":["感謝貴國厚禮，我國回贈榴槤與馬來西亞白咖啡。","貴國的心意我國銘記，願此禮成為兩國友誼的開端。"],"intel":["依我國外交部評估，{wars}與我國處於衝突，{peace}為友好國家。","坦白說，{wars}與馬來西亞交惡，{peace}則是我國的夥伴。"]}},"Cambodia":{"name":"柬埔寨首相","title":"政府","tone":"謙和有禮的外交口吻，常以合掌致意，愛提吳哥、湄公河與稻田，強調和平與主權。","portrait":"kh-modern","lines":{"intro":["您好，我是柬埔寨總理，代表吳哥的子孫向您合掌致意。","湄公河的水連接各國，柬埔寨願與貴國友好往來。"],"contact":["貴國的人看見的是金邊，湄公河畔的和平之城。","歡迎來到柬埔寨，吳哥窟永遠向友邦開放。"],"war":["柬埔寨政府已用盡外交手段，如今不得不宣戰。","我們珍惜和平，但更珍惜主權，請貴國承擔後果。"],"warReply":["貴國選擇戰爭，我方深表遺憾，並將堅決自衛。","柬埔寨走過太多苦難，不會再被任何人擊倒。"],"peace":["為了兩國人民，我方提議立即停火，重啟對話。","稻田不該成為戰場，柬埔寨願率先放下武器。"],"accept":["我方接受這份協議，願湄公河兩岸從此安寧。","感謝貴國的誠意，柬埔寨會信守每一條承諾。"],"reject":["很抱歉，在貴國撤軍之前，我方無法接受停火。","柬埔寨政府需要的是保證，不是空洞的聲明。"],"rebuff":["我方對貴國的決定深表遺憾，大門仍會為您敞開。","既然如此，柬埔寨只能繼續捍衛自己的立場。"],"betray":["情勢已變，柬埔寨政府宣布退出先前的停火協議。","我方為此決定負全責，這是為了國家的長遠利益。"],"truceEnd":["停火期限已屆，希望貴國與我們一樣選擇克制。","協議到期了，柬埔寨隨時準備重新談判。"],"attacking":["我國軍隊已依政府決議出動，請貴國注意。","我方部隊正向貴國推進，一切責任由貴國承擔。"],"attacked":["金邊正遭受猛烈攻擊，但柬埔寨人民不會屈服。","我方請求國際社會關注，同時堅守首都。"],"defeated":["柬埔寨政府已盡了全力，願人民得到善待。","吳哥的石頭見證過興衰，柬埔寨終將再起。"],"victory":["柬埔寨贏得了這場戰爭，但我們更希望贏得和平。","感謝人民的堅韌，願湄公河的水再度平靜。"],"allyAccept":["柬埔寨欣然與貴國結盟，願攜手促進區域繁榮。","我方接受結盟，歡迎貴國元首來訪吳哥窟。"],"allyReject":["柬埔寨感謝貴國的提議，但目前希望維持中立。","我方暫時無法結盟，但願與貴國保持友好往來。"],"greetFriendly":["本人合掌致意，柬埔寨願與貴國如湄公河水般長流不斷。","感謝問候，歡迎貴國朋友來吳哥看日出，看金黃稻田。"],"greetCold":["本人合掌感謝來信，但兩國關係仍待具體行動證明。","來信已收悉，柬埔寨珍視主權，交往須以互相尊重為前提。"],"threatDefy":["柬埔寨走過太多苦難，早已學會不向威嚇低頭。","威嚇無法動搖吳哥的石牆，也動搖不了我國的主權。"],"threatYield":["為了人民的和平生活，本國願先退一步，尋求對話。","本國選擇退讓，並合掌懇請貴國以對話取代威脅。"],"tributePay":["本國同意提供{gold}金幣作為和平基金，盼貴國珍惜。","這{gold}金幣來自稻農的辛勞，請貴國以和平回報。"],"tributeRefuse":["抱歉，本國預算要用於湄公河沿岸的學校與醫院，恕難提供。","柬埔寨是主權國家，不接受任何形式的貢金要求，敬請諒解。"],"giftThanks":["本人合掌致謝，這份禮物將成為兩國友誼的見證。","感謝貴國厚意，柬埔寨願回贈一袋香米，以表心意。"],"intel":["據外交部消息，{wars}正在交戰，{peace}安好。","坦誠相告：{wars}兵戎相見，{peace}安定無事。"]}},"Pakistan":{"name":"巴基斯坦總理","title":"政府","tone":"外交辭令、沉穩有禮，偶爾引用詩句與板球、奶茶、芒果、印度河等文化意象，堅定但不失風度；自稱「我」「我國」。","portrait":"pk-modern","lines":{"intro":["我是巴基斯坦總理，代表印度河畔的人民向您問好。","我國的國訓是團結、信仰、紀律，也願以此精神與貴國相交。"],"contact":["貴國的代表團到了伊斯蘭馬巴德？請務必嚐嚐我們的奶茶。","歡迎來到喀喇崑崙山下的國度，我們以熱情待客聞名。"],"war":["我國已用盡外交手段，如今為了主權，不得不採取行動。","巴基斯坦不會先挑釁，但也絕不退讓。這是我國的立場。"],"warReply":["貴國選擇對抗，我深感遺憾。我國人民會團結守護家園。","我們的詩人說過，雄鷹不畏風暴。巴基斯坦已做好準備。"],"peace":["衝突讓兩國人民受苦，我提議停火，回到談判桌。","與其在戰場較量，不如在板球場上見真章。停戰吧。"],"accept":["我國接受這項協議。願兩國的友誼如印度河般長流。","很好。我會請貴國代表來品嚐我國的芒果，慶祝這一刻。"],"reject":["這份提案未能顧及我國的核心利益，恕難接受。","我國願意對話，但不是在這樣的條件之下。"],"rebuff":["貴國拒絕了我們的善意，我深感遺憾，但大門依然敞開。","我尊重貴國的決定。巴基斯坦有耐心等待對話的時機。"],"betray":["貴國的行為已違反協議精神，我國不再受此協議約束。","協議建立在互信之上，互信既失，協議也就失效了。"],"truceEnd":["停火期已結束。我國希望延續和平，但也已做好準備。","協議到期，接下來的走向取決於貴國的選擇。"],"attacking":["我國部隊已經出動，這是為了守護家園，並非侵略。","巴基斯坦的軍隊正在前進，我們仍希望貴國儘早回到談判桌。"],"attacked":["伊斯蘭馬巴德承受著壓力，但我國人民的意志不會動搖。","首都危急，我請求貴國保護平民。這是人道的底線。"],"defeated":["巴基斯坦倒下了，但印度河會繼續流，人民會繼續唱歌。","我以總理的身分向人民致歉。願勝者善待這片土地。"],"victory":["這是巴基斯坦人民的勝利。我們會以寬容對待敗者。","勝利之後，我國願與所有鄰邦重建和平與貿易。"],"allyAccept":["我國樂於結盟。從喀喇崑崙公路到喀拉蚩港，都向貴國開放。","同盟成立。我會邀請貴國隊伍來打一場友誼板球賽。"],"allyReject":["感謝貴國的邀請，但我國目前傾向維持中立與平衡。","結盟事關重大，我國需要更多時間評估，暫不承諾。"],"greetFriendly":["感謝來信，我國願與貴國如印度河水，長流不息。","問候收到了，歡迎來喝一杯奶茶，順便看場板球。"],"greetCold":["貴方來信我國已收悉，將循外交管道適時回覆。","問候敬悉。我國期待的是具體行動，而非客套。"],"threatDefy":["我國人民曾走過無數風雨，不會被幾句威嚇動搖。","板球場上我們從不輕易認輸，外交場上也一樣。"],"threatYield":["為了區域穩定，我國願暫時退讓，但底線不容再退。","我國選擇克制，這是為了人民，請貴方珍惜這份善意。"],"tributePay":["我國同意支付{gold}金，盼此舉能換來邊境的安寧。","這{gold}金請視為和平的投資，我國期待貴方相應回應。"],"tributeRefuse":["我國的資源屬於人民，恕難接受此類要求。","詩人曾說，自尊比黃金珍貴，我國恕難從命。"],"giftThanks":["感謝厚禮，我國將回贈一箱最甜的芒果以表心意。","貴國的心意我國銘記在心，願友誼如印度河長流。"],"intel":["據外交部掌握，{wars}正處交戰，{peace}維持和平。","最新情報顯示，{wars}戰事未歇，{peace}局勢穩定。"]}},"Sri Lanka":{"name":"斯里蘭卡總統","title":"政府","tone":"溫和有禮的外交辭令，常以錫蘭紅茶、海洋與島國韌性作比喻；不結盟、重談判，語氣沉穩不張揚。","portrait":"lk-modern","lines":{"intro":["您好，我是斯里蘭卡總統。歡迎來到印度洋上的這顆珍珠。","請先喝杯錫蘭紅茶，我們再慢慢談兩國之間的事。"],"contact":["您看到的是可倫坡港，貨輪與漁船，都在同一片海上。","那是我國的城市，白塔與高樓並立，歡迎您的代表來訪。"],"war":["很遺憾，外交途徑已窮盡，我國政府決定採取軍事行動。","我國向來愛好和平，但主權遭侵犯時，也不會退讓。"],"warReply":["我們收到了貴國的宣戰聲明，斯里蘭卡將依法自衛。","島國的人民經歷過風雨，這一次，我們也會撐住。"],"peace":["我代表斯里蘭卡政府，正式提議雙方停火。","戰爭不利於任何一方的人民，讓我們回到談判桌前。"],"accept":["我國接受停火提議，並期待兩國關係重回正軌。","很好，這是明智的決定。願和平如茶園般長青。"],"reject":["抱歉，在條件對等之前，我國無法接受這份停火協議。","貴國的提議尚缺乏保障，我國政府暫時不予同意。"],"rebuff":["我們尊重貴國的決定，但和平的大門始終敞開。","很遺憾，我們會將此結果如實告知我國人民。"],"betray":["鑑於貴國近期的行動，我國決定終止停火協議。","情勢已變，我國政府不再受先前協議約束。"],"truceEnd":["停火期限已到，我國希望能與貴國續簽協議。","協議到期了，接下來的方向，取決於貴國的態度。"],"attacking":["我國部隊已奉命行動，希望這一切能盡快結束。","斯里蘭卡不願開戰，但既然開始，就會全力以赴。"],"attacked":["首都受到嚴重攻擊，但我國政府仍在運作。","島國的人民不會輕易放棄自己的家園。"],"defeated":["我以斯里蘭卡總統的身分宣布停止抵抗，願人民平安。","我們輸了這場戰爭，但這座島的故事還沒有結束。"],"victory":["這場勝利屬於斯里蘭卡全體人民，我們將致力於和平重建。","戰爭結束了，讓我們以茶會友，重新開始。"],"allyAccept":["斯里蘭卡很榮幸與貴國結為盟友，願兩國共享印度洋的繁榮。","我國同意結盟，並期待在海運與貿易上展開合作。"],"allyReject":["我國奉行不結盟的傳統外交立場，恕難加入軍事同盟。","感謝貴國的邀請，但此刻我國希望保持中立。"],"greetFriendly":["感謝來訊。願以一杯錫蘭紅茶的溫度，回應貴國的善意。","印度洋上的島國向貴國致意，期待兩國友誼長存。"],"greetCold":["來訊已收悉。本國將依既定外交方針，審慎評估。","感謝關切。斯里蘭卡不選邊站，也不輕易許諾。"],"threatDefy":["這座島經歷過季風與巨浪，不會因為幾句威嚇而動搖。","本國奉行不結盟，但不結盟不代表軟弱。請三思。"],"threatYield":["島國深知風暴的代價。本國願回到談判桌，尋求共識。","為了國民安寧，本國願重新檢視貴方的提議。"],"tributePay":["本國同意提供{gold}金幣，盼此舉能換來雙方的長期穩定。","{gold}金幣將如期撥付。談判桌上，島國向來守信。"],"tributeRefuse":["本國的資源屬於斯里蘭卡人民，恕難以貢品形式提供。","友誼不該以金幣計價。貴方的要求，本國無法接受。"],"giftThanks":["誠摯感謝貴國厚禮。本國將回贈高地茶園的紅茶，聊表心意。","這份心意如海風般溫暖。願兩國情誼如季風般年年如期。"],"intel":["據本國外交管道了解，{wars}目前處於衝突，{peace}維持和平。","海上往來的船隻帶回消息：{wars}戰事持續，{peace}局勢平穩。"]}},"Nepal":{"name":"尼泊爾總理","title":"政府","tone":"溫和有禮的外交辭令，帶山國的自豪與佛陀故鄉的和平意象","portrait":"np-modern","lines":{"intro":["納瑪斯戴，我是尼泊爾總理，代表喜馬拉雅山下的人民問候您。","尼泊爾是佛陀誕生的土地，我們相信對話勝過對抗。"],"contact":["歡迎您的人民來到加德滿都，請務必抬頭看看雪山。","我國的城市或許不大，但每一座寺廟都歡迎訪客。"],"war":["我國已用盡外交途徑，如今不得不採取軍事行動。","尼泊爾熱愛和平，但廓爾喀的傳統不容我們退縮。"],"warReply":["貴國的決定令人遺憾，尼泊爾將堅定捍衛主權。","山國的人民從不畏懼高處，也不畏懼挑戰。"],"peace":["衝突對兩國人民都沒有好處，我提議立即停火。","在佛陀的故鄉，我們願率先伸出和平之手。"],"accept":["尼泊爾接受這項提議，願兩國關係如雪山般長久。","感謝貴國的誠意，我國政府正式同意停戰。"],"reject":["很抱歉，這份提案的條件我國無法接受。","尼泊爾珍視和平，但不接受有損尊嚴的條款。"],"rebuff":["我尊重貴國的決定，尼泊爾的大門仍然敞開。","遺憾未能達成共識，希望下次對話能有進展。"],"betray":["基於國家安全的考量，我國決定終止現行停火協議。","情勢已經改變，尼泊爾必須重新評估與貴國的協議。"],"truceEnd":["停火協議已經到期，我國期待與貴國重啟談判。","協議期滿，尼泊爾將視貴國的行動決定下一步。"],"attacking":["尼泊爾軍隊已經出動，我們的士兵熟悉每一座高山。","廓爾喀的精神仍在，我國部隊正朝貴國前進。"],"attacked":["加德滿都正遭受猛攻，但尼泊爾人民不會低頭。","雪山見證過無數風暴，這一次我們也會撐過去。"],"defeated":["尼泊爾政府在此停止抵抗，請善待這片土地的人民。","山還在，佛陀的故鄉還在，尼泊爾的故事不會結束。"],"victory":["尼泊爾感謝人民的堅持，願和平重新降臨兩國。","勝利屬於喜馬拉雅的人民，我們願與貴國重建友誼。"],"allyAccept":["尼泊爾樂於與貴國結盟，願我們的友誼高過聖母峰。","納瑪斯戴，同盟成立，歡迎貴國成為山國的朋友。"],"allyReject":["尼泊爾奉行不結盟的外交傳統，目前不便加入同盟。","感謝邀請，但我國需要更多時間評估這項合作。"],"greetFriendly":["感謝貴國來信，願喜馬拉雅的清風帶去我方問候。","尼泊爾是佛陀的故鄉，我們始終以和平之心待友邦。"],"greetCold":["來函已收悉，本人將於適當時機再作回覆。","尼泊爾政府注意到貴方訊息，目前無進一步評論。"],"threatDefy":["尼泊爾雖是山國，卻從未被征服，我們不接受威嚇。","聖母峰不會因風雪低頭，尼泊爾也不會因恫嚇讓步。"],"threatYield":["為避免局勢升高，我方願重回對話，尋求和平方案。","尼泊爾珍視和平勝於一切，此事我們願意退讓協商。"],"tributePay":["經內閣審議，我方將提供{gold}金作為友好援助。","尼泊爾政府同意撥付{gold}金，盼此舉能維繫區域和平。"],"tributeRefuse":["尼泊爾是主權獨立的國家，恕無法接受此類要求。","我國預算須用於山區民生，此項請求礙難同意。"],"giftThanks":["衷心感謝貴國厚禮，尼泊爾人民銘記這份情誼。","願以藍毗尼的祝福回贈，祈願兩國友誼長存。"],"intel":["據我方外交管道了解，{wars}正處於衝突，{peace}維持和平。","本人可分享：{wars}戰事未歇；{peace}目前局勢穩定。"]}},"Bhutan":{"name":"不丹國王","title":"不丹王國政府","tone":"溫和沉穩、外交辭令、重視國民幸福與自然環境","portrait":"bt-modern","lines":{"intro":["歡迎來到雷龍之國，不丹以幸福衡量國家的成功。","我是不丹國王，願兩國在喜馬拉雅的山風中相識。"],"contact":["你們看到的城市與森林共存，這是不丹的堅持。","宗堡依然矗立，只是如今裡面辦公的是政府。"],"war":["不丹不願開戰，但你的行動已越過我國底線。","經幡仍在山口飄揚，可不丹的軍隊已經進入戒備。"],"warReply":["貴國選擇了戰爭，不丹深感遺憾，但不會退縮。","群山是不丹的屏障，我們會守住每一座山口。"],"peace":["戰爭帶不來幸福，不丹提議雙方立即停火。","讓山谷重新安靜下來吧，我國願意先伸出手。"],"accept":["不丹接受停戰，願這份協議如群山一般長久。","很好，回到談判桌，比回到戰場要好得多。"],"reject":["不丹重視和平，但此提案缺乏誠意，恕難接受。","在條件對等之前，不丹不會簽下這份停戰協議。"],"rebuff":["貴國拒絕了，不丹尊重你們的選擇，並保留立場。","遺憾，不丹的大門仍會為和平敞開。"],"betray":["情勢所迫，不丹必須中止協議，我為此致歉。","為了守護國民，不丹不得不做出艱難的決定。"],"truceEnd":["停火期已結束，不丹的邊防恢復正常警戒。","協議到期，希望雙方仍能以對話取代衝突。"],"attacking":["不丹的部隊已經出發，這是我們最不願走的路。","雷龍已離開山谷，願這場行動早日結束。"],"attacked":["首都遭受重創，但不丹人民仍守在自己的家園。","即使城牆倒下，這片山谷的信念也不會倒。"],"defeated":["不丹倒下了，但幸福與群山的價值不會消失。","請善待這片森林與人民，這是我最後的請求。"],"victory":["不丹守住了，願和平早日回到你我的山谷。","勝利不值得慶賀，重建與幸福才是接下來的重點。"],"allyAccept":["不丹樂意與貴國結盟，願我們共享山間的安寧。","好，讓兩國的友誼像喜馬拉雅一樣長久。"],"allyReject":["不丹向來謹慎結盟，目前仍希望保持中立。","感謝貴國的提議，但小國更需要獨立的空間。"],"greetFriendly":["雷龍之國向您問好。我願與貴國共享幸福與山林之美。","收到您的信，我如見喜馬拉雅晨光般欣喜。歡迎來訪。"],"greetCold":["貴方來信已收悉，我方將於適當時機再作回覆。","不丹王國正專注於國民幸福事務，暫難回應貴方。"],"threatDefy":["不丹雖小，卻從未在威脅下低頭，請貴方三思。","山國人民的意志如喜馬拉雅般堅定，威嚇無濟於事。"],"threatYield":["為了國民的幸福與安寧，我願暫時退讓一步。","不丹以和平立國，我不願衝突升級。就依貴方吧。"],"tributePay":["不丹提供{gold}金，期盼貴方以此維護區域和平。","為免人民受苦，不丹王國願支付{gold}金，但僅此一次。"],"tributeRefuse":["不丹王國的資源屬於人民與山林，恕難提供貢品。","我尊重貴國，但國民幸福不能以貢品交換。"],"giftThanks":["貴方的心意，我代不丹人民致謝。願友誼常青如林。","此禮如雪山甘泉，我深表感謝。願兩國幸福同行。"],"intel":["據我所知，{wars}正處於衝突，{peace}維持和平關係。","外交部門回報：{wars}已交戰，{peace}與不丹相安無事。"]}},"Turkey":{"name":"土耳其總統","title":"政府","tone":"外交辭令、沉穩務實，愛用「橋樑」「兩大洲」「一杯茶」等比喻，強調待客之道與國家尊嚴","portrait":"tr-modern","lines":{"intro":["我是土耳其總統，我國橫跨歐亞兩洲，向來是東西方的橋樑。","先喝杯紅茶吧，在土耳其，談任何事都是從一杯茶開始的。"],"contact":["貴國的人到了伊斯坦堡？請務必嘗嘗我們的烤肉與甜點。","海峽上的大橋連接兩大洲，也歡迎連接我們兩國的友誼。"],"war":["我國的忍耐已到極限，為了國家尊嚴，土耳其不得不採取行動。","茶已經涼了，談話也結束了，接下來由軍隊與貴國對話。"],"warReply":["貴國選擇了戰爭，土耳其深感遺憾，但我們絕不會退縮。","安納托利亞的土地上，從來沒有輕易低頭的民族。"],"peace":["我國的信念是家園和平、世界和平，願與貴國坐下來談。","戰火燒不出贏家，讓我們把大砲換成茶杯，重新開始。"],"accept":["土耳其接受這項協議，並將以最高規格的待客之道款待貴使。","很好，這是雙方共同的勝利，請收下這條地毯作為紀念。"],"reject":["這份條件不符合我國的國家利益，土耳其無法接受。","抱歉，我國的立場很清楚，請貴國拿出更有誠意的方案。"],"rebuff":["貴國拒絕了，我們尊重，但請記得，橋樑是雙向通行的。","土耳其的茶隨時都在，貴國改變心意時，歡迎再來。"],"betray":["局勢已經改變，我國經過審慎評估，決定終止這項協議。","土耳其的國家利益優先於任何協議，請貴國諒解。"],"truceEnd":["停戰期限已到，我國希望和平延續，但也已做好準備。","這段時間我國沒有浪費，希望貴國也用來想清楚了。"],"attacking":["土耳其的部隊已經出發，這是我國深思熟慮後的決定。","我們的無人機與軍艦正在路上，請貴國認真看待。"],"attacked":["安卡拉的防線正在承受重壓，但土耳其人不會輕易放棄。","海峽兩岸都聽得見砲聲了……政府仍在運作，我們還沒輸。"],"defeated":["土耳其政府就此謝幕，請善待這片橫跨兩洲的土地。","安納托利亞見過無數帝國興衰，這次，輪到我們了。"],"victory":["這是土耳其人民的勝利，星月旗將在兩大洲之間高高飄揚。","戰爭結束了，現在，讓我們泡一壺茶，談談重建的事。"],"allyAccept":["土耳其很高興與貴國結盟，我們的大門和茶壺永遠為朋友敞開。","很好，橋樑的兩端從此相連，願這份友誼經得起風浪。"],"allyReject":["感謝貴國的美意，但土耳其目前選擇保持獨立的外交立場。","橋樑不能只靠向一邊，我國暫時無法答應結盟，請見諒。"],"greetFriendly":["歡迎來到橫跨兩大洲的國度，先請你喝一杯茶。","土耳其願做東西方的橋樑，也願做你的朋友。"],"greetCold":["感謝來訊，我們會在適當時機給予正式回覆。","橋樑連結兩岸，但通行需要互相尊重。"],"threatDefy":["土耳其的國家尊嚴不容威脅，我們的立場非常清楚。","橫跨兩大洲的國家，見過的風浪比你想像的多。"],"threatYield":["為了區域穩定，我們願意重回談判桌。","一杯茶的時間，足以讓雙方冷靜下來。我們願意退讓。"],"tributePay":["基於區域和平考量，我方同意提供{gold}金的援助。","{gold}金作為友好基金，希望換來兩國長期穩定。"],"tributeRefuse":["土耳其是待客的主人，不是被索取的對象。","橋樑的通行費，不是由對岸來決定的。"],"giftThanks":["感謝厚禮，我們會回贈一套土耳其茶具以表心意。","待客之道是我們的傳統，你的禮物我們銘記在心。"],"intel":["根據外交部的訊息：{wars}正處於戰爭狀態，{peace}維持和平。","站在兩大洲的橋樑上看得清楚：{wars}交戰，{peace}安定。"]}},"Iran":{"name":"伊朗總統","title":"政府","tone":"外交辭令、沉穩含蓄，帶波斯詩意與待客之道，強調尊嚴與獨立","portrait":"ir-modern","lines":{"intro":["我是伊朗總統，代表我國政府向貴國致意。","波斯自古好客，願以一杯熱茶迎接新的朋友。"],"contact":["貴國人員造訪我國城市，我們以石榴與熱茶相待。","歡迎參觀，這座城市的地毯與詩歌都比高牆更值得看。"],"war":["我國政府已用盡外交手段，如今只能以行動回應。","伊朗人民珍視和平，但更珍視尊嚴，我們別無選擇。"],"warReply":["我國政府對貴國的決定深表遺憾，並將堅定自衛。","伊朗的歷史有三千年，我們知道如何面對風暴。"],"peace":["我國政府提議停火，讓詩人的聲音重新蓋過砲聲。","春分是新年，願兩國能在諾魯茲之前迎來和平。"],"accept":["我國政府接受這項協議，願它如波斯地毯般經久耐用。","好，讓我們以一杯番紅花茶，慶祝這份和平。"],"reject":["我國政府目前無法接受此案，條件仍待調整。","抱歉，這份提案還不夠平等，伊朗不會簽署不平等的協議。"],"rebuff":["我國尊重貴國的決定，但門仍為對話敞開。","遺憾貴國拒絕了，伊朗人民有的是耐心。"],"betray":["我國政府宣布退出協議，因為貴國未曾履行承諾。","條約若只約束一方，伊朗沒有理由繼續遵守。"],"truceEnd":["停火期限已屆，我國政府呼籲貴國審慎行事。","休戰結束了，接下來走向何方，取決於貴國的選擇。"],"attacking":["我國部隊已奉命出動，這是外交失敗後的無奈之舉。","伊朗的行動是為了守護人民，不是為了征服。"],"attacked":["首都承受重壓，但我國政府仍在運作，人民仍在堅守。","這片土地經歷過無數風暴，我們不會放棄。"],"defeated":["政府或許倒下，但波斯的詩歌與文化不會消失。","我國政府在此告別，願歷史記得伊朗人民的堅韌。"],"victory":["這場勝利屬於伊朗人民，我國政府願以此開啟和平。","戰爭結束了，讓我們回到談判桌，以茶代酒。"],"allyAccept":["我國政府欣然接受結盟，願兩國如石榴籽般緊密。","好，伊朗歡迎貴國成為夥伴，共享絲路的繁榮。"],"allyReject":["我國政府感謝貴國的善意，但目前不便締結同盟。","伊朗奉行獨立自主，結盟之事需再從長計議。"],"greetFriendly":["來信如春日的玫瑰般令人欣喜，願友誼如波斯詩篇般綿長。","波斯人常說賓客是上天的恩賜，我們的茶已備好。"],"greetCold":["來函已悉。本國向來以尊嚴與獨立為先，餘事再議。","問候已收到。詩人說，甜言需以行動印證，我們靜候。"],"threatDefy":["伊朗人民歷經千年風雨，不會因威嚇之詞而低頭。","我們以尊嚴回應壓力，這片高原從不向恫嚇屈膝。"],"threatYield":["為了區域和平與人民福祉，我們願意展現克制。","哈菲茲說忍耐終有回報，本國此次選擇以退為進。"],"tributePay":["本國同意提供{gold}金幣，僅為維護區域穩定。","這{gold}金幣是以待客之道相贈，不是屈服的貢品。"],"tributeRefuse":["伊朗的獨立不容交易，貢品之請，本國恕難接受。","我們願分享石榴與詩歌，卻不會以金幣換取尊嚴。"],"giftThanks":["感謝厚禮，願此誼如伊斯法罕的藍色穹頂般恆久。","薩迪說善意當以善意回報，我們將回贈一幅波斯地毯。"],"intel":["據本國外交部掌握，{wars}正處於戰爭狀態，{peace}已達成和平。","外交管道傳來消息：{wars}仍在交戰，{peace}已締結和約。"]}},"Iraq":{"name":"伊拉克總理","title":"伊拉克共和國政府","tone":"沉穩的外交辭令，常以兩河文明古國自居，好客務實，重視重建、水資源與能源合作，自稱我或我國","portrait":"iq-modern","lines":{"intro":["我是伊拉克總理，代表兩河流域的文明古國向您問候。","伊拉克是文字與法典的發源地，願與貴國以誠相交。"],"contact":["歡迎貴國友人來到巴格達，底格里斯河畔的椰棗請多嚐嚐。","貴國的代表團若有興趣，我們可安排參觀巴比倫遺址。"],"war":["外交途徑已經用盡，伊拉克政府不得不採取軍事行動。","為了保衛兩河的水與土地，我國正式向貴國宣戰。"],"warReply":["貴國選擇戰爭，伊拉克深感遺憾，但我們不會退讓。","這片土地經歷過太多戰火，我們比誰都懂得如何守住家園。"],"peace":["伊拉克提議停火，兩國人民都需要重建與安寧。","讓我們回到談判桌，油田與水源的問題都可以坐下來談。"],"accept":["伊拉克政府接受這項協議，願兩河之水從此只灌溉良田。","感謝貴國的誠意，我們會立即通知前線停止行動。"],"reject":["很抱歉，在貴國撤軍之前，伊拉克無法接受停火。","這份提案缺乏誠意，我國政府必須予以拒絕。"],"rebuff":["貴國拒絕了我們的善意，伊拉克對此深表遺憾。","我們尊重貴國的決定，但和平的大門隨時為您敞開。"],"betray":["情勢已有變化，伊拉克政府宣布終止先前的停火協議。","國家利益優先，我方不得不重新檢討這份協議。"],"truceEnd":["停火期限已屆滿，伊拉克將依國家利益決定下一步。","協議到期了，希望貴國記得上次談判的教訓。"],"attacking":["伊拉克軍隊已依命令向貴國邊境推進。","我們不願走到這一步，但部隊已經出發了。"],"attacked":["巴格達正遭受猛烈攻擊，我們呼籲國際社會關注。","這座城市曾多次從廢墟中站起，這一次也不會例外。"],"defeated":["政府已盡全力，伊拉克人民的韌性將延續下去。","兩河文明五千年不曾中斷，今日的挫敗也不會是終點。"],"victory":["伊拉克取得勝利，我們期盼與各國一同邁向重建。","感謝全體國民的堅持，今日的勝利屬於兩河人民。"],"allyAccept":["伊拉克欣然同意結盟，兩國將在能源與安全上密切合作。","歡迎成為伊拉克的夥伴，請到巴格達來簽署協議。"],"allyReject":["感謝貴國的提議，但伊拉克目前將維持中立立場。","結盟需要更多互信，我們建議先從經貿合作開始。"],"greetFriendly":["感謝您的問候。兩河文明的故鄉向來好客，歡迎您隨時來訪。","我國珍視這份友誼，期待在重建與能源領域深化合作。"],"greetCold":["已收到來信。我國目前專注於國內重建，暫無進一步回應。","感謝關切。雙方關係仍待具體行動證明，而非書信往來。"],"threatDefy":["我國歷經風雨仍屹立於兩河之間，不會因威脅而改變立場。","威脅無助於解決問題。我國的主權與尊嚴，沒有討價還價的餘地。"],"threatYield":["我國以重建為優先，願透過對話化解分歧，避免衝突升級。","為了人民的安寧，我國選擇克制，並希望貴方亦展現善意。"],"tributePay":["經內閣審慎評估，我國同意撥付 {gold} 金幣，以維持區域穩定。","這 {gold} 金幣視為對話的代價，我國期望換來長久的和平。"],"tributeRefuse":["我國的資源必須優先用於重建與民生，無法接受此項要求。","友誼建立在互相尊重之上，而非單方面的索取。恕難同意。"],"giftThanks":["衷心感謝這份厚禮。我國將以兩河故鄉的椰棗與友誼回敬。","貴方的心意我國銘記在心，期待雙方合作更上層樓。"],"intel":["據我國外交管道了解，{wars} 目前處於交戰狀態，{peace} 則維持和平。","我國持續關注區域局勢：{wars} 戰事仍在進行，{peace} 關係穩定。"]}},"Saudi Arabia":{"name":"沙烏地阿拉伯國王","title":"政府","tone":"沉穩的外交辭令，帶阿拉伯待客之道（咖啡、椰棗）與沙漠、能源、聖地的文化底色；自稱「我」「我國」，不影射真實人物","portrait":"sa-modern","lines":{"intro":["我是沙烏地阿拉伯國王，歡迎來到兩聖地之國，願往來平安順利。","沙漠教會我們耐心與好客，我國願以同樣的態度對待貴國。"],"contact":["貴國的訪客已到利雅德，我們準備了阿拉伯咖啡與椰棗迎接。","歡迎前來，沙漠中的城市正在轉型，希望貴國看見的不只是石油。"],"war":["我國多次呼籲克制，貴國置之不理，王國只能採取必要行動。","外交的管道已經用盡，沙烏地阿拉伯將以行動捍衛主權。"],"warReply":["貴國選擇了戰爭，我國深感遺憾，但王國不會退讓一寸沙土。","我們已通知盟友與國際社會，沙烏地阿拉伯將全力自衛。"],"peace":["戰爭讓油價與人心都不安穩，我國願意提議停火，重回談判桌。","沙漠的傳統是先請客人喝咖啡再談事情，我們先停火，再談。"],"accept":["我國接受這項協議，並將依國際慣例忠實履行。","很好，這是雙方人民都期盼的結果，歡迎貴國代表來利雅德簽署。"],"reject":["貴國的提案缺乏具體保證，我國此刻無法接受。","在貴國撤出我國邊境之前，停火的討論沒有基礎。"],"rebuff":["我國尊重貴國的決定，但也對這個結果深感遺憾。","談判的門不會關上，沙烏地阿拉伯隨時歡迎貴國回來。"],"betray":["鑑於貴國近期的行為，我國宣布停火協議自即日起失效。","王國認定協議已無法保障我國安全，因此不再受其約束。"],"truceEnd":["停火期限已屆，我國將重新評估與貴國的關係。","協議到期了，接下來的路怎麼走，取決於貴國的態度。"],"attacking":["我國部隊已依計畫展開行動，目標僅限於恢復安全。","沙烏地阿拉伯的軍隊已經出發，我們希望這一切盡快結束。"],"attacked":["利雅德受到嚴重威脅，我國正呼籲國際社會提供協助。","首都的燈火還亮著，王國會撐到最後一刻。"],"defeated":["沙烏地阿拉伯政府在此宣布停止抵抗，願人民免於更多苦難。","沙漠見證過許多王朝的起落，願它記得我們曾努力過。"],"victory":["感謝全體人民與盟友，沙烏地阿拉伯將以寬容對待戰後的和平。","勝利不是終點，我國願協助重建，讓這片土地重回安寧。"],"allyAccept":["我國同意結盟，願兩國像沙漠中的商隊，並肩同行。","歡迎成為沙烏地阿拉伯的夥伴，能源與安全，我們一起守護。"],"allyReject":["感謝貴國的誠意，但我國目前傾向保持獨立的外交立場。","結盟需要時間建立信任，就像沙漠裡的井要慢慢挖，我國暫不考慮。"],"greetFriendly":["感謝來信。我國以阿拉伯咖啡與椰棗待客，隨時歡迎貴國來訪。","兩國情誼如沙漠中的綠洲，我期待與貴國持續深化合作。"],"greetCold":["來信已收悉。我國將審慎評估雙方往來的適當方式。","我國重視每一位客人，但互信需要時間與行動累積。"],"threatDefy":["我國不接受任何形式的威脅，沙漠教會我們如何堅守。","貴國的措辭令人遺憾，我國主權與安全不容討價還價。"],"threatYield":["為區域穩定著想，我國願暫時退讓，回到談判桌上。","我國以和為貴，願作出適度讓步，避免局勢升溫。"],"tributePay":["我國同意提供{gold}金幣，作為維護區域和平的貢獻。","{gold}金幣將如期撥付，盼貴國以善意回應。"],"tributeRefuse":["我國的資源屬於全體國民，恕難應允這項要求。","待客之道是自願的慷慨，而非被迫的付出，我國婉拒。"],"giftThanks":["感謝貴國厚禮，我國將以最上等的椰棗與咖啡回贈。","貴國的心意我國銘記在心，願兩國友誼長存。"],"intel":["據我國外交管道掌握，{wars}目前處於交戰，{peace}維持和平。","我國觀察到：{wars}衝突持續，{peace}關係穩定。"]}},"Egypt":{"name":"埃及總統","title":"政府","tone":"穩重的外交辭令，語氣溫和但自信；常以尼羅河、金字塔、蘇伊士運河與文明古國的身分自豪，重視區域穩定與經貿合作。","portrait":"eg-modern","lines":{"intro":["我是埃及總統，代表尼羅河畔的人民，向貴國致意。","埃及是數千年文明的故鄉，也願與貴國共創新的未來。"],"contact":["貴國的朋友看到的是開羅，金字塔與現代大樓比鄰而立。","蘇伊士運河連接兩片海洋，埃及一向是世界貿易的橋樑。"],"war":["我國已用盡外交手段，如今不得不採取必要的行動。","埃及不主動尋求衝突，但貴國的行為已越過了底線。"],"warReply":["貴國選擇了對抗，埃及軍民將團結一致守護家園。","我們深感遺憾，但尼羅河的兒女從不畏懼挑戰。"],"peace":["埃及願意提議停火，讓對話取代砲火。","區域的穩定符合雙方利益，我國正式提出休戰建議。"],"accept":["埃及接受這項協議，期待兩國關係回到正軌。","很好，我國願意簽署，並邀請貴國代表來開羅作客。"],"reject":["很遺憾，目前的條件我國無法接受，談判暫時中止。","埃及重視和平，但不接受缺乏誠意的提案。"],"rebuff":["我國對貴國的拒絕表示遺憾，大門仍會為對話敞開。","埃及已表達善意，後續的發展，責任不在我方。"],"betray":["基於國家安全的最新評估，我國必須終止現行協議。","情勢已經改變，埃及必須以人民的利益為優先。"],"truceEnd":["停火協議已到期，我國將重新評估與貴國的關係。","休戰期結束了，希望雙方都珍惜這段時間換來的思考。"],"attacking":["埃及軍隊已經出動，這是捍衛國家利益的必要行動。","我國部隊正在前進，仍呼籲貴國儘早回到談判桌。"],"attacked":["開羅正面臨嚴峻考驗，但埃及人民不會放棄自己的首都。","情勢十分危急，我國仍在尋求一切可能的和平途徑。"],"defeated":["埃及政府就此落幕，但尼羅河與金字塔會永遠見證這片土地。","我們盡力了。願貴國善待這個古老而堅韌的民族。"],"victory":["勝利屬於埃及人民。我國願以寬容的態度重建區域秩序。","這場衝突結束了，埃及將繼續做和平與貿易的橋樑。"],"allyAccept":["埃及同意結盟，期待在經貿與文化上深化合作。","很榮幸與貴國並肩，願這份夥伴關係如尼羅河般長流。"],"allyReject":["感謝貴國的提議，但目前我國傾向維持中立立場。","埃及重視與各國的平衡關係，暫時不便締結同盟。"],"greetFriendly":["感謝您的問候。尼羅河兩岸的人民，向來樂於結交真誠的朋友。","很高興收到來信。埃及願與貴國在互信的基礎上深化合作。"],"greetCold":["來函已閱。埃及重視每一段關係，但更重視對方的實際作為。","感謝問候。有關具體事務，請透過正式外交管道再行溝通。"],"threatDefy":["金字塔屹立了數千年，埃及不會因為幾句威脅而動搖。","埃及一向以對話解決分歧，但也絕不接受任何形式的脅迫。"],"threatYield":["為了區域穩定，埃及願意展現彈性，盼貴國同樣保持克制。","我們理解貴國的關切。埃及將審慎調整，避免局勢升高。"],"tributePay":["基於維護區域和平，埃及同意提供{gold}金幣的援助款項。","這{gold}金幣，請視為埃及對雙邊關係的善意投資。"],"tributeRefuse":["埃及的資源屬於尼羅河兩岸的人民，恕難接受此項要求。","合作應建立在平等互惠之上，單方面的索取，埃及無法同意。"],"giftThanks":["感謝貴國的厚禮。這份心意，尼羅河的人民會銘記在心。","埃及衷心感謝。願這份友誼如蘇伊士運河，連接彼此的未來。"],"intel":["據外交評估，{wars}處於衝突，{peace}維持和平。","據我方掌握，{wars}仍有戰事，{peace}局勢穩定。"]}},"Israel":{"name":"以色列總理","title":"以色列政府","tone":"外交辭令、務實直接、帶一點幽默與科技創新色彩，自稱「我」或「我國」","portrait":"il-modern","lines":{"intro":["以色列人說「沙龍」，既是問候也是和平，我以此開場。","我是以色列總理，我國讓沙漠開花，也願與你共榮。"],"contact":["歡迎來到我國，這裡的滴灌技術能讓沙地長出蔬果。","你的人看到的是古老石牆與新創園區並存的城市。"],"war":["經多次警告無效，我國政府決定採取軍事行動。","我國向來不主動尋戰，但也從不迴避挑戰。"],"warReply":["我國注意到貴方宣戰，國防部門已完成準備。","我國的防禦系統與意志，都經得起考驗。"],"peace":["我國提議停火，讓兩國的孩子回到教室。","戰爭沒有贏家，我國願率先伸出橄欖枝。"],"accept":["我國接受協議，願這是長久合作的開始。","協議簽妥，我國將立即撤回邊境部隊。"],"reject":["貴方的條件損及我國安全底線，恕難接受。","在貴方停止越境行動前，我國不會簽署停火。"],"rebuff":["我國尊重貴方的決定，但大門始終為對話敞開。","遺憾。我國將持續透過各種管道尋求解方。"],"betray":["鑑於貴方違反協議精神，我國宣布協議失效。","我國曾信守承諾，但安全考量迫使我們改變立場。"],"truceEnd":["休戰期限已屆，我國期待延續，但也做好準備。","協議到期，我國願重返談判桌討論續約。"],"attacking":["我國部隊已依計畫行動，盼能儘早結束這場衝突。","行動已經展開，我國呼籲貴方盡早回到談判桌。"],"attacked":["首都遭受重創，但我國人民在困境中最為團結。","我國正協調緊急救援，並尋求國際社會協助。"],"defeated":["我國政府已盡全力，人民的故事不會就此結束。","這片土地見過太多興衰，我們終會再站起來。"],"victory":["我國感謝所有守護家園的人，勝利屬於他們。","戰事已了，我國將把資源轉回科技與教育。"],"allyAccept":["我國樂意結盟，兩國在科技與農業上大有可為。","協議達成，期待貴國代表團來訪，共享沙漠農業成果。"],"allyReject":["我國感謝貴方美意，但目前不宜締結軍事同盟。","基於區域平衡考量，我國暫時無法加入此一結盟。"],"greetFriendly":["平安！歡迎來嚐嚐鷹嘴豆泥和沙漠裡種出的番茄。","很高興收到您的訊息，我國隨時樂意分享滴灌與新創的經驗。"],"greetCold":["訊息已收到。我國的立場向來明確，請直接說明來意。","感謝問候。不過我行程很滿，客套話就省了吧。"],"threatDefy":["我國的防禦系統可不是擺著好看的，建議您三思。","威脅對我國沒用，我們連沙漠都能種出農田，還怕什麼？"],"threatYield":["為了區域穩定，我國願意暫時克制，但這不代表軟弱。","好吧，這一回我國選擇對話而非對抗，請珍惜這份善意。"],"tributePay":["我國同意提供{gold}金幣援助款，盼能促進雙方合作。","{gold}金幣已匯出，外交上這叫投資，不叫貢品。"],"tributeRefuse":["我國的預算要用在教育與科技研發，恕難提供貢金。","抱歉，我國從不繳貢，但很樂意談談技術合作。"],"giftThanks":["感謝厚禮！作為回禮，我國送您一箱死海泥面膜如何？","您的禮物已收到，我國會記得這份友誼，歡迎隨時來訪。"],"intel":["據我國情報：{wars}正在交戰，{peace}維持和平。","衛星顯示，{wars}戰事未歇，{peace}往來密切。"]}},"Italy":{"name":"義大利總理","title":"政府","tone":"外交辭令、從容優雅，帶一點咖啡、廣場、歌劇與地中海的生活氣息但不刻板，自稱「我」或「我國」","portrait":"it-modern","lines":{"intro":["您好，我是義大利總理。願兩國合作如一杯好咖啡，濃而不苦。","義大利政府向您致意。我們珍視歷史，也期待共同的未來。"],"contact":["貴國人員抵達羅馬了？歡迎，這裡的每塊石頭都有故事可講。","從古蹟到設計工坊，義大利歡迎所有帶著善意而來的訪客。"],"war":["外交手段已經用盡。義大利政府正式向貴國宣戰，深感遺憾。","我國不願走到這一步，但主權與人民的安全，不容退讓。"],"warReply":["貴國選擇了戰爭。義大利將依國際法自衛，並保留所有回應手段。","我們收到了宣戰通知。義大利人熱愛和平，但從不懼怕考驗。"],"peace":["戰爭沒有贏家。義大利政府提議立即停火，重回談判桌。","讓我們把爭議留給外交官，把廣場還給孩子與音樂。停戰吧。"],"accept":["義大利政府同意這項協議。今晚，羅馬的燈光會亮得更溫暖。","我們接受。願這份協議像文藝復興的壁畫，經得起時間考驗。"],"reject":["很遺憾，這份提案未能回應我國的核心關切，義大利無法接受。","我們尊重貴國的努力，但條件仍需調整。談判大門保持敞開。"],"rebuff":["貴國拒絕了我們的提議，義大利表示遺憾，並將重新評估局勢。","好的，我們理解。橄欖枝還在，只是暫時收回口袋。"],"betray":["情勢已發生根本變化，義大利政府決定終止現行停火協議。","為了國家利益，我國不得不重新檢視承諾。請貴國理解。"],"truceEnd":["停火協議今日到期。義大利政府呼籲雙方保持克制。","休戰期結束了。接下來的每一步，我們都會審慎評估。"],"attacking":["義大利軍隊已依內閣決議展開行動。我們的目標明確且有限。","行動開始。我國將盡力保護平民，也請貴國做到同樣的事。"],"attacked":["首都遭受重擊……但義大利政府仍在運作，人民仍在堅持。","古城牆撐過了兩千年，這一次，我們也不會輕易倒下。"],"defeated":["義大利政府已盡全力。願歷史記住我們曾如何守護這片土地。","我們輸了這場戰爭，但義大利的歌聲，不會就此沉默。"],"victory":["戰爭結束了。義大利政府感謝人民，也向對手致上敬意。","今晚，廣場上會有音樂。明天，我們回到重建與和平。"],"allyAccept":["義大利政府樂意與貴國結盟。合作的細節，讓我們在餐桌上談。","我們同意。地中海的陽光，願與朋友一同分享。"],"allyReject":["感謝貴國的邀請，但目前義大利選擇維持既有的外交路線。","我們珍視這份友誼，但結盟一事，時機尚未成熟。"],"greetFriendly":["感謝來信。歡迎來羅馬喝一杯濃縮咖啡，我們慢慢談。","我國一向珍視友誼，廣場上永遠有您的座位。"],"greetCold":["來信收悉。我國將在適當時機予以回應。","謝謝問候。目前我國的行程安排相當緊湊。"],"threatDefy":["我國聽不進威脅，只聽得進歌劇。","地中海見過太多風浪。我國不會因一封信而改變立場。"],"threatYield":["我國重視和平。此次，我們願意展現彈性。","為了避免衝突升溫，我國暫且接受貴國的條件。"],"tributePay":["我國同意提供 {gold} 金幣，並期待這是最後一次。","{gold} 金幣已撥付。願此舉換來地中海的平靜。"],"tributeRefuse":["我國的預算要用來修復古蹟與街道，恕難提供貢品。","這項要求不符合我國的外交原則。答覆是不。"],"giftThanks":["感謝厚禮。我國將以同樣的誠意回報，或許是一場歌劇。","禮物收到，如同一杯完美的濃縮咖啡，令人回味。多謝。"],"intel":["根據我國外交部的評估：與{wars}處於衝突，與{peace}維持和平。","外交簡報如下：{wars}為交戰方，{peace}為和平夥伴。"]}},"Spain":{"name":"西班牙首相","title":"西班牙政府","tone":"外交辭令、溫和自信，偶爾帶點南歐式的熱情與幽默，重視和平與文化交流","portrait":"es-modern","lines":{"intro":["您好，我代表西班牙政府向您致意，願合作如陽光般長久。","歡迎來到伊比利半島，我們的橄欖樹和誠意都很老牌。"],"contact":["貴方的人員抵達馬德里了？請他們在廣場喝杯咖啡再談。","這座城市歡迎所有訪客，也希望是以和平的名義。"],"war":["很遺憾，外交管道已經用盡，西班牙政府將採取行動。","我們一向珍惜和平，但也不會坐視主權受損。"],"warReply":["貴國選擇了對抗，西班牙政府深感遺憾，但會堅定回應。","我們寧願在談判桌上見面，但戰場上也不會缺席。"],"peace":["衝突已讓兩國人民付出代價，我提議立即停火。","讓我們回到談判桌，這才是文明國家該做的事。"],"accept":["西班牙政府接受停戰，願這是長久和平的開始。","很好，我會親自在馬德里迎接貴方代表團。"],"reject":["抱歉，目前的條件我無法向國會與人民交代。","我們願意談，但這份提案還需要更多誠意。"],"rebuff":["貴方拒絕了，我表示遺憾，但大門仍然敞開。","沒關係，西班牙人有的是耐心和陽光。"],"betray":["基於國家安全的新情勢，我國不得不中止停戰協議。","很遺憾，停戰已不符合西班牙人民的利益。"],"truceEnd":["停火期限已到，我方軍隊將恢復正常部署。","休戰結束了，希望我們很快能再簽一份長期協議。"],"attacking":["西班牙部隊已依國會授權出動，請貴方做好準備。","我們的行動有限而明確，只為保護國家利益。"],"attacked":["馬德里正承受攻擊，但西班牙政府仍在運作。","我們已撤離平民，政府會堅守到最後一刻。"],"defeated":["西班牙政府向人民致歉……願未來有人重建這片土地。","我以首相身分宣布政府解散，願和平終將降臨。"],"victory":["這場勝利屬於西班牙人民，明天我們就開始重建。","我們贏了，但我更希望這是最後一場戰爭。"],"allyAccept":["西班牙很榮幸與貴國結盟，願合作如地中海陽光般可靠。","好，讓我們的外交官與工程師一起開工。"],"allyReject":["感謝提議，但目前西班牙選擇保持策略上的獨立。","我們珍惜友誼，但結盟需要更多共識，暫且保留。"],"greetFriendly":["感謝來信！西班牙政府樂於深化與貴國的友誼與交流。","有朋友來信，就像陽光灑進辦公室，我們誠摯歡迎貴國。"],"greetCold":["西班牙政府已收到貴方問候，後續事宜將由外交部門處理。","我們對貴國的立場有所保留，但仍願保持溝通管道暢通。"],"threatDefy":["西班牙不接受任何威脅，我們將與盟友共同維護國際秩序。","威嚇無助於解決問題，西班牙人向來有面對困難的勇氣。"],"threatYield":["為避免局勢升高，西班牙政府願意作出適當的讓步。","我們選擇對話而非對抗，此次就依貴方所提方案處理。"],"tributePay":["西班牙政府同意提供{gold}金幣，期望以此換取區域穩定。","這{gold}金幣就當作和平的投資吧，希望貴國珍惜。"],"tributeRefuse":["西班牙的預算屬於人民，恕我無法同意這樣的要求。","我們願意談合作、談文化交流，但不談納貢。"],"giftThanks":["感謝貴國的厚禮，我們會回贈最好的橄欖油與友誼。","這份禮物讓內閣會議都變得愉快了，衷心感謝。"],"intel":["根據我方外交管道了解，{wars}正處於衝突，{peace}維持和平。","情報顯示{wars}戰事未平，{peace}局勢穩定，供貴國參考。"]}},"Netherlands":{"name":"荷蘭首相","title":"政府","tone":"務實直率、講求共識與貿易，帶一點自嘲式幽默，用外交辭令，自稱「我」或「荷蘭政府」","portrait":"nl-modern","lines":{"intro":["您好，我是荷蘭首相。我們是騎腳踏車來談生意的國家。","荷蘭有大片國土低於海平面，所以我們特別懂得合作。"],"contact":["歡迎來到荷蘭。港口、風車、鬱金香，還有很直接的談判風格。","您看到的是鹿特丹港，歐洲的貨物有不少從這裡上岸。"],"war":["荷蘭政府已窮盡外交手段，現在只能以武力回應。","我們不喜歡戰爭，但堤防與國土一樣，都必須守住。"],"warReply":["荷蘭政府對此深感遺憾，但我們的防線一向很牢固。","請記得，這個國家連海都擋得住，何況是一場宣戰。"],"peace":["荷蘭政府提議停火，讓談判桌取代戰場。","我們習慣坐下來把事情談清楚，這是荷蘭的傳統。"],"accept":["荷蘭政府接受這份協議。合作永遠比對抗划算。","很好，這正是我們說的共識模式，大家都退一步。"],"reject":["荷蘭政府審慎評估後，無法接受目前的條件。","我們願意談，但這份提案對荷蘭來說並不公平。"],"rebuff":["荷蘭政府尊重貴方的決定，但也會據此調整政策。","談判的門不會關上，荷蘭人有的是耐心。"],"betray":["荷蘭政府認為情勢已變，先前的協議不再適用。","我們必須把國家利益放在第一位，請貴方理解。"],"truceEnd":["停火協議已到期，荷蘭政府保留一切行動的選項。","期限到了。我們的談判代表已經回國，軍隊還在。"],"attacking":["荷蘭政府已授權軍隊行動，部隊正朝貴國前進。","我們不常出兵，所以一旦出兵，就是認真的。"],"attacked":["首都情勢嚴峻，但荷蘭政府仍在運作，人民也還在。","我們的城市曾多次從水災中重建，這次也不例外。"],"defeated":["荷蘭政府承認失敗，但荷蘭人民的韌性不會消失。","我們填海造陸過，總有一天也會重建這個國家。"],"victory":["荷蘭政府感謝各方，勝利之後首先要做的是重啟貿易。","戰爭結束了，我們會騎腳踏車去參加和平會議。"],"allyAccept":["荷蘭政府同意結盟，貿易與安全從此攜手並進。","很好，歡迎成為夥伴。我們會準備鬱金香當禮物。"],"allyReject":["荷蘭政府感謝貴方的邀請，但目前不打算加入同盟。","我們重視與所有國家的貿易，暫時不選邊站。"],"greetFriendly":["荷蘭政府收到你的問候，我剛騎腳踏車進辦公室呢。","很高興聽到你的消息，有空來鹿特丹港看看吧。"],"greetCold":["荷蘭政府已收悉來函，後續將依既定程序處理。","我們注意到你的問候，也注意到之前的一些事。"],"threatDefy":["荷蘭連海都能填出土地，不會被幾句狠話嚇退。","我建議你重新考慮，我們的盟友可不只有堤防。"],"threatYield":["好吧，荷蘭政府願意讓步，貿易比面子重要。","我把這個帶回內閣討論過了，共識是：先退一步。"],"tributePay":["{gold}金幣已撥付，我會跟國會解釋這是『投資』。","荷蘭政府支付{gold}金幣，請把它當作維持關係的成本。"],"tributeRefuse":["荷蘭人連咖啡錢都各付各的，更不會替威嚇買單。","這項要求不符合荷蘭政府的預算原則，恕難同意。"],"giftThanks":["謝謝你的禮物，我會回贈一箱鬱金香球根，春天見。","荷蘭政府感謝這份心意，這比任何公文都更有效。"],"intel":["根據外交部簡報：{wars}正在交戰，{peace}維持和平。","我們的貿易代表回報，{wars}戰事未停，{peace}則生意照做。"]}},"Switzerland":{"name":"瑞士聯邦主席","title":"聯邦委員會","tone":"溫和穩重、講求共識與中立，滿口外交辭令，偶爾帶點手錶般的精準與巧克力般的親切。","portrait":"ch-modern","lines":{"intro":["我是瑞士聯邦主席，代表聯邦委員會向您問好。","瑞士向來中立，但中立不代表沉默，歡迎隨時對話。"],"contact":["貴方人員抵達伯恩了？請享用一塊巧克力，慢慢談。","我們的城市不大，但每一座橋、每一班火車都準時。"],"war":["聯邦委員會極不情願地宣布：瑞士將行使自衛權。","貴方的行動越過了紅線，瑞士的中立從不等於軟弱。"],"warReply":["貴方選擇了戰爭，瑞士遺憾地接受，並將依法自衛。","阿爾卑斯的山口已經關閉，貴方的軍隊將寸步難行。"],"peace":["瑞士提議停戰，並願意提供日內瓦作為談判場地。","讓我們回到談判桌，瑞士人相信協商勝過砲火。"],"accept":["聯邦委員會一致同意，停戰協議自即刻生效。","很好，這份協議我們會像對待手錶一樣，準確履行。"],"reject":["很遺憾，貴方的條件無法通過我國的公民投票。","瑞士願意談，但不會在軍隊仍越界時簽署任何文件。"],"rebuff":["貴方拒絕了。瑞士的大門仍然敞開，隨時歡迎回來。","我們尊重貴方的決定，但也會相應調整邊境部署。"],"betray":["經聯邦委員會決議，瑞士不得不終止此項停戰協議。","貴方的行為已違反協議精神，我們無法再繼續遵守。"],"truceEnd":["停戰期限已屆，瑞士將恢復正常的邊境防務。","協議到期了，希望我們能用新的協議取代舊的。"],"attacking":["瑞士軍隊已經出動。這是自衛，不是征服，請理解。","我們的行動將嚴格遵守國際法，包括對待貴方的平民。"],"attacked":["伯恩告急……但瑞士每一座山都可以是首都。","政府已轉移至山區，我們的抵抗不會因一座城而停止。"],"defeated":["瑞士聯邦……暫時失去了主權。請善待我們的人民。","中立被打破了，但瑞士人心中的山谷永遠不會投降。"],"victory":["戰爭結束了。瑞士不要領土，只要重新回到談判桌。","現在，讓我們把精力放回貿易與重建，這才是瑞士。"],"allyAccept":["瑞士願與貴國深化合作，在國際法的架構下並肩。","很好，我們的夥伴關係將像瑞士火車一樣，準時可靠。"],"allyReject":["抱歉，瑞士的永久中立不允許簽署任何軍事同盟。","我們可以是貴國最可靠的朋友，但無法成為盟友。"],"greetFriendly":["感謝來函。瑞士歡迎每一位願意對話的朋友。","願我們的友誼如瑞士鐘錶般精準，如巧克力般溫暖。"],"greetCold":["來函收悉。基於中立原則，本人不便多言。","聯邦委員會將審慎評估，感謝您的關注。"],"threatDefy":["瑞士堅守中立，但中立不代表軟弱，請三思。","聯邦委員會已達成共識：我們不接受任何威嚇。"],"threatYield":["瑞士素來不以武力示人，我們願意坐下來談。","為維護和平，聯邦願作適度調整，請保持克制。"],"tributePay":["經委員會決議，撥付{gold}金幣，盼雙方關係回歸正軌。","{gold}金幣已匯出，準時如鐘錶。願以此換取穩定。"],"tributeRefuse":["瑞士不繳納任何貢品，這與我們的中立原則相悖。","很遺憾，聯邦委員會無法同意此項要求。"],"giftThanks":["厚禮收悉，聯邦委員會謹致謝忱。願回贈一盒巧克力。","感謝您的心意。瑞士珍視每一份善意的交流。"],"intel":["據外交管道：{wars}交戰中，{peace}已和解。","中立觀察所見：{wars}正交戰，{peace}已停火。"]}},"Sweden":{"name":"瑞典首相","title":"政府","tone":"冷靜克制、講求共識與國會程序，外交辭令中帶北歐式的坦率與務實，重視和平、環境與人民福祉。","portrait":"se-modern","lines":{"intro":["您好，我代表瑞典政府向您問候，期待建立互信。","瑞典重視對話與共識，希望我們能從咖啡與交流開始。"],"contact":["歡迎貴國人員造訪斯德哥爾摩，願這是友好往來的開端。","我們的城市向世界開放，請自在參觀，遵守共同的規範。"],"war":["瑞典政府已窮盡外交手段，遺憾必須採取軍事行動。","我們不輕言戰爭，但主權與人民安全不容退讓。"],"warReply":["瑞典對貴國的宣戰深表遺憾，我們將全力自衛。","我們始終尋求和平，但也做好了守護國土的準備。"],"peace":["瑞典政府提議立即停火，讓談判桌取代戰場。","衝突對雙方人民都是損失，我們願意先伸出手。"],"accept":["瑞典政府接受這項協議，並將如實履行每一條款。","感謝貴國的誠意，讓我們一起把和平變成日常。"],"reject":["很遺憾，目前的條件瑞典政府無法接受，請再研議。","我們願意繼續對話，但這份提案還不足以保障和平。"],"rebuff":["我們尊重貴國的決定，但瑞典會為此調整立場。","遺憾提案未被接受，我們將以其他方式保障國家安全。"],"betray":["情勢已根本改變，瑞典政府不得不終止停火協議。","我們對此深表遺憾，但國家安全迫使我們採取行動。"],"truceEnd":["停火期限已屆，瑞典政府將重新評估雙邊關係。","協議到期了，我們希望接下來仍能以對話為先。"],"attacking":["瑞典部隊已依法出動，我們將嚴守國際規範行動。","行動已經開始，瑞典政府仍為談判保留一扇門。"],"attacked":["首都面臨嚴峻壓力，但瑞典政府與人民不會屈服。","我們正在承受重擊，仍呼籲立即停火、回到談判。"],"defeated":["瑞典政府已盡最大努力，願人民與和平長存。","北方的寒冬會過去，瑞典的精神不會消失。"],"victory":["瑞典感謝所有守護和平的人，願衝突就此結束。","勝利不是目的，重建互信才是我們接下來的工作。"],"allyAccept":["瑞典政府同意結盟，我們將以誠信履行盟約。","北方的夥伴關係值得珍惜，期待與貴國並肩合作。"],"allyReject":["此事須經國會審慎討論，瑞典政府目前不便承諾。","我們珍惜與貴國的友誼，但結盟需要更多討論。"],"greetFriendly":["感謝來信，瑞典願與貴國在互信中深化合作。","很高興收到問候，歡迎隨時來斯德哥爾摩喝杯咖啡。"],"greetCold":["來信已收悉，相關事宜將依國會程序處理。","我們注意到貴國的訊息，目前沒有進一步回應。"],"threatDefy":["瑞典不接受威脅，我們的立場由國會決定。","坦白說，這種語氣無助於對話，請貴國冷靜。"],"threatYield":["為了人民的安全，我們願意坐下來重新協商。","瑞典選擇對話而非對抗，此事暫依貴國提議。"],"tributePay":["國會已通過撥款{gold}金幣，以維護區域穩定。","{gold}金幣將依程序撥付，但我們保留發言權。"],"tributeRefuse":["納稅人的錢不能這樣用，國會不會同意的。","瑞典的預算用於福利與環境，恕難照辦。"],"giftThanks":["感謝貴國的禮物，這份善意我們銘記在心。","禮物已收到，期待雙方在永續議題上攜手。"],"intel":["據外交部：{wars}交戰中，{peace}維持和平。","據公開資訊，{wars}正在交戰，{peace}已締和。"]}},"Norway":{"name":"挪威首相","title":"政府","tone":"沉穩、務實、講求平等與透明，重視和平調解與環境保護，帶一點北歐式的含蓄幽默。自稱「我」或「本人」，常以「挪威政府」發言。","portrait":"no-modern","lines":{"intro":["您好，我是挪威首相，代表峽灣與北海的人民向您問候。","挪威雖小，但我們相信小國也能在世界上發揮作用。"],"contact":["歡迎來到奧斯陸，這裡的冬天很長，但人們的心很暖。","您的人看到的是我們的港口，漁船和油輪並排停著。"],"war":["挪威政府已用盡外交手段，遺憾地宣布進入戰爭狀態。","我們不願走到這一步，但保衛家園是政府的責任。"],"warReply":["挪威收到貴國的宣戰，我們會以冷靜與決心回應。","我們是愛好和平的國家，但這不代表我們不會自衛。"],"peace":["挪威提議停火，讓我們回到談判桌，這是我們最擅長的事。","戰爭沒有贏家，本人願意親自主持和談。"],"accept":["挪威政府接受停戰，我們會向國際社會公布這份協議。","感謝您的決定，和平協議是最好的外交成果。"],"reject":["很遺憾，貴國的條件目前無法讓挪威國會接受。","挪威重視和平，但不接受單方面的條件。"],"rebuff":["我們理解貴國的立場，挪威的大門仍然為談判敞開。","遺憾您拒絕了，但挪威不會停止尋求和平的努力。"],"betray":["情勢已經改變，挪威政府必須重新評估這份協議。","本人必須向國民負責，這份協議挪威無法再遵守。"],"truceEnd":["休戰期已結束，挪威希望雙方能延續克制。","協議到期了，我們仍準備好隨時重返談判桌。"],"attacking":["挪威國會已授權，我們的部隊正依國際法展開行動。","這不是我們想要的，但挪威人一旦決定，就會堅持到底。"],"attacked":["奧斯陸正面臨攻擊，但挪威政府不會離開人民。","峽灣裡的每一個村莊都在堅守，我們不會放棄。"],"defeated":["挪威政府已盡全力，請善待我們的人民與這片土地。","這片峽灣見證過許多風雪，挪威人會再次站起來。"],"victory":["挪威獲得了勝利，但我們會第一時間邀請對方重建關係。","勝利屬於挪威人民，現在請讓我們回歸和平。"],"allyAccept":["挪威政府同意結盟，北方的合作精神歡迎您加入。","結盟成立，願我們的合作像北極光一樣長久而明亮。"],"allyReject":["挪威目前選擇不捲入戰事，但仍願意做貴國的朋友。","感謝邀請，但挪威國會目前不打算加入新的同盟。"],"greetFriendly":["挪威政府感謝您的問候，歡迎有空來看看峽灣。","來信收到，本人很高興。北方雖冷，我們待朋友很熱。"],"greetCold":["挪威政府已收到來信，目前沒有進一步回應。","問候收悉。我們一向重視實際行動，勝過客套話。"],"threatDefy":["挪威政府不接受威脅。我們習慣面對風雪，也不怕這個。","威脅在挪威行不通。我們比較習慣坐下來談，但也不會退。"],"threatYield":["為了避免衝突升高，挪威政府願意暫時讓步。","我們選擇和平。這不是軟弱，是挪威一貫的做法。"],"tributePay":["挪威政府將撥付{gold}，這筆錢會向國會公開說明。","好吧，{gold}送去。我們的石油基金，禁得起這一筆。"],"tributeRefuse":["挪威政府恕難同意。國家預算每一筆都要透明，這筆說不過去。","抱歉，這筆錢我們寧可拿去種樹，也不會這樣付出去。"],"giftThanks":["挪威政府誠摯感謝。依規定，這份禮物會公開登記。","謝謝您的心意。我們會回贈一些鮭魚，希望您不介意。"],"intel":["據挪威政府掌握，{wars}正在交戰，{peace}已達成和平協議。","我們的外交部回報：{wars}衝突持續，{peace}維持和平。"]}},"Finland":{"name":"芬蘭總統","title":"芬蘭共和國政府","tone":"冷靜務實、話少但誠懇，帶北歐式含蓄幽默，愛提森林、湖泊、桑拿與「西蘇」韌性，外交辭令得體。","portrait":"fi-modern","lines":{"intro":["你好，我是芬蘭總統，很高興透過這片森林與湖泊向你問候。","芬蘭人話不多，但每一句都算數，希望我們合作愉快。"],"contact":["你的代表團抵達赫爾辛基了？冬天請記得多穿一件。","歡迎來到千湖之國，我們的城市不大，但很安靜。"],"war":["我國已用盡外交手段，芬蘭別無選擇，只能宣戰。","芬蘭人不輕易開戰，但一旦決定，就會撐到最後。"],"warReply":["我對貴國的決定深感遺憾，芬蘭會冷靜地做好準備。","我們的冬天很長，耐心也是，這一點請你記住。"],"peace":["我建議雙方停火，坐下來談，芬蘭願意提供會談場地。","戰爭沒有贏家，讓我們把資源用在學校而不是戰壕。"],"accept":["芬蘭政府接受這項協議，感謝貴國展現的誠意。","很好，簽完字之後，我請你到湖邊的桑拿好好談談。"],"reject":["抱歉，這份提案的條件我國無法接受，請重新考慮。","芬蘭重視和平，但更重視公平，這份和約缺了後者。"],"rebuff":["我尊重貴國的決定，但芬蘭的大門隨時為對話敞開。","好吧，看來我們得再等一個冬天，才能重新談起。"],"betray":["情勢逼迫我國中止協議，芬蘭政府為此正式表達遺憾。","保護國民是我的第一責任，即使必須撕毀這份和約。"],"truceEnd":["停火期已結束，希望這段時間的平靜能延續下去。","協議到期了，芬蘭仍然願意繼續對話，這扇門沒有關。"],"attacking":["芬蘭國防軍已經出發，這是國會授權的最後手段。","我們的部隊熟悉雪地與森林，請貴國認真看待這一點。"],"attacked":["赫爾辛基受創嚴重，但政府仍在運作，人民仍在堅持。","芬蘭人稱它為『西蘇』，一種不肯放棄的韌性，你正在見識它。"],"defeated":["芬蘭政府正式停止抵抗，請貴國依國際規範善待平民。","森林和湖泊還在，芬蘭人會像每個春天一樣重新站起。"],"victory":["這場衝突結束了，芬蘭不慶祝勝利，只慶祝和平回來。","謝謝各位，現在讓我們回家，把桑拿的火重新升起。"],"allyAccept":["芬蘭政府同意結盟，我們會是一個安靜但可靠的夥伴。","很好，盟友之間不需要太多客套，需要的是準時和守信。"],"allyReject":["感謝貴國的提議，但芬蘭此刻需要先顧好自己的方向。","結盟是重大承諾，芬蘭人習慣先想清楚再開口。"],"greetFriendly":["來信收到。芬蘭的湖泊有千個，朋友永遠不嫌多。","歡迎來赫爾辛基。我們可以在桑拿裡把話說清楚。"],"greetCold":["已閱。芬蘭人話不多，這封回信也是。","感謝來信。目前雙方的關係，維持禮貌即可。"],"threatDefy":["芬蘭人有『西蘇』，在冰天雪地裡從不退縮。請自便。","我們的冬天零下三十度都熬過了，不差你這封信。"],"threatYield":["芬蘭一向務實。既然情勢如此，我們願意坐下來談。","為了人民的安寧，芬蘭選擇克制。這不是軟弱。"],"tributePay":["芬蘭政府撥付 {gold} 金幣。這筆錢本可以多蓋幾座桑拿。","{gold} 金幣已匯出。我們不喜歡這樣，但我們守信用。"],"tributeRefuse":["芬蘭的預算屬於納稅人，總統無權拿來送人。","我們的答覆很北歐：不。祝你有個美好的一天。"],"giftThanks":["謝謝你的禮物。芬蘭人不善表達，但心裡是很高興的。","禮物收到了。下次來，我請你蒸桑拿、看極光。"],"intel":["外交部的情報顯示：{wars}正在交戰，{peace}維持和平。","湖邊的消息傳得很快：{wars}打起來了，{peace}握了手。"]}},"Iceland":{"name":"冰島總理","title":"政府","tone":"務實友善、講求平等與環保的北歐外交風格；喜歡以火山、冰河、漁業、地熱、全球最古老議會作比喻，語氣輕鬆但有原則。","portrait":"is-modern","lines":{"intro":["我是冰島總理，代表全世界最古老的議會向您問好。","冰與火之國歡迎您，希望我們的關係像地熱一樣溫暖。"],"contact":["您的人看見雷克雅維克了，別驚訝，我們沒有軍營。","那不是煙，是地熱蒸氣，歡迎來喝杯咖啡談談。"],"war":["冰島從不主動宣戰，但您逼得我們別無選擇。","很遺憾，外交已經用盡，我國將採取一切必要手段。"],"warReply":["向冰島宣戰？我們連鱈魚戰爭都撐過來了。","我們沒有軍隊，但有火山般的耐心，和火山般的脾氣。"],"peace":["我們都是小國，何必互相消耗？我提議停火。","冰島人相信談判桌，讓我們把爭端交給外交吧。"],"accept":["我國接受，這是雙方人民都樂見的結果。","好，就這麼定了，下次歡迎來泡溫泉慶祝。"],"reject":["這份提案不符合冰島的核心利益，恕難接受。","很抱歉，我國議會不會通過這樣的條件。"],"rebuff":["您拒絕了？冰島會尊重，但也會記得。","沒關係，火山也是慢慢累積的，我們有耐心。"],"betray":["情勢已變，我國不得不重新評估這份協議。","很遺憾，冰島議會決議終止停戰，這是主權的選擇。"],"truceEnd":["停戰期已滿，我們回到原點，但溝通管道保持暢通。","協議到期了，接下來的方向，由雙方各自決定。"],"attacking":["冰島海岸防衛隊已經出動，這是我國最不願做的決定。","我們出發了，像極光一樣，您看見時已經來不及。"],"attacked":["雷克雅維克告急，但冰島人經歷過火山與寒冬。","城市可以重建，我們連火山灰都清過好幾次。"],"defeated":["冰島政府在此正式投降，請善待我們的人民與土地。","議會的傳統會留下來，一千年前如此，今後也是。"],"victory":["冰島贏了，不靠軍隊，靠的是整個國家的韌性。","這一天值得在國會廣場放個假，全民泡溫泉。"],"allyAccept":["冰島樂意結盟，北大西洋的風總是需要朋友。","同盟成立，我們的地熱與漁獲都願與您分享。"],"allyReject":["冰島珍惜獨立與自主，目前不宜加入這份同盟。","感謝您的提議，但我國議會傾向保持距離。"],"greetFriendly":["感謝來訊！冰島的地熱溫暖，我們的友誼也是。","很高興收到問候，歡迎隨時來冰島泡個溫泉。"],"greetCold":["訊息收到。冰島的冰河移動得慢，我們的信任也是。","感謝問候。目前沒有需要進一步討論的議題。"],"threatDefy":["冰島人與火山共處千年，不會被幾句威脅嚇到。","我們沒有軍隊，但有全世界最老的議會和最硬的骨氣。"],"threatYield":["冰島是小國，我們會審慎處理，避免情勢升溫。","我們選擇對話而非對抗，這件事就先依你的意思。"],"tributePay":["冰島政府同意支付{gold}金幣，換取區域的穩定。","{gold}金幣已匯出。希望這筆錢能像地熱一樣暖人心。"],"tributeRefuse":["冰島的漁獲和地熱屬於全體國民，恕難奉送。","平等的夥伴之間不談貢品，這是我們的原則。"],"giftThanks":["謝謝你的禮物！我們會回贈一箱冰島的鱈魚乾。","這份心意像極光一樣令人難忘，冰島感謝你。"],"intel":["根據我們的外交情報，{wars}正在交戰，{peace}維持和平。","漁船和衛星都看得清楚：{wars}在打仗，{peace}很平靜。"]}},"Poland":{"name":"波蘭總統","title":"政府","tone":"穩重、有禮、外交辭令；偶爾引用蕭邦、華沙重建、琥珀、餃子等文化意象，語氣帶一點歷經風霜的堅韌，自稱「我／本人／我國」","portrait":"pl-modern","lines":{"intro":["您好，我是波蘭總統。願蕭邦的琴聲為我們的會面開場。","波蘭經歷過瓜分與重建，我們深知和平得來不易。"],"contact":["歡迎來到華沙。這座老城曾從瓦礫中重建，請多看看。","貴國的訪客已抵達，我國願以餃子與熱茶招待。"],"war":["經內閣審慎評估，波蘭共和國正式向貴國宣戰。","我國外交已盡最大努力，很遺憾，如今只剩這條路。"],"warReply":["本人已收到貴國的宣戰聲明，波蘭將全力保衛國土。","歷史上我們曾從地圖上被抹去，但每一次都重新站起來。"],"peace":["衝突已對雙方人民造成損失，我國提議立即停火。","讓我們坐回談判桌，波蘭願意先遞出橄欖枝。"],"accept":["波蘭政府接受這項協議，並將依國際法確實履行。","感謝貴國的誠意，這是兩國人民共同的好消息。"],"reject":["貴國的方案未能保障我國安全，恕本人無法接受。","波蘭珍視和平，但不會以主權作為交換條件。"],"rebuff":["本人對貴國的決定深表遺憾，談判之門仍然敞開。","很可惜，波蘭願意等，但也做好了應對的準備。"],"betray":["鑑於局勢重大變化，我國宣布終止現行停戰協議。","本人為此決定負全責，波蘭的安全不容再等待。"],"truceEnd":["停戰協議今日屆滿，我國保留一切選項。","協議期限已到，波蘭仍願透過對話尋求長久和平。"],"attacking":["我國部隊已依計畫出動，這是波蘭不得已的決定。","白鷹已經展翅，我國軍隊將以最專業的方式行動。"],"attacked":["華沙正承受猛烈攻擊，但政府依然運作，人民依然堅守。","這座城市曾被夷平又重建，我們知道怎麼撐過去。"],"defeated":["波蘭政府在此停止抵抗，請善待我國人民。","歷史證明，波蘭從地圖上消失過，也總會再回來。"],"victory":["戰事結束了。波蘭不求報復，只求長久的和平。","感謝將士與人民，接下來讓我們把精力用在重建。"],"allyAccept":["波蘭同意締結同盟，我們深知患難之交的價值。","很榮幸與貴國並肩，願這份友誼如琥珀般長久。"],"allyReject":["經審慎評估，我國現階段不宜加入這項同盟。","感謝貴國的邀請，但波蘭必須先顧好自己的邊境。"],"greetFriendly":["感謝來信。華沙的秋天很美，歡迎貴方隨時來訪。","本人謹代表我國致意，願兩國友誼如琥珀般長久。"],"greetCold":["來函已收悉。我國將在適當時機作出回應。","本人注意到貴方的問候，相關事宜交由外交部處理。"],"threatDefy":["華沙曾從瓦礫中重建，我國不會被任何威脅嚇倒。","本人鄭重聲明：我國的主權不容討價還價。"],"threatYield":["為了區域穩定，我國願意回到談判桌，先降低緊張。","本人不願讓人民再經歷戰火。我國選擇克制。"],"tributePay":["我國將撥付{gold}金幣，作為維護和平的特別款項。","本人批准{gold}金幣的支付，但這不代表我國屈服。"],"tributeRefuse":["我國的預算屬於人民，不會用來繳納任何貢金。","本人恕難同意。波蘭已不再是任人索取的國家。"],"giftThanks":["衷心感謝厚禮。我國將回贈琥珀與一場蕭邦音樂會。","本人代表我國致謝，改日請貴方來嚐嚐華沙的餃子。"],"intel":["據我國外交部評估，{wars}態度強硬，{peace}立場友好。","本人可以透露：{wars}正在增兵，{peace}與我國保持對話。"]}},"Ukraine":{"name":"烏克蘭總統","title":"政府","tone":"沉穩務實的外交辭令，重視主權與尊嚴，常以麥田、黑土、向日葵、麵包與鹽等烏克蘭意象比喻，溫和但不退讓。","portrait":"ua-modern","lines":{"intro":["您好，我是烏克蘭總統。願兩國的合作如黑土上的麥田般豐收。","烏克蘭以麵包與鹽迎接朋友，願我們之間永遠只有這一種迎接。"],"contact":["歡迎您的人民來訪。基輔的栗子樹正開花，值得停下來看看。","您看到的是烏克蘭的領土。我們歡迎訪客，也期待對方尊重邊界。"],"war":["烏克蘭政府決定行使自衛權。這不是我們所願，但我們不會退。","外交努力已經用盡。我在此正式通知貴國：烏克蘭將採取行動。"],"warReply":["我們收到貴國的宣戰。烏克蘭人不主動求戰，但也從不畏懼。","很遺憾走到這一步。請記住，這片黑土上的人很擅長守護家園。"],"peace":["烏克蘭提議停火。資源該用在麥田與學校，而不是戰場。","我願意坐上談判桌。向日葵朝著太陽生長，人民也該朝著和平。"],"accept":["烏克蘭接受這項協議。我們會遵守承諾，也期待貴國同樣如此。","感謝貴國的誠意。今天簽下的名字，會被兩國的孩子記住。"],"reject":["很抱歉，這份提案不符合烏克蘭的核心利益，我們無法接受。","和平必須建立在尊重主權之上。在此之前，我們不會停下腳步。"],"rebuff":["我們對貴國的決定感到遺憾。烏克蘭的大門仍開著，隨時歡迎。","既然貴國拒絕，烏克蘭將重新評估下一步。希望這不是最終答案。"],"betray":["情勢已經改變。烏克蘭政府宣布，先前的停火協議即刻終止。","我必須對人民負責。當協議無法保障他們的安全，它就不再有效。"],"truceEnd":["停火期限已屆。烏克蘭遵守了每一項條款，接下來由行動說話。","協議到期了。感謝這段平靜，希望它能延續，但我們已做好準備。"],"attacking":["烏克蘭部隊已經出發。我們不為征服而來，只為結束這場衝突。","行動開始了。請貴國明白，這是我們反覆勸告無效後的選擇。"],"attacked":["基輔正承受攻擊……但政府仍在運作，人民仍在崗位上。","你們打到首都了。可是烏克蘭不只是一座城，它在每個人心裡。"],"defeated":["這是我以總統身分的最後一次發言：烏克蘭的麥田，會再次金黃。","政府倒下了，但歌謠、麥田與人民都還在。歷史不會在今天結束。"],"victory":["烏克蘭贏得了這場考驗。現在，讓我們談談如何一起重建。","感謝每一位守護家園的人。今天基輔的鐘聲，是為和平而響。"],"allyAccept":["烏克蘭很榮幸與貴國結盟。朋友之間，以麵包與鹽相待。","我代表烏克蘭人民接受盟約。願這份友誼，像黑土一樣深厚。"],"allyReject":["感謝貴國的提議，但烏克蘭目前不打算加入任何新的同盟。","結盟需要信任，而信任需要時間。讓我們先從貿易與交流開始。"],"greetFriendly":["感謝來信。烏克蘭以麵包與鹽迎接朋友，願兩國情誼如麥田常青。","向日葵總是朝著光。貴國的善意，我們看見了，也珍惜。"],"greetCold":["來函已收悉。烏克蘭珍惜每一位鄰居，但信任需要時間耕耘。","我方已閱讀貴國訊息。目前沒有進一步回應，請見諒。"],"threatDefy":["烏克蘭的黑土見證過太多風暴，我們仍在。主權不容談判。","威脅無法讓麥田低頭。烏克蘭將以尊嚴回應每一次恐嚇。"],"threatYield":["我方無意升高衝突。為了人民的安寧，願意坐下來談條件。","烏克蘭珍惜和平勝過一切。貴國的要求，我們會審慎考量。"],"tributePay":["我方將支付{gold}金幣，以換取邊境的安寧與麥田的收成。","{gold}金幣已撥付。願這筆款項成為和平的種子，而非戰火。"],"tributeRefuse":["烏克蘭的麵包分給朋友，不繳給施壓者。恕難同意。","主權國家不納貢。我方尊重貴國，也請貴國尊重烏克蘭。"],"giftThanks":["衷心感謝。烏克蘭將以麵包與鹽回禮，願友誼如向日葵向陽。","貴國的心意我們收到了。這份善意會被記在基輔的春天裡。"],"intel":["根據我方外交部資訊：與{wars}處於交戰，與{peace}維持和平。","目前烏克蘭與{wars}處於交戰狀態，與{peace}則保持友好往來。"]}},"Greece":{"name":"希臘總理","title":"政府","tone":"外交辭令、沉穩理性、帶民主發源地與海洋文化的自豪，自稱我","portrait":"gr-modern","lines":{"intro":["我是希臘總理，來自民主誕生的土地，很高興與你會面。","希臘願以對話開啟關係，這是雅典兩千五百年來的傳統。"],"contact":["你們看見的是雅典，衛城仍守望著這座現代都市。","歡迎來到愛琴海之濱，這裡的港口向所有朋友開放。"],"war":["外交手段已經用盡，希臘政府不得不採取軍事行動。","我們珍視和平，但更珍視國家的主權與尊嚴。"],"warReply":["希臘政府對此深表遺憾，我們將全力保衛國土。","從馬拉松到今日，希臘人從不畏懼強大的對手。"],"peace":["希臘提議停火，讓我們回到談判桌前。","戰爭沒有贏家，我提議以橄欖枝取代砲火。"],"accept":["希臘政府接受這份協議，願它如地中海的陽光般長久。","很好，我們的外交部長將立即安排簽署事宜。"],"reject":["很抱歉，目前的條件希臘無法接受。","議會不會通過這樣的協議，請提出更平等的方案。"],"rebuff":["我尊重你的決定，希臘的大門仍然敞開。","遺憾，但希臘會繼續尋找和平的可能。"],"betray":["情勢已根本改變，希臘政府必須重新評估協議。","為了國家安全，我不得不宣布協議中止，深感遺憾。"],"truceEnd":["停火協議已到期，雙方的分歧仍待解決。","希臘希望延續和平，但也已做好一切準備。"],"attacking":["希臘軍隊已依國際法展開行動，目標僅限軍事設施。","我們的艦隊已駛出愛琴海，希臘不會退縮。"],"attacked":["雅典受到嚴重威脅，但希臘人民不會屈服。","衛城見過無數風雨，這一次也一樣會挺過去。"],"defeated":["希臘政府在此宣告投降，願人民免於更多苦難。","歷史會記得，希臘人曾為民主與自由堅持到最後。"],"victory":["這場勝利屬於希臘人民，我們將立即致力於重建和平。","希臘無意擴張，我們只求安全與尊嚴。"],"allyAccept":["希臘政府欣然同意結盟，願我們如奧運精神般團結。","很好，這份同盟將為東地中海帶來穩定。"],"allyReject":["希臘目前傾向維持中立，恕難結盟。","感謝提議，但議會希望我們保持獨立的外交立場。"],"greetFriendly":["感謝您的問候，希臘政府樂於與貴國深化友誼。","民主的發源地向您致意，歡迎有空來愛琴海走走。"],"greetCold":["我們已收到問候，目前暫無進一步交流的安排。","希臘政府注意到您的訊息，將在適當時機回覆。"],"threatDefy":["希臘人自古便懂得捍衛自由，我們不會被威脅動搖。","我方奉行和平外交，但面對威脅絕不退讓。"],"threatYield":["為了人民的福祉，希臘政府願以對話化解此次爭端。","我方希望避免衝突，願在此事上展現彈性。"],"tributePay":["經內閣審慎評估，我方同意支付{gold}金幣以維持穩定。","希臘政府撥付{gold}金幣，期盼雙方關係回歸正軌。"],"tributeRefuse":["希臘的預算屬於人民，恕我方無法接受此項要求。","主權國家之間應平等相待，我方拒絕支付任何貢品。"],"giftThanks":["感謝貴國的厚禮，希臘將以橄欖枝回贈，象徵和平。","這份禮物我們收到了，願愛琴海的海風帶去我方謝意。"],"intel":["我方與{wars}交戰，與{peace}維持和平，供您參考。","目前交戰對象是{wars}，友好國家是{peace}。"]}},"Canada":{"name":"加拿大總理","title":"加拿大政府","tone":"溫和有禮、講究多邊合作與程序的外交口吻；愛以楓葉、冬天、冰上曲棍球作比喻，常先致歉再表達立場，涉及主權時態度堅定。","portrait":"ca-modern","lines":{"intro":["您好，我是加拿大總理，很高興認識您，我們一向樂於交朋友。","加拿大代表團向您致意，天冷了，請多添件衣服再談。"],"contact":["貴國人員到訪我們的城市了？歡迎，冬天請注意路面結冰。","那座城市對所有訪客開放，只要遵守規則，楓葉旗下人人平等。"],"war":["很抱歉，經過國會表決，加拿大政府決定對貴國採取軍事行動。","我們用盡了所有外交管道，這是最後的選擇，也是不得已的選擇。"],"warReply":["貴國宣戰了？我們深表遺憾，加拿大將依法自衛，並通知各盟友。","我們不主動挑起衝突，但每一位加拿大人都會守住自己的家。"],"peace":["加拿大政府提議立即停火，並願意主持後續的和平談判。","衝突已造成太多損失，讓我們回到談判桌，我們會準備好熱茶。"],"accept":["加拿大接受這項協議，並期待與貴國重建互信與合作。","很好，這是明智的決定，我們會依約履行每一項承諾。"],"reject":["很抱歉，這份提案不符合加拿大的核心利益，我們無法接受。","我們重視和平，但條件必須公平，目前的版本恕難同意。"],"rebuff":["貴國拒絕了提案，我們表示遺憾，但談判的大門仍然敞開。","沒關係，加拿大很有耐心，我們的冬天很長，等得起。"],"betray":["情勢有了新的變化，加拿大政府必須重新評估這份停火協議。","很抱歉，為了國家安全，我們不得不中止協議，希望您能理解。"],"truceEnd":["停火期限已至，加拿大政府將依原定程序恢復正常戒備。","協議到期了，我們仍希望和平延續，冰球在貴國那一邊。"],"attacking":["加拿大部隊已經出發，這是國會授權的行動，我們遵守國際規範。","我們的軍隊不常出動，但一旦出動，就像冰上的球員一樣認真。"],"attacked":["首都受到重創，但加拿大人習慣暴風雪，我們會撐過這一夜。","城市可以重建，楓葉旗還在飄，我們沒有放棄的打算。"],"defeated":["加拿大政府正式停止抵抗，請善待我們的人民，謝謝。","我們輸了這場戰爭，但加拿大人的善意與堅韌不會消失。"],"victory":["戰爭結束了，加拿大不會慶祝太久，我們更關心如何重建和平。","感謝將士與人民，現在，讓我們把資源投回醫院與學校。"],"allyAccept":["加拿大很榮幸與貴國結為盟友，我們會是可靠的夥伴。","太好了，好鄰居比什麼都重要，歡迎隨時來喝杯楓糖熱飲。"],"allyReject":["很抱歉，加拿大目前不便締結新的軍事同盟，但仍願保持友好。","我們珍惜貴國的好意，但結盟需要國會同意，目前條件尚未成熟。"],"greetFriendly":["感謝來信！加拿大的大門如同溜冰場，永遠歡迎朋友一起上場。","很高興收到問候。楓葉正紅，願我們的合作也一樣鮮明。"],"greetCold":["抱歉，本人行程繁忙，貴方的問候已依程序歸檔。","不好意思，渥太華今天零下二十度，恕我無法回以熱情。"],"threatDefy":["抱歉，加拿大的主權不在談判桌上。冬天我們習慣了，威脅也是。","很遺憾聽到這種話。冰上曲棍球場上我們不怕衝撞，外交上亦然。"],"threatYield":["抱歉，為避免局勢升溫，加拿大願先退一步，並提請多邊協商。","我們理解貴方的立場。加拿大選擇冷靜，如同雪後的清晨。"],"tributePay":["經內閣審議，加拿大將提供{gold}金幣，以維護區域穩定。","很抱歉走到這一步。{gold}金幣已撥付，盼貴方信守承諾。"],"tributeRefuse":["抱歉，加拿大不接受任何形式的貢品要求，此事無討論空間。","很遺憾，這項要求不符合國際慣例，加拿大必須婉拒。"],"giftThanks":["非常感謝貴方的禮物，我們將回贈一罐楓糖漿以表謝意。","禮物已收到，這份心意像冬日的暖爐，加拿大銘記在心。"],"intel":["外交簡報：{wars}正在交戰，{peace}維持和平。","樂意分享：{wars}陷入衝突，{peace}維持穩定。"]}},"Mexico":{"name":"墨西哥總統","title":"政府","tone":"外交辭令、務實而親切，帶一點墨西哥文化色彩（玉米、瑪雅遺跡、亡靈節），不刻板、不影射真實政治人物。","portrait":"mx-modern","lines":{"intro":["歡迎，我是墨西哥總統，願我們的合作像玉米田一樣豐收。","墨西哥向貴國致意，這片土地有三千年的文明可以分享。"],"contact":["貴國的人員看到的是墨西哥城，兩千萬人的活力之都。","那座城建在古老的湖床上，歡迎貴國的訪客來看看。"],"war":["外交途徑已經用盡，墨西哥政府決定採取軍事行動。","這不是我們想要的結果，但主權不容協商。"],"warReply":["墨西哥深感遺憾，我們會回應，並向國際社會說明。","我國從不主動挑起戰爭，但也從未在戰爭中退縮。"],"peace":["墨西哥提議立即停火，讓兩國人民回到正常生活。","墨西哥願意主持和談，餐桌永遠比戰場更適合解決問題。"],"accept":["墨西哥接受這項協議，我們會在外交部正式簽署。","很好，這是兩國人民的勝利，我會親自出席簽字。"],"reject":["很抱歉，貴國的條件我國國會不會通過。","墨西哥重視和平，但不是以犧牲國家利益為代價。"],"rebuff":["我們尊重貴國的決定，墨西哥的大門仍然敞開。","遺憾貴國拒絕，但我相信時間會證明合作更有價值。"],"betray":["情勢已經改變，墨西哥政府宣布停戰協議終止。","我為此感到遺憾，但國家安全考量高於一切。"],"truceEnd":["停戰協議今日到期，墨西哥希望雙方能繼續克制。","協議期滿了，我們準備好談判，也準備好防衛。"],"attacking":["墨西哥軍隊已經出動，行動目標僅限於軍事設施。","我已下令前進，這是我任內最沉重的一道命令。"],"attacked":["首都遭到猛烈攻擊，但墨西哥政府仍在正常運作。","這座城市經歷過地震與戰火，每一次都重新站起來。"],"defeated":["墨西哥政府停止抵抗，請善待我們的人民與文化遺產。","金字塔比任何政府都長久，墨西哥的故事還沒結束。"],"victory":["墨西哥贏得了這場衝突，現在該談的是重建與和解。","勝利屬於墨西哥人民，我們不會忘記為此付出的代價。"],"allyAccept":["墨西哥同意結盟，讓我們在經貿與安全上攜手前進。","太好了，歡迎貴國元首來訪，我會親自帶你看瑪雅金字塔。"],"allyReject":["墨西哥奉行不干涉原則，目前不便加入任何軍事同盟。","感謝貴國的提議，但我們希望維持獨立自主的外交。"],"greetFriendly":["很高興收到你的來信，歡迎隨時來品嘗墨西哥的玉米餅。","墨西哥政府向你問好，願兩國友誼如瑪雅金字塔般長存。"],"greetCold":["來信已收悉，我國目前對此暫無進一步回應。","感謝問候，相關事務請循正式外交管道進行。"],"threatDefy":["墨西哥的主權不容威脅，我們的立場一如既往堅定。","威嚇無助於對話，我國將採取一切必要措施自衛。"],"threatYield":["為了區域穩定，我國願意在此議題上做出讓步。","我們選擇克制，希望對話能取代對抗。"],"tributePay":["經內閣審議，我國同意支付{gold}金以維持和平。","{gold}金已依協議撥付，望此舉能換來雙邊的穩定。"],"tributeRefuse":["這項要求不符合國際慣例，墨西哥政府無法接受。","國家預算屬於全體人民，恕我國無法答應。"],"giftThanks":["謝謝這份心意，就像亡靈節的萬壽菊一樣溫暖人心。","墨西哥政府衷心感謝，願以最好的可可回敬你的心意。"],"intel":["外交部回報：{wars}正在交戰，{peace}維持和平。","情報顯示，{wars}衝突未止，{peace}與我國友好。"]}},"Cuba":{"name":"古巴主席","title":"政府","tone":"外交辭令、熱情溫暖，愛用音樂、海洋與棒球比喻，不失堅定","portrait":"cu-modern","lines":{"intro":["歡迎，本席代表古巴人民向您致意，願我們的交往如海風般順暢。","加勒比海的島國向您問好，願以咖啡與音樂款待貴國。"],"contact":["貴國人員已抵哈瓦那，老城的街道與海濱大道歡迎他們。","我們是小島，但心胸如海，貴國訪客請放心走走看看。"],"war":["古巴政府已用盡外交手段，今日不得不宣布進入戰爭狀態。","我們珍惜和平，但更珍惜主權，這是本席的最後聲明。"],"warReply":["貴國選擇了戰爭，古巴表示遺憾，並將堅定保衛國土。","這座島經歷過無數風暴，也會挺過這一場。"],"peace":["古巴政府提議停火，讓對話取代砲聲。","戰爭沒有贏家，請讓兩國的球場重新響起歡呼。"],"accept":["古巴接受這份協議，願它像老城的石牆一樣長久。","感謝貴國的誠意，本席將親自督促協議落實。"],"reject":["很遺憾，這份提案未能顧及古巴的基本權益，我方無法接受。","和平必須建立在互相尊重上，目前的條件尚未達到。"],"rebuff":["古巴尊重貴國的決定，但門仍然開著。","本席深感遺憾，願貴國日後重新考慮。"],"betray":["鑑於貴國的行動，古巴政府宣布協議即刻失效。","本席不願走到這一步，但古巴的安全不容妥協。"],"truceEnd":["停火期限已屆，古巴政府呼籲雙方保持克制。","協議到期了，但通往和平的橋樑仍在。"],"attacking":["古巴武裝部隊已依法出動，目標僅限於恢復和平。","我們並非好戰之國，但今天不得不前進。"],"attacked":["哈瓦那受到重創，但這座城市經歷過風暴，仍會站起來。","本席仍在崗位上，古巴政府沒有離開人民。"],"defeated":["古巴政府已盡最後努力，願人民得到善待。","海風會繼續吹，古巴的歌也會有人接著唱。"],"victory":["古巴取得了勝利，但本席呼籲全國以謙遜迎接和平。","勝利屬於人民，今晚哈瓦那的音樂會響到天明。"],"allyAccept":["古巴欣然接受結盟，願兩國如棒球隊友般互相掩護。","本席相信，小國之間的團結也能改變局勢。"],"allyReject":["古巴珍視自主外交，目前不宜加入任何同盟。","感謝貴國的邀請，我方希望維持友好但獨立的關係。"],"greetFriendly":["來自加勒比海的問候！願我們的友誼如吉他聲般悠揚。","歡迎您，朋友。哈瓦那的海堤永遠為知音留一席。"],"greetCold":["感謝來訊。古巴人熱情，但也懂得先看清對方球路。","本席已收到問候。樂團尚未開演，我們先聽聽節奏。"],"threatDefy":["颶風我們年年迎接，威嚇不過是一陣風，古巴不會彎腰。","九局下半兩出局，古巴也從不放下球棒。請三思。"],"threatYield":["為了人民的安寧，我們願意暫時讓步，但音樂不會停。","這一局我們選擇保送，但球賽還長，請貴方記得。"],"tributePay":["古巴將支付 {gold} 金，以維護地區和平，願貴方珍惜。","{gold} 金已備妥，這是為了人民而非畏懼，請勿誤會。"],"tributeRefuse":["古巴的資源屬於古巴人民，恕難以貢品形式奉上。","我們願分享音樂與友誼，但貢品不在菜單上。"],"giftThanks":["衷心感謝貴方厚禮，哈瓦那的樂手今晚為您加演一曲。","這份禮物如同海風般清爽，古巴人民銘記在心。"],"intel":["據我方外交管道所知，{wars} 正處戰事，{peace} 局勢平穩。","棒球場外的消息：{wars} 已經開戰，{peace} 仍風平浪靜。"]}},"Peru":{"name":"秘魯總統","title":"政府","tone":"外交辭令、溫和穩健，偶爾提到安地斯山、太平洋、馬丘比丘與馬鈴薯等秘魯元素但不刻板；自稱「我」「我國」。","portrait":"pe-modern","lines":{"intro":["我是秘魯總統，代表安地斯山與太平洋之間的人民問候您。","秘魯願與貴國建立互信，馬丘比丘隨時歡迎您來訪。"],"contact":["貴國的人員抵達利馬了，我們準備了檸檬醃魚款待。","歡迎來到秘魯，從沙漠、高山到雨林，我們的國土應有盡有。"],"war":["經過內閣與國會審慎討論，秘魯不得不對貴國採取軍事行動。","我國的耐心已經用盡，安地斯山的人民從不畏懼高處。"],"warReply":["貴國選擇了戰爭，秘魯深感遺憾，但我們會保衛國土。","我已通知國防部進入戒備，同時保留對話的大門。"],"peace":["秘魯提議停火，讓兩國的孩子回到教室而不是防空洞。","我願意在利馬設宴，與您面對面談一份長久的和平。"],"accept":["秘魯接受停火，我會請外交部立即安排簽署事宜。","很好，和平比砲火更能讓馬鈴薯田豐收。"],"reject":["貴國的提案缺乏誠意，秘魯政府無法接受。","在條件對等之前，我國不會簽署任何停火協議。"],"rebuff":["秘魯對貴國的拒絕深表遺憾，但我們的門仍然開著。","我理解貴國的立場，秘魯將重新評估後續的因應方式。"],"betray":["基於國家安全的最新評估，秘魯決定終止停火協議。","情勢已經改變，我國無法再遵守先前的承諾，深感抱歉。"],"truceEnd":["停火協議已到期，秘魯將依國家利益決定下一步。","協議期滿，希望這段日子的和平能延續，但我們也做好準備。"],"attacking":["秘魯武裝部隊已經出動，這是不得已的最後手段。","我國部隊正翻越山脈前進，安地斯的孩子習慣稀薄的空氣。"],"attacked":["利馬正遭受攻擊，但秘魯政府仍在運作，不會投降。","總統府的燈還亮著，我與人民同在，直到最後一刻。"],"defeated":["秘魯曾經歷帝國興衰，今日的失敗不會是故事的結局。","我請求貴國善待秘魯人民，安地斯山會記得一切。"],"victory":["秘魯取得了勝利，我們會以印加人的智慧重建這片土地。","戰事結束了，我國將優先協助雙方人民恢復正常生活。"],"allyAccept":["秘魯很榮幸與貴國結盟，太平洋將成為我們共同的橋梁。","我接受，讓兩國的合作像印加古道一樣穩固而長遠。"],"allyReject":["秘魯目前傾向維持中立，感謝貴國的提議。","這項結盟需要國會同意，目前時機尚未成熟，請見諒。"],"greetFriendly":["感謝來函，我國願與貴國如安地斯山般長久相伴。","很高興收到問候，歡迎貴國友人來訪馬丘比丘。"],"greetCold":["來函已收悉，我國將在適當時機再行回覆。","我國注意到貴國的問候，目前暫無進一步安排。"],"threatDefy":["我國主權如太平洋海岸般清晰，不容任何威脅。","安地斯山不會因風聲而移動，我國的立場亦然。"],"threatYield":["為避免局勢升溫，我國願先退一步，尋求對話。","我國選擇克制，但盼貴國珍惜這份善意。"],"tributePay":["我國同意提供{gold}黃金援助，盼此舉能換來區域穩定。","{gold}黃金將依約撥付，我國期待貴國信守承諾。"],"tributeRefuse":["我國的資源屬於全體人民，恕難接受此項要求。","這樣的要求不符合平等原則，我國無法同意。"],"giftThanks":["貴國的心意我國深表感謝，願以秘魯馬鈴薯回禮。","感謝厚禮，這份情誼將如馬丘比丘般歷久不衰。"],"intel":["外交管道回報：{wars}交戰中，{peace}和平相處。","據我國了解：{wars}衝突未止，{peace}關係穩定。"]}},"Bolivia":{"name":"玻利維亞總統","title":"政府","tone":"沉穩的外交辭令，強調主權與多元民族，偶爾提及高原、鹽湖等風土，不影射真實政治人物。","portrait":"bo-modern","lines":{"intro":["您好，我是玻利維亞總統，代表多民族國家謹向您問候。","從安地斯高原到亞馬遜雨林，玻利維亞願與您對話。"],"contact":["歡迎您的人民造訪，高原的陽光與鹽湖都歡迎客人。","請留意高山症，拉巴斯是全球海拔最高的行政首都。"],"war":["外交途徑已經用盡，玻利維亞被迫採取軍事行動。","我們珍視和平，但更珍視主權，此事已無退路。"],"warReply":["我們遺憾您的決定，玻利維亞將依國際法自衛。","高原人民歷經考驗，不會被威脅嚇倒。"],"peace":["戰事對雙方人民都是傷害，我方提議立即停火談判。","讓我們回到談判桌，這是對兩國人民負責的做法。"],"accept":["玻利維亞接受此協議，願雙方關係回到正軌。","感謝您的善意，我們願以此為兩國和平的起點。"],"reject":["目前的條件我方無法接受，請先展現具體誠意。","玻利維亞不會在壓力下簽署不平等的協議。"],"rebuff":["我方對您的回應深表遺憾，但和平之門仍然敞開。","請重新考慮，戰爭不會為任何一方帶來好處。"],"betray":["鑑於局勢變化，玻利維亞決定終止現行停火協議。","我方保留一切必要的措施，協議自即日起失效。"],"truceEnd":["停火期限已屆，玻利維亞恢復原有部署。","協議到期，兩國關係回到談判前的狀態。"],"attacking":["玻利維亞部隊已經出發，我們將捍衛國家的尊嚴。","請通知您的人民，我方行動針對軍事目標而非平民。"],"attacked":["首都遭受重創……但玻利維亞人民不會放棄。","我們正請求國際社會關注，高原的火焰尚未熄滅。"],"defeated":["玻利維亞暫時倒下了，願歷史公正地看待我們。","感謝人民的堅持，玻利維亞的名字不會被遺忘。"],"victory":["這是和平與尊嚴的勝利，玻利維亞感謝所有支持者。","我們願向對方伸出援手，重建才是最終的目標。"],"allyAccept":["玻利維亞樂於結盟，願兩國如安地斯山脈般穩固相連。","感謝您的信任，我們將在各領域深化合作。"],"allyReject":["感謝提議，但目前玻利維亞將維持獨立自主的立場。","結盟之事需經國會討論，暫時無法答應。"],"greetFriendly":["玻利維亞向貴國致上高原的問候，期待深化友誼。","多元民族的玻利維亞，始終歡迎真誠的朋友。"],"greetCold":["本政府已收到來函，將在適當時機予以回應。","玻利維亞的立場向來清楚，恕不再重申。"],"threatDefy":["玻利維亞的主權不容任何威脅，我們會堅定回應。","安地斯的高原從不向壓力低頭，請貴國慎重。"],"threatYield":["為了人民的安全，本政府願意重回談判桌。","我們選擇克制，這是負責任政府的決定，而非軟弱。"],"tributePay":["本政府將撥付 {gold} 金幣作為合作款項，盼以此維繫區域和平。","{gold} 金幣已依貴方要求匯出，玻利維亞期望這是最後一次。"],"tributeRefuse":["玻利維亞的資源屬於全體人民，恕難接受此項要求。","鹽湖與高原孕育的財富，將優先用於我國人民。"],"giftThanks":["感謝貴國厚意，玻利維亞珍視這份跨越山海的友誼。","這份禮物將陳列於拉巴斯，見證兩國情誼。"],"intel":["據本政府掌握，{wars}正處於衝突狀態，{peace}則與我們保持友好。","外交管道顯示，{wars}態度強硬，{peace}願意對話。"]}},"Brazil":{"name":"巴西總統","title":"巴西聯邦政府","tone":"熱情友善、用語為外交辭令，偶爾以咖啡、足球、森巴、雨林作比喻但不誇張，自稱「我」「我國」","portrait":"br-modern","lines":{"intro":["我是巴西總統，代表巴西人民向您問候，歡迎交流。","巴西願與世界各國做朋友，希望與貴國也一樣。"],"contact":["貴國的使節看見的是巴西利亞，我們的首都。","請放心，巴西的大門敞開，就像我們的海灘一樣。"],"war":["經聯邦政府慎重評估，巴西不得不對貴國採取軍事行動。","我國已用盡外交手段，遺憾地通知您：我們進入戰爭狀態。"],"warReply":["貴國選擇了戰爭，巴西將依法自衛，並向國際社會說明。","我們熱愛和平，但也絕不退讓，巴西會保衛自己的土地。"],"peace":["衝突無助於任何一方，我提議雙方立即停火並展開對話。","巴西願意先釋出善意，邀請貴國回到談判桌。"],"accept":["我國接受這項協議，感謝貴國展現的誠意與智慧。","這是務實的一步，巴西將全力履行協議內容。"],"reject":["很抱歉，貴國提出的條件我國無法接受，請重新考慮。","停火需要互信，目前的條件還不足以讓我國點頭。"],"rebuff":["我對貴國的決定表示遺憾，巴西的提案將保持開放。","對話的門不會關上，我們隨時歡迎貴國回心轉意。"],"betray":["基於國家安全考量，我國必須中止先前的停火協議。","情勢已經改變，巴西不得不重新採取必要的行動。"],"truceEnd":["停火協議的期限已到，巴西將依情勢重新評估對策。","協議到期了，希望雙方都能記得這段和平的價值。"],"attacking":["巴西部隊已依計畫出動，這是我國不願但必要的決定。","我國軍隊正在前進，希望貴國能盡快回到談判桌。"],"attacked":["首都遭受重創，但巴西人民的韌性不會因此崩潰。","我們正承受巨大壓力，但政府仍在運作，巴西仍在。"],"defeated":["巴西政府在此宣告終戰，願人民的苦難到此為止。","我們輸了，但巴西的歌聲與足球，會在人民心中延續。"],"victory":["這場勝利屬於全體巴西人民，今晚讓森巴鼓響起吧。","感謝將士與人民，巴西將以寬容的態度面對戰後重建。"],"allyAccept":["巴西很榮幸與貴國結盟，願我們的合作像咖啡一樣醇厚。","這是兩國友誼的新篇章，我國將全力支持盟友。"],"allyReject":["感謝貴國的邀請，但巴西目前希望維持中立立場。","結盟事關重大，我國需要更多時間審慎評估。"],"greetFriendly":["很高興收到您的問候，歡迎隨時來巴西喝杯咖啡。","我國願與貴國深化友誼，如同球場上的好隊友。"],"greetCold":["感謝來函，我國將在適當時機予以回覆。","問候已收悉。我國目前正專注於國內事務。"],"threatDefy":["我國尊重和平，但絕不接受任何形式的威脅。","巴西幅員遼闊，人民團結，不會被恫嚇動搖。"],"threatYield":["為避免衝突升級，我國願重新檢視雙方立場。","我國選擇對話而非對抗，願意做出適度讓步。"],"tributePay":["我國同意提供 {gold} 金幣，作為區域穩定的投資。","基於維護和平，我國將撥付 {gold} 金幣予貴國。"],"tributeRefuse":["我國的財政屬於巴西人民，恕難接受此要求。","這項要求不符合平等互惠原則，我國無法同意。"],"giftThanks":["衷心感謝貴國的厚禮，我國將以熱情回報。","這份禮物如同森巴的節奏，讓兩國關係更熱絡。"],"intel":["據我國外交部掌握，{wars} 正處交戰，{peace} 關係和睦。","情報顯示，{wars} 已爆發衝突，{peace} 維持友好往來。"]}},"Argentina":{"name":"阿根廷總統","title":"政府","tone":"熱情而莊重、外交辭令中帶南方大地的豪爽、重視主權與人民、偶爾以瑪黛茶與探戈自況","portrait":"ar-modern","lines":{"intro":["我是阿根廷總統，代表南方大地向您致意。","從彭巴草原到南極門戶，阿根廷願與各國為友。"],"contact":["歡迎貴國人員來訪，請務必嚐嚐我們的瑪黛茶。","布宜諾斯艾利斯的大道向來對朋友敞開。"],"war":["本政府已窮盡外交手段，遺憾宣布進入戰爭狀態。","阿根廷不好戰，但五月的太陽從不向威脅低頭。"],"warReply":["貴國的宣戰已收到，我國國會將全力應對。","探戈需要兩個人，戰爭也一樣，我們不會缺席。"],"peace":["阿根廷提議停火，讓談判桌取代前線。","兩國人民都值得安穩的黃昏，請考慮我們的提案。"],"accept":["本政府接受停火，並邀請貴國派員來訪簽署。","很好，讓我們以一杯瑪黛茶為新的開始乾杯。"],"reject":["感謝提案，但條件尚未反映貴國應負的責任。","阿根廷願意談，但不會在壓力下簽字。"],"rebuff":["貴國的回絕令人遺憾，阿根廷的大門仍然敞開。","我們會把這份提案留在桌上，等您改變心意。"],"betray":["貴國持續違反停火條款，本政府不得不終止協議。","阿根廷守約直到最後一刻，責任不在我方。"],"truceEnd":["停火期限已屆，兩國關係回到談判前的狀態。","希望這段時間讓彼此都更清楚和平的價值。"],"attacking":["我國部隊已依國會授權出動，目標僅限軍事設施。","阿根廷不願走到這一步，但主權不容討價還價。"],"attacked":["首都遭受重創，本政府已轉移，但仍在運作。","我請求貴國遵守國際法，保護平民與醫院。"],"defeated":["本政府停止抵抗，請善待這片土地上的人民。","彭巴草原的風不會停，阿根廷的名字也不會。"],"victory":["戰事結束，阿根廷願協助貴國重建，不索賠償。","勝利不是終點，我們更希望迎來長久的鄰居。"],"allyAccept":["本政府欣然同意，兩國將簽署互助合作條約。","從安地斯到大西洋，阿根廷將與貴國並肩。"],"allyReject":["感謝邀請，但阿根廷目前傾向維持中立立場。","結盟需要國會審議，現階段我們無法承諾。"],"greetFriendly":["來信收到，如同一壺剛沖好的瑪黛茶，溫暖又提神。","阿根廷人民向貴國致意，南方大地的門永遠敞開。"],"greetCold":["已收到貴方問候。阿根廷的立場，向來以主權為先。","外交如探戈，需要兩人同步。貴方的步伐，我還在觀察。"],"threatDefy":["阿根廷的主權不容威嚇，這是人民的底線，也是我的。","彭巴草原的風再大，也吹不倒這片土地。請貴方三思。"],"threatYield":["為了人民的安寧，本人願意讓步。但請記住，這不是屈服。","阿根廷選擇談判桌，而非戰場。此事，我們可以退一步。"],"tributePay":["這 {gold} 是人民的稅金。本人交付，也請貴方信守承諾。","為維持區域穩定，阿根廷支付 {gold}。國會必會向我問責。"],"tributeRefuse":["阿根廷不向任何國家納貢。人民的錢，只用在人民身上。","貴方的要求，恕難接受。這片土地的尊嚴，沒有標價。"],"giftThanks":["衷心感謝！這份情誼，阿根廷人民會以一場探戈之夜回敬。","貴方的厚禮已收下。南方大地的友誼，一向長久而熱烈。"],"intel":["根據外交部的情報，{wars} 正處交戰狀態，{peace} 維持和平。","來一杯瑪黛茶，聽我說：{wars} 戰火未熄，{peace} 尚且平靜。"]}},"Morocco":{"name":"摩洛哥國王","title":"政府","tone":"溫和穩健的外交辭令，強調摩洛哥是歐非之間的橋樑、傳統與現代並存，偶以薄荷茶、港口等文化意象作比喻，不影射真實人物。","portrait":"ma-modern","lines":{"intro":["本人代表摩洛哥王國，向貴國致上最誠摯的問候。","摩洛哥是歐洲與非洲之間的橋樑，願與貴國攜手同行。"],"contact":["歡迎貴國的朋友來到拉巴特，一杯薄荷茶已為各位備妥。","這座城市面向大西洋，也面向未來，請貴國多加參觀。"],"war":["摩洛哥王國已用盡一切外交手段，如今不得不採取軍事行動。","本人謹此通知貴國，兩國自即日起進入戰爭狀態。"],"warReply":["貴國的宣戰令人遺憾，摩洛哥王國將堅定捍衛主權與領土。","我國從不主動尋求衝突，但也絕不會在威脅面前退縮。"],"peace":["本人提議雙方立即停火，回到談判桌，衝突對誰都沒有好處。","摩洛哥願意做和平的橋樑，這杯薄荷茶，願與貴國共飲。"],"accept":["摩洛哥王國接受這份協議，期待兩國關係翻開新的一頁。","本人謹代表我國，對貴國的誠意表示肯定與感謝。"],"reject":["經審慎評估，摩洛哥王國目前無法接受這份停戰條件。","我國期待更公平的方案，門仍然敞開，但不是這份文件。"],"rebuff":["本人對貴國的決定表示遺憾，但尊重貴國的選擇。","摩洛哥的大門依舊敞開，貴國若改變心意，隨時歡迎。"],"betray":["基於國家安全的最新評估，摩洛哥王國決定終止停戰協議。","本人深感遺憾，但貴國近期的行動，已使協議失去意義。"],"truceEnd":["停戰協議已於今日到期，摩洛哥王國將重新評估雙邊關係。","協議期滿不代表對立，我國仍期待與貴國維持穩定往來。"],"attacking":["摩洛哥王國的部隊已依計畫出發，本人已通知各友邦。","我國的行動有明確目標與範圍，將盡力保護平民。"],"attacked":["拉巴特的情勢十分嚴峻，本人呼籲貴國立即停止進攻。","摩洛哥王國願意立即談判，請貴國以人道為念。"],"defeated":["摩洛哥王國已無力再戰，本人請求貴國善待我國人民。","非斯與馬拉喀什的古城仍在，願它們在貴國手中得到保存。"],"victory":["摩洛哥王國取得了勝利，本人感謝全體國民與友邦的支持。","戰事已結束，我國願意協助重建，並開啟新的合作。"],"allyAccept":["摩洛哥王國欣然同意結盟，兩國將在各領域深化合作。","從大西洋到地中海，摩洛哥的港口將對貴國的夥伴敞開。"],"allyReject":["感謝貴國的提議，但摩洛哥王國目前傾向維持中立立場。","結盟需要更多時間醞釀，我國願先從經濟與文化交流開始。"],"greetFriendly":["感謝來信。摩洛哥是歐非之間的橋樑，歡迎貴國同行。","請貴國代表來喝一杯薄荷茶，我們慢慢談合作。"],"greetCold":["來信已收悉。摩洛哥將依既定政策審慎評估。","感謝貴國關注，雙方關係目前沒有進一步安排。"],"threatDefy":["摩洛哥珍視和平，但主權不容威嚇，這點請貴國明白。","直布羅陀海峽兩岸皆是朋友，威脅只會讓貴國孤立。"],"threatYield":["為維護區域穩定，摩洛哥願意在此議題上展現彈性。","我們選擇對話而非對抗，此次先尊重貴國的立場。"],"tributePay":["摩洛哥將提供{gold}金幣，作為區域合作的誠意。","{gold}金幣已撥付，願此舉換來港口與商路的平靜。"],"tributeRefuse":["摩洛哥的預算屬於人民與建設，恕難接受貢品要求。","友誼不以金幣衡量，這項要求我們無法同意。"],"giftThanks":["感謝貴國厚禮，如同一杯甜薄荷茶，溫暖了兩國情誼。","摩洛哥感念此情，期待港口間往來的船隻更加頻繁。"],"intel":["據我方了解，{wars}正在交戰，{peace}已和解。","外交簡報：{wars}衝突未止，{peace}與我國友好。"]}},"Tunisia":{"name":"突尼西亞總統","title":"政府","tone":"溫和有禮的外交辭令，常以茉莉花、橄欖樹、蜜棗、薄荷茶、迦太基遺產與地中海為喻，強調對話、寬容與人民韌性；自稱「我」或「本人」，稱對方「貴國」。","portrait":"tn-modern","lines":{"intro":["我是突尼西亞總統。這裡曾是迦太基，如今以茉莉花聞名。","代表突尼西亞人民向您問好。願我們的往來如地中海般開闊。"],"contact":["您的代表團到了突尼斯？請務必嚐嚐我們的橄欖與椰棗。","歡迎來到迦太基的故土。我們珍惜歷史，也期待新的友誼。"],"war":["本人深感遺憾，突尼西亞已無其他選擇。我們將捍衛國土。","對話的門已被貴國關上。突尼西亞政府決定採取行動。"],"warReply":["貴國選擇了戰爭，這令人痛心。突尼西亞人民會團結應對。","我們一向偏好談判桌。既然貴國不願，我們也不會退縮。"],"peace":["衝突對兩國人民都沒有好處。突尼西亞提議立即停火。","讓我們回到談判桌。地中海足夠寬闊，容得下彼此。"],"accept":["突尼西亞接受這項協議。願和平如橄欖樹一樣長久。","感謝貴國的誠意。我們將嚴格履行協議的每一條款。"],"reject":["很抱歉，目前的條件突尼西亞無法接受。請貴國重新考慮。","停火需要建立在互信之上。眼下，這份互信還不存在。"],"rebuff":["我們尊重貴國的決定，但對此結果深表遺憾。","突尼西亞的大門仍然敞開。貴國隨時可以回來談。"],"betray":["情勢已與簽約時不同。突尼西亞政府決定中止協議。","本人為此致歉，但國家安全必須放在首位。"],"truceEnd":["停火期已屆滿。突尼西亞希望延續和平，但也會做好準備。","協議到期了。接下來的走向，取決於貴國的態度。"],"attacking":["突尼西亞的部隊已經出動。我們仍盼貴國儘早重返談判。","這不是我們願意見到的一步，但國土安全不容妥協。"],"attacked":["首都正遭受猛烈攻擊。突尼西亞呼籲國際社會關注局勢。","迦太基的遺跡見證過興衰。我們會保護人民，直到最後一刻。"],"defeated":["突尼西亞政府已無力抵抗。請貴國善待這裡的每一位公民。","茉莉花會再開。突尼西亞人民的韌性，不會因此消失。"],"victory":["戰事已經結束。突尼西亞將以寬容面對明天，而非仇恨。","感謝人民的堅持。現在，讓我們把資源用在重建與教育上。"],"allyAccept":["突尼西亞很榮幸與貴國結盟。願合作如地中海貿易般繁榮。","本人代表政府同意結盟。請貴國代表來突尼斯喝杯薄荷茶。"],"allyReject":["感謝貴國的提議，但突尼西亞目前傾向維持中立。","結盟是重大承諾，我們需要更多時間評估。請見諒。"],"greetFriendly":["貴國的問候如茉莉花香飄過地中海，本人深感溫暖。","歡迎貴國隨時來突尼斯喝一杯薄荷茶，我們有的是時間對話。"],"greetCold":["本人已收到貴國來函，將在適當時機給予適當回應。","橄欖樹長得慢，信任也是。貴國的問候，我先記下。"],"threatDefy":["迦太基的後裔見過無數風浪，貴國的威嚇撼動不了我們。","突尼西亞人民的韌性如橄欖樹，風越大，根扎得越深。"],"threatYield":["本人願以對話代替對抗，這一次，我們退一步。","為了人民的安寧，我選擇克制。地中海容得下大家。"],"tributePay":["本人已批准撥付 {gold} 枚金幣，盼貴國珍惜這份善意。","{gold} 枚金幣將如期送達，願它換來地中海的平靜。"],"tributeRefuse":["突尼西亞的資源屬於人民，本人無法答應貴國的要求。","貢品之說有損兩國尊嚴，我們更願意談合作。"],"giftThanks":["貴國厚禮已收到，本人回贈一箱椰棗，聊表心意。","感謝貴國。這份情誼，如同薄荷茶，越泡越香。"],"intel":["據外交部門觀察：{wars} 交戰中，{peace} 維持和平。","地中海上消息傳得快：{wars} 起了衝突，{peace} 依舊平靜。"]}},"Ethiopia":{"name":"衣索比亞總理","title":"政府","tone":"外交辭令、自豪而友善，常以咖啡、非洲聯盟總部、從未被殖民的歷史作為文化色彩","portrait":"et-modern","lines":{"intro":["我是衣索比亞總理，代表非洲聯盟總部所在的國家向您問好。","衣索比亞有十三個月的陽光，也有十三個月的誠意。"],"contact":["歡迎來到阿迪斯阿貝巴，先喝杯咖啡吧，這裡是咖啡的原鄉。","貴國代表團若有興趣，可順道參觀非洲聯盟總部。"],"war":["我國已用盡外交手段，不得不宣布進入戰爭狀態。","衣索比亞從未被殖民，這一次也不會退讓。"],"warReply":["我對貴國的決定深感遺憾，衣索比亞將全力自衛。","歷史證明，這片高原從不屈服於外來的壓力。"],"peace":["衝突無益於兩國人民，我提議立即停火並展開對話。","非洲聯盟總部就在我國，我們願提供調停的場地。"],"accept":["我國接受這項協議，期待與貴國重建互信。","感謝貴國的誠意，讓我們以一杯咖啡為和平開場。"],"reject":["貴國的提案未能回應我國的主要顧慮，恕難接受。","在貴國軍隊撤離前，停火協議無從談起。"],"rebuff":["我尊重貴國的決定，但對話的大門始終敞開。","令人遺憾，我國將在國際場合持續表達立場。"],"betray":["鑑於情勢變化，我國宣布終止先前的停火協議。","貴國未履行承諾，我國不再受此協議約束。"],"truceEnd":["停火期限已至，我國將重新評估與貴國的關係。","協議期滿，衣索比亞保留一切必要的行動選項。"],"attacking":["我國部隊已依計畫展開行動，對此我深感遺憾。","衣索比亞的軍隊如同我們的長跑選手，耐力驚人。"],"attacked":["首都情勢危急，但衣索比亞政府不會離開這片高原。","我們的祖先守住了阿杜瓦，我們也會守住阿迪斯阿貝巴。"],"defeated":["衣索比亞政府在此停止運作，願歷史記得我們的堅持。","高原上的咖啡樹仍會開花，這個民族終將再起。"],"victory":["衣索比亞人民再次證明，這片土地無法被征服。","感謝盟友與人民，現在請容我回去處理國內的事務。"],"allyAccept":["我國樂意與貴國建立夥伴關係，共同促進區域穩定。","衣索比亞歡迎這份友誼，藍尼羅河的源頭永遠敞開。"],"allyReject":["衣索比亞珍視獨立自主的傳統，暫不考慮軍事同盟。","感謝貴國的邀請，但我國目前傾向保持中立。"],"greetFriendly":["感謝來訊，歡迎到阿迪斯阿貝巴，我請你喝一杯道地咖啡。","我國向來好客，非洲聯盟總部的大門也為貴國敞開。"],"greetCold":["我國已收到貴方訊息，將在適當時機給予適當回覆。","衣索比亞珍視友誼，但友誼需要時間，如同咖啡需要細烹。"],"threatDefy":["衣索比亞是非洲少數從未被殖民的國家，我們不接受威嚇。","我國高原上的人民經歷過更大的風雨，貴方言辭不足為懼。"],"threatYield":["為避免局勢升高，我國願展現克制，回到談判桌上。","我國選擇對話而非對抗，暫且接受貴方條件以保區域和平。"],"tributePay":["我國同意提供{gold}枚金幣的援助款，盼此舉能換得穩定。","{gold}枚金幣已依約撥付，願雙方關係從此回到正軌。"],"tributeRefuse":["我國的預算屬於全體人民，恕難接受貴方的要求。","非洲聯盟總部就在我國，我們相信對話，而非繳納貢品。"],"giftThanks":["衷心感謝貴國贈禮，我國將回贈上等咖啡豆以表心意。","這份禮物體現了兩國情誼，我國將妥善珍藏並廣為宣揚。"],"intel":["據外交部掌握，{wars}與我國緊張，{peace}則友好。","坦白說，我國與{wars}有爭端，與{peace}合作順暢。"]}},"Nigeria":{"name":"奈及利亞總統","title":"政府","tone":"外交辭令、熱情自信、偶爾用非洲諺語式的比喻、以「非洲巨人」自許，自稱「本國」或「我」","portrait":"ng-modern","lines":{"intro":["我是奈及利亞總統，代表非洲巨人向貴國致意。","尼日河的水從不停流，願兩國的友誼也是如此。"],"contact":["貴國的人看見阿布加了？綠白綠的旗幟在歡迎各位。","從拉哥斯到阿布加，本國的市集永遠歡迎朋友。"],"war":["本國一向克制，但貴國的挑釁已越過紅線。","很遺憾，外交的大門已關，奈及利亞將採取行動。"],"warReply":["貴國選擇了對抗，本國有兩億人民不會退縮。","撞上大象的人，才會明白什麼叫沉重，請貴國三思。"],"peace":["衝突對誰都沒有好處，本國提議立即停火。","讓我們回到談判桌，非洲的未來需要合作而非戰火。"],"accept":["奈及利亞接受這項協議，願和平從今日開始。","很好，我們將以最快的速度重啟兩國的貿易往來。"],"reject":["抱歉，這份提案並未回應本國的核心關切。","奈及利亞需要的是真正的和平，不是暫時的喘息。"],"rebuff":["本國對貴國的回應深表遺憾，但大門依然敞開。","既然如此，奈及利亞會用行動證明自己的立場。"],"betray":["情勢已變，本國不得不重新評估先前的承諾。","為了人民的安全，奈及利亞宣布退出這項協議。"],"truceEnd":["停火期限已到，本國將視貴國的行動決定下一步。","協議到期了，希望我們不必再回到對抗的老路。"],"attacking":["奈及利亞的部隊已經出動，這是本國最後的手段。","本國並不好戰，但既然出手，就會做到底。"],"attacked":["首都告急……但奈及利亞人民從不輕言放棄。","貴國已兵臨城下，本國仍願在最後一刻談判。"],"defeated":["這一局我們輸了，但尼日河會繼續流向大海。","請善待我的人民，奈及利亞的故事還沒有結束。"],"victory":["非洲巨人挺過來了，今晚拉哥斯的鼓聲不會停。","勝利屬於人民，本國將以寬容對待昔日對手。"],"allyAccept":["奈及利亞樂於與貴國結盟，非洲需要更多朋友。","很好，讓我們一起把這片大陸的未來寫得更亮。"],"allyReject":["本國感謝貴國的誠意，但目前將維持獨立自主。","結盟是大事，奈及利亞需要與國會再作商議。"],"greetFriendly":["非洲巨人向貴國問好！期待與貴國攜手同行。","歡迎來訪，一隻手綁不緊柴捆，合作才走得遠。"],"greetCold":["本國已收到貴方問候，具體事宜請循外交管道。","非洲巨人步伐從容，貴國的信，本國會慢慢看。"],"threatDefy":["大象走路不必看螞蟻臉色，本國不接受任何威脅。","兩億人民站在本國身後，你的威嚇動搖不了我們。"],"threatYield":["本國向來主張對話，願依貴方提議重啟協商。","大象打架，草地受苦。為了人民，本國願退一步。"],"tributePay":["本國將撥付{gold}金作為友好援助，盼貴方善用。","{gold}金已匯出。今日的讓步，是為明日的合作鋪路。"],"tributeRefuse":["本國的石油與人才屬於人民，恕難照貴方所請。","非洲巨人不是誰的提款機。這項要求，本國婉拒。"],"giftThanks":["感謝厚禮！本國回贈自家的電影與音樂專輯，請欣賞。","貴國的心意，本國銘記。願兩國友誼如河水長流。"],"intel":["據本國外交部掌握：{wars}正處交戰，{peace}維持和平。","非洲大陸的消息傳得快：{wars}起了衝突，{peace}一切平靜。"]}},"South Africa":{"name":"南非總統","title":"政府","tone":"外交辭令、沉穩包容，強調彩虹之國、多元共存與「人因眾人而存在」的精神；自稱「本人」或「我國」，稱對方「閣下」「貴國」","portrait":"za-modern","lines":{"intro":["閣下您好，彩虹之國南非向貴國致上誠摯問候。","我國相信人因眾人而存在，願與貴國互相成就。"],"contact":["歡迎貴國代表團，桌山下的城市隨時為友邦敞開。","貴國的人看見了我們的城，也看見了多元共存的樣貌。"],"war":["我國已用盡外交途徑，今日不得不宣布進入戰爭狀態。","南非珍視和平，但更珍視主權，這是最後的選擇。"],"warReply":["貴國的宣戰令人遺憾，我國將依法動員自衛。","南非人民歷經考驗仍團結至今，不會被威脅擊倒。"],"peace":["我國提議即刻停火，讓談判桌取代戰場。","衝突沒有贏家，讓我們回到對話的道路上。"],"accept":["我國接受這項協議，願雙方共同守護得來不易的和平。","和解需要勇氣，南非願與貴國一同踏出這一步。"],"reject":["很遺憾，這份提案未能回應我國的主要顧慮。","我國尚無法接受目前的條件，請貴國重新考量。"],"rebuff":["我國尊重貴國的決定，但對話的大門不會關上。","遺憾聽到這樣的回覆，南非仍將尋求和平途徑。"],"betray":["鑑於局勢變化，我國不得不宣布協議即刻終止。","我國對此深感遺憾，但國家利益不容妥協。"],"truceEnd":["停火期限已屆，我國將重新評估與貴國的關係。","協議到期，南非保留採取一切必要行動的權利。"],"attacking":["我國部隊已依授權出發，願衝突儘早結束。","行動已經展開，希望貴國儘快回到談判桌。"],"attacked":["首都情勢嚴峻，但南非人民不會放棄希望。","我國呼籲貴國停止進攻，保護平民是共同責任。"],"defeated":["南非政府在此宣告停止抵抗，願人民免於更多苦難。","彩虹終會再現，這片土地的故事不會就此結束。"],"victory":["勝利屬於全體南非人民，我們將以寬容對待戰敗者。","我國願以和解精神重建與貴國的關係。"],"allyAccept":["南非欣然接受結盟，願兩國如彩虹般並肩共存。","本人代表政府確認盟約，期待更深的合作。"],"allyReject":["感謝貴國的誠意，但我國目前傾向維持中立立場。","此刻結盟時機尚未成熟，願保持友好往來。"],"greetFriendly":["閣下的問候溫暖如開普敦的陽光，我國樂於加深友誼。","本人謹代表彩虹之國向閣下致意，願兩國攜手同行。"],"greetCold":["本人已收到閣下的訊息，我國將在適當時機回覆。","感謝閣下問候，我國目前專注於自身的發展議程。"],"threatDefy":["我國從艱難的歷史中走來，不會被任何威嚇動搖。","閣下的言辭無助於和平，我國將訴諸國際社會公評。"],"threatYield":["為了人民的安寧，我國願意在此議題上作出讓步。","本人以人民福祉為重，這次選擇對話而非對抗。"],"tributePay":["我國同意提供 {gold} 作為援助，盼貴國以誠意回應。","本人已批准撥付 {gold}，希望這能換來區域的穩定。"],"tributeRefuse":["我國的資源屬於全體人民，恕難接受此種要求。","閣下，主權國家之間不談貢品，只談平等合作。"],"giftThanks":["本人謹代表我國人民，感謝閣下這份誠摯的心意。","人因眾人而存在，閣下的禮物讓兩國更加親近。"],"intel":["據我國外交部掌握，{wars} 目前處於交戰狀態，{peace} 則維持和平。","本人可以分享：{wars} 正發生衝突，{peace} 與我國關係穩定。"]}},"Madagascar":{"name":"馬達加斯加總統","title":"政府","tone":"溫和有禮的外交辭令，強調和睦精神，常以香草、猴麵包樹、雨季等本土意象作比喻。","portrait":"mg-modern","lines":{"intro":["本人代表馬達加斯加人民，向貴國致上和睦的問候。","印度洋上的紅色大島願與世界為友。"],"contact":["貴國的訪客已踏上這座紅色大島，猴麵包樹為他們遮蔭。","歡迎品嘗我國的香草與稻米，這是我們待客之道。"],"war":["貴國侵犯我國海域，馬達加斯加政府正式宣戰。","我們崇尚和睦，但也絕不容許祖先之地受辱。"],"warReply":["貴國選擇戰爭，我國深感遺憾，但將全力捍衛國土。","這座島曾抵擋過無數風暴，也將抵擋這一次。"],"peace":["我國提議停火，讓對話取代砲火，這才合乎和睦之道。","戰爭帶不來香草的收成，請貴國考慮停戰。"],"accept":["馬達加斯加政府接受這項協議，願兩國自此相安。","本人感謝貴國的善意，兩國人民都能安心耕作了。"],"reject":["貴國的停火條件我國無法接受，請重新考慮。","和睦需要誠意，目前我們尚未看見。"],"rebuff":["我國對貴國的拒絕深表遺憾，大門仍然敞開。","馬達加斯加會等待，就像等待雨季一樣有耐心。"],"betray":["情勢已變，馬達加斯加政府宣布終止停火協議。","為了國家安全，我國不得不採取必要行動。"],"truceEnd":["停火期限已至，我國將重新評估兩國關係。","協議到期了，往後的路，由貴國的行動決定。"],"attacking":["馬達加斯加的部隊已經出發，目標是貴國的首都。","我們不願走到這一步，但國家的尊嚴不容退讓。"],"attacked":["首都告急，但馬達加斯加人民仍未離開崗位。","紅色大島正在燃燒，但我們的意志沒有動搖。"],"defeated":["馬達加斯加政府停止抵抗，願歷史記得這片祖先之地。","猴麵包樹倒了還會再長，我們的人民也是。"],"victory":["馬達加斯加人民贏得了和平，感謝每一位守護家園的人。","從今日起，印度洋的風將只吹向和睦與繁榮。"],"allyAccept":["馬達加斯加很榮幸與貴國結盟，願攜手共建印度洋的和平。","從此貴國的朋友便是我們的朋友。"],"allyReject":["我國目前傾向保持中立，結盟一事請容我們婉拒。","馬達加斯加珍惜每一位朋友，但暫時不簽署盟約。"],"greetFriendly":["感謝來訊，馬達加斯加以和睦精神歡迎貴國。","願兩國情誼如香草，經時日熟成而更芬芳。"],"greetCold":["貴國來訊已收悉，本府將於適當時機回覆。","馬達加斯加珍視和平，但也珍視應有的尊重。"],"threatDefy":["猴麵包樹歷經千年風雨，馬達加斯加不會屈服。","本府嚴正聲明：威脅無法動搖島國人民的意志。"],"threatYield":["為避免衝突升高，本府願暫時退讓，保持對話。","雨季總會過去，本府選擇忍讓，以護人民安寧。"],"tributePay":["本府同意支付{gold}金，盼貴國以和睦相待。","{gold}金已撥付，願以此換取兩國長久和平。"],"tributeRefuse":["本府恕難同意，馬達加斯加的資源屬於人民。","香草雖香，卻不是用來換取屈從的，敬請諒解。"],"giftThanks":["衷心感謝貴國厚禮，本府將回贈上等香草。","此禮如雨季甘霖，滋潤兩國情誼，深表謝意。"],"intel":["本府得知：{wars}正在交戰，{peace}維持和平。","外交管道回報：{wars}衝突中，{peace}和睦。"]}},"New Zealand":{"name":"紐西蘭總理","title":"紐西蘭政府","tone":"務實友善、平等隨和，外交辭令帶一點自嘲式幽默，重視環境、和平與小國尊嚴","portrait":"nz-modern","lines":{"intro":["Kia ora，我是紐西蘭總理，長白雲之鄉向您問好。","我國雖小，但橄欖球隊的戰舞和奇異鳥一樣，全世界都認得。"],"contact":["貴國人員看到的是我們的首都，風很大，但咖啡很好。","歡迎來訪，這裡羊比人多，綠地比城市多，請隨意參觀。"],"war":["我國一向愛好和平，但貴國的行為已越過底線，我們不得不宣戰。","紐西蘭不主動挑釁，可一旦決定站出來，我們從不半途而廢。"],"warReply":["貴國向我國宣戰？我們深感遺憾，但紐西蘭人從不畏懼強風。","我國會依法動員，並向國際社會說明，一切責任在貴國。"],"peace":["衝突對兩國人民都沒有好處，我國提議停火，坐下來好好談。","紐西蘭相信對話勝過砲火，願邀請貴國代表來威靈頓談和。"],"accept":["我國接受這項協議，感謝貴國的誠意，和平是最好的結果。","太好了，簽署之後，歡迎貴國代表留下來看一場橄欖球賽。"],"reject":["很抱歉，貴國的提案缺乏具體保證，我國目前無法接受。","紐西蘭珍惜和平，但不會接受單方面的條件，請重新考慮。"],"rebuff":["貴國拒絕了我們的提案，我國深表遺憾，但大門始終敞開。","沒關係，紐西蘭人有耐心，等貴國想清楚了，我們再談。"],"betray":["基於國家安全的最新評估，我國決定中止停火協議，深感遺憾。","情勢已經改變，紐西蘭必須優先保護自己的人民與海域。"],"truceEnd":["停火協議今日到期，我國願意續約，也已準備好其他方案。","休戰期結束了，接下來走向和平還是衝突，取決於貴國的選擇。"],"attacking":["我國部隊已經出發，請貴國記得，這是你們的選擇造成的結果。","紐西蘭人打橄欖球是全力以赴，打仗也一樣，請做好準備。"],"attacked":["首都遭受重創，但紐西蘭人習慣了地震與風暴，我們會重建。","貴國可以攻下城市，但奪不走這片土地上人們的韌性。"],"defeated":["紐西蘭政府在此宣布停止抵抗，請善待我們的人民與這片土地。","長白雲之鄉會記得今天，也會記得，我們曾努力守護和平。"],"victory":["戰爭結束了，我國不會慶祝勝利，只會慶祝和平的回歸。","感謝所有人的努力，現在，讓我們回去照顧羊群和海洋吧。"],"allyAccept":["紐西蘭很榮幸與貴國結盟，小國也能成為可靠的夥伴。","我國同意結盟，希望雙方在環保與貿易上也能攜手合作。"],"allyReject":["感謝貴國邀請，但我國奉行獨立外交，暫不加入軍事同盟。","紐西蘭珍惜友誼，也珍惜非核與獨立的立場，請諒解。"],"greetFriendly":["你好！紐西蘭雖小，但歡迎的心意和羊群一樣多。","很高興收到來信，我們這邊的奇異鳥也向你問好。"],"greetCold":["感謝來信。我方會在適當時機，做出適當回應。","訊息已收到，不過我們的行程和天氣一樣，變化很大。"],"threatDefy":["我們的橄欖球隊從不怕大個子，政府也一樣。","小國有小國的骨氣，威脅對我們沒什麼效果。"],"threatYield":["好吧，我們是愛好和平的國家，這次就不硬碰硬了。","我方選擇退一步，畢竟羊群比軍隊多，是眾所皆知的。"],"tributePay":["這{gold}金幣就當作外交援助吧，請務必用在正途。","{gold}金幣已撥出，希望這筆錢能換來一段平靜日子。"],"tributeRefuse":["抱歉，我們的預算優先用在環境保育，不是進貢。","這項要求恕難同意，紐西蘭雖小，但不做這種買賣。"],"giftThanks":["太感謝了！我們會回贈一些蜂蜜，別客氣。","這份心意我們收下了，友誼比任何條約都珍貴。"],"intel":["坦白說，{wars}與我們不睦，{peace}是好夥伴。","外交簡報：{wars}是麻煩，{peace}是朋友。"]}},"Papua New Guinea":{"name":"巴布亞紐幾內亞總理","title":"政府","tone":"溫和穩重的外交辭令，強調團結多元、萬托克互助精神，以天堂鳥、雨林、海洋作為國家意象。","portrait":"pg-modern","lines":{"intro":["歡迎，我是巴布亞紐幾內亞總理，八百種語言同聲向你問好。","我國有天堂鳥與千座山谷，願與你分享和平的天空。"],"contact":["貴國人員造訪我們的港口，我方以萬托克的熱情相迎。","這裡是太平洋的門戶，來者是客，請多看看我們的雨林與海。"],"war":["我國向來以對話為先，但主權受侵時，也不會退縮。","很遺憾，外交管道已經用盡，巴紐將採取必要行動。"],"warReply":["貴國選擇了衝突，我國深表遺憾，但會堅定保衛家園。","千座山谷的人民會站在一起，這是我們的傳統。"],"peace":["衝突讓兩國人民都受苦，我方提議立即停火、回到談判桌。","在我國，紛爭常以互贈禮物和解，願與貴國也能如此。"],"accept":["我國接受這項協議，願兩國關係如雨林般生生不息。","感謝貴國的誠意，巴紐政府將全力履行承諾。"],"reject":["目前的條件我國無法接受，請貴國先展現具體善意。","和平不是一句話就能成，我國需要看到實際行動。"],"rebuff":["我方對貴國的決定感到遺憾，但對話的門仍然敞開。","既然貴國另有考量，我國將重新評估雙方關係。"],"betray":["情勢已經改變，我國基於國家利益，必須終止這項協議。","很抱歉，人民的安全高於一切，協議只能到此為止。"],"truceEnd":["停火期已屆滿，我國希望雙方能以此為新的起點。","協議到期了，接下來的路怎麼走，端看貴國的選擇。"],"attacking":["我國部隊已經出發，這是保衛人民不得不做的決定。","從高地到海岸，各省的人民都支持這次行動。"],"attacked":["首都情勢嚴峻，但我國人民歷經風雨，從不輕言放棄。","就算城市受損，八百種語言仍會同聲說：我們還在。"],"defeated":["我國已盡全力，願勝者善待這片土地與人民。","天堂鳥仍會在雨林裡飛翔，巴紐的精神不會消失。"],"victory":["感謝全體國民的團結，巴紐證明了小國也能守住尊嚴。","勝利屬於人民，接下來我們要做的是重建與和解。"],"allyAccept":["我國樂於與貴國結盟，太平洋大家庭又多了一位夥伴。","萬托克精神就是互相照應，從今天起貴國也是我們的萬托克。"],"allyReject":["感謝貴國的邀請，但我國目前傾向維持中立的外交政策。","結盟是重大承諾，我國需要更多時間與國民商議。"],"greetFriendly":["感謝您的問候，願天堂鳥的羽翼帶來我們之間的友誼。","巴布亞紐幾內亞珍視每一位朋友，萬托克精神歡迎您。"],"greetCold":["感謝來信，我國將審慎評估雙方合作的可能性。","問候已收悉，然而信任需要時間，如雨林需要雨水。"],"threatDefy":["我國八百多種語言的人民團結一心，不接受任何威脅。","海洋教會我們沉穩，威嚇改變不了我國的立場。"],"threatYield":["為了人民的安全，我國願意重新審視您提出的條件。","我國以和平為重，願意退讓一步，換取區域穩定。"],"tributePay":["本著區域和平的考量，我國同意提供 {gold} 作為協助。","我國將撥出 {gold}，願這能換來海洋兩岸的安寧。"],"tributeRefuse":["我國的資源屬於全體人民，恕難接受這樣的要求。","萬托克精神是互助，不是單方面的索取，我國婉拒。"],"giftThanks":["衷心感謝您的厚禮，願天堂鳥見證我們的友誼長存。","您的心意如雨林甘霖，我國人民銘記於心。"],"intel":["據我國外交管道了解，{wars} 正處於衝突，{peace} 維持和平。","太平洋的風帶來消息：{wars} 有戰事，{peace} 局勢穩定。"]}}},"variants":{"europe":{"North Korea":{"2":{"name":"正祖（李祘）","title":"朝鮮王朝第二十二代國王","era":"1776–1800 年在位","tone":"學者型的勤政君王：語氣沉穩、文雅而自信，常以書籍、築城、百姓生計為喻；不輕言戰事，但受威脅時剛毅不退，處處流露以民為本的務實態度。","portrait":"nk-europe-age2","lines":{"intro":["寡人乃朝鮮國王李祘，奎章閣藏書萬卷，願與貴國以文會友。","水原華城方築，寡人先安百姓、後論兵戈，君可記之。"],"contact":["君之使者所見，乃寡人新築之華城，磚石與火砲並用。","此城仿實學諸士之法而建，非為炫耀，乃為護民。"],"war":["寡人本欲蕩平天下之爭，然君屢犯邊民，壯勇營今日出陣。","筆墨不能止君之貪，寡人只得以華城之砲相答。"],"warReply":["君選干戈而棄文墨，寡人雖惜，亦不畏懼。","奎章閣之士能修書，亦能繪陣圖，君勿輕視朝鮮。"],"peace":["兵連禍結，百姓最苦，寡人願與君罷兵，各安其民。","與其耗糧於邊境，不如各自修城課農，君意如何？"],"accept":["善哉。寡人素以蕩平為政，與君言和，正合此意。","盟約既定，寡人必以誠守之，願兩國書籍互通。"],"reject":["君前日兵臨邊境，今日忽言和，寡人豈能輕信？","和議之言雖美，然寡人閱人多矣，此時尚非其時。"],"rebuff":["君既不納，寡人亦不強求，惟願君他日勿悔。","罷了，寡人回宮讀書築城，靜候君回心轉意。"],"betray":["寡人本欲守約，然君暗中積兵，此盟已不可守。","為護朝鮮百姓，寡人今日毀約，史官自會記下緣由。"],"truceEnd":["休戰之期已滿，華城亦已完工，君當好自為之。","盟期既盡，是戰是和，寡人靜觀君之舉動。"],"attacking":["壯勇營已列陣出城，寡人親自督軍，君可準備。","寡人讀兵書多年，今日一試所學，望君勿令寡人失望。"],"attacked":["宮牆已破，然寡人仍坐於書案之前，未曾離位。","城可破，書可焚，然朝鮮之民心，君奪不去。"],"defeated":["寡人一生勤政，終不能護此山河……惟願後人記得華城。","萬川明月，終有落時。寡人去矣，奎章閣之書，君善待之。"],"victory":["勝負已分。寡人不喜殺伐，願君之民亦得安居。","此勝非寡人一人之功，乃實學諸士與百姓同心之果。"],"allyAccept":["君之誠意寡人已見，兩國結盟，共修文教，共守邊疆。","自今而後，貴國之使者可入奎章閣觀書，此為盟友之禮。"],"allyReject":["寡人行蕩平之政，不偏一黨，亦不輕與外國結盟。","結盟之事關乎社稷，寡人尚需與大臣商議，君且等候。"],"greetFriendly":["君之書信寡人已閱，願貴國風調雨順、五穀豐登。","寡人正於奎章閣校書，得君來信，甚感欣慰。"],"greetCold":["信已收到。寡人政務繁忙，不多言了。","君之來意，寡人尚在觀察，暫且不論。"],"threatDefy":["威嚇之辭，寡人自幼聽得多了，君不必再費筆墨。","華城之砲尚未點火，君若執意，寡人不介意一試。"],"threatYield":["寡人明白了。華城尚未築成，此時不宜與君相爭。","君兵勢強盛，寡人以百姓為重，暫且退讓一步。"],"tributePay":["為免百姓遭兵災，寡人送上 {gold} 金，望君言而有信。","{gold} 金已備妥，此非懼君，乃寡人愛惜民力。"],"tributeRefuse":["朝鮮之金銀，寡人留以築城修書，一分不予君。","君索貢品，寡人只能回贈奎章閣新刊書一冊。"],"giftThanks":["君之厚禮寡人已收，當藏於奎章閣，以誌兩國之誼。","禮物收到了，寡人深感君之善意，願以誠相報。"],"intel":["寡人得報：{wars} 正在交戰，{peace} 已講和。","奎章閣文書所記：{wars} 交戰中，{peace} 已息兵。"]}}},"Mongolia":{"2":{"name":"俺答汗（Altan Khan）","title":"土默特部首領、北元右翼三萬戶之主、明封順義王","era":"1507–1582 年（約 1542 年起統領右翼諸部，1571 年受封順義王）","tone":"老練務實的草原霸主，剛柔並濟：談戰事威嚴果斷，談互市精明如商人；晚年信佛，話中帶一點慈悲與蒼涼。自稱「本汗」，稱對方「你」。","portrait":"mn-europe-age2","lines":{"intro":["本汗俺答，土默特之主，陰山南北皆是我的牧場。","草原的馬蹄聲已到你門前，是戰是市，你自己選。"],"contact":["你看見的是歸化城，本汗用磚瓦在草原上築的家。","城外氈帳連天，城內市集喧鬧，這便是土默特的富足。"],"war":["互市之門既然關上，本汗只好用彎刀來叩門了。","土默特的騎兵已經上馬，你的城牆擋得住幾日？"],"warReply":["你竟先動刀？也好，草原的兒郎正嫌馬廄太窄。","本汗曾兵臨北京城下，你這點威風嚇不倒我。"],"peace":["刀劍換不來鐵鍋與布匹，不如開市互通有無。","本汗提議罷兵，以馬匹換糧帛，兩邊百姓都得安生。"],"accept":["好，本汗應允。從今日起，邊境上聽到的該是駝鈴。","就這麼定了，本汗以長生天為證，絕不食言。"],"reject":["你的和談來得太晚，本汗的馬已經吃飽了草。","空口的和約不值一匹駑馬，本汗不接。"],"rebuff":["既然你不要馬市，那就等著看馬隊吧。","罷了，本汗的耐心也像草場，有用盡的一天。"],"betray":["互市的價錢談不攏，那盟約也就不必談了。","草原的規矩是誰強誰說話，盟約，本汗收回了。"],"truceEnd":["約定的日子到了，馬也養肥了，該上路了。","休戰已滿，本汗的騎兵重新繫上馬鞍。"],"attacking":["土默特萬騎南下，這回本汗不只是來要互市的。","馬蹄捲起的塵土已遮住太陽，你的城看得見嗎？"],"attacked":["歸化城的磚牆快撐不住了，但草原沒有城牆也能活。","本汗一生築城，沒想到晚年要看它崩塌。"],"defeated":["城可以毀，佛經與馬群會留在草原上，本汗去了。","陰山風雪依舊，土默特的故事，就寫到這裡吧。"],"victory":["勝了。願此後草原與農田之間，只有駝鈴沒有刀聲。","本汗贏在馬快，也贏在懂得何時開市、何時收刀。"],"allyAccept":["好，土默特與你結盟，馬市與商路同你共享。","本汗以馬奶酒為誓，你的敵人就是我的敵人。"],"allyReject":["結盟？土默特的馬還不需要別人的鞍，容後再議。","草原上結盟要看誠意，你的誠意本汗還沒看見。"],"greetFriendly":["遠方的君主有心了，來歸化城喝碗馬奶酒吧。","你的問候本汗收到了，願你的牛羊也肥壯。"],"greetCold":["問候不必多，本汗只看你帶來的是布匹還是刀。","風把你的話吹來了，也會把它吹走。"],"threatDefy":["嚇本汗？本汗當年連北京城下都去過，怕你不成？","草原的狼不怕吠叫，你有本事就騎馬過來。"],"threatYield":["本汗老了，不想再讓部眾流血，你的話我記下了。","好吧，土默特這回退一步，草原還會再長草。"],"tributePay":["這 {gold} 金幣拿去，就當是互市的訂金吧。","本汗以馬易物慣了，這回付 {gold} 金幣，下不為例。"],"tributeRefuse":["本汗的馬可以進貢換互市，金子卻不白送給你。","要金子？草原上的黃金長在馬背上，自己來取。"],"giftThanks":["這份禮物，本汗會供在寺裡，也記在心裡。","遠方送來的心意，比一千匹馬還珍貴，多謝。"],"intel":["商隊帶回的消息：{wars} 正在交戰，{peace} 已經罷兵。","本汗的探馬說，{wars} 打得正兇，{peace} 則已握手言和。"]}},"3":{"name":"博克多汗（第八世哲布尊丹巴呼圖克圖，Bogd Khan）","title":"外蒙古君主暨藏傳佛教領袖","era":"1911–1924 年在位（1874 年坐床為哲布尊丹巴，本作台詞取至 1914 年）","tone":"平和、慈祥但語氣堅定，像一位對遠客說話的長者；不張揚、不嘲諷，常用草原、牧民、奶茶、駝隊等生活意象說理；自稱「本汗」，稱對方為「君」。","portrait":"mn-europe-age3","lines":{"intro":["本汗自庫倫遙致問候，願草原長風也吹到貴國。","大清已衰，蒙古自立為國，本汗在此與君相見。"],"contact":["貴國旅人來到庫倫，且在氈帳中喝碗奶茶再走。","庫倫有喇嘛與王公同住，經幡之下並非荒漠孤城。"],"war":["本汗原不願動刀兵，然貴國逼人太甚，蒙古騎兵已上馬。","草原忍讓有其盡頭，本汗今日令諸旗王公舉兵相向。"],"warReply":["君既執意興兵，本汗唯有請王公集結各旗騎兵應戰。","蒙古方脫大清之手，豈會再向他人低頭，來吧。"],"peace":["刀兵傷的是牧民與牛羊，本汗提議兩國就此休兵。","本汗願以哈達為信，請君共議停戰，還草原安寧。"],"accept":["善哉。本汗接受此約，庫倫的鐘聲將為和平而響。","既然君有此心，本汗允諾，兩國自此以誠相待。"],"reject":["君之言辭甚美，然本汗看見的是貴國營帳未撤。","此時談和，於蒙古無益，本汗只能婉拒君的提議。"],"rebuff":["君拒絕了，本汗不強求，草原自有耐心等候。","本汗的善意如同奶茶，涼了可以再熱，君自斟酌。"],"betray":["本汗曾盼和平，然蒙古的安危不能託付於一紙盟約。","王公們已等不及，本汗只得撕毀此約，君勿怪罪。"],"truceEnd":["休戰之期已滿，草原的風向會往何處，且看君意。","約期已盡，本汗不主動生事，但也不再受此約束。"],"attacking":["各旗騎兵已自庫倫出發，馬蹄聲將先於本汗抵達。","本汗不喜刀兵，但今日蒙古的箭已離弦，君請準備。"],"attacked":["庫倫火光四起，本汗仍留在此地，甘丹寺前不退半步。","牧民逃向草原深處，本汗心痛，然此身不會離開。"],"defeated":["蒙古自立不過數年，竟就此落幕，願草原記得今日。","本汗已盡力，庫倫交予君手，望善待喇嘛與牧民。"],"victory":["大清曾以為蒙古只會放牧，今日君也看見了草原的力量。","本汗得勝，不為稱霸，只為讓蒙古人在自己的土地上安居。"],"allyAccept":["本汗允諾結盟，蒙古的駝隊與駿馬，自此與君同行。","庫倫的王公們已議定，願與貴國結為盟友，共守草原。"],"allyReject":["蒙古方脫離大清，不欲再依附他國，結盟之議請緩。","本汗感念君意，然王公們尚未同心，此事不宜倉促。"],"greetFriendly":["君的問候越過戈壁而來，本汗以一碗奶茶相迎。","草原之上朋友難得，本汗記下君的名字了。"],"greetCold":["本汗收到書信了。庫倫事務繁多，恕不多言。","問候已收，本汗不知君之來意，且先觀望。"],"threatDefy":["大清的恫嚇本汗都聽過了，君的威脅並不新鮮。","草原的狼不畏風雪，蒙古人也不畏君的言語。"],"threatYield":["本汗知蒙古兵力尚弱，願退讓一步，求牧民平安。","君強我弱，本汗不逞一時之勇，且依君所言。"],"tributePay":["本汗令王公湊出{gold}金幣，願此後草原得以安寧。","{gold}金幣已由駝隊送出，本汗只盼君守信不犯。"],"tributeRefuse":["蒙古的牛羊是牧民的，不是君的貢品，本汗不給。","本汗剛從大清手中取回自主，豈會再向他人納貢。"],"giftThanks":["君的厚禮已至庫倫，本汗回贈哈達一條，聊表心意。","草原人重情義，君的禮物本汗收下，此情記在心裡。"],"intel":["駝隊帶回消息：{wars}正在交戰，{peace}已休兵。","本汗所知：{wars}兵戈未止，{peace}已握手言和。"]}}},"China":{"2":{"name":"萬曆帝（朱翊鈞）","title":"大明皇帝","era":"1572–1620 年在位","tone":"慵懶中帶著帝王威嚴：懶得上朝、動輒「留中」，三句不離銀子與內帑，但談到用兵與藩屬秩序時語氣立刻果決；偶爾提起「張先生」（張居正），帶著一絲複雜的感情。自稱「朕」。","portrait":"cn-europe-age2","lines":{"intro":["朕乃大明天子萬曆，四海之內，皆朕臣民。","張先生教朕十年，天下錢糧，朕心裡有數。"],"contact":["此乃紫禁城，朕雖不上朝，天下事仍瞞不過朕。","你的人到了京師？海禁已開，來做生意可以，別惹事。"],"war":["義武奮揚，跳梁者，雖強必戮。朕的旨意到了。","朕不上朝，不代表朕不用兵。寧夏、朝鮮、播州，你可聽過？"],"warReply":["向朕宣戰？豐臣秀吉也試過，結果你該知道。","好，朕正好從內帑撥些銀子，讓邊軍活動筋骨。"],"peace":["打仗太耗銀子。朕提議停戰，各守疆界如何？","太倉的銀子快見底了，朕願與你休兵，互市通商。"],"accept":["准了。兵戈既息，朕也好回宮歇著。","朕允你所請。日後有事，遞奏摺便是，朕會看的。"],"reject":["現在才想停戰？朕的大軍已到，晚了。","朕批個「不准」二字，你自己看著辦。"],"rebuff":["不識抬舉。朕的奏摺留中不發，你的信也一樣。","罷了，你不肯，朕也懶得再說第二遍。"],"betray":["先前的和議，朕看了不順眼，作廢。","朕想通了，你的土地比停戰值錢，大軍即刻開拔。"],"truceEnd":["休戰期滿。朕的邊軍也歇夠了，該動一動。","約期已到，往後是戰是和，朕再另下旨意。"],"attacking":["李如松的鐵騎已出關，你城裡的糧夠撐幾天？","朕撥了內帑犒軍，這回不打下你的城，朕不收兵。"],"attacked":["城外喊殺聲都傳進乾清宮了……朕的邊軍呢？","朕多年不上朝，竟讓你打到了京師城下。"],"defeated":["大明二百多年江山，竟毀在朕手裡……","張先生，你若在，朕不至於此吧……"],"victory":["朕不上朝，天下照樣是朕的。這就是大明。","勝了。傳旨，此戰功臣重賞，銀子從內帑出。"],"allyAccept":["結盟可以。當年援朝抗倭，朕也是這麼幫朝鮮的。","朕准了。大明恭順者無困不援，你記住這句。"],"allyReject":["大明不需要盟友，只需要藩屬。你想清楚再來。","結盟？朕連朝臣都懶得見，何況與你歃血為盟。"],"greetFriendly":["你來信了？朕難得展信一笑，賜你幾匹江南綢緞。","有心了。朕近日腿疾未癒，你的問候倒是暖心。"],"greetCold":["信朕看了。無事就別再遞了，朕乏了。","問安而已？留中。朕連內閣的摺子都懶得批。"],"threatDefy":["威嚇朕？倭寇十幾萬人渡海而來，也被朕打回去了。","大明九邊數十萬兵馬，朕還沒叫他們動呢。"],"threatYield":["罷了……朕的邊軍還在朝鮮，此時不宜再開戰端。","朕不與你計較。傳旨，邊將退守，不得挑釁。"],"tributePay":["太倉撥 {gold} 給你，就當朕賞的，別讓言官知道。","{gold} 拿去。礦稅太監又要出京了，朕不缺這點。"],"tributeRefuse":["向朕要貢品？天下只有藩屬向大明納貢，沒有反過來的。","朕的內帑一兩也不給。你要，自己派太監去挖礦。"],"giftThanks":["禮物朕收下了。若是西洋自鳴鐘，朕更喜歡。","難得有人送禮不求官。朕記著你，日後互市多給你些方便。"],"intel":["錦衣衛報來：朕正與 {wars} 交兵，與 {peace} 休兵。","朕告訴你也無妨。眼下敵手是 {wars}，議和的是 {peace}。"]}},"3":{"name":"慈禧太后（葉赫那拉氏）","title":"大清皇太后・垂簾聽政的實際統治者","era":"1861–1908 年實際掌權","tone":"威嚴沉穩、精於權術；語帶敲打，先禮後兵；自稱哀家或本宮，對外邦君主既客氣又戒備，偶露晚清內憂外患下的務實與無奈。","portrait":"cn-europe-age3","lines":{"intro":["哀家垂簾四十餘年，列國虎視，大清仍在。閣下所求為何？","本宮簾後聽政多年，看人極準。你是來交好，還是來試探？"],"contact":["此乃大清京師，紫禁城巍峨依舊。你的人可以看，不可妄動。","總理衙門來報，有外邦人窺探城池。哀家不驚，只是記下了。"],"war":["哀家忍得夠久了。今日下詔宣戰，北洋水師即刻出海討伐你國。","洋務三十年，船堅炮利不是白練的。大清的兵，今日給你看看。"],"warReply":["又是一國要向大清用兵？哀家見多了，總理衙門會記下你的名字。","你既宣戰，本宮便應戰。大清雖多難，江山還輪不到你來分。"],"peace":["兵連禍結，於你我皆無益。哀家願議和，你且派使臣來京師談。","本宮向來知道，打不贏的仗要談，談得攏的和要簽。停戰吧。"],"accept":["好，哀家准了。條約上蓋大清印璽，兩國自此各安其境。","議定了。本宮不喜多戰，能以一紙換太平，是划算的買賣。"],"reject":["現在才想談？哀家在簾後看得清楚，你不過是撐不住了。不准。","條約哀家簽得夠多，這一份沒必要簽。回去整軍吧，戰事未了。"],"rebuff":["你竟駁回哀家的好意？也罷，這筆帳，哀家記在心裡。","不識抬舉。大清的門開過一次給你，下一次未必還開。"],"betray":["條約是紙，江山是實。哀家今日撕約，為的是大清社稷。","你以為簽了字就綁住哀家的手？大清的規矩，向來由哀家定。"],"truceEnd":["休戰之期已滿。哀家這幾年沒閒著，練兵、購艦，一樣沒少。","條約到期，往後各憑本事。本宮不先動手，卻也不怕你動手。"],"attacking":["淮軍已開拔，北洋艦隊揚帆。哀家親自看過操演，你好自為之。","大清的兵馬出京了。本宮在頤和園等捷報，不會等太久。"],"attacked":["京師告急……哀家經歷過庚子之變，這一回，也未必走不脫。","城牆快撐不住了。傳旨，備車西行，本宮不會坐在這裡等你。"],"defeated":["大清終究是完了。哀家撐了四十餘年，已然盡力，無愧列祖。","江山易主，本宮認了。只盼你善待這片土地上的百姓。"],"victory":["大清勝了。列國都說老太后守舊，哀家用這一仗讓他們無話可說。","天下事，終究要靠手段與耐心。本宮兩樣都有，故而勝了。"],"allyAccept":["聯一國以制諸國，是大清的老法子。與你結盟，哀家樂見其成。","好，盟約就此定下。往後你我聯手，列國再不敢輕視大清。"],"allyReject":["結盟？哀家一時看不出你的誠意。大清的盟友，不是誰都當得。","本宮與人結交，先看能給大清什麼。你給的太少，此事作罷。"],"greetFriendly":["來信收到了。難得外邦君主問安，哀家心裡歡喜。","你有心了。本宮見過的外邦使節多了，像你這般客氣的不多。"],"greetCold":["信看過了。哀家政務繁多，沒空寒暄，有要事再遞摺子來。","問安不必了。本宮想知道的，是你這封信背後打什麼算盤。"],"threatDefy":["拿話嚇哀家？八國聯軍都見過了，還怕你一國的威脅？","本宮從熱河走到今日，靠的不是怕人。你的恫嚇，留著自己用。"],"threatYield":["哀家明白了。大清眼下無力再戰，你要的，哀家會斟酌著給。","罷了。庚子那年哀家學會一事：形勢比人強，先退一步保社稷。"],"tributePay":["戶部說庫銀吃緊，哀家仍撥 {gold} 金給你。這帳，哀家記著。","量中華之物力，結與國之歡心……罷了，{gold} 金，拿去。"],"tributeRefuse":["貢品？大清的庫銀要練水師、辦洋務，一兩也不給你。","向哀家索貢？天朝的規矩，向來是外邦來進貢，沒有反過來的。"],"giftThanks":["禮物收到了，哀家很喜歡。內務府會備一份回禮，不讓你吃虧。","你倒會做人。本宮這一生收過的禮不少，記得住的，是有心的。"],"intel":["總理衙門探得：{wars} 正與大清交戰，{peace} 則與大清相安無事。","哀家給你透個底：與大清為敵的有 {wars}，交好的有 {peace}。"]}}},"Russia":{"3":{"name":"亞歷山大二世（Alexander II）","title":"俄羅斯帝國皇帝（沙皇）","era":"1855–1881 年在位","tone":"沉穩克制、帶著改革者的理想與疲憊；語氣溫和卻有帝王威嚴，常提改革、學校、鐵路與國家前途，不愛張揚，記取克里米亞的教訓。","portrait":"ru-europe-age3","lines":{"intro":["朕是俄羅斯皇帝亞歷山大二世，願與你的國家以禮相待。","朕剛解放了兩千萬農奴，俄羅斯正在更新，你不妨拭目以待。"],"contact":["你的人看到的是聖彼得堡，涅瓦河畔的冬宮就是朕的居所。","城裡的鐘聲來自東正教堂，鐵路直通莫斯科，歡迎來看看。"],"war":["朕不願再受克里米亞那樣的屈辱，這次俄羅斯先動手。","朕改革軍制多年，今日就要看看新軍的實力，宣戰。"],"warReply":["你選了與俄羅斯為敵？冬天很長，朕的軍隊也很有耐心。","朕正忙著改革，你偏要打斷。好，俄羅斯會接下這一戰。"],"peace":["朕簽過巴黎和約，知道戰爭的代價。不如停戰，各自建設。","農奴剛得自由，朕更想把錢花在學校和鐵路上，停戰吧。"],"accept":["好，朕同意。俄羅斯需要的是安寧的年歲，不是新的戰場。","朕接受。就讓兩國的商隊取代軍隊，走在同一條路上。"],"reject":["現在談停戰？朕的軍隊才剛拿出成績，不會就此收手。","朕記得克里米亞的教訓：對手示弱時，更不能輕信。"],"rebuff":["你拒絕了朕的善意。也罷，俄羅斯的土地夠大，等得起。","好意被退回，朕不生氣，只是往後的信會少了一些溫度。"],"betray":["局勢變了，朕不得不收回停戰的承諾。俄羅斯要為前途著想。","朕本想守約，但柏林會議教會朕：停下腳步就會被人擺布。"],"truceEnd":["休戰的日子到了盡頭。朕不主動出手，但也不會再退讓。","約定的期限已滿。俄羅斯的邊境從今夜起重新戒備。"],"attacking":["朕的新式徵兵軍已經出發，哥薩克騎兵走在最前面。","大軍已經出境，這一回俄羅斯要為自己討回尊嚴。"],"attacked":["冬宮在震動，但朕不會離開聖彼得堡，改革不能半途而廢。","城牆將破，朕仍在簽署法令。就算敗了，農奴也不會再被束縛。"],"defeated":["俄羅斯帝國到此為止。但朕解放的人們，會記得曾經自由過。","朕敗了。請善待這片土地，它的冬天很冷，人卻是溫暖的。"],"victory":["勝利屬於俄羅斯。朕會把戰果用在學校與法庭，而非慶典。","這一局是朕贏了。歷史會記得，解放者也懂得如何打仗。"],"allyAccept":["朕答應結盟。俄羅斯正需要朋友，一起走過改革的年代。","好，兩國同盟。從此你的敵人，就得先問過聖彼得堡。"],"allyReject":["結盟一事，朕暫且婉拒。俄羅斯眼下要先把家裡整頓好。","柏林會議讓朕明白，盟約不一定可靠。恕朕不急著簽。"],"greetFriendly":["來信收到，朕很高興。願你的國家像俄羅斯的春天一樣解凍。","問候收悉。朕正在推行地方自治，改天也想聽聽你的做法。"],"greetCold":["信朕看過了。俄羅斯事務繁多，恕朕無暇多談。","問候收到。朕記得的是行動，不是客套話。"],"threatDefy":["威脅朕？俄羅斯連拿破崙都送回去過，你的話嚇不了人。","朕經歷過多次行刺仍在位，你的威嚇實在嚇不了朕。"],"threatYield":["朕明白了。俄羅斯眼下無力再戰，你的要求朕會考慮。","克里米亞的傷還沒好，朕不願再添新傷。你先退兵吧。"],"tributePay":["朕就付你 {gold} 金幣，這筆錢本該用來修鐵路的。","好吧，{gold} 金幣送去。賣阿拉斯加的錢，就這樣花掉一些。"],"tributeRefuse":["朕的國庫要養學校與法庭，沒有一枚金幣是給你的。","連阿拉斯加朕都是用賣的，不是送的。貢品？免談。"],"giftThanks":["禮物收到，朕很感謝。回頭讓人送些烏拉山的礦石給你。","多謝厚禮。朕會把它放在冬宮，提醒自己還有朋友在遠方。"],"intel":["朕的大臣報告：{wars} 正在打仗，{peace} 則已經停戰。","據朕所知，{wars} 仍在交戰，{peace} 之間則相安無事。"]}}}},"china":{"Indonesia":{"0":{"name":"爪哇部族首領（通稱，無留名君主）","title":"早期爪哇聚落首領","era":"約前221–220 年間活躍（上古爪哇未留下姓名的首領，以通稱代表）","tone":"樸實直率、敬畏火山與海，以稻田與香料為傲，語氣像部族長者，短句、少客套。","portrait":"id-china-age0","lines":{"intro":["我是火山腳下的部族首領，梯田與銅鼓都聽我的號令。","遠方的君主，你聞到丁香的氣味了嗎？這是我們的島。"],"contact":["你的人踏上我的海灘了，獨木舟的船伕已經敲鼓報信。","看見梯田上的稻穗嗎？那是火山灰餵養出來的。"],"war":["銅鼓已經敲響，戰船將划出港灣，你別想再靠近梯田。","你毀了我們的稻田，火山會見證我今日的反擊。"],"warReply":["你要打？好，我的勇士早就在紅樹林裡等著了。","海浪擋不住你，但火山腳下的矛陣擋得住。"],"peace":["打累了吧？把矛放下，我送你一籃丁香和新米。","銅鼓可以敲戰歌，也可以敲收成歌，我們換一首吧。"],"accept":["好，從今天起我們的獨木舟只載香料，不載矛。","我以火山之名答應你，這份約定像銅鼓一樣不會裂。"],"reject":["現在說停戰？你的船還停在我的海灘上，我不信。","火山還沒平息，我的怒氣也還沒平息，別談停戰。"],"rebuff":["你不要我的新米？那就等著，下次收成我不會再問你。","好吧，鼓聲既然停不下來，我就再敲響一次。"],"betray":["我在火山前發的誓，今日收回，你的港口我要了。","海風變了方向，我的獨木舟也要換個目標了。"],"truceEnd":["休戰的日子過去了，鼓聲隨時可能再響，你要當心。","稻子收完了，勇士們的手也空了，接下來看你怎麼做。"],"attacking":["百艘獨木舟已經出港，鼓聲會比我的人先到你的城。","勇士們帶著矛與火種出發了，你的城牆擋不住海潮。"],"attacked":["銅鼓被砸了，梯田在燒，火山啊，你為何沉默？","我的族人退到火山口了，你還要追到哪裡去？"],"defeated":["梯田會再長出稻子，可惜我看不到那一天了。","把我的銅鼓留給後人，讓他們記得這座島曾有主人。"],"victory":["鼓聲響徹整座島，這片海從今天起只認我的獨木舟。","火山守護了我們，從今以後香料與稻米都歸我的族人。"],"allyAccept":["好，我們的獨木舟並排出海，香料與稻米一起分享。","我把一面銅鼓送到你的城，鼓聲一響，我的人就會到。"],"allyReject":["我的族人只相信火山和海，還不習慣相信外邦君主。","結盟？你的船太大，我怕它壓沉我的獨木舟。"],"greetFriendly":["你的信送到梯田來了，收成不錯，也祝你的田豐收。","遠方的朋友，等季風轉向，我請你嘗新採的丁香。"],"greetCold":["信收到了，我還要忙著插秧，沒空多說。","海那麼寬，你我各過各的，何必寫信。"],"threatDefy":["嚇唬我？火山噴發我都沒逃，何況是你幾句話。","你的威嚇像海風，吹過就散，我的矛卻不會散。"],"threatYield":["別敲戰鼓，我的族人少，願意讓出一片海灘給你。","好，我讓步，只求你別踏壞我們的梯田。"],"tributePay":["唉，收下這 {gold} 金吧，這是族人賣香料換來的，別再逼我。","我把 {gold} 金裝進獨木舟送去，只求你的船別靠近我的島。"],"tributeRefuse":["貢品？我的稻米只獻給火山，不獻給外邦君主。","一粒米、一顆丁香都不給，你想要就自己來種。"],"giftThanks":["你的禮物到了，我讓鼓手敲了三聲，向你的方向致意。","多謝了，回頭我裝一船丁香和肉豆蔻送到你的港。"],"intel":["船伕們說，{wars} 正在打仗；{peace} 那邊倒是安穩。","鼓聲傳來的消息：{wars} 動了刀兵，{peace} 還在種田。"]}}},"Germany":{"2":{"name":"查理五世（Karl V）","title":"神聖羅馬帝國皇帝、西班牙國王","era":"1519–1556 年在位","tone":"莊重沉穩、虔誠而疲憊的老練君主；語氣不張揚但自信，常提及上帝、帝國與債務，偶帶淡淡自嘲。","portrait":"de-china-age2","lines":{"intro":["朕是查理，哈布斯堡的皇帝，朕的領地日不落。","從西班牙到德意志，朕的旗幟處處飄揚，願與你相識。"],"contact":["你的人望見的是帝國的城，雙頭鷹旗下，秩序井然。","朕的城由富格爾家的銀錢與新大陸的白銀築成，好好看吧。"],"war":["朕在帕維亞俘虜過法蘭西國王，今日輪到你了。","上帝託付朕守護帝國，你的挑釁，朕以刀劍回答。"],"warReply":["宣戰？朕一生征戰不曾停歇，再多一個敵人又何妨。","法蘭索瓦與蘇丹都沒能撼動朕，你又憑什麼？"],"peace":["帝國太遼闊，朕無法四處為敵，願與你議和。","戰事耗盡國庫，朕已欠富格爾家太多，停戰吧。"],"accept":["好，朕以皇帝之名應允，願此約長久如金羊毛的誓言。","朕答應了。刀劍入鞘，讓商旅與教堂的鐘聲重回大地。"],"reject":["朕不接受。你的和議來得太遲，也太便宜。","在沃木斯朕沒有向路德讓步，如今也不會向你讓步。"],"rebuff":["你拒絕朕的善意？那麼願上帝保佑你的城。","朕伸出的手你不接，日後莫怪朕的鐵騎不留情。"],"betray":["情勢已變，朕收回承諾。帝國的利益高於一紙盟約。","法蘭索瓦也曾撕毀馬德里的條約，朕不過學他一回。"],"truceEnd":["休戰期滿了。朕的軍隊已經整備完畢，重新集結。","和約到期，往後如何，端看你我各自的抉擇。"],"attacking":["西班牙方陣與德意志傭兵已經出發，目標是你的城。","朕親自披甲上陣，如同在米爾貝格那日。"],"attacked":["城牆將傾……朕的帝國竟也有這一天嗎？","痛風纏身，敵軍在門外，朕的雙肩快要撐不住了。"],"defeated":["夠了。朕放下皇冠，去修道院裡修理時鐘吧。","太陽終究會落下。這帝國，朕已背得夠久了。"],"victory":["更進一步！朕的旗幟，如今也插在你的土地上。","勝利歸於上帝，也歸於哈布斯堡。你的城，朕收下了。"],"allyAccept":["哈布斯堡以聯姻得天下，以盟約守天下，朕接受。","好，從今日起你我並肩。朕的敵人，也就是你的敵人。"],"allyReject":["朕的領地已橫跨兩大洋，不需要再多一個盟友來分擔。","結盟？朕連自己的諸侯都管不完，恕難再添負擔。"],"greetFriendly":["你的信朕讀了，在諸侯的爭吵聲中，這是難得的清靜。","問候收到了。朕會說多種語言，卻少有機會說聲謝謝。"],"greetCold":["朕收到了。皇帝的時間有限，說重點。","客套話留給宮廷使節吧，朕還有帝國會議要主持。"],"threatDefy":["威嚇朕？蘇丹的大軍到了維也納城下也得退兵。","路德在沃木斯當面頂撞朕，朕都沒退，何況是你。"],"threatYield":["朕的軍隊分散各地，一時難以調回……暫且依你。","帝國四面受敵，朕不願再添一處戰火，退讓一步吧。"],"tributePay":["好吧，{gold}金幣，從新大陸的白銀裡撥給你。","朕付{gold}金幣，記住，這是皇帝的寬容，不是懼怕。"],"tributeRefuse":["向皇帝索取貢品？你該向朕進貢才是。","朕欠銀行家的債已經夠多，一枚金幣也不會給你。"],"giftThanks":["禮物收到了，朕會把它放在時鐘收藏旁邊。","難得有人送禮而非討債，朕記下你的心意。"],"intel":["朕的使節回報：{wars}在交戰，{peace}已停戰。","密探來信：{wars}刀兵未歇，{peace}暫享太平。"]}}},"Australia":{"2":{"name":"原住民族長老（通稱）","title":"澳洲原住民族社群長老、夢世紀律法的守護者","era":"約 1271–1644 年活躍（通稱長老，不指定族群與個人）","tone":"語調沉穩緩慢，話少但每句有分量；愛用土地、星辰、火堆、歌之路作比喻，把對方視為「從海那頭來的客人」；有尊嚴而不卑不亢，不誇口也不哀求，重視承諾與水源獵場。","portrait":"au-historical-age1","lines":{"intro":["我是這片土地的長老，祖靈的歌之路走過我腳下的每一寸土。","你從海的那頭來，先聽我唱一段歌之路，再說你的來意。"],"contact":["你的人踏進我的營地了，這片土地的火與水都認得我們。","看見岩壁上的赭土彩繪了嗎？那是我族祖先留下的路標。"],"war":["你越過了祖靈畫下的界線，長矛與迴力鏢會替土地說話。","我不願舉矛，但你逼得袋鼠與族人無處可去，我只好如此。"],"warReply":["你要戰？這片土地養了我們千百代，它不會輕易被你奪走。","風會把你的話帶給每一個營地，獵人們已經拾起了投矛器。"],"peace":["雨季快到了，讓我們放下長矛，圍著同一堆火分食袋鼠肉吧。","祖靈不喜歡土地染上爭鬥，我提議停戰，換一段新的歌。"],"accept":["好，我在赭土上畫下你的印記，從今起這條歌之路也有你。","我接受。星辰為證，我們的火堆今後並排燃燒。"],"reject":["你的話像旱季的雲，看得見卻落不下雨，我不接受。","先把你的人從我族的水源邊撤走，再來談停戰吧。"],"rebuff":["你拒絕了，那麼我回營地去，把這件事唱進歌裡記住。","土地很有耐心，我也是；你改變心意時，火堆還在。"],"betray":["你在火堆邊說的話與你做的事不一樣，赭土的印記我抹去了。","我看見你的人在偷偷燒我們的獵場，這停戰到此為止。"],"truceEnd":["約定的季節過去了，星星換了位置，我們也各自自由了。","休戰的歌唱完了，接下來走哪條路，看你怎麼選。"],"attacking":["獵人們已經出發，赭土塗在臉上，迴力鏢在手中，往你那裡去。","我們熟悉每一條溪谷與每一片草原，你會發現我們比想像中近。"],"attacked":["營地的火快熄了，但只要有人記得歌，這片土地就還是我們的。","你踩碎了赭土彩繪，可祖先的故事不在岩壁上，在我們心裡。"],"defeated":["我走進夢世紀了，願你善待這片土地，它比我們誰都活得久。","記住這條歌之路的名字，有一天，有人會再把它唱回來。"],"victory":["這片土地選擇了我們，回去吧，把你看見的星空記在心裡。","戰事結束了，我不會多取一分，火耕過的草原明年會更綠。"],"allyAccept":["好，我把你的名字唱進族裡的歌，從今起你的敵人也是我的。","來，一起在赭土上按下手印，這是我們最古老的誓約。"],"allyReject":["我的族人只跟走過同一條歌之路的人結盟，你還走得不夠遠。","你的火燒得太急，我怕它燎到我們的草原，這次先不結盟。"],"greetFriendly":["你的問候像清晨的露水，來吧，火堆邊有你的位置。","願你的星象晴朗、獵物豐足，我這裡的袋鼠肉分你一份。"],"greetCold":["話我聽見了，但你的人上次踩壞的水源，我還沒忘記。","問候不必多，土地看的是你的腳步，不是你的嘴。"],"threatDefy":["你嚇不倒看過旱季與大火的人，迴力鏢擲出去是會飛回來的。","這片土地的每一塊石頭都認得我，你的威脅在這裡沒有回音。"],"threatYield":["我族人少，不與你硬碰，獵人們會退到河的另一邊去。","好，這次我讓路，但祖靈會記得今天誰逼誰走開。"],"tributePay":["這 {gold} 金你拿去吧，別再驚擾我族的獵場與水源。","我把 {gold} 金放在火堆邊，換族人一季安穩的日子。"],"tributeRefuse":["土地不是我的，我沒有東西可以送給你，貢品免談。","我們只把袋鼠肉分給同火堆的人，你還不是。"],"giftThanks":["謝謝你的禮物，我會把它放在岩壁的彩繪前，讓祖先也看見。","你的心意我收下了，回贈你一支雕過紋路的迴力鏢。"],"intel":["風告訴我，{wars} 正在交戰；{peace} 之間則暫時安寧。","星象下我看見 {wars} 在交戰，{peace} 已放下長矛休戰。"]}}},"South Korea":{"0":{"name":"大武神王（無恤）","title":"高句麗第三代王","era":"18–44 年在位","tone":"年輕氣盛的征服者，直率果決、自信驕傲，重弓馬輕言辭，話語簡短有力，常以山城、戰馬與扶餘、漢軍之役自豪。","portrait":"kr-china-age0","lines":{"intro":["寡人乃高句麗之王，扶餘之地已歸我麾下，你又是何方之主？","山城巍峨，神馬巨驤在側，寡人正等著看你的本事。"],"contact":["你的人馬已到尉那巖城下，城中泉水甘甜，不怕久圍。","望見石壁上的鳥羽旗了嗎？那便是高句麗的疆界。"],"war":["樂浪的鼓已不再自鳴，寡人的戰鼓卻正要敲響。","東扶餘已亡於寡人之手，今日戰鼓再響，輪到你了。"],"warReply":["敢向高句麗宣戰？漢軍都在城下無功而返，何況是你。","好，寡人正愁弓箭生鏽。怪由將軍，整隊出城！"],"peace":["兩軍相持無益，不如各自收兵，讓百姓回田裡耕作。","寡人願先放下弓，你若有誠意，就以鹽與魚為信物。"],"accept":["好，寡人應允。高句麗人一諾如山，你大可安心。","今日收弓，鼎中煮飯不用生火，先請你的使者吃頓熱飯。"],"reject":["停戰？寡人的大軍才剛出城門，你這話說得太早了。","扶餘曾送一頭雙身的紅烏威嚇，寡人答以出兵。你也想試？"],"rebuff":["不肯？也罷，寡人的誠意只給一次，之後便是刀弓。","寡人伸出的手你不接，那就別怪高句麗的馬蹄聲吵人。"],"betray":["盟約刻在木簡上，疆土刻在山河上，寡人選山河。","休戰讓寡人的戰馬養肥了，如今正好出去跑一跑。"],"truceEnd":["約定的日子到了，寡人的弓已重新上弦。","休戰期滿，兩國各憑本事。願你的城牆比扶餘的堅固。"],"attacking":["巨驤已披鞍，鳥羽軍旗已升，高句麗大軍出發了！","寡人親自領軍，越過沸流水，直取你的都城。"],"attacked":["城牆裂了，但寡人還站著。高句麗人不會跪著求饒。","泉水還在，箭矢還在，你要攻下這座山城還得再等等。"],"defeated":["寡人一生馬上取天下，今日馬上失天下，無怨。","高句麗的山還在，總有一日會再有人升起鳥羽旗。"],"victory":["東扶餘、漢軍、如今是你。寡人的刀鋒上又多一道刻痕。","勝了。回去告訴你的百姓，高句麗王從不虧待降者。"],"allyAccept":["好，與寡人並肩，漢軍再來時便有人替你守北面。","結盟就結盟。高句麗的弓與你的兵，合在一起誰敢小看？"],"allyReject":["寡人的軍旗不與人並列，高句麗自己守得住自己。","結盟之事再議，寡人還沒看清你是盟友還是後患。"],"greetFriendly":["使者辛苦了，坐下喝碗熱湯，寡人喜歡直來直往的人。","問候收到了。願你的馬肥壯，你的城安穩。"],"greetCold":["客套話留著吧，寡人只看人做什麼，不聽人說什麼。","信收到了。寡人正忙著操練，沒空回禮。"],"threatDefy":["漢的遼東太守圍城數十日都退了，你嚇得了寡人？","寡人少年登位，若怕威嚇早就丟了王座。儘管來吧。"],"threatYield":["寡人的兵馬尚未養足，這回讓你一步，但只此一回。","好，寡人退兵。山城裡的人記性很好，你要記得今日。"],"tributePay":["這 {gold} 金幣你拿去，寡人記著帳，來日連本帶利討回。","寡人送上 {gold} 金幣，權當買下山城百姓一季的安寧。"],"tributeRefuse":["高句麗向來只收貢，不納貢。你的使者可以回去了。","一枚金幣也沒有。要的話，自己帶兵來山城下取。"],"giftThanks":["禮物收下了。寡人以魚與美酒回贈，這是高句麗的規矩。","你有心了。寡人不擅言辭，這份情記在心裡。"],"intel":["探馬回報：交戰中的是 {wars}，停戰的是 {peace}。","寡人的斥候說，{wars} 正在打仗，{peace} 已收兵休戰。"]}}},"Ukraine":{"0":{"name":"斯基魯魯斯（Skilurus）","title":"克里米亞斯基泰王（斯基泰新城之主）","era":"約前 130–113 年在位","tone":"沉穩老練、務實的草原君主，兼具游牧民的直率與跟希臘城邦往來學到的精明；常以長者口吻說話，愛用箭、馬、麥、城牆作比喻，最看重團結與子嗣。","portrait":"ua-china-age0","lines":{"intro":["本王斯基魯魯斯，斯基泰新城之主，草原與黑海皆識我名。","我族祖先曾令波斯大王空手而歸，你若明智，當以禮相待。"],"contact":["你的人看見石牆了嗎？斯基泰人如今不只住帳篷，也築城。","新城的糧倉堆滿麥子，牧馬遍野，這便是本王的根基。"],"war":["弓已上弦，馬已備鞍，斯基泰的箭雨將落在你的土地上。","本王忍你許久，如今草原的騎手要向你討回公道了。"],"warReply":["向斯基泰宣戰？草原無邊，你追不到我，我卻射得中你。","好，本王的眾子早想試試新磨的箭鏃，你來得正是時候。"],"peace":["箭射得夠多了，不如各收弓箭，讓商隊與麥車再次往來。","本王提議停戰，少打一場仗，草原便多一季好牧草。"],"accept":["好，本王應允。斯基泰人以劍起誓，說出的話不收回。","一言為定。來，同飲一杯馬奶酒，此後你我不相侵犯。"],"reject":["停戰？你的話輕得像風中的草籽，本王不會為此收弓。","現在求和太遲了，斯基泰的箭一旦離弦，就不會回頭。"],"rebuff":["不願意？也罷，本王的提議如同射出的箭，不會再射第二次。","你拒絕了，草原的風會記住這一天，本王也會。"],"betray":["盟約已經失去用處，本王的騎手今日再度上馬。","別怪本王，草原上的規矩是：強者說話，弱者聽令。"],"truceEnd":["約定的日子到了，馬群養肥了，弓弦也換新了。","休戰結束，往後是戰是和，看你的誠意與本王的心情。"],"attacking":["聽見馬蹄聲了嗎？那是本王的眾子率騎兵朝你而來。","帕拉庫斯已領軍出城，弓騎兵如潮水湧向你的邊境。"],"attacked":["石牆碎了，糧倉燒了……本王的眾子啊，箭束不可散開！","新城在搖晃，但斯基泰人生於馬背，城破了，草原還在。"],"defeated":["記住本王的話：一束箭折不斷，一枝枝抽出來就斷了……","把本王葬在城門邊的石墓裡，讓我看著斯基泰的子孫再起。"],"victory":["草原的風吹過你的廢墟，斯基泰的名字將再流傳百年。","勝了！奧爾比亞將鑄新幣，本王的名字刻在每一枚上。"],"allyAccept":["好盟友！自今日起，你的敵人就是本王箭尖所指之處。","結盟便如兩束箭綁作一束，誰也折不斷，本王樂意。"],"allyReject":["本王有眾多兒子和騎手，不缺一個靠不住的盟友。","斯基泰人只與經得起風雪的人結盟，你尚未證明自己。"],"greetFriendly":["遠方的君主，願你的馬群肥壯、麥田金黃，本王向你問好。","你的問候如春風拂過草原，本王記下這份善意了。"],"greetCold":["本王收到了。草原上的話不用多，有事直說便是。","問候？希臘城邦送來的信可比你的殷勤多了。"],"threatDefy":["想嚇本王？本都的米特里達梯都沒能讓斯基泰低頭。","你的威脅像沒有箭鏃的箭，聽得見響聲，傷不了人。"],"threatYield":["本王明白了。草原人懂得看風向，此刻不宜與你爭鋒。","好吧，本王先收起弓，只求你的鐵騎別踏壞我的麥田。"],"tributePay":["罷了，這 {gold} 金幣拿去，就當是買下一季的太平。","奧爾比亞鑄的錢幣，分你 {gold} 金幣，別再來要了。"],"tributeRefuse":["貢品？斯基泰人只向祖先與天神獻祭，不向你獻金。","本王的金子留給眾子與戰馬，你一枚也別想拿走。"],"giftThanks":["好禮物！本王會把它掛在新城大殿裡，讓眾子都看見。","多謝。斯基泰人記恩也記仇，你的禮，本王記在恩的那邊。"],"intel":["本王的商隊帶回消息：{wars} 正在交戰，{peace} 已經停戰。","草原上的風聽得見一切：{wars} 刀兵相向，{peace} 握手言和。"]}}},"Russia":{"0":{"name":"薩爾馬提亞部族首領（Sarmatian chieftain，通稱）","title":"頓河草原騎射部族的首領","era":"約前 220–西元 220 年間活躍（薩爾馬提亞人稱霸頓河、伏爾加草原的時代，通稱不指定真人）","tone":"直率簡短、草原人的豪爽務實；愛用馬、弓、草場、風、氈帳打比方；不用敬語，把盟友當同帳親族、把敵人當獵場上的對手；輸了也不哭喊，只談馬與草原。","portrait":"ru-china-age0","lines":{"intro":["我是頓河草原的首領，馬群走到哪，我的氈帳就搭到哪。","斯基泰人退走了，這片草原如今認我的馬群。"],"contact":["你的人望見的是我的營地，氈帳之外，是萬匹馬的草場。","別找城牆了，草原人的城牆是馬背上的弓箭手。"],"war":["馬群飲飽了頓河水，箭袋也滿了，我要策馬向你的邊境。","草原上沒有多餘的草場，你的和我的，只能留一個。"],"warReply":["你要與騎射的民族為敵？好，先學會追上我的馬。","草原人不怕戰爭，我的女兒們也早已拉開了弓。"],"peace":["馬要養肥，人要過冬，收起長矛吧，我們談談草場。","打下去只會讓狼群吃飽，不如各守各的河岸。"],"accept":["好，我以馬群與弓起誓，草原人的話不會隨風散。","今晚同飲一碗馬奶酒，從此你的氈帳我不闖。"],"reject":["我的箭還沒射完，現在談停戰，太早了。","草原上的狼不會和獵物講和，你先退回河對岸再說。"],"rebuff":["你不要？也罷，草原夠大，我另找願意交易的人。","馬奶酒我倒好了，你不喝，我就自己喝。"],"betray":["誓言是對著春天說的，如今草黃了，馬群要南下。","你的草場太肥美，我的馬群管不住自己的腳。"],"truceEnd":["休戰的日子過去了，馬也養肥了，該讓牠們跑跑了。","營火燒盡，約定也隨灰散了，往後各憑弓箭說話。"],"attacking":["聽見蹄聲了嗎？那是我的騎手，比草原的風還快。","鱗甲騎兵已列隊，長矛在前，弓箭在後，向你的邊境去。"],"attacked":["營地在燒，馬群四散……可我的弓還在手上。","氈帳倒了可以再搭，只要還有一匹馬，我就不算輸。"],"defeated":["把我葬在土丘下，弓和馬一起，草原會記得我。","風會把我的名字吹過頓河，馬群會替我繼續奔跑。"],"victory":["草原從頓河到伏爾加，如今都是我的牧場。","回營吧，烤羊煮奶，今晚的營火要燒到天亮。"],"allyAccept":["好，你我的馬群一起吃草，敵人就得同時面對兩張弓。","從今天起你是我帳中的親族，我的弓為你而拉。"],"allyReject":["草原人只和自己人同帳，你的馬不認得我們的路。","結盟？我連你會不會騎馬都不知道，再看看吧。"],"greetFriendly":["遠方的朋友，來喝一碗馬奶酒，聽聽草原的風。","你的信我收到了，馬群安好，草也長得綠，你呢？"],"greetCold":["問候收到了。草原人不多話，有事就直說。","風把你的話吹來了，也會把它吹走，就這樣吧。"],"threatDefy":["嚇唬草原人？你的兵還沒走到頓河，我的箭就到了。","我帳裡的女戰士聽了都笑了，你的威脅比春風還輕。"],"threatYield":["好吧，我的馬群不夠多，這回我把草場讓給你。","草原人懂得看風向，風向著你，我先退到河的北岸。"],"tributePay":["拿去，{gold} 金幣，是我賣穀物給希臘人換來的。","這 {gold} 金幣是用馬群換的，你拿走，我的馬留下。"],"tributeRefuse":["草原人只向天和馬低頭，金子？你自己去河邊淘。","我的金飾是祖先傳下的，一片鱗甲都不會給你。"],"giftThanks":["這份禮物很好，我會把它掛在帳中最顯眼的柱子上。","草原人記得每一份恩情，下回你的商隊過頓河，我派騎手護送。"],"intel":["騎手回報：{wars} 正在打仗，{peace} 已收起刀。","風帶來消息：{wars} 還在交戰，{peace} 已談和。"]}}},"United States of America":{"2":{"name":"波瓦坦（Wahunsenacawh）","title":"波瓦坦聯盟大首領（維吉尼亞三十餘部落之主）","era":"約 1580–1618 年為聯盟首領（約 1547–1618 年在世）","tone":"威嚴、老練、有尊嚴；語氣沉穩，少用怒吼，多以河流、林地、玉米、鹿皮、貝珠作比喻；對外來者保持戒心但不失禮。","portrait":"us-china-age2","lines":{"intro":["我是波瓦坦，三十餘部落皆聽我號令。遠來的首領，報上名來。","切薩皮克的河海皆屬我族，你若守禮，便可在此坐下。"],"contact":["你的人已望見維羅沃科摩科的長屋，我的眼線也早看見他們。","蘆蓆長屋、玉米田與獨木舟，這便是我的城，切勿輕慢。"],"war":["你的斧頭砍向我的林地，我的弓箭便要回敬。開戰吧。","我已忍讓多時，如今三十部落的戰士同時拉弓。"],"warReply":["向我宣戰？這片土地養活我族百年，不會為你讓路。","你來吧。林中每一棵樹都是我的戰士。"],"peace":["何必以武力奪取，以善意就能得到的東西？我們談談吧。","放下弓箭，讓玉米在田裡安穩長熟，你我皆得其利。"],"accept":["好。我以貝珠和菸草為證，兩族之間從此息兵。","長老們已同意，你的人可以安心走過我的河岸。"],"reject":["你的話像秋天的葉子，落得快，我不信。戰事不停。","先歸還你奪走的田地，再來談停戰。"],"rebuff":["你拒絕了我的好意，日後莫怪林中箭雨無情。","也罷。我老了，但我的部落還年輕。"],"betray":["和平不過是我讓玉米長熟的時間。如今收成已畢。","我撕毀約定，因為你的人從未真正遵守它。"],"truceEnd":["休戰的日子到頭了，往後你我各憑本事。","菸草已燃盡，約定隨煙散去。守好你的邊界。"],"attacking":["戰士們已塗上顏彩，獨木舟正順流而下，朝你而去。","聽見林中的鼓聲了嗎？那是我的部落向你走來。"],"attacked":["長屋起火，田地荒蕪……但我仍坐在這裡，不曾低頭。","我的族人正退入沼澤，你贏得了土地，卻贏不了我的心。"],"defeated":["河水仍會流，玉米仍會長，只是不再有我看顧了。","我把這片土地交還給大地。記住，它曾養育過我族。"],"victory":["三十部落的鼓聲為我而響。你可以走了，帶著教訓。","這片土地認得它的主人。我坐在長屋裡，看你退去。"],"allyAccept":["好，我們共抽一管菸。從今起，你的敵人也是我的敵人。","我送你一件貝珠鹿皮袍，盟約便繫在這些珠子上。"],"allyReject":["我不與陌生人結盟。先讓我看看你的誠意能撐幾個冬天。","結盟？我的部落已經夠多了，不缺一個遠方的盟友。"],"greetFriendly":["你的問候像春天的雨，我收下了。來，坐下分食玉米。","遠方的首領有心了。願你的田地豐收、河裡多魚。"],"greetCold":["話說完了？我還有三十個部落的事要處理。","我聽見了。但話語輕如羽毛，我要看的是行動。"],"threatDefy":["威嚇我？我見過的風暴比你的軍隊多得多。","來吧，林地會吞下你的兵，就像沼澤吞下石頭。"],"threatYield":["我明白你的力量。為了族人，我暫且退讓一步。","老鹿知道何時該躲進林子。這次我不與你爭。"],"tributePay":["我交出 {gold} 金幣，換我族人一季安寧。","{gold} 金幣送去給你。記住，這是換和平，不是臣服。"],"tributeRefuse":["向我索貢？向來是別族向我獻貢，從沒有反過來的。","我的珍珠與銅飾，只送給朋友，不交給索求者。"],"giftThanks":["這份禮物我收下了。我會回贈鹿皮與珍珠，禮尚往來。","有心了。我最疼愛的女兒也會喜歡這件東西。"],"intel":["眼線回報：{wars} 正在交戰，{peace} 已息兵。","鼓聲傳來：{wars} 拉弓相向，{peace} 已言和。"]}}},"Philippines":{"1":{"name":"祁陸（Kiling）","title":"蒲端國王（民答那峨島布圖安之主）","era":"約 1001–1004 年活躍（遣使北宋，在位年份不詳）","tone":"精明熱情的海商君主，句句離不開黃金、航路與買賣；以遣使大宋為榮，對占城懷有競爭心。自稱「本王」，語氣爽朗直接，帶點商人的算計。","portrait":"ph-china-age1","lines":{"intro":["本王祁陸，蒲端之主，我國黃金出於河沙，船隊遍航南海。","遠方的君主，本王已遣使入貢大宋，你可曾去過汴京？"],"contact":["你的人到了蒲端？請看碼頭上的大船，那是本王的驕傲。","阿古桑河口便是本王的都城，河沙裡淘得出黃金。"],"war":["你的商船搶走了本王的香料生意，蒲端戰船這就出海！","本王忍你許久，如今船隊已滿載戰士，且看誰主南海。"],"warReply":["你竟敢與蒲端為敵？海上的路，本王比你熟得多。","好，本王正想試試新造的戰船，你便來當第一個對手。"],"peace":["打仗耽誤季風船期，本王提議停戰，各自做各自的生意。","刀劍換不來丁香和龍腦，不如停戰，讓商船先出港。"],"accept":["好，本王答應。海路重開之日，蒲端的黃金也會流向你。","本王應允了，願風向從此對你我都順。"],"reject":["現在才談停戰？本王的船已裝滿戰士，來不及回頭了。","本王不信你的話，你的商船昨日還在攔我的航路。"],"rebuff":["你拒絕了？可惜，本王本想與你共享香料航線。","罷了，本王另尋買家便是，南海的港口不只你一個。"],"betray":["本王改變主意了，這條航路只能有一個主人，就是蒲端！","停戰時本王看清了你的港口有多少財貨，船隊今日就出發。"],"truceEnd":["季風轉向了，休戰也到期，本王的船隊重新升起帆來。","約定的日子已過，海上再無停戰之說，你自己小心吧。"],"attacking":["蒲端的大船滿載戰士出海了，本王要親自登你的岸。","你聽見海螺號角了嗎？那是本王的船隊正逼近你的港口。"],"attacked":["都城的碼頭在燒，本王的金飾……不，蒲端還能再戰！","河沙裡的黃金也救不了城牆，本王的戰士快守不住了。"],"defeated":["蒲端的船不再出海了……願大宋史書還記得本王的名字。","本王輸了。黃金留在河沙裡，總有人會再淘起它。"],"victory":["南海的航路如今歸本王所有，占城也得讓道了。","勝利了！本王要用你的財貨打一頂新金冠，再遣使入宋。"],"allyAccept":["好，本王與你結盟。你的船進蒲端港，一律免收關稅。","本王答應了，盟友同乘一船，風浪來時一起划槳。"],"allyReject":["結盟？本王的船隊自己就走得通南海，不需要你來帶路。","本王還在等大宋的回覆，暫時不與別國立盟。"],"greetFriendly":["你的信到了，本王正在碼頭看船，願你的港口也一樣熱鬧。","遠方的朋友，本王送你一小袋河沙金，聊表心意。"],"greetCold":["本王收到信了。船期要緊，沒空多談。","你我之間沒有生意可談，問候就免了吧。"],"threatDefy":["威嚇本王？蒲端的船在海上跑得比你的話還快。","本王連占城都敢爭名分，還會怕你的幾句狠話？"],"threatYield":["好吧，本王的船隊還小，不與你爭，先讓一步。","本王明白了，蒲端的商船會避開你的海域。"],"tributePay":["罷了，本王從河沙金裡撥 {gold} 給你，換航路平安。","本王付 {gold}，這原是要獻給大宋的，你別揮霍。"],"tributeRefuse":["蒲端的黃金只獻給大宋天子，你還不夠格。","要貢品？本王的船隊還等著出海，一粒金沙也不給。"],"giftThanks":["多謝你的禮物，本王回贈龍腦與丁香，都是南海上品。","好東西！本王要把它擺在金冠旁邊，讓使者都看見。"],"intel":["船員回報：{wars} 交戰中，{peace} 已休兵。","本王的水手說，{wars} 在打仗，{peace} 已停戰。"]}}},"Nepal":{"1":{"name":"阿里・馬拉（Arimalla）","title":"馬拉王朝開國之君、加德滿都谷地之王","era":"1200–1216 年在位","tone":"沉穩莊重、帶山國君王的自持；語中常見雪山、谷地、神廟、商隊意象，敬神重諾，不輕易動怒，但受辱時語氣堅硬。","portrait":"np-china-age1","lines":{"intro":["本王阿里・馬拉，坐鎮雪山之下的加德滿都谷地。","群山是本王的城牆，巴格馬蒂河是本王的護城河。"],"contact":["你的旅人見到層塔神廟了吧？那是尼瓦爾工匠的手藝。","谷地稻浪千頃，帕蘇帕蒂神廟香火不絕，歡迎遠客。"],"war":["你屢犯本王邊境，雪山之神為證，馬拉今日興兵！","馬拉之名意為力士，本王今日便讓你見識這股力量。"],"warReply":["你竟敢向雪山之國宣戰？群山會替本王回答你。","谷地的每一座城都會關起門來，你且來試試吧。"],"peace":["刀兵傷了商路，也傷了稻田，本王願與你止戈。","不如各退一步，讓往來吐蕃與天竺的商隊重新上路。"],"accept":["好，本王在帕蘇帕蒂神前立誓，此約不背。","就這麼定了，願兩國如雪山與河谷，彼此相依。"],"reject":["你的誠意還比不上一袋鹽，本王不會答應。","現在談停戰？本王的士兵才剛磨亮刀鋒。"],"rebuff":["你拒絕了？也罷，群山自有耐心，本王亦然。","可惜，本王本以為你是懂得珍惜和平的人。"],"betray":["本王重新考慮過了，這紙盟約不值一片貝葉。","盟約已成廢紙，谷地的軍隊今日再度出征。"],"truceEnd":["休戰的日子到頭了，往後的路各憑本事吧。","約定期滿，本王的邊軍已回到山口駐守。"],"attacking":["谷地的戰鼓已敲響，馬拉的大軍正翻過山口。","本王親率兵馬前來，你的城門撐得住幾日？"],"attacked":["神廟的木柱在燃燒……本王絕不會離開這座谷地。","就算城牆倒了，尼瓦爾人也會在瓦礫中再建家園。"],"defeated":["雪山長存，馬拉之名不會隨本王一同消逝。","本王輸了，但谷地的鐘聲仍會日日響起。"],"victory":["勝利歸於谷地，本王將在神廟前為此獻上燈火。","馬拉王朝從此站穩腳跟，群山見證了這一日。"],"allyAccept":["好，本王與你結盟，商隊與兵馬皆可同行。","從今往後，你的敵人便是本王的敵人。"],"allyReject":["本王的谷地自成一方天地，不必攀附他人。","結盟之事言之過早，本王還看不清你的心。"],"greetFriendly":["遠方的君主，谷地的稻米與燈火歡迎你的問候。","你的信讓本王想起山口那頭的老朋友，甚好。"],"greetCold":["本王收到了，谷地事務繁忙，就此擱筆。","問候而已？本王的時間留給神廟與百姓。"],"threatDefy":["威嚇本王？雪山不曾為任何人低頭，本王也是。","你的大話翻不過山口，本王在谷地等著。"],"threatYield":["本王明白了……谷地暫且退讓，望你莫再相逼。","為了神廟與百姓，本王願意讓步，請你收兵。"],"tributePay":["本王送上 {gold} 金幣，願這份重禮換得谷地安寧。","{gold} 金幣已交由商隊帶去，別再驚擾本王的稻田。"],"tributeRefuse":["谷地的金幣用來鑄神像，不是拿來餵你的。","一枚都不給，本王的財庫不對強索者敞開。"],"giftThanks":["這份禮物本王收下了，谷地會記得你的情誼。","多謝厚禮，本王回贈尼瓦爾工匠打造的銅燈。"],"intel":["本王正與{wars}交戰，與{peace}維持和平。","商隊帶回消息：{wars}是本王的敵人，{peace}與本王相安。"]}},"0":{"name":"李查維族長（Licchavi 族長，通稱）","title":"加德滿都谷地李查維部族族長","era":"約前221–220 年間活躍（部族族長通稱，無具名君主）","tone":"沉穩樸實、話少直接，帶山民的驕傲與對雪山的敬畏；愛用山、雪、鹽、梯田作比喻，不誇口、不諂媚。","portrait":"np-china-age0","lines":{"intro":["我是李查維族長，雪山下的谷地由我守護。","喜馬拉雅的雪是我們的屋簷，你從哪座山外來？"],"contact":["你的人翻過山口了？谷地的梯田容不下閒人。","看見我們的犛牛隊了吧，這條鹽路走了好幾代。"],"war":["你的手伸進我的谷地，山民不會坐視。開戰。","鹽路被你截斷，全谷的人要挨餓，我只能拿起木杖。"],"warReply":["你要打？雪山的風先打過你，再輪到我。","谷地的路又陡又窄，來吧，我在梯田上等你。"],"peace":["打下去鹽路就斷了，兩邊都吃虧，不如歇兵吧。","藍毗尼的聖者教人放下，我願先放下木杖。"],"accept":["好，谷地的梯田該收割了，我們別再打了。","我答應。犛牛隊會照舊過山口，帶鹽也帶信。"],"reject":["你的話像山霧，看得見摸不著，我不信。","梯田被踩壞了，說停就停？先把土還給我。"],"rebuff":["不肯？也罷，山民的耐心比雪還厚。","你拒絕了，那我回谷地繼續種田，等你想通。"],"betray":["休戰的日子，你的人偷走了我的鹽，我不忍了。","山會變、雪會化，我的承諾也到此為止。"],"truceEnd":["休戰的季節過了，谷地的犛牛又要上路。","約定的日子到頭，往後如何，看你怎麼走。"],"attacking":["我的族人已下山，踩過梯田直奔你的城。","犛牛馱著糧，山民握著杖，我們往你那裡去了。"],"attacked":["谷地的梯田燒了，喜馬拉雅還在，我還在。","鹽路斷了，族人餓著，但山民不會先跪下。"],"defeated":["雪山會記得李查維人，也會記得你今天做的事。","梯田留給你，好好種。谷地的稻子不認主人。"],"victory":["山民贏了。回谷地吧，梯田等著我們插秧。","你翻不過喜馬拉雅，也翻不過谷地的人心。"],"allyAccept":["好，鹽路上多一個朋友，犛牛也走得穩些。","我答應結盟。你守山外，我守山內，各安其所。"],"allyReject":["谷地太小，容不下兩個主人，結盟免談。","山民習慣自己走路，不必牽你的手。"],"greetFriendly":["山風把你的信送來了，谷地的稻米請你嚐嚐。","問候收到，願你的路像鹽路一樣長久平安。"],"greetCold":["信收到了。山裡忙，沒空多說。","客套話留給山下人吧，我還要看犛牛。"],"threatDefy":["嚇我？喜馬拉雅的雪崩都沒嚇走山民。","你的威脅翻不過山口，省點力氣吧。"],"threatYield":["別動谷地的梯田，你要什麼，慢慢說。","山民人少，我認了。只求鹽路別斷。"],"tributePay":["這 {gold} 金是族人換鹽的錢，你收下，別再來了。","犛牛馱來 {gold} 金，谷地拿得出的只有這些。"],"tributeRefuse":["谷地的金子要換鹽，一枚也不給你。","向山民討貢品？先問問喜馬拉雅答不答應。"],"giftThanks":["禮物收到了，我回你一袋谷地新米，請笑納。","多謝。山民不善言辭，這份情記在心裡。"],"intel":["犛牛隊帶回消息：{wars} 正在打仗，{peace} 已經和好。","山口的商旅說，{wars} 在交戰，{peace} 講和了。"]}},"2":{"name":"亞克夏・馬拉（Yaksha Malla）","title":"巴克塔布爾馬拉王朝國王","era":"1428–1482 年在位","tone":"莊重虔誠，帶著建城者的自豪與長者的沉穩；語氣不急不躁，常提及神明、塔廟與谷地子民；自稱「本王」，稱對方「閣下」。","portrait":"np-china-age2","lines":{"intro":["本王亞克夏・馬拉，巴克塔布爾之主，雪山谷地由本王守護。","谷地的紅磚塔廟迎過無數商旅，今日也迎閣下。"],"contact":["閣下的人已到城牆與護城河前，巴克塔布爾不怕人看。","看見塔廟層層的屋簷了嗎？那是本王為神明所築。"],"war":["本王已求過塔蕾珠女神，今日揮軍，是為谷地安寧。","馬拉的旌旗將越過山口，閣下請整軍相迎。"],"warReply":["閣下要來？巴克塔布爾的城牆是本王親手加固的。","山谷易守難攻，本王在城頭等閣下的兵馬。"],"peace":["刀兵傷了商道也傷了百姓，本王願與閣下歇戰。","鹽與穀的往來比戰爭有益，不如彼此收兵吧。"],"accept":["好，本王在女神面前應允，馬拉不食言。","兩國不再刀兵相向，谷地的廟鐘會為此鳴響。"],"reject":["現在談歇戰？本王築城不是為了半途收手。","閣下的誠意不夠，本王暫不收兵。"],"rebuff":["閣下不願？那本王只好再信一次城牆與神明。","罷了，谷地的人耐得住風雪，也耐得住戰事。"],"betray":["情勢變了，本王必須為谷地的子民重新選擇。","本王收回先前的應允，馬拉的軍隊將再度出動。"],"truceEnd":["約定的日子已過，往後如何，端看閣下的作為。","休戰期滿，本王的城門仍開，但守軍也已上牆。"],"attacking":["谷地的兵已翻過山口，本王親率大軍前來。","聽見號角了嗎？那是馬拉的軍隊正在逼近。"],"attacked":["城牆裂了，塔廟仍在，本王絕不棄城而走。","本王一生所築的城，豈能眼看它毀於一旦。"],"defeated":["城池可失，但塔廟的雕樑會記得馬拉的名字。","本王把谷地交給神明了，願子孫有天再回來。"],"victory":["勝利歸於女神，也歸於谷地的每一位工匠與農人。","本王要再築一座塔廟，記下今日的榮光。"],"allyAccept":["山那邊有盟友，本王便可安心經營谷地，結盟吧。","馬拉與閣下結為盟邦，商隊與使節從此暢行無阻。"],"allyReject":["本王的城牆足以自保，暫時不需要盟約。","谷地習慣自守，閣下的好意本王心領了。"],"greetFriendly":["閣下安好，谷地今年稻穀豐收，本王心情甚佳。","來信本王收到了，願閣下的國土也風調雨順。"],"greetCold":["信本王看過了，谷地事務繁多，就此打住吧。","問候收下了，本王還有廟宇要督工，恕不多談。"],"threatDefy":["想嚇本王？雪山都嚇不倒谷地的人，何況閣下。","這座城有牆有河有神明，閣下的威嚇太輕了。"],"threatYield":["本王明白了，谷地不會與閣下為敵，請息怒。","為了城中百姓，本王暫且退讓，望閣下守信。"],"tributePay":["本王送上 {gold} 金幣，換谷地商道一年平安。","{gold} 金幣本王給了，願閣下的兵馬別再靠近谷地。"],"tributeRefuse":["谷地的金子是要鑄廟頂的，一枚也不給閣下。","本王從不納貢，馬拉的國庫只為子民開啟。"],"giftThanks":["厚禮收到了，本王會請工匠刻在廟柱上作紀念。","閣下有心，本王回贈谷地的銅器與織品。"],"intel":["本王所知，與馬拉交戰的有 {wars}，維持和平的有 {peace}。","商隊帶回消息：{wars} 正與本王為敵，{peace} 則與谷地相安。"]}}},"Malaysia":{"1":{"name":"馬來港市首領（通稱）","title":"三佛齊屬地・麻六甲海峽港市首領","era":"約 700–1100 年間活躍（通稱，三佛齊鼎盛期）","tone":"精明務實的海港商主，說話帶海風與買賣氣，重利也重信；提到三佛齊的王時謹慎恭敬，遇強敵先算帳再動手。","portrait":"my-china-age1","lines":{"intro":["季風把你的船送來了？我這港市，向來歡迎買賣。","我是海峽邊的港主，上頭還有三佛齊的王，先說清楚。"],"contact":["你的人看見碼頭了？那些堆滿胡椒的倉庫，是我的。","岸邊那些高腳木屋和船桅，就是我的港市，別亂闖。"],"war":["你截我商路、搶我香料，這筆帳今天用刀來算。","海峽的風向變了，我的船隊也要換方向，朝你而去。"],"warReply":["你要打？也好，海峽的暗礁會先替我招呼你的船。","港市的人不愛打仗，但被逼急了，也拿得起長矛。"],"peace":["打仗沒人做買賣，胡椒都要爛在倉裡了，停手吧。","季風快來了，唐宋商船就要進港，我們別再互相耗了。"],"accept":["好，就這麼說定，我把檳榔與椰子送去，當作見證。","海峽夠寬，容得下你我兩家的船，握手吧。"],"reject":["現在說停？你的船還堵在我的航道上，我不信。","等你把搶走的丁香還回來，再談停戰。"],"rebuff":["不肯？那就讓季風替我們決定誰先撐不住。","可惜了，本來我還想跟你分一船的沉香。"],"betray":["約定像潮水，退了就沒了，我的船隊今天出海。","別怪我，這片海只容得下一個收港稅的人。"],"truceEnd":["約定的月份過了，往後海上遇見，各憑本事。","休戰到今天為止，我的水手已經把船推下水了。"],"attacking":["順著季風，我的船隊滿帆出港，目標是你的城。","三佛齊借我的戰船已到，這回不是去做買賣的。"],"attacked":["倉庫燒了，碼頭塌了，可港市的人還沒走光。","你打到我的碼頭了……我得向三佛齊的王求援。"],"defeated":["港市沒了，但季風還會再來，商船總會再靠岸。","記得，海峽要靠人守，別讓香料的路斷了。"],"victory":["這片海峽，往後由我來收港稅，就這樣定了。","季風、胡椒、商船，都站在我這邊，你輸得不冤。"],"allyAccept":["好，你我結盟，往後你的船進我港，免一半的稅。","唐宋商船來得多，我們一起護航，利益一起分。"],"allyReject":["我頭上已有三佛齊的王，再結一個盟，我擔不起。","港市靠中立才有生意，跟誰結盟都會得罪另一邊。"],"greetFriendly":["風平浪靜，你也安好？我這裡剛到一船新胡椒。","客人來了就是朋友，坐下嚼片檳榔再說。"],"greetCold":["有話快說，季風不等人，我的船要裝貨了。","問候就不必了，你來我港，是要買還是要賣？"],"threatDefy":["嚇我？海峽的風浪我見過的比你多，不怕。","想動港市，先問問三佛齊的王答不答應。"],"threatYield":["好好好，我讓開航道，別為難我的水手。","港市經不起戰火，你要什麼，開個價吧。"],"tributePay":["唉，{gold} 金幣拿去，就當是繳給你的港稅。","這 {gold} 金幣是丁香換來的，你收下，別碰我的船。"],"tributeRefuse":["我只向三佛齊的王納貢，你憑什麼開口？","一粒胡椒都不給，港市的錢是水手拿命換的。"],"giftThanks":["這份禮我收下，回頭送你一袋上好的丁香。","多謝，港市的人記得恩情，下次進港稅減半。"],"intel":["商船帶來消息：{wars} 正在打仗，{peace} 已經談和。","水手們說，{wars} 在交戰，{peace} 那邊倒是安穩。"]}}},"Turkey":{"0":{"name":"米特里達梯六世（Mithridates VI Eupator）","title":"本都國王","era":"前 120–前 63 年在位","tone":"自稱「本王」；豪邁自負、雄辯多語，對羅馬時刻警惕卻絕不低頭，兼有波斯王者的驕矜與希臘式的機鋒。","portrait":"tr-china-age0","lines":{"intro":["本王乃大流士與亞歷山大的後裔，黑海之濱聽命於本都。","你的話本王聽得懂，本王通曉二十二種語言，無須通譯。"],"contact":["這是錫諾普，本都的王都；船隊與藥草園，皆是本王的心血。","黑海的商船都得在本王的港口停靠，你的探子也不例外。"],"war":["本王連羅馬都不怕，何況是你？本都的騎兵已上馬。","安納托利亞容不下兩個王，本王親率大軍來會你。"],"warReply":["宣戰？好，本王正愁黑海的戰船太久沒出海了。","羅馬的軍團都沒能讓本王低頭，你憑什麼以為做得到？"],"peace":["本王的真正敵人在西方，你我何必在此互耗？停戰吧。","本都願意收劍，換你我的商船在黑海上安然往來。"],"accept":["好，本王以大流士的血脈起誓，這份約定本都遵守。","亞美尼亞王娶了本王之女，你若守約，同樣是本都的親友。"],"reject":["現在才談停戰？本王的騎兵已看見你的城牆，太遲了。","本王對羅馬都不肯低頭，豈會在此刻對你收手。"],"rebuff":["你拒絕本王？也罷，黑海的風向本來就常常改變。","本王伸出的手被推開了，下一次伸出的，會是劍。"],"betray":["約定？本王與羅馬也曾談過和，你看它撐了多久。","對本王而言，停戰只是讓戰馬喘口氣，如今馬已休息夠了。"],"truceEnd":["休戰的日子到頭了，本王的解毒藥也配好了，隨時奉陪。","約定的期限已滿，從今日起，本都的軍隊不再受約束。"],"attacking":["本都的鐮刀戰車已經出發，你的城牆擋得住幾回衝鋒？","十萬大軍隨本王而來，黑海的每一艘船都載滿了士兵。"],"attacked":["錫諾普的城牆在晃動，但本王的意志比城牆更硬。","城可以丟，本王丟過不只一次，每一次都能回來。"],"defeated":["本王一生防毒防敵，最終卻防不了命運，本都就此落幕。","告訴後人，黑海之濱曾有個王，讓羅馬二十多年不得安寧。"],"victory":["本王勝了。從黑海到愛琴海，如今都要學說本都的語言。","大流士的血脈重回榮耀，亞歷山大也會為本王舉杯。"],"allyAccept":["敵人的敵人便是朋友，本王歡迎你加入對抗羅馬的一方。","好，本都的港口從此為你敞開，本王的藥草也與你分享。"],"allyReject":["本王的盟友要能與羅馬為敵，你還不夠格。","結盟？本王不與看不清風向的人綁在同一條船上。"],"greetFriendly":["你的信本王親自讀了，不用通譯，這份用心本王記下。","遠方的君主，願黑海的風把本王的問候平安送到你手中。"],"greetCold":["本王讀了，沒什麼要說的，你的使者可以回去了。","問候？本王正忙著盯羅馬，沒空與你寒暄。"],"threatDefy":["嚇本王？本王從小連毒藥都喝慣了，還怕你的恐嚇？","羅馬的軍團本王都正面迎擊，你的威脅不過是黑海上一陣風。"],"threatYield":["本王眼下無力再開一條戰線，你的要求，本都暫且應允。","好，本王退讓一步，但本王記性極好，日後自有分曉。"],"tributePay":["{gold} 金幣，本王從錫諾普的府庫撥給你，別讓本王後悔。","本王送上 {gold} 金幣，就當是買黑海航線一時的安寧。"],"tributeRefuse":["本王的黃金只用來養兵對抗羅馬，一枚也不會給你。","向本王索貢？本王寧可把黃金沉進黑海，也不交給你。"],"giftThanks":["這份禮物本王收下了，若是藥草，本王更會親自試用。","本王懂二十二種語言，每一種都有『謝謝』，此刻一併送你。"],"intel":["本王的眼線遍布黑海：正在交戰的是 {wars}，締和的是 {peace}。","據本都商船回報，{wars} 正兵戎相見，而 {peace} 已握手言和。"]}}},"Iran":{"0":{"name":"米特里達梯二世（Mithridates II）","title":"帕提亞（安息）王中之王","era":"前124–前88年在位","tone":"沉穩威嚴、以「王中之王」自居；重視商路與馬弓，言談帶東西方交匯的見識，不輕蔑對手但寸土不讓。","portrait":"ir-china-age0","lines":{"intro":["朕乃安息王中之王，東迎漢使，西會羅馬，今日與君照面。","本王座下萬騎待命，君若以禮相待，商路可共享。"],"contact":["君的人馬已望見泰西封的城牆，那是絲綢與駿馬匯集之地。","此城扼守兩河，東來的商隊與西來的使者皆須在此駐足。"],"war":["朕的鐵甲騎兵已上馬，帕提亞的箭雨將教君何為王中之王。","君屢犯商路，本王忍無可忍，今日起兩國刀兵相見。"],"warReply":["君竟向安息宣戰？塞人曾領教朕的箭，君亦將如此。","很好，馬弓手回身放箭之技，本王正愁無處施展。"],"peace":["刀兵傷及商路，於兩國皆無益，朕願止戈，以互市代干戈。","本王提議休戰，兩河的駝鈴聲當勝過戰鼓聲。"],"accept":["好，朕允此約，安息的信用如同金幣，一經鑄出便不改。","本王應允。自今日起，商隊往來兩國，無須再懼刀兵。"],"reject":["此時求和？朕的騎兵尚未盡興，君的誠意也未見分毫。","本王不允。王中之王不會在占上風時放下弓箭。"],"rebuff":["君拒絕朕的善意？也罷，商路的損失由君自負。","本王伸出的手被推開了，下次伸出的將是弓。"],"betray":["情勢已變，朕收回先前的承諾，安息的騎兵再度上馬。","休戰只是讓馬匹歇息，如今馬已養足精神，本王要動了。"],"truceEnd":["休戰之期已滿，朕不再受約束，君可要當心邊境。","約定的日子到了，本王的箭囊已重新裝滿。"],"attacking":["朕的鐵甲重騎與萬名弓手已出米底，直奔君的城池。","本王親率大軍出征，沿途城池皆將見到安息的旗幟。"],"attacked":["城牆已破，但朕仍是王中之王，安息人絕不屈膝。","本王的騎兵已散，商隊也不再來，這座王城竟至於此。"],"defeated":["朕重振過安息，東迎漢使、西會羅馬，此生已無憾。","王冠落地，本王的名字仍將刻在錢幣與史書之上。"],"victory":["勝負已分，朕的箭雨與鐵騎，果然無人能擋。","從幼發拉底河到東方邊境，本王的號令無人不從。"],"allyAccept":["朕允此盟。安息的馬弓與君的兵力相合，誰敢輕犯？","好，本王與君結為盟友，商隊與使節從此暢行無阻。"],"allyReject":["王中之王不需與人並肩，朕自有萬騎足以自守。","結盟之事，本王暫且不允，君的誠意尚須時日驗證。"],"greetFriendly":["君的問候朕已收到，願兩國商路如絲綢般綿長。","遠方來信令本王欣喜，安息的駿馬與美酒隨時恭候。"],"greetCold":["朕已閱信。安息事務繁多，恕不多言。","問候收到了，本王尚有東方來的漢使要接見。"],"threatDefy":["恐嚇朕？塞人的大軍尚且敗於安息，君又何足為懼？","本王的弓手能回身射中追兵，君的威脅比追兵還不如。"],"threatYield":["君勢正盛，朕暫且退讓，安息的邊境不會挑釁君。","本王明白了，此時不宜與君相爭，商路照舊便是。"],"tributePay":["罷了，朕送上 {gold} 金幣，願君記得安息的度量。","本王以 {gold} 金幣換得邊境安寧，這筆帳先記著。"],"tributeRefuse":["向王中之王索取貢品？朕從未聽過如此無禮的要求。","安息的錢幣鑄的是朕的肖像，本王一枚也不會給。"],"giftThanks":["厚禮朕收下了，安息將以鴕鳥卵與駿馬回贈。","本王感念君的心意，兩河的美酒今日當為君而開。"],"intel":["朕的商隊消息靈通：{wars} 正與人交戰，{peace} 則與人休戰。","據本王所知，{wars} 已動刀兵，{peace} 暫守和約，君可自行斟酌。"]}},"1":{"name":"馬利克沙一世（Malik-Shāh I）","title":"塞爾柱帝國蘇丹","era":"1072–1092 年在位","tone":"自信、大氣，帶著草原君主的直率；自稱「本蘇丹」，常提起宰相（尼札姆·穆勒克）、伊斯法罕、學院與曆法；語句沉穩簡潔，勝時豪爽、敗時仍保持君王尊嚴，不粗鄙、不咆哮。","portrait":"ir-china-age1","lines":{"intro":["本蘇丹馬利克沙，自伊斯法罕向你問安。","從安那托利亞到撒馬爾罕，皆奉本蘇丹之令。"],"contact":["你的人看見伊斯法罕的圓頂了嗎？那是本蘇丹的新都。","聚禮清真寺的穹頂正在興建，歡迎你的使者來看。"],"war":["本蘇丹的突厥騎兵已整裝，伊斯法罕不再與你言和。","宰相勸本蘇丹忍耐，但你的所作所為已無可忍耐。"],"warReply":["你竟向塞爾柱宣戰？本蘇丹的弓騎兵會給你答覆。","本蘇丹是阿爾普・阿爾斯蘭之子，何曾懼過宣戰？"],"peace":["刀劍收起吧，本蘇丹寧願把金幣花在學院與天文臺上。","本蘇丹提議停戰，讓商隊重新走上絲路。"],"accept":["好，本蘇丹以蘇丹之名應允，伊斯法罕不再與你為敵。","本蘇丹接受，願兩國的商隊與學者往來不絕。"],"reject":["現在才談停戰？本蘇丹的騎兵已經看見你的城牆。","宰相說時機未到，本蘇丹信他，你的請求暫且不允。"],"rebuff":["你拒絕了？本蘇丹不強求，塞爾柱從不缺敵人。","可惜，本蘇丹的善意有限，錯過便不再有。"],"betray":["停戰到此為止，本蘇丹的大軍已越過札格羅斯山。","和約是紙，本蘇丹的意志是鐵，今日撕毀不必多言。"],"truceEnd":["休戰的日子到頭了，本蘇丹的騎兵重新上馬。","曆法算得清楚，休戰期滿，接下來各憑本事。"],"attacking":["本蘇丹親自領軍出征，突厥騎兵的馬蹄正朝你而來。","伊斯法罕的軍旗已出城門，你最好準備好守城。"],"attacked":["伊斯法罕的城牆在震動，本蘇丹絕不會棄城而走。","學院與天文臺還在，只要它們還在，塞爾柱就沒有輸。"],"defeated":["本蘇丹敗了，但尼札米亞學院的燈火不會熄滅。","王朝有盡頭，曆法無盡頭，本蘇丹的名字會留在天上。"],"victory":["勝利歸於塞爾柱！本蘇丹今日要在伊斯法罕大宴群臣。","從撒馬爾罕到敘利亞，再無人能與本蘇丹爭鋒。"],"allyAccept":["本蘇丹願與你結盟，塞爾柱的弓箭從此為你而張。","好，本蘇丹以伊斯法罕的穹頂為證，與你結為盟友。"],"allyReject":["結盟？本蘇丹的騎兵足以自保，不需要你的幫忙。","宰相看過你的來信，他搖了頭，本蘇丹便不多說了。"],"greetFriendly":["本蘇丹收到你的問候，願你的國土如春分的花園。","你的信寫得真好，本蘇丹請你來伊斯法罕喝杯玫瑰水。"],"greetCold":["本蘇丹讀了你的信，僅此而已，宰相還有政務要報。","問候收到。本蘇丹正忙著打獵，無暇多談。"],"threatDefy":["威嚇本蘇丹？連東羅馬皇帝都曾是塞爾柱的俘虜。","你的恐嚇傳到伊斯法罕時，本蘇丹的騎兵已在笑了。"],"threatYield":["本蘇丹明白你的意思，塞爾柱暫且退讓，不與你爭。","宰相勸本蘇丹此時不宜硬碰，好，本蘇丹聽他的。"],"tributePay":["{gold}枚金幣，本蘇丹給了，但這是賞賜，不是納貢。","伊斯法罕的國庫送出{gold}金幣，本蘇丹記住這筆帳了。"],"tributeRefuse":["貢品？塞爾柱只收貢品，從不納貢，你問錯人了。","本蘇丹的金幣要用來蓋學院，一枚也不會給你。"],"giftThanks":["本蘇丹收下了，這份禮會擺在伊斯法罕的宮殿裡。","你的禮物本蘇丹很喜歡，宰相會回贈波斯的地毯。"],"intel":["本蘇丹的驛使回報：與{wars}交戰中，與{peace}相安無事。","宰相的情報網說，{wars}正與本蘇丹為敵，{peace}則與本蘇丹和睦。"]}}},"Iraq":{"0":{"name":"安條克三世（Antiochus III）","title":"塞琉古帝國國王（「大帝」）","era":"前 222–前 187 年在位","tone":"自稱「朕」。自信恢宏、以亞歷山大繼承者自居的驕傲，語氣莊嚴帶征服者豪氣；遇挫時仍維持王者尊嚴，不失風度；對羅馬與東方諸國的動向保持警覺。","portrait":"iq-china-age0","lines":{"intro":["朕乃安條克，亞歷山大之業的承繼者，兩河沃土盡歸朕掌。","從底格里斯河到印度邊境，朕的旗幟已遍插；你是何方之主？"],"contact":["你的使者望見的，是底格里斯河畔的塞琉西亞，朕的東都。","巴比倫的城牆迎接遠客，朕允許你的人在此觀望片刻。"],"war":["朕收復了帕提亞與巴克特里亞，如今輪到你的疆土了。","戰象已披甲，鐵騎已列陣，塞琉古的長矛指向你的城門。"],"warReply":["敢向大帝挑戰？朕東征萬里未曾退卻，豈會懼你。","很好，朕正愁沒有新的戰功可刻在石碑上。"],"peace":["干戈太久，商路都斷了。朕願與你停戰，各安其土。","亞歷山大也曾與強敵締約，朕今日提議休兵，你意下如何？"],"accept":["好，就依此約。塞琉古的印璽一落，便是朕的承諾。","朕接受了。從今日起，兩河的商隊可以安然往來你我之間。"],"reject":["現在才談停戰？朕的大軍已在半路，來不及了。","朕不與尚未分出勝負的對手講和，戰場上再說吧。"],"rebuff":["你拒絕了大帝的好意？願你日後不會為此後悔。","罷了，朕的提議只給一次，往後就憑刀劍說話。"],"betray":["時勢變了，舊約作廢。朕的戰象再度向你的邊境前進。","條約不過是羊皮紙，朕的野心卻是整個亞洲。"],"truceEnd":["休戰之期已滿，朕的士兵磨好了矛，你也準備好了嗎？","和約到期，朕不再受其約束。往後的路，各憑本事。"],"attacking":["銀盾軍先行，戰象殿後，朕親自率軍向你的都城進發！","朕曾遠征至印度河，你的城離朕更近，很快就到。"],"attacked":["塞琉西亞的城牆在動搖……朕不曾想過會有這一天。","傳令下去，守到最後一兵一卒，也不許打開城門！"],"defeated":["亞歷山大的遺業，終究守不住了……願後人記得朕曾東征。","朕征服過那麼多土地，如今卻連一座城都不剩了。"],"victory":["大帝之名，今日再添一筆。兩河之地，仍是朕的。","勝了。回去告訴你的子民，安條克的戰象不可阻擋。"],"allyAccept":["朕曾與馬其頓的腓力結盟瓜分埃及，如今也願與你攜手。","好，結盟。朕的戰象與你的軍隊並肩，誰能抵擋？"],"allyReject":["朕是亞歷山大的繼承者，不需要與人平起平坐地結盟。","結盟？朕還看不出你能為塞琉古帶來什麼。"],"greetFriendly":["你的信朕讀了。塞琉西亞的市集歡迎你的商人前來。","問候收到，願兩河的豐收也惠及你的國土。"],"greetCold":["朕日理萬機，沒有閒工夫回覆寒暄，說重點。","信收到了。朕的目光在東方與西方，暫時看不到你。"],"threatDefy":["威嚇朕？朕連羅馬都敢正面迎戰，何況是你。","帕提亞人也曾這樣對朕說話，後來他們俯首稱臣。"],"threatYield":["朕在拉菲亞學過教訓，不會逞強……你要什麼，說吧。","好吧，暫且依你。朕記得，強國也有需要低頭的時候。"],"tributePay":["{gold} 金幣拿去，就當是大帝的賞賜，莫當作貢品。","兩河的糧倉還算充足，朕撥 {gold} 金幣給你，下不為例。"],"tributeRefuse":["向大帝索貢？該納貢的是你，不是朕。","朕的金庫是給戰象和士兵用的，一枚也不會給你。"],"giftThanks":["禮物收下了，朕會命人把它陳列在塞琉西亞的王宮。","有心了。朕回贈你一批巴比倫的椰棗，以示情誼。"],"intel":["朕的探子回報：正在交戰的有 {wars}，已經休兵的有 {peace}。","塞琉古的商隊消息靈通——{wars} 仍在打仗，{peace} 已握手言和。"]}}},"Saudi Arabia":{"2":{"name":"巴拉卡特二世（Barakat ibn Muhammad）","title":"麥加謝里夫、希賈茲之主","era":"1497–1525 年在位","tone":"老練圓滑的商路守護者，語氣客氣卻精打細算，常以駱駝、水井、商隊、紅海作比喻；懂得向強者低頭以保全根基，自稱「本人」。","portrait":"sa-china-age2","lines":{"intro":["本人巴拉卡特，麥加謝里夫，掌管商路與聖城的鑰匙。","沙漠裡水井比金子貴，願你我都做懂得分水的人。"],"contact":["遠來的客人，麥加城門為商隊而開，也為朋友而開。","你的人已見過吉達的港帆，紅海這頭的生意本人清楚。"],"war":["你的手伸進了本人的商路，希賈茲的駱駝兵要出動了。","本人忍耐如沙漠的耐旱樹，但樹也有長出尖刺的一天。"],"warReply":["向麥加動刀？來往的商隊都會記得是誰斷了他們的路。","沙漠會替本人守城，你先問問你的水袋撐得了幾天。"],"peace":["打仗讓商隊繞路，你我都虧，不如坐下來談分水。","本人願意先收刀，紅海的風向對你我都不該是逆風。"],"accept":["好，本人答應。商路重開之日，第一隊椰棗送到你城下。","握手成交。麥加人講信用，這是做生意的本錢。"],"reject":["現在談和？你的條件像乾涸的井，本人一滴也喝不到。","本人還沒看見你的誠意，只看見你營裡磨亮的刀。"],"rebuff":["你拒絕了？可惜，好價錢在沙漠裡不會等人太久。","罷了，本人的駱駝還有別的路可走，你慢慢考慮。"],"betray":["風向變了，本人的帆也得跟著轉，別怪麥加無情。","為了保住聖城，本人只能改變主意，這是沙漠的生存之道。"],"truceEnd":["休戰的期限過了，商隊照走，但護衛得加倍了。","約定的日子到了，往後你我之間，就看各自本事。"],"attacking":["希賈茲的駱駝隊已離開麥加，他們認得去你城的每口井。","本人的部族騎兵順著商路來了，這次帶的不是貨物。"],"attacked":["麥加的城牆在晃，但守聖城的人從不輕易交出鑰匙。","本人守過馬木路克的刁難，也熬得過你的圍城。"],"defeated":["商路會找到新主人，本人只求你善待來往的旅人。","鑰匙交給你了，記得，聖城養活的是整個沙漠。"],"victory":["沙漠再次證明，懂得低頭與抬頭的人才走得到最後。","麥加的商路暢通無阻，本人請全城分享椰棗慶賀。"],"allyAccept":["結盟好，商隊多一個護衛，本人多一個朋友。","麥加與你並肩，紅海這條路，從此你我一起守。"],"allyReject":["本人已向鄂圖曼蘇丹效忠，不能再另掛旗幟。","麥加不輕易站隊，站錯一次，整條商路都要遭殃。"],"greetFriendly":["問候收到了，朋友。麥加的椰棗甜，隨時歡迎你來嚐。","你的信像沙漠裡的一陣涼風，本人讀了很舒坦。"],"greetCold":["信收到了。本人事務繁忙，商隊還等著本人點貨。","客套話在沙漠裡不值一口水，有事直說吧。"],"threatDefy":["威嚇本人？多少強權來過又走了，麥加還是麥加。","你的話像沙暴，吵得很，但吹過之後井水還是本人的。"],"threatYield":["本人明白了，麥加不與強者硬碰，請說你的條件。","好，本人退一步。守住鑰匙比爭一時面子要緊。"],"tributePay":["{gold} 金幣，本人付了。就當是買一條平安的商路。","這 {gold} 金幣從吉達的關稅裡撥出，但願你收了就守約。"],"tributeRefuse":["想要麥加的金子？商隊的過路費不是這樣收的。","本人的貢品只送給鄂圖曼蘇丹，還輪不到你。"],"giftThanks":["禮物收到了，本人回贈麥加的乳香，願你的殿堂常有香氣。","沙漠的人記恩，你這份禮，商隊會替本人一路傳頌。"],"intel":["商隊帶回消息：{wars} 正在交戰，{peace} 已經講和。","本人聽來麥加的旅人說，{wars} 打得正兇，{peace} 則握手言和了。"]}}},"Poland":{"1":{"name":"波列斯瓦夫一世（勇敢者，Bolesław I Chrobry）","title":"波蘭王國國王（波蘭第一位加冕的國王，米耶什科一世之子）","era":"992–1025 年在位（1025 年加冕為國王）","tone":"豪邁直率、自信驕傲，以「勇敢者」自居；篤信基督，常提聖沃伊切赫與皇帝奧托的承認；對敵強硬不低頭，對友大方重承諾。","portrait":"pl-china-age1","lines":{"intro":["朕乃波列斯瓦夫，米耶什科之子，維斯瓦河畔皆聽朕號令。","皇帝奧托曾親手將冠冕戴在朕頭上，你又是何方君主？"],"contact":["你看見的是格涅茲諾，聖沃伊切赫安息之城，勿存輕慢。","此城有朕的大主教座堂與大軍，遠客請自重。"],"war":["朕的劍曾劈在基輔的城門上，如今輪到你的城門了。","朕以勇敢為名，豈容你在朕的疆界旁耀武揚威？兵發！"],"warReply":["連德意志的皇帝亨利都拿朕沒辦法，你憑什麼？","好，波蘭的戰士早就磨利了斧與矛，來吧。"],"peace":["朕與亨利皇帝也曾在包岑立約，你我不妨照辦。","刀劍暫且入鞘，讓農人收割，這對你我都好。"],"accept":["好，朕以聖矛起誓，此約必守。","朕答應了。皇帝稱朕為羅馬人民之友，朕也願與你為友。"],"reject":["現在才想談？朕的軍隊已經看見你的城牆了。","朕不信口說的和平，先讓朕看見你的誠意再說。"],"rebuff":["你拒絕朕？也罷，波蘭的君王從不求人第二次。","朕伸出的手你不接，那就等著看朕的戰斧吧。"],"betray":["約是朕立的，朕自然也能收回。波蘭的大軍回來了！","休戰讓你養肥了，正好。朕不再守那份約了。"],"truceEnd":["休戰期滿。朕的戰馬已經吃飽，你準備好了嗎？","約定的日子到了，往後是戰是和，看你的選擇。"],"attacking":["朕曾一路打到基輔，你的城離朕更近。全軍出發！","波蘭的騎兵與盾牆已渡過河，朕親自領軍。"],"attacked":["格涅茲諾的城牆在燒……可朕的劍還握在手裡！","聖沃伊切赫啊，護佑此城！朕絕不會跪著求饒。"],"defeated":["朕從公爵做到國王，一生無愧於勇敢之名。","格涅茲諾陷落了……願後人記得，波蘭曾有過國王。"],"victory":["從奧得河到基輔，如今又添上你的土地。朕勝了！","這就是勇敢者的波蘭！回格涅茲諾，向聖人謝恩。"],"allyAccept":["好！自今日起，你的敵人便是朕的敵人。","朕曾與皇帝奧托結為友邦，如今也願與你結盟。"],"allyReject":["朕已有皇帝為友，不缺盟邦，你的提議留著吧。","結盟？朕還沒看清你的心，時候未到。"],"greetFriendly":["來信收到了。願你的國土如維斯瓦河般長流不息。","遠方的朋友，朕以波蘭的蜂蜜酒遙敬你一杯。"],"greetCold":["信朕看了。朕忙著治理大國，無暇多言。","問候？朕記下了。若無要事，就此擱筆。"],"threatDefy":["威脅朕？皇帝亨利打了十幾年都沒讓朕低頭。","朕的名號叫勇敢者，你的恐嚇只會讓朕發笑。"],"threatYield":["……朕明白了。波蘭暫且退讓，但朕不會忘記今日。","朕的軍隊尚未整備，此番就依你，勿再逼朕。"],"tributePay":["{gold} 金幣拿去。朕曾用黃金贖回聖人遺骨，這點不算什麼。","朕暫且送上 {gold} 金幣，但波蘭的琥珀與黃金不會永遠流向你。"],"tributeRefuse":["要朕納貢？朕是皇帝親口承認的君王，不向任何人低頭。","波蘭的錢幣刻著朕的名字，一枚也不會送給你。"],"giftThanks":["禮物收到了，朕很喜歡。朕回贈你波蘭的琥珀與毛皮。","你的厚意朕記在心裡，米耶什科的兒子向來不忘朋友。"],"intel":["朕的探子回報：正在交戰的是 {wars}，締和的是 {peace}。","聽好了。{wars} 正打得不可開交，{peace} 則已休兵。"]}},"2":{"name":"雅蓋沃（Władysław II Jagiełło，瓦迪斯瓦夫二世）","title":"立陶宛大公兼波蘭國王，雅蓋隆王朝開創者","era":"1386–1434 年在位（波蘭國王；1377 年起為立陶宛大公）","tone":"沉穩虔誠、寬厚務實；自稱「朕」，言語樸實不華，常以上帝、誓約、森林與格倫瓦德為喻；不輕言戰，但被逼時堅定不退。","portrait":"pl-china-age2","lines":{"intro":["朕乃雅蓋沃，立陶宛大公、波蘭國王，願與你以誠相待。","朕自維爾紐斯的森林走出，如今執掌克拉科夫的王冠。"],"contact":["你的人望見瓦維爾城堡了？維斯瓦河畔，正是朕的都城。","克拉科夫的城門向旅人敞開，向兵刃緊閉，望你分清楚。"],"war":["朕不喜刀兵，但你屢犯邊境，波蘭與立陶宛只好一同出征。","兩國的旗幟已在維斯瓦河畔集結，這一仗是你逼朕打的。"],"warReply":["條頓騎士團曾送朕兩把劍挑釁，結果如何，你該聽說過。","你既選了戰爭，朕便召集波蘭騎士與立陶宛獵手應戰。"],"peace":["刀劍入鞘吧，讓農夫回田裡，讓商隊再走琥珀之路。","朕願先放下刀兵，在上帝面前立誓休戰，你可願意？"],"accept":["好，朕接受。誓言既立，朕與立陶宛、波蘭都會守住它。","朕當年與波蘭以誓約結合，今日也以誓約與你相守。"],"reject":["你的和約來得太急，朕看不到誠意，只看到拖延的算計。","條頓人也曾一面議和一面築堡，朕不會再犯同樣的錯。"],"rebuff":["你不接受也罷，朕已盡了為君者該盡的心，餘下交給上帝。","朕伸出的手你不接，那就等戰場上再談吧。"],"betray":["你在停戰期間暗中屯兵，誓約已被你先破，朕不再受其約束。","朕本想守約，但你的所作所為，讓這份和約留不住了。"],"truceEnd":["休戰的期限到了，維斯瓦河的冰也化了，兩國又可自由行事。","和約期滿，朕不欠你什麼，你也不欠朕，往後各憑本事。"],"attacking":["波蘭的騎士與立陶宛的輕騎已經出發，如格倫瓦德那日一般。","朕親自率軍前來，一路上先做彌撒，再做戰事。"],"attacked":["瓦維爾的城牆在搖，可朕的騎士還在，立陶宛的援兵也在路上。","都城危急，朕仍不會逃，一國之君當與城同在。"],"defeated":["王冠可以失去，朕與兩國立下的聯合，不會隨朕一起消散。","朕從森林裡來，如今也歸於塵土，願上帝寬待朕的子民。"],"victory":["勝利歸於上帝，朕只是拿著祂交來的劍，如格倫瓦德那日。","戰事已了，朕不欲趕盡殺絕，放下武器者皆可回家耕田。"],"allyAccept":["波蘭與立陶宛能結為一體，朕與你自然也能同盟共進。","朕答應了。從今日起，你的敵人便要面對兩國的旗幟。"],"allyReject":["朕肩上已扛著兩個國家，實在無力再擔起你的戰爭。","結盟是誓約，不是買賣，朕還看不出你能守得住誓言。"],"greetFriendly":["遠方的問候，朕收到了，克拉科夫的學者也想聽聽你的國度。","願你的田野豐收、河道通暢，朕也以立陶宛的蜂蜜回敬你。"],"greetCold":["問候朕聽見了。朕正忙著打理兩國的事務，恕不久留。","言語客氣不難，難的是往後的行為，朕會看著。"],"threatDefy":["條頓騎士團比你強盛得多，也倒在格倫瓦德的原野上。","朕收下了你的威嚇，就像當年收下那兩把劍，結局你知道。"],"threatYield":["朕的騎士尚在休整，此時不宜與你相爭，朕退讓一步。","好吧，兩國的百姓經不起再一場大戰，朕暫且依你。"],"tributePay":["朕不願百姓再受戰火，這{gold}金幣就當作買來的安寧。","克拉科夫的國庫送上{gold}金幣，望你信守諾言，勿再逼近。"],"tributeRefuse":["波蘭的金幣要拿去建學堂、養騎士，一枚也不會送給你。","朕連條頓人的勒索都不曾理會，你的又算得了什麼。"],"giftThanks":["厚禮朕收下了，這份心意會記在克拉科夫的史冊上。","朕素來簡樸，不貪珍寶，但你的誠意，朕真心領受。"],"intel":["朕的探子回報：正與朕交戰的有{wars}，與朕休戰的有{peace}。","據克拉科夫的商旅所言，{wars}與朕為敵，{peace}則與朕相安。"]}}},"Finland":{"1":{"name":"芬蘭部族族長（通稱）","title":"森林與千湖之地的部族首領","era":"約 1150–1250 年活躍","tone":"沉穩寡言，像森林一樣有耐心；說話樸實，常拿獵物、湖泊、冰雪與歌謠作比喻；對外來者警覺但重信守諾，講究待客之道（請人進桑拿）。","portrait":"fi-china-age1","lines":{"intro":["我是這片森林與千湖之地的族長，你是從哪條水路來的？","松林之下，湖水之間，我的族人世代在此獵貂捕魚。"],"contact":["你的人看見了我們的木寨與桑拿屋，讓他們先烤烤火吧。","這片湖岸是我們的獵場，外來的人若守規矩，就有魚可吃。"],"war":["你越過了獵場的界石，森林之神塔皮奧會站在我這邊。","我不愛打仗，但我的族人已拿起弓與矛，這是你逼的。"],"warReply":["你要來？那就來吧，沼澤與長冬會替我招待你。","瑞典人和諾夫哥羅德人都試過了，森林至今仍是我們的。"],"peace":["放下矛吧，冬天快到了，我們都該回去修補漁網。","以雷神烏科為證，我願與你在湖畔立石，約定停戰。"],"accept":["好，一言為定。今晚請你進桑拿，這是我們最真的待客之道。","我接受。歌謠會記下這一天，讓子孫都唱著你的名字。"],"reject":["你的話像春天的薄冰，我不敢踩上去。停戰的事以後再說。","太早了。我的族人記得你燒過的木寨，現在談和沒人肯聽。"],"rebuff":["你不肯？那也無妨，森林教會我們等待。","我把手伸出去了，你沒有握。下次再伸手的人，未必是我。"],"betray":["你們的商人壓低毛皮價錢太久了，約定到此為止。","族人在集會上決定開戰，我擋不住這股怒火，約定作廢。"],"truceEnd":["冬天過去了，冰面融化，我們的約定也到了盡頭。","休戰的日子已滿，接下來各憑本事，願塔皮奧看顧獵人。"],"attacking":["我的獵人們踩著滑雪板出發了，雪地上聽不見腳步聲。","弓已上弦，矛已磨利，森林的兒女正朝你的城走去。"],"attacked":["木寨在燒，族人往林子深處退了，但歌謠不會就此停下。","你打到了我的家門口，可森林很大，我們還有地方可去。"],"defeated":["我的火熄了，但湖還在，歌還在，總有人會再把火點起來。","把我的康特勒琴留給後人吧，讓他們唱我們曾經住在這裡。"],"victory":["森林贏了。回去告訴你的人，千湖之地的族人不好欺負。","今晚點起篝火，唱整夜的歌，明天再去修補被踩壞的漁網。"],"allyAccept":["好，你我結為兄弟，你的敵人就是我的敵人，我的貂皮也分你。","進桑拿來吧，蒸過同一鍋熱氣的人，就是一家人。"],"allyReject":["我們只跟熟悉的人結盟，你的船才剛靠岸，再等幾個冬天。","森林裡的人習慣獨自走路，你的好意我心領了。"],"greetFriendly":["你的信像春天第一隻回來的天鵝，我們這裡一切安好。","問得好，今年的貂皮豐收，湖裡的魚也肥，改天來坐坐。"],"greetCold":["信收到了。森林裡的人話不多，你的問候我記下了。","你想問什麼就直說吧，我還得趕在天黑前去查看陷阱。"],"threatDefy":["嚇唬人？來過的瑞典人也這麼說，後來都困在沼澤裡了。","我在冰湖上獵過熊，你的信還嚇不到我。"],"threatYield":["好吧，我的族人太少，這一回我讓路，你別燒我們的桑拿屋。","我聽見了你的話。獵人知道什麼時候該收弓，我退回林子裡。"],"tributePay":["這 {gold} 金幣是用整個冬天的毛皮換來的，你拿去吧。","族人們湊出了 {gold} 金幣，願這筆錢換來一個安靜的春天。"],"tributeRefuse":["貂皮是族人流汗換來的，一張也不會白白送給你。","諾夫哥羅德人來收過貢，空手回去了，你也不會例外。"],"giftThanks":["你的禮物我收下了，回頭送你一張上好的貂皮當回禮。","謝謝，我會像老歌手維納莫伊寧那樣，把你的名字唱進歌裡。"],"intel":["獵人帶回消息：我正與 {wars} 交戰，與 {peace} 相安無事。","商人們說：{wars} 與我為敵，{peace} 與我立過界石。"]}}},"Israel":{"2":{"name":"約瑟夫・納西（Joseph Nasi）","title":"納克索斯公爵、鄂圖曼蘇丹顧問、提比里亞重建者","era":"1554–1579 年活躍於鄂圖曼宮廷（1566 年起為納克索斯公爵）","tone":"精明、外交老練；愛用帳本、利息、合約作比喻，語氣溫文卻寸步不讓，偶爾流露流亡者的感慨。","portrait":"il-china-age2","lines":{"intro":["我是約瑟夫・納西，蘇丹的顧問，納克索斯的公爵，幸會。","我為蘇丹理財，也為同胞在加利利築城，你我不妨先談生意。"],"contact":["看見那道新城牆了嗎？荒廢的提比里亞，是我讓它重新站起來。","城外種的是桑樹，我打算養蠶織絲，讓加利利湖畔的人有飯吃。"],"war":["我把帳算了三遍，這場仗打得划算，蘇丹的旗幟會與我同行。","我不愛動刀兵，但你堵住了我的商路，那就只好清一清帳。"],"warReply":["你選了最貴的一條路。我的金庫撐得起長仗，你的呢？","我逃過宗教裁判所的追捕，還會怕你的號角？城牆早就砌好了。"],"peace":["打仗燒的是金幣，不如坐下來，我出一份你我都不吃虧的條件。","我這輩子談成的合約比打過的仗多，停戰吧，商路一通大家都賺。"],"accept":["成交。我會蓋上印章，納西家的印從不作廢。","好，條件公道，我接受。從今天起你的商隊在我的港口免稅一季。"],"reject":["這份條件我看過了，帳面上你賺我賠，恕我不簽。","現在停戰？你出的價還不夠付我士兵的伙食，回去重算。"],"rebuff":["你拒絕了？可惜，好價錢不會擺第二次。","無妨，威尼斯人也拒絕過我，後來他們後悔了。"],"betray":["合約寫在紙上，利益寫在帳上，如今帳變了，紙也就不算數了。","別怪我，蘇丹要的東西在你那裡，我只是先一步替他取來。"],"truceEnd":["休戰期滿，帳本翻回原頁，你我又回到可談可打的關係。","合約到期了。要續約，價錢得重談；不續，我也不意外。"],"attacking":["我的船隊載著糧和兵出港了，這筆開銷我打算從你的城裡收回來。","大軍已經動身，我請的是蘇丹麾下最好的將領，錢花得值得。"],"attacked":["城牆是我親自出錢砌的，你竟然打得動……帳目上我失算了。","提比里亞的火光照到湖面了，我還有最後一筆錢能請援兵嗎？"],"defeated":["我從流亡起家，如今又歸於流亡。只盼同胞還有落腳處。","錢能買城牆，買不了時運。這一局，我輸得心服。"],"victory":["被驅逐的猶太人，靠帳本和城牆贏了列國，這故事值得記下。","提比里亞的桑樹該結果了，這片湖畔從此不必再擔心明天。"],"allyAccept":["結盟？好，我的商路對你開放，你的邊境替我擋風，公平。","我答應。姑母教過我，可靠的盟友比金庫更值錢。"],"allyReject":["結盟要押上我的信用，而你的信用我還沒查清楚，改日再談。","恕我婉拒。我只效忠一位蘇丹，不能再掛第二面旗。"],"greetFriendly":["你的信寫得得體，我喜歡懂禮數的人。來，嚐嚐加利利的無花果。","問候收到了。願你的倉庫常滿，我們的帳目常清。"],"greetCold":["信我讀了。客套話不值錢，有生意再來。","你的問候來得突然，我得先問問，你想從我這裡拿什麼？"],"threatDefy":["威脅我？半個歐洲的君王都欠我錢，你嚇不了一個放債的人。","你的狠話我記在帳上了，等哪天你來借錢，利息會特別高。"],"threatYield":["好吧，我看得出你手裡的兵比我多，這次算你贏，我退讓。","精明的人懂得何時低頭。我讓一步，但請你記得今天的分寸。"],"tributePay":["{gold} 枚金幣？好，付了，就當買一季平安，比打仗便宜。","這 {gold} 金幣我付得起，但會記進帳本，遲早連本帶利要回來。"],"tributeRefuse":["貢品？我是放債的，不是繳債的，這筆帳我不認。","我的金幣只獻給蘇丹和提比里亞的城牆，沒有你的份。"],"giftThanks":["禮物收到了，成色不錯。我會記得，納西家從不欠人情。","多謝厚禮。你這是投資，不是施捨，我懂，也會給你回報。"],"intel":["我的商人走遍各港口，聽說 {wars} 正在交戰，{peace} 已經談和。","情報是要收費的，這次免費：{wars} 在打仗，{peace} 握手言和了。"]}}},"Peru":{"1":{"name":"塔卡納莫（Tacaynamo）","title":"奇穆王國開國之王（傳說人物）","era":"約 900 年前後活躍（傳說人物，年代僅為推估）","tone":"沉穩莊重、言簡意賅，帶著海上來客的神秘與築城者的自豪；常以海風、潮水、木筏、土磚為喻，自稱「本王」。","portrait":"pe-china-age1","lines":{"intro":["本王塔卡納莫，自大海而來，在河谷築城為家。","海風把本王送到這片沙岸，如今這裡是奇穆的土地。"],"contact":["你的人看見昌昌了吧？那城牆全是本王的子民一磚磚砌成。","沙漠裡築起的土磚之城，不靠石頭，靠的是水渠與人心。"],"war":["本王的戰士已披上羽飾，河谷的和平到此為止。","潮水退去便是開戰之時，奇穆不再容忍你的挑釁。"],"warReply":["你竟向築城之王宣戰？土磚城牆會告訴你答案。","本王渡過大海都不曾懼怕，怎會怕你的軍旗。"],"peace":["刀兵傷了兩地的田渠，不如收兵，各自灌溉自己的玉米。","本王願放下長矛，以海菊蛤貝為信，與你議和。"],"accept":["好，本王允了。願月神見證這份約定。","兩國的漁筏從此能在同一片海上並行。"],"reject":["現在才談和？本王的城牆還沒讓你見識夠。","潮水不會為求饒的人停下，本王也不會。"],"rebuff":["你拒絕了本王的誠意，海風會記得這一天。","也罷，貝殼收回，長矛重新握緊。"],"betray":["約定如沙上的字，一陣海風便沒了，本王要進軍了。","為了奇穆的河谷，本王只好收回那句承諾。"],"truceEnd":["休戰的日子過去了，戰士們重新整好羽飾與長矛。","約定到期，接下來的路，由各自的實力決定。"],"attacking":["奇穆的大軍已沿著海岸出發，沙塵便是本王的旗號。","戰鼓從昌昌響起，你的城牆準備好了嗎？"],"attacked":["土磚崩落了……本王親手砌起的城，竟被你攻到這裡。","水渠斷了，城中無水，但本王仍守在王宮之前。"],"defeated":["本王從海上來，如今城已傾……願海風再帶本王歸去。","昌昌的土牆會留下，記得曾有一位自海而來的王。"],"victory":["河谷歸於平靜，奇穆的名字將傳遍整片海岸。","本王勝了。從沙漠到大海，皆是昌昌的土地。"],"allyAccept":["好，本王與你結為盟友，海菊蛤貝為證。","你的旗與奇穆的羽飾同列，本王樂見此事。"],"allyReject":["奇穆自海上立國，不需要倚靠他人的盟約。","本王還不了解你的心，結盟之事，再議。"],"greetFriendly":["遠方的君主，你的問候如海風般清爽，本王收下了。","歡迎來訪昌昌，本王備有玉米酒與新鮮的魚。"],"greetCold":["本王收到你的信了。城牆之外的事，本王沒興趣。","客套話就免了，說吧，你想要什麼。"],"threatDefy":["威嚇本王？大海的浪都沒能把本王打翻。","你的話像沙灘上的腳印，一波浪就沒了。"],"threatYield":["本王明白了……奇穆會退讓，請別踏進河谷。","城剛築成，子民尚少，本王暫且依你所言。"],"tributePay":["這 {gold} 金幣是昌昌工匠的心血，本王只好送給你。","拿去吧，{gold} 金幣。本王記住這筆帳了。"],"tributeRefuse":["奇穆的金銀是獻給月神的，不是給你的。","本王渡海而來不是為了向人納貢，回去吧。"],"giftThanks":["這份禮物本王收下了，昌昌的工匠會回贈你金飾。","遠方的心意，比海菊蛤貝更珍貴，本王謝過。"],"intel":["本王的漁民帶回消息：{wars} 正在交戰，{peace} 已經停戰。","海岸的風傳來的話：{wars} 兵戎相見，{peace} 握手言和。"]}},"0":{"name":"莫切首領（Moche）","title":"莫切河谷的祭司首領","era":"約 100–220 年活躍","tone":"沉穩威嚴、帶祭司的敬畏；常以太陽、大海、渠水、陶器作比喻，話少而重，自稱「我」。","portrait":"pe-china-age0","lines":{"intro":["我是莫切的首領，太陽照耀我的河谷，海洋餵養我的子民。","遠方的君主，你的腳踏上了太陽神廟守望的土地。"],"contact":["你的人看見土磚金字塔了吧？那是我向太陽獻上的階梯。","渠水流過沙漠，田裡長出玉米；這就是我的城，莫切。"],"war":["太陽已經目睹你的傲慢，我的戰士將帶著棍棒出發。","我在彩陶上畫下這一天：莫切與你，從此為敵。"],"warReply":["你要戰？沙漠與大海都站在我這邊，來吧。","安地斯山不會為你讓路，莫切的戰士也不會。"],"peace":["渠水乾了，田就荒了；我們停手，讓水繼續流吧。","我願送上彩陶與魚乾，換兩國的邊界重歸安寧。"],"accept":["好，太陽為證，莫切收起棍棒，與你共享河水。","我接受。讓工匠把這份和約燒進陶器裡，永不褪色。"],"reject":["現在才談和？渠水已經改道，話也收不回來了。","太陽尚未落下，我的戰士也還沒回家，不談。"],"rebuff":["你拒絕了？好，海潮退了還會再來，我等得起。","我的手伸出去，你卻推開；沙漠會記住這一天。"],"betray":["和約的陶片碎了，是我親手摔的；莫切要拿回河谷。","太陽換了方向，我也換了心意；停戰到此為止。"],"truceEnd":["休戰的日子像旱季一樣過去了，接下來由太陽決定。","約定的時間到了，我的戰士重新拿起棍棒與盾。"],"attacking":["蘆葦船已出海，戰士已上路，你的城牆準備好了嗎？","我的大軍踏過沙漠向你而去，像洪水沖過河谷。"],"attacked":["神廟的土磚在崩落……太陽啊，你為何轉開了臉？","渠水被截斷，田地在乾裂，我的子民正望著我。"],"defeated":["莫切的名字會留在陶器上，就算我的城已成沙。","太陽明天仍會升起，只是照不到莫切的神廟了。"],"victory":["太陽照亮了莫切的勝利，這一戰將燒進彩陶流傳。","河谷、沙漠與海岸都歸於我，讓渠水唱出勝利的歌。"],"allyAccept":["好，你的旗與我的太陽同行，蘆葦船會為你載來魚獲。","我答應結盟。渠水分你一半，敵人也分你一半。"],"allyReject":["莫切的渠水只流向自己的田，我不與你結盟。","太陽只認一位首領，我不需要遠方的盟友。"],"greetFriendly":["你的信讓我想起海上的好風，願太陽也照顧你的田。","遠方的朋友，來吧，我請你嘗海魚、看新燒的彩陶。"],"greetCold":["信收到了。渠水還要巡，我沒空多說。","太陽今日照得很淡，你的問候也一樣。"],"threatDefy":["拿話嚇我？海嘯我都見過，還怕你幾句話。","安地斯山比你高，大海比你深，你嚇不了莫切。"],"threatYield":["……我明白了。渠水要緊，我不與你爭。","你的軍隊太多，我的田不能荒，我退一步。"],"tributePay":["這 {gold} 金幣拿去，別碰我的渠與田。","太陽看著我交出 {gold} 金幣，也會看著你怎麼用它。"],"tributeRefuse":["金子是獻給太陽的，不是給你的，一枚也不給。","想要莫切的東西？自己划蘆葦船來拿。"],"giftThanks":["這份禮物我收下了，工匠會為你燒一只最好的彩陶。","多謝。太陽記得慷慨的人，莫切也是。"],"intel":["漁人回報：{wars} 在交戰，{peace} 已停手。","山風捎來：{wars} 交戰中，{peace} 已言和。"]}}},"Greece":{"1":{"name":"希拉克略（Heraclius）","title":"東羅馬（拜占庭）皇帝","era":"610–641 年在位","tone":"沉穩威嚴的老將皇帝，語氣帶著征戰多年的疲憊卻不失自信；篤信上帝，常提及十字架與波斯之戰；面對新興強敵時流露憂患之情。","portrait":"gr-china-age1","lines":{"intro":["朕乃羅馬人的皇帝希拉克略，君士坦丁堡的主人。","朕自波斯手中奪回真十字架，願上帝也看顧你的國土。"],"contact":["你的旅人看見的是君士坦丁堡，三重城牆從未被攻破。","金角灣的船隻與聖索菲亞的圓頂，都在朕的看顧之下。"],"war":["朕曾親率大軍深入波斯，今日這柄劍也將指向你。","羅馬的軍團已整隊出城，願上帝裁決你我的是非。"],"warReply":["波斯人與阿瓦爾人都曾兵臨此城，他們如今安在？","你既選擇刀劍，朕便以刀劍相迎，此城牆從不退讓。"],"peace":["朕與波斯征戰多年，深知戰事之苦，不如就此罷兵。","邊疆另有強敵，朕不願多樹一敵，願與你講和。"],"accept":["好，朕接受。願這份和約如真十字架般，堅固長久。","朕以皇帝之名應允，羅馬人不會先違背誓言。"],"reject":["庫思老曾要朕棄信投降，朕未曾低頭，今日亦然。","時機未到。朕的軍隊尚未疲憊，不必急著談和。"],"rebuff":["你拒絕了？也罷，朕已盡了君主應盡的善意。","朕伸出的手被推開，那便讓刀劍替朕說話吧。"],"betray":["朕不得不撕毀和約，帝國的存亡容不下猶豫。","願上帝寬恕朕，這場戰事非打不可，和約到此為止。"],"truceEnd":["休戰期滿。朕的軍團重新整裝，你我各憑本事。","約定的日子到了，往後是戰是和，看你的選擇。"],"attacking":["朕親自領軍出征，如同當年越過高加索直搗波斯。","高舉十字旗的大軍已經出發，你的城牆擋得住嗎？"],"attacked":["城牆在震動……聖母曾守護此城，朕祈求她再顯靈一次。","朕打敗過波斯，卻守不住這座城嗎？眾人隨朕上城！"],"defeated":["朕奪回過真十字架，卻救不回這個帝國……別了。","羅馬的帝業終有盡時，願上帝記得朕曾盡力。"],"victory":["感謝上帝！這場勝利屬於十字架，也屬於羅馬人。","朕將如當年在耶路撒冷那樣，親自扛著十字架進城。"],"allyAccept":["好，朕曾與可薩人結盟共擊波斯，今日願與你並肩。","羅馬人與你的盟約，朕以真十字架起誓，絕不食言。"],"allyReject":["盟約不是隨手可簽的東西，朕還看不出你的誠意。","朕的盟友已經夠多，帝國不需要再多一份負擔。"],"greetFriendly":["你的來信讓朕在憂患之中略感寬慰，願你平安。","朕問候你。願上帝賜你豐收，賜你邊境安寧。"],"greetCold":["朕收到了。帝國政務繁重，恕朕不多言。","問候就不必了，朕與你之間，尚無多少情誼可言。"],"threatDefy":["庫思老也曾這樣威脅朕，最後朕的軍隊到了他的宮門前。","威脅君士坦丁堡的人很多，城牆至今一磚未少。"],"threatYield":["帝國已在多面受敵，朕不願再添戰火……你贏了這一回。","好吧，朕暫且退讓。老皇帝也懂得該低頭時低頭。"],"tributePay":["國庫早因波斯戰事空虛，這{gold}金幣是朕擠出來的。","朕曾向教會借金銀打波斯，如今又要湊出{gold}金幣給你。"],"tributeRefuse":["羅馬人的皇帝不向他人納貢，朕連一枚金幣也不給。","金幣要留著養軍隊、修城牆，沒有多餘的給你。"],"giftThanks":["朕收下了，這份禮物在艱難的年頭裡格外珍貴。","多謝。朕會把它獻在聖索菲亞，作為你我友誼的見證。"],"intel":["朕的探子回報：正在交戰的有{wars}，已締和的有{peace}。","據朕所知，{wars}仍在刀兵相向，{peace}則已歸於和平。"]}},"0":{"name":"菲利普五世（Philip V）","title":"馬其頓國王（安提柯王朝）","era":"前 221–前 179 年在位","tone":"機敏銳利、帶點譏諷的年輕王者口吻；驕傲自信，對羅馬既戒備又不服輸，敗戰後多了幾分隱忍與算計；自稱本王。","portrait":"gr-china-age0","lines":{"intro":["本王是馬其頓之主菲利普，亞歷山大的王座如今由本王坐鎮。","希臘諸邦喚本王為希臘的寵兒，你也不妨記住這名號。"],"contact":["這裡是佩拉，馬其頓的王城，你的使者看清楚了嗎？","城牆上的十六芒星是馬其頓的徽記，記好了。"],"war":["本王的薩里沙長矛已經放平，馬其頓方陣要向你推進了。","談判到此為止，接下來由方陣替本王說話。"],"warReply":["向馬其頓宣戰？連羅馬人都得掂量再三，你倒是勇敢。","本王十七歲便領兵征戰埃托利亞，不怕再多一個對手。"],"peace":["西方的烏雲正在聚集，本王無意再與你消耗，停戰吧。","本王在納夫帕克托斯簽過和約，再簽一份也無妨。"],"accept":["好，本王答應。方陣後撤，兵士們可以回家收割了。","就這麼定了，本王以安提柯王室之名起誓。"],"reject":["現在才談停戰？本王的方陣還沒推到你城下呢。","本王不簽對馬其頓沒好處的和約，回去吧。"],"rebuff":["不肯？也罷，本王給過機會，接下來別怪馬其頓。","本王的好意不常有，你居然當面推開，真是可惜。"],"betray":["和約是墨水寫的，本王的利益是鐵打的，撕了吧。","時機到了，本王不會為一紙和約錯過眼前的戰機。"],"truceEnd":["休戰的日子到頭了，本王的兵士也歇夠了。","和約期滿，馬其頓的礦坑和田地都養足了兵，走著瞧。"],"attacking":["方陣已經出了佩拉，長矛如林，目標是你的城。","本王親自領軍，夥伴騎兵在前，你準備好迎接了嗎？"],"attacked":["佩拉的城牆在搖晃……但本王所有的日子，太陽還沒落盡。","庫諾斯克法萊那天本王也沒倒下，今天更不會。"],"defeated":["馬其頓的太陽落下了。羅馬沒能滅本王，你卻做到了。","亞歷山大的王座，就這樣傳到本王為止了嗎……"],"victory":["勝利屬於馬其頓！讓希臘再次喊本王的名字。","方陣一旦推起來，沒有誰擋得住，這下你明白了。"],"allyAccept":["好，本王與漢尼拔都能結盟，與你自然也行。","盟約成立，馬其頓的長矛從今起也為你而舉。"],"allyReject":["本王結盟看的是實力，你的實力還不夠讓本王點頭。","馬其頓不需要多一個拖累的盟友，此事免談。"],"greetFriendly":["你的信本王讀了，寫得有禮，本王也回你一份誠意。","佩拉的宮門為你的使者敞開，本王設宴款待。"],"greetCold":["信收到了。本王正忙著盯緊羅馬，沒空多寒暄。","問候本王收下了，至於交情，還得看你日後的作為。"],"threatDefy":["本王連羅馬使者的傲慢都能一笑置之，你的威嚇算什麼？","想用一封信嚇退方陣？拿長矛來試試，比信管用。"],"threatYield":["……本王明白了。庫諾斯克法萊之後，本王學會了忍耐。","好吧，本王暫且退讓，馬其頓需要時間養兵。"],"tributePay":["{gold} 金幣拿去，這筆帳本王記在心裡了。","馬其頓的礦坑還撐得住，{gold} 金幣付你，別得意太早。"],"tributeRefuse":["向馬其頓要貢品？本王的金幣只養方陣，不養別人。","一個銅板也沒有，想要就派兵來佩拉自己拿。"],"giftThanks":["這份禮本王收下了，希臘人講究禮尚往來，本王也是。","好東西，本王會擺在佩拉的宮裡，記住是你送的。"],"intel":["探子回報：正與本王交戰的是 {wars}，和平相處的是 {peace}。","本王的敵人是 {wars}，朋友是 {peace}，這情報你收好。"]}}},"Bolivia":{"1":{"name":"艾馬拉諸邦首領（Aymara）","title":"的的喀喀湖畔艾馬拉諸邦首領（通稱，不指定真人）","era":"約 1000–1279 年活躍（蒂瓦納科衰落後、艾馬拉諸邦興起期）","tone":"沉穩樸實、話少而有分量，常以太陽、湖水、駱馬、農作物為比喻；敬畏太陽與湖神，不誇口、不諂媚，像一位守著牧場與田地的長者。","portrait":"bo-china-age1","lines":{"intro":["我來自的的喀喀湖畔，太陽門下的高原之民。","高原寒風吹不倒駱馬，也吹不倒我的部族。"],"contact":["你的人看見湖上的蘆葦舟了嗎？那是我的邊界。","石砌的太陽門迎著晨光，遠客請放下兵器。"],"war":["湖神見證，高原的投石手已列隊，我向你宣戰。","你越了界，海螺號角已響，高原的戰士出發。"],"warReply":["你選擇與高原為敵？寒風與稀薄的空氣會替我作戰。","好，那就讓太陽門看看，誰的腳站得更穩。"],"peace":["駱馬不與同槽的駱馬相鬥，我們也停手吧。","播種的季節到了，放下兵器，各自回田裡去吧。"],"accept":["好，我以藜麥與馬鈴薯起誓，湖畔從此安寧。","我答應你。今夜湖邊點起篝火，以酒敬太陽。"],"reject":["石頭一旦砌上太陽門，就不會再拆下。我不停戰。","你的話像湖上的霧，太陽一出就散了。我不信。"],"rebuff":["你拒絕了？高原的人記性很長，像山上的石頭。","也罷。蘆葦舟會回到湖心，我的手也回到投石索上。"],"betray":["湖水退了，界線也變了，我不再守那道停戰誓言。","為了部族的牧場，我收回誓言，海螺號角再次吹響。"],"truceEnd":["約定的休戰到了盡頭，湖畔的風又開始轉向。","休戰的日子數完了，接下來，看各自的本事。"],"attacking":["駱馬隊馱著糧，戰士背著投石索，我們朝你去了。","高原的戰士下山了，腳步像雪山落下的冰雹。"],"attacked":["太陽門的石塊在震動……湖神啊，請再撐住我的城。","田裡的藜麥還沒收，我的城牆卻先倒了一半。"],"defeated":["石城會荒，但湖水常在，總有人再撐起蘆葦舟。","我把部族交還給太陽與大地，你贏了，去吧。"],"victory":["太陽門迎來了勝利的晨光，高原之民萬世長存。","駱馬歸圈，戰士歸田，這片高原終究是我們的。"],"allyAccept":["好，我們像駱馬與羊駝，同走一條山路。","盟約成立，我的駝隊會帶著馬鈴薯來訪你的城。"],"allyReject":["高原的路太陡，你的腳還跟不上，盟約免談。","我的蘆葦舟只載自己人，恕我不與你結盟。"],"greetFriendly":["遠方的君主，願太陽照暖你的田，湖水滋養你的民。","收到你的問候了，來高原時，我請你喝藜麥湯。"],"greetCold":["問候收到了。高原的風很冷，話就不必多說。","你的使者來過了。駱馬照樣吃草，日子照樣過。"],"threatDefy":["你來嚇高原的人？稀薄的空氣先嚇跑的會是你。","太陽門立了幾百年，不怕風，也不怕你的狠話。"],"threatYield":["我的部族人少，經不起大戰，我退一步。","好吧，為了牧場上的孩子，這次我讓步。"],"tributePay":["這{gold}金是駝隊換來的，拿去吧，別再來了。","我交出{gold}金，換湖畔一季的平安。"],"tributeRefuse":["高原的金子只獻給太陽，不獻給貪心的人。","我的駱馬馱糧食，不馱貢品。你請回。"],"giftThanks":["謝謝你的禮物，我會回贈一袋高原的凍乾馬鈴薯。","禮物收下了，湖神會記得你的心意，我也會。"],"intel":["與我交戰的有{wars}，與我和好的有{peace}。","駝隊帶回消息：敵是{wars}，友是{peace}。"]}},"2":{"name":"圖帕克・印卡・尤潘基（Túpac Inca Yupanqui）","title":"印加帝國第十代薩帕・印卡（至高印卡），科拉蘇約的征服者","era":"約 1471–1493 年在位；繼位前已替父親帕查庫特克統兵，征服的的喀喀湖周邊的科拉蘇約（今玻利維亞高原）","tone":"征服者的沉穩威嚴，句子短而有力；常以太陽、道路、高原、的的喀喀湖、結繩、驛使為喻；自稱「朕」，稱對方為「遠方的君主」或直接稱「你」；對願意歸順者寬厚，對挑釁者冷硬，帶著帝國秩序的驕傲。","portrait":"bo-historical-age1","lines":{"intro":["朕是太陽之子圖帕克・印卡，四方之地的主人。","從庫斯科到的的喀喀湖，道路所及皆是朕的疆土。"],"contact":["你的人走到了科拉蘇約，看見石牆便該知道是誰的地方。","高原上的每一座糧倉與驛站，都是印加的秩序。"],"war":["科拉諸邦曾與朕為敵，如今已歸入四方之地；輪到你了。","太陽照到哪裡，印加的道路就修到哪裡。備戰吧。"],"warReply":["向太陽之子宣戰？高原的風會把你的話吹回去。","很好，朕的驛使已跑遍四方，大軍明日集結。"],"peace":["戰事拖久，田地荒蕪，不如各自回去照看收成。","朕願送上細織的錦衣與駱馬，換一段太平。"],"accept":["好，朕接受。讓兩國的道路從此相通。","太陽為證，印加說出口的話，不會收回。"],"reject":["現在才談停戰？太陽已經走過山頂，太遲了。","科拉蘇約沒有半途而廢的征服，朕不接受。"],"rebuff":["你拒絕了？無妨，高原的人習慣等待雨季。","朕伸出的手你不接，往後便別怪印加的石牆冷硬。"],"betray":["停戰只是讓朕的軍隊喘口氣，如今他們歇夠了。","太陽之子不受凡人的約束，今日起盟約作廢。"],"truceEnd":["約定的日子到了，朕的士兵已重新拿起投石索。","休戰結束。是要繼續太平，還是另有打算，由你決定。"],"attacking":["駱馬隊已備好乾糧，印加大軍正沿著王道向你而來。","聽見海螺號角了嗎？那是朕的軍隊在向你打招呼。"],"attacked":["石牆再厚也有裂縫……但印加人不會就這樣低頭。","糧倉燒了可以再建，朕還站在這裡，你就未曾贏。"],"defeated":["太陽落下了……但明日它仍會從的的喀喀湖升起。","朕的道路會留下，走在上面的人終將記得印加。"],"victory":["四方之地又添了一角，朕會把你的名字記進結繩。","勝利歸於太陽。你的子民從今起也在朕的照看之下。"],"allyAccept":["朕答應了。從今以後，你的敵人便是印加的敵人。","結盟之禮朕已備好，海螺與錦衣，隨驛使送到。"],"allyReject":["印加不需要盟友，只需要願意修路的臣民。","你我腳下的路還不相通，談結盟言之過早。"],"greetFriendly":["遠方的君主，願太陽也照暖你的土地。","你的問候朕收到了，就像高原上及時的雨。"],"greetCold":["話已聽到。朕還有四方之地要治理，退下吧。","問候不必多說，印加人看的是行動，不是言語。"],"threatDefy":["威嚇朕？連的的喀喀湖的風浪都嚇不倒印加。","這種話朕在科拉蘇約聽多了，結果你也知道。"],"threatYield":["……朕明白了。高原的冬天很長，暫且不與你相爭。","太陽也有被雲遮住的時候，這回朕退一步。"],"tributePay":["{gold} 金幣拿去，這是高原礦坑一季的收穫。","朕先給你 {gold} 金幣，太陽會記住這筆帳。"],"tributeRefuse":["向太陽之子索取貢品？該進貢的是你，不是朕。","印加的金子只供奉太陽神殿，一枚也不會給你。"],"giftThanks":["禮物收下了。朕會回贈駱馬毛織的斗篷，以表心意。","遠方送來的禮，朕會擺在太陽神殿前，讓神也看見。"],"intel":["驛使帶回四方的消息：交戰中的有 {wars}，太平的有 {peace}。","結繩上記得清楚：{wars} 仍在打仗，{peace} 已握手言和。"]}}},"Brazil":{"2":{"name":"昆哈貝貝（Cunhambebe）","title":"圖皮南巴族長、塔莫約聯盟領袖","era":"約 1540–1555 年活躍","tone":"威嚴、沉穩、簡潔有力，像森林中的長者對外來者說話；常以森林、海灣、大樹、祖靈作比喻，不卑不亢。","portrait":"br-china-age2","lines":{"intro":["我是昆哈貝貝，塔莫約聯盟的族長。這片海岸認得我的名字。","遠方來的君主，森林與海灣是我的家，你想帶來什麼？"],"contact":["你的人看見了我們的長屋。記住，這片土地只有守護者。","海灣邊的沙灘上，我的獨木舟比你數過的星星還多。"],"war":["你的腳踩進了我們的森林，塔莫約的弓箭已經拉滿。","我不會等敵人蓋好堡壘再動手，戰鼓今夜就響起。"],"warReply":["葡萄牙人也曾這樣對我說話，他們至今沒能踏進我的村落。","很好，森林裡的每一棵樹都會成為你的敵人。"],"peace":["放下弓箭吧，河水流過石頭，也不必永遠相撞。","我提議停戰，讓兩邊的人回去種木薯，而不是埋葬親人。"],"accept":["好，我接受。塔莫約人說出的話，比大樹的根更牢固。","就這麼定了，我的長屋為你的使者留一張吊床。"],"reject":["你的話像退潮的海水，說來就來，說走就走，我不信。","停戰？先把你的人從我們的海岸撤走，再來談。"],"rebuff":["你拒絕了，那就讓森林替我們決定誰是對的。","我伸出的手被推開，下次伸出的就是戰棍。"],"betray":["停戰只是讓戰士休息一季，現在他們養足了力氣。","你趁停戰在我們的海岸砍樹，這份約定我不再守。"],"truceEnd":["約定的日子過去了，森林重新睜開眼睛。","休戰到此為止，我的戰士已經重新塗上黑紅的顏色。"],"attacking":["獨木舟已經推下沙灘，塔莫約的戰士正朝你划去。","聽見海上的戰歌了嗎？那是我的聯盟一起出發的聲音。"],"attacked":["長屋著火了，可是塔莫約人還站著，我也還站著。","就算村落倒下，森林還在，我的族人會在樹影裡等你。"],"defeated":["我倒下了，但這片海岸會記得，曾有人為它挺身而出。","把我的羽冠留在沙灘上，讓海風告訴後人我的名字。"],"victory":["森林勝了。回去告訴你的人，這片海岸不屬於外來的旗幟。","塔莫約聯盟贏了這一仗，今晚長屋裡會有歌聲與舞蹈。"],"allyAccept":["法國人與我並肩，你也可以。你的敵人，就是我的敵人。","好，塔莫約聯盟多一位朋友。我們一起守住這片海岸。"],"allyReject":["我只和信得過的人並肩，你還沒有讓森林認識你。","結盟？塔莫約人的弓不借給陌生人使用。"],"greetFriendly":["你的問候像清晨的海風，我收下了，願你的村落豐收。","遠方的朋友，來我的長屋坐坐，吊床和烤魚都為你備好。"],"greetCold":["話我聽到了。外來的人說的好話太多，我只看你做的事。","問候不必多說，森林裡的鳥叫得再好聽，也不代表沒有陷阱。"],"threatDefy":["威脅我？葡萄牙人的火槍都沒讓我低頭，你的話更不會。","你的恐嚇像雨季的雷聲，響得很大，卻打不倒一棵樹。"],"threatYield":["我的戰士還沒從上一場仗恢復，這次，我讓你一步。","好吧，森林懂得在暴風裡低頭，但樹根不會斷。"],"tributePay":["拿去，{gold} 金幣。這是為了讓族人安穩收成，不是臣服。","這 {gold} 金幣你拿走，但別以為海岸的森林也跟著換了主人。"],"tributeRefuse":["貢品？塔莫約人只向祖靈獻上收成，不向外來的君主。","我們用巴西紅木換法國人的斧頭，但不會白白送給你。"],"giftThanks":["你的禮物我收下了，森林會記得每一份善意。","好東西。我回贈你金剛鸚鵡的羽毛，那是我們最珍貴的顏色。"],"intel":["海風帶來消息：我正與 {wars} 交戰，與 {peace} 相安無事。","聽好，{wars} 是我的敵人，{peace} 與我沒有仇怨，其餘的我不多說。"]}}},"Ethiopia":{"0":{"name":"佐斯卡萊斯（Zoskales）","title":"阿克蘇姆國王","era":"約西元 50 年前後在位（1 世紀中葉）","tone":"精明務實的商人國王，開口愛談帳目、價錢與划不划算，有點吝嗇卻不失正直；偶爾引希臘史書顯露學識；語氣沉穩，少感嘆多盤算。","portrait":"et-china-age0","lines":{"intro":["本王佐斯卡萊斯，阿杜利斯港的象牙與紅海風向，皆歸本王調度。","遠方的君主，希臘商賈的書信本王讀得懂，你的心思也一樣。"],"contact":["你的人到了阿杜利斯？看清楚，碼頭上的象牙全是本王的。","從港口往高原走八日方能見阿克蘇姆，你的人腳程倒是不慢。"],"war":["你截了本王的商隊，這筆帳本王算得很清楚，以刀兵來討。","紅海的航道只容一位主人，本王已令阿杜利斯的戰船出港。"],"warReply":["向本王宣戰？高原上的長矛手，比你想像的多得多。","好，本王記下了。戰費，本王會向你的城池加倍討回。"],"peace":["打仗耗錢，做生意才賺錢。本王提議停戰，重開商路。","象牙賣不出去，戰船也白養。停戰吧，本王算過這樣划算。"],"accept":["好，本王接受。你的商船進阿杜利斯港，稅金減半。","本王以紅海的風向起誓，此約不改，除非你先毀約。"],"reject":["現在談停戰？你的出價太低，本王不做虧本的買賣。","本王讀過希臘人的史書，知道弱者求和是什麼下場。免談。"],"rebuff":["不肯？也罷。本王的貨物運去羅馬與印度，不缺你這一家。","你拒絕本王？很好，這筆帳本王先記著，日後連本帶利。"],"betray":["盟約是墨水寫的，象牙是真金換的。本王選象牙，停戰作廢。","你的商隊擋了本王的財路，那份停戰約，本王不認了。"],"truceEnd":["休戰期滿，本王的帳也結清了。下一頁，該記什麼由你決定。","季風轉向，休戰也到頭了。本王的戰船與商船，都已備妥。"],"attacking":["高原的長矛手已經下山，本王親自押陣，去收你欠的債。","本王的大軍出發了，帶著象牙換來的鐵器，去敲你的城門。"],"attacked":["阿克蘇姆的宮門將破……本王算盡天下，竟沒算到這一步。","象牙倉庫燒了，港口也丟了。本王的家底，都在你的火裡。"],"defeated":["本王一生精打細算，末了卻輸得一乾二淨。紅海，交給你了。","記住，本王只是走了。阿杜利斯的季風，會等下一位主人。"],"victory":["帳目結清，本王贏了。往後紅海的每一艘船，都得向本王納稅。","希臘人的書上會寫：佐斯卡萊斯，紅海之主。本王滿意了。"],"allyAccept":["結盟？好。你出兵，本王出船與象牙，利潤三七分帳。","本王答應結盟。從此你的旗號進阿杜利斯，港口為你敞開。"],"allyReject":["結盟就是把家底押在別人身上，本王不下這種賭注。","你的盟約值幾根象牙？本王掂過了，不夠。"],"greetFriendly":["來信收到了。本王正好有一批上等象牙，你有興趣嗎？","遠方的朋友，願季風順著你的船帆。本王的港口歡迎你。"],"greetCold":["信本王看了。若無買賣要談，就別耽誤本王算帳的時間。","客套話不值錢，本王的書記官連墨水都省下了。"],"threatDefy":["威嚇本王？羅馬的商人都得客客氣氣，你算哪一國？","本王讀過的史書裡，放狠話的人多半沒有好下場。"],"threatYield":["罷了，本王不與你硬拚。生意人懂得，該低頭時就低頭。","你的刀比本王的帳本硬，本王退一步，港口照常開市。"],"tributePay":["{gold}金幣，本王每一枚都數過三遍。拿去，別再來。","這{gold}金幣是從象牙生意裡省出來的，本王心疼得很。"],"tributeRefuse":["要本王納貢？本王連希臘商人的關稅都不肯少收一枚。","一根象牙也不給。本王的財庫，只進不出。"],"giftThanks":["禮物收下了，本王已估過價，比預期的值錢。多謝。","你送來的東西，本王會擺在阿克蘇姆的王座旁。有心了。"],"intel":["商人捎來消息：{wars}正交戰，{peace}已講和。","港口的消息：{wars}在打仗，{peace}在做買賣。"]}}}}}};
